@app.route('/api/customization/logo', methods=['POST'])
@login_required
def customization_logo_post():
    """Accept a PNG/SVG/JPEG logo upload (≤512 KB), store base64 in settings."""
    import base64
    f = request.files.get('logo')
    if not f:
        return jsonify({'error': 'No file uploaded'}), 400
    allowed = {'image/png', 'image/svg+xml', 'image/jpeg', 'image/jpg'}
    mime = f.mimetype or ''
    if mime not in allowed:
        return jsonify({'error': f'Unsupported type: {mime}. Use PNG, SVG, or JPEG.'}), 400
    data = f.read(512 * 1024 + 1)
    if len(data) > 512 * 1024:
        return jsonify({'error': 'File too large (max 512 KB)'}), 400
    b64 = 'data:' + mime + ';base64,' + base64.b64encode(data).decode()
    s = load_settings()
    s.setdefault('customization', {})['agency_logo_b64'] = b64
    save_settings(s)
    return jsonify({'ok': True, 'data_uri': b64})

@app.route('/api/customization/logo', methods=['DELETE'])
@login_required
def customization_logo_delete():
    """Remove agency logo, reverting banner logos to infra-TAK text mark."""
    s = load_settings()
    s.setdefault('customization', {}).pop('agency_logo_b64', None)
    save_settings(s)
    return jsonify({'ok': True})

@app.route('/help')
@login_required
def help_page():
    """Help: backdoor URL, console password info, reset password, hardening."""
    settings = load_settings()
    current_ssh_port = _get_current_ssh_port()
    _relay = settings.get('email_relay') or {}
    return render_template('help.html', settings=settings, version=VERSION, current_ssh_port=current_ssh_port,
                           diag_support_email=DIAG_SUPPORT_EMAIL,
                           diag_email_ready=bool(_relay.get('relay_host') and _relay.get('smtp_user')))


# ── v10.2.1 (W3): Help → Diagnostics ──────────────────────────────────────────
# PLAN-v10.2.1 §4. One read-only report support can read, built by the console so a
# customer never needs SSH and a pasted script (operator, 2026-09-30: "that is too much
# for him"). READS ONLY: nothing below installs, restarts, clears or repairs — not even
# ldapsearch, which is used only when it is already present. Every section is wrapped
# so one failure prints "(section failed: …)" and the rest still run, and the whole
# report passes through _diag_redact() before anyone can see it.
DIAG_SUPPORT_EMAIL = ''          # pre-fills the Help card's address field; '' = blank
_DIAG_JOB = {'running': False, 'report': None, 'generated_at': None, 'error': None}
_DIAG_LOCK = threading.Lock()
_DIAG_TAIL_BYTES = 2 * 1024 * 1024
_DIAG_SECRET_KEY_RE = re.compile(r'(pass|secret|token|key)', re.I)
_DIAG_TAK_LOG_TS = re.compile(r'^(\d{4}-\d{2}-\d{2}-\d{2}:\d{2})')


def _diag_cmd(argv, timeout=20, priv=True, stdin=None):
    """Output of a read-only command, or a '(… failed: …)' line. Never raises.
    `priv=False` for tools that work as any user (and are not on the broker allow-list)."""
    try:
        r = subprocess.run(_sudo_wrap(argv) if priv else argv, input=stdin,
                           capture_output=True, text=True, timeout=timeout)
        return ((r.stdout or '') + (r.stderr or '')).rstrip()
    except Exception as e:
        return f'({argv[0]} failed: {str(e)[:120]})'


def _diag_tail(path, max_bytes=_DIAG_TAIL_BYTES):
    """Last `max_bytes` of a log as lines, read directly; None when this console cannot read it.
    ⚠ Never routed through the broker: a whole TAK log can exceed its 32 MiB message cap,
    and `tail` is not on its allow-list."""
    try:
        with open(path, 'rb') as f:
            f.seek(0, 2)
            size = f.tell()
            f.seek(max(0, size - max_bytes))
            lines = f.read().decode('utf-8', 'replace').splitlines()
    except OSError:
        return None
    return lines[1:] if size > max_bytes else lines


def _diag_unreadable(path):
    """Why _diag_tail() returned None: the file is missing, or this console may not read it."""
    try:
        os.stat(path)
    except FileNotFoundError:
        return 'missing'
    except OSError:
        pass
    return 'not readable by the console on this box'


def _diag_top(n=10):
    """CPU summary + busiest processes over a 1 s sample (top's 2nd iteration — its 1st is
    since-boot averages). Program names only: full command lines can carry secrets."""
    raw = _diag_cmd(['top', '-b', '-n', '2', '-d', '1', '-o', '%CPU', '-w', '200'], priv=False)
    lines = raw.splitlines()
    starts = [i for i, l in enumerate(lines) if l.startswith('top - ')]
    if len(starts) < 2:
        return ['top: ' + (raw[:200] or 'no output')]
    it = lines[starts[-1]:]
    out = [l.strip() for l in it if l.startswith('%Cpu')][:1]
    hdr = next((i for i, l in enumerate(it) if l.split()[:2] == ['PID', 'USER']), None)
    if hdr is None:
        return out
    out.append('busiest processes (1 s sample): %CPU %MEM user command')
    for l in it[hdr + 1:hdr + 1 + n]:
        f = l.split()
        if len(f) >= 12:
            out.append(f"  {f[8]:>6} {f[9]:>5} {f[1][:12]:<12} {' '.join(f[11:])[:40]}")
    return out


def _diag_tak_log_window(lines, hours=3):
    """TAK log lines from the last `hours`, keeping stack-trace continuation lines with the
    entry they belong to (they carry no timestamp of their own)."""
    cutoff = (datetime.now() - timedelta(hours=hours)).strftime('%Y-%m-%d-%H:%M')
    out, keep = [], False
    for ln in lines:
        m = _DIAG_TAK_LOG_TS.match(ln)
        if m:
            keep = m.group(1) >= cutoff
        if keep:
            out.append(ln)
    return out


def _diag_cert_enddate(pem):
    """'notAfter=…' for a PEM certificate, via openssl (stdin, no shell)."""
    if not pem or 'BEGIN CERTIFICATE' not in pem:
        return '(no certificate)'
    return _diag_cmd(['openssl', 'x509', '-noout', '-enddate', '-subject'], priv=False, stdin=pem).replace('\n', '  ')


def _diag_ak(settings, path):
    """GET an Authentik API path → parsed JSON. Raises on failure (the section wrapper reports it)."""
    import urllib.request as _ur
    token = _get_authentik_env_value(settings, 'AUTHENTIK_BOOTSTRAP_TOKEN') or \
        _get_authentik_env_value(settings, 'AUTHENTIK_TOKEN')
    if not token:
        raise RuntimeError('no Authentik API token in the Authentik .env')
    req = _ur.Request(f'{_get_authentik_api_url(settings)}/api/v3/{path}',
                      headers={'Authorization': f'Bearer {token}'})
    return json.loads(_ur.urlopen(req, timeout=10).read().decode())


def _diag_ldap_bind(dn, password):
    """Result + memberOf lines of an LDAP bind+search as `dn`. Password never printed."""
    if not password:
        return '  (no password on record — skipped)'
    if not shutil.which('ldapsearch'):
        return '  (ldapsearch not installed — skipped; diagnostics never installs anything)'
    cn = dn.split(',', 1)[0].split('=', 1)[-1]
    out = _diag_cmd(['ldapsearch', '-x', '-H', 'ldap://127.0.0.1:389', '-D', dn, '-w', password,
                     '-b', 'ou=users,dc=takldap', f'(cn={cn})', 'memberOf'], timeout=20, priv=False)
    keep = [l for l in out.splitlines() if l.startswith(('result:', 'memberOf:', 'ldap_bind', 'ldap_sasl'))
            or "Can't contact" in l]
    return '\n'.join('  ' + l for l in keep) or '  (no output)'


def _diag_secret_values(settings):
    """Every secret value this box knows, for exact-string redaction."""
    vals = set()

    def walk(obj, key=''):
        if isinstance(obj, dict):
            for k, v in obj.items():
                walk(v, str(k))
        elif isinstance(obj, list):
            for v in obj:
                walk(v, key)
        elif isinstance(obj, str) and _DIAG_SECRET_KEY_RE.search(key):
            vals.add(obj)
    walk(settings)
    try:
        for ln in (_get_authentik_env_content(settings) or '').splitlines():
            k, _, v = ln.partition('=')
            if v and _DIAG_SECRET_KEY_RE.search(k):
                vals.add(v.strip().strip('"').strip("'"))
    except Exception:
        pass
    try:
        with open(os.path.join(CONFIG_DIR, 'auth.json')) as f:
            vals.add(json.load(f).get('password_hash') or '')
    except Exception:
        pass
    # Below 6 characters a "secret" is a port, a boolean or a placeholder; scrubbing those
    # would shred the report without protecting anything.
    return sorted((v for v in vals if v and len(v) >= 6), key=len, reverse=True)


def _diag_redact(text, settings):
    """Remove every known secret value, then anything that still looks like one."""
    for v in _diag_secret_values(settings):
        text = text.replace(v, '[REDACTED]')
    text = re.sub(r'(?i)\b(password|passwd|secret|token|api[_-]?key)(["\']?\s*[=:]\s*["\']?)([^\s"\',;&]{4,})',
                  r'\1\2[REDACTED]', text)
    text = re.sub(r'(?i)\bBearer\s+[A-Za-z0-9._~+/=-]{8,}', 'Bearer [REDACTED]', text)
    return text


def _diag_section_box(settings):
    out = []
    git = lambda *a: _diag_cmd(['git', '-C', BASE_DIR] + list(a), priv=False)
    out.append(f"console: v{VERSION}  git={git('rev-parse', '--short', 'HEAD')}  "
               f"branch={git('branch', '--show-current')}  update_channel={settings.get('update_channel') or 'main'}")
    out.append(f"fqdn={settings.get('fqdn') or '-'}  server_ip={settings.get('server_ip') or '-'}  "
               f"ssl_mode={settings.get('ssl_mode') or '-'}  os_type={settings.get('os_type') or '-'}")
    import getpass
    out.append(f"console runs as: {getpass.getuser()}  broker routing: {_broker_should_route()}")
    try:
        with open('/etc/os-release') as f:
            osr = dict(l.strip().split('=', 1) for l in f if '=' in l)
        osname = osr.get('PRETTY_NAME', '').strip('"')
    except Exception:
        osname = '?'
    out.append(f"os: {osname}  kernel: {os.uname().release}  arch: {os.uname().machine}  cpus: {os.cpu_count()}")
    vm, sw = psutil.virtual_memory(), psutil.swap_memory()
    out.append(f"ram: {vm.total // 2**30} GiB total, {vm.available // 2**30} GiB available ({vm.percent}% used)  "
               f"swap: {sw.total // 2**30} GiB ({sw.percent}% used)")
    out.append(f"uptime since: {datetime.fromtimestamp(psutil.boot_time()).strftime('%Y-%m-%d %H:%M')}  "
               f"load: {' '.join(f'{x:.2f}' for x in os.getloadavg())}")
    out.extend(_diag_top())
    for mp in ('/', '/opt', '/var/lib/docker', os.path.expanduser('~')):
        try:
            du = psutil.disk_usage(mp)
            out.append(f"disk {mp}: {du.free // 2**30} GiB free of {du.total // 2**30} GiB ({du.percent}% used)")
        except Exception:
            pass
    td = _diag_cmd(['timedatectl', 'show', '-p', 'NTPSynchronized', '-p', 'Timezone'], priv=False)
    out.append(f"clock: {datetime.utcnow().strftime('%Y-%m-%d %H:%M:%S')} UTC  {td.replace(chr(10), '  ')}")
    kern = _diag_cmd(['journalctl', '-k', '--since', '24 hours ago', '--no-pager', '-q'], timeout=30)
    oom = [l for l in kern.splitlines() if re.search(r'out of memory|oom-kill|killed process', l, re.I)]
    out.append(f"kernel, last 24 h: {len(oom)} OOM-kill line(s)")
    out.extend('  ' + l[:220] for l in oom[-5:])
    sysj = _diag_cmd(['journalctl', '--since', '24 hours ago', '--no-pager', '-q', '-p', 'err'], timeout=30)
    full = [l for l in sysj.splitlines() if 'No space left' in l]
    out.append(f"'No space left on device' in the system journal, last 24 h: {len(full)}")
    return out


def _diag_section_console(settings):
    out = [f"failed units: {_diag_cmd(['systemctl', '--failed', '--no-legend', '--plain'], priv=False) or 'none'}"]
    j = _diag_cmd(['journalctl', '-u', 'takwerx-console', '--since', '2 hours ago', '--no-pager', '-q', '-n', '5000'], timeout=30)
    bad = [l for l in j.splitlines() if re.search(r'Traceback|\bERROR\b|CRITICAL|failed:', l)]
    out.append(f"console journal, last 2 h: {sum('Traceback' in l for l in bad)} traceback(s), {len(bad)} error-class line(s)")
    out.extend('  ' + l[:240] for l in bad[-15:])
    audit = _diag_tail('/var/log/takwerx-broker/audit.log', 512 * 1024)
    if audit is not None:
        recent = audit[-2000:]
        out.append(f"broker audit (recent): {sum('DENIED' in l for l in recent)} DENIED, "
                   f"{sum('WOULD-DENY' in l for l in recent)} WOULD-DENY")
        out.extend('  ' + l[:220] for l in [l for l in recent if 'DENIED' in l or 'WOULD-DENY' in l][-5:])
    return out


def _diag_section_connectivity(settings):
    out = []
    fqdn = (settings.get('fqdn') or '').split(':')[0].strip()
    sip = str(settings.get('server_ip') or '').strip()
    if fqdn:
        for host in (fqdn, f'tak.{fqdn}', f'infratak.{fqdn}', f'takportal.{fqdn}', f'authentik.{fqdn}'):
            try:
                ips = sorted({a[4][0] for a in socket.getaddrinfo(host, None, socket.AF_INET)})
                out.append(f"dns {host}: {', '.join(ips)}{'' if (not sip or sip in ips) else '   <-- not server_ip ' + sip}")
            except Exception as e:
                out.append(f"dns {host}: does not resolve ({str(e)[:60]})"
                           f"{'   (apex record — optional)' if host == fqdn else ''}")
    ports = _diag_cmd(['ss', '-tlnH'], priv=False)
    listening = sorted({l.split()[3] for l in ports.splitlines() if len(l.split()) > 3},
                       key=lambda a: int(a.rsplit(':', 1)[-1]) if a.rsplit(':', 1)[-1].isdigit() else 0)
    out.append(f"listening tcp: {' '.join(listening)}")
    fw = _firewall_status_local()      # the Firewall page's own reader — both backends
    out.append(f"firewall backend: {_fw_backend()}  enabled: {fw.get('enabled')}"
               f"{'  (' + str(fw.get('error')) + ')' if fw.get('error') else ''}")
    rules = fw.get('rules_numbered') or fw.get('rules') or []
    ip_blocks = [l for l in rules if re.search(r'\b(REJECT|DENY)\b', l) and re.search(r'\]\s+Anywhere\s', l)]
    rest = [l for l in rules if l not in ip_blocks and '(v6)' not in l]
    out.append(f"  {len(rules)} rules: {len(ip_blocks)} per-IP blocks (fail2ban/recidive), "
               f"{sum('(v6)' in l for l in rules)} IPv6 copies, the rest:")
    out.extend('  ' + l.strip()[:160] for l in rest[:80])
    if shutil.which('fail2ban-client'):
        st = _diag_cmd(['fail2ban-client', 'status'])
        jails = re.findall(r'Jail list:\s*(.*)', st)
        jl = [j.strip() for j in (jails[0].split(',') if jails else []) if j.strip()]
        out.append(f"fail2ban jails: {', '.join(jl) or '(none)'}")
        for jail in jl:
            js = _diag_cmd(['fail2ban-client', 'status', jail])
            banned = (re.findall(r'Banned IP list:\s*(.*)', js) or [''])[0].split()
            if banned:
                out.append(f"  {jail}: {len(banned)} banned — {' '.join(banned[:10])}{' …' if len(banned) > 10 else ''}")
    if shutil.which('wg'):
        wg = _diag_cmd(['wg', 'show', 'all', 'latest-handshakes'])
        for l in wg.splitlines():
            parts = l.split()
            if len(parts) >= 3 and parts[-1].isdigit():
                age = int(time.time()) - int(parts[-1]) if int(parts[-1]) else None
                out.append(f"wireguard {parts[0]} peer …{parts[1][-8:]}: "
                           f"{'never' if age is None else str(age) + ' s since last handshake'}")
    relay = settings.get('email_relay') or {}
    targets = [('github.com', 443), ('ghcr.io', 443), ('registry-1.docker.io', 443)]
    if relay.get('relay_host'):
        try:
            targets.append((relay['relay_host'], int(relay.get('relay_port') or 587)))
        except Exception:
            pass
    for host, port in targets:
        t0 = time.time()
        try:
            socket.create_connection((host, port), timeout=3).close()
            out.append(f"outbound {host}:{port}: ok ({int((time.time() - t0) * 1000)} ms)")
        except Exception as e:
            out.append(f"outbound {host}:{port}: FAILED ({str(e)[:80]})")
    # Certificate expiry of what the box actually presents. openssl s_client is an inspection
    # tool: it shows the certificate whether or not it would verify — which is the point, since an
    # expired or self-signed certificate is what this line exists to catch. Nothing is sent.
    _hp = _caddy_https_port(settings)
    for label, port, sni in ((f'infratak.{fqdn}:{_hp}', _hp, f'infratak.{fqdn}'), ('8446 (TAK web)', 8446, None)):
        if label.startswith('infratak.:'):
            continue
        argv = ['openssl', 's_client', '-connect', f'127.0.0.1:{port}'] + (['-servername', sni] if sni else [])
        raw = _diag_cmd(argv, timeout=8, priv=False, stdin='')
        m = re.search(r'-----BEGIN CERTIFICATE-----.*?-----END CERTIFICATE-----', raw, re.S)
        out.append(f"tls {label}: {_diag_cert_enddate(m.group(0)) if m else 'no certificate presented'}")
    return out


def _diag_section_containers(settings):
    ps = _diag_cmd(['docker', 'ps', '-a', '--format', '{{.Names}}|{{.Status}}|{{.Image}}'], timeout=30)
    rows = [l.split('|') for l in ps.splitlines() if l.count('|') == 2]
    if not rows:
        return [ps or '(no containers)']
    st = _diag_cmd(['docker', 'stats', '--no-stream', '--format', '{{.Name}}|{{.CPUPerc}}|{{.MemUsage}}'],
                   timeout=30)
    use = {f[0]: (f[1], f[2].split('/')[0].strip()) for f in (l.split('|') for l in st.splitlines())
           if len(f) == 3}
    w = max(len(r[0]) for r in rows)
    return [f"{r[0].ljust(w)}  {r[1][:45].ljust(45)}  cpu {use.get(r[0], ('-', ''))[0]:>7}  "
            f"mem {use.get(r[0], ('', '-'))[1]:>10}  {r[2]}" for r in sorted(rows)]


def _diag_section_authentik(settings):
    if not _get_authentik_env_content(settings):
        return ['Authentik not installed on this box']
    out = []
    img = _diag_cmd(['docker', 'inspect', 'authentik-server-1', '--format', '{{.Config.Image}}'])
    out.append(f"image: {img}")
    for c in ('server', 'worker'):
        out.append(f"{c} AUTHENTIK_POSTGRESQL__HOST: "
                   f"{_diag_cmd(['docker', 'exec', f'authentik-{c}-1', 'printenv', 'AUTHENTIK_POSTGRESQL__HOST'])}")
    env = _diag_cmd(['docker', 'inspect', 'authentik-ldap-1', '--format', '{{range .Config.Env}}{{println .}}{{end}}'])
    host = next((l for l in env.splitlines() if l.startswith('AUTHENTIK_HOST=')), 'AUTHENTIK_HOST=(not found)')
    out.append(f"ldap outpost {host}   (internal http://authentik-server… = routing-spiral risk; https://<fqdn> = normal)")
    # One statement: psql -c prints only the LAST result of a multi-statement string.
    sql = ("SELECT 'idle_in_tx='||count(*) FROM pg_stat_activity WHERE state='idle in transaction' "
           "UNION ALL SELECT 'tasks_'||state||'='||count(*) FROM authentik_tasks_task GROUP BY state")
    out.append('postgres: ' + _diag_cmd(['docker', 'exec', 'authentik-postgresql-1', 'psql', '-U', 'authentik',
                                         '-d', 'authentik', '-tAc', sql]).replace('\n', '  '))
    def guarded(label, fn):
        try:
            fn()
        except Exception as e:
            out.append(f"({label} failed: {type(e).__name__}: {str(e)[:160]})")

    def users():
        for u in _diag_ak(settings, 'core/users/?search=webadmin&page_size=20').get('results', []):
            out.append(f"user {u.get('username')}: pk={u.get('pk')} active={u.get('is_active')} type={u.get('type')} "
                       f"path={u.get('path')} superuser={u.get('is_superuser')} last_login={u.get('last_login')}")
            out.append(f"  groups: {[g.get('name') for g in (u.get('groups_obj') or [])]}")

    def reputation():
        for p in _diag_ak(settings, 'policies/reputation/?page_size=20').get('results', []):
            out.append(f"reputation policy {p.get('name')}: threshold={p.get('threshold')} "
                       f"check_username={p.get('check_username')} check_ip={p.get('check_ip')}")
        scores = _diag_ak(settings, 'policies/reputation/scores/?page_size=100&ordering=score').get('results', [])
        out.append(f"reputation scores: {len(scores)}  (at or below the threshold = that username is LOCKED OUT)")
        out.extend(f"  {s.get('identifier')} ip={s.get('ip')} score={s.get('score')} updated={s.get('updated')}"
                   for s in scores[:30])

    def bindings():
        flows = _diag_ak(settings, 'flows/instances/?slug=ldap-authentication-flow').get('results', [])
        apps = [a for a in _diag_ak(settings, 'core/applications/?superuser_full_list=true&page_size=100').get('results', [])
                if 'ldap' in (a.get('slug', '') + a.get('name', '')).lower()]
        # A flow's binding target is its policybindingmodel_ptr_id — its pk is rejected
        # (HTTP 400 "not one of the available choices"). An application's pk works as-is.
        for label, pk in [('flow ldap-authentication-flow', f.get('policybindingmodel_ptr_id') or f['pk']) for f in flows] + \
                         [(f"app {a['slug']}", a['pk']) for a in apps]:
            bs = _diag_ak(settings, f'policies/bindings/?target={pk}&page_size=100').get('results', [])
            out.append(f"policy bindings on {label}: {len(bs)}")
            for b in bs:
                out.append(f"  order={b.get('order')} enabled={b.get('enabled')} negate={b.get('negate')} "
                           f"failure_result={b.get('failure_result')} policy={(b.get('policy_obj') or {}).get('name')} "
                           f"group={(b.get('group_obj') or {}).get('name')} user={(b.get('user_obj') or {}).get('username')}")

    guarded('webadmin user lookup', users)
    guarded('reputation lookup', reputation)
    guarded('policy binding lookup', bindings)
    out.append('ldap bind as webadmin:')
    out.append(_diag_ldap_bind('cn=webadmin,ou=users,dc=takldap', (settings.get('webadmin_password') or '').strip()))
    out.append('ldap bind as adm_ldapservice:')
    out.append(_diag_ldap_bind('cn=adm_ldapservice,ou=users,dc=takldap',
                               _get_authentik_env_value(settings, 'AUTHENTIK_BOOTSTRAP_LDAPSERVICE_PASSWORD')))
    lg = _diag_cmd(['docker', 'logs', 'authentik-ldap-1', '--since', '3h', '--tail', '5000'], timeout=30)
    hits = [l for l in lg.splitlines() if '"Search request"' not in l and
            re.search(r'webadmin|does not apply|invalid cred|denied|"level":"error"|recursion', l, re.I)]
    out.append(f"ldap outpost log, last 3 h (webadmin / denials / errors): {len(hits)} line(s)")
    out.extend('  ' + l[:300] for l in hits[-25:])
    sl = _diag_cmd(['docker', 'logs', 'authentik-server-1', '--since', '12h', '--tail', '20000'], timeout=40)
    dels = [l for l in sl.splitlines() if '"DELETE"' in l and 'core/users' in l]
    out.append(f"server log, last 12 h: user DELETE requests: {len(dels)}")
    out.extend('  ' + l[:300] for l in dels[-10:])
    def events():
        ev = _diag_ak(settings, 'events/events/?search=webadmin&ordering=-created&page_size=20').get('results', [])
        out.append('events for webadmin (newest first):')
        for e in ev:
            c = e.get('context') or {}
            out.append(f"  {str(e.get('created', ''))[:19]} {e.get('action')} "
                       f"{str(c.get('message') or c.get('reason') or '')[:160]}")
    guarded('event lookup', events)
    return out


def _diag_section_takserver(settings):
    try:
        method = _tak_install_method()
    except Exception:
        method = '?'
    if not os.path.exists('/opt/tak') and not _tak_is_container():
        return ['TAK Server not installed on this box'] + _diag_tak_update_history()
    out = [f"install method: {method}"]
    ver = _diag_cmd(['dpkg-query', '-W', '-f=${Version}', 'takserver'], priv=False) if shutil.which('dpkg-query') \
        else _diag_cmd(['rpm', '-q', 'takserver'], priv=False)
    out.append(f"package: {ver}   service: {_diag_cmd(['systemctl', 'is-active', 'takserver'], priv=False)}")
    for prof in ('api', 'messaging'):
        pid = _diag_cmd(['pgrep', '-f', f'java.*spring.profiles.active={prof}'], priv=False).split('\n')[0].strip()
        if pid.isdigit():
            try:
                jvm = os.readlink(f'/proc/{pid}/exe')
            except OSError:
                jvm = '(not readable as the console user)'
            # v10.2.7: warn only when it applies. Printed unconditionally before, it read as a
            # diagnosis on every healthy Java-17 box (seen in the lutak2.net report, 2026-10-03).
            _jm = re.search(r'(?:java|jdk|jre)-?(\d{2})\b', jvm)
            _jmajor = int(_jm.group(1)) if _jm else 0
            _jnote = ('   WARNING: TAK 5.7 on Java 21+ = every new QR enrollment fails (pin Java 17)'
                      if _jmajor >= 21 and '5.7' in (ver or '') else '')
            out.append(f"running JVM ({prof}): {jvm}{_jnote}")
    out.append(f"default java: {os.path.realpath(shutil.which('java') or '') or '(none)'}")
    try:
        out.append(f"installed JVMs: {', '.join(sorted(d for d in os.listdir('/usr/lib/jvm') if not d.startswith('.'))) or '(none)'}")
    except OSError:
        pass
    try:
        cc = _read_own_or_priv('/opt/tak/CoreConfig.xml') or ''
    except Exception as e:
        cc = ''
        out.append(f"CoreConfig.xml not readable ({str(e)[:80]})")
    for tag, attrs in (('ldap', ('url', 'adminGroup', 'groupprefix', 'style', 'serviceAccountDN',
                                 'enableConnectionPool')),
                       ('auth', ('default', 'x509groups', 'x509useGroupCache')),
                       ('connector', ('port', 'clientAuth', '_name')),
                       # v10.2.11: where TAK looks for its database and as whom (never the password)
                       ('connection', ('url', 'username'))):
        for el in re.findall(rf'<{tag}\b[^>]*>', cc):
            out.append(f"<{tag}> " + ' '.join(f'{a}={v}' for a, v in re.findall(r'(\w+)="([^"]*)"', el) if a in attrs))
    for el in re.findall(r'<input\b[^>]*>', cc):
        out.append('<input> ' + ' '.join(f'{a}={v}' for a, v in re.findall(r'(\w+)="([^"]*)"', el)
                                         if a in ('_name', 'protocol', 'port', 'auth')))
    try:
        uaf = _read_own_or_priv('/opt/tak/UserAuthenticationFile.xml') or ''
        in_flat = 'yes' if 'identifier="webadmin"' in uaf else 'no'
        out.append(f"flat-file users: {uaf.count('<User ')}  webadmin in flat file: {in_flat}")
    except Exception:
        pass
    for name in ('takserver.pem', 'ca.pem'):
        try:
            out.append(f"cert {name}: {_diag_cert_enddate(_read_own_or_priv('/opt/tak/certs/files/' + name))}")
        except Exception:
            pass
    est = _diag_cmd(['ss', '-tnH', 'state', 'established', '( sport = :8089 )'], priv=False)
    peers = [l.split()[-1] for l in est.splitlines() if l.split()]
    out.append(f"clients connected on 8089: {len(peers)}")
    out.extend(f"  peer {p}" for p in peers[:25])
    noise = re.compile(r'DEBUG|FedReconnectPool|grpc-federation|PeriodicUpdateCancellation|federation|TakFig|'
                       r'no certificate revocation lists|mission subscription for client')
    frame = re.compile(r'^\s+at |^\s*\.\.\. \d+ more')
    for log in ('takserver-messaging.log', 'takserver-api.log'):
        lines = _diag_tail('/opt/tak/logs/' + log)
        if lines is None:
            out.append(f"{log}: {_diag_unreadable('/opt/tak/logs/' + log)}")
            continue
        hits = [l for l in _diag_tak_log_window(lines)
                if not frame.search(l) and not noise.search(l)
                and re.search(r'ssl|tls|handshake|certificate|signClient|enroll|ldap|Exception|\bERROR\b', l, re.I)]
        out.append(f"{log}, last 3 h: {len(hits)} TLS/enrollment/LDAP/error line(s)")
        # Grouped by cause and client host: one device retrying a failed handshake every
        # second buries everything else, and the client's address — the thing support
        # needs — sits at the very end of the line where a plain truncation drops it.
        groups = {}
        for l in hits:
            m = re.search(r'Cause: (.*?)(?:\. Additional info|$)', l)
            cause = (m.group(1) if m else re.sub(r'^\S+ \[[^\]]*\] \w+ \S+ - ', '', l))[:110]
            r = re.search(r'Remote address: /?([^\s,;]+)', l)
            remote = r.group(1).rsplit(':', 1)[0] if r else '-'
            groups[(cause, remote)] = groups.get((cause, remote), 0) + 1
        for (cause, remote), n in sorted(groups.items(), key=lambda kv: -kv[1])[:12]:
            out.append(f"  {n:>6} x {cause}   from {remote}")
        if hits:
            out.append('  newest:')
            out.extend('    ' + l[:320] for l in hits[-6:])
    # v10.2.3: a backup that stalls on a lock can be explained from a report alone —
    # without running the update again to watch it fail.
    _mode = _get_tak_deployment_config(settings).get('mode')
    if _mode in ('two_server', 'external_db'):
        out.append(f"cot database sessions: not shown — the database is not on this box ({_mode})")
    else:
        out.extend(_cot_stall_report())
    out.extend(_diag_tak_update_history())
    return out


def _diag_tak_update_history(tail=150):
    """v10.2.2 W9: recent TAK Server update runs + the log of the latest that did not
    succeed (recorded by _tak_update_job; redacted with the rest of the report)."""
    out = []
    live = upgrade_status.get('running') or tak58_status.get('running')
    if live:
        out.append('TAK Server update: one is RUNNING right now — its log so far is below')
    hist = _tak_update_history()
    if not hist:
        out.append('TAK Server updates recorded by this console: none (recording began in v10.2.2)')
        return out
    # 'running' is a checkpoint (v10.2.11). Only the newest can still be live; any other —
    # or the newest when no worker is running — was cut off mid-run.
    for i, h in enumerate(hist):
        if h.get('result') == 'running' and not (live and i == 0):
            h['result'] = 'INTERRUPTED (the console stopped mid-run; last checkpoint shown)'
    out.append('TAK Server updates recorded by this console (newest first; time = end, or last checkpoint):')
    for h in hist:
        out.append(f"  {h.get('finished', '?')}  {h.get('result', '?')}  {h.get('kind', '?')}  "
                   f"{h.get('package') or '-'}  (started {h.get('started', '?')}, {h.get('seconds', '?')} s)")
    bad = next((h for h in hist if h.get('result') != 'ok'), None)
    if bad:
        lines = bad.get('lines') or []
        out.append(f"log of the latest update that did not succeed or is still running ({bad.get('finished')}, "
                   f"{bad.get('kind')}), last {min(len(lines), tail)} of {bad.get('total_lines', len(lines))} lines:")
        out.extend('    ' + str(l)[:300] for l in lines[-tail:])
    return out


# ── v10.2.11 (ops #9): enough to say HOW a TAK database broke, from the report alone ──
# lutak2.net (GH #105/#106) sent a report showing TAK 5.8 installed, "database cot does not
# exist" and martiuser failing to log in — and nothing that said which PostgreSQL clusters
# exist, what installed 5.8 and when, or whether the data is still on disk. Every answer
# started "please run pg_lsclusters…". These two sections are those questions.
_DIAG_PKG_RE = re.compile(r'takserver|postgres|postgis|openjdk', re.I)
_DIAG_TRAIL_DAYS = 30


def _diag_log_lines(path, max_bytes=_DIAG_TAIL_BYTES):
    """Tail of a log as lines: a direct read, else (under a log or PostgreSQL directory the
    broker may read) a privileged one. None when neither works."""
    lines = _diag_tail(path, max_bytes)
    if lines is None and path.startswith(('/var/log/', '/var/lib/postgresql/', '/var/lib/pgsql/')):
        try:
            txt = _read_own_or_priv(path)
            lines = txt.splitlines()[-20000:] if txt is not None else None   # '' = an empty log
        except Exception:
            lines = None
    return lines


def _diag_rotated_lines(path, keep=2):
    """A log and its rotated copies (path.1, path.2.gz, …), oldest first; unreadable ones skipped."""
    import gzip
    out = []
    for i in range(keep, 0, -1):
        for p in (f'{path}.{i}', f'{path}.{i}.gz'):
            try:
                with (gzip.open(p, 'rb') if p.endswith('.gz') else open(p, 'rb')) as f:
                    out.extend(f.read(8 * 1024 * 1024).decode('utf-8', 'replace').splitlines())
            except OSError:
                pass
    return out + (_diag_log_lines(path) or [])


def _diag_pg_overview(port=None):
    """Version, port, data directory, databases (with size) and login roles of a local
    cluster. Fixed, console-authored SQL only (see _pg_exec's security invariant)."""
    sql = ("SELECT 'server '||current_setting('server_version')||'  port '||current_setting('port')"
           "||'  data '||current_setting('data_directory') "
           "UNION ALL SELECT 'database '||datname||'  '||pg_size_pretty(pg_database_size(datname)) "
           "FROM pg_database WHERE NOT datistemplate "
           "UNION ALL SELECT 'login roles: '||coalesce(string_agg(rolname, ', ' ORDER BY rolname), '(none)') "
           "FROM pg_roles WHERE rolcanlogin")
    try:
        r = _pg_exec(['psql', '-tAX', '-d', 'postgres'] + (['-p', str(port)] if port else []) + ['-c', sql],
                     timeout=20)
    except Exception as e:
        return [f'  (could not query: {str(e)[:160]})']
    if r.returncode != 0:
        return ['  (could not query: %s)' % ((r.stderr or '').strip()[:160] or 'exit %s' % r.returncode)]
    return ['  ' + l for l in (r.stdout or '').splitlines() if l.strip()]


def _diag_pg_log(path):
    """FATAL/ERROR/start/stop lines of a PostgreSQL server log, repeats counted."""
    lines = _diag_log_lines(path, 1024 * 1024)
    if lines is None:
        return [f"  {path}: missing, or not readable by the console on this box"]
    hits = [l for l in lines if re.search(r'FATAL|PANIC|ERROR|starting PostgreSQL|shutting down|'
                                          r'database system (is ready|was shut down|was interrupted)|'
                                          r'received \w+ shutdown', l)]
    groups = {}
    for l in hits:
        msg = re.sub(r'^\S+ \S+ \S+ \[\d+\]\s*(\S+@\S+\s+)?', '', l)[:160]
        groups[msg] = groups.get(msg, 0) + 1
    out = [f"  {path}: {len(hits)} error/start/stop line(s) in the recent tail"]
    out.extend(f"    {n:>6} x {m}" for m, n in sorted(groups.items(), key=lambda kv: -kv[1])[:10])
    if hits:
        out.append('    newest:')
        out.extend('      ' + l[:240] for l in hits[-8:])
    return out


def _diag_section_tak_database(settings):
    if not os.path.exists('/opt/tak') and not _tak_is_container():
        return ['TAK Server not installed on this box']
    out = []
    deb = bool(shutil.which('dpkg-query'))
    if deb:
        pk = _diag_cmd(['dpkg-query', '-W', '-f=${db:Status-Abbrev} ${Package} ${Version}\n',
                        'takserver*', 'postgresql*', 'postgis*'], priv=False)
        # Status 'ii' = installed; 'iU'/'iF'/'iH' = unpacked or half-configured — an install
        # that did not finish, which the next apt run will try to complete.
        rows = [l for l in pk.splitlines() if l.strip() and not l.startswith(('un ', 'dpkg-query:'))]
    else:
        rows = _diag_cmd(['rpm', '-qa', '--last', 'takserver*', 'postgresql*', 'postgis*'], priv=False).splitlines()
    out.append('packages (takserver / postgresql / postgis):' + ('' if rows else ' none found'))
    out.extend('  ' + l.strip()[:160] for l in rows[:40])
    mode = _get_tak_deployment_config(settings).get('mode')
    units = []
    if mode in ('two_server', 'external_db'):
        out.append(f"PostgreSQL: the TAK database is not on this box ({mode}) — clusters not listed")
    elif _tak_is_container():
        out.append('PostgreSQL (inside the TAK database container):')
        out.extend(_diag_pg_overview())
    elif deb:
        lsc = _diag_cmd(['pg_lsclusters', '--no-header'])
        rows = [l.split() for l in lsc.splitlines() if l.strip()]
        clusters = [r for r in rows if len(r) >= 6 and r[0].isdigit()]
        out.append('PostgreSQL clusters (pg_lsclusters): version cluster port status owner data-dir log')
        out.extend('  ' + ' '.join(r) for r in rows[:10])
        if not clusters:
            out.append('  (no clusters listed' + (f': {lsc[:160]}' if lsc else '') + ')')
        for r in clusters:
            if r[3].startswith('online'):
                out.append(f'cluster {r[0]}/{r[1]} (port {r[2]}):')
                out.extend(_diag_pg_overview(r[2]))
        out.append('PostgreSQL server logs:')
        for r in clusters:
            # TAK's clusters log through logging_collector into <data>/log/postgresql-%a.log
            # (pg_lsclusters prints that relative pattern): today's and yesterday's file.
            if len(r) > 6 and not r[6].startswith('/') and r[5].startswith('/var/lib/postgresql/'):
                for d in (1, 0):
                    out.extend(_diag_pg_log(os.path.join(
                        r[5], (datetime.now() - timedelta(days=d)).strftime(r[6]))))
            else:
                out.extend(_diag_pg_log(r[6] if len(r) > 6 else f'/var/log/postgresql/postgresql-{r[0]}-{r[1]}.log'))
        units = [f'postgresql@{r[0]}-{r[1]}.service' for r in clusters]
    else:
        try:
            dirs = sorted(d for d in os.listdir('/var/lib/pgsql') if d[:2].isdigit())
        except OSError:
            dirs = []
        out.append(f"PostgreSQL data directories under /var/lib/pgsql: {', '.join(dirs) or '(none readable)'}")
        units = _diag_cmd(['systemctl', 'list-units', '--all', '--no-legend', '--plain', 'postgresql*'], priv=False)
        out.extend('  unit ' + ' '.join(l.split()[:4]) for l in units.splitlines() if l.strip())
        out.append('cluster on the default port:')
        out.extend(_diag_pg_overview())
        out.append('PostgreSQL server logs:')
        vers = sorted(set(re.findall(r'postgresql-(\d+)\.service', units)) | set(dirs))
        for v in vers:
            for d in (1, 0):
                out.extend(_diag_pg_log(f"/var/lib/pgsql/{v}/data/log/"
                                        f"postgresql-{(datetime.now() - timedelta(days=d)).strftime('%a')}.log"))
        units = [f'postgresql-{v}.service' for v in vers]
    if units and mode not in ('two_server', 'external_db') and not _tak_is_container():
        # Start/stop history of each cluster's unit: when a cluster first came up and when one
        # was stopped — the two events that bracket an upgrade. Named units, not a glob: a
        # `-u 'postgresql*'` glob scans the whole journal (30 s and nothing, on test6).
        j = _diag_cmd(['journalctl'] + [a for u in units for a in ('-u', u)] +
                      ['--since', f'{_DIAG_TRAIL_DAYS} days ago', '--no-pager', '-q', '-o', 'short-iso'], timeout=30)
        ev = [l for l in j.splitlines() if re.search(r'Start|Stop|Fail|exited|Deactivated', l)]
        out.append(f"PostgreSQL service start/stop ({', '.join(units)}), last {_DIAG_TRAIL_DAYS} days: {len(ev)} line(s)")
        out.extend('  ' + l[:200] for l in ev[-25:])
    snaps = (settings.get('tak_snapshots') or [])[:6]
    out.append(f"TAK snapshots recorded (newest first): {len(settings.get('tak_snapshots') or [])}")
    for sn in snaps:
        lbl = str(sn.get('label') or '?')
        p = os.path.join(SNAPSHOT_DIR, lbl)
        try:   # a directory: _exists_priv reads files, so ask `test -d` (broker-allowed) instead
            on_disk = re.match(r'^[\w.-]+$', lbl) and (os.path.isdir(p) or subprocess.run(
                _sudo_wrap(['test', '-d', p]), capture_output=True, timeout=10).returncode == 0)
        except Exception:
            on_disk = False
        out.append(f"  {lbl}  taken {sn.get('taken_at', '?')}  TAK {sn.get('tak_version') or '?'}  "
                   f"{sn.get('size_mb', '?')} MB  db_dump={sn.get('db_dump')}"
                   f"{' (' + str(sn.get('db_dump_bytes') // 1024) + ' KB)' if isinstance(sn.get('db_dump_bytes'), int) else ''}"
                   f"  on disk: {'yes' if on_disk else 'NO'}")
    return out


def _diag_apt_history(lines, cutoff):
    """apt transactions since `cutoff` that touched TAK/PostgreSQL/Java: when, the command
    line, who asked, the matching packages, and whether the transaction finished."""
    out, block = [], {}

    def flush():
        if not block.get('Start-Date') or block['Start-Date'] < cutoff:
            return
        pk = []
        for k in ('Install', 'Upgrade', 'Downgrade', 'Remove', 'Purge', 'Reinstall'):
            hits = [p for p in re.findall(r'(\S+ \([^)]*\))', block.get(k, '')) if _DIAG_PKG_RE.search(p)]
            if hits:
                pk.append(f"{k}: {', '.join(hits)}")
        if not pk and not _DIAG_PKG_RE.search(block.get('Commandline', '')):
            return
        out.append(f"  {block['Start-Date']}  {block.get('Commandline', '(no command line)')[:200]}"
                   f"{'  [requested by ' + block['Requested-By'] + ']' if block.get('Requested-By') else ''}")
        out.extend('      ' + p[:300] for p in pk)
        if block.get('Error'):
            out.append('      Error: ' + block['Error'][:240])
        if not block.get('End-Date'):
            out.append('      NO End-Date — this transaction did not finish')
    for ln in lines + ['']:
        if not ln.strip():
            flush()
            block = {}
            continue
        k, _, v = ln.partition(': ')
        block[k.strip()] = v.strip()
    return out


def _diag_section_change_trail(settings):
    out = []
    cutoff = (datetime.utcnow() - timedelta(days=_DIAG_TRAIL_DAYS)).strftime('%Y-%m-%d')
    if os.path.exists('/var/log/apt'):
        hist = _diag_apt_history(_diag_rotated_lines('/var/log/apt/history.log'), cutoff)
        out.append(f"apt transactions touching takserver/postgresql/postgis/java, last {_DIAG_TRAIL_DAYS} days: "
                   f"{sum(1 for l in hist if not l.startswith('      '))}")
        out.extend(hist[-60:])
        # dpkg.log also catches a bare `dpkg -i`, which apt's history never sees.
        dp = [l for l in _diag_rotated_lines('/var/log/dpkg.log')
              if l[:10] >= cutoff and len(l.split()) > 3
              and l.split()[2] in ('install', 'upgrade', 'remove', 'purge') and _DIAG_PKG_RE.search(l.split()[3])]
        out.append(f"dpkg install/upgrade/remove of those packages, last {_DIAG_TRAIL_DAYS} days: {len(dp)}")
        out.extend('  ' + l[:200] for l in dp[-40:])
    else:
        # Dated lines only: rpm scriptlet output is logged undated between them.
        recent = lambda l: re.match(r'\d{4}-\d{2}-\d{2}', l) and l[:10] >= cutoff
        rl = [l for l in _diag_rotated_lines('/var/log/dnf.rpm.log')
              if recent(l) and _DIAG_PKG_RE.search(l)
              and re.search(r'\b(Install|Upgrade|Upgraded|Downgrade|Erase|Reinstall)', l)]
        out.append(f"rpm transactions touching takserver/postgresql/postgis/java, last {_DIAG_TRAIL_DAYS} days: {len(rl)}")
        out.extend('  ' + l[:200] for l in rl[-40:])
        cmds = [l for l in _diag_rotated_lines('/var/log/dnf.log')
                if recent(l) and 'Command:' in l and _DIAG_PKG_RE.search(l)]
        out.append(f"dnf commands naming those packages, last {_DIAG_TRAIL_DAYS} days: {len(cmds)}")
        out.extend('  ' + l[:200] for l in cmds[-15:])
    # The OS patch job (Help/Dashboard "Install updates"): apt full-upgrade / dnf upgrade
    # with TAK held — but PostgreSQL is not held, and its runs are not otherwise visible here.
    kp = _diag_log_lines(_KERNEL_PATCH_LOGFILE, 1024 * 1024)
    if kp is None:
        out.append(f"OS patch job log: {_diag_unreadable(_KERNEL_PATCH_LOGFILE)}")
    else:
        keep = [l for l in kp if re.search(r'=== |FATAL|WARN|held|released', l)
                or (_DIAG_PKG_RE.search(l) and re.search(r'Unpacking|Setting up|Removing|Upgrading|Installing|'
                                                         r'Erasing|Creating new|Stopping|Starting|cluster', l))]
        runs = sum('job starting' in l for l in kp)
        out.append(f"OS patch job log: {runs} run(s) in the recent tail; start/end, warnings and TAK/PostgreSQL/Java lines:")
        out.extend('  ' + l[:220] for l in keep[-40:])
    # v10.3.0 W4: the console-driven 22.04 -> 24.04 upgrade. Its status file names the step, its
    # log says why and whether the box is unchanged; Ubuntu's upgrader keeps its own log. A failed
    # run must reach us in the report an operator sends, not only in a panel they closed.
    try:
        ou_status = _os_upgrade_read_status()
    except Exception:
        ou_status = ''
    ou = _diag_log_lines(_OS_UPGRADE_LOGFILE, 1024 * 1024) if os.path.exists(_OS_UPGRADE_LOGFILE) else None
    if ou_status or os.path.exists(_OS_UPGRADE_LOGFILE):
        out.append(f"OS upgrade 22.04 -> 24.04 status: {ou_status or 'none recorded'}")
        if ou is None:
            out.append(f"OS upgrade job log: {_diag_unreadable(_OS_UPGRADE_LOGFILE)}")
        else:
            keep = [l for l in ou if re.search(r'=== |FATAL|WARN|UNCHANGED|PARTLY UPGRADED|re-enabled|'
                                                r'pg_lsclusters|venv|rebooting|Please |^E: ', l)]
            out.append(f"OS upgrade job log: {sum('upgrade 22.04 -> 24.04 starting' in l for l in ou)} run(s); "
                       f"steps, failures and the upgrader's own refusals:")
            out.extend('  ' + l[:220] for l in keep[-60:])
        if os.path.exists('/var/log/dist-upgrade'):
            dl = _diag_log_lines('/var/log/dist-upgrade/main.log', 256 * 1024)
            if dl:
                out.append("ubuntu-release-upgrader main.log (last 25 lines):")
                out.extend('  ' + l[:220] for l in dl[-25:])
    boots = _diag_cmd(['journalctl', '--list-boots', '--no-pager', '-q'], timeout=20)
    bl = [l for l in boots.splitlines() if l.strip()]
    out.append(f"boots in the journal: {len(bl)} (newest last)")
    out.extend('  ' + l.strip()[:160] for l in bl[-8:])
    for unit in ('takwerx-console.service', 'takserver.service'):
        j = _diag_cmd(['journalctl', f'UNIT={unit}', '--since', f'{_DIAG_TRAIL_DAYS} days ago',
                       '--no-pager', '-q', '-o', 'short-iso'], timeout=30)
        ev = [l for l in j.splitlines() if re.search(r'Started|Stopped|Stopping|Failed|exited|restart', l)
              and 'Killing process' not in l]
        out.append(f"{unit} start/stop, last {_DIAG_TRAIL_DAYS} days: {len(ev)} line(s)")
        out.extend('  ' + l[:200] for l in ev[-15:])
    return out


def _diag_section_takportal(settings):
    names = [n for n in _diag_cmd(['docker', 'ps', '-a', '--format', '{{.Names}}']).splitlines()
             if 'portal' in n.lower()]
    if not names:
        return ['TAK Portal not installed on this box']
    web = next((n for n in names if not re.search(r'worker|db|postgres|redis', n, re.I)), names[0])
    out = [f"containers: {', '.join(names)}"]
    lg = _diag_cmd(['docker', 'logs', web, '--since', '3h', '--tail', '5000'], timeout=30)
    hits = [l for l in lg.splitlines() if re.search(r'enroll|qr|itak|error|fail', l, re.I)]
    out.append(f"{web} log, last 3 h (enrollment / errors): {len(hits)} line(s)")
    out.extend('  ' + l[:260] for l in hits[-20:])
    # v10.2.8 W12: the addresses Portal uses for TAK, its own links and Authentik — the bcg-tak
    # report could not show that Portal was still on the server's IP.
    existing = {}
    try:
        existing = _takportal_get_existing_settings() or {}
        out.append('addresses: ' + ', '.join(f"{k}={existing.get(k) or '(unset)'}" for k in TAKPORTAL_DOMAIN_KEYS))
        stale = _takportal_stale_address_fields(settings, existing=existing)
        if stale:
            out.append('⚠ still on the server IP while the box has a domain: '
                       + ', '.join(f"{f['key']} (should be {f['suggested']})" for f in stale))
    except Exception as e:
        out.append(f'addresses: could not read ({str(e)[:100]})')
    out.extend(_diag_takportal_authentik(settings, existing))
    return out


def _diag_takportal_token_state(token, infratak_token):
    """'BLANK' / 'TEMPLATE PLACEHOLDER' / 'set (N chars, …)' for Portal's AUTHENTIK_TOKEN.
    Never the value — only its length and whether it equals the token infra-TAK would push."""
    t = str(token or '').strip()
    if not t:
        return 'BLANK'
    if t == TAKPORTAL_TEMPLATE_PLACEHOLDERS['AUTHENTIK_TOKEN']:
        return 'TEMPLATE PLACEHOLDER'
    if not infratak_token:
        same = "infra-TAK's Authentik .env has no token to compare"
    elif hmac.compare_digest(t, infratak_token):
        same = "same as infra-TAK's Authentik token"
    else:
        same = "DIFFERENT from infra-TAK's Authentik token"
    return f'set ({len(t)} chars, {same})'


def _diag_takportal_authentik(settings, existing):
    """ops #71: TAK Portal's side of every Authentik write — the URL and token it calls with,
    and its authentik_outbox queue, whose last_error is the real Authentik error behind
    "Authentik operation failed and remains queued for retry". Read-only SELECTs."""
    out = []
    raw_url = str((existing or {}).get('AUTHENTIK_URL') or '').strip()
    try:
        p = urllib.parse.urlsplit(raw_url)
        url = f'{p.scheme}://{p.hostname}{":" + str(p.port) if p.port else ""}' if p.hostname else raw_url
    except ValueError:
        url = raw_url
    if raw_url == TAKPORTAL_TEMPLATE_PLACEHOLDERS['AUTHENTIK_URL']:
        url += '  <-- TAK Portal template placeholder'
    infratak_token = (_get_authentik_env_value(settings, 'AUTHENTIK_BOOTSTRAP_TOKEN')
                      or _get_authentik_env_value(settings, 'AUTHENTIK_TOKEN') or '').strip()
    out.append(f"authentik as TAK Portal calls it: AUTHENTIK_URL={url or '(unset)'}  "
               f"AUTHENTIK_TOKEN={_diag_takportal_token_state((existing or {}).get('AUTHENTIK_TOKEN'), infratak_token)}")
    db = next((c['name'] for c in _takportal_project_containers() if c['service'] == 'postgres'),
              'tak-portal-postgres')

    def q(sql):
        return _diag_cmd(['docker', 'exec', db, 'psql', '-U', 'takportal', '-d', 'takportal',
                          '-tA', '-F', '|', '-c', sql])
    count = q('SELECT count(*) FROM authentik_outbox')
    if not count.strip().isdigit():
        out.append(f'authentik_outbox: could not read ({count.strip()[:160] or "no output"})')
        return out
    out.append(f'authentik_outbox: {count.strip()} queued row(s) (0 = every Authentik write applied)')
    rows = q("SELECT id, kind, attempts, to_char(created_at AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI'), "
             "regexp_replace(coalesce(last_error, ''), '\\s+', ' ', 'g') "
             "FROM authentik_outbox ORDER BY id DESC LIMIT 5")
    for ln in rows.splitlines():
        f = ln.split('|', 4)
        if len(f) == 5:
            out.append(f"  id={f[0]} {f[1]} attempts={f[2]} queued {f[3]} UTC  "
                       f"last_error: {f[4][:240] or '(none yet)'}")
    # A row that fails 20 times is dead-lettered: deleted, its error kept only here.
    dead = q("SELECT regexp_replace(coalesce(last_error, ''), '\\s+', ' ', 'g') FROM directory_sync WHERE id = 1").strip()
    out.append(f"directory_sync last_error: {dead[:300] or '(none)'}")
    return out


def _diag_section_emailrelay(settings):
    relay = settings.get('email_relay') or {}
    configured = bool(relay.get('relay_host') and relay.get('smtp_user'))
    out = [f"configured: {configured}  relay: {relay.get('relay_host') or '-'}:{relay.get('relay_port') or '-'}  "
           f"from: {relay.get('from_addr') or '-'}  postfix: {_diag_cmd(['systemctl', 'is-active', 'postfix'], priv=False)}"]
    if not configured:
        return out
    q = _diag_cmd(['postqueue', '-p'], priv=False)
    queued = [l for l in q.splitlines() if re.match(r'^[0-9A-F]{6,}', l)]
    out.append(f"mail queue: {len(queued)} message(s)")
    reasons = [l.strip() for l in q.splitlines() if l.strip().startswith('(')]
    out.extend('  ' + r[:220] for r in sorted(set(reasons))[:8])
    for path in ('/var/log/mail.log', '/var/log/maillog'):
        lines = _diag_tail(path, 512 * 1024)
        if lines is not None:
            errs = [l for l in lines if re.search(r'status=(deferred|bounced)|reject|warning|error', l, re.I)]
            out.append(f"{path}: {len(errs)} deferred/bounced/error line(s) in the recent tail")
            out.extend('  ' + l[:240] for l in errs[-10:])
            break
    return out


def _diag_section_guarddog(settings):
    if not os.path.exists('/opt/tak-guarddog'):
        return ['Guard Dog not deployed on this box']
    out = [f"deployed version: {settings.get('guarddog_deployed_version') or '?'}"]
    timers = _diag_cmd(['systemctl', 'list-timers', '--all', '--no-pager', '--plain', 'tak*'], priv=False)
    out.append(f"timers: {len([l for l in timers.splitlines() if '.timer' in l])}")
    # restarts.log is Guard Dog's event log — every watcher appends its restarts/alerts there.
    # (10.2.1 read watchdog.log, which nothing writes: every box reported it "not readable".)
    log = '/var/log/takguard/restarts.log'
    lines = _diag_tail(log, 512 * 1024)
    if lines is None:
        out.append(f"restarts.log: {_diag_unreadable(log)}")
    else:
        ev = [l for l in lines if re.search(r'restart|alert|fail|unhealthy|missing|down', l, re.I)
              and 'fail2ban: Banned' not in l]
        out.append(f"restarts.log: {len(ev)} restart/alert line(s) in the recent tail")
        out.extend('  ' + l[:240] for l in ev[-15:])
        # The weekly repack logs why it failed or skipped here, but a chatty watcher pushes
        # it out of the last 15 (ops #74: takdbrepack `failed`, reason nowhere in the report).
        rp = [l for l in lines if 'DB-REPACK:' in l]
        if rp:
            out.append(f"last DB-REPACK line(s), {len(rp)} in the recent tail:")
            out.extend('  ' + l[:240] for l in rp[-3:])
    return out


def _diag_section_modules(settings):
    flags = sorted(k for k, v in settings.items()
                   if re.search(r'_(enabled|deployed|installed)$', k) and v and not isinstance(v, dict))
    vers = sorted(f'{k}={v}' for k, v in settings.items()
                  if re.search(r'(_version|_tag|_release)$', k) and isinstance(v, (str, int)) and v)
    return [f"enabled/deployed flags: {', '.join(flags) or '(none)'}",
            f"recorded versions: {', '.join(vers) or '(none)'}",
            'container states: see "Containers" above']


def _diag_section_module_results(settings):
    """v10.2.8 W10: the last update/deploy result of every module, from .config/module-results.json —
    so a failure the customer saw (or did not see) is in the report they send, with its reason."""
    d = _mod_results_load()
    if not d:
        return ['no module update or deploy has been recorded on this box yet '
                '(recording began in v10.2.8)']
    out = []
    for name in sorted(d):
        m = d.get(name) or {}
        last = m.get('last') or {}
        when = (last.get('finished_at') or last.get('started_at') or '?').replace('T', ' ').rstrip('Z')
        line = (f"{name}: last {last.get('kind') or 'update'} {(last.get('outcome') or '?').upper()} "
                f"{when} UTC ({last.get('from') or '?'} -> {last.get('to') or '?'})")
        if last.get('outcome') in ('failed', 'interrupted'):
            line += f" | step: {last.get('step') or '?'} | {last.get('error') or '(no reason recorded)'}"
            if last.get('summary') and last.get('summary') not in (last.get('error') or ''):
                line += f" | message: {last.get('summary')}"
        out.append(line)
        for h in (m.get('history') or [])[1:4]:
            if h.get('outcome') in ('failed', 'interrupted'):
                out.append(f"    earlier {h.get('outcome')} "
                           f"{(h.get('finished_at') or h.get('started_at') or '?').replace('T', ' ').rstrip('Z')} UTC: "
                           f"{h.get('error') or '?'}")
    return out


_DIAG_SECTIONS = (
    ('Box', _diag_section_box),
    ('Console', _diag_section_console),
    ('Module updates — last result per module', _diag_section_module_results),
    ('Connectivity', _diag_section_connectivity),
    ('Containers', _diag_section_containers),
    ('Authentik / LDAP / webadmin', _diag_section_authentik),
    ('TAK Server', _diag_section_takserver),
    ('TAK Server database — PostgreSQL, packages, snapshots', _diag_section_tak_database),
    ('What changed on this box — installs, OS patches, reboots, restarts', _diag_section_change_trail),
    ('TAK Portal', _diag_section_takportal),
    ('Email Relay', _diag_section_emailrelay),
    ('Guard Dog', _diag_section_guarddog),
    ('Other modules', _diag_section_modules),
)


def _diag_collect():
    """The full report text, redacted. Never raises."""
    settings = load_settings()
    t0 = time.time()
    parts = [f"infra-TAK diagnostics — {settings.get('fqdn') or settings.get('server_ip') or 'unknown box'} — "
             f"v{VERSION} — {datetime.utcnow().strftime('%Y-%m-%d %H:%M:%S')} UTC",
             'This report contains hostnames, IP addresses, usernames and log lines. '
             'Passwords, tokens and keys are redacted. Nothing was changed on this box to produce it.']
    for n, (title, fn) in enumerate(_DIAG_SECTIONS, 1):
        s0 = time.time()
        try:
            body = fn(settings)
        except Exception as e:
            body = [f'(section failed: {type(e).__name__}: {str(e)[:200]})']
        parts.append(f"\n===== {n}. {title}  ({time.time() - s0:.1f} s) =====")
        parts.extend(str(x) for x in body)
    parts.append(f"\n===== end — {time.time() - t0:.0f} s =====")
    return _diag_redact('\n'.join(parts), settings)


@app.route('/api/module-results/<module>')
@login_required
def module_result_api(module):
    """v10.2.8 W10: a module's last recorded update/deploy result (read-only)."""
    if not _MODULE_NAME_RE.match(module or ''):
        return jsonify({'error': 'unknown module'}), 400
    return jsonify({'module': module, 'last': _mod_result_last(module)})


def _diag_worker():
    try:
        report = _diag_collect()
        with _DIAG_LOCK:
            _DIAG_JOB.update(report=report, error=None,
                             generated_at=datetime.utcnow().strftime('%Y-%m-%dT%H:%M:%SZ'))
    except Exception as e:
        with _DIAG_LOCK:
            _DIAG_JOB['error'] = str(e)[:300]
    finally:
        with _DIAG_LOCK:
            _DIAG_JOB['running'] = False


def _diag_filename(generated_at):
    """infratak-diagnostics-<fqdn>-<UTC>.txt — the same name for the download and the attachment."""
    name = re.sub(r'[^A-Za-z0-9.-]', '_', load_settings().get('fqdn') or 'box')
    return f"infratak-diagnostics-{name}-{re.sub(r'[^0-9T]', '', generated_at or '')}.txt"


def _diag_build_email(to_addr, subject, report, filename):
    """The report in the body (readable on a phone with nothing to open) AND as a .txt
    attachment (easy to save and forward). `to_addr` must already be validated."""
    from email.mime.multipart import MIMEMultipart
    from email.mime.text import MIMEText
    relay = load_settings().get('email_relay') or {}
    from_addr = relay.get('from_addr') or 'noreply@localhost'
    msg = MIMEMultipart()
    msg['From'] = f"{relay.get('from_name') or 'infra-TAK'} <{from_addr}>"
    msg['To'] = to_addr
    msg['Subject'] = re.sub(r'[\r\n]+', ' ', subject)
    msg.attach(MIMEText(report, 'plain', 'utf-8'))
    part = MIMEText(report, 'plain', 'utf-8')
    part.add_header('Content-Disposition', 'attachment', filename=filename)
    msg.attach(part)
    return from_addr, msg


def _diag_send_email(to_addr, subject, report, filename):
    """Send through the Email Relay (localhost:25 → Postfix), the same path Guard Dog uses.
    Its own sender because _guarddog_send_alert_email_via_relay sends a body only, and Guard
    Dog's alert path is not changed by this feature (PLAN-v10.2.1 §2)."""
    import smtplib
    from_addr, msg = _diag_build_email(to_addr, subject, report, filename)
    with smtplib.SMTP('localhost', 25, timeout=30) as smtp:
        smtp.sendmail(from_addr, [to_addr], msg.as_string())


@app.route('/api/support/diagnostics/run', methods=['POST'])
@login_required
def support_diagnostics_run():
    with _DIAG_LOCK:
        if _DIAG_JOB['running']:
            return jsonify({'success': False, 'error': 'Diagnostics are already running'}), 409
        _DIAG_JOB.update(running=True, error=None)
    print('[diagnostics] report requested', flush=True)
    threading.Thread(target=_diag_worker, daemon=True).start()
    return jsonify({'success': True})


@app.route('/api/support/diagnostics/status')
@login_required
def support_diagnostics_status():
    with _DIAG_LOCK:
        return jsonify(dict(_DIAG_JOB))


@app.route('/api/support/diagnostics/download')
@login_required
def support_diagnostics_download():
    from flask import Response
    with _DIAG_LOCK:
        report, when = _DIAG_JOB['report'], _DIAG_JOB['generated_at']
    if not report:
        return jsonify({'success': False, 'error': 'Run diagnostics first'}), 404
    return Response(report, mimetype='text/plain', headers={
        'Content-Disposition': f'attachment; filename="{_diag_filename(when)}"'})


@app.route('/api/support/diagnostics/email', methods=['POST'])
@login_required
def support_diagnostics_email():
    raw = ((request.get_json(silent=True) or {}).get('to') or '').strip()
    # Exactly ONE address. _safe_alert_emails() splits on whitespace and commas, so
    # "a@b.com\r\nBcc: x@y.com" would quietly become two recipients; refuse instead.
    to = _safe_alert_email(raw)
    if not to or to != raw:
        return jsonify({'success': False, 'error': 'Enter one valid email address'}), 400
    settings = load_settings()
    relay = settings.get('email_relay') or {}
    if not (relay.get('relay_host') and relay.get('smtp_user')):
        return jsonify({'success': False, 'error': 'Email Relay is not configured on this box — use Download instead'}), 400
    with _DIAG_LOCK:
        report, when = _DIAG_JOB['report'], _DIAG_JOB['generated_at']
    if not report:
        return jsonify({'success': False, 'error': 'Run diagnostics first'}), 400
    subject = f"infra-TAK diagnostics — {settings.get('fqdn') or settings.get('server_ip') or 'box'} — v{VERSION}"
    try:
        _diag_send_email(to, subject, report, _diag_filename(when))
    except Exception as e:
        return jsonify({'success': False, 'error': f'Send failed: {str(e)[:200]}'}), 500
    print(f'[diagnostics] report emailed to {to}', flush=True)
    return jsonify({'success': True, 'message': f'Sent to {to}'})


def _update_check_response(data):
    """Return JSON response with no-cache headers so FQDN/proxy path never serves stale update badge."""
    from flask import make_response
    r = make_response(jsonify(data))
    r.headers['Cache-Control'] = 'no-store, no-cache, must-revalidate, max-age=0'
    r.headers['Pragma'] = 'no-cache'
    return r


def _github_release_notes_for_tag(tag_name: str) -> str:
    """Return human-readable update details for the dashboard Details panel.

    Prefer GitHub **Release** body (same tag). Tags-only releases return 404 — then link to
    docs/RELEASE-*.md and the tag URL on GitHub so operators always see something useful.
    """
    import urllib.request
    import urllib.error
    import urllib.parse
    if not tag_name or not tag_name.strip():
        return ''
    tag_name = tag_name.strip()
    base = f'https://github.com/{GITHUB_REPO}'
    doc_slug = tag_name if tag_name.startswith('v') else f'v{tag_name}'
    fallback = (
        f'Release notes (markdown in repo): {base}/blob/main/docs/RELEASE-{doc_slug}.md\n'
        f'Tag on GitHub: {base}/releases/tag/{urllib.parse.quote(tag_name)}'
    )
    try:
        url = f'https://api.github.com/repos/{GITHUB_REPO}/releases/tags/{urllib.parse.quote(tag_name)}'
        req = urllib.request.Request(
            url,
            headers={'Accept': 'application/vnd.github.v3+json', 'User-Agent': 'infra-TAK'}
        )
        with urllib.request.urlopen(req, timeout=6) as resp:
            data = json.loads(resp.read().decode())
        body = (data.get('body') or '').strip()
        if body:
            # Cap size for JSON/UI; panel scrolls but avoid huge payloads
            if len(body) > 12000:
                body = body[:12000].rstrip() + '\n\n… (truncated)'
            html_url = (data.get('html_url') or '').strip()
            extra = f'\n\n---\nOn GitHub: {html_url}' if html_url else ''
            return body + extra
    except urllib.error.HTTPError as e:
        if e.code != 404:
            return fallback + f'\n\n(Release API: HTTP {e.code})'
    except Exception:
        pass
    return fallback


@app.route('/api/update/channel', methods=['POST'])
@login_required
def set_update_channel():
    """Toggle the update channel between 'main' (stable releases) and 'dev' (dev branch head).

    Persisted in settings.json as update_channel. The update check and apply routes
    both respect this setting so the operator never has to SSH to switch tracks.

    Switching TO 'dev' requires the console password to be supplied in the request
    body as 'password' — prevents accidental channel changes by an operator who
    clicked the wrong button. Switching back to 'main' requires no password.
    """
    data = request.get_json(force=True) or {}
    channel = (data.get('channel') or 'main').strip().lower()
    if channel not in ('main', 'dev'):
        return jsonify({'ok': False, 'error': 'channel must be "main" or "dev"'}), 400
    if channel == 'dev':
        pw = (data.get('password') or '').strip()
        if not pw:
            return jsonify({'ok': False, 'error': 'password required to switch to dev channel', 'need_password': True}), 403
        auth = load_auth()
        if not auth.get('password_hash') or not check_password_hash(auth['password_hash'], pw):
            return jsonify({'ok': False, 'error': 'incorrect password', 'need_password': True}), 403
    s = load_settings()
    s['update_channel'] = channel
    save_settings(s)
    update_cache.update({'latest': None, 'checked': 0, 'notes': '', 'body': ''})
    return jsonify({'ok': True, 'channel': channel})


@app.route('/api/update/check')
@login_required
def update_check():
    import urllib.request
    now = time.time()
    def _parse_version_tuple(v):
        return tuple(int(p) for p in v.replace('-alpha','').replace('-beta','').split('.'))

    _settings = load_settings()
    _channel = (_settings.get('update_channel') or 'main').strip().lower()
    _on_dev = (_channel == 'dev')

    # Dev channel: compare current VERSION against the HEAD commit message on dev.
    # We report update_available when the dev branch HEAD SHA differs from the
    # currently running commit (i.e. there are new commits on dev we haven't pulled).
    if _on_dev:
        try:
            gh_headers = {'Accept': 'application/vnd.github.v3+json', 'User-Agent': 'infra-TAK'}
            dev_req = urllib.request.Request(
                f'https://api.github.com/repos/{GITHUB_REPO}/commits?sha=dev&per_page=1',
                headers=gh_headers
            )
            dev_resp = urllib.request.urlopen(dev_req, timeout=5)
            dev_data = json.loads(dev_resp.read().decode())
            if not dev_data:
                return _update_check_response({'current': VERSION, 'latest': None, 'channel': 'dev',
                    'error': 'No commits on dev', 'body': '', 'update_available': False,
                    'check_failed': True})
            head = dev_data[0]
            head_sha = head.get('sha', '')[:7]
            head_msg = (head.get('commit', {}).get('message', '') or '').splitlines()[0][:80]
            # Check local git HEAD to see if we're already at this commit
            try:
                _local_sha = subprocess.run(
                    ['git', f'--git-dir={os.path.join(os.path.dirname(os.path.abspath(__file__)), ".git")}',
                     'rev-parse', '--short', 'HEAD'],
                    capture_output=True, text=True, timeout=5
                ).stdout.strip()
            except Exception:
                _local_sha = ''
            _remote_full_sha = head.get('sha', '')
            _is_ahead = bool(_remote_full_sha) and not _remote_full_sha.startswith(_local_sha or 'XXXXXXXX')
            latest_label = f'dev@{head_sha}'
            notes = f'dev branch — {head_msg}'
            body = f'Latest commit on dev:\n{head_sha} — {head_msg}\n\nClick "Pull dev" to update to this commit.'
            update_cache.update({'latest': latest_label, 'checked': now, 'notes': notes, 'body': body})
            return _update_check_response({'current': VERSION, 'latest': latest_label, 'notes': notes,
                'body': body, 'channel': 'dev', 'update_available': _is_ahead})
        except Exception as e:
            # v10.1.40: check_failed distinguishes "I could not find out" from "there is
            # nothing new". Without it the UI's `else` branch printed "Up to date" over a
            # GitHub rate-limit (unauthenticated = 60/hour/IP, and the Guard Dog updates
            # watcher spends from the same bucket), a DNS blip or a 5s timeout — so a box
            # could stop seeing console updates for an hour and say it was current.
            return _update_check_response({'current': VERSION, 'latest': None, 'channel': 'dev',
                'error': str(e)[:200], 'body': '', 'update_available': False,
                'check_failed': True})

    # Main channel: existing tag-based check.
    force = request.args.get('refresh') == '1'
    if not force and update_cache['latest'] and (now - update_cache['checked']) < 600:
        try:
            cached_newer = _parse_version_tuple(update_cache['latest']) > _parse_version_tuple(VERSION)
            if update_cache['latest'].strip() == VERSION.strip():
                cached_newer = False
        except (ValueError, IndexError):
            cached_newer = False
        return _update_check_response({'current': VERSION, 'latest': update_cache['latest'], 'notes': update_cache['notes'],
            'body': update_cache.get('body') or '', 'channel': 'main',
            'update_available': cached_newer})
    try:
        gh_headers = {'Accept': 'application/vnd.github.v3+json', 'User-Agent': 'infra-TAK'}
        req = urllib.request.Request(
            f'https://api.github.com/repos/{GITHUB_REPO}/tags',
            headers=gh_headers
        )
        resp = urllib.request.urlopen(req, timeout=5)
        data = json.loads(resp.read().decode())
        if not data:
            return _update_check_response({'current': VERSION, 'latest': None, 'channel': 'main', 'error': 'No tags found', 'body': '', 'update_available': False, 'check_failed': True})
        # Only surface tags that are actually on the main branch so that tags
        # pushed on dev before a merge-to-main don't show as "update available".
        try:
            main_req = urllib.request.Request(
                f'https://api.github.com/repos/{GITHUB_REPO}/commits?sha=main&per_page=100',
                headers=gh_headers
            )
            main_resp = urllib.request.urlopen(main_req, timeout=5)
            main_commits = {c['sha'] for c in json.loads(main_resp.read().decode())}
        except Exception:
            main_commits = None  # fall back: don't filter if we can't reach main
        versions = []
        for tag in data:
            if main_commits is not None and tag.get('commit', {}).get('sha') not in main_commits:
                continue
            name = tag.get('name', '').lstrip('v').replace('-alpha','').replace('-beta','')
            parts = name.split('.')
            try:
                versions.append((tuple(int(p) for p in parts), tag))
            except (ValueError, IndexError):
                continue
        if not versions:
            return _update_check_response({'current': VERSION, 'latest': None, 'channel': 'main', 'error': 'No version tags', 'body': '', 'update_available': False, 'check_failed': True})
        versions.sort(key=lambda x: x[0], reverse=True)
        latest_tag = versions[0][1]
        latest = latest_tag.get('name', '').lstrip('v')
        try:
            latest_tuple = _parse_version_tuple(latest)
            current_tuple = _parse_version_tuple(VERSION)
            is_newer = latest_tuple > current_tuple
        except (ValueError, IndexError):
            is_newer = False
        # Never show "update available" when current and latest are the same (avoid stale badge after update)
        if latest.strip() == VERSION.strip():
            is_newer = False
        notes = f"Version {latest_tag.get('name', '')}"
        tag_full = (latest_tag.get('name') or '').strip()
        body = _github_release_notes_for_tag(tag_full) if is_newer else ''
        update_cache.update({'latest': latest, 'checked': now, 'notes': notes, 'body': body})
        return _update_check_response({'current': VERSION, 'latest': latest, 'notes': notes, 'body': body,
            'channel': 'main', 'update_available': is_newer})
    except Exception as e:
        return _update_check_response({'current': VERSION, 'latest': None, 'channel': 'main', 'error': str(e)[:200], 'body': '', 'update_available': False, 'check_failed': True})

def _fetch_latest_tag_name():
    """Return the latest release tag name (e.g. 'v0.2.3-alpha') from GitHub, or None on error."""
    import urllib.request
    try:
        req = urllib.request.Request(
            f'https://api.github.com/repos/{GITHUB_REPO}/tags',
            headers={'Accept': 'application/vnd.github.v3+json', 'User-Agent': 'infra-TAK'}
        )
        resp = urllib.request.urlopen(req, timeout=5)
        data = json.loads(resp.read().decode())
        if not data:
            return None
        versions = []
        for tag in data:
            name = tag.get('name', '').lstrip('v').replace('-alpha', '').replace('-beta', '')
            parts = name.split('.')
            try:
                versions.append((tuple(int(p) for p in parts), tag.get('name', '')))
            except (ValueError, IndexError):
                continue
        if not versions:
            return None
        versions.sort(key=lambda x: x[0], reverse=True)
        return versions[0][1]  # full tag name e.g. v0.2.3-alpha
    except Exception:
        return None


def _repo_ownership_selfheal(trigger=''):
    """v10.1.4 WS13: heal foreign-owned entries inside the console repo.

    Root-shell git operations (or root-era start.sh runs) leave files/dirs in
    the takwerx-owned repo owned by root. git-as-takwerx then cannot unlink
    files inside root-owned dirs, so Update Now HALF-APPLIES: HEAD moves, the
    blocked files keep OLD content ("error: unable to unlink old '…':
    Permission denied"), and the box silently runs mixed versions (test8
    2026-07-18: broker/takwerx_broker.py + nodered/flows.json stayed at 10.1.3
    under a 10.1.4 HEAD — with the WS8 broker fix in the stale file).

    Detects entries whose owner differs from the console user (including
    .git/ — root-era fetches leave root-owned pack files that break future
    gc/fetch) and re-owns the whole install dir via the broker (`chown -R -h`,
    exact shape carved out in the broker rulebook; permissive legacy daemons
    execute it too, which is what un-wedges a box whose NEW broker source is
    itself one of the blocked files). No-op as root — a root-owned repo is the
    correct state on root-era boxes.

    Returns the offending repo-relative paths found BEFORE the chown; the
    startup caller uses them to restore torn file content afterwards."""
    if os.getuid() == 0:
        return []
    repo = os.path.dirname(os.path.abspath(__file__))
    uid = os.getuid()
    offenders = []
    try:
        for dirpath, dirnames, filenames in os.walk(repo):
            for name in dirnames + filenames:
                p = os.path.join(dirpath, name)
                try:
                    if os.lstat(p).st_uid != uid:
                        offenders.append(os.path.relpath(p, repo))
                except OSError:
                    continue
    except Exception as e:
        print(f"repo ownership heal ({trigger}): scan failed (non-fatal): {e}", flush=True)
        return []
    if not offenders:
        return []
    import pwd as _pwd
    import grp as _grp
    try:
        user = _pwd.getpwuid(uid).pw_name
        group = _grp.getgrgid(os.getgid()).gr_name
    except Exception:
        user, group = str(uid), str(os.getgid())
    print(f"repo ownership heal ({trigger}): {len(offenders)} foreign-owned entr(y/ies) "
          f"(e.g. {', '.join(offenders[:4])}) — re-owning {repo} to {user}:{group}", flush=True)
    try:
        r = subprocess.run(
            _sudo_wrap(['chown', '-R', '-h', f'{user}:{group}', repo]),
            capture_output=True, text=True, timeout=180)
        if r.returncode != 0:
            print(f"repo ownership heal ({trigger}): chown FAILED (rc={r.returncode}): "
                  f"{(r.stderr or r.stdout or '').strip()[:300]}", flush=True)
            return []
        print(f"repo ownership heal ({trigger}): ✓ repo re-owned to {user}:{group}", flush=True)
    except Exception as e:
        print(f"repo ownership heal ({trigger}): chown error (non-fatal): {e}", flush=True)
        return []
    return offenders


@app.route('/api/update/apply', methods=['POST'])
@login_required
def update_apply():
    # v10.1.29 (W10): free-space preflight, deliberately BEFORE the single-flight
    # lock is written so a refused update does not sit on the 20-minute lock.
    #
    # Verified 2026-08-10: nothing in this path checked free space. On a nearly
    # full box `git fetch` + `git checkout --force` fail with "No space left on
    # device" and can leave a half-applied tree — the "wrong version / failed
    # Update Now" state the README's universal-recovery section exists to clean
    # up. It is also why a full box cannot self-rescue: the release that adds
    # Purge Old CoT cannot be installed without the free space Purge recovers.
    # Same class of guard as the VACUUM FULL preflight: refuse legibly instead of
    # letting the underlying tool emit ENOSPC.
    _update_min_free = 1024 ** 3
    try:
        _st = os.statvfs(os.path.dirname(os.path.abspath(__file__)))
        _free_b = _st.f_bavail * _st.f_frsize
    except Exception:
        _free_b = None
    if _free_b is not None and _free_b < _update_min_free:
        return jsonify({
            'success': False,
            'needed_bytes': _update_min_free,
            'free_bytes': _free_b,
            'error': (f'Update Now needs ~1 GB free to fetch and check out; this filesystem '
                      f'has {_free_b // (1024 * 1024)} MB. Free disk first — see Guard Dog '
                      '> Database maintenance (CoT) > Diagnose.'),
        }), 400

    # v0.9.24 Item 1: Update Now single-flight lock.
    # Field incident on test8 (2026-05-16): operator double-clicked "Update Now"
    # from two browser tabs. Both POSTs to /api/update/apply ran concurrently
    # in the same console process, both did git fetch+checkout, both scheduled
    # `systemctl restart takwerx-console`. The second restart fired ~2s after
    # the first and killed the first deploy mid-bootstrap. Docker `restart:
    # unless-stopped` does NOT restart explicitly stopped containers, so
    # tak-portal and mediamtx ended up in `Exited` state for 12+ minutes until
    # operator manual recovery.
    #
    # The lock is a timestamped file at /var/lib/takwerx-console/update-now.lock.
    # Lifecycle:
    #   - written at the top of this endpoint
    #   - cleared at the end of _post_update_auto_deploy (in _run_post_update_guarded
    #     finally block, AND in the no-op early-return path)
    #   - 20-min TTL covers the rare case where a deploy crashes without clearing it
    #
    # Item 2 below (post-update service recovery sweep) is the belt to this fix's
    # suspenders — if anything still gets stopped mid-deploy, the sweep brings it back.
    _update_lock = '/var/lib/takwerx-console/update-now.lock'
    _update_lock_ttl_s = 1200
    try:
        os.makedirs(os.path.dirname(_update_lock), exist_ok=True)
        if os.path.exists(_update_lock):
            _age = int(time.time() - os.path.getmtime(_update_lock))
            if _age < _update_lock_ttl_s:
                _lock_info = ''
                try:
                    with open(_update_lock) as _lf:
                        _lock_info = _lf.read().strip()
                except Exception:
                    pass
                return jsonify({
                    'success': False,
                    'in_progress': True,
                    'started_seconds_ago': _age,
                    'error': (
                        f'Update Now is already in progress (started ~{_age}s ago). '
                        f'The console will restart automatically when complete — '
                        f'wait 1–3 minutes then refresh this page. Avoid clicking '
                        f'Update Now in multiple browser tabs.'
                    ),
                    'lock_info': _lock_info or None,
                }), 409
            print(f"Update Now: clearing stale lock (age={_age}s ≥ TTL={_update_lock_ttl_s}s)", flush=True)
        with open(_update_lock, 'w') as _lf:
            _lf.write(
                f"version={VERSION}\n"
                f"started_utc={datetime.utcnow().strftime('%Y-%m-%dT%H:%M:%SZ')}\n"
                f"pid={os.getpid()}\n"
            )
    except Exception as _le:
        # Lock-file IO failure is non-blocking. Single-flight is an availability
        # optimization, not a correctness guarantee; we'd rather a degraded
        # double-deploy than a wedged Update Now button on a misconfigured box.
        print(f"Update Now: lock-file IO error (non-blocking, continuing): {_le}", flush=True)

    console_dir = os.path.dirname(os.path.abspath(__file__))
    git_env = {'GIT_TERMINAL_PROMPT': '0'}
    git_cfg = ['git', '-c', f'safe.directory={console_dir}']
    # Ensure git works on repos owned by other users (e.g. takwerx-owned
    # ~/TAK-Portal and ~/CloudTAK when the console process HOME differs from
    # the repo owner). --system writes to /etc/gitconfig — applies to every
    # user on the machine, which is correct for a single-tenant server.
    subprocess.run(
        ['git', 'config', '--system', '--replace-all', 'safe.directory', '*'],
        capture_output=True, timeout=5
    )
    # Empty remote.origin.fetch: explicit refspecs are *additive* with defaults; without this,
    # `git fetch origin +refs/tags/foo:refs/tags/foo` still updates heads/tags per origin.fetch
    # and can hit "would clobber existing tag" on field installs.
    git_cfg_fetch_isolated = git_cfg + ['-c', 'remote.origin.fetch=']

    def _git(args, timeout=60, isolated_fetch=False):
        prefix = git_cfg_fetch_isolated if isolated_fetch else git_cfg
        return subprocess.run(
            prefix + args,
            cwd=console_dir,
            capture_output=True,
            text=True,
            timeout=timeout,
            env={**os.environ, **git_env}
        )

    def _git_err(r):
        return (r.stderr or '').strip() or (r.stdout or '').strip() or 'git command failed'

    def _error_payload(err):
        out = {'success': False, 'error': err}
        if 'dubious ownership' in err.lower() or 'safe.directory' in err.lower():
            out['workaround'] = f'On the server run: sudo git config --global --add safe.directory {console_dir}'
        return out

    def _fail_release_lock(payload):
        # An error return must release the single-flight lock. Leaving it behind turns
        # one failed attempt into a 20-minute outage: every retry 409s with "already in
        # progress" until the TTL expires (test12, 2026-07-17 — a rejected fetch left the
        # lock, so Update Now looked wedged even after the git issue itself was fixed).
        # Success paths deliberately keep the lock; _post_update_auto_deploy clears it.
        try:
            os.remove(_update_lock)
        except Exception:
            pass
        return jsonify(payload)

    # v0.9.3: Record current version for one-step rollback before updating
    try:
        _pre_update_version = VERSION
        _s = load_settings()
        # Determine the current git tag so rollback can fetch it
        _cur_tag_r = subprocess.run(
            ['git', f'--git-dir={os.path.join(console_dir, ".git")}',
             f'--work-tree={console_dir}', 'describe', '--tags', '--exact-match'],
            capture_output=True, text=True, timeout=10
        )
        _cur_tag = (_cur_tag_r.stdout or '').strip() if _cur_tag_r.returncode == 0 else f'v{VERSION}'
        _s['console_rollback'] = {
            'available':   True,
            'version':     VERSION,
            'tag':         _cur_tag,
            'snapshot_at': datetime.utcnow().strftime('%Y-%m-%dT%H:%M:%SZ'),
        }
        save_settings(_s)
    except Exception:
        pass

    _apply_settings = load_settings()
    _apply_channel = (_apply_settings.get('update_channel') or 'main').strip().lower()
    _apply_dev = (_apply_channel == 'dev')

    try:
        # Never use pull --rebase in Update Now.
        # Field installs can be detached/tagged or have stale rebase metadata; rebase causes customer-facing conflicts.
        for abort_args in (['rebase', '--abort'], ['merge', '--abort'], ['cherry-pick', '--abort']):
            try:
                _git(abort_args, timeout=15)
            except Exception:
                pass

        if _apply_dev:
            # Dev channel: fetch origin/dev HEAD and check it out directly.
            # The leading '+' forces the tracking-ref update: without it, a box that fetched
            # dev before a history rewrite (force-push) is permanently wedged with
            # "[rejected] dev -> origin/dev (non-fast-forward)" — Update Now can never
            # recover on its own (test12, 2026-07-16). Forcing mirrors the default refspec
            # (+refs/heads/*) and is safe: the checkout below is already --force.
            fetch_dev = _git(
                ['fetch', 'origin', '+dev:refs/remotes/origin/dev'], timeout=60, isolated_fetch=True
            )
            if fetch_dev.returncode != 0:
                return _fail_release_lock(_error_payload(_git_err(fetch_dev)))
            target_ref = 'refs/remotes/origin/dev'
            target_label = 'origin/dev'
        else:
            # Main channel: resolve latest tag from GitHub API, then fetch ONLY that tag (+ = update
            # local tag if it moved). Bulk `git fetch --tags` fails on many field installs: local
            # v0.3.8-alpha etc. can differ from origin ("would clobber existing tag") even when the
            # operator only wants the newest release.
            tag_name = _fetch_latest_tag_name()
            target_ref = None
            if tag_name:
                refspec = f'+refs/tags/{tag_name}:refs/tags/{tag_name}'
                fetch_tag = _git(['fetch', 'origin', refspec], timeout=120, isolated_fetch=True)
                if fetch_tag.returncode != 0:
                    return _fail_release_lock(_error_payload(_git_err(fetch_tag)))
                verify_tag = _git(['rev-parse', '-q', '--verify', f'refs/tags/{tag_name}'], timeout=15)
                if verify_tag.returncode == 0:
                    target_ref = f'refs/tags/{tag_name}'

            # Fallback: track origin/main if tag lookup fails.
            if not target_ref:
                fetch_main = _git(
                    ['fetch', 'origin', '+main:refs/remotes/origin/main'], timeout=30, isolated_fetch=True
                )
                if fetch_main.returncode != 0:
                    return _fail_release_lock(_error_payload(_git_err(fetch_main)))
                target_ref = 'refs/remotes/origin/main'
            target_label = tag_name or 'origin/main'

        # v10.1.4 WS13: heal foreign-owned repo entries BEFORE the checkout — a
        # past root-shell git op leaves root-owned dirs that make the checkout
        # below half-apply ("unable to unlink old '…': Permission denied" while
        # HEAD still moves → box runs mixed versions).
        _repo_ownership_selfheal('update-apply')

        checkout = _git(['checkout', '--force', target_ref], timeout=30)
        if checkout.returncode != 0 and 'unable to unlink' in _git_err(checkout).lower():
            # Ownership poisoning surfaced mid-checkout (pre-checkout heal missed
            # or could not complete — e.g. broker briefly unreachable). Heal and
            # retry ONCE so a single Update Now click still converges.
            _repo_ownership_selfheal('update-apply-retry')
            checkout = _git(['checkout', '--force', target_ref], timeout=30)
        if checkout.returncode != 0:
            err = _git_err(checkout)
            payload = _error_payload(err)
            if 'unable to unlink' in err.lower():
                # WS13: never show a customer raw git stderr with no next step.
                # HEAD has moved and the new app.py is staged; the startup heal
                # completes the rest on the next boot — tell them exactly that.
                payload['error'] = (
                    'Update staged, but some files are still locked by root ownership '
                    'from an earlier operation on this server. Click the Reboot button — '
                    'the console repairs ownership and completes this update automatically '
                    'during startup. No command line needed.'
                )
                payload['detail'] = err[:400]
            return _fail_release_lock(payload)

        update_cache.update({'latest': None, 'checked': 0, 'notes': '', 'body': ''})
        _ensure_gunicorn_upgrade(console_dir)
        _detached_console_restart()
        return jsonify({
            'success': True,
            'output': f'Updated to {target_label}',
            'restart_required': True,
            'restart_message': 'Console is restarting. You may see 502 briefly — wait 10–15 seconds then refresh the page.'
        })
    except Exception as e:
        return _fail_release_lock({'success': False, 'error': str(e)[:200]})

# Issue #113: the daily restart's idle gate — what counts as "busy".
# A module record left `running` longer than this is a thread that died without
# finishing, not work in flight; past it the record stops holding the restart off.
_RESTART_GATE_RECORD_MAX_S = 3 * 3600


def _console_busy_reason():
    """Why the daily console restart must wait, or None when the console is idle.

    The original gate only looked at app.py's own `*_status` globals. Module
    files keep their job state in their own namespaces (the registry's _JOBS,
    ATLAS's per-deployment update/removal slots, TVR's and the simulator's
    status dicts), so a running ATLAS update read as idle and the 04:00 restart
    killed its `docker compose up` mid-recreate (#113). Every module operation
    gets the same look now, plus the persisted module-results record as a
    backstop for anything that ran through _mod_result_start().
    """
    # 1) Update Now lock — file-based, set at the top of the Update Now endpoint
    #    (20-min TTL), so it survives even if the worker handling it is wedged.
    try:
        _lock = '/var/lib/takwerx-console/update-now.lock'
        if os.path.exists(_lock):
            _age = int(time.time() - os.path.getmtime(_lock))
            if _age < 1200:
                return f'Update Now in progress (~{_age}s ago)'
    except Exception:
        pass
    # 2) Any in-memory *_status dict reporting a running operation. Scanned
    #    dynamically so new deploy-status globals are covered automatically.
    try:
        for _name, _val in list(globals().items()):
            if _name.endswith('_status') and isinstance(_val, dict) and _val.get('running'):
                return f'{_name} running'
    except Exception:
        pass
    # 3) Module registry jobs (deploy / uninstall through modules/__init__.py).
    try:
        _jobs = mod_registry.running_jobs()
        if _jobs:
            return f"module {', '.join(sorted(_jobs))} running"
    except Exception:
        pass
    # 4) Module files' own state, scanned the same way as (2): a `*_status` dict
    #    that is running, or a `*_slots` dict holding one (ATLAS keeps one slot
    #    per deployment for updates and another for removals).
    try:
        for _mname, _mod in list(_sys.modules.items()):
            if not _mname.startswith('modules.') or _mod is None:
                continue
            for _name, _val in list(vars(_mod).items()):
                if not isinstance(_val, dict):
                    continue
                if _name.endswith('_status') and _val.get('running'):
                    return f"{_mname.split('.', 1)[1]} {_name} running"
                if _name.endswith('_slots'):
                    for _key, _slot in list(_val.items()):
                        if isinstance(_slot, dict) and _slot.get('running'):
                            return f"{_mname.split('.', 1)[1]} {_name}[{_key}] running"
    except Exception:
        pass
    # 5) A module-results record still `running`. This process marked every
    #    leftover one interrupted when it started, so a live one is in flight.
    try:
        _now = datetime.utcnow()
        for _module, _m in sorted(_mod_results_load().items()):
            _last = (_m or {}).get('last') or {}
            if _last.get('outcome') != 'running':
                continue
            try:
                _age = (_now - datetime.strptime(_last.get('started_at') or '',
                                                 '%Y-%m-%dT%H:%M:%SZ')).total_seconds()
            except ValueError:
                continue   # never let a malformed record hold the restart off forever
            if _age < _RESTART_GATE_RECORD_MAX_S:
                return f"{_module} {_last.get('kind') or 'operation'} running"
    except Exception:
        pass
    return None


@app.route('/api/console/restart-safe')
def console_restart_safe():
    """v0.9.44: localhost-only readiness probe for the daily console-restart
    timer (tak-console-restart.sh). Returns {"safe": bool, "reason": str|null}.

    safe=False when any deploy/update operation is in flight, so the timer
    defers the restart instead of killing a mid-flight deploy. Not session/
    browser driven (mirrors the localhost-only Guard Dog script endpoints), so
    it carries no @login_required — but it is restricted to loopback callers.
    """
    if (request.remote_addr or '') not in ('127.0.0.1', '::1', 'localhost'):
        return jsonify({'error': 'forbidden'}), 403

    busy = _console_busy_reason()
    return jsonify({'safe': busy is None, 'reason': busy})


@app.route('/api/console/power', methods=['POST'])
@login_required
def console_power_api():
    """Power off / reboot the box from the console (no SSH). Destructive and
    outward-facing — poweroff needs a physical power-on to return — so it
    re-confirms the console password (mirrors the dev-channel-switch gate) ON TOP
    of @login_required, so it can't be an accidental click. Runs the systemctl
    verb through the broker (verb-gated: poweroff + reboot are allowlisted),
    detached so the HTTP response returns before the box goes down."""
    data = request.get_json(silent=True) or {}
    action = (data.get('action') or '').strip()
    password = data.get('password') or ''
    if action not in ('poweroff', 'reboot'):
        return jsonify({'success': False, 'error': 'action must be "poweroff" or "reboot".'}), 400
    auth = load_auth()
    if not auth.get('password_hash') or not check_password_hash(auth['password_hash'], password):
        return jsonify({'success': False, 'error': 'Incorrect console password.', 'need_password': True}), 403
    _detached_power_action(action, delay=2)
    return jsonify({'success': True, 'action': action})


_CONSOLE_UNIT = '/etc/systemd/system/takwerx-console.service'


def _broker_force_enabled_in_unit():
    """True if TAKWERX_FORCE_BROKER=1 is set in the console's systemd unit."""
    try:
        with open(_CONSOLE_UNIT) as f:
            return 'TAKWERX_FORCE_BROKER=1' in f.read()
    except OSError:
        return False


def _broker_service_active():
    try:
        r = subprocess.run(['systemctl', 'is-active', 'takwerx-broker'],
                           capture_output=True, text=True, timeout=8)
        return r.stdout.strip() == 'active'
    except Exception:
        return False


def _broker_status_dict():
    enforce = None
    enforce_info = {}
    deny_count = None
    readiness = {}
    try:
        if _broker_available():
            pong = _broker_request({'op': 'ping'}, timeout=5)
            enforce = bool(pong.get('enforce'))
            enforce_info = pong.get('enforce_info') or {}
            deny_count = pong.get('deny_count')
            readiness = pong.get('readiness') or {}
    except Exception:
        pass
    return {
        'installed': os.path.exists(_BROKER_SCRIPT) and os.path.exists('/etc/systemd/system/takwerx-broker.service'),
        'service_active': _broker_service_active(),
        'socket_present': _broker_available(),
        'routing_active': _broker_should_route(),
        'force_enabled': _broker_force_enabled_in_unit(),
        'enforce': enforce,   # None=unknown, False=permissive (watch), True=enforcing
        # v10.0.8: how the mode was decided, the stay-permissive reason, denials
        # since start, and opt-in readiness (opted_in / ready / clean_since /
        # reason) so the card can render the "Turn on enforcing" flow.
        'enforce_info': enforce_info,
        'deny_count': deny_count,
        'readiness': readiness,
        'console_uid': os.getuid(),
        'audit_log': '/var/log/takwerx-broker/audit.log',
        'socket': BROKER_SOCKET,
    }


@app.route('/api/console/broker/status')
@login_required
def console_broker_status():
    """v10.0.5: status for the 'Least-Privilege Console' Cyber Control card."""
    return jsonify(_broker_status_dict())


@app.route('/api/console/broker/selftest')
@login_required
def console_broker_selftest():
    """v10.0.5: prove the privileged broker works end-to-end. Talks to the broker
    DIRECTLY (via _broker_request), so it is valid whether or not the console is
    currently routing through it — clicking "Run self-test" needs no restart.
    When routing IS active, an extra check exercises the console's own helpers."""
    checks = []

    def add(name, ok, detail='', level=None):
        checks.append({'name': name, 'ok': bool(ok),
                       'level': level or ('pass' if ok else 'fail'),
                       'detail': str(detail)[:300]})

    info = _broker_status_dict()
    if not _broker_available():
        return jsonify({'ok': False, 'info': info,
                        'error': 'broker socket not present — is takwerx-broker.service running?'}), 503

    # 1. ping — the guard answers
    try:
        r = _broker_request({'op': 'ping'})
        add('Guard responds (ping)', r.get('ok') and r.get('pong'), r)
    except Exception as e:
        add('Guard responds (ping)', False, e)

    # 2. allowed write+read round-trip (broker's own log dir always exists)
    probe = '/var/log/takwerx-broker/.selftest'
    try:
        import base64 as _bb
        w = _broker_request({'op': 'write', 'path': probe,
                             'content_b64': _bb.b64encode(b'broker-ok').decode()})
        rd = _broker_request({'op': 'read', 'path': probe})
        got = _bb.b64decode(rd.get('content_b64') or '') if rd.get('ok') else b''
        add('Allowed write + read', w.get('ok') and got == b'broker-ok')
        _broker_request({'op': 'exec', 'argv': ['rm', '-f', probe]})
    except Exception as e:
        add('Allowed write + read', False, e)

    # 3. allowed exec returns output
    try:
        r = _broker_request({'op': 'exec', 'argv': ['systemctl', '--version']})
        out = ''
        if r.get('ok'):
            import base64 as _bb
            out = _bb.b64decode(r.get('stdout_b64') or '').decode(errors='replace')
        add('Allowed command runs', r.get('ok') and r.get('returncode') == 0 and 'systemd' in out)
    except Exception as e:
        add('Allowed command runs', False, e)

    # 4. rulebook would DENY a sudoers write (dry-run verdict — NB this proves the
    #    rulebook's answer, NOT that the console is confined to it; see capstone).
    try:
        r = _broker_request({'op': 'check', 'req': {'op': 'write', 'path': '/etc/sudoers.d/takwerx-evil'}})
        add('Rulebook denies sudoers write (dry-run)', r.get('ok') and r.get('verdict') == 'DENY', r.get('reason'))
    except Exception as e:
        add('Rulebook denies sudoers write (dry-run)', False, e)

    # 5. rulebook would DENY arbitrary shell (dry-run verdict)
    try:
        r = _broker_request({'op': 'check', 'req': {'op': 'exec', 'argv': ['bash', '-c', 'id']}})
        add('Rulebook denies arbitrary shell (dry-run)', r.get('ok') and r.get('verdict') == 'DENY', r.get('reason'))
    except Exception as e:
        add('Rulebook denies arbitrary shell (dry-run)', False, e)

    # 6. when routing is on, prove the console's OWN helpers go through the broker
    if _broker_should_route():
        try:
            _write_priv(probe, 'via-helpers\n')
            back = _read_priv(probe)
            add('Console routes through guard', back.strip() == 'via-helpers')
            _broker_request({'op': 'exec', 'argv': ['rm', '-f', probe]})
        except Exception as e:
            add('Console routes through guard', False, e)

    # Up to here the checks prove the guard MECHANICALLY works. Whether it is an
    # actual ENFORCED privilege boundary depends on two more things the panel must
    # not hide: the console must run NON-ROOT (else it bypasses the guard directly)
    # AND the broker must be ENFORCING (permissive only logs would-deny). State that
    # honestly — a security reviewer reads this panel.
    functional_ok = all(c['ok'] for c in checks)
    console_root = (info.get('console_uid') == 0)
    enforce = info.get('enforce')  # True=enforcing, False=permissive, None=unknown
    # The boundary EXISTS iff the console is NON-ROOT: it then physically cannot make
    # privileged changes except through the guard. Enforce mode is a STRICTNESS level
    # (active deny vs learning-mode logging), not whether a boundary exists — fresh
    # installs ship non-root + permissive, which is the intended locked-down state. So
    # non-root passes; only a still-root console is flagged.
    boundary = not console_root
    if console_root:
        add('Console is confined to the guard', False, level='warn',
            detail='NO — the console runs as ROOT (uid 0): it can make privileged '
                   'changes directly, bypassing the guard, which only records them. '
                   'Switch the console to non-root (automatic on fresh installs; the '
                   'on-box migration for an existing root box) to make it a boundary.')
    else:
        note = ('YES — the console runs unprivileged; it cannot make privileged '
                'changes except through the guard.')
        if enforce is False:
            note += ' Rulebook is in learning mode (permissive) — enforce mode adds active blocking.'
        elif enforce is True:
            note += ' Rulebook is enforcing.'
        add('Console is confined to the guard', True, detail=note)
    overall = 'pass' if (functional_ok and boundary) else ('warn' if functional_ok else 'fail')
    return jsonify({'ok': functional_ok and boundary, 'overall': overall,
                    'functional_ok': functional_ok, 'boundary': boundary,
                    'console_root': console_root, 'enforce': enforce,
                    'info': info, 'checks': checks})


@app.route('/api/console/broker/routing', methods=['POST'])
@login_required
def console_broker_routing():
    """v10.0.5: enable/disable least-privilege routing by toggling
    TAKWERX_FORCE_BROKER=1 in the console's systemd unit, then restarting the
    console. SAFE: the console keeps running as root either way — this only
    decides whether its privileged calls go THROUGH the guard. It does NOT flip
    the console to a non-root user (that stays gated on the rulebook hardening)."""
    data = request.get_json(silent=True) or {}
    enable = bool(data.get('enable'))

    if enable and not _broker_available():
        return jsonify({'success': False,
                        'error': 'Broker is not running — cannot enable routing. Check: systemctl status takwerx-broker'}), 400

    try:
        unit = ''
        if os.path.exists(_CONSOLE_UNIT):
            try:
                unit = _read_priv(_CONSOLE_UNIT)   # v10.0.5 non-root: read via broker
            except Exception:
                unit = ''
        lines = [ln for ln in unit.splitlines()
                 if 'TAKWERX_FORCE_BROKER' not in ln]
        if enable:
            # insert under [Service] (after the line that opens it)
            out = []
            inserted = False
            for ln in lines:
                out.append(ln)
                if ln.strip() == '[Service]' and not inserted:
                    out.append('Environment=TAKWERX_FORCE_BROKER=1')
                    inserted = True
            if not inserted:   # no [Service] header found — append safely
                out.append('Environment=TAKWERX_FORCE_BROKER=1')
            unit = '\n'.join(out) + '\n'
        else:
            unit = '\n'.join(lines) + '\n'
        _write_priv(_CONSOLE_UNIT, unit)   # v10.0.5 non-root: /etc/systemd/system root-owned
        subprocess.run(_sudo_wrap(['systemctl', 'daemon-reload']), capture_output=True, timeout=15)
        # persist intent so a future start.sh re-run can honor it (P1 wiring)
        try:
            _s = load_settings()
            _s['broker_force_routing'] = enable
            save_settings(_s)
        except Exception:
            pass
        # detached delayed restart (same pattern as Update Now) so this response returns first
        _detached_console_restart()
        return jsonify({
            'success': True,
            'enabled': enable,
            'restart_required': True,
            'restart_message': 'Console is restarting to apply the change. You may see a brief 502 — wait ~15 seconds, then refresh.'
        })
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/console/broker/enforce', methods=['POST'])
@login_required
def console_broker_enforce():
    """v10.0.8: OPT IN to enforcement (deliberate — the box never flips on its own).
    Calls the broker `enforce_enable` op (a ratchet: it only ever CREATES the
    root-owned opt-in marker, never removes it), then restarts the broker so it
    re-evaluates. The broker enforces ONLY once its 72h audit window is clean;
    until then it reports 'enabled — waiting for clean window'. Turning enforcement
    back OFF is intentionally NOT exposed here — that is the SSH-only break-glass
    kill switch (Environment=TAKWERX_BROKER_ENFORCE=0), so a compromised console can
    only ever make the box MORE locked down."""
    if not _broker_available():
        return jsonify({'success': False,
                        'error': 'Guard is not running — cannot enable enforcement. Check: systemctl status takwerx-broker'}), 400
    try:
        resp = _broker_request({'op': 'enforce_enable'}, timeout=15)
    except Exception as e:
        return jsonify({'success': False, 'error': f'could not reach the guard: {e}'}), 500
    if not resp.get('ok'):
        return jsonify({'success': False, 'error': resp.get('error') or 'guard refused the request'}), 500
    # Restart the broker so _resolve_enforce re-runs with the marker present.
    try:
        subprocess.run(_sudo_wrap(['systemctl', 'restart', 'takwerx-broker']), capture_output=True, timeout=20)
    except Exception:
        pass
    return jsonify({
        'success': True,
        'opted_in': True,
        'ready': bool(resp.get('ready')),
        'message': resp.get('note') or 'Enforcement enabled.',
    })


_NONROOT_MIGRATE_UNIT = 'infratak-nonroot-migrate'
_NONROOT_MIGRATE_STATUS = '/var/lib/infratak-nonroot-migrate.status'
_NONROOT_MIGRATE_LOG = '/var/log/takwerx-console-nonroot-migrate.log'


@app.route('/api/console/migrate-nonroot', methods=['POST'])
@login_required
def console_migrate_nonroot_api():
    """v10.0.5: flip a legacy ROOT console to the unprivileged takwerx user FROM THE
    BROWSER (no CLI — the whole infra-TAK premise), wrapping
    scripts/migrate-console-nonroot.sh --apply --auto-rollback. The migration
    restarts/replaces the console process, so it MUST run DETACHED in its own cgroup
    (systemd-run) to survive — same pattern as the kernel-patch job. The console is
    ALREADY root here (the button only shows on a root console), so this is a
    root->non-root provisioning step, NOT a privilege escalation; the script path is
    fixed (no request input reaches the command). --auto-rollback restores the root
    unit if the flip fails, so a botched migration cannot lock the operator out."""
    if os.getuid() != 0:
        return jsonify({'success': False, 'error': 'Console already runs non-root — nothing to migrate.'}), 400
    if not (os.path.exists('/usr/bin/systemd-run') or os.path.exists('/bin/systemd-run')):
        return jsonify({'success': False, 'error': 'systemd-run not found — cannot run the migration safely.'}), 500
    install_dir = os.path.dirname(os.path.abspath(__file__))
    script = os.path.join(install_dir, 'scripts', 'migrate-console-nonroot.sh')
    if not os.path.exists(script):
        return jsonify({'success': False, 'error': f'migration script not found at {script}'}), 500
    # Refuse if a migration is already in flight (fixed unit name → one at a time);
    # avoids a confusing "unit already exists" 500 on a double-click/retry.
    try:
        st = subprocess.run(_sudo_wrap(['systemctl', 'is-active', _NONROOT_MIGRATE_UNIT + '.service']),
                            capture_output=True, text=True, timeout=5)
        if (st.stdout or '').strip() in ('active', 'activating'):
            return jsonify({'success': False, 'error': 'A non-root migration is already running.'}), 409
    except Exception:
        pass
    # Reset any prior FAILED transient unit so systemd accepts a fresh start of the same name.
    try:
        subprocess.run(_sudo_wrap(['systemctl', 'reset-failed', _NONROOT_MIGRATE_UNIT + '.service']),
                       capture_output=True, timeout=5)
    except Exception:
        pass
    try:  # seed status (0600) so the poller has something the instant this returns (console is root here)
        with open(_NONROOT_MIGRATE_STATUS, 'w') as f:
            f.write('running')
        os.chmod(_NONROOT_MIGRATE_STATUS, 0o600)
    except Exception:
        pass
    cmd = [
        'systemd-run',
        '--unit=' + _NONROOT_MIGRATE_UNIT,
        '--description=infra-TAK console non-root migration (detached)',
        '--property=StandardOutput=append:' + _NONROOT_MIGRATE_LOG,
        '--property=StandardError=append:' + _NONROOT_MIGRATE_LOG,
        '--setenv=PATH=/usr/sbin:/usr/bin:/sbin:/bin',
    ]
    # RHEL/SELinux: the transient migrate unit must run UNCONFINED. Otherwise, under
    # enforcing SELinux it runs in a confined domain and the flip's provision rsync
    # (start.sh: rsync of the current install → /opt/infratak) is denied search
    # access to the current install's home dir (/home/<user>) even as root, so
    # start.sh exits non-zero and the migration auto-rolls-back. Root-caused live on
    # Rocky 9.8: `SELinux is preventing /usr/bin/rsync from search access on the
    # directory rocky`. Same unconfined_service_t treatment the console + broker
    # units already carry (see _startup_ensure_broker). No-op where SELinux is
    # Disabled or absent (Ubuntu/Debian), so the happy path is unchanged.
    try:
        _ge = subprocess.run(['getenforce'], capture_output=True, text=True, timeout=5)
        if _ge.returncode == 0 and _ge.stdout.strip() != 'Disabled':
            cmd.append('--property=SELinuxContext=system_u:system_r:unconfined_service_t:s0')
    except Exception:
        pass
    cmd += [
        '--no-block',
        '/bin/bash', script, '--apply', '--auto-rollback',
    ]
    try:
        r = subprocess.run(_sudo_wrap(cmd), capture_output=True, text=True, timeout=15)
    except Exception as e:
        return jsonify({'success': False, 'error': f'could not launch migration: {e}'}), 500
    if r.returncode != 0:
        err = (r.stderr or r.stdout or '').strip()[:300]
        return jsonify({'success': False, 'error': f'systemd-run failed: {err}'}), 500
    return jsonify({'success': True,
                    'message': 'Migration started. The console will restart as the takwerx user (~30–60s). This page reconnects automatically.'})


@app.route('/api/console/migrate-nonroot/status')
@login_required
def console_migrate_nonroot_status_api():
    """Poll the non-root migration. The page calls this after it reconnects: the
    authoritative success signal is the console actually running non-root now;
    otherwise read the breadcrumb the script writes (running / done / failed:<reason>)."""
    nonroot = (os.getuid() != 0)
    state, detail = 'unknown', ''
    try:
        with open(_NONROOT_MIGRATE_STATUS) as f:
            raw = f.read().strip()
        if raw.startswith('failed-rollback:'):   # flip failed AND rollback unverified — SSH recovery
            state, detail = 'failed', raw[len('failed-rollback:'):]
        elif raw.startswith('failed:'):
            state, detail = 'failed', raw[len('failed:'):]
        elif raw in ('running', 'done'):
            state = raw
    except Exception:
        pass
    if nonroot:           # console answering as non-root == migration succeeded
        state = 'done'
    return jsonify({'state': state, 'nonroot': nonroot, 'detail': detail})


@app.route('/api/console/rollback', methods=['POST'])
@login_required
def console_rollback_api():
    """Roll back the console to the version saved before the last Update Now."""
    data = request.get_json(silent=True) or {}
    password = data.get('password', '')
    auth = load_settings().get('auth', {})
    if not auth.get('password_hash') or not check_password_hash(auth['password_hash'], password):
        return jsonify({'ok': False, 'error': 'Incorrect password'}), 403
    console_dir = os.path.dirname(os.path.abspath(__file__))
    s = load_settings()
    rb = s.get('console_rollback') or {}
    if not rb.get('available'):
        return jsonify({'ok': False, 'error': 'No rollback available (no snapshot recorded before last update)'}), 400
    prev_tag = rb.get('tag', '').strip()
    if not prev_tag:
        return jsonify({'ok': False, 'error': 'Rollback tag not recorded'}), 400
    try:
        git_cfg = ['git', '-c', f'safe.directory={console_dir}']
        # Fetch the tag from origin
        fetch_r = subprocess.run(
            git_cfg + ['fetch', 'https://github.com/takwerx/infra-TAK.git',
                       f'refs/tags/{prev_tag}:refs/tags/{prev_tag}'],
            cwd=console_dir, capture_output=True, text=True, timeout=60,
            env={**os.environ, 'GIT_TERMINAL_PROMPT': '0'}
        )
        checkout_r = subprocess.run(
            git_cfg + ['checkout', '--force', prev_tag],
            cwd=console_dir, capture_output=True, text=True, timeout=30,
            env={**os.environ, 'GIT_TERMINAL_PROMPT': '0'}
        )
        if checkout_r.returncode != 0:
            err = (checkout_r.stderr or '').strip() or 'git checkout failed'
            return jsonify({'ok': False, 'error': err}), 500
        # Clear rollback availability (one rollback per update)
        s['console_rollback'] = {'available': False}
        save_settings(s)
        _detached_console_restart()
        return jsonify({
            'ok': True, 'tag': prev_tag,
            'message': f'Rolled back to {prev_tag}. Console is restarting.'
        })
    except Exception as e:
        return jsonify({'ok': False, 'error': str(e)[:200]}), 500


@app.route('/takserver')
@login_required
def takserver_page():
    modules = detect_modules()
    tak = modules.get('takserver', {})
    ak = modules.get('authentik', {})
    # Show "Connect TAK Server to LDAP" when: TAK Server + Authentik installed, CoreConfig exists, LDAP not yet applied
    has_ldap = _coreconfig_has_ldap()
    show_connect_ldap = (
        tak.get('installed') and ak.get('installed') and
        os.path.exists('/opt/tak/CoreConfig.xml') and not has_ldap
    )
    ldap_connected = tak.get('installed') and ak.get('installed') and has_ldap
    # Reset deploy_done once TAK Server is running so the running view shows
    if tak.get('installed') and tak.get('running') and not deploy_status.get('running', False):
        deploy_status.update({'complete': False, 'error': False})
    tak_version = _get_takserver_version_info().get('version', '') if tak.get('installed') else ''
    _tak_jvm = _running_tak_jvm_version() if tak.get('installed') else ''
    _settings = load_settings()
    _tak_cfg = _get_tak_deployment_config(_settings)
    _is_two_server = _tak_cfg.get('mode') == 'two_server'
    _s1_host = (_tak_cfg.get('server_one', {}).get('host') or '').strip() if _is_two_server else ''
    _total_ram = _get_total_ram_gb_local() if tak.get('installed') else None
    _recommended_heap = _recommended_takserver_heap_gb(_total_ram) if _total_ram is not None else 4
    _current_heap = _get_current_takserver_heap_gb() if tak.get('installed') else None
    _upgrade_done = upgrade_status.get('complete', False)
    if _upgrade_done and not upgrade_status.get('running'):
        upgrade_status.update({'complete': False})
    _migrate_done = tak_migrate_status.get('complete', False)
    if _migrate_done and not tak_migrate_status.get('running'):
        tak_migrate_status.update({'complete': False})
    # v10.2.0 W5: 5.8/PG18 readiness for the update section. Cached (see
    # _tak_58_preflight_cached) so a page render never waits on `du`, and wrapped
    # so a probe failure degrades to "no card" rather than a 500 on the whole page.
    try:
        _tak58 = _tak_58_preflight_cached() if tak.get('installed') else None
    except Exception:
        _tak58 = None
    return render_template('takserver.html',
        tak58=_tak58,
        settings=_settings, modules=modules, tak=tak, tak_version=tak_version,
        tak_jvm=_tak_jvm,
        tak_installed=tak.get('installed', False),
        show_connect_ldap=show_connect_ldap, ldap_connected=ldap_connected,
        authentik_base_url=_get_authentik_base_url(_settings),
        takserver_base_url=_get_takserver_base_url(_settings),
        metrics=get_system_metrics(), version=VERSION, deploying=deploy_status.get('running', False),
        deploy_done=deploy_status.get('complete', False), deploy_error=deploy_status.get('error', False),
        upgrading=upgrade_status.get('running', False), upgrade_done=_upgrade_done,
        upgrade_error=upgrade_status.get('error', False),
        migrating=tak_migrate_status.get('running', False), migrate_done=_migrate_done,
        migrate_error=tak_migrate_status.get('error', False),
        two_server_mode=_is_two_server, s1_host=_s1_host, tak_is_container=_tak_is_container(),
        total_ram_gb=_total_ram, recommended_heap_gb=_recommended_heap, current_heap_gb=_current_heap)

