@app.route('/api/takserver/two-server/preflight', methods=['POST'])
@login_required
def takserver_two_server_preflight():
    data = request.get_json() or {}
    settings = load_settings()
    cfg = _get_tak_deployment_config(settings)
    if isinstance(data.get('config'), dict):
        cfg = _normalize_tak_deployment_config(_deep_merge_dict(cfg, data.get('config')))
    if cfg.get('mode') != 'two_server':
        return jsonify({'success': False, 'error': 'Deployment mode is not set to two_server', 'config': cfg}), 400

    checks = []
    server_one = cfg.get('server_one', {})
    server_two = cfg.get('server_two', {})
    db_port = int(cfg.get('database', {}).get('port') or 5432)

    def add_check(name, ok, details=''):
        checks.append({'name': name, 'ok': bool(ok), 'details': (details or '')[:600]})

    add_check('Server One host configured', bool(server_one.get('host')), server_one.get('host', ''))
    if server_two.get('use_localhost'):
        add_check('Server Two host configured', True, 'Using infra-TAK host (local)')
    else:
        add_check('Server Two host configured', bool(server_two.get('host')), server_two.get('host', ''))

    one_ok = two_ok = False
    one_out = two_out = ''
    if server_one.get('host'):
        one_ok, one_out = _ssh_probe(server_one, 'echo "server_one_ok" && uname -a', timeout=18)
    add_check('SSH to Server One (Database Server)', one_ok, one_out)
    if server_two.get('host') or server_two.get('use_localhost'):
        two_ok, two_out = _ssh_probe(server_two, 'echo "server_two_ok" && uname -a', timeout=18)
    add_check('SSH to Server Two (Core Server)', two_ok, two_out)

    # From Server Two, verify DB TCP path to Server One:5432 (or configured DB port).
    db_reach_ok = False
    if two_ok and server_one.get('host'):
        probe_cmd = f'timeout 6 bash -lc "</dev/tcp/{server_one.get("host")}/{db_port}" >/dev/null 2>&1 && echo OPEN || echo CLOSED'
        ok, out = _ssh_probe(server_two, probe_cmd, timeout=20)
        db_reach_ok = ok and 'OPEN' in (out or '')
        if not db_reach_ok and one_ok:
            # Diagnose: SSH to Server One and check PG status for actionable detail.
            diag_cmd = (
                f'pg_installed=$(dpkg -l 2>/dev/null | grep -ci postgres); '
                f'pg_listen=$(ss -tlnp 2>/dev/null | grep :{db_port} || true); '
                f'ufw_line=$(sudo ufw status 2>/dev/null | grep {db_port} | head -3 || true); '
                f'if [ "$pg_installed" = "0" ]; then echo "DIAG: PostgreSQL not installed on Server One. Run Deploy to Server One first."; '
                f'elif [ -z "$pg_listen" ]; then echo "DIAG: PostgreSQL installed but not listening on port {db_port}. Service may be stopped."; '
                f'else echo "DIAG: PostgreSQL listening: $pg_listen | UFW: $ufw_line"; fi'
            )
            _, diag_out = _ssh_probe(server_one, diag_cmd, timeout=15)
            detail = f'CLOSED — {(diag_out or "").strip()}'
            add_check(f'Server Two can reach Server One DB port {db_port}', False, detail)
        else:
            add_check(f'Server Two can reach Server One DB port {db_port}', db_reach_ok, out)
    else:
        add_check(f'Server Two can reach Server One DB port {db_port}', False, 'Skipped (SSH/host check failed)')

    all_ok = all(c['ok'] for c in checks)
    return jsonify({
        'success': all_ok,
        'config': cfg,
        'checks': checks,
        'summary': {
            'ready': all_ok,
            'server_one_ssh': one_ok,
            'server_two_ssh': two_ok,
            'db_reachable_from_server_two': db_reach_ok,
        }
    })

_PG_IDENT_RE = re.compile(r'^[A-Za-z_][A-Za-z0-9_]{0,62}$')

# The value we tell an operator to put in Azure's `azure.extensions` server parameter.
# It is deliberately the SAME string static/takserver.js has displayed since the Azure
# instructions shipped: handing someone two different values for one field is how you
# get a half-applied setting. The ENFORCED requirement is narrower (see the allow-list
# gate in the provision route) — POSTGIS and PGCRYPTO because TAK's schema needs them
# and 5.8 stopped creating them, FUZZYSTRMATCH and POSTGIS_TOPOLOGY because
# SchemaManager.purge() DROPs them and Azure rejects a DROP naming an extension it does
# not allow. ADDRESS_STANDARDIZER is not needed by anything on the upgrade path; it
# stays in the recommended string only because boxes in the field already carry it.
_AZURE_EXTENSIONS_RECOMMENDED = 'FUZZYSTRMATCH,POSTGIS,POSTGIS_TOPOLOGY,ADDRESS_STANDARDIZER,PGCRYPTO'


@app.route('/api/takserver/external-db/provision', methods=['POST'])
@login_required
def takserver_external_db_provision():
    """Provision the TAK Server database user on an external/managed PostgreSQL instance.
    Installs postgresql-client if needed, connects as the admin user, creates the app user
    (martiuser by default), grants required privileges, and returns a log of what was done.

    v0.9.12 hardening — defence against SQL injection:
      * All identifiers (db_user, db_name, admin_user, app_user) are
        regex-validated against the Postgres identifier grammar
        (^[A-Za-z_][A-Za-z0-9_]{0,62}$) before any psql call. Postgres
        does NOT support parameter substitution for identifiers, so this
        is the only safe path.
      * Passwords (app_pass) go through `psql -v` substitution and
        :'name' quoting, NEVER f-strings.
      * db_host is validated via _safe_migration_db_host (IP or simple
        DNS name only).
    """
    import secrets, string
    data = request.get_json() or {}
    settings = load_settings()
    cfg = _get_tak_deployment_config(settings)
    if isinstance(data.get('config'), dict):
        cfg = _normalize_tak_deployment_config(_deep_merge_dict(cfg, data.get('config')))
    edb = cfg.get('external_db', {})

    db_host    = (data.get('db_host')    or edb.get('host')     or '').strip()
    db_port    = int(data.get('db_port') or edb.get('port')     or 5432)
    db_name    = (data.get('db_name')    or edb.get('name')     or 'cot').strip()
    app_user   = (data.get('app_user')   or edb.get('user')     or 'martiuser').strip()
    app_pass   = (data.get('app_pass')   or '').strip()
    admin_user = (data.get('admin_user') or 'postgres').strip()
    admin_pass = (data.get('admin_pass') or '').strip()

    if not db_host:
        return jsonify({'success': False, 'error': 'No database host provided', 'log': []}), 400
    if not admin_pass:
        return jsonify({'success': False, 'error': 'Admin password is required to provision the database', 'log': []}), 400

    # v0.9.12 — input validation BEFORE any psql call.
    if not _safe_migration_db_host(db_host):
        return jsonify({'success': False, 'error': 'Invalid db_host (must be IP or simple DNS name)', 'log': []}), 400
    if not (1 <= db_port <= 65535):
        return jsonify({'success': False, 'error': 'Invalid db_port', 'log': []}), 400
    for _ident_name, _ident_val in (('app_user', app_user), ('db_name', db_name), ('admin_user', admin_user)):
        if not _PG_IDENT_RE.fullmatch(_ident_val):
            return jsonify({
                'success': False,
                'error': f'Invalid {_ident_name}: must match Postgres identifier grammar ^[A-Za-z_][A-Za-z0-9_]{{0,62}}$',
                'log': []
            }), 400

    log = []

    def plog(msg):
        log.append(msg)

    # Auto-generate app password if not provided
    generated_pass = False
    if not app_pass:
        alphabet = string.ascii_letters + string.digits + '!@#%^*'
        app_pass = ''.join(secrets.choice(alphabet) for _ in range(24))
        generated_pass = True
        plog(f'  Generated strong password for {app_user}')

    # Install postgresql-client if psql not available
    try:
        r = subprocess.run(['which', 'psql'], capture_output=True, text=True, timeout=5)
        if r.returncode != 0:
            # Multiplatform (CLAUDE.md): the psql client package name differs by family —
            # Debian/Ubuntu = postgresql-client, RHEL/Rocky = postgresql (provides /usr/bin/psql).
            # Go through the apt<->dnf shim (_pkg_install), never a bare apt-get (which doesn't
            # exist on RHEL — that was the FileNotFoundError on the external-DB Rocky path).
            client_pkg = 'postgresql' if _distro_family() == 'rhel' else 'postgresql-client'
            plog(f'  psql not found — installing {client_pkg}...')
            ok_inst, inst_out = _pkg_install(client_pkg, timeout=300)
            if not ok_inst:
                plog(f'  ✗ Failed to install {client_pkg}: {(inst_out or "")[:300]}')
                return jsonify({'success': False, 'log': log, 'error': f'Could not install {client_pkg}'}), 500
            plog(f'  ✓ {client_pkg} installed')
        else:
            plog('  ✓ psql available')
    except Exception as e:
        plog(f'  ✗ Error checking psql: {e}')
        return jsonify({'success': False, 'log': log, 'error': str(e)}), 500

    def run_sql(sql, label, use_db=None, pw_var=None):
        """Run a SQL statement as the admin user. Returns (ok, output).

        pw_var={'name': value}: when provided the SQL is piped to psql via
        stdin with a leading \\set directive so psql resolves :'name' before
        sending to the server. Piping via stdin avoids shell-level and psql
        -v parser issues with special characters (e.g. # in passwords).
        """
        try:
            target_db = use_db or db_name
            env = dict(os.environ, PGPASSWORD=admin_pass)
            argv = ['psql', '-h', db_host, '-p', str(db_port), '-U', admin_user,
                    '-d', target_db, '--no-password', '-t', '-A']
            if pw_var:
                # Build \set directives piped via stdin — avoids -v parsing issues
                # with special chars (# treated as comment by psql's -v parser).
                set_lines = ''
                for _k, _v in pw_var.items():
                    escaped = _v.replace('\\', '\\\\').replace("'", "\\'")
                    set_lines += f"\\set {_k} '{escaped}'\n"
                stdin_sql = set_lines + sql
                r = subprocess.run(argv, input=stdin_sql, capture_output=True,
                                   text=True, timeout=20, env=env)
            else:
                argv.extend(['-c', sql])
                r = subprocess.run(argv, capture_output=True, text=True, timeout=20, env=env)
            ok = r.returncode == 0
            out = (r.stdout or r.stderr or '').strip()[:300]
            return ok, out
        except Exception as e:
            return False, str(e)[:300]

    # Step 1: Verify admin connection — always use the 'postgres' system database first
    # since the target database (e.g. 'cot') may not exist yet on fresh managed instances.
    plog(f'  Connecting as {admin_user} to {db_host}:{db_port}/postgres...')
    ok, out = run_sql('SELECT 1;', 'admin connect', use_db='postgres')
    if not ok:
        plog(f'  ✗ Admin connection failed: {out}')
        return jsonify({'success': False, 'log': log, 'error': f'Cannot connect as {admin_user}: {out}'}), 400
    plog(f'  ✓ Connected as {admin_user}')

    # Step 1b: Create the target database if it doesn't exist
    plog(f'  Checking if database {db_name} exists...')
    ok, out = run_sql(f"SELECT 1 FROM pg_database WHERE datname='{db_name}';", 'check db', use_db='postgres')
    db_exists = ok and '1' in out
    if db_exists:
        plog(f'  Database {db_name} already exists')
    else:
        plog(f'  Creating database {db_name}...')
        ok, out = run_sql(
            f"CREATE DATABASE {db_name} ENCODING 'UTF8' LC_COLLATE 'en_US.UTF-8' LC_CTYPE 'en_US.UTF-8' TEMPLATE template0;",
            'create db', use_db='postgres'
        )
        if not ok:
            plog(f'  ✗ Failed to create database: {out}')
            return jsonify({'success': False, 'log': log, 'error': f'Could not create database {db_name}: {out}'}), 500
        plog(f'  ✓ Created database {db_name}')

    # Step 2: Create app user if it doesn't exist.
    # Identifier (app_user) was regex-validated upfront — safe to inline.
    # Password goes through psql -v substitution and :'pw' quoting.
    plog(f'  Checking if user {app_user} exists...')
    ok, out = run_sql(f"SELECT 1 FROM pg_roles WHERE rolname='{app_user}';", 'check user', use_db='postgres')
    user_exists = ok and '1' in out
    if user_exists:
        plog(f'  User {app_user} already exists — updating password...')
        ok, out = run_sql(f"ALTER USER {app_user} WITH PASSWORD :'pw';", 'alter user', use_db='postgres', pw_var={'pw': app_pass})
        if not ok:
            plog(f'  ✗ Failed to update password: {out}')
        else:
            plog(f'  ✓ Password updated for {app_user}')
    else:
        plog(f'  Creating user {app_user}...')
        ok, out = run_sql(f"CREATE USER {app_user} WITH PASSWORD :'pw';", 'create user', use_db='postgres', pw_var={'pw': app_pass})
        if not ok:
            plog(f'  ✗ Failed to create user: {out}')
            return jsonify({'success': False, 'log': log, 'error': f'Could not create user {app_user}: {out}'}), 500
        plog(f'  ✓ Created user {app_user}')

    # Step 3: Grant database privileges (connect to postgres to issue GRANT ON DATABASE)
    plog(f'  Granting privileges on database {db_name} to {app_user}...')
    ok, out = run_sql(f'GRANT ALL PRIVILEGES ON DATABASE {db_name} TO {app_user};', 'grant db', use_db='postgres')
    plog(f'  {"✓" if ok else "✗"} GRANT ALL ON DATABASE: {out if not ok else "OK"}')

    # Step 3b: Cloud-provider-specific role grants
    is_rds = '.rds.amazonaws.com' in db_host
    is_azure = '.postgres.database.azure.com' in db_host
    if is_rds:
        plog(f'  AWS RDS detected — granting rds_superuser to {app_user} (required for PostGIS)...')
        ok, out = run_sql(f'GRANT rds_superuser TO {app_user};', 'grant rds_superuser', use_db='postgres')
        plog(f'  {"✓" if ok else "✗"} rds_superuser grant: {out if not ok else "OK"}')
    if is_azure:
        plog(f'  Azure PostgreSQL detected — granting azure_pg_admin to {app_user}...')
        ok, out = run_sql(f'GRANT azure_pg_admin TO {app_user};', 'grant azure_pg_admin', use_db='postgres')
        plog(f'  {"✓" if ok else "✗"} azure_pg_admin grant: {out if not ok else "OK"}')

    # Step 3c: the extensions TAK's schema needs, created by the ADMIN in the target
    # database — for EVERY managed provider, not just Azure.
    #
    # This used to run only on the Azure branch, and on TAK 5.7 that was CORRECT for
    # AWS: 5.7's own migrations created the extensions, so granting rds_superuser was
    # enough and RDS installs and updates worked with nothing else —
    #
    #   5.7  V7__create_base_schema.sql:14   CREATE EXTENSION IF NOT EXISTS postgis;
    #   5.7  V9__create_resource_hash.sql:9  CREATE EXTENSION IF NOT EXISTS pgcrypto;
    #
    # **TAK 5.8 removed those lines.** No migration in 5.8's SchemaManager creates any
    # extension; the vendor moved it to db-utils/setup.sql, which is run by
    # takserver-setup-db.sh — and that script only ever runs on a LOCAL install. On an
    # external database the console runs SchemaManager directly, so on 5.8 nothing
    # creates PostGIS and the first migration that needs it dies. Measured on a fresh
    # RDS PostgreSQL 18 instance, 2026-09-04:
    #
    #   Migration of schema "public" to version "7 - create base schema" failed!
    #   ERROR: function addgeometrycolumn(...) does not exist
    #   -> SchemaManager exited 2, cot had only `plpgsql`, schema_version stayed 0
    #
    # and the deploy still reported DEPLOYMENT COMPLETE, leaving TAK 5.8 running
    # against a database with no schema. This is an UPSTREAM 5.8 regression against
    # every managed-database deployment, and it hits upgrades as well as fresh
    # installs — Azure escapes it only because of the pre-create below.
    #
    # The list mirrors TAK's own setup.sql rather than guessing: postgis and pgcrypto,
    # and NOT fuzzystrmatch / postgis_topology / address_standardizer — setup.sql
    # explicitly DROPs the first two as "unneeded extensions put in place by setup
    # scripts for schema versions 7-12". The old Azure list created all five and hard
    # -failed provisioning if the tenant had not whitelisted them, i.e. it demanded
    # operators whitelist extensions TAK deletes.
    if is_rds or is_azure:
        _req_ext = 'postgis'
        _opt_ext = ['pgcrypto']
        _provider = 'Azure' if is_azure else 'AWS RDS'
        plog(f'  {_provider}: creating the extensions TAK needs, as {admin_user}...')
        ok, out = run_sql(f'CREATE EXTENSION IF NOT EXISTS {_req_ext};',
                          f'create ext {_req_ext}', use_db=db_name)
        plog(f'  {"✓" if ok else "✗"} {_req_ext}: {out if not ok else "OK"}')
        if not ok:
            if is_azure:
                msg = (
                    'PostGIS could not be created in the database and TAK\'s schema cannot be '
                    'built without it. On Azure this normally means the extension is not '
                    'whitelisted: Azure Portal → your PostgreSQL Flexible Server → Server '
                    'parameters → search "azure.extensions" → set it to '
                    + _AZURE_EXTENSIONS_RECOMMENDED + ' → '
                    'Save, then re-run Provision Database. Reported: %s'
                    % (out or 'unknown error'))
            else:
                msg = (
                    'PostGIS could not be created in the database and TAK\'s schema cannot be '
                    'built without it. Confirm the instance offers PostGIS for this engine '
                    'version and that the admin user may create extensions. Reported: %s'
                    % (out or 'unknown error'))
            plog(f'  ✗ {msg}')
            return jsonify({'success': False, 'error': msg, 'log': log,
                            'extensions_not_whitelisted': True}), 400
        _opt_missing = []
        for ext in _opt_ext:
            ok, out = run_sql(f'CREATE EXTENSION IF NOT EXISTS {ext};', f'create ext {ext}',
                              use_db=db_name)
            plog(f'  {"✓" if ok else "△"} {ext}: {out if not ok else "OK"}')
            if not ok:
                _opt_missing.append(ext)
        if _opt_missing:
            plog('  △ Not available on this instance: %s. PostGIS is present, so the base '
                 'schema will build; note these in case a later TAK feature needs them.'
                 % ', '.join(_opt_missing))

        # Azure only: the allow-list must also cover the extensions TAK DROPs.
        #
        # SchemaManager's `upgrade` opens with UpgradeCommand -> SchemaManager.purge(),
        # which issues DROP EXTENSION IF EXISTS fuzzystrmatch / postgis_topology CASCADE
        # on both 5.7 and 5.8. Azure refuses a DROP naming a non-allow-listed extension
        # even when it does not exist, so SchemaManager exits 2 and no schema is ever
        # built. Creating postgis and pgcrypto is therefore NOT sufficient on Azure, and
        # provisioning that returns success here while the deploy is guaranteed to fail
        # ten minutes later is a worse outcome than refusing now. Measured az-test-rds
        # 2026-09-19. AWS RDS is unaffected — a DROP IF EXISTS of an absent extension
        # simply succeeds there.
        if is_azure:
            _az_need = ['POSTGIS', 'PGCRYPTO', 'FUZZYSTRMATCH', 'POSTGIS_TOPOLOGY']
            ok_al, out_al = run_sql('show azure.extensions;', 'read azure.extensions',
                                    use_db=db_name)
            if ok_al:
                _allowed = set(x.strip().upper()
                               for x in (out_al or '').replace('\n', ',').split(',') if x.strip())
                _az_missing = [e for e in _az_need if e not in _allowed]
                if _az_missing:
                    _all = _AZURE_EXTENSIONS_RECOMMENDED
                    msg = (
                        'Azure: %s %s not allow-listed. TAK\'s SchemaManager runs '
                        'DROP EXTENSION IF EXISTS fuzzystrmatch / postgis_topology before it '
                        'builds the schema, and Azure rejects a DROP naming an extension that '
                        'is not allow-listed even when it is not installed — so the deploy '
                        'would fail with no schema. Azure Portal → %s → Settings → Server '
                        'parameters → azure.extensions → set value to: %s → Save, then re-run '
                        'Provision Database.'
                        % (', '.join(_az_missing),
                           'is' if len(_az_missing) == 1 else 'are',
                           db_host.split('.')[0], _all))
                    plog('  \u2717 ' + msg)
                    return jsonify({'success': False, 'error': msg, 'log': log,
                                    'extensions_not_whitelisted': True,
                                    'missing_extensions': _az_missing}), 400
                plog('  \u2713 azure.extensions covers all 4 required: ' + ','.join(_az_need))
            else:
                plog('  \u25b3 Could not read azure.extensions (%s) \u2014 confirm POSTGIS, '
                     'PGCRYPTO, FUZZYSTRMATCH and POSTGIS_TOPOLOGY are allow-listed in the '
                     'Azure Portal.' % (out_al or 'no output'))

    # Step 4: Grant schema privileges (must connect to the target database)
    plog(f'  Granting schema privileges...')
    schema_sql = (
        f'GRANT ALL ON SCHEMA public TO {app_user}; '
        f'ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT ALL ON TABLES TO {app_user}; '
        f'ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT ALL ON SEQUENCES TO {app_user};'
    )
    ok, out = run_sql(schema_sql, 'grant schema', use_db=db_name)
    plog(f'  {"✓" if ok else "✗"} Schema grants: {out if not ok else "OK"}')

    # Step 5: Verify app user can connect
    plog(f'  Verifying {app_user} can authenticate...')
    try:
        env = dict(os.environ, PGPASSWORD=app_pass)
        r = subprocess.run(
            ['psql', '-h', db_host, '-p', str(db_port), '-U', app_user, '-d', db_name,
             '-c', 'SELECT version();', '--no-password', '-t', '-A'],
            capture_output=True, text=True, timeout=15, env=env
        )
        if r.returncode == 0:
            plog(f'  ✓ {app_user} authenticated successfully')
        else:
            plog(f'  ⚠ {app_user} auth check: {(r.stderr or r.stdout or "").strip()[:200]}')
    except Exception as e:
        plog(f'  ⚠ Auth verify error: {e}')

    plog(f'  ✓ Database provisioned — {app_user}@{db_host}:{db_port}/{db_name}')

    return jsonify({
        'success': True,
        'log': log,
        'app_user': app_user,
        'app_pass': app_pass if generated_pass else None,
        'generated_pass': generated_pass,
    })


@app.route('/api/takserver/external-db/test-connection', methods=['POST'])
@login_required
def takserver_external_db_test_connection():
    """Test TCP + pg_isready connectivity to an external/managed PostgreSQL endpoint.
    Does not require SSH — runs checks from the local host (Server Two / TAK Server VM).
    """
    data = request.get_json() or {}
    settings = load_settings()
    cfg = _get_tak_deployment_config(settings)
    if isinstance(data.get('config'), dict):
        cfg = _normalize_tak_deployment_config(_deep_merge_dict(cfg, data.get('config')))
    edb = cfg.get('external_db', {})
    db_host = (edb.get('host') or '').strip()
    db_port = int(edb.get('port') or 5432)
    db_name = (edb.get('name') or 'cot').strip()
    db_user = (edb.get('user') or 'martiuser').strip()
    db_pass = (edb.get('password') or '').strip()
    if not db_host:
        return jsonify({'success': False, 'error': 'No database host configured', 'checks': []}), 400

    # v0.9.12 — input validation. Catches command-injection vectors before
    # any shell-out below. Previous code piped `db_host` through `bash -c`.
    if not _safe_migration_db_host(db_host):
        return jsonify({'success': False, 'error': 'Invalid db_host (must be IP or simple DNS name)', 'checks': []}), 400
    if not (1 <= db_port <= 65535):
        return jsonify({'success': False, 'error': 'Invalid db_port', 'checks': []}), 400

    checks = []

    def add_check(name, ok, detail=''):
        # ok=None means "skipped/informational" — preserve as null in JSON, not bool
        checks.append({'name': name, 'ok': (None if ok is None else bool(ok)), 'detail': (detail or '')[:400]})

    # Check 1: TCP reachability — v0.9.12: socket.create_connection instead of
    # `bash -c "</dev/tcp/HOST/PORT"`. No shell, no injection vector.
    tcp_ok = False
    try:
        import socket as _sock_tc
        with _sock_tc.create_connection((db_host, db_port), timeout=8):
            tcp_ok = True
            add_check(f'TCP {db_host}:{db_port}', True, f'Connected to {db_host}:{db_port}')
    except (_sock_tc.timeout, OSError) as _tc_err:
        add_check(f'TCP {db_host}:{db_port}', False, str(_tc_err)[:200])
    except Exception as e:
        add_check(f'TCP {db_host}:{db_port}', False, str(e)[:200])

    # Check 2: pg_isready (if pg_isready available locally)
    pg_ready_ok = False
    try:
        r = subprocess.run(
            ['pg_isready', '-h', db_host, '-p', str(db_port), '-d', db_name, '-U', db_user, '-t', '8'],
            capture_output=True, text=True, timeout=12
        )
        pg_ready_ok = r.returncode == 0
        add_check(f'pg_isready ({db_name}@{db_host})', pg_ready_ok, (r.stdout or r.stderr or '').strip()[:200])
    except FileNotFoundError:
        add_check('pg_isready', None, 'pg_isready not installed locally — TCP check only')
    except Exception as e:
        add_check('pg_isready', False, str(e)[:200])

    # Check 3: psql auth (if password provided and psql available)
    if db_pass and tcp_ok:
        try:
            env = dict(os.environ, PGPASSWORD=db_pass)
            r = subprocess.run(
                ['psql', '-h', db_host, '-p', str(db_port), '-U', db_user, '-d', db_name,
                 '-c', 'SELECT version();', '--no-password', '-t', '-A'],
                capture_output=True, text=True, timeout=15, env=env
            )
            auth_ok = r.returncode == 0
            add_check(f'psql auth ({db_user}@{db_name})', auth_ok,
                      (r.stdout or r.stderr or '').strip()[:200] if not auth_ok else 'Authenticated successfully')
        except FileNotFoundError:
            add_check('psql auth', None, 'psql client not installed locally — skipped')
        except Exception as e:
            add_check('psql auth', False, str(e)[:200])

    # Check 4: Azure extension whitelist probe
    # Only runs when the endpoint is an Azure Flexible Server FQDN AND an app
    # user password is stored (i.e. Provision Database has been run at least once).
    # Skipped gracefully before provisioning — no FAIL so Test Connection passes
    # at the pre-provision stage and the operator can proceed to step 3.
    if '.postgres.database.azure.com' in db_host and tcp_ok:
        if not db_pass:
            add_check('Azure extensions whitelisted', None, 'Skipped — run Provision Database first, then re-test')
        else:
            # What Azure must ALLOW — which is not the same as what we create.
            #
            # We create postgis and pgcrypto (TAK 5.8 stopped creating them itself).
            # But TAK's SchemaManager, on both 5.7 and 5.8, opens `upgrade` with
            # UpgradeCommand -> SchemaManager.purge(), which unconditionally issues:
            #
            #   DROP EXTENSION IF EXISTS fuzzystrmatch CASCADE;
            #   DROP EXTENSION IF EXISTS postgis_topology CASCADE;
            #
            # On AWS RDS that is a no-op when the extension isn't there. **Azure rejects
            # a DROP of a non-allow-listed extension by NAME, even with IF EXISTS** —
            # "extension \"fuzzystrmatch\" is not allow-listed for users". SchemaManager
            # dies at exit 2 and the database never gets a schema. Measured on
            # az-test-rds, 2026-09-19, on a fresh 5.7 install.
            #
            # So the allow-list is four, not the two we create. address_standardizer is
            # NOT included: only SetupPostresOnRDS/SetupPostresGeneric reference it and
            # neither is on the `upgrade` path we run.
            _AZ_EXT_REASON = {
                'POSTGIS': 'TAK schema (we create it)',
                'PGCRYPTO': 'TAK schema (we create it)',
                'FUZZYSTRMATCH': "SchemaManager.purge() DROPs it — Azure blocks the DROP if it isn't allow-listed",
                'POSTGIS_TOPOLOGY': "SchemaManager.purge() DROPs it — same",
            }
            azure_required = list(_AZ_EXT_REASON)
            try:
                # Ask for the ALLOW-LIST, not pg_available_extensions. The latter lists
                # what the engine could install and answers "yes" for extensions Azure
                # still refuses, so it passed this check green while the deploy failed.
                env = dict(os.environ, PGPASSWORD=db_pass)
                r = subprocess.run(
                    ['psql', '-h', db_host, '-p', str(db_port), '-U', db_user, '-d', 'postgres',
                     '-c', 'show azure.extensions;', '--no-password', '-t', '-A'],
                    capture_output=True, text=True, timeout=15, env=env
                )
                if r.returncode == 0:
                    allowed = set(x.strip().upper() for x in (r.stdout or '').replace('\n', ',').split(',') if x.strip())
                    missing = [e for e in azure_required if e not in allowed]
                    if missing:
                        # Suggest the exact string the UI has shown since this feature
                        # shipped (static/takserver.js) — an operator must never be handed
                        # two different values for the same field. ADDRESS_STANDARDIZER is
                        # not required by anything on the upgrade path, but it is already
                        # set on boxes in the field and is harmless as a superset.
                        all_upper = _AZURE_EXTENSIONS_RECOMMENDED
                        detail = (
                            'Missing: %s (%s). In Azure Portal → %s → Settings → Server parameters → '
                            'azure.extensions → set value to: %s → Save.'
                            % (','.join(missing),
                               '; '.join(f'{m}: {_AZ_EXT_REASON[m]}' for m in missing),
                               db_host.split('.')[0], all_upper)
                        )
                        add_check('Azure extensions allow-listed', False, detail)
                    else:
                        add_check('Azure extensions allow-listed', True,
                                  'All 4 required extensions allow-listed: ' + ','.join(azure_required))
                else:
                    add_check('Azure extensions allow-listed', None,
                              'Could not read azure.extensions — verify manually in Azure Portal')
            except Exception as e:
                add_check('Azure extensions allow-listed', None, f'Extension check skipped: {str(e)[:150]}')

    all_ok = all(c['ok'] for c in checks if c.get('ok') is not None)
    return jsonify({'success': all_ok, 'checks': checks, 'host': db_host, 'port': db_port})


def _ensure_ssh_pubkey(key_path):
    """Make <key_path>.pub exist whenever the PRIVATE key already does. Returns (ok, error).

    An operator-supplied private key arrives WITHOUT its public half: the uploaded AWS/Azure
    .pem path (`/upload-ssh-key`) only ever wrote the private key, and an operator can point
    ssh_key_path at a key they made themselves. Every "Setup SSH key" button then fell through
    to `ssh-keygen -t ed25519 -f <path that already exists>`, which asks "Overwrite (y/n)?" on
    a stdin that is not a TTY under gunicorn -- it dies, and the operator has no way to answer
    it. Worse, the next step ("Copy key to host") hard-fails on a missing .pub, so the wizard
    dead-ends with no way forward. Field report: EC2 two-server DB migration, 2026-09-15.

    Derive the public half with `ssh-keygen -y` instead of regenerating. Never regenerate over
    an existing private key, and never overwrite an existing .pub. The derived key loses the
    original -C comment; ssh-copy-id does not care.
    """
    key_path = os.path.expanduser((key_path or '').strip())
    if not key_path or not os.path.exists(key_path):
        return False, 'private key not found'
    pub_path = key_path + '.pub'
    if os.path.exists(pub_path):
        return True, ''
    try:
        r = subprocess.run(['ssh-keygen', '-y', '-f', key_path],
                           capture_output=True, text=True, timeout=10,
                           stdin=subprocess.DEVNULL)
    except Exception as e:
        return False, str(e)[:200]
    if r.returncode != 0 or not (r.stdout or '').strip():
        err = (r.stderr or r.stdout or 'ssh-keygen -y failed').strip()
        if 'passphrase' in err.lower():
            err = 'the private key is passphrase-protected - re-export it without a passphrase'
        return False, err[:200]
    try:
        fd = os.open(pub_path, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o644)
        with os.fdopen(fd, 'w') as f:
            f.write((r.stdout or '').strip() + '\n')
    except Exception as e:
        return False, f'could not write {pub_path}: {str(e)[:160]}'
    return True, ''


@app.route('/api/takserver/two-server/ensure-ssh-key', methods=['POST'])
@login_required
def takserver_two_server_ensure_ssh_key():
    """Ensure an SSH key exists on this host for Server One. Generate if missing. Returns pub path and fingerprint."""
    data = request.get_json() or {}
    settings = load_settings()
    cfg = _get_tak_deployment_config(settings)
    if isinstance(data.get('config'), dict):
        cfg = _normalize_tak_deployment_config(_deep_merge_dict(cfg, data.get('config')))
    s1 = cfg.get('server_one', {})
    key_path = (s1.get('ssh_key_path') or '').strip() or os.path.expanduser('~/.ssh/id_rsa')
    key_path = os.path.expanduser(key_path)
    pub_path = key_path + '.pub'
    if os.path.exists(key_path):
        # The .pub may be absent even though the private key is here (uploaded .pem, or an
        # operator-supplied ssh_key_path). Derive it -- do NOT fall through to ssh-keygen,
        # which would prompt "Overwrite (y/n)?" on a non-TTY stdin and dead-end step 3.
        derived = not os.path.exists(pub_path)
        pub_ok, pub_err = _ensure_ssh_pubkey(key_path)
        if not pub_ok:
            return jsonify({
                'success': False,
                'error': f'A private key already exists at {key_path}, but its public half '
                         f'could not be derived: {pub_err}',
            }), 400
        try:
            r = subprocess.run(
                ['ssh-keygen', '-l', '-f', pub_path],
                capture_output=True, text=True, timeout=5
            )
            fingerprint = (r.stdout or '').strip() if r.returncode == 0 else ''
        except Exception:
            fingerprint = ''
        # Persist key path so Guard Dog and TAK Server UI have it without user typing it
        if cfg.get('server_one', {}).get('ssh_key_path') != key_path:
            cfg['server_one'] = cfg.get('server_one') or {}
            cfg['server_one']['ssh_key_path'] = key_path
            settings['tak_deployment'] = cfg
            save_settings(settings)
        return jsonify({
            'success': True,
            'key_path': key_path,
            'public_key_path': pub_path,
            'fingerprint': fingerprint,
            'message': 'Public key derived from your existing private key' if derived else 'Key already exists',
        })
    key_dir = os.path.dirname(key_path)
    if key_dir and not os.path.isdir(key_dir):
        try:
            os.makedirs(key_dir, mode=0o700)
        except Exception as e:
            return jsonify({'success': False, 'error': f'Could not create {key_dir}: {e}'}), 400
    try:
        subprocess.run(
            ['ssh-keygen', '-t', 'ed25519', '-N', '', '-f', key_path, '-C', 'infra-tak-server-one'],
            capture_output=True, text=True, timeout=30,
            stdin=subprocess.DEVNULL, check=True,
        )
    except subprocess.CalledProcessError as e:
        return jsonify({'success': False, 'error': (e.stderr or e.stdout or str(e))[:400]}), 400
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)[:400]}), 400
    try:
        r = subprocess.run(['ssh-keygen', '-l', '-f', pub_path], capture_output=True, text=True, timeout=5)
        fingerprint = (r.stdout or '').strip() if r.returncode == 0 else ''
    except Exception:
        fingerprint = ''
    # Persist key path so Guard Dog and TAK Server UI have it without user typing it
    cfg['server_one'] = cfg.get('server_one') or {}
    cfg['server_one']['ssh_key_path'] = key_path
    settings['tak_deployment'] = cfg
    save_settings(settings)
    return jsonify({
        'success': True,
        'key_path': key_path,
        'public_key_path': pub_path,
        'fingerprint': fingerprint,
        'message': 'New key generated',
    })


@app.route('/api/takserver/two-server/upload-ssh-key', methods=['POST'])
@login_required
def takserver_two_server_upload_ssh_key():
    """v10.0.5: accept the operator's EXISTING SSH PRIVATE key (the AWS `.pem` / Azure key
    the cloud DB box was launched with) so the console can reach Server One with NO password
    and NO CLI — the universal path for cloud key-only boxes (EC2/Azure don't have SSH
    passwords). Security: the key is written 0600 to a FIXED console-owned path (never a
    request-controlled path → no traversal), validated as a real usable private key via
    `ssh-keygen -y`, and NEVER logged or echoed back. Passphrase-protected keys are rejected
    (can't be used non-interactively). Sets server_one.ssh_key_path + auth_method=ssh_key so
    the deploy skips steps 2-3 entirely."""
    data = request.get_json() or {}
    key_text = (data.get('private_key') or '')
    if not key_text.strip():
        return jsonify({'success': False, 'error': 'No key provided.'}), 400
    key_text = key_text.replace('\r\n', '\n').replace('\r', '\n')
    if not key_text.endswith('\n'):
        key_text += '\n'
    if '-----BEGIN' not in key_text or 'PRIVATE KEY' not in key_text:
        return jsonify({'success': False, 'error': 'That does not look like an SSH private key — expected a "-----BEGIN … PRIVATE KEY-----" block (e.g. your AWS .pem file).'}), 400
    # FIXED destination — never request-controlled (no traversal). Console-owned ~/.ssh.
    key_path = os.path.expanduser('~/.ssh/infratak_serverone')
    try:
        os.makedirs(os.path.dirname(key_path), mode=0o700, exist_ok=True)
    except Exception as e:
        return jsonify({'success': False, 'error': f'Could not prepare key dir: {str(e)[:160]}'}), 400
    try:
        fd = os.open(key_path, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600)
        with os.fdopen(fd, 'w') as f:
            f.write(key_text)
        os.chmod(key_path, 0o600)
    except Exception as e:
        return jsonify({'success': False, 'error': f'Could not write key: {str(e)[:160]}'}), 500
    # Validate it's a usable, passphrase-free private key by deriving its public half.
    try:
        # stdin=DEVNULL: without it a passphrase-protected key makes ssh-keygen PROMPT and
        # hang until the timeout, so the passphrase hint below never fires. EOF = fail fast.
        r = subprocess.run(['ssh-keygen', '-y', '-f', key_path], capture_output=True, text=True, timeout=10,
                           stdin=subprocess.DEVNULL)
    except Exception as e:
        try: os.remove(key_path)
        except Exception: pass
        return jsonify({'success': False, 'error': f'Key validation failed: {str(e)[:160]}'}), 500
    if r.returncode != 0:
        try: os.remove(key_path)   # don't leave a bad/sensitive file around
        except Exception: pass
        _err = (r.stderr or r.stdout or '').lower()
        hint = ('the key is passphrase-protected — re-export it without a passphrase and upload that'
                if 'passphrase' in _err or 'incorrect passphrase' in _err
                else 'invalid or unsupported private key format')
        return jsonify({'success': False, 'error': f'Key rejected: {hint}.'}), 400
    # Persist the PUBLIC half too. `ssh-keygen -y` above already produced it and we used to
    # throw it away, so an uploaded .pem left <key>.pub absent -- which broke "Setup SSH key"
    # and permanently blocked "Copy key to host". Non-fatal: the private key alone is enough
    # for every deploy/migration path, the .pub only feeds ssh-copy-id.
    try:
        _pub_fd = os.open(key_path + '.pub', os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o644)
        with os.fdopen(_pub_fd, 'w') as _pub_f:
            _pub_f.write((r.stdout or '').strip() + '\n')
    except Exception:
        pass
    fingerprint = ''
    try:
        fr = subprocess.run(['ssh-keygen', '-l', '-f', key_path], capture_output=True, text=True, timeout=5)
        if fr.returncode == 0:
            fingerprint = (fr.stdout or '').strip()
    except Exception:
        pass
    # Point Server One at this key + ssh_key auth (skips generate/copy).
    settings = load_settings()
    cfg = _get_tak_deployment_config(settings)
    if isinstance(data.get('config'), dict):
        cfg = _normalize_tak_deployment_config(_deep_merge_dict(cfg, data.get('config')))
    cfg['server_one'] = cfg.get('server_one') or {}
    cfg['server_one']['ssh_key_path'] = key_path
    cfg['server_one']['auth_method'] = 'ssh_key'
    settings['tak_deployment'] = cfg
    save_settings(settings)
    return jsonify({
        'success': True,
        'key_path': key_path,
        'fingerprint': fingerprint,
        'message': 'SSH key uploaded — Server One will connect with it. Skip steps 2 & 3; go straight to 4. Deploy Server One.',
    })


@app.route('/api/takserver/two-server/install-ssh-key', methods=['POST'])
@login_required
def takserver_two_server_install_ssh_key():
    """Copy this host's SSH public key to Server One using ssh-copy-id (one-time password). Password not stored.
    Optional body keys install_host, install_user, install_port — copy to that host instead (e.g. new Server One before DB migration)."""
    data = request.get_json() or {}
    password = (data.get('password') or '').strip()
    if not password:
        return jsonify({'success': False, 'error': 'Password required for one-time copy'}), 400
    settings = load_settings()
    cfg = _get_tak_deployment_config(settings)
    if isinstance(data.get('config'), dict):
        cfg = _normalize_tak_deployment_config(_deep_merge_dict(cfg, data.get('config')))
    s1 = cfg.get('server_one', {})
    install_host = (data.get('install_host') or '').strip()
    if install_host:
        if not _safe_migration_db_host(install_host):
            return jsonify({'success': False, 'error': 'Invalid install_host (use IPv4 or hostname)'}), 400
        host = install_host
        user = (data.get('install_user') or s1.get('ssh_user') or 'root').strip() or 'root'
        raw_port = data.get('install_port')
        if raw_port is not None and str(raw_port).strip():
            try:
                port = int(raw_port)
            except (TypeError, ValueError):
                return jsonify({'success': False, 'error': 'install_port must be a number'}), 400
        else:
            port = int(s1.get('ssh_port') or 22)
    else:
        host = (s1.get('host') or '').strip()
        if not host:
            return jsonify({'success': False, 'error': 'Server One host not set'}), 400
        user = (s1.get('ssh_user') or 'root').strip() or 'root'
        port = int(s1.get('ssh_port') or 22)
    key_path = (s1.get('ssh_key_path') or '').strip() or os.path.expanduser('~/.ssh/id_rsa')
    key_path = os.path.expanduser(key_path)
    pub_path = key_path + '.pub'
    if not os.path.exists(pub_path):
        # Self-heal rather than send the operator back to a step that cannot help them:
        # if the private key is here, derive its public half (uploaded .pem case).
        _ok, _perr = _ensure_ssh_pubkey(key_path)
        if not _ok:
            return jsonify({'success': False, 'error': f'Public key not found at {pub_path} and could not be derived from {key_path}: {_perr}. Run "Setup SSH key" first.'}), 400
    if shutil.which('sshpass') is None:
        return jsonify({'success': False, 'error': 'sshpass not installed. Run: apt install sshpass (or use manual ssh-copy-id)'}), 400
    try:
        r = subprocess.run(
            ['sshpass', '-e', 'ssh-copy-id', '-i', pub_path,
             '-o', 'StrictHostKeyChecking=accept-new', '-p', str(port), f'{user}@{host}'],
            capture_output=True, text=True, timeout=30,
            env={**os.environ, 'SSHPASS': password},
        )
        if r.returncode != 0:
            err = (r.stderr or r.stdout or 'Unknown error').strip()[:500]
            return jsonify({'success': False, 'error': err}), 400
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)[:400]}), 400
    if install_host:
        return jsonify({'success': True, 'message': f'Key installed on {user}@{host}:{port}. Next: 4. Deploy Server One (DB) on new host (this page), then Start migration.'})
    return jsonify({'success': True, 'message': 'Key installed on Server One. Next: 4. Deploy Server One (DB).'})


def _valid_core_ip(value):
    """core_ip is interpolated into root pg_hba / firewall commands on Server One and
    MUST be a literal IPv4 (used as `<ip>/32` and a firewalld `family='ipv4'` source).
    Strict IPv4 validation keeps the value correct AND makes the shell interpolation
    injection-proof — a valid IPv4 contains no shell-significant characters."""
    v = (value or '').strip()
    if not v:
        return False
    try:
        ipaddress.IPv4Address(v)
        return True
    except (ipaddress.AddressValueError, ValueError):
        return False


def _resolve_core_ip(settings, cfg):
    """Resolve Server Two (Core) public IP for firewall and pg_hba rules.
    Returns a VALIDATED IPv4 string, or None — callers must treat None as 'not set'.
    server_two.host is operator-supplied via the request config blob, so it is
    validated here (the single chokepoint feeding _setup_server_one[_rhel], which
    interpolate core_ip into root shell commands on Server One)."""
    s2 = cfg.get('server_two', {})
    if s2.get('use_localhost'):
        core_ip = (settings.get('server_ip') or '').strip()
        if not core_ip:
            try:
                r = subprocess.run(
                    ['curl', '-s', '--connect-timeout', '5', 'https://ifconfig.me'],
                    capture_output=True, text=True, timeout=8
                )
                core_ip = (r.stdout or '').strip() if r.returncode == 0 else ''
            except Exception:
                pass
    else:
        core_ip = (s2.get('host') or '').strip()
    return core_ip if _valid_core_ip(core_ip) else None


# v10.1.51 (W2) — TCP keepalives on the SPLIT-SERVER remote Postgres.
#
# On a split box TAK Server's DB is a REAL remote host, not a container on the loopback.
# Postgres ships tcp_keepalives_idle=7200 (2 h), so nothing probes an idle connection for
# two hours and any NAT / stateful firewall on the path silently drops it while TAK keeps
# holding the dead socket. Field evidence (test8, 2026-08-26): HikariCP went
# total=0/active=0/idle=0/waiting=201 and never rebuilt — 40,534 errors, TAK Server down
# ~16 h — with Postgres itself up 35 days, reachable, and 9 of 2100 connections in use.
# Smaller self-healing clusters of the same signature appear on Aug 24 and Aug 25.
#
# We already codify exactly these values for the Postgres we deploy in a container
# (_AUTHENTIK_PG_COMMAND_TAIL) — the remote split DB was simply the one Postgres we
# configure but never tuned. Same fleet constant, so every split box converges on the same
# operational state; the sed deletes any existing line first, so this is a convergence
# write, NOT a max(current, target) that would let an operator's edit outlive the incident.
#
# Deliberately keepalives ONLY. idle_session_timeout / idle_in_transaction_session_timeout
# are right for Authentik's workload and are NOT assumed to be right for TAK's — reaping a
# TAK session mid-operation is a behavior change nobody has measured. The diagnosed failure
# is dead sockets, and keepalives are what detect those.
_SPLIT_DB_KEEPALIVE_LINES = ('tcp_keepalives_idle = 60\\n'
                             'tcp_keepalives_interval = 10\\n'
                             'tcp_keepalives_count = 6')


# Reusable SSH snippets: discover the PG data dir + service name on a RHEL Server One
# (PGDG postgresql-<major> vs base). Module-level since v10.1.51 so the split-server DEPLOY path
# and the keepalive RETROFIT below discover the same paths and cannot drift.
# NB: /var/lib/pgsql is 0700 postgres-owned — the glob MUST run under sudo or it expands to
# nothing as the SSH login user (the bug that bit the first run: empty PGDATA).
# ── PostgreSQL major version — fleet constants (v10.2.0 W1) ────────────────
# TAK Server 5.8 requires PostgreSQL 18 (deb Depends: postgresql-18,
# postgresql-18-postgis-3). 5.7 requires 15 and does NOT tolerate 18, so a box is
# on exactly one of them and the move is a single guided migration, never a
# standalone "upgrade Postgres" step.
#
# TWO constants on purpose — they are NOT interchangeable:
#   TAK_PG_MAJOR   what we INSTALL. One fleet constant, no per-box tiering and no
#                  max(cur, target): every box converges on the same major.
#   TAK_PG_MAJORS  what we RECOGNISE, newest first. Health checks, service
#                  discovery and systemd After= lines MUST accept BOTH. A box that
#                  has not migrated yet is on 15, and a box mid-migration has both
#                  clusters on disk. Probing only the new major would false-red
#                  every un-migrated box in the fleet the moment this ships — the
#                  same failure shape as the RHEL `postgresql-15` false-red that
#                  the probes below already exist to fix.
TAK_PG_MAJOR = 18
TAK_PG_MAJORS = (18, 15)
# ('postgresql-18', 'postgresql-15') — for systemctl is-active / discovery
_PG_SVC_UNITS = tuple('postgresql-%d' % m for m in TAK_PG_MAJORS)
# Debian's unsuffixed meta-service plus every major we recognise. Listing a unit
# that does not exist in After= is harmless to systemd.
_PG_SVC_AFTER = ' '.join(['postgresql.service'] + ['postgresql-%d.service' % m for m in TAK_PG_MAJORS])


_PG_REMOTE_PGDATA_SH = ("PGDATA=$(sudo sh -c 'ls -d /var/lib/pgsql/*/data 2>/dev/null' | sort -V | tail -1); "
                        "[ -z \"$PGDATA\" ] && sudo test -d /var/lib/pgsql/data && PGDATA=/var/lib/pgsql/data; true")
_PG_REMOTE_PGSVC_SH = (
    'PGSVC=postgresql; for _m in ' + ' '.join(str(m) for m in TAK_PG_MAJORS) + '; do '
    'systemctl list-unit-files 2>/dev/null | grep -q "^postgresql-$_m" && { PGSVC=postgresql-$_m; break; }; '
    'done; true')


def _pg_keepalive_sh(conf_expr):
    """Shell that converges tcp_keepalives_* in the postgresql.conf named by conf_expr.

    conf_expr is inserted into the remote shell verbatim and MUST already be quoted by the
    caller (every call site passes a double-quoted "$PGDATA/postgresql.conf"-style path built
    on the remote host, never anything derived from user input). Delete-then-append, so a box
    that already has a value converges instead of accumulating duplicate lines."""
    return (
        f'sudo sed -i "/^[[:space:]]*#*[[:space:]]*tcp_keepalives_[a-z]*[[:space:]]*=/d" {conf_expr}; '
        f'printf "\\n{_SPLIT_DB_KEEPALIVE_LINES}\\n" | sudo tee -a {conf_expr} >/dev/null'
    )


def _setup_server_one_rhel(s1, core_ip, db_port, db_pkg_path=None, db_pkg_name=None):
    """RHEL/Rocky Server One (DB box) setup — the dnf/PGDG/.noarch.rpm/systemctl/firewalld/
    /var/lib/pgsql mirror of the Debian _setup_server_one, per TAK Server Config Guide 5.7
    (pp.14-16) and the proven single-server RHEL install. The takserver-database .noarch.rpm
    is the DB installer (sets up the cot DB + martiuser, same role as the .deb); we install it,
    then verify + SELF-HEAL (postgresql-<major>-setup initdb + start if the rpm didn't) and configure
    remote access at the RHEL data dir. Heavily instrumented so the first live run shows exactly
    what the rpm did. All ops run over SSH on Server One (sudo there). Returns (ok, log, db_password)."""
    log = ['Server One detected as RHEL/Rocky family — using dnf / firewalld / systemctl / /var/lib/pgsql path.']
    # Defense-in-depth: core_ip is interpolated into root pg_hba/firewalld commands below.
    # _resolve_core_ip already validates it, but re-check at the sink so no future caller
    # can reach the shell interpolation with a non-IPv4 (injection-proofing).
    if not _valid_core_ip(core_ip):
        return False, log + ['Refusing to configure Server One: core IP is not a valid IPv4 address.'], ''
    # EL version + arch for the EPEL/PGDG repo URLs.
    _, _elv = _ssh_probe(s1, '. /etc/os-release 2>/dev/null; echo "${VERSION_ID%%.*}"', timeout=10)
    el_ver = (_elv or '').strip()
    el_ver = el_ver if el_ver in ('8', '9') else '9'
    _, _ar = _ssh_probe(s1, 'uname -m', timeout=10)
    el_arch = 'aarch64' if ('aarch64' in (_ar or '') or 'arm64' in (_ar or '')) else 'x86_64'
    # Reusable SSH snippets: discover the PG data dir + service name (PGDG postgresql-<major> vs base).
    # NB: /var/lib/pgsql is 0700 postgres-owned — the glob MUST run under sudo or it expands
    # to nothing as the SSH login user (the bug that bit the first run: empty PGDATA).
    PGDATA = _PG_REMOTE_PGDATA_SH
    PGSVC = _PG_REMOTE_PGSVC_SH

    # Step 1: repos — EPEL + PGDG (arch/EL-aware) + disable the system postgresql module + CRB.
    repo_cmd = (
        'sudo dnf -y install epel-release 2>&1 || '
        f'sudo dnf -y install https://dl.fedoraproject.org/pub/epel/epel-release-latest-{el_ver}.noarch.rpm 2>&1 || true; '
        f'sudo dnf -y install https://download.postgresql.org/pub/repos/yum/reporpms/EL-{el_ver}-{el_arch}/pgdg-redhat-repo-latest.noarch.rpm 2>&1 || true; '
        'sudo dnf -qy module disable postgresql 2>&1 || true; '
        'sudo dnf -y install dnf-plugins-core 2>&1 || true; '
        '(sudo dnf config-manager --set-enabled crb 2>/dev/null || sudo dnf config-manager --set-enabled powertools 2>/dev/null || true); '
        # GH #56: verify EPEL actually landed — the DB rpm's postgis deps (hdf5,
        # xerces-c) come from EPEL and fail with a misleading error without it.
        '(rpm -q epel-release >/dev/null 2>&1 && echo EPEL_OK || echo EPEL_MISSING); '
        'echo REPO_DONE'
    )
    _, rout = _ssh_probe(s1, repo_cmd, timeout=240)
    if 'EPEL_MISSING' in (rout or ''):
        log.append('⚠ EPEL repo NOT installed on Server One — the takserver-database rpm\'s '
                   'postgis dependencies (hdf5, xerces-c) will fail to resolve. On genuine RHEL run: '
                   f'sudo dnf -y install https://dl.fedoraproject.org/pub/epel/epel-release-latest-{el_ver}.noarch.rpm')
    log.append('Repos (EPEL/PGDG/CRB): ' + ('configured.' if 'REPO_DONE' in (rout or '') else ('warnings — ' + (rout or '')[:300])))

    # Step 2: install the takserver-database .noarch.rpm (the DB installer), unless already set up.
    if db_pkg_path and db_pkg_name:
        verify_cmd = (PGDATA + '; ' + PGSVC + '; '
                      'sudo -u postgres psql -lqt 2>/dev/null | grep -qw cot && '
                      'systemctl is-active "$PGSVC" >/dev/null 2>&1 && echo PG_OK')
        vok, vout = _ssh_probe(s1, verify_cmd, timeout=15)
        if vok and 'PG_OK' in (vout or ''):
            log.append('PostgreSQL already running and cot exists — skipping rpm install.')
        else:
            sok, sout = _scp_to_host(s1, db_pkg_path, '/tmp/', timeout=300)
            if not sok:
                log.append('SCP of database rpm failed: ' + (sout or ''))
                return False, log, ''
            log.append('Copied database rpm to /tmp/ on Server One.')
            install_cmd = f'cd /tmp && sudo dnf -y install ./{db_pkg_name} --setopt=clean_requirements_on_remove=false 2>&1; echo RC=$?'
            _, iout = _ssh_probe(s1, install_cmd, timeout=600)
            log.append('takserver-database rpm install output:')
            log.append((iout or '')[:1000])
    else:
        # No takserver-database package was supplied, so there is nothing to resolve
        # dependencies FROM and we have to name the packages ourselves.
        #
        # This is the ONLY place that does. Everywhere else — the native deploy and the
        # branch above — installs a TAK package and lets dnf/apt resolve, which is
        # strictly better: TAK's own packages declare exactly what they need, verified
        # 2026-09-02 by reading them:
        #
        #   takserver / takserver-database 5.8  ->  postgresql18-server postgresql18-contrib
        #                                           postgis36_18 postgis36_18-utils
        #   takserver / takserver-database 5.7  ->  postgresql15-server postgresql15-contrib
        #                                           postgis33_15 postgis33_15-utils
        #
        # So the vendor already answers "which PostgreSQL", per artifact, and any list we
        # hardcode is wrong for every other TAK version and goes stale at 5.9. Naming them
        # here is a fallback, not a policy — note it also has to include the -utils
        # subpackage the real dependency set carries, which the first version of this list
        # omitted. PostGIS is version-coupled per PG major (postgis33_15 vs postgis36_18),
        # so it cannot be derived from TAK_PG_MAJOR alone.
        _pgis = {18: 'postgis36_18', 15: 'postgis33_15'}.get(TAK_PG_MAJOR)
        _pkgs = 'postgresql%(m)d-server postgresql%(m)d-contrib' % {'m': TAK_PG_MAJOR}
        _full = (_pkgs + ' ' + _pgis + ' ' + _pgis + '-utils') if _pgis else _pkgs
        _, iout = _ssh_probe(s1, (
            'sudo dnf -y install ' + _full + ' 2>&1 || '
            'sudo dnf -y install ' + _pkgs + ' 2>&1; echo RC=$?'), timeout=600)
        log.append('PostgreSQL %d install (no database package supplied): %s'
                   % (TAK_PG_MAJOR, (iout or '')[:300]))

    # Step 3: ensure the cluster is INITIALIZED + STARTED (self-heal — the rpm may or may not have).
    init_cmd = (
        PGDATA + '; ' + PGSVC + '; '
        'if [ -z "$PGDATA" ] || [ ! -f "$PGDATA/PG_VERSION" ]; then '
        '  SETUP=$(ls /usr/pgsql-*/bin/postgresql-*-setup 2>/dev/null | sort -V | tail -1); '
        '  if [ -n "$SETUP" ]; then sudo "$SETUP" initdb 2>&1; else sudo postgresql-setup --initdb 2>&1; fi; '
        "  PGDATA=$(sudo sh -c 'ls -d /var/lib/pgsql/*/data 2>/dev/null' | sort -V | tail -1); [ -z \"$PGDATA\" ] && PGDATA=/var/lib/pgsql/data; "
        'fi; '
        'sudo systemctl enable "$PGSVC" 2>/dev/null; sudo systemctl start "$PGSVC" 2>&1; '
        'echo "PGDATA=$PGDATA PGSVC=$PGSVC ACTIVE=$(systemctl is-active "$PGSVC" 2>/dev/null)"'
    )
    _, nout = _ssh_probe(s1, init_cmd, timeout=120)
    log.append('PG init/start: ' + (nout or '')[:300])

    # Step 4: remote-access config (listen_addresses + pg_hba) at the RHEL data dir, then restart.
    cfg_cmd = (
        PGDATA + '; ' + PGSVC + '; '
        '[ -z "$PGDATA" ] && { echo NO_PGDATA; exit 0; }; '
        'sudo sed -i "/^[[:space:]]*#*[[:space:]]*listen_addresses[[:space:]]*=/d" "$PGDATA/postgresql.conf"; '
        "printf \"\\nlisten_addresses = '*'\\n\" | sudo tee -a \"$PGDATA/postgresql.conf\" >/dev/null; "
        + _pg_keepalive_sh('"$PGDATA/postgresql.conf"') + '; ' +
        'sudo sed -i "s/md5host/md5\\nhost/g" "$PGDATA/pg_hba.conf"; '
        # v10.1.9 W1: fresh splits get hostssl+SCRAM (encrypted wire); retrofit boxes keep their
        # existing plaintext line here — _enable_server_one_db_tls handles their upgrade.
        f'grep -q "^host.*{core_ip}/32" "$PGDATA/pg_hba.conf" 2>/dev/null || '
        f'printf "\\nhostssl all all {core_ip}/32 scram-sha-256\\n" | sudo tee -a "$PGDATA/pg_hba.conf" >/dev/null; '
        'sudo systemctl restart "$PGSVC" 2>&1; echo "ACTIVE=$(systemctl is-active "$PGSVC" 2>/dev/null)"'
    )
    _, cout = _ssh_probe(s1, cfg_cmd, timeout=40)
    if 'NO_PGDATA' in (cout or '') or 'ACTIVE=active' not in (cout or ''):
        log.append('PostgreSQL remote-access config FAILED: ' + (cout or '')[:300])
        _, diag = _ssh_probe(s1, (
            PGDATA + '; ' + PGSVC + '; echo "--- pgdata=$PGDATA svc=$PGSVC ---"; '
            'sudo ls -la "$PGDATA" 2>&1 | head -6; echo "--- journal ---"; '
            'sudo journalctl -u "$PGSVC" -n 25 --no-pager 2>&1 | tail -25; echo "--- rpm -qa postgres/takserver ---"; '
            'rpm -qa 2>/dev/null | grep -iE "postgres|postgis|takserver" | head'), timeout=25)
        log.append('Diagnostics from Server One:')
        log.append((diag or '')[:1400])
        return False, log, ''
    log.append(f'PostgreSQL configured: listen_addresses=*, pg_hba host {core_ip}, service active.')

    # Step 5: firewalld — open db_port FROM the core IP only (+ ssh); drop any broad port-open.
    fw_cmd = (
        'sudo systemctl enable --now firewalld 2>/dev/null || true; '
        'sudo firewall-cmd --permanent --add-service=ssh 2>/dev/null || true; '
        f'sudo firewall-cmd --permanent --add-rich-rule="rule family=\'ipv4\' source address=\'{core_ip}\' port protocol=\'tcp\' port=\'{db_port}\' accept" 2>&1 || true; '
        f'sudo firewall-cmd --permanent --remove-port={db_port}/tcp 2>/dev/null || true; '
        'sudo firewall-cmd --reload 2>&1; echo FW_DONE'
    )
    _, fout = _ssh_probe(s1, fw_cmd, timeout=40)
    log.append('firewalld: ' + ('db port scoped to core, ssh allowed.' if 'FW_DONE' in (fout or '') else (fout or '')[:200]))

    # Step 5b: make sure the cot DB and martiuser actually EXIST.
    #
    # The takserver-database rpm only provisions them as part of its initdb; on a host
    # that ALREADY has a PostgreSQL cluster the install prints "Data directory is not
    # empty!", skips that work, and leaves no role and no database — while every step
    # after it carries on. Measured on dev5 2026-09-04 (a box with a pre-existing PG18
    # cluster): the deploy reported success with `db_password_captured: true`, and the
    # server had `postgres template0 template1` and exactly one role. A redeploy, or any
    # box that has ever run PostgreSQL, lands here.
    #
    # TAK ships the fix: db-utils/takserver-setup-db.sh, which their own comments call a
    # manual post-install step. Run it when, and only when, the role or database is absent.
    _need_sql = ("sudo -u postgres psql -tAXc \"select count(*) from pg_roles where "
                 "rolname='martiuser'\" 2>/dev/null; "
                 "sudo -u postgres psql -tAXc \"select count(*) from pg_database where "
                 "datname='cot'\" 2>/dev/null")
    _, _need_out = _ssh_probe(s1, _need_sql, timeout=30)
    _need = [t for t in (_need_out or '').split() if t.isdigit()]
    if len(_need) < 2 or _need[0] == '0' or _need[1] == '0':
        log.append('cot database or martiuser missing after the rpm install (this host already '
                   'had a PostgreSQL cluster, so the rpm skipped its own setup) — running TAK\'s '
                   'takserver-setup-db.sh.')
        # `-f`, not `-x`: TAK ships db-utils scripts mode 0544, so they are executable by
        # root and NOT by the SSH user doing the test — the guard reported
        # NO_SETUP_DB_SCRIPT for a script that was sitting right there (dev5, 2026-09-04).
        # Same upstream packaging habit as the container bundle's missing execute bits.
        # Run it through `sudo bash` so the mode does not matter, and with stdin closed so
        # a prompt cannot hang the deploy.
        _, _setup_out = _ssh_probe(s1, (
            'if [ -f /opt/tak/db-utils/takserver-setup-db.sh ]; then '
            'cd /opt/tak/db-utils && sudo bash ./takserver-setup-db.sh </dev/null 2>&1 | tail -14; '
            'else echo NO_SETUP_DB_SCRIPT; fi'), timeout=600)
        log.append('takserver-setup-db.sh: ' + (_setup_out or '')[:400])
        _, _need_out = _ssh_probe(s1, _need_sql, timeout=30)
        _need = [t for t in (_need_out or '').split() if t.isdigit()]
        if len(_need) < 2 or _need[0] == '0' or _need[1] == '0':
            log.append('✗ Server One still has no martiuser role and/or no cot database. The core '
                       'cannot use this database, so stopping here rather than handing back a '
                       'server that will fail at first login.')
            return False, log, ''
        log.append('✓ cot database and martiuser now present on Server One.')

    # Step 6: capture + verify the DB password (platform-neutral helpers — already work on RHEL).
    db_password, _ = _fetch_db_password_from_server_one(s1)
    if db_password:
        log.append('Captured DB password from Server One.')
        pw_ok, pw_msg = _verify_server_one_db_password(s1, db_password, db_port=db_port)
        log.append('DB credential verified on Server One.' if pw_ok else f'Warning: captured password failed validation ({pw_msg}).')
    else:
        log.append('Warning: could not read DB password from Server One CoreConfig.')

    # Step 7: build the TAK schema (RHEL-only). The .noarch.rpm deliberately does NOT run
    # SchemaManager — its own takserver-setup-db.sh says it "cannot be run by the RPM installer
    # and must be a manual post-install step." (The Debian .deb's postinst DOES build the schema,
    # which is why the .deb split never needed this.) Without it the cot DB comes up with the
    # martiuser role + database but ZERO tables, so the core 500s on /oauth/token ("relation
    # group_bitpos_sequence does not exist") and 8446 login fails. Run SchemaManager explicitly
    # (idempotent 'upgrade' — reports "up to date" on re-runs; java + SchemaManager.jar both ship
    # with takserver-database). Field-validated on aws-rocky1: 93 updates, cot 0→60 tables.
    if db_pkg_path and db_password:
        schema_cmd = (
            'if [ -f /opt/tak/db-utils/SchemaManager.jar ]; then '
            'cd /opt/tak/db-utils && sudo java -jar SchemaManager.jar '
            f'-url jdbc:postgresql://127.0.0.1:{db_port}/cot -user martiuser '
            f'-password {shlex.quote(db_password)} upgrade 2>&1 | tail -8; '
            'else echo NO_SCHEMA_MANAGER; fi'
        )
        _, scout = _ssh_probe(s1, schema_cmd, timeout=240)
        if 'up to date' in (scout or '') or 'Successfully applied' in (scout or ''):
            log.append('TAK schema built on Server One (SchemaManager upgrade).')
        else:
            log.append('WARNING: TAK schema build did not confirm — the cot DB may have no tables '
                       '(8446 login will 500). Output: ' + (scout or '')[:400])
    # Step 8 (v10.1.9 W1): encrypt the core↔DB wire — TLS + SCRAM (CJIS in-transit).
    tls_pem = _server_one_tls_step(s1, core_ip, db_password, log)

    # Final gate. Everything above logs warnings and carries on, and this function used to
    # `return True` regardless — so a Server One with no martiuser, no tables and a password
    # that failed validation was handed back as a success, and the operator only found out
    # when the core 500'd at login. Ask the database instead: the role, the database, and
    # actual tables in it.
    _, _final = _ssh_probe(s1, (
        "sudo -u postgres psql -tAXc \"select count(*) from pg_roles where rolname='martiuser'\" "
        "2>/dev/null; "
        "sudo -u postgres psql -tAX -d cot -c \"select count(*) from information_schema.tables "
        "where table_schema='public'\" 2>/dev/null"), timeout=40)
    _vals = [t for t in (_final or '').split() if t.isdigit()]
    _roles = int(_vals[0]) if len(_vals) > 0 else 0
    _tables = int(_vals[1]) if len(_vals) > 1 else 0
    log.append(f'Server One verification: martiuser={"present" if _roles else "MISSING"}, '
               f'cot public tables={_tables}.')
    if not _roles or _tables < 1:
        log.append('✗ Server One is not usable as a TAK database: the core would fail at first '
                   'login with "relation ... does not exist". Fix this before deploying Server Two.')
        return False, log, db_password, tls_pem
    return True, log, db_password, tls_pem


# ==========================================================================
# v10.1.27 (item C) — ONE spelling of the PGDG apt source, product-wide
# ==========================================================================
# The two-server Server One path used to write
#   /etc/apt/sources.list.d/postgresql.list  signed-by=/etc/apt/keyrings/postgresql.asc
# while the single-box TAK deploy wrote
#   /etc/apt/sources.list.d/pgdg.list        signed-by=/usr/share/keyrings/pgdg.asc
# A box that was ever a Server One (or where the operator ran our runbook) then
# BRICKED apt on a later single-box deploy: apt normalises the URL difference,
# sees one repo configured two ways with different Signed-By values, and refuses
# to read ANY source — every apt operation on the box fails, not just ours.
# Same filename, same keyring, everywhere — and skip entirely when the box
# already has PGDG configured by someone else.
_PGDG_APT_HOST = 'apt.postgresql.org'
_PGDG_LIST = '/etc/apt/sources.list.d/pgdg.list'
_PGDG_KEYRING = '/usr/share/keyrings/pgdg.asc'
_PGDG_KEY_URL = 'https://www.postgresql.org/media/keys/ACCC4CF8.asc'

# Shell fragment for the REMOTE (Server One over SSH) path. Ends with '&& ' so it
# drops into the existing && chains. Idempotent and conflict-aware.
_PGDG_REMOTE_SETUP_SH = (
    'sudo mkdir -p /usr/share/keyrings && '
    f'if ! grep -rqs "{_PGDG_APT_HOST}" /etc/apt/sources.list /etc/apt/sources.list.d/ 2>/dev/null; then '
    f'sudo curl -sL {_PGDG_KEY_URL} --output {_PGDG_KEYRING} && '
    # v10.3.0 W1: codename from /etc/os-release, lsb_release fallback, and REFUSE on
    # empty — a bare $(lsb_release -cs) on a noble minimal image expands to nothing and
    # writes "apt -pgdg main", which apt then rejects for every source on the box.
    f'cn={_APT_CODENAME_SH} && '
    '( [ -n "$cn" ] || { echo "cannot determine the apt codename of this host (no VERSION_CODENAME, no lsb_release)" >&2; false; } ) && '
    f'echo "deb [signed-by={_PGDG_KEYRING}] https://{_PGDG_APT_HOST}/pub/repos/apt ${{cn}}-pgdg main" '
    f'| sudo tee {_PGDG_LIST} >/dev/null; '
    'else echo "PGDG apt source already configured on this host - reusing it"; fi && '
)


def _setup_server_one(s1, core_ip, db_port, db_pkg_path=None, db_pkg_name=None):
    """Full Server One setup: optionally install DB .deb, configure PG for remote access, open UFW.
    Returns (ok, log_lines, db_password).
    """
    log = []
    # Defense-in-depth: core_ip is interpolated into root pg_hba/UFW commands on Server One
    # (and the RHEL branch below). _resolve_core_ip validates it; re-check at the sink so no
    # caller can reach the shell interpolation with a non-IPv4 value (injection-proofing).
    if not _valid_core_ip(core_ip):
        return False, ['Refusing to configure Server One: core IP is not a valid IPv4 address.'], ''
    # v10.0.5: the DB box (Server One) can be a DIFFERENT OS family than the console. Detect its
    # OS over SSH and dispatch to the RHEL/Rocky path (dnf/PGDG/.noarch.rpm/systemctl/firewalld/
    # /var/lib/pgsql) — mirrors the Debian steps below per TAK Config Guide 5.7 + the proven
    # single-server RHEL install. Default stays Debian (byte-identical to the original path).
    _fam_ok, _fam = _ssh_probe(s1, '. /etc/os-release 2>/dev/null; echo "${ID} ${ID_LIKE}"', timeout=12)
    if _fam_ok and any(t in (_fam or '').lower() for t in ('rhel', 'rocky', 'almalinux', 'centos', 'fedora')):
        return _setup_server_one_rhel(s1, core_ip, db_port, db_pkg_path, db_pkg_name)
    # Kill stale apt/dpkg locks and fix broken packages from interrupted installs.
    apt_unlock = (
        'sudo killall -q apt-get dpkg unattended-upgr 2>/dev/null; '
        'for i in 1 2 3 4 5 6; do '
        'fuser /var/lib/dpkg/lock /var/lib/apt/lists/lock /var/cache/apt/archives/lock >/dev/null 2>&1 || break; '
        'echo "Waiting for apt lock ($i)…"; sleep 5; done; '
        'sudo rm -f /var/lib/dpkg/lock /var/lib/dpkg/lock-frontend /var/lib/apt/lists/lock /var/cache/apt/archives/lock 2>/dev/null; '
        'dpkg -l takserver-database 2>/dev/null | grep -q "^..[rR]" && '
        'sudo dpkg --force-remove-reinstreq --remove takserver-database 2>/dev/null; '
        'sudo dpkg --configure -a 2>/dev/null; '
        'sudo apt-get -f install -y 2>/dev/null; true'
    )
    _ssh_probe(s1, apt_unlock, timeout=60)

    # Step 1: SCP and install the database .deb if provided
    if db_pkg_path and db_pkg_name:
        # Fix any corrupted pg_hba.conf before trying to start PG
        _ssh_probe(s1, (
            'PG_MAIN=$(find /etc/postgresql -type d -name main 2>/dev/null | head -1); '
            '[ -n "$PG_MAIN" ] && [ -f "$PG_MAIN/pg_hba.conf" ] && '
            'sudo sed -i "s/md5host/md5\\nhost/g" "$PG_MAIN/pg_hba.conf" 2>/dev/null; true'
        ), timeout=10)
        _ssh_probe(s1, 'sudo pg_ctlcluster 15 main start 2>/dev/null; true', timeout=20)
        already_ok = False
        verify_cmd = 'sudo -u postgres psql -lqt 2>/dev/null | grep -q cot && systemctl is-active postgresql >/dev/null 2>&1 && echo PG_OK'
        vok, vout = _ssh_probe(s1, verify_cmd, timeout=10)
        if vok and 'PG_OK' in (vout or ''):
            already_ok = True
            log.append('PostgreSQL already running and cot database exists — skipping install.')

        if not already_ok:
            ok, out = _scp_to_host(s1, db_pkg_path, '/tmp/', timeout=300)
            if not ok:
                return False, ['SCP failed: ' + (out or '')], ''
            log.append('Copied database package to Server One /tmp/')

            install_cmd = (
                'cd /tmp && sudo apt-get update -qq && '
                'sudo apt-get install -y lsb-release && '
                + _PGDG_REMOTE_SETUP_SH +
                'sudo apt-get update -qq && '
                f'sudo DEBIAN_FRONTEND=noninteractive apt-get install -y ./{db_pkg_name}'
            )
            ok, out = _ssh_probe(s1, install_cmd, timeout=600)
            log.append(out or '')
            if not ok:
                _ssh_probe(s1, 'sudo pg_ctlcluster 15 main start 2>/dev/null; true', timeout=20)
                vok, vout = _ssh_probe(s1, verify_cmd, timeout=10)
                if not (vok and 'PG_OK' in (vout or '')):
                    diag_cmd = (
                        'echo "--- cluster start attempt ---"; '
                        'sudo pg_ctlcluster 15 main start 2>&1; '
                        'echo "--- cluster logs ---"; '
                        'sudo cat /var/lib/postgresql/15/main/log/$(ls -t /var/lib/postgresql/15/main/log/ 2>/dev/null | head -1) 2>/dev/null | tail -30 || echo "no cluster logs"; '
                        'echo "--- postgresql.conf listen ---"; '
                        'grep -n listen_addresses /etc/postgresql/15/main/postgresql.conf 2>/dev/null; '
                        'echo "--- pg_hba.conf ---"; '
                        'cat /etc/postgresql/15/main/pg_hba.conf 2>/dev/null | grep -v "^#" | grep -v "^$"'
                    )
                    _, diag = _ssh_probe(s1, diag_cmd, timeout=20)
                    log.append('Install failed. Diagnostics from Server One:')
                    log.append(diag or 'no diagnostic output')
                    return False, log, ''
                log.append('Install had warnings but PostgreSQL is running and cot database exists.')
            log.append('TAK database package installed.')
    else:
        # No .deb provided — check if PG is already installed, if not install vanilla PG
        check_cmd = 'dpkg -l 2>/dev/null | grep -ci postgres'
        ok, out = _ssh_probe(s1, check_cmd, timeout=10)
        pg_count = int((out or '0').strip()) if ok else 0
        if pg_count == 0:
            pg_install = (
                'sudo apt-get update -qq && '
                'sudo apt-get install -y lsb-release && '
                + _PGDG_REMOTE_SETUP_SH +
                'sudo apt-get update -qq && '
                'sudo DEBIAN_FRONTEND=noninteractive apt-get install -y '
                'postgresql-%d postgresql-%d-postgis-3' % (TAK_PG_MAJOR, TAK_PG_MAJOR)
            )
            ok, out = _ssh_probe(s1, pg_install, timeout=300)
            log.append(out or '')
            if not ok:
                log.append('PostgreSQL install failed on Server One.')
                return False, log, ''
            log.append('PostgreSQL installed on Server One.')

    # Step 2: Configure PostgreSQL for remote access
    # Fix any previously corrupted pg_hba.conf lines (e.g. "md5host" from missing newline)
    pg_config_cmd = (
        'PG_MAIN=$(find /etc/postgresql -type d -name main 2>/dev/null | head -1) && '
        '[ -n "$PG_MAIN" ] && [ -f "$PG_MAIN/postgresql.conf" ] && '
        "sudo sed -i '/^\\s*#*\\s*listen_addresses\\s*=/d' \"$PG_MAIN/postgresql.conf\" && "
        "printf \"\\nlisten_addresses = '*'\\n\" | sudo tee -a \"$PG_MAIN/postgresql.conf\" > /dev/null && "
        + _pg_keepalive_sh('"$PG_MAIN/postgresql.conf"') + ' && ' +
        'sudo sed -i "s/md5host/md5\\nhost/g" "$PG_MAIN/pg_hba.conf" && '
        # v10.1.9 W1: fresh splits get hostssl+SCRAM (encrypted wire); retrofit boxes keep their
        # existing plaintext line here — _enable_server_one_db_tls handles their upgrade.
        f'(grep -q "^host.*{core_ip}/32" "$PG_MAIN/pg_hba.conf" 2>/dev/null || '
        f'printf "\\nhostssl all all {core_ip}/32 scram-sha-256\\n" | sudo tee -a "$PG_MAIN/pg_hba.conf" > /dev/null) && '
        '(sudo pg_ctlcluster 15 main restart 2>/dev/null || sudo systemctl restart postgresql 2>/dev/null || true)'
    )
    ok, out = _ssh_probe(s1, pg_config_cmd, timeout=30)
    if not ok:
        log.append('PostgreSQL remote-access config failed: ' + (out or ''))
        return False, log, ''
    log.append('PostgreSQL configured: listen_addresses=* and pg_hba entry for ' + core_ip)

    # Step 3: UFW — v0.9.12 hardening: drop unconditional `allow {db_port}/tcp`
    # (defeated the source-scoped allow above and exposed Postgres to the public
    # internet). Postgres only needs to be reachable from Server Two's IP. Same
    # class of bug as the v0.9.11 CloudTAK 5433 incident — except UFW is
    # actually effective here (native Postgres, not Docker-published).
    # Also add an explicit `deny {db_port}/tcp` belt-and-braces so a future
    # `ufw allow` of that port (e.g. by an operator script) doesn't reopen the
    # surface unless the source-scope rule is matched first.
    # v0.9.46: delete any legacy broad `allow {db_port}/tcp` (pre-v0.9.12 boxes still
    # carry one; UFW is first-match-wins so it shadows the deny below, leaving Postgres
    # open to the internet). Delete runs AFTER the scoped allow so the core never loses
    # its DB; `delete allow` only removes the Anywhere rule, scoped allows survive.
    # ORDER: delete any pre-existing deny FIRST (UFW appends + first-match-wins, so a
    # stale deny would shadow the scoped allow), add the scoped allow, drop the broad
    # allow, then re-add the deny LAST so it sits below the allow.
    ufw_cmd = (
        f'sudo ufw allow 22/tcp && '
        f'sudo ufw allow from {core_ip} to any port 22 proto tcp && '
        f'(sudo ufw delete deny {db_port}/tcp || true) && '
        f'sudo ufw allow from {core_ip} to any port {db_port} proto tcp && '
        f'(sudo ufw delete allow {db_port}/tcp || true) && '
        f'sudo ufw deny {db_port}/tcp && '
        'sudo ufw --force enable && sudo ufw reload'
    )
    ok, out = _ssh_probe(s1, ufw_cmd, timeout=25)
    if not ok:
        log.append('UFW config failed: ' + (out or ''))
        return False, log, ''
    log.append(f'UFW: allowed {core_ip} → port {db_port}, denied all other sources (v0.9.12 hardening)')

    # Step 4: Read auto-generated DB password from Server One (try multiple sources)
    db_password, _ = _fetch_db_password_from_server_one(s1)
    if db_password:
        log.append('Captured DB password from Server One.')
        pw_ok, pw_msg = _verify_server_one_db_password(s1, db_password, db_port=db_port)
        if pw_ok:
            log.append('DB credential verified on Server One.')
        else:
            log.append(f'Warning: captured password failed validation ({pw_msg}). '
                       'Use Sync DB Password after deploy if TAK Server cannot connect.')
    else:
        log.append('Warning: could not read DB password from Server One — CoreConfig may need manual password fix.')

    # Step 5 (v10.1.9 W1): encrypt the core↔DB wire — TLS + SCRAM (CJIS in-transit).
    tls_pem = _server_one_tls_step(s1, core_ip, db_password, log)

    # Same final gate as the RHEL path: every step above logs warnings and carries on, so
    # without this a Server One with no martiuser and no tables is handed back as a
    # success and the operator finds out when the core 500s at login. Ask the database.
    _, _final = _ssh_probe(s1, (
        "cd /tmp && sudo -u postgres psql -tAXc \"select count(*) from pg_roles where "
        "rolname='martiuser'\" 2>/dev/null; "
        "cd /tmp && sudo -u postgres psql -tAX -d cot -c \"select count(*) from "
        "information_schema.tables where table_schema='public'\" 2>/dev/null"), timeout=40)
    _vals = [t for t in (_final or '').split() if t.isdigit()]
    _roles = int(_vals[0]) if len(_vals) > 0 else 0
    _tables = int(_vals[1]) if len(_vals) > 1 else 0
    log.append(f'Server One verification: martiuser={"present" if _roles else "MISSING"}, '
               f'cot public tables={_tables}.')
    if not _roles or _tables < 1:
        log.append('✗ Server One is not usable as a TAK database: the core would fail at first '
                   'login with "relation ... does not exist". Fix this before deploying Server Two.')
        return False, log, db_password, tls_pem
    return True, log, db_password, tls_pem


def _redact_db_secret(text, secret=None):
    """Strip DB passwords out of captured command output before it reaches a log
    or an API response. psql echoes the offending statement on error, so a failed
    `ALTER USER … PASSWORD 'x'` would otherwise leak the credential into journald
    and into the deploy log the browser receives."""
    out = text or ''
    if secret:
        out = out.replace(secret, '***')
    # Belt and braces: redact any PASSWORD '…' / PGPASSWORD=… shape we didn't expect.
    out = re.sub(r"(?i)(password\s+')[^']*(')", r'\1***\2', out)
    out = re.sub(r'(?i)(PGPASSWORD=)\S+', r'\1***', out)
    return out


def _enable_server_one_db_tls(s1, core_ip, db_password=None, remove_plaintext=False):
    """Enable PostgreSQL native TLS + SCRAM on Server One (the split-deploy DB box) over SSH.
    Idempotent — safe to re-run on every deploy/retrofit pass. Pairs with the CoreConfig
    sslEnabled/sslMode/sslRootCert attributes per TAK Server Config Guide Appendix D:
      1. self-signed 10y cert in the PG data dir, SAN = the exact host the core box dials
         (sslMode=verify-full on the JDBC side pins it)
      2. postgresql.conf managed lines (# infra-TAK-dbtls): ssl=on, cert paths,
         password_encryption=scram-sha-256
      3. pg_hba: hostssl <core_ip>/32 scram-sha-256 inserted ABOVE any plaintext host line;
         the plaintext line is dropped only when remove_plaintext=True — the retrofit path
         removes it only AFTER verifying the TLS connection live, never before
      4. re-hash martiuser to SCRAM (needs db_password; PG15 default hashing is already
         SCRAM on both families, this converges pre-15-era md5 stragglers)
    Returns (ok, log_lines, cert_pem). cert_pem='' on failure — callers MUST treat that as
    'leave CoreConfig untouched'; pointing TAK at a cert we failed to capture kills the DB link."""
    log = []
    if not _valid_core_ip(core_ip):
        return False, ['DB TLS: core IP failed validation, refusing shell interpolation.'], ''
    s1_host = (s1.get('host') or '').strip()
    if not re.fullmatch(r'[A-Za-z0-9.\-]{1,253}', s1_host or ''):
        return False, ['DB TLS: Server One host failed validation, refusing shell interpolation.'], ''
    is_ip = bool(re.fullmatch(r'\d{1,3}(\.\d{1,3}){3}', s1_host))
    san = f'IP:{s1_host}' if is_ip else f'DNS:{s1_host}'

    # v10.1.9 W1 FIX (found on the first fresh two-server DEPLOY, AWS 2026-07-25):
    # the hostssl rule must name the address Server One ACTUALLY sees the core
    # arrive from — which is NOT necessarily settings['server_ip'].
    #
    # `_resolve_core_ip()` returns the box's PUBLIC address. That is right when the
    # split is addressed publicly (SSD Nodes class, where the two boxes talk over
    # the internet), and WRONG whenever Server One is addressed privately: on AWS
    # with Server One at 172.31.41.4 the core arrives from 172.31.43.128, so a
    # `hostssl <public>/32` rule never matches and the connection silently falls
    # through to TAK's own stock `host all martiuser 0.0.0.0/0 md5`. Traffic still
    # ended up encrypted (the JDBC side pins verify-full), but ONLY client-side —
    # the server was not requiring it, so a CoreConfig reset by a TAK upgrade would
    # silently downgrade the link to cleartext with nothing to notice.
    #
    # Server One already knows the answer: sshd sets $SSH_CLIENT on the session the
    # console is driving, and that is the source address AFTER any NAT. Union it
    # with core_ip so both the private and public routes are covered. Same
    # `$SSH_CLIENT ∪ server_ip` shape that fixed the Guard Dog health agent.
    core_ips = []
    src_ok, src_out = _ssh_probe(s1, 'echo "SRC=${SSH_CLIENT%% *}"', timeout=20)
    if src_ok:
        for _line in (src_out or '').splitlines():
            if _line.startswith('SRC='):
                _cand = _line.split('=', 1)[1].strip()
                if _valid_core_ip(_cand):
                    core_ips.append(_cand)
                break
    if core_ip not in core_ips:
        core_ips.append(core_ip)          # always keep the configured/public route

    # Delete-then-insert each, ALWAYS, so placement is corrected on every run and
    # never left below a broader rule (pg_hba is first-match-wins).
    hba_cmd = ''
    for _ip in core_ips:
        _ip_sed = _ip.replace('.', r'\.')
        hba_cmd += (
            f'sudo sed -i -E "/^hostssl[[:space:]]+all[[:space:]]+all[[:space:]]+{_ip_sed}\\/32/d" "$HBA"; '
            f'if sudo grep -Eq "^(host|hostssl|hostnossl|local)[[:space:]]" "$HBA"; then '
            f'sudo sed -i "0,/^\\(host\\|hostssl\\|hostnossl\\|local\\)[[:space:]]/s//hostssl all all {_ip}\\/32 scram-sha-256\\n&/" "$HBA"; '
            f'else printf "\\nhostssl all all {_ip}/32 scram-sha-256\\n" | sudo tee -a "$HBA" >/dev/null; fi; '
        )

    cfg_cmd = (
        'DATA=$(sudo -u postgres psql -tAc "show data_directory" 2>/dev/null); '
        'CONF=$(sudo -u postgres psql -tAc "show config_file" 2>/dev/null); '
        'HBA=$(sudo -u postgres psql -tAc "show hba_file" 2>/dev/null); '
        '{ [ -z "$DATA" ] || [ -z "$CONF" ] || [ -z "$HBA" ]; } && { echo NO_PG; exit 0; }; '
        'if ! sudo test -s "$DATA/infratak-db.crt"; then '
        'sudo openssl req -x509 -newkey rsa:4096 -sha256 -days 3650 -nodes '
        '-keyout "$DATA/infratak-db.key" -out "$DATA/infratak-db.crt" '
        f'-subj "/CN={s1_host}" -addext "subjectAltName={san}" >/dev/null 2>&1 '
        '&& sudo chown postgres:postgres "$DATA/infratak-db.key" "$DATA/infratak-db.crt" '
        '&& sudo chmod 600 "$DATA/infratak-db.key" && sudo chmod 644 "$DATA/infratak-db.crt" '
        '&& echo CERT_GENERATED || echo CERT_FAILED; else echo CERT_EXISTS; fi; '
        # Managed config lines: delete-then-append keeps this idempotent across re-runs.
        'sudo sed -i "/# infra-TAK-dbtls$/d" "$CONF"; '
        'printf "ssl = on # infra-TAK-dbtls\\n'
        'ssl_cert_file = \'%s/infratak-db.crt\' # infra-TAK-dbtls\\n'
        'ssl_key_file = \'%s/infratak-db.key\' # infra-TAK-dbtls\\n'
        'password_encryption = scram-sha-256 # infra-TAK-dbtls\\n" "$DATA" "$DATA" '
        '| sudo tee -a "$CONF" >/dev/null; '
        # hostssl must go ABOVE **every** existing host rule, not just an exact
        # <core_ip>/32 match. pg_hba is first-match-wins, and real boxes carry
        # broader rules (test8's Server One had `host all martiuser 0.0.0.0/0 md5`)
        # that would otherwise match the core box first and make our line dead
        # code. Insert before the FIRST host/hostssl/local rule in the file.
        # Delete-then-insert, ALWAYS. An existing hostssl line is not good enough —
        # a line appended at the BOTTOM (what earlier code did, and what test8 was
        # left carrying) sits below broader rules and is never consulted. Removing
        # ours first and re-inserting at the top makes placement correct on every
        # run, not just the first.
        + hba_cmd +
        'sudo -u postgres psql -qc "select pg_reload_conf();" >/dev/null 2>&1; '
        'echo "SSL=$(sudo -u postgres psql -tAc "show ssl" 2>/dev/null)"'
    )
    ok, out = _ssh_probe(s1, cfg_cmd, timeout=90)
    out = out or ''
    if 'NO_PG' in out:
        return False, ['DB TLS: PostgreSQL not reachable on Server One (could not resolve data dir).'], ''
    if 'CERT_FAILED' in out:
        return False, ['DB TLS: certificate generation failed on Server One: ' + out[:300]], ''
    if 'SSL=on' not in out:
        return False, ['DB TLS: ssl did not report on after reload: ' + out[:300]], ''
    log.append('DB TLS: cert %s, ssl=on, hostssl %s scram-sha-256 in pg_hba.'
               % ('generated' if 'CERT_GENERATED' in out else 'already present',
                  ', '.join(f'{_i}/32' for _i in core_ips)))
    if len(core_ips) > 1:
        log.append('DB TLS: Server One sees the core arrive from %s; %s (configured) also allowed.'
                   % (core_ips[0], core_ips[-1]))

    if db_password:
        sql = "ALTER USER martiuser WITH PASSWORD '" + db_password.replace("'", "''") + "'"
        rok, rout = _ssh_probe(s1, 'sudo -u postgres psql -qc ' + shlex.quote(sql) + ' && echo REHASHED', timeout=30)
        if rok and 'REHASHED' in (rout or ''):
            log.append('DB TLS: martiuser re-hashed to SCRAM.')
        else:
            # NEVER echo psql's output raw: on a syntax error psql quotes the failing
            # statement back ("LINE 1: ALTER USER … PASSWORD 'secret'"), and this log
            # goes to journald AND into the deploy's JSON response. CJIS: secrets are
            # never logged (same rule the broker's _summary redaction enforces).
            log.append('DB TLS warning: martiuser SCRAM re-hash did not confirm — '
                       + _redact_db_secret(rout or '', db_password)[:200])

    if remove_plaintext:
        # Only the retrofit calls this, and only after verifying a live TLS connection.
        #
        # We remove ONLY the exact `<core_ip>/32` line infra-TAK itself wrote. We do
        # NOT touch broader operator rules (e.g. `host all martiuser 0.0.0.0/0 md5`,
        # found live on test8's Server One) — other consumers may depend on them and
        # silently deleting an operator's ACL could take them down. Instead we DETECT
        # any remaining non-TLS rule that still admits the core box and surface it
        # loudly, because while one exists the plaintext path is not actually closed.
        # v10.1.9 W1 FIX: ALSO drop TAK Server's own stock permissive rule.
        # `host all martiuser 0.0.0.0/0 md5` appeared on a BRAND-NEW Server One
        # minutes after a fresh deploy, with no human ever touching its pg_hba
        # (AWS two-server validation, 2026-07-25) — and `git log -S'0.0.0.0/0'`
        # proves infra-TAK has never written one. So it is TAK's own db-setup
        # artifact present on every split box, NOT an operator ACL, which is what
        # makes removing it safe. Anything we do NOT recognise is still left alone
        # and reported. Only ever reached with remove_plaintext=True, which the
        # retrofit sets solely AFTER verifying a live TLS connection.
        stock = r'^host[[:space:]]+all[[:space:]]+(martiuser|all)[[:space:]]+0\.0\.0\.0/0[[:space:]]'
        # The pattern contains a literal '/' (0.0.0.0/0), which would terminate a
        # sed /addr/ delimiter — escape it for sed, leave it plain for grep.
        stock_sed = stock.replace('/', r'\/')
        _sed_ips = [ip.replace('.', r'\.') for ip in core_ips]
        dels = ''.join(
            f'sudo sed -i -E "/^host[[:space:]]+.*{s}\\/32/d" "$HBA"; ' for s in _sed_ips)
        counts = ' + '.join(
            f'$(sudo grep -cE "^host[[:space:]]+.*{s}/32" "$HBA" || true)' for s in _sed_ips)
        rm_cmd = (
            'HBA=$(sudo -u postgres psql -tAc "show hba_file" 2>/dev/null); '
            '[ -z "$HBA" ] && { echo NO_PG; exit 0; }; '
            # Back up before ANY edit — this file is the box's access control.
            'sudo cp -a "$HBA" "$HBA.takwerx-bak" 2>/dev/null; '
            # Count what we actually delete — claiming "plaintext removed" when the
            # sed matched nothing is a false success report (test8: there was never
            # a /32 line, yet the migration announced it had removed one).
            f'N=$(( {counts} )); '
            f'S=$(sudo grep -cE \'{stock}\' "$HBA" || true); '
            + dels +
            f'sudo sed -i -E "/{stock_sed}/d" "$HBA"; '
            'sudo -u postgres psql -qc "select pg_reload_conf();" >/dev/null 2>&1; '
            'echo "PLAINTEXT_REMOVED=$N"; '
            'echo "STOCK_REMOVED=$S"; '
            # Anything still `host` (not hostssl) that isn't loopback-only is a
            # residual cleartext path to this database.
            'echo RESIDUAL_START; '
            'sudo grep -E "^host[[:space:]]" "$HBA" | grep -vE "127\\.0\\.0\\.1/32|::1/128" || true; '
            'echo RESIDUAL_END'
        )
        rok, rout = _ssh_probe(s1, rm_cmd, timeout=30)
        out_s = rout or ''
        if rok and 'PLAINTEXT_REMOVED=' in out_s:
            nrem = out_s.split('PLAINTEXT_REMOVED=', 1)[1].split('\n', 1)[0].strip()
            _ips_txt = ', '.join(core_ips)
            log.append('DB TLS: removed %s plaintext pg_hba line(s) for %s.' % (nrem, _ips_txt)
                       if nrem not in ('', '0') else
                       'DB TLS: no dedicated plaintext pg_hba line for %s existed to remove.' % _ips_txt)
            srem = (out_s.split('STOCK_REMOVED=', 1)[1].split('\n', 1)[0].strip()
                    if 'STOCK_REMOVED=' in out_s else '')
            if srem not in ('', '0'):
                log.append("DB TLS: removed %s of TAK Server's own stock `host all <user> 0.0.0.0/0` "
                           'rule(s) — the cleartext-from-anywhere path is now closed '
                           '(pg_hba backed up alongside itself as .takwerx-bak).' % srem)
            try:
                residual = out_s.split('RESIDUAL_START', 1)[1].split('RESIDUAL_END', 1)[0].strip()
            except IndexError:
                residual = ''
            if residual:
                log.append('DB TLS ⚠ RESIDUAL CLEARTEXT PATH — Server One still has non-TLS '
                           'pg_hba rule(s) that admit remote clients. The core↔DB link is now '
                           'encrypted, but these leave another way in and are NOT ours to delete '
                           '(other consumers may rely on them). Operator review required:')
                for line in residual.splitlines()[:6]:
                    log.append('    ' + line.strip())
        else:
            log.append('DB TLS warning: could not remove plaintext pg_hba line — ' + out_s[:200])

    pok, pem = _ssh_probe(s1, 'DATA=$(sudo -u postgres psql -tAc "show data_directory" 2>/dev/null); sudo cat "$DATA/infratak-db.crt"', timeout=20)
    pem = (pem or '').strip()
    if not (pok and pem.startswith('-----BEGIN CERTIFICATE-----')):
        return False, log + ['DB TLS: could not read back the server cert — CoreConfig will NOT be switched to TLS.'], ''
    log.append('DB TLS: server cert captured for JDBC verify-full pinning.')
    return True, log, pem


def _server_one_tls_step(s1, core_ip, db_password, log):
    """Deploy-tail TLS step shared by the Debian and RHEL Server One paths. Returns cert_pem
    ('' on failure). On failure also fail-opens a firewalled plaintext pg_hba line — a fresh
    split only wrote hostssl, which never matches non-TLS connections, so without this a TLS
    hiccup would leave the core box with no matching pg_hba entry at all."""
    tls_ok, tls_log, tls_pem = _enable_server_one_db_tls(s1, core_ip, db_password=db_password)
    log.extend(tls_log)
    if tls_ok:
        return tls_pem
    log.append('WARNING: DB TLS enable failed — falling back to the firewalled plaintext path; '
               'CoreConfig stays non-TLS until a later pass succeeds.')
    if _valid_core_ip(core_ip):
        ip_sed = core_ip.replace('.', r'\.')
        _ssh_probe(s1, (
            'HBA=$(sudo -u postgres psql -tAc "show hba_file" 2>/dev/null); '
            '[ -z "$HBA" ] && exit 0; '
            f'sudo grep -Eq "^host[[:space:]].*{ip_sed}/32" "$HBA" || '
            f'printf "\\nhost    all    all    {core_ip}/32    md5\\n" | sudo tee -a "$HBA" >/dev/null; '
            'sudo -u postgres psql -qc "select pg_reload_conf();" >/dev/null 2>&1; true'
        ), timeout=30)
    return ''


TAK_DB_TLS_ROOTCERT_PATH = '/opt/tak/certs/files/takdb-root.crt'


def _coreconfig_db_tls_converge(cc, settings=None):
    """v10.1.9 W1: stamp the TAK-documented ssl attributes (CoreConfig.xsd <connection>:
    sslEnabled/sslMode/sslRootCert — TAK Server Config Guide Appendix D) onto the DB
    <connection> element when this box is a two_server core with a captured Server One cert.
    Pure string transform — callers write the result via their own privileged write path.
    Guards, in order of importance:
      - only touches a <connection> whose jdbc host EQUALS the saved Server One host, so
        single-box (127.0.0.1) and external-DB configs are never stamped with our cert
      - returns cc unchanged unless the pinned root cert is verifiably on disk (pointing
        TAK at a missing sslRootCert kills the DB link at boot)
      - never raises; any failure returns the input unchanged."""
    try:
        if '<connection' not in (cc or ''):
            return cc
        s = settings if settings is not None else load_settings()
        cfg = _get_tak_deployment_config(s)
        if cfg.get('mode') != 'two_server':
            return cc
        s1_host = (cfg.get('server_one', {}).get('host') or '').strip()
        if not s1_host:
            return cc
        pem = (cfg.get('database', {}).get('ssl_root_cert_pem') or '').strip()
        stamp_ok = pem.startswith('-----BEGIN CERTIFICATE-----')
        if stamp_ok:
            # Materialize the pinned root cert (idempotent, tak-readable).
            # NB: _read_priv RAISES (BrokerError / CalledProcessError) when the path
            # doesn't exist — which is ALWAYS true on the first run. Treat "cannot
            # read" as "not present yet", never as a reason to abort: swallowing it
            # here is what made the stamp a silent no-op on every non-root box
            # (caught live on test8 2026-07-25, first real run of this code).
            try:
                existing = (_read_priv(TAK_DB_TLS_ROOTCERT_PATH) or '').strip()
            except Exception:
                existing = ''
            if existing != pem:
                _makedirs_priv(os.path.dirname(TAK_DB_TLS_ROOTCERT_PATH))
                _write_priv(TAK_DB_TLS_ROOTCERT_PATH, pem + '\n')
                subprocess.run(_sudo_wrap(['chown', 'tak:tak', TAK_DB_TLS_ROOTCERT_PATH]), capture_output=True, timeout=15)
                subprocess.run(_sudo_wrap(['chmod', '644', TAK_DB_TLS_ROOTCERT_PATH]), capture_output=True, timeout=15)
                try:
                    stamp_ok = (_read_priv(TAK_DB_TLS_ROOTCERT_PATH) or '').strip() == pem
                except Exception as _ce:
                    print(f"DB TLS converge: pinned cert unreadable after write ({_ce}) — not stamping", flush=True)
                    stamp_ok = False

        def _stamp(m):
            attrs, close = m.group(1), m.group(2)
            um = re.search(r'jdbc:postgresql://([^:/"]+)', attrs)
            if not um or um.group(1) != s1_host:
                return m.group(0)
            # Strip first: stale attrs pinning a previous host's cert fail verify-full and
            # kill the DB link (e.g. after a Server One migration to a new box).
            attrs = re.sub(r'\s+ssl(Enabled|Mode|RootCert|Cert|Key)="[^"]*"', '', attrs)
            if not stamp_ok:
                return attrs + close
            return (attrs + ' sslEnabled="true" sslMode="verify-full" sslRootCert="'
                    + TAK_DB_TLS_ROOTCERT_PATH + '"' + close)
        return re.sub(r'(<connection\b[^>]*?)(\s*/?>)', _stamp, cc)
    except Exception as e:
        # Return the input unchanged (never corrupt CoreConfig) but SAY SO — a
        # silent return here hid a total failure behind "no CoreConfig change".
        print(f"DB TLS converge: skipped, returning CoreConfig unchanged ({e})", flush=True)
        return cc


def _harden_sensitive_permissions(plog=None):
    """v10.1.9 W7 — tighten world-readable secrets left behind by default umasks.

    Found live on test8 2026-07-25 while auditing after an operator report:
      - /opt/tak/certs/files/admin.key was 644 (tak:tak). The TAK ADMIN client
        private key, readable by `takwerx` — i.e. a console compromise could
        impersonate the TAK administrator, which is exactly what running the
        console non-root is supposed to prevent. Written by TAK's own cert
        scripts under a default umask, not by us.
      - authentik/.env, CloudTAK/.env, TAK-Portal/.env were 644, each carrying
        DB passwords + signing keys. These we generate, so this one IS ours.
      - /opt/tak/CoreConfig.xml was 674 — the DB password in plaintext, world
        readable.

    None of these are network-reachable; they are local privilege-escalation
    stepping stones. Idempotent and cheap, so it runs on every console boot via
    _startup_migrations (console-path delivery — existing boxes get it from a
    normal update, no SSH). Ownership is never changed, only the mode, so a
    service that already reads its own file keeps working:
      *.key / *.p12 / *.jks → 600      (owner-only; TAK runs as their owner)
      module .env           → 600      (owner-only; compose runs as that user)
      CoreConfig.xml        → 640      (tak group keeps read; world loses it)

    GUARD (added after W7 broke CoreConfig reads): every tightening is verified —
    if the console could get the bytes of a file before the chmod and cannot after
    it, the mode is REVERTED and reported. See _console_can_read() below.
    """
    def _say(m):
        (plog or (lambda x: print(f"Permissions hardening: {x}", flush=True)))(m)

    def _console_can_read(path):
        """Can THIS console process actually obtain the contents of `path`?

        Direct read first, then the privileged route (broker / sudo cat) — a
        broker-routed read counts, because that is how the console is SUPPOSED
        to reach hardened files (CoreConfig.xml since v10.1.9). Only False when
        neither route yields bytes. Always True as root, so the guard is a no-op
        on root installs — which is correct: root never lost a read.

        Deliberately a REAL read, not os.access(): the broker enforces a path
        allowlist, so 'the mode allows it' and 'the console can get it' are
        different questions and only the read answers the second one. Contents
        are discarded immediately — these are secret files, nothing is logged.
        """
        try:
            with open(path, 'rb') as f:
                f.read(1)
            return True
        except OSError:
            pass
        try:
            _read_priv(path)
            return True
        except Exception:
            return False

    targets = []
    # ── /opt/tak/certs is DELIBERATELY NOT hardened ───────────────────────────
    # It is a SHARED directory by design: bind-mounted into the Node-RED
    # container (`/opt/tak/certs/files -> /certs`) which runs as uid 1000, while
    # the files are owned by `tak` (uid 1491). Tightening them to 600 locked
    # Node-RED out and killed its TAK feeds fleet-wide —
    #   [tls-config:TAK Mission API TLS] Error: EACCES: permission denied,
    #   open '/certs/admin.key'
    # — on test8/test6/test12/NUC the moment this shipped (2026-07-25). The
    # loose mode on admin.key IS a real weakness, but it cannot be fixed by
    # chmod alone: a legitimate consumer needs cross-uid read. The fix is a
    # separate, narrower cert path for Node-RED (or a shared group), tracked on
    # the roadmap — NOT a blanket chmod. Do not re-add this without solving that.
    # Leftover 600s from the W7 window are healed by _heal_nodered_cert_read_access().
    #
    # Module .env files (we generate these). Cover both the non-root home and the
    # root-era layout that pre-flip boxes still carry.
    for home in ('/home/takwerx', '/root'):
        for mod in ('authentik', 'CloudTAK', 'TAK-Portal', 'node-red', 'nodered',
                    'netbird', 'eud-remote-assist', 'webodm', 'emailrelay'):
            targets.append((f'{home}/{mod}/.env', '600'))
    targets.append(('/opt/tak/CoreConfig.xml', '640'))

    fixed, blocked = [], []
    for path, want in targets:
        try:
            r = subprocess.run(_sudo_wrap(['stat', '-c', '%a', path]),
                               capture_output=True, text=True, timeout=15)
            cur = (r.stdout or '').strip()
            if not cur or r.returncode != 0:
                continue                      # not present on this box
            # Before tightening: a file inside a user's home must be OWNED by that
            # user. Pre-flip boxes carry root-owned .env files under /home/takwerx
            # (written when the console still ran as root). Combine that with the
            # 600 below and the owner of the home — the console, and the user that
            # runs `docker compose` — cannot read its own config at all. That is
            # what killed the TAK Portal console page on test12: PermissionError on
            # /home/takwerx/TAK-Portal/.env, 500 on every load, silent since the
            # mode changed on 2026-07-25. Fixing ownership keeps the security goal
            # (nobody but the owner can read it) while restoring the owner's access,
            # and is the reason 600 was safe to assume in the first place.
            # Scoped to THIS console's own home, deliberately. The targets list also
            # covers /root/<mod>/.env for pre-flip boxes, and on a flipped box those
            # are stale copies that the non-root migration left owned by takwerx —
            # "owner should match the home" would chown them back to root and undo
            # that migration. Narrowing to the running console's home fixes the file
            # that is actually read and leaves the leftovers alone. (Without this it
            # only worked by accident: os.stat('/root') raises for takwerx, so the
            # chown was skipped by exception rather than by intent.)
            try:
                import pwd as _pwd2
                _me = _pwd2.getpwuid(os.getuid())
                my_home = os.path.realpath(_me.pw_dir)
                if os.path.realpath(path).startswith(my_home + os.sep) \
                        and os.stat(path).st_uid != _me.pw_uid:
                    subprocess.run(_sudo_wrap(['chown', f'{_me.pw_name}:{_me.pw_name}', path]),
                                   capture_output=True, timeout=15)
                    fixed.append(f'{path} owner->{_me.pw_name}')
            except Exception:
                pass
            # Only tighten. Never widen a mode an operator deliberately narrowed.
            if int(cur, 8) & ~int(want, 8):
                could_read = _console_can_read(path)
                c = subprocess.run(_sudo_wrap(['chmod', want, path]), capture_output=True, timeout=15)
                if c.returncode != 0:
                    continue
                # ── The guard ────────────────────────────────────────────────
                # W7 has now twice tightened a path something legitimately reads:
                # /opt/tak/certs killed Node-RED's TAK feeds fleet-wide, and
                # CoreConfig.xml 640 locked `takwerx` out of the file that 16
                # call sites read — where a bare `except` turned "cannot read"
                # into a confidently WRONG answer ("LDAP not connected" on a
                # connected box). Both were caught in the field, not here.
                # So: never leave a mode we cannot read through. If the console
                # could get the bytes before and cannot now, put the mode back
                # and say so — a hardening step that breaks the console is a
                # bug to surface, not a security win to keep.
                if could_read and not _console_can_read(path):
                    subprocess.run(_sudo_wrap(['chmod', cur, path]), capture_output=True, timeout=15)
                    blocked.append(f'{path} ({cur}->{want} REVERTED)')
                    continue
                fixed.append(f'{path} {cur}->{want}')
        except Exception:
            continue
    if fixed:
        _say(f'tightened {len(fixed)} file(s): ' + '; '.join(fixed[:8])
             + (f' (+{len(fixed) - 8} more)' if len(fixed) > 8 else ''))
    if blocked:
        _say('⚠ NOT hardened — the console can no longer read these after the chmod, '
             'so the old mode was restored. Route the reader through the broker '
             '(_read_priv / _read_coreconfig) before tightening again: '
             + '; '.join(blocked))
    return fixed


def _heal_nodered_cert_read_access(plog=None):
    """v10.1.16 — heal leftover W7 damage on the one cert pair Node-RED must read.

    W7 (cabf599) blanket-tightened /opt/tak/certs to 600 and was reverted ~40
    minutes later (705d9e6) — but the revert only STOPPED the chmod; it never
    restored files already tightened. Boxes whose feeds broke loudly were fixed
    by hand during the 2026-07-25 incident; a box with flows deployed but no
    configurator configs fails silently ([tls-config:TAK Mission API TLS]
    EACCES in the container log and nothing else) — found on the NUC
    2026-08-01, five weeks stale.

    This is the sanctioned EXCEPTION to "only tighten, never widen"
    (_harden_sensitive_permissions above): exactly two files, admin.pem and
    admin.key under /opt/tak/certs/files, restored to the 644 that TAK's own
    cert scripts produce — the Node-RED container (uid 1000) reads them through
    a bind mount while `tak` owns them, so owner-only modes starve a legitimate
    consumer (operator decision 2026-07-25: Node-RED keeps the admin cert).
    Runs only when a local Node-RED install exists (the consumer), never
    touches ownership, and never touches any other file — CA/signing keys stay
    as tight as they are. Idempotent, cheap, every boot."""
    def _say(m):
        (plog or (lambda x: print(f"Node-RED cert heal: {x}", flush=True)))(m)

    # The consumer: a local Node-RED install — compose dir in this console's
    # home, or the container itself (a root-era ~/node-red is invisible to a
    # flipped takwerx console; same union as detect_modules()).
    present = os.path.exists(os.path.join(os.path.expanduser('~/node-red'), 'docker-compose.yml'))
    if not present:
        try:
            r = subprocess.run(['docker', 'ps', '-a', '--filter', 'name=nodered',
                                '--format', '{{.Names}}'],
                               capture_output=True, text=True, timeout=8,
                               env=_broker_shim_env())
            present = bool((r.stdout or '').strip())
        except Exception:
            present = False
    if not present:
        return

    for fname in ('admin.pem', 'admin.key'):
        path = f'/opt/tak/certs/files/{fname}'
        try:
            r = subprocess.run(_sudo_wrap(['stat', '-c', '%a', path]),
                               capture_output=True, text=True, timeout=15)
            cur = (r.stdout or '').strip()
            if not cur or r.returncode != 0:
                continue                      # TAK not installed / file absent
            if int(cur, 8) & 0o044 == 0o044:
                continue                      # group+other read already present
            c = subprocess.run(_sudo_wrap(['chmod', '644', path]),
                               capture_output=True, timeout=15)
            if c.returncode == 0:
                _say(f'{path} {cur}->644 (Node-RED bind-mount consumer, uid 1000)')
            else:
                _say(f'⚠ could not restore {path} (mode {cur}) — Node-RED TAK '
                     f'TLS will fail with EACCES until it is 644')
        except Exception:
            continue


# v10.1.9 W1: bump whenever the retrofit's BEHAVIOUR changes, so boxes that
# already recorded completion under an older build get the new pass exactly once.
# 1 = original. 2 = $SSH_CLIENT-scoped hostssl + removal of TAK's stock
#     `host all <user> 0.0.0.0/0` rule.
SPLIT_DB_TLS_FIX_VERSION = 2


def _split_db_tls_complete(state=None):
    """True only when the retrofit has run AND at the CURRENT fix version.

    Without this, a marker written by an older build locks the box out of every
    later fix forever — test8 recorded plain 'enabled' before the stock-rule
    removal existed, so it would have kept its cleartext path with the migration
    permanently skipped. Legacy 'enabled' parses as v1 and therefore re-runs once.
    Uses '@v' rather than ':' so it cannot collide with the 'attempts:N' form."""
    s = (state if state is not None else _split_db_tls_state()) or ''
    if not s.startswith('enabled'):
        return False
    ver = 1
    if '@v' in s:
        try:
            ver = int(s.split('@v', 1)[1])
        except ValueError:
            ver = 1
    return ver >= SPLIT_DB_TLS_FIX_VERSION


def _split_db_tls_state(value=None):
    """Read/write the retrofit's completion marker.

    Deliberately a SEPARATE file, not a key in settings.json: the console has many
    background threads doing load→modify→save on settings, and one of them clobbered
    this flag on test8 (2026-07-25 — migration wrote it at 02:03:21, an unrelated
    thread that had loaded earlier re-saved at 02:10:52 and the key vanished). A
    lost marker means the migration re-runs forever. This file has exactly one
    writer, so it cannot lose a race."""
    path = os.path.join(CONFIG_DIR, 'split-db-tls.state')
    if value is None:
        try:
            with open(path) as f:
                return (f.read() or '').strip()
        except OSError:
            return ''
    try:
        os.makedirs(CONFIG_DIR, exist_ok=True)
        with open(path, 'w') as f:
            f.write(str(value).strip())
        os.chmod(path, 0o600)
    except OSError as e:
        print(f"Split DB TLS retrofit: could not persist state marker ({e})", flush=True)
    return str(value).strip()


def _migrate_split_db_tls():
    """v10.1.9 W1 retrofit: encrypt an EXISTING split-box core↔DB link via the normal console
    update path (no operator SSH/start.sh — console-path delivery rule). Runs in a background
    thread from _startup_migrations. Ordered so a failure can never sever a working DB link:
      1. enable TLS server-side (hostssl inserted ABOVE the existing plaintext line)
      2. stamp CoreConfig ssl attrs, restart takserver
      3. VERIFY live: pg_stat_ssl shows the martiuser connection encrypted
      4. only then remove the plaintext pg_hba line and mark split_db_tls_state=enabled
    On verify failure: CoreConfig rolled back, takserver restarted on the plaintext path,
    attempt recorded (held after 3 — clear split_db_tls_attempts in settings to re-arm)."""
    _p = lambda m: print(f"Split DB TLS retrofit: {m}", flush=True)
    try:
        time.sleep(90)  # let boot settle: broker, takserver autostart, network
        s = load_settings()
        cfg = _get_tak_deployment_config(s)
        if cfg.get('mode') != 'two_server':
            return
        _state = _split_db_tls_state()
        if _split_db_tls_complete(_state):
            return
        if _state.startswith('enabled'):
            _p(f"re-running: marker is {_state or 'enabled'} (fix v1), current fix version is "
               f"v{SPLIT_DB_TLS_FIX_VERSION} — applying the newer pass once")
        attempts = int(_state.split(':', 1)[1]) if _state.startswith('attempts:') else 0
        if attempts >= 3:
            _p("held after 3 failed attempts — investigate, then clear split_db_tls_attempts in settings to re-arm")
            return
        s1 = cfg.get('server_one', {})
        if not (s1.get('host') or '').strip() or not os.path.exists('/opt/tak/CoreConfig.xml'):
            return
        core_ip = _resolve_core_ip(s, cfg)
        if not core_ip:
            _p("core IP unresolved — will retry next boot")
            return
        ok, out = _ssh_probe(s1, 'echo SSH_OK', timeout=20)
        if not ok or 'SSH_OK' not in (out or ''):
            _p("Server One SSH unreachable — will retry next boot: " + (out or '')[:200])
            return

        db_password = (cfg.get('database', {}).get('password') or '').strip()
        tls_ok, tls_log, pem = _enable_server_one_db_tls(s1, core_ip, db_password=db_password)
        for line in tls_log:
            _p(line)
        if not tls_ok or not pem:
            _p("server-side TLS enable failed — plaintext path untouched; will retry next boot")
            return
        s = load_settings()
        cfg = _get_tak_deployment_config(s)
        cfg.setdefault('database', {})['ssl_root_cert_pem'] = pem
        s['tak_deployment'] = cfg
        save_settings(s)

        cc_orig = _read_priv('/opt/tak/CoreConfig.xml') or ''
        if not cc_orig.strip():
            _p("could not read CoreConfig — will retry next boot")
            return
        cc_new = _coreconfig_db_tls_converge(cc_orig, s)
        r_act = subprocess.run(_sudo_wrap(['systemctl', 'is-active', 'takserver']),
                               capture_output=True, text=True, timeout=15)
        was_active = (r_act.stdout or '').strip() == 'active'
        if not was_active:
            # Never juggle the link while the operator has TAK down — stamp and defer.
            if cc_new != cc_orig:
                _write_priv('/opt/tak/CoreConfig.xml', cc_new)
                _p("CoreConfig stamped; takserver not active — TLS verify + plaintext removal deferred")
            else:
                _p("takserver not active — TLS verify deferred to a boot where it runs")
            return
        if cc_new != cc_orig:
            _write_priv('/opt/tak/CoreConfig.xml', cc_new)
            _p("CoreConfig stamped (sslEnabled, sslMode=verify-full) — restarting takserver")
            subprocess.run(_sudo_wrap(['systemctl', 'restart', 'takserver']), capture_output=True, timeout=180)
        elif 'sslEnabled="true"' not in cc_orig:
            _p("no CoreConfig change and no ssl attrs present — will retry next boot")
            return

        # Verify the live link is actually TLS (TAK's pool comes up over ~1-3 min).
        q = ('sudo -u postgres psql -tAc "SELECT (bool_or(s.ssl))::text || \'/\' || count(*)::text '
             'FROM pg_stat_ssl s JOIN pg_stat_activity a USING(pid) '
             'WHERE a.usename=\'martiuser\' AND a.client_addr IS NOT NULL"')
        verified = False
        saw_plain = False
        for _ in range(24):  # ~4 min
            time.sleep(10)
            vok, vout = _ssh_probe(s1, q, timeout=25)
            vout = (vout or '').strip()
            if vok and '/' in vout:
                flag, cnt = vout.split('/', 1)
                if cnt.strip().isdigit() and int(cnt.strip()) > 0:
                    if flag.strip() == 'true':
                        verified = True
                        break
                    saw_plain = True
        if verified:
            rm_ok, rm_log, _pem2 = _enable_server_one_db_tls(s1, core_ip, db_password=db_password,
                                                             remove_plaintext=True)
            for line in rm_log:
                _p(line)
            # Record WHICH kind of done this was. The retrofit runs exactly once and
            # is then skipped forever, so a residual cleartext rule we deliberately
            # chose not to delete would be announced in a single journal line and
            # never mentioned again — the operator's cue to close it disappears.
            # 'enabled-residual' still counts as complete, so the migration stays
            # one-shot; it just keeps re-warning on every boot. The @v suffix is
            # what lets a LATER fix reach this box exactly once (see
            # _split_db_tls_complete) instead of being skipped forever.
            _split_db_tls_state(('enabled-residual' if any('RESIDUAL CLEARTEXT PATH' in l for l in rm_log)
                                 else 'enabled') + f'@v{SPLIT_DB_TLS_FIX_VERSION}')
            if any('RESIDUAL CLEARTEXT PATH' in l for l in rm_log):
                _p("✓ DONE — the core↔DB link is now TLS (verify-full pinned). NOTE: Server One "
                   "still accepts non-TLS connections from other clients (listed above) — that "
                   "residual path is the operator's to close.")
            else:
                _p("✓ COMPLETE — core↔DB link is TLS (verify-full pinned) and no cleartext path remains")
            return
        _p("✗ TLS link did NOT verify (%s) — rolling CoreConfig back to the plaintext path"
           % ("connections still plaintext" if saw_plain else "no martiuser connection observed"))
        _write_priv('/opt/tak/CoreConfig.xml', cc_orig)
        subprocess.run(_sudo_wrap(['systemctl', 'restart', 'takserver']), capture_output=True, timeout=180)
        _split_db_tls_state(f'attempts:{attempts + 1}')
        _p(f"rolled back and takserver restarted; attempt {attempts + 1}/3 recorded — will retry next boot")
    except Exception as e:
        _p(f"error (non-fatal, will retry next boot): {e}")


def _split_db_keepalives_state():
    """Marker for the v10.1.51 keepalive retrofit ('' | 'attempts:N' | 'done:V')."""
    return (load_settings().get('split_db_keepalives_state') or '').strip()


SPLIT_DB_KEEPALIVE_FIX_VERSION = 1


def _split_db_keepalives_complete(state=None):
    st = _split_db_keepalives_state() if state is None else state
    if not st.startswith('done'):
        return False
    try:
        return int(st.split(':', 1)[1]) >= SPLIT_DB_KEEPALIVE_FIX_VERSION
    except (IndexError, ValueError):
        return False


def _migrate_split_db_keepalives():
    """v10.1.51 (W2) retrofit: converge tcp_keepalives_* onto an EXISTING split box's remote
    Postgres through the normal console update path — no operator SSH, no start.sh
    (console-path delivery rule). Fresh splits get this from _setup_server_one{,_rhel};
    this is the pass that reaches the boxes already in the field.

    Why it matters: test8, 2026-08-26 — TAK Server down ~16 h with Postgres up 35 days and
    9 of 2100 connections in use. HikariCP sat at total=0/active=0/idle=0/waiting=201 and
    never rebuilt (40,534 errors) because the remote DB shipped tcp_keepalives_idle=7200,
    so nothing probed the idle link for two hours and the NAT on the path dropped it while
    TAK held the dead socket. Aug 24 and Aug 25 show the same signature self-healing.

    Deliberately the SAFEST possible migration:
      * config edit only — no schema, no data, no CoreConfig, no TAK restart
      * RELOAD, not restart. tcp_keepalives_* are SIGHUP-context, so the DB never goes down
        and no live connection is dropped; new connections pick the values up
      * delete-then-append, so a box already carrying a value converges to the fleet
        constant instead of accumulating duplicate lines or keeping an operator's edit
      * verifies by reading the file back, and only then marks done. A failure records an
        attempt and retries on the next console restart (held after 3)."""
    _p = lambda m: print(f"Split DB keepalives: {m}", flush=True)
    try:
        # Later than the TLS retrofit's 90s so the two never touch pg_hba/postgresql.conf
        # and reload/restart Postgres at the same moment on the same host.
        time.sleep(150)
        s = load_settings()
        cfg = _get_tak_deployment_config(s)
        if cfg.get('mode') != 'two_server':
            return
        state = _split_db_keepalives_state()
        if _split_db_keepalives_complete(state):
            return
        attempts = int(state.split(':', 1)[1]) if state.startswith('attempts:') else 0
        if attempts >= 3:
            _p("held after 3 failed attempts — investigate Server One, then clear "
               "split_db_keepalives_state in settings to re-arm")
            return
        s1 = cfg.get('server_one', {})
        if not (s1.get('host') or '').strip():
            return
        ok, out = _ssh_probe(s1, 'echo SSH_OK', timeout=20)
        if not ok or 'SSH_OK' not in (out or ''):
            _p("Server One SSH unreachable — will retry next boot: " + (out or '')[:200])
            return

        # Find postgresql.conf on either family: Debian /etc/postgresql/*/main first, then
        # the RHEL data dir (same discovery the deploy path uses).
        cmd = (
            'PGCONF=""; '
            'PGM=$(find /etc/postgresql -type d -name main 2>/dev/null | sort -V | tail -1); '
            '[ -n "$PGM" ] && [ -f "$PGM/postgresql.conf" ] && PGCONF="$PGM/postgresql.conf"; '
            'if [ -z "$PGCONF" ]; then ' + _PG_REMOTE_PGDATA_SH + '; '
            '  [ -n "$PGDATA" ] && sudo test -f "$PGDATA/postgresql.conf" && PGCONF="$PGDATA/postgresql.conf"; '
            'fi; '
            '[ -z "$PGCONF" ] && { echo NO_PGCONF; exit 0; }; '
            + _pg_keepalive_sh('"$PGCONF"') + '; '
            # SIGHUP only. Try every reload spelling; a unit that does not exist is a no-op.
            'sudo pg_ctlcluster 15 main reload 2>/dev/null; '
            'sudo systemctl reload postgresql 2>/dev/null; '
            + ''.join('sudo systemctl reload postgresql-%d 2>/dev/null; ' % _m
                      for _m in sorted(set(TAK_PG_MAJORS) | {16})) +
            'echo "PGCONF=$PGCONF"; '
            'echo "IDLE=$(sudo grep -c \'^tcp_keepalives_idle = 60\' \"$PGCONF\")"'
        )
        ok, out = _ssh_probe(s1, cmd, timeout=60)
        out = out or ''
        if 'NO_PGCONF' in out:
            _p("no postgresql.conf found on Server One — nothing to converge (is the DB "
               "really on this host?). Not retried as a failure.")
            return
        if not ok or 'IDLE=1' not in out:
            attempts += 1
            s = load_settings()
            s['split_db_keepalives_state'] = f'attempts:{attempts}'
            save_settings(s)
            _p(f"convergence not confirmed (attempt {attempts}/3) — will retry next boot: "
               + out.strip()[:300])
            return
        s = load_settings()
        s['split_db_keepalives_state'] = f'done:{SPLIT_DB_KEEPALIVE_FIX_VERSION}'
        save_settings(s)
        _p("converged on Server One (tcp_keepalives_idle=60, interval=10, count=6) and "
           "reloaded Postgres — no restart, no connection dropped. New DB connections now "
           "detect a dead link in ~2 min instead of never.")
    except Exception as e:
        _p(f"error (non-fatal, retries next boot): {e}")


def _fetch_db_password_from_server_one(s1_cfg):
    """Fetch martiuser DB password from Server One. Tries CoreConfig.example.xml and CoreConfig.xml.
    Fetches file via sudo cat and parses in Python so we don't depend on remote grep/sed.
    Returns (password, failure_reason). On success: (str, None). On failure: ('', str)."""
    first_ssh_error = None
    for pw_file in ('/opt/tak/CoreConfig.example.xml', '/opt/tak/CoreConfig.xml'):
        ok, out = _ssh_probe(s1_cfg, f"sudo cat {pw_file} 2>/dev/null", timeout=10)
        if not ok:
            if first_ssh_error is None:
                raw = (out or '').strip()[:200]
                first_ssh_error = raw if raw else 'connection failed or no response (check key, host, and that Server One allows SSH from this host)'
            continue
        if not (out or '').strip():
            continue
        # Prefer JDBC <connection ...> password first (avoid matching unrelated
        # password fields like LDAP/service-account credentials in CoreConfig).
        for pattern in (
            r'<connection[^>]*url\s*=\s*["\']jdbc:postgresql://[^"\']+/cot["\'][^>]*password\s*=\s*["\']([^"\']*)["\']',
            r'<connection[^>]*username\s*=\s*["\']martiuser["\'][^>]*password\s*=\s*["\']([^"\']*)["\']',
            r'password\s*=\s*["\']([^"\']*)["\']',
            r'password=["\']([^"\']*)["\']',
        ):
            match = re.search(pattern, out)
            if match:
                candidate = (match.group(1) or '').strip()
                if candidate:
                    return candidate, None
        for pwd_cmd in (
            f"sudo grep -o 'password=\"[^\"]*\"' {pw_file} 2>/dev/null | head -1 | sed 's/.*password=\"//;s/\"$//'",
            f"sudo sed -n 's/.*password=\"\\([^\"]*\\)\".*/\\1/p' {pw_file} 2>/dev/null | head -1",
        ):
            ok2, pwd_out = _ssh_probe(s1_cfg, pwd_cmd, timeout=10)
            candidate = (pwd_out or '').strip() if ok2 else ''
            if candidate:
                return candidate, None
    if first_ssh_error:
        return '', f'SSH to Server One failed: {first_ssh_error}'
    return '', 'No password= found in CoreConfig.example.xml or CoreConfig.xml on Server One (or password was empty).'


def _verify_server_one_db_password(s1_cfg, db_password, db_port=5432, db_user='martiuser', db_name='cot'):
    """Validate DB credentials directly on Server One via psql.
    Returns (True, msg) when auth works, else (False, reason)."""
    if not (db_password or '').strip():
        return False, 'empty DB password'
    try:
        port = int(db_port or 5432)
    except Exception:
        port = 5432
    pw_q = shlex.quote((db_password or '').strip())
    user_q = shlex.quote((db_user or 'martiuser').strip() or 'martiuser')
    db_q = shlex.quote((db_name or 'cot').strip() or 'cot')
    # v0.9.46: capture psql's real error (was 2>/dev/null) so a failure reports WHY —
    # password-auth-failed vs no-pg_hba-entry vs missing-db — instead of a blanket "rejected".
    cmd = (
        "if ! command -v psql >/dev/null 2>&1; then echo NO_PSQL; exit 0; fi; "
        f"ERR=$(PGPASSWORD={pw_q} psql -h 127.0.0.1 -p {port} -U {user_q} -d {db_q} -tAc \"select 1\" 2>&1); "
        "if echo \"$ERR\" | tr -d '[:space:]' | grep -qx 1; then echo AUTH_OK; "
        "else echo \"AUTH_FAIL: $(echo \"$ERR\" | head -1)\"; fi"
    )
    ok, out = _ssh_probe(s1_cfg, cmd, timeout=15)
    out_s = (out or '').strip()
    if not ok:
        return False, (out_s[:200] or 'SSH validation failed')
    if 'AUTH_OK' in out_s:
        return True, 'DB auth verified on Server One'
    if 'NO_PSQL' in out_s:
        return False, 'psql not available on Server One for credential validation'
    low = out_s.lower()
    if 'password authentication failed' in low:
        return False, 'DB password rejected by PostgreSQL on Server One (password authentication failed)'
    if 'pg_hba' in low:
        return False, 'pg_hba.conf on Server One has no entry for the 127.0.0.1/martiuser loopback path — ' + out_s[:160]
    if 'does not exist' in low:
        return False, 'DB or role missing on Server One — ' + out_s[:160]
    return False, ('DB auth failed on Server One — ' + out_s[:180]) if out_s else 'DB password rejected by PostgreSQL on Server One'


@app.route('/api/takserver/two-server/open-db-firewall', methods=['POST'])
@login_required
def takserver_two_server_open_db_firewall():
    """Prepare Server One: install PostgreSQL + TAK database .deb if needed, configure PG for remote access, open UFW."""
    data = request.get_json() or {}
    settings = load_settings()
    cfg = _get_tak_deployment_config(settings)
    if isinstance(data.get('config'), dict):
        cfg = _normalize_tak_deployment_config(_deep_merge_dict(cfg, data.get('config')))
    if cfg.get('mode') != 'two_server':
        return jsonify({'success': False, 'error': 'Deployment mode is not two_server'}), 400
    s1 = cfg.get('server_one', {})
    if not (s1.get('host') or '').strip():
        return jsonify({'success': False, 'error': 'Server One host not set'}), 400
    db_port = int(cfg.get('database', {}).get('port') or 5432)
    core_ip = _resolve_core_ip(settings, cfg)
    if not core_ip:
        return jsonify({'success': False, 'error': 'Server Two (Core) IP unknown. Set Server IP in Settings.'}), 400

    # Check for uploaded database .deb to SCP + install if PG is missing
    uploaded = [f for f in os.listdir(UPLOAD_DIR) if f.endswith('.deb') or f.endswith('.rpm')]
    db_pkg = next((f for f in uploaded if 'database' in f.lower()), '')
    db_pkg_path = os.path.join(UPLOAD_DIR, db_pkg) if db_pkg else None
    if db_pkg_path and not os.path.isfile(db_pkg_path):
        db_pkg_path = None

    res = _setup_server_one(s1, core_ip, db_port,
                            db_pkg_path=db_pkg_path, db_pkg_name=db_pkg if db_pkg_path else None)
    # Failure paths return 3-tuples; success returns a 4th element: the DB TLS root cert PEM.
    ok, log, db_password = res[0], res[1], res[2]
    tls_pem = res[3] if len(res) > 3 else ''
    if db_password:
        cfg['database']['password'] = db_password
    if tls_pem:
        cfg['database']['ssl_root_cert_pem'] = tls_pem
    if db_password or tls_pem:
        settings['tak_deployment'] = cfg
        save_settings(settings)

    if not ok:
        return jsonify({'success': False, 'error': log[-1] if log else 'Setup failed on Server One', 'log': log}), 400
    return jsonify({'success': True, 'message': f'Server One ready: PostgreSQL listening, UFW open for {core_ip} → port {db_port}. Next: 5. Deploy Server Two (Core), then fill out certs and hit Deploy TAK Server.', 'log': log})


@app.route('/api/takserver/two-server/runbook', methods=['GET'])
@login_required
def takserver_two_server_runbook():
    """Generate a practical two-server command runbook using manual naming/order."""
    settings = load_settings()
    cfg = _get_tak_deployment_config(settings)
    if cfg.get('mode') != 'two_server':
        return jsonify({'success': False, 'error': 'Deployment mode is not set to two_server', 'config': cfg}), 400

    uploaded = [f for f in os.listdir(UPLOAD_DIR) if f.endswith('.deb') or f.endswith('.rpm')]
    db_pkg = next((f for f in uploaded if 'database' in f.lower()), '')
    core_pkg = next((f for f in uploaded if 'core' in f.lower()), '')

    s1 = cfg.get('server_one', {})
    s2 = cfg.get('server_two', {})
    db_host = (s1.get('host') or '<SERVER_ONE_DB_HOST>').strip() or '<SERVER_ONE_DB_HOST>'
    db_port = int(cfg.get('database', {}).get('port') or 5432)
    core_host_for_db_acl = (s2.get('host') or '').strip()
    if s2.get('use_localhost'):
        core_host_for_db_acl = (settings.get('server_ip') or '').strip() or '<INFRA_SERVER_IP>'
    if not core_host_for_db_acl:
        core_host_for_db_acl = '<SERVER_TWO_CORE_HOST>'

    server_one_steps = [
        '# Server One: Database Server',
        'sudo apt-get update && sudo apt-get install -y lsb-release',
        # v10.1.27: same filename + keyring path the console itself uses, and skip
        # if this box already has PGDG configured — two sources for one repo with
        # different signed-by paths make apt refuse to read ANY source (exit 100).
        f'grep -rqs "{_PGDG_APT_HOST}" /etc/apt/sources.list /etc/apt/sources.list.d/ && echo "PGDG already configured - skip the next two commands"',
        'sudo mkdir -p /usr/share/keyrings',
        f'sudo curl {_PGDG_KEY_URL} --output {_PGDG_KEYRING}',
        f'cn={_APT_CODENAME_SH} && [ -n "$cn" ] && echo "deb [signed-by={_PGDG_KEYRING}] https://{_PGDG_APT_HOST}/pub/repos/apt ${{cn}}-pgdg main" | sudo tee {_PGDG_LIST} >/dev/null',
        'sudo apt update',
        f'sudo apt install -y ./{db_pkg}' if db_pkg else 'sudo apt install -y ./takserver-database_x.x-RELEASExx_all.deb',
        # v0.9.12 hardening: source-scope only, deny everything else on db_port.
        # The pre-v0.9.12 unconditional `ufw allow {db_port}/tcp` defeated the
        # source-scope rule above and left Postgres reachable from the internet.
        # v0.9.46: delete any stale deny first (UFW first-match-wins; appended allow would
        # otherwise sit below it), add scoped allow, drop broad allow, re-add deny last.
        f'sudo ufw delete deny {db_port}/tcp || true',
        f'sudo ufw allow from {core_host_for_db_acl} to any port {db_port} proto tcp',
        f'sudo ufw delete allow {db_port}/tcp || true',
        f'sudo ufw deny {db_port}/tcp',
        'sudo ufw --force enable',
        '# v10.1.9: encrypt the core↔DB wire (TLS + SCRAM) — TAK Server Config Guide Appendix D',
        'PGDATA=$(sudo -u postgres psql -tAc "show data_directory")',
        f'sudo openssl req -x509 -newkey rsa:4096 -sha256 -days 3650 -nodes -keyout "$PGDATA/infratak-db.key" -out "$PGDATA/infratak-db.crt" -subj "/CN={db_host}" -addext "subjectAltName=IP:{db_host}"',
        'sudo chown postgres:postgres "$PGDATA"/infratak-db.* && sudo chmod 600 "$PGDATA/infratak-db.key" && sudo chmod 644 "$PGDATA/infratak-db.crt"',
        'CONF=$(sudo -u postgres psql -tAc "show config_file")',
        'printf "ssl = on\\nssl_cert_file = \'%s/infratak-db.crt\'\\nssl_key_file = \'%s/infratak-db.key\'\\npassword_encryption = scram-sha-256\\n" "$PGDATA" "$PGDATA" | sudo tee -a "$CONF"',
        f'echo "hostssl all all {core_host_for_db_acl}/32 scram-sha-256" | sudo tee -a "$(sudo -u postgres psql -tAc \'show hba_file\')"   # replaces any plaintext host line for {core_host_for_db_acl}',
        'sudo -u postgres psql -c "select pg_reload_conf();"',
    ]
    server_two_steps = [
        '# Server Two: Core Server',
        'sudo apt-get update && sudo apt-get install -y lsb-release',
        f'sudo apt install -y ./{core_pkg}' if core_pkg else 'sudo apt install -y ./takserver-core_x.x-RELEASExx_all.deb',
        f'sudo sed -i \'s|jdbc:postgresql://127.0.0.1:5432/cot|jdbc:postgresql://{db_host}:{db_port}/cot|g\' /opt/tak/CoreConfig.xml',
        '# v10.1.9: pin + encrypt the DB link — copy the server cert from Server One, then add',
        f'#   sslEnabled="true" sslMode="verify-full" sslRootCert="/opt/tak/certs/files/takdb-root.crt"',
        '#   to the <connection …> element in /opt/tak/CoreConfig.xml (Config Guide Appendix D)',
        f'sudo scp <user>@{db_host}:"$(ssh <user>@{db_host} sudo -u postgres psql -tAc \'show data_directory\')/infratak-db.crt" /opt/tak/certs/files/takdb-root.crt && sudo chown tak:tak /opt/tak/certs/files/takdb-root.crt',
        'sudo systemctl daemon-reload',
        'sudo systemctl enable takserver',
        'sudo systemctl restart takserver',
        'sudo ufw allow 8089/tcp && sudo ufw allow 8443/tcp && sudo ufw allow 8446/tcp && sudo ufw --force enable',
    ]
    notes = [
        'Manual naming/order preserved: Server One (Database Server) first, then Server Two (Core Server).',
        'Database password is generated by the TAK installer; confirm the value in /opt/tak/CoreConfig.example.xml on Server One and ensure Server Two CoreConfig.xml matches it.',
        'PostgreSQL TLS per Appendix D is included above (v10.1.9): server cert + hostssl/SCRAM on '
        'Server One, sslEnabled/sslMode=verify-full/sslRootCert on the CoreConfig <connection>. '
        'The console-driven deploy does all of this automatically.',
    ]
    return jsonify({
        'success': True,
        'config': cfg,
        'detected_packages': {'database': db_pkg, 'core': core_pkg},
        'server_one_steps': server_one_steps,
        'server_two_steps': server_two_steps,
        'notes': notes,
    })


@app.route('/api/takserver/two-server/deploy-server-one', methods=['POST'])
@login_required
def takserver_two_server_deploy_server_one():
    """Full Server One deploy: SCP database .deb, install, configure PG for remote, open UFW, capture DB password.
    Optional body: deploy_target_host (+ deploy_target_user, deploy_target_port) — deploy to that host only while
    keeping saved server_one.host unchanged (for DB migration: prepare new VM before Start migration)."""
    data = request.get_json() or {}
    settings = load_settings()
    cfg = _get_tak_deployment_config(settings)
    if isinstance(data.get('config'), dict):
        cfg = _normalize_tak_deployment_config(_deep_merge_dict(cfg, data.get('config')))
    if cfg.get('mode') != 'two_server':
        return jsonify({'success': False, 'error': 'Deployment mode is not two_server'}), 400
    s1_saved = dict(cfg.get('server_one', {}))
    s1 = dict(cfg.get('server_one', {}))
    deploy_alt = (data.get('deploy_target_host') or '').strip()
    preserve_saved_host = False
    if deploy_alt:
        if not _safe_migration_db_host(deploy_alt):
            return jsonify({'success': False, 'error': 'Invalid deploy_target_host'}), 400
        saved_host = (s1.get('host') or '').strip()
        if saved_host and deploy_alt.lower() == saved_host.lower():
            return jsonify({'success': False, 'error': 'deploy_target_host is the same as saved Server One — use normal step 4 without deploy_target_host.'}), 400
        s1['host'] = deploy_alt
        du = (data.get('deploy_target_user') or '').strip()
        if du:
            s1['ssh_user'] = du
        dp = data.get('deploy_target_port')
        if dp is not None and str(dp).strip():
            try:
                s1['ssh_port'] = int(dp)
            except (TypeError, ValueError):
                return jsonify({'success': False, 'error': 'deploy_target_port must be a number'}), 400
        preserve_saved_host = True
    if not (s1.get('host') or '').strip():
        return jsonify({'success': False, 'error': 'Server One host not set'}), 400
    db_port = int(cfg.get('database', {}).get('port') or 5432)
    core_ip = _resolve_core_ip(settings, cfg)
    if not core_ip:
        return jsonify({'success': False, 'error': 'Server Two (Core) IP unknown. Set Server IP in Settings or ensure this host can reach ifconfig.me.'}), 400

    # Require SSH to Server One first — otherwise deploy and password capture will both fail
    ssh_ok, ssh_out = _ssh_probe(s1, 'echo ok', timeout=10)
    if not ssh_ok:
        err = (ssh_out or 'Connection failed').strip()[:300]
        return jsonify({
            'success': False,
            'error': f'Cannot SSH to Server One ({s1.get("host")}). Run step 2 (Setup SSH key) and step 3 (Copy key to Server One) first. Without SSH, deployment cannot proceed.',
            'detail': err,
        }), 400

    uploaded = [f for f in os.listdir(UPLOAD_DIR) if f.endswith('.deb') or f.endswith('.rpm')]
    db_pkg = next((f for f in uploaded if 'database' in f.lower()), '')
    if not db_pkg:
        return jsonify({
            'success': False,
            'error': 'No takserver-database .deb in uploads — add the file on this TAK Server page (drag/drop or browse) so we can deploy it. If it was deleted, upload it again from tak.gov.',
        }), 400
    local_deb = os.path.join(UPLOAD_DIR, db_pkg)
    if not os.path.isfile(local_deb):
        return jsonify({
            'success': False,
            'error': f'Uploads list "{db_pkg}" but the file is gone from disk — upload the takserver-database .deb again.',
        }), 400

    if preserve_saved_host:
        ok_ver, ver_err = _assert_uploaded_db_deb_matches_server_one(s1_saved, local_deb, db_pkg)
        if not ok_ver:
            return jsonify({'success': False, 'error': ver_err}), 400

    res = _setup_server_one(s1, core_ip, db_port,
                            db_pkg_path=local_deb, db_pkg_name=db_pkg)
    # Failure paths return 3-tuples; success returns a 4th element: the DB TLS root cert PEM.
    ok, log, db_password = res[0], res[1], res[2]
    tls_pem = res[3] if len(res) > 3 else ''
    if db_password:
        if preserve_saved_host:
            # Do not persist alternate host — migration still needs saved Server One = current DB source.
            # Same for the TLS cert: storing the ALTERNATE box's cert against the saved host would
            # break verify-full pinning on the still-live link; migration stores it on cutover.
            settings = load_settings()
            cfg_save = _get_tak_deployment_config(settings)
            cfg_save.setdefault('database', {})['password'] = db_password
            settings['tak_deployment'] = cfg_save
            save_settings(settings)
            log.append('Note: Saved Server One host unchanged (alternate deploy). Use Start migration when ready.')
        else:
            cfg['database']['password'] = db_password
            if tls_pem:
                cfg['database']['ssl_root_cert_pem'] = tls_pem
            settings['tak_deployment'] = cfg
            save_settings(settings)

    if not ok:
        return jsonify({'success': False, 'error': log[-1] if log else 'Deploy failed on Server One', 'log': log}), 400

    # Deploy Guard Dog health agent to Server One so Remote DB monitor can go green without a separate deploy
    ssh_key_path = (s1.get('ssh_key_path') or '').strip()
    if ssh_key_path and os.path.exists(os.path.expanduser(ssh_key_path)):
        ha_ok, ha_msg = _deploy_health_agent_to_server_one(s1)
        log.append('Health agent: ' + (ha_msg if ha_ok else f'Skip/fail: {ha_msg}'))
    else:
        log.append('Health agent: skipped (no SSH key to Server One)')

    return jsonify({
        'success': True,
        'message': 'Server One (Database) deploy complete. Next: 5. Deploy Server Two (Core), then fill out certs and hit Deploy TAK Server.',
        'log': log,
        'db_password_captured': bool(db_password),
    })


@app.route('/api/takserver/two-server/deploy-server-two', methods=['POST'])
@login_required
def takserver_two_server_deploy_server_two():
    """Automate Server Two (this host): install core .deb, point CoreConfig at Server One DB with correct password, restart."""
    data = request.get_json() or {}
    settings = load_settings()
    cfg = _get_tak_deployment_config(settings)
    if isinstance(data.get('config'), dict):
        cfg = _normalize_tak_deployment_config(_deep_merge_dict(cfg, data.get('config')))
    if cfg.get('mode') != 'two_server':
        return jsonify({'success': False, 'error': 'Deployment mode is not two_server'}), 400
    s1 = cfg.get('server_one', {})
    db_host = (s1.get('host') or '').strip()
    if not db_host:
        return jsonify({'success': False, 'error': 'Server One host not set'}), 400
    db_port = int(cfg.get('database', {}).get('port') or 5432)
    db_password = (cfg.get('database', {}).get('password') or '').strip()
    uploaded = [f for f in os.listdir(UPLOAD_DIR) if f.endswith('.deb') or f.endswith('.rpm')]
    core_pkg = next((f for f in uploaded if 'core' in f.lower()), '')
    if not core_pkg:
        return jsonify({'success': False, 'error': 'No core package uploaded. Upload takserver-core .deb first.'}), 400
    local_deb = os.path.join(UPLOAD_DIR, core_pkg)
    if not os.path.isfile(local_deb):
        return jsonify({'success': False, 'error': f'Package not found: {core_pkg}'}), 400
    log = []

    # If no DB password stored, try to fetch it from Server One now (same SSH as step 4)
    if not db_password:
        db_password, fetch_err = _fetch_db_password_from_server_one(s1)
        if db_password:
            cfg['database']['password'] = db_password
            settings['tak_deployment'] = cfg
            save_settings(settings)
            log.append('Fetched DB password from Server One.')
        else:
            return jsonify({
                'success': False,
                'error': 'DB password not set. Run steps 2–3 (Setup SSH key, Copy key to Server One), then step 4 (Deploy Server One) so we can capture it automatically. Or paste the password from Server One in the "DB password (from Server One)" field above and click Save Config.',
                'detail': (fetch_err or '')[:200],
            }), 400

    # Validate DB password against Server One before patching CoreConfig.
    db_user = (cfg.get('database', {}).get('user') or 'martiuser').strip() or 'martiuser'
    db_name = (cfg.get('database', {}).get('name') or 'cot').strip() or 'cot'
    ok_pw, msg_pw = _verify_server_one_db_password(s1, db_password, db_port=db_port, db_user=db_user, db_name=db_name)
    if not ok_pw:
        return jsonify({
            'success': False,
            'error': (
                'DB credential validation failed on Server One. '
                'Use Sync DB Password with the current martiuser password from Server One, then retry.'
            ),
            'detail': msg_pw,
        }), 400

    # Increase concurrent TCP connections per TAK guide.
    # v10.0.5 non-root: `| sudo tee -a` is dead for takwerx — append via the broker.
    try:
        try:
            _lc = _read_priv('/etc/security/limits.conf')
        except Exception:
            _lc = ''
        if 'soft nofile 32768' not in _lc:
            _write_priv('/etc/security/limits.conf', '* soft nofile 32768\n* hard nofile 32768\n', mode='a')
    except Exception:
        pass

    # Install the core package — Debian: apt; RHEL/Rocky: dnf (+ the repo prereqs the
    # takserver-core rpm needs), mirroring the proven single-server RHEL deploy (Step 2/4).
    if _distro_family() == 'rhel':
        _pg_arch = 'aarch64' if _host_arch() == 'arm64' else 'x86_64'
        run_cmd('dnf install -y epel-release 2>&1', check=False, quiet=True)
        # GH #56: genuine RHEL has no `epel-release` in its enabled repos — fall back
        # to the Fedora EPEL rpm URL (no-op when the package name resolved above).
        run_cmd('rpm -q epel-release > /dev/null 2>&1 || dnf install -y https://dl.fedoraproject.org/pub/epel/epel-release-latest-9.noarch.rpm 2>&1', check=False, quiet=True)
        run_cmd(f'dnf install -y https://download.postgresql.org/pub/repos/yum/reporpms/EL-9-{_pg_arch}/pgdg-redhat-repo-latest.noarch.rpm 2>&1', check=False, quiet=True)
        run_cmd('dnf -qy module disable postgresql 2>&1', check=False, quiet=True)
        run_cmd('dnf install -y java-17-openjdk-devel 2>&1', check=False, quiet=True)
        run_cmd('dnf config-manager --set-enabled crb 2>&1', check=False, quiet=True)
        _core_ok = run_cmd(f'cd {UPLOAD_DIR} && dnf install -y ./{core_pkg} --setopt=clean_requirements_on_remove=false 2>&1', "Installing takserver-core (dnf)...")
        run_cmd(f'alternatives --set java java-17-openjdk.{_pg_arch} 2>/dev/null; true', check=False, quiet=True)
        # Idempotency: dnf exits non-zero on a re-install ("Transaction test error" when the
        # package is already present) or on a postinstall-scriptlet hiccup, even though the
        # package files installed fine. Don't hard-fail (which also SKIPS the JDBC patch below)
        # if takserver-core is actually installed — verify with `rpm -q` and treat present as
        # success. (Field-seen on a re-run split pre-stage: install succeeded, second attempt
        # tripped a transaction-test error, whole pre-stage falsely reported failure.)
        if not _core_ok:
            _chk = subprocess.run('rpm -q takserver-core', shell=True, capture_output=True,
                                  text=True, timeout=30, env=_broker_shim_env())
            if _chk.returncode == 0:
                _core_ok = True
                log.append('takserver-core dnf exit non-zero but rpm -q confirms it is installed — continuing (idempotent).')
        log.append('takserver-core installed via dnf (RHEL).' if _core_ok else 'takserver-core dnf install FAILED — see deploy log.')
        if not _core_ok:
            return jsonify({'success': False, 'error': 'Core package install (dnf) failed on Server Two — check the deploy log for the dnf error.', 'log': log}), 400
    else:
        try:
            # --allow-downgrades: installing an OLDER core than the box currently has is a
            # downgrade, and apt refuses with "Packages were downgraded and -y was used
            # without --allow-downgrades". The single-server deploy already carries this
            # flag for exactly that reason; the two-server core install never got it, so
            # standing a 5.7 pair up on a box that had touched 5.8 failed outright
            # (dev-4, 2026-09-04) — which is precisely how anyone tests an upgrade.
            r = _run_priv_chain([['apt-get', 'update', '-qq'],
                                 ['apt-get', 'install', '-y', '--allow-downgrades',
                                  f'./{core_pkg}']], 'and', timeout=600, cwd=UPLOAD_DIR)
            log.append(r.stdout or '')
            log.append(r.stderr or '')
            if r.returncode != 0:
                return jsonify({'success': False, 'error': (r.stderr or r.stdout or 'apt install failed')[:500], 'log': log}), 400
        except Exception as e:
            return jsonify({'success': False, 'error': str(e)[:400], 'log': log}), 400

    # Patch CoreConfig.xml: JDBC URL and DB password
    core_config = '/opt/tak/CoreConfig.xml'
    # RHEL: the takserver-core rpm ships CoreConfig.example.xml (not CoreConfig.xml). Seed it
    # so the JDBC patch below runs (mirrors the single-server RHEL deploy); else TAK keeps the
    # default localhost JDBC and never connects to Server One.
    if _distro_family() == 'rhel' and not os.path.exists(core_config) and os.path.exists('/opt/tak/CoreConfig.example.xml'):
        run_cmd('cp /opt/tak/CoreConfig.example.xml /opt/tak/CoreConfig.xml 2>&1; chown tak:tak /opt/tak/CoreConfig.xml 2>/dev/null; true', check=False, quiet=True)
    if os.path.exists(core_config):
        try:
            # v10.0.5 non-root: read/write CoreConfig via the broker (literal `sudo
            # cat`/`sudo tee` fail — takwerx isn't in sudoers — and /opt/tak is tak:tak).
            content = _read_priv(core_config)
            if not content:
                return jsonify({'success': False, 'error': 'Could not read CoreConfig.xml', 'log': log}), 400

            jdbc_new = f'jdbc:postgresql://{db_host}:{db_port}/cot'
            content = content.replace('jdbc:postgresql://127.0.0.1:5432/cot', jdbc_new)

            if db_password:
                content = re.sub(
                    r'(<connection[^>]*password=")[^"]*(")',
                    lambda m: m.group(1) + db_password + m.group(2),
                    content
                )

            # v10.1.9 W1: stamp the documented ssl attrs when Server One captured a TLS cert.
            content = _coreconfig_db_tls_converge(content)

            _write_priv(core_config, content)

            subprocess.run(_sudo_wrap(['systemctl', 'daemon-reload']), capture_output=True, timeout=90)
            subprocess.run(_sudo_wrap(['systemctl', 'enable', 'takserver']), capture_output=True, timeout=90)
            subprocess.run(_sudo_wrap(['systemctl', 'restart', 'takserver']), capture_output=True, timeout=90)
            log.append(f'CoreConfig updated: DB→{db_host}:{db_port}, takserver restarted.')
        except Exception as e:
            return jsonify({'success': False, 'error': f'CoreConfig update failed: {e}', 'log': log}), 400
    return jsonify({'success': True, 'message': 'Server Two (Core) pre-staged. Next: fill out Certificate Information and hit Deploy TAK Server to generate certs, configure auth, and finish setup.', 'log': log})


@app.route('/api/takserver/two-server/sync-db-password', methods=['POST'])
@login_required
def takserver_two_server_sync_db_password():
    """Patch CoreConfig.xml on this host with DB password and restart TAK Server. No SSH to Server One.
    Password from: request body (paste in UI), else settings (saved from deploy). Fixes empty password / 8443 auth failure."""
    settings = load_settings()
    cfg = _get_tak_deployment_config(settings)
    if cfg.get('mode') != 'two_server':
        return jsonify({'success': False, 'error': 'Not in two-server mode'}), 400
    if not os.path.exists('/opt/tak/CoreConfig.xml'):
        return jsonify({'success': False, 'error': 'TAK Server not installed (no CoreConfig.xml)'}), 400

    data = request.get_json() or {}
    db_pass = (data.get('password') or '').strip()
    if not db_pass:
        db_pass = (cfg.get('database', {}).get('password') or '').strip()
    if not db_pass:
        return jsonify({
            'success': False,
            'error': 'No DB password provided. Paste the martiuser password from Server One in the "DB password" field (from /opt/tak/CoreConfig.example.xml on Server One), or add it in Settings → TAK deployment → Server One / Database.'
        }), 400

    # Validate the provided password against Server One before writing CoreConfig.
    s1 = cfg.get('server_one', {})
    db_port = int(cfg.get('database', {}).get('port') or 5432)
    db_user = (cfg.get('database', {}).get('user') or 'martiuser').strip() or 'martiuser'
    db_name = (cfg.get('database', {}).get('name') or 'cot').strip() or 'cot'
    if (s1.get('host') or '').strip():
        ok_pw, msg_pw = _verify_server_one_db_password(s1, db_pass, db_port=db_port, db_user=db_user, db_name=db_name)
        if not ok_pw:
            return jsonify({
                'success': False,
                'error': (
                    'Password was not accepted by PostgreSQL on Server One. '
                    'Paste the current martiuser password and try again.'
                ),
                'detail': msg_pw,
            }), 400

    try:
        # v10.0.5 non-root: read/write CoreConfig via the broker (literal `sudo cat`/
        # `sudo tee` fail as takwerx; /opt/tak is tak:tak).
        content = _read_priv('/opt/tak/CoreConfig.xml')
        if not content:
            return jsonify({'success': False, 'error': 'Could not read CoreConfig.xml'}), 400
        content = re.sub(r'(<connection[^>]*password=")[^"]*(")', lambda m: m.group(1) + db_pass + m.group(2), content)
        _write_priv('/opt/tak/CoreConfig.xml', content)
        cfg.setdefault('database', {})['password'] = db_pass
        settings['tak_deployment'] = cfg
        save_settings(settings)
        subprocess.run(_sudo_wrap(['systemctl', 'restart', 'takserver']), capture_output=True, text=True, timeout=60)
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)[:300]}), 500

    return jsonify({'success': True, 'message': 'DB password updated and TAK Server restarted. Try 8443/8446 again in a minute.'})


@app.route('/api/takserver/two-server/migrate-database/start', methods=['POST'])
@login_required
def takserver_two_server_migrate_database_start():
    """Start background migration: dump cot on current Server One, restore on new host, point Core + settings."""
    if tak_migrate_status.get('running'):
        return jsonify({'error': 'Database migration already in progress'}), 409
    if not os.path.exists('/opt/tak/CoreConfig.xml'):
        return jsonify({'error': 'TAK Server not installed'}), 400
    data = request.get_json() or {}
    new_host = (data.get('new_host') or '').strip()
    if not new_host:
        return jsonify({'error': 'new_host is required (IP or hostname of the new Server One)'}), 400
    if not _safe_migration_db_host(new_host):
        return jsonify({'error': 'Invalid new_host (use IPv4 or hostname, letters/digits/dots/hyphens only)'}), 400
    settings = load_settings()
    cfg = _get_tak_deployment_config(settings)
    if cfg.get('mode') != 'two_server':
        return jsonify({'error': 'Not in two-server mode'}), 400
    old_s1 = dict(cfg.get('server_one', {}))
    old_host = (old_s1.get('host') or '').strip()
    if not old_host:
        return jsonify({'error': 'Current Server One host not configured'}), 400
    if new_host.lower() == old_host.lower():
        return jsonify({'error': 'new_host must differ from current Server One host'}), 400
    core_ip = _resolve_core_ip(settings, cfg)
    if not core_ip:
        return jsonify({'error': 'Server Two (Core) IP unknown — set Server IP in Settings'}), 400
    new_ssh_user = (data.get('new_ssh_user') or '').strip()
    new_ssh_port = data.get('new_ssh_port')
    new_s1 = dict(old_s1)
    new_s1['host'] = new_host
    if new_ssh_user:
        new_s1['ssh_user'] = new_ssh_user
    if new_ssh_port is not None and str(new_ssh_port).strip():
        try:
            new_s1['ssh_port'] = int(new_ssh_port)
        except (TypeError, ValueError):
            return jsonify({'error': 'new_ssh_port must be a number'}), 400
    key_path = _find_ssh_key_for_server_one(old_s1)
    if key_path:
        new_s1['ssh_key_path'] = key_path
    db_port = int(cfg.get('database', {}).get('port') or 5432)
    db_user = (cfg.get('database', {}).get('user') or 'martiuser').strip() or 'martiuser'
    db_name = (cfg.get('database', {}).get('name') or 'cot').strip() or 'cot'
    uploaded_m = [f for f in os.listdir(UPLOAD_DIR) if f.endswith('.deb') or f.endswith('.rpm')]
    db_pkg_m = next((f for f in uploaded_m if 'database' in f.lower()), '')
    if not db_pkg_m:
        return jsonify({
            'error': 'No takserver-database .deb in uploads — upload it again on this page (it may have been removed). It must match the version on your current Server One.',
        }), 400
    local_deb_m = os.path.join(UPLOAD_DIR, db_pkg_m)
    if not os.path.isfile(local_deb_m):
        return jsonify({
            'error': f'Uploads reference "{db_pkg_m}" but the file is missing — upload the takserver-database .deb again before starting migration.',
        }), 400
    # Version match uses SSH to current Server One — run in worker so this POST returns fast
    # (reverse proxies often timeout slow requests → browser "Failed to fetch").
    tak_snap = copy.deepcopy(cfg)
    tak_migrate_log.clear()
    tak_migrate_status.update({'running': True, 'complete': False, 'error': False})
    threading.Thread(
        target=run_takserver_two_server_db_migrate,
        args=(dict(old_s1), dict(new_s1), tak_snap, core_ip, db_port, db_user, db_name, local_deb_m, db_pkg_m),
        daemon=True,
    ).start()
    return jsonify({'success': True})


@app.route('/api/takserver/two-server/migrate-database/log')
@login_required
def takserver_two_server_migrate_database_log():
    idx = int(request.args.get('index', 0))
    return jsonify({
        'entries': tak_migrate_log[idx:],
        'total': len(tak_migrate_log),
        'running': tak_migrate_status['running'],
        'complete': tak_migrate_status['complete'],
        'error': tak_migrate_status['error'],
    })


@app.route('/api/takserver/two-server/migration-database-deb-status', methods=['GET'])
@login_required
def takserver_migration_database_deb_status():
    """Report whether uploads include takserver-database .deb (same dir as deploy/upgrade). Uses dpkg-deb locally; no SSH."""
    uploaded = [f for f in os.listdir(UPLOAD_DIR) if f.endswith('.deb') or f.endswith('.rpm')]
    db_pkg = next((f for f in uploaded if 'database' in f.lower()), '')
    out = {
        'has_database_deb': False,
        'filename': None,
        'deb_version': None,
        'file_missing': False,
    }
    if not db_pkg:
        return jsonify(out)
    local_path = os.path.join(UPLOAD_DIR, db_pkg)
    out['filename'] = db_pkg
    if not os.path.isfile(local_path):
        out['file_missing'] = True
        return jsonify(out)
    out['has_database_deb'] = True
    _pkg, ver = _local_deb_control_fields(local_path)
    out['deb_version'] = ver
    return jsonify(out)


@app.route('/api/takserver/pin-packages', methods=['POST'])
@login_required
def takserver_pin_packages():
    """Add takserver* and postgresql* to the unattended-upgrades blacklist on both Server Two (local) and Server One (SSH).
    Prevents automatic apt upgrades from breaking the DB connection or regenerating credentials."""
    settings = load_settings()
    cfg = _get_tak_deployment_config(settings)
    is_two_server = cfg.get('mode') == 'two_server'
    results = {}

    pin_snippet = (
        'UA_CONF="/etc/apt/apt.conf.d/50unattended-upgrades"; '
        'if [ ! -f "$UA_CONF" ]; then echo NO_UA; '
        'elif grep -q "takserver" "$UA_CONF" 2>/dev/null; then echo ALREADY_PINNED; '
        'else '
        'sudo sed -i \'/Unattended-Upgrade::Package-Blacklist/a\\        "takserver*";\\n        "postgresql*";\' "$UA_CONF" 2>/dev/null && echo PINNED || echo FAILED; '
        'fi'
    )

    try:
        r = subprocess.run(pin_snippet, shell=True, capture_output=True, text=True, timeout=15)
        out = (r.stdout or '').strip()
        if 'PINNED' in out:
            results['server_two'] = 'pinned'
        elif 'ALREADY_PINNED' in out:
            results['server_two'] = 'already_pinned'
        elif 'NO_UA' in out:
            results['server_two'] = 'no_unattended_upgrades'
        else:
            results['server_two'] = 'failed'
    except Exception as e:
        results['server_two'] = f'error: {str(e)[:100]}'

    if is_two_server:
        s1 = cfg.get('server_one', {})
        if (s1.get('host') or '').strip():
            try:
                ok, out = _ssh_probe(s1, pin_snippet, timeout=15)
                out_s = (out or '').strip()
                if ok and 'PINNED' in out_s:
                    results['server_one'] = 'pinned'
                elif ok and 'ALREADY_PINNED' in out_s:
                    results['server_one'] = 'already_pinned'
                elif ok and 'NO_UA' in out_s:
                    results['server_one'] = 'no_unattended_upgrades'
                else:
                    results['server_one'] = f'failed: {out_s[:100]}'
            except Exception as e:
                results['server_one'] = f'error: {str(e)[:100]}'
        else:
            results['server_one'] = 'no_host_configured'

    all_ok = all(v in ('pinned', 'already_pinned', 'no_unattended_upgrades') for v in results.values())
    msgs = []
    for server, status in results.items():
        label = 'Server One (DB)' if server == 'server_one' else 'This host'
        if status == 'pinned':
            msgs.append(f'{label}: packages pinned')
        elif status == 'already_pinned':
            msgs.append(f'{label}: already pinned')
        elif status == 'no_unattended_upgrades':
            # v10.1.37: this used to read "(safe)". On RHEL/Rocky the apt config
            # file is ALWAYS absent, so every EL box was told it was safe on the
            # strength of a file we never expected to find — a guess, not a check.
            # The EL analogue is dnf-automatic; report what we actually observed.
            if _pkg_mgr() == 'dnf':
                _p = _auto_update_posture()
                if not _p.get('installed'):
                    msgs.append(f'{label}: dnf-automatic not installed — nothing updates this host automatically')
                elif _p.get('enabled'):
                    msgs.append(f'{label}: ⚠ dnf-automatic is ENABLED and has no package allowlist — it can update TAK components')
                else:
                    msgs.append(f'{label}: dnf-automatic installed but not enabled')
            else:
                msgs.append(f'{label}: unattended-upgrades not installed')
        else:
            msgs.append(f'{label}: {status}')

    return jsonify({'success': all_ok, 'results': results, 'message': '; '.join(msgs)})


def _pin_status_short(s):
    """Short label for pin status for UI breakdown."""
    return {'pinned': 'locked', 'not_pinned': 'unlocked', 'safe': 'unlocked (no UA)', 'unknown': '?'}.get(s, s)


@app.route('/api/takserver/pin-packages/status')
@login_required
def takserver_pin_packages_status():
    """Check if takserver/postgresql packages are already pinned on both hosts."""
    settings = load_settings()
    cfg = _get_tak_deployment_config(settings)
    is_two_server = cfg.get('mode') == 'two_server'
    results = {}

    check_cmd = (
        'UA_CONF="/etc/apt/apt.conf.d/50unattended-upgrades"; '
        'if [ ! -f "$UA_CONF" ]; then echo NO_UA; '
        'elif grep -q "takserver" "$UA_CONF" 2>/dev/null; then echo PINNED; '
        'else echo NOT_PINNED; fi'
    )

    try:
        r = subprocess.run(check_cmd, shell=True, capture_output=True, text=True, timeout=10)
        out = (r.stdout or '').strip()
        results['server_two'] = 'pinned' if 'PINNED' in out else ('safe' if 'NO_UA' in out else 'not_pinned')
    except Exception:
        results['server_two'] = 'unknown'

    if is_two_server:
        s1 = cfg.get('server_one', {})
        if (s1.get('host') or '').strip():
            try:
                ok, out = _ssh_probe(s1, check_cmd, timeout=10)
                out_s = (out or '').strip()
                if ok and 'PINNED' in out_s:
                    results['server_one'] = 'pinned'
                elif ok and 'NO_UA' in out_s:
                    results['server_one'] = 'safe'
                elif ok:
                    results['server_one'] = 'not_pinned'
                else:
                    results['server_one'] = 'unknown'
            except Exception:
                results['server_one'] = 'unknown'

    # Only show "Locked" when blacklist is actually present. 'safe' (no UA file) = show Unlocked.
    all_pinned = all(v == 'pinned' for v in results.values())
    # Per-host breakdown for two-server so UI can show which host is still pinned.
    breakdown = []
    if results.get('server_two') is not None:
        breakdown.append('This host: ' + _pin_status_short(results['server_two']))
    if results.get('server_one') is not None:
        breakdown.append('DB host: ' + _pin_status_short(results['server_one']))
    return jsonify({'pinned': all_pinned, 'results': results, 'breakdown': ' · '.join(breakdown) if breakdown else None})


def _recommended_takserver_heap_gb(total_ram_gb):
    """Suggest -Xmx heap in GB from total system RAM (TAK Server core runs on this host)."""
    if total_ram_gb is None or total_ram_gb <= 0:
        return 4
    if total_ram_gb >= 32:
        return 12
    if total_ram_gb >= 16:
        return 8
    if total_ram_gb >= 8:
        return 4
    return 2


def _get_current_takserver_heap_gb():
    """Return current total JVM heap in GB from /etc/default/takserver or setenv.sh, else None."""
    import re
    defaults_file = '/etc/default/takserver'
    for path in [defaults_file]:
        content = None
        try:
            with open(path, 'r') as f:
                content = f.read()
        except (OSError, IOError):
            try:
                content = _read_priv(path) or content  # v10.0.5 non-root: broker read (literal `sudo cat` bypassed the broker)
            except Exception:
                pass
        if content:
            m = re.search(r'# infra-TAK total heap: (\d+)g', content)
            if m:
                return int(m.group(1))
    setenv = '/opt/tak/setenv.sh'
    content = None
    try:
        with open(setenv, 'r') as f:
            content = f.read()
    except (OSError, IOError):
        try:
            content = _read_priv(setenv) or content  # v10.0.5 non-root: broker read (literal `sudo cat` bypassed the broker)
        except Exception:
            pass
    if content:
        m = re.search(r'-Xmx(\d+)g', content, re.IGNORECASE)
        if m:
            return int(m.group(1))
    return None


TAKSERVER_HEAP_VARS = ('CONFIG_MAX_HEAP', 'API_MAX_HEAP', 'MESSAGING_MAX_HEAP',
                       'PLUGIN_MANAGER_MAX_HEAP', 'RETENTION_MAX_HEAP')
_TAKSERVER_HEAP_BLOCK_A = '# >>> infra-TAK managed heap >>>'
_TAKSERVER_HEAP_BLOCK_B = '# <<< infra-TAK managed heap <<<'


def _merge_takserver_heap_defaults(existing, heap_gb, heaps_mb):
    """Return /etc/default/takserver with infra-TAK's heap vars replaced and everything else kept.

    GH #282: set-heap used to write the whole file, so an operator's own variables were
    dropped every time the suggested heap was applied. infra-TAK owns only the five
    *_MAX_HEAP vars: any line setting one of them (with or without `export`) is removed,
    as are our previous managed block and the two unmarked comment lines older releases
    wrote, and one managed block is appended at the end so it wins over anything above it.
    `heaps_mb` maps each name in TAKSERVER_HEAP_VARS to its value in MB.
    """
    import re as _re
    text = _re.sub(rf'{_re.escape(_TAKSERVER_HEAP_BLOCK_A)}.*?{_re.escape(_TAKSERVER_HEAP_BLOCK_B)}\n?',
                   '', existing or '', flags=_re.DOTALL)
    owned = _re.compile(r'^\s*(?:export\s+)?(?:%s)=' % '|'.join(TAKSERVER_HEAP_VARS))
    legacy = ('# infra-TAK total heap:', '# Proportional split across TAK Server processes')
    kept = [ln for ln in text.splitlines()
            if not owned.match(ln) and not ln.strip().startswith(legacy)]
    while kept and not kept[-1].strip():
        kept.pop()
    block = [_TAKSERVER_HEAP_BLOCK_A,
             f'# infra-TAK total heap: {heap_gb}g',
             '# Proportional split across TAK Server processes (same ratios as setenv.sh defaults)']
    block += [f'export {name}={int(heaps_mb[name])}' for name in TAKSERVER_HEAP_VARS]
    block.append(_TAKSERVER_HEAP_BLOCK_B)
    return '\n'.join(kept + ([''] if kept else []) + block) + '\n'


@app.route('/api/takserver/heap-info')
@login_required
def takserver_heap_info():
    """Return total RAM, recommended heap, and current heap (if set via drop-in) for this host."""
    total = _get_total_ram_gb_local()
    recommended = _recommended_takserver_heap_gb(total)
    current = _get_current_takserver_heap_gb()
    return jsonify({'total_ram_gb': total, 'recommended_heap_gb': recommended, 'current_heap_gb': current})


@app.route('/api/takserver/set-heap', methods=['POST'])
@login_required
def takserver_set_heap():
    """Set TAK Server JVM heap via /etc/default/takserver (individual MAX_HEAP vars) and restart."""
    data = request.get_json() or {}
    heap_gb = data.get('heap_gb')
    total_ram_gb = _get_total_ram_gb_local()
    if heap_gb is None:
        heap_gb = _recommended_takserver_heap_gb(total_ram_gb)
    try:
        heap_gb = int(heap_gb)
        if heap_gb < 2 or heap_gb > 64:
            return jsonify({'success': False, 'error': 'heap_gb must be between 2 and 64'}), 400
    except (TypeError, ValueError):
        return jsonify({'success': False, 'error': 'heap_gb must be an integer'}), 400

    import re as _re
    total_mb = heap_gb * 1024
    w_config = 1.0 / 35000
    w_api = 1.0 / 6300
    w_msg = 1.0 / 6300
    w_plugin = 1.0 / 30000
    w_retain = 1.0 / 30000
    w_total = w_config + w_api + w_msg + w_plugin + w_retain
    config_mb = int(total_mb * w_config / w_total)
    api_mb = int(total_mb * w_api / w_total)
    msg_mb = int(total_mb * w_msg / w_total)
    plugin_mb = int(total_mb * w_plugin / w_total)
    retain_mb = int(total_mb * w_retain / w_total)

    defaults_file = '/etc/default/takserver'
    # GH #282: merge into the operator's file instead of replacing it. A file that exists
    # but cannot be read is a refusal, never a blank slate to overwrite.
    existing = ''
    if _exists_priv(defaults_file):
        try:
            existing = _read_own_or_priv(defaults_file)
        except Exception as _rd_err:
            return jsonify({'success': False, 'error': f'Could not read {defaults_file}, left it unchanged: {str(_rd_err)[:200]}'}), 500
    defaults_content = _merge_takserver_heap_defaults(existing, heap_gb, {
        'CONFIG_MAX_HEAP': config_mb, 'API_MAX_HEAP': api_mb, 'MESSAGING_MAX_HEAP': msg_mb,
        'PLUGIN_MANAGER_MAX_HEAP': plugin_mb, 'RETENTION_MAX_HEAP': retain_mb})
    try:
        # v10.0.5 non-root: /etc/default/takserver + /opt/tak/setenv.sh are root-owned;
        # was bare `sudo tee`/`sudo cat` (bypass broker → EPERM non-root). Route via broker.
        try:
            _write_priv(defaults_file, defaults_content)
        except Exception as _we:
            return jsonify({'success': False, 'error': f'Failed to write {defaults_file}: {str(_we)[:200]}'}), 500

        setenv = '/opt/tak/setenv.sh'
        try:
            _setenv_cur = _read_priv(setenv)
        except Exception:
            _setenv_cur = ''
        if _setenv_cur:
            cleaned = _re.sub(r'\n*export JAVA_OPTS="\$JAVA_OPTS\s+-Xms\d+[gGmM]\s+-Xmx\d+[gGmM]"\n*', '\n', _setenv_cur)
            # v10.0.5 container TAK: the container does NOT mount or read /etc/default/takserver
            # (no systemd unit) — its entrypoint sources ONLY /opt/tak/setenv.sh, which RAM-auto-
            # computes the per-process heaps UNLESS *_MAX_HEAP is already set (`if [ -z … ]`). So on
            # container we must inject the operator's values into setenv.sh itself, or set-heap
            # silently no-ops (confirmed on aws-arm: 8g written to /etc/default was ignored; the
            # container kept the RAM-auto -Xmx). Idempotent managed block, prepended so it is in
            # scope before setenv.sh's own `if [ -z ]` guards run.
            if _tak_is_container():
                _hm_a = '# >>> infra-TAK managed heap >>>'
                _hm_b = '# <<< infra-TAK managed heap <<<'
                cleaned = _re.sub(rf'{_re.escape(_hm_a)}.*?{_re.escape(_hm_b)}\n?', '', cleaned, flags=_re.DOTALL)
                _hm_block = (f"{_hm_a}\n"
                             f"# total {heap_gb}g via console — delete this block to revert to RAM-auto\n"
                             f"export CONFIG_MAX_HEAP={config_mb}\n"
                             f"export API_MAX_HEAP={api_mb}\n"
                             f"export MESSAGING_MAX_HEAP={msg_mb}\n"
                             f"export PLUGIN_MANAGER_MAX_HEAP={plugin_mb}\n"
                             f"export RETENTION_MAX_HEAP={retain_mb}\n"
                             f"{_hm_b}\n")
                cleaned = _hm_block + cleaned
            if cleaned != _setenv_cur:
                _write_priv(setenv, cleaned)

        rr = subprocess.run(_tak_systemctl('restart'), shell=True, capture_output=True, text=True, timeout=120)  # v10.0.1: container-aware
        if rr.returncode != 0:
            return jsonify({'success': False, 'error': f'Restart failed: {(rr.stderr or rr.stdout or "unknown").strip()[:200]}'}), 500
    except subprocess.TimeoutExpired:
        return jsonify({'success': False, 'error': 'Command timed out'}), 500
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)[:200]}), 500
    return jsonify({
        'success': True,
        'message': f'TAK Server heap set to {heap_gb} GB total across 5 processes and restarted.',
        'heap_gb': heap_gb,
        'current_heap_gb': heap_gb,
        'total_ram_gb': total_ram_gb,
    })


@app.route('/api/takserver/unpin-packages', methods=['POST'])
@login_required
def takserver_unpin_packages():
    """Remove takserver* and postgresql* from unattended-upgrades blacklist on both servers."""
    settings = load_settings()
    cfg = _get_tak_deployment_config(settings)
    is_two_server = cfg.get('mode') == 'two_server'
    results = {}

    # Remove blacklist lines; verify after so we only report UNPINNED when "takserver" is really gone.
    unpin_script = (
        'UA_CONF="/etc/apt/apt.conf.d/50unattended-upgrades"; '
        'if [ ! -f "$UA_CONF" ]; then echo NO_UA; exit 0; fi; '
        'if ! grep -q "takserver" "$UA_CONF" 2>/dev/null; then echo ALREADY_UNPINNED; exit 0; fi; '
        'sudo sed -i -e \'/"takserver\\*"/d\' -e \'/"postgresql\\*"/d\' "$UA_CONF" 2>/dev/null; '
        'if grep -q "takserver" "$UA_CONF" 2>/dev/null; then echo FAILED; else echo UNPINNED; fi'
    )

    try:
        r = subprocess.run(unpin_script, shell=True, capture_output=True, text=True, timeout=15)
        out = (r.stdout or '').strip()
        if 'UNPINNED' in out:
            results['server_two'] = 'unpinned'
        elif 'ALREADY_UNPINNED' in out:
            results['server_two'] = 'already_unpinned'
        elif 'NO_UA' in out:
            results['server_two'] = 'no_unattended_upgrades'
        else:
            results['server_two'] = 'failed'
    except Exception as e:
        results['server_two'] = f'error: {str(e)[:100]}'

    if is_two_server:
        s1 = cfg.get('server_one', {})
        if (s1.get('host') or '').strip():
            try:
                ok, out = _ssh_probe(s1, unpin_script, timeout=15)
                out_s = (out or '').strip()
                if ok and 'UNPINNED' in out_s:
                    results['server_one'] = 'unpinned'
                elif ok and 'ALREADY_UNPINNED' in out_s:
                    results['server_one'] = 'already_unpinned'
                elif ok and 'NO_UA' in out_s:
                    results['server_one'] = 'no_unattended_upgrades'
                else:
                    results['server_one'] = f'failed: {out_s[:100]}'
            except Exception as e:
                results['server_one'] = f'error: {str(e)[:100]}'

    all_ok = all(v in ('unpinned', 'already_unpinned', 'no_unattended_upgrades') for v in results.values())
    msgs = []
    for server, status in results.items():
        label = 'Server One (DB)' if server == 'server_one' else 'This host'
        if status in ('unpinned', 'already_unpinned', 'no_unattended_upgrades'):
            continue
        msgs.append(f'{label}: {status}')
    message = '; '.join(msgs) if msgs else ('Unlocked on all hosts' if all_ok else 'Unlock failed')
    return jsonify({'success': all_ok, 'results': results, 'message': message})


