@app.route('/api/netbird/control', methods=['POST'])
@login_required
@_records_module_update(  # v10.2.8 W10
    'netbird',
    when=lambda: (request.get_json(silent=True) or {}).get('action') == 'update',
    from_fn=lambda: (_get_netbird_version_info().get('version') or ''),
    to_fn=lambda: _get_netbird_target_images()[0].rsplit(':', 1)[-1])
def netbird_control_api():
    action = (request.json or {}).get('action', '')
    if action not in ('start', 'stop', 'restart', 'update'):
        return jsonify({'error': 'Invalid action'}), 400
    
    nb_dir = NETBIRD_INSTALL_DIR
    if not os.path.exists(os.path.join(nb_dir, 'docker-compose.yml')):
        return jsonify({'error': 'NetBird is not installed'}), 404
    
    import subprocess as _sp
    if action == 'update':
        # v10.0.9: NetBird is pinned. A box may carry a stale/broken tag on disk (an older pin,
        # or the briefly-shipped :latest that broke auth), so rewrite the compose to the vetted
        # pin BEFORE pull — Update always converges the box onto the tested image, never chases
        # upstream latest. (Bumping the pin in a release is what actually moves NetBird forward.)
        _netbird_sync_compose_image_tags(nb_dir)
        pull = _sp.run(_sudo_wrap(['docker', 'compose', 'pull', 'netbird-server', 'dashboard']),
                       capture_output=True, text=True, cwd=nb_dir, timeout=600)
        if pull.returncode != 0:
            err = (pull.stderr or pull.stdout or 'docker compose pull failed').strip()[:400]
            return jsonify({'success': False, 'error': err}), 500
        try:
            _netbird_recreate_containers(nb_dir, lambda _m: None)
            _netbird_finalize_account_store()
        except Exception as ex:
            return jsonify({'success': False, 'error': str(ex)[:300]}), 500
        time.sleep(2)
        r_status = _sp.run(_sudo_wrap(['docker', 'inspect', '-f', '{{.State.Running}}', 'netbird-server']),
                             capture_output=True, text=True)
        running = r_status.stdout.strip() == 'true'
        vinfo = _get_netbird_version_info()
        return jsonify({
            'success': True,
            'running': running,
            'action': action,
            'pull': 'Pulled latest netbird-server and dashboard images',
            'version': vinfo.get('version') or '',
        })
    if action == 'start':
        _sp.run(_sudo_wrap(['docker', 'compose', 'start']), capture_output=True, cwd=nb_dir)
    elif action == 'stop':
        _sp.run(_sudo_wrap(['docker', 'compose', 'stop']), capture_output=True, cwd=nb_dir)
    elif action == 'restart':
        _sp.run(_sudo_wrap(['docker', 'compose', 'restart']), capture_output=True, cwd=nb_dir)
        
    time.sleep(2)
    r_status = _sp.run(_sudo_wrap(['docker', 'inspect', '-f', '{{.State.Running}}', 'netbird-server']), capture_output=True, text=True)
    running = r_status.stdout.strip() == 'true'
    return jsonify({'success': True, 'running': running})

