# ── Leg 4 — CONNECT ANCHOR (box-side automation) ──────────────────────────────
# Turns the manual wg0.conf hand-assembly into a form: the console generates the
# box WireGuard keypair, writes the tunnel config, and dials the anchor. The
# anchor VPS itself is still stood up manually (RUNBOOK-oracle-anchor-provisioning,
# private notes) — this automates only the box half. Field-validated field defaults
# from the 2026-07-07 Starlink build: overlay 172.31.99.0/24, box .2, anchor .1,
# udp/443 (guest nets filter high UDP ports; 443 looks like HTTPS/QUIC).
_CONN_WG_IF = 'wg0'
_CONN_BOX_WG_IP = '172.31.99.2'
_CONN_ANCHOR_WG_IP = '172.31.99.1'
_CONN_WG_KEY_RE = re.compile(r'^[A-Za-z0-9+/]{43}=$')  # 32-byte base64 WireGuard key


def _conn_wg_conf_path():
    return '/etc/wireguard/%s.conf' % _CONN_WG_IF


def _conn_anchor_status():
    """Parse `wg show wg0` into a status dict. Never raises."""
    out = {'configured': False, 'up': False, 'handshake_secs': None,
           'endpoint': '', 'rx_bytes': None, 'tx_bytes': None}
    settings = load_settings()
    anchor = settings.get('connectivity_anchor') or {}
    if anchor.get('anchor_ip'):
        out['configured'] = True
        out['anchor_ip'] = anchor.get('anchor_ip')
        out['wg_port'] = anchor.get('wg_port')
        out['box_pubkey'] = anchor.get('box_pubkey', '')
        # v10.1.10: is the relay running the bootstrap we currently ship? Relays
        # provisioned by an older console keep whatever that version wrote — e.g.
        # the pre-hardening prober that bound 0.0.0.0 instead of the tunnel IP
        # (found in the field 2026-07-26). Stamp mismatch drives both the console
        # banner and the boot-time auto re-assert below.
        out['bootstrap_sha'] = anchor.get('bootstrap_sha', '')
        out['bootstrap_current'] = (anchor.get('bootstrap_sha') == _CONN_ANCHOR_BOOTSTRAP_SHA256)
        out['can_reassert'] = os.path.exists(_CONN_ANCHOR_KEY_PATH)
    try:
        r = subprocess.run(_sudo_wrap(['wg', 'show', _CONN_WG_IF, 'dump']),
                           capture_output=True, text=True, timeout=8)
        if r.returncode != 0 or not r.stdout.strip():
            return out
        lines = r.stdout.strip().splitlines()
        # dump format: first line = interface; peer lines follow (tab-separated).
        # peer: pubkey preshared endpoint allowed-ips latest-handshake rx tx keepalive
        for ln in lines[1:]:
            f = ln.split('\t')
            if len(f) >= 8:
                out['up'] = True
                out['endpoint'] = f[2] if f[2] != '(none)' else ''
                hs = int(f[4]) if f[4].isdigit() else 0
                out['rx_bytes'] = int(f[5]) if f[5].isdigit() else 0
                out['tx_bytes'] = int(f[6]) if f[6].isdigit() else 0
                if hs > 0:
                    import time as _t
                    # dump gives an absolute epoch for latest handshake; convert to age.
                    out['handshake_secs'] = max(0, int(_t.time()) - hs)
    except Exception:
        pass
    return out


@app.route('/api/connectivity/anchor/status')
@login_required
def connectivity_anchor_status_api():
    return jsonify(_conn_anchor_status())


def _conn_validate_anchor_inputs(anchor_ip, anchor_pubkey, wg_port):
    """Shared strict validation. Returns (ok, wg_port_int_or_error_string)."""
    try:
        ipaddress.ip_address(anchor_ip)
    except (ValueError, TypeError):
        return False, 'Anchor IP is not a valid IP address.'
    if anchor_pubkey is not None and not _CONN_WG_KEY_RE.fullmatch(anchor_pubkey or ''):
        return False, 'Anchor WireGuard public key is malformed (expected a 44-char base64 key ending in "=").'
    try:
        wg_port = int(wg_port)
    except (ValueError, TypeError):
        return False, 'WireGuard port must be a number.'
    if not (1 <= wg_port <= 65535):
        return False, 'WireGuard port out of range.'
    return True, wg_port


def _conn_configure_box_tunnel(anchor_ip, anchor_pubkey, wg_port):
    """Generate the box keypair, write /etc/wireguard/wg0.conf, bring up the tunnel.
    Callers must have validated inputs already. Returns (ok, box_pubkey, error)."""
    if not shutil.which('wg'):
        try:
            _pkg_install(['wireguard-tools'])
        except Exception as ex:
            return False, '', 'Could not install wireguard-tools: %s' % str(ex)[:160]
        if not shutil.which('wg'):
            return False, '', 'wireguard-tools unavailable after install.'
    try:
        priv = subprocess.run(['wg', 'genkey'], capture_output=True, text=True, timeout=10).stdout.strip()
        pub = subprocess.run(['wg', 'pubkey'], input=priv + '\n', capture_output=True, text=True, timeout=10).stdout.strip()
    except Exception as ex:
        return False, '', 'Key generation failed: %s' % str(ex)[:160]
    if not (_CONN_WG_KEY_RE.fullmatch(priv) and _CONN_WG_KEY_RE.fullmatch(pub)):
        return False, '', 'Generated key looked malformed — aborting.'
    conf = (
        '[Interface]\n'
        'Address = %s/24\n'
        # MTU 1280 (IPv6 floor): wg-quick's auto MTU assumes a 1500 path; cellular
        # carriers translate IPv4 into IPv6 (464XLAT, +20B) and the encapsulated
        # packet silently exceeds the path — small packets (handshakes, pings,
        # 302s) pass, the first full-size TCP segment dies forever (field-hit
        # 2026-07-11 night: console 000 through the tunnel over AT&T while ping
        # worked; relay SACKed every byte EXCEPT the first 1368-byte segment).
        'MTU = 1280\n'
        'PrivateKey = %s\n\n'
        '[Peer]\n'
        'PublicKey = %s\n'
        'Endpoint = %s:%d\n'
        'AllowedIPs = %s/32\n'
        'PersistentKeepalive = 25\n'
    ) % (_CONN_BOX_WG_IP, priv, anchor_pubkey, anchor_ip, wg_port, _CONN_ANCHOR_WG_IP)
    tmp_path = None
    try:
        fd, tmp_path = tempfile.mkstemp(prefix='wg-', suffix='.conf')
        os.write(fd, conf.encode())
        os.close(fd)
        os.chmod(tmp_path, 0o600)
        inst = _run_priv_chain([
            ['install', '-D', '-m', '600', '-o', 'root', '-g', 'root', tmp_path, _conn_wg_conf_path()],
        ], mode='and')
        if not inst or inst.returncode != 0:
            return False, '', 'Could not write tunnel config: %s' % ((inst.stderr if inst else '') or 'install failed')[:160]
    finally:
        if tmp_path and os.path.exists(tmp_path):
            try:
                os.remove(tmp_path)
            except Exception:
                pass
    up = _run_priv_chain([
        ['systemctl', 'enable', 'wg-quick@%s' % _CONN_WG_IF],
        ['systemctl', 'restart', 'wg-quick@%s' % _CONN_WG_IF],
    ], mode='seq')
    if not up or up.returncode != 0:
        return False, '', 'Tunnel config written but bring-up failed: %s' % ((up.stderr if up else '') or 'systemctl failed')[:160]
    return True, pub, ''


@app.route('/api/connectivity/anchor/configure', methods=['POST'])
@login_required
def connectivity_anchor_configure_api():
    data = request.get_json(silent=True) or {}
    anchor_ip = (data.get('anchor_ip') or '').strip()
    anchor_pubkey = (data.get('anchor_pubkey') or '').strip()
    ok, wg_port = _conn_validate_anchor_inputs(anchor_ip, anchor_pubkey, data.get('wg_port', 51820))
    if not ok:
        return jsonify({'success': False, 'error': wg_port}), 400
    cfg_ok, pub, err = _conn_configure_box_tunnel(anchor_ip, anchor_pubkey, wg_port)
    if not cfg_ok:
        return jsonify({'success': False, 'error': err}), 500

    settings = load_settings()
    settings['connectivity_anchor'] = {
        'anchor_ip': anchor_ip, 'anchor_pubkey': anchor_pubkey,
        'wg_port': wg_port, 'box_pubkey': pub,
    }
    save_settings(settings)
    return jsonify({
        'success': True,
        'box_pubkey': pub,
        'add_box_cmd': 'sudo ./connectivity-anchor-bootstrap.sh add-box %s' % pub,
    })


@app.route('/api/connectivity/anchor/disconnect', methods=['POST'])
@login_required
def connectivity_anchor_disconnect_api():
    _run_priv_chain([
        ['systemctl', 'disable', 'wg-quick@%s' % _CONN_WG_IF],
        ['systemctl', 'stop', 'wg-quick@%s' % _CONN_WG_IF],
        ['rm', '-f', _conn_wg_conf_path()],
    ], mode='seq')
    settings = load_settings()
    settings.pop('connectivity_anchor', None)
    save_settings(settings)
    return jsonify({'success': True})


# ── Leg 4 (full) — PROVISION ANCHOR OVER SSH (upload the .key, console does it all) ──
# Mirrors the TAK split-deploy pattern (takserver_two_server_upload_ssh_key): the
# operator makes the Oracle VM + downloads its SSH key, then just enters the anchor
# IP and uploads that key. The console SSHes in, runs the bootstrap, reads the WG
# public key out of the output, configures the box tunnel, and authorizes the box on
# the anchor with add-box — no terminal, no hand-copied keys.
# v10.1.3 (security residual from the 10.1.2 review): the bootstrap is fetched from
# an IMMUTABLE commit SHA (never a branch) and its bytes are verified against a known
# SHA-256 before it runs as root on the operator's anchor — no curl|bash of mutable
# remote code (CLAUDE.md supply-chain rule). WHEN YOU EDIT connectivity-anchor-
# bootstrap.sh: commit it, then update BOTH the commit SHA in the URL and the digest
# below (`git show <sha>:scripts/connectivity-anchor-bootstrap.sh | shasum -a 256`).
_CONN_ANCHOR_BOOTSTRAP_COMMIT = '44d6a17132f3e3c2a424c3bb3278b7bc5630ff2b'
_CONN_ANCHOR_BOOTSTRAP_SHA256 = 'e86c99bcb1f76ef4e8059e281aff186c4e04120a3dccb226ac14045d7a628212'
_CONN_ANCHOR_BOOTSTRAP_RAW = ('https://raw.githubusercontent.com/takwerx/infra-TAK/'
                              + _CONN_ANCHOR_BOOTSTRAP_COMMIT
                              + '/scripts/connectivity-anchor-bootstrap.sh')
_CONN_ANCHOR_KEY_PATH = os.path.expanduser('~/.ssh/infratak_anchor')
_CONN_SSH_USER_RE = re.compile(r'^[a-z_][a-z0-9_-]{0,31}$')
_connectivity_provision_status = {'running': False, 'complete': False, 'error': '', 'log': []}


def _conn_prov_log(msg):
    _connectivity_provision_status['log'].append(msg)


def _conn_write_anchor_key(key_text):
    """Write + validate the uploaded anchor SSH private key to a FIXED 0600 path
    (never request-controlled → no traversal). Rejects passphrase-protected keys
    (can't be used non-interactively). Returns (ok, error). Mirrors split-deploy."""
    key_text = (key_text or '').replace('\r\n', '\n').replace('\r', '\n')
    if not key_text.strip():
        return False, 'No SSH key provided.'
    if not key_text.endswith('\n'):
        key_text += '\n'
    if '-----BEGIN' not in key_text or 'PRIVATE KEY' not in key_text:
        return False, 'That does not look like an SSH private key (expected a "-----BEGIN … PRIVATE KEY-----" block, e.g. the Oracle .key file).'
    try:
        os.makedirs(os.path.dirname(_CONN_ANCHOR_KEY_PATH), mode=0o700, exist_ok=True)
        fd = os.open(_CONN_ANCHOR_KEY_PATH, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600)
        with os.fdopen(fd, 'w') as f:
            f.write(key_text)
        os.chmod(_CONN_ANCHOR_KEY_PATH, 0o600)
    except Exception as e:
        return False, 'Could not store key: %s' % str(e)[:160]
    try:
        r = subprocess.run(['ssh-keygen', '-y', '-f', _CONN_ANCHOR_KEY_PATH],
                           capture_output=True, text=True, timeout=10,
                           stdin=subprocess.DEVNULL)
    except Exception as e:
        try:
            os.remove(_CONN_ANCHOR_KEY_PATH)
        except Exception:
            pass
        return False, 'Key validation failed: %s' % str(e)[:160]
    if r.returncode != 0:
        try:
            os.remove(_CONN_ANCHOR_KEY_PATH)
        except Exception:
            pass
        _e = (r.stderr or r.stdout or '').lower()
        if 'passphrase' in _e:
            return False, 'The key is passphrase-protected — re-export it without a passphrase and upload that.'
        return False, 'Invalid or unsupported private key format.'
    return True, ''


def _conn_anchor_ssh(anchor_ip, ssh_user, remote_cmd, timeout=180):
    """Run one command on the anchor over SSH with the uploaded key. Returns (ok, output)."""
    host_cfg = {'host': anchor_ip, 'ssh_user': ssh_user, 'ssh_port': 22,
                'auth_method': 'ssh_key', 'ssh_key_path': _CONN_ANCHOR_KEY_PATH}
    return _ssh_probe(host_cfg, remote_cmd, timeout=timeout)


def _run_connectivity_provision(anchor_ip, ssh_user, wg_port):
    st = _connectivity_provision_status
    try:
        _conn_prov_log('Connecting to relay %s as %s…' % (anchor_ip, ssh_user))
        ok, out = _conn_anchor_ssh(anchor_ip, ssh_user, 'echo relay-reachable', timeout=25)
        if not ok:
            st.update({'running': False, 'complete': True, 'error': 'Cannot SSH to the relay: %s' % out[:200]})
            return
        # Fetch, VERIFY the pinned SHA-256, then run the bootstrap on the anchor. The
        # URL is an immutable commit SHA + fixed digest (no branch); WG_PORT is a
        # validated int. Nothing operator-typed lands in this remote shell string. A
        # digest mismatch aborts BEFORE any sudo bash runs (supply-chain guard).
        _conn_prov_log('Running the relay setup (this installs WireGuard + forwards)…')
        setup_cmd = ("curl -fsSL '%s' -o ~/connectivity-anchor-bootstrap.sh && "
                     "echo '%s  '$HOME'/connectivity-anchor-bootstrap.sh' | sha256sum -c - && "
                     "chmod +x ~/connectivity-anchor-bootstrap.sh && "
                     "sudo WG_PORT=%d bash ~/connectivity-anchor-bootstrap.sh setup"
                     ) % (_CONN_ANCHOR_BOOTSTRAP_RAW, _CONN_ANCHOR_BOOTSTRAP_SHA256, wg_port)
        ok, out = _conn_anchor_ssh(anchor_ip, ssh_user, setup_cmd, timeout=240)
        if not ok:
            _err = out[:300]
            if 'sha256sum' in out.lower() or 'FAILED' in out:
                _err = 'Anchor bootstrap integrity check failed (unexpected script contents) — aborted before running. %s' % _err
            st.update({'running': False, 'complete': True, 'error': 'Anchor bootstrap failed: %s' % _err})
            return
        m = re.search(r'WireGuard public key\s*:\s*([A-Za-z0-9+/]{43}=)', out)
        if not m:
            st.update({'running': False, 'complete': True, 'error': 'Could not read the relay WireGuard key from the setup output.'})
            return
        anchor_pubkey = m.group(1)
        _conn_prov_log('Relay is up. Configuring this box\'s tunnel…')
        cfg_ok, box_pub, err = _conn_configure_box_tunnel(anchor_ip, anchor_pubkey, wg_port)
        if not cfg_ok:
            st.update({'running': False, 'complete': True, 'error': err})
            return
        _conn_prov_log('Authorizing this box on the relay…')
        # box_pub is a validated base64 WG key (fullmatch in _conn_configure_box_tunnel).
        addbox_cmd = 'sudo bash ~/connectivity-anchor-bootstrap.sh add-box %s' % box_pub
        ok, out = _conn_anchor_ssh(anchor_ip, ssh_user, addbox_cmd, timeout=60)
        if not ok:
            st.update({'running': False, 'complete': True, 'error': 'Box configured but authorizing it on the relay failed: %s' % out[:200]})
            return
        settings = load_settings()
        settings['connectivity_anchor'] = {
            'anchor_ip': anchor_ip, 'anchor_pubkey': anchor_pubkey,
            'wg_port': wg_port, 'box_pubkey': box_pub, 'provisioned': True,
            'bootstrap_sha': _CONN_ANCHOR_BOOTSTRAP_SHA256,
            # Kept so a later re-assert reaches the relay without asking again —
            # Oracle's Ubuntu images use 'ubuntu', the RHEL ones 'opc'.
            'ssh_user': ssh_user,
        }
        save_settings(settings)
        _conn_prov_log('Done. The tunnel is dialing — status will show connected shortly.')
        st.update({'running': False, 'complete': True, 'error': ''})
    except Exception as ex:
        st.update({'running': False, 'complete': True, 'error': str(ex)[:300]})


@app.route('/api/connectivity/anchor/provision', methods=['POST'])
@login_required
def connectivity_anchor_provision_api():
    if _connectivity_provision_status.get('running'):
        return jsonify({'success': False, 'error': 'A provisioning run is already in progress.'}), 409
    data = request.get_json(silent=True) or {}
    anchor_ip = (data.get('anchor_ip') or '').strip()
    ssh_user = (data.get('ssh_user') or 'ubuntu').strip()
    ssh_key = data.get('ssh_private_key') or ''
    ok, wg_port = _conn_validate_anchor_inputs(anchor_ip, None, data.get('wg_port', 51820))
    if not ok:
        return jsonify({'success': False, 'error': wg_port}), 400
    if not _CONN_SSH_USER_RE.fullmatch(ssh_user):
        return jsonify({'success': False, 'error': 'SSH username has invalid characters.'}), 400
    key_ok, key_err = _conn_write_anchor_key(ssh_key)
    if not key_ok:
        return jsonify({'success': False, 'error': key_err}), 400
    _connectivity_provision_status.update({'running': True, 'complete': False, 'error': '', 'log': []})
    threading.Thread(target=_run_connectivity_provision, args=(anchor_ip, ssh_user, wg_port), daemon=True).start()
    return jsonify({'success': True})


@app.route('/api/connectivity/anchor/provision-status')
@login_required
def connectivity_anchor_provision_status_api():
    st = _connectivity_provision_status
    return jsonify({'running': st.get('running', False), 'complete': st.get('complete', False),
                    'error': st.get('error', ''), 'log': st.get('log', [])})


# ── v10.1.10 — relay re-assert (console-path delivery for relay-side fixes) ────
# A relay is provisioned once and then never touched again, so any fix we make to
# connectivity-anchor-bootstrap.sh only ever reaches NEW relays — existing ones
# keep whatever the console that built them wrote. Field 2026-07-26: a relay built
# before the prober hardening was still running it bound to 0.0.0.0 with a public
# INPUT accept, months after the fix shipped. The operator can't be the delivery
# mechanism (that means SSH, and the whole product promise is "no more SSH"), so
# the console re-runs the bootstrap itself whenever the relay's stamped SHA is not
# the one we ship. The box already holds the relay key at _CONN_ANCHOR_KEY_PATH.
#
# Safe to re-run: cmd_setup only generates the WireGuard key / writes wg0.conf when
# ABSENT (so the tunnel identity and every added peer survive), the forward rules
# go through ipt_ensure (additive, deduped), and write_prober rewrites the unit and
# restarts it — which is precisely the fix. It never flushes.
def _conn_reassert_relay(log_fn=None):
    """Re-run the pinned bootstrap on a provisioned relay. Returns (ok, message)."""
    def _log(m):
        if log_fn:
            try:
                log_fn(m)
            except Exception:
                pass
    settings = load_settings()
    anchor = settings.get('connectivity_anchor') or {}
    if not anchor.get('anchor_ip'):
        return False, 'No relay is configured on this box.'
    if not os.path.exists(_CONN_ANCHOR_KEY_PATH):
        return False, ('The relay SSH key is no longer on this box — re-run Set Up Relay '
                       'with the .key file to refresh it.')
    ok, wg_port = _conn_validate_anchor_inputs(anchor.get('anchor_ip'), None,
                                               anchor.get('wg_port', 51820))
    if not ok:
        return False, 'Stored relay settings are invalid: %s' % wg_port
    anchor_ip = anchor.get('anchor_ip')
    ssh_user = anchor.get('ssh_user') or 'ubuntu'
    if not _CONN_SSH_USER_RE.fullmatch(ssh_user):
        ssh_user = 'ubuntu'
    # Same pinned-URL + digest-verify path as first provisioning — a relay re-assert
    # must not become a softer way to run unverified remote code as root.
    cmd = ("curl -fsSL '%s' -o ~/connectivity-anchor-bootstrap.sh && "
           "echo '%s  '$HOME'/connectivity-anchor-bootstrap.sh' | sha256sum -c - && "
           "chmod +x ~/connectivity-anchor-bootstrap.sh && "
           "sudo WG_PORT=%d bash ~/connectivity-anchor-bootstrap.sh setup"
           ) % (_CONN_ANCHOR_BOOTSTRAP_RAW, _CONN_ANCHOR_BOOTSTRAP_SHA256, wg_port)
    _log('Re-asserting relay %s…' % anchor_ip)
    ok, out = _conn_anchor_ssh(anchor_ip, ssh_user, cmd, timeout=240)
    if not ok:
        if 'sha256sum' in (out or '').lower() or 'FAILED' in (out or ''):
            return False, ('Relay bootstrap integrity check failed (unexpected script contents) — '
                           'nothing was run on the relay.')
        return False, 'Could not re-assert the relay: %s' % (out or '')[:200]
    s2 = load_settings()
    a2 = s2.get('connectivity_anchor') or {}
    a2['bootstrap_sha'] = _CONN_ANCHOR_BOOTSTRAP_SHA256
    s2['connectivity_anchor'] = a2
    save_settings(s2)
    _log('Relay re-asserted and up to date.')
    return True, 'Relay updated.'


def _startup_reassert_relay():
    """Boot-time: bring a stale relay up to the bootstrap we ship. Never raises.

    Runs in a thread — an unreachable relay must never delay console startup. Only
    acts on a SHA mismatch, so it is a no-op on every boot after the first."""
    try:
        anchor = (load_settings().get('connectivity_anchor') or {})
        # Gate on the KEY, not the 'provisioned' flag: a box adopted from the manual
        # configure path still has a relay worth healing, and the key is what decides
        # whether we can actually reach it.
        if not anchor.get('anchor_ip') or not os.path.exists(_CONN_ANCHOR_KEY_PATH):
            return
        if anchor.get('bootstrap_sha') == _CONN_ANCHOR_BOOTSTRAP_SHA256:
            return
        print("Startup migration: relay is running an older bootstrap — re-asserting "
              "(fixes the prober bind + forward rules)", flush=True)
        ok, msg = _conn_reassert_relay()
        print("Startup migration: relay re-assert %s — %s"
              % ('OK' if ok else 'SKIPPED', msg), flush=True)
    except Exception as e:
        print("Startup migration: relay re-assert error (non-fatal): %s" % e, flush=True)


@app.route('/api/connectivity/anchor/reassert', methods=['POST'])
@login_required
def connectivity_anchor_reassert_api():
    ok, msg = _conn_reassert_relay()
    return jsonify({'success': ok, 'message' if ok else 'error': msg}), (200 if ok else 400)


# ── Leg 5 — VERIFY (green/red reachability matrix) ─────────────────────────────
# Proves clients can actually reach the stack from the public internet — the loop
# that kills router/NSG trial-and-error. v1 vantage decision (deliberate deviation
# from the PLAN's relay-side :5099 prober): the relay CANNOT probe its own public
# IP — locally-originated packets skip the PREROUTING DNAT and never traverse the
# cloud NSG, so a relay-side self-probe false-REDs a perfectly working setup. A
# direct outbound TCP connect from THIS BOX to the relay's public endpoint walks
# the true client path end-to-end (internet → cloud NSG → relay DNAT → WireGuard →
# box service) — the same round trip the LDAP-outpost FQDN probe validated in the
# field 2026-07-08. The :5099 seed prober stays on the relay for a future
# third-vantage / Class-A probe-back build.
_CONN_VERIFY_PORTS = [
    (443,  'Web UIs (Portal / CloudTAK / Authentik via Caddy)', True),
    (8089, 'TAK streaming (CoT / ATAK-iTAK connections)',        True),
    (8443, 'Marti API / WebTAK',                                  True),
    (8446, 'Certificate + QR enrollment',                         True),
    (80,   "Let's Encrypt renewal (HTTP-01)",                     False),
]
# Mirrors modules/atlas.py DEVICE_PORT (the module is loaded by the marketplace, not
# imported here); tests/test_relay_forwards_module_ports.py keeps the two equal.
ATLAS_DEVICE_PORT = 8449


def _conn_verify_ports(settings):
    """The base ports PLUS the ports whichever modules are deployed actually need.

    v10.1.49. The matrix only ever probed the five base ports, so every port a
    module opened afterwards was forwarded-and-unverifiable — the operator found
    out it was blocked when a client failed, with a client-side error that names
    nothing.

    GH #62 is exactly that: EUD Remote Assist puts `https://<fqdn>:8448` into the
    enrolment QR, the deploy opens 8448 in the HOST firewall, and nothing ever
    checks whether a cloud security group or L4 load balancer is letting it
    through. The admin portal on 443 works, so everything LOOKS fine, and the
    phone reports only "Unable to connect". Same shape as
    [[coraz-tak-ports-no-l4-ingress]].

    Only ports whose module is actually deployed are added — probing 8448 on a box
    with no Remote Assist would be a permanent red that means nothing.
    """
    # GH #206: Caddy's web/ACME ports follow the operator's setting.
    _cmap = {443: _caddy_https_port(settings), 80: _caddy_http_port(settings)}
    ports = [(_cmap.get(p, p), label, req) for p, label, req in _CONN_VERIFY_PORTS]
    try:
        # v10.1.52 (GH #62 follow-up): detect Remote Assist the same belt-and-braces way the
        # rest of this file does -- `remote_assist_enabled` alone is NOT a reliable signal.
        # The v10.1.49 probe gated on that flag by itself, and the reporter came back on the
        # NEXT release saying "Not seeing the EUD line as a check": the check we added
        # BECAUSE of his issue did not fire on his box. Every other consumer of this fact
        # already ORs in the modules dict (see the OIDC_ADMIN_GROUP migration), because a box
        # deployed before the flag existed -- or through the marketplace path -- has the
        # module installed and the flag unset. Match them, and fall back to the container
        # itself so a settings file that has lost both still probes correctly.
        _ra = bool(settings.get('remote_assist_enabled')) \
            or 'remote_assist' in (settings.get('modules') or {}) \
            or os.path.isdir(REMOTE_ASSIST_INSTALL_DIR)
        if _ra:
            ports.append((REMOTE_ASSIST_DEVICE_PORT,
                          'EUD Remote Assist device enrolment (the QR points here)', True))
    except Exception:
        pass
    # v10.2.9 (GH #92): ATLAS MDM's device channel, same shape as 8448 above: the
    # provisioning QR points the tablet at :8449, the module opens it in the host
    # firewall, and a relay or cloud security group that drops it shows up only as a
    # SocketTimeoutException on the tablet. `atlas_enabled` is the flag ATLAS's own
    # detect() treats as "installed" (it self-heals the flag from the running
    # containers, so it does not have Remote Assist's lost-flag problem).
    if settings.get('atlas_enabled'):
        ports.append((ATLAS_DEVICE_PORT,
                      'ATLAS MDM device channel (enrolled tablets connect here)', True))
    try:
        _mtx = _get_module_deployment_config(settings, 'mediamtx_deployment') or {}
        if _mtx.get('deployed'):
            ports.append((8554, 'Video RTSP (MediaMTX)',  True))
            ports.append((8322, 'Video RTSPS (MediaMTX)', True))
            # 8890 is SRT over UDP and is deliberately NOT probed: a TCP connect
            # says nothing about a UDP path, and a connectionless probe cannot
            # distinguish "open" from "silently dropped". Reporting a made-up
            # state for it would be the exact defect this whole line of work is
            # about. It is called out in the UI instead.
    except Exception:
        pass
    # v10.2.9 (GH #92 follow-up): TAK Video Restreamer's and CloudTAK's video ports, which
    # the relay forwards from this release. TVR shares MediaMTX's 8554 (the two conflict, so
    # only one is ever deployed) and adds RTSPS 8555 and RTMP 1935. CloudTAK's are probed
    # only for a local deploy: the relay forwards to this box, not to a remote CloudTAK host.
    # SRT (8890 / 18890) is UDP and not probed, for the reason given for MediaMTX above.
    if settings.get('tak_video_restreamer_enabled'):
        if 8554 not in {p for p, _label, _req in ports}:
            ports.append((8554, 'Video RTSP (TAK Video Restreamer)', True))
        ports.append((8555, 'Video RTSPS (TAK Video Restreamer)', True))
        ports.append((1935, 'Video RTMP (TAK Video Restreamer)', True))
    try:
        _ct = _get_cloudtak_deployment_config(settings)
        _ct_dir = os.path.expanduser('~/CloudTAK')
        if _ct.get('target_mode') != 'remote' and any(
                os.path.exists(os.path.join(_ct_dir, f)) for f in ('docker-compose.yml', 'compose.yaml')):
            ports.append((18554, 'CloudTAK video RTSP', True))
            ports.append((11935, 'CloudTAK video RTMP', True))
    except Exception:
        pass
    return ports

_connectivity_verify_status = {'running': False, 'complete': False, 'error': '', 'result': None}


def _conn_verify_tcp(host, port, timeout=5):
    """One TCP connect probe. Returns {'state','ms','detail'} and never raises."""
    import socket as _s
    t0 = time.time()
    try:
        with _s.create_connection((host, port), timeout=timeout):
            return {'state': 'green', 'ms': int((time.time() - t0) * 1000), 'detail': ''}
    except OSError as ex:
        return {'state': 'red', 'ms': int((time.time() - t0) * 1000),
                'detail': (getattr(ex, 'strerror', '') or str(ex))[:80]}


def _run_connectivity_verify(settings):
    st = _connectivity_verify_status
    try:
        anchor = settings.get('connectivity_anchor') or {}
        result = {'ports': {}, 'target': '', 'mode': '', 'vantage': '', 'ts': int(time.time())}
        if anchor.get('anchor_ip'):
            result['target'] = anchor['anchor_ip']
            result['mode'] = 'relay'
            result['vantage'] = ("this box → the relay's public address — the exact path clients take "
                                 "(internet → cloud firewall/NSG → relay forward → tunnel → this box)")
        else:
            fqdn = (settings.get('fqdn') or '').split(':')[0].strip()
            result['target'] = fqdn or (settings.get('server_ip') or '').strip()
            result['mode'] = 'direct'
            result['vantage'] = ("this box → its own public address. On a home network without NAT "
                                 "hairpin this can show red even when outside clients connect fine — "
                                 "confirm with a phone on cellular if reds look wrong.")
        if not result['target']:
            st.update({'running': False, 'complete': True, 'result': None,
                       'error': 'Nothing to verify yet — connect a relay (or set an FQDN / public IP) first.'})
            return
        required_green = 0
        _verify_ports = _conn_verify_ports(settings)
        for port, label, required in _verify_ports:
            probe = _conn_verify_tcp(result['target'], port)
            probe['label'] = label
            probe['required'] = required
            if probe['state'] == 'red':
                # The killer diagnostic: is the service even listening locally? Separates
                # "deploy the module first" from "the path (router/NSG/forward) is blocked".
                local = _conn_verify_tcp('127.0.0.1', port, timeout=2)
                probe['local_listener'] = (local['state'] == 'green')
                if not probe['local_listener']:
                    probe['hint'] = 'nothing listening on this box yet — deploy the module that owns this port'
                elif result['mode'] == 'relay':
                    # Relay vantage is a REAL outside path (box -> relay public -> tunnel
                    # -> back); a red here is trustworthy.
                    probe['hint'] = ('service reachable locally but NOT from outside — check the path: '
                                     'relay cloud firewall/NSG ingress + forwarded ports')
                else:
                    # Direct mode probes the box's OWN public address — a self-probe that
                    # fails on any network without NAT hairpin (home routers, 1:1-NAT
                    # VPSes; field-hit 2026-07-12: test12 all-red while the operator was
                    # browsing the console THROUGH port 443). A failed self-probe proves
                    # nothing about outside reachability — never present it as red.
                    probe['state'] = 'unverified'
                    probe['hint'] = ('listening on this box, but the box cannot reach its own public '
                                     'address on this network (no NAT hairpin) — outside clients may '
                                     'connect fine; confirm from a phone on cellular')
            if probe['state'] == 'green' and required:
                required_green += 1
            result['ports'][str(port)] = probe
        result['all_green'] = required_green == sum(1 for _, _, req in _verify_ports if req)
        result['required_red'] = sum(1 for p in result['ports'].values() if p.get('required') and p.get('state') == 'red')
        result['unverified'] = sum(1 for p in result['ports'].values() if p.get('state') == 'unverified')
        st.update({'running': False, 'complete': True, 'error': '', 'result': result})
    except Exception as ex:
        st.update({'running': False, 'complete': True, 'error': str(ex)[:300]})


@app.route('/api/connectivity/verify', methods=['POST'])
@login_required
def connectivity_verify_api():
    if _connectivity_verify_status.get('running'):
        return jsonify({'error': 'A verify run is already in progress'}), 409
    _connectivity_verify_status.update(
        {'running': True, 'complete': False, 'error': '', 'result': None})
    settings = load_settings()
    threading.Thread(target=_run_connectivity_verify, args=(settings,), daemon=True).start()
    return jsonify({'success': True})


@app.route('/api/connectivity/verify-status')
@login_required
def connectivity_verify_status_api():
    st = _connectivity_verify_status
    return jsonify({'running': st.get('running', False), 'complete': st.get('complete', False),
                    'error': st.get('error', ''), 'result': st.get('result')})


# ── Leg 6 — WIFI JOIN (tell the box its next network, from the browser) ────────
# Kills the netplan hand-edit for a portable box: scan/list networks + add one from
# the UI. SAFETY MODEL (headless box reached remotely — a bad apply strands it):
#  - ADDITIVE ONLY: never removes an existing access-point, so the current
#    connection can't be dropped by adding a new one.
#  - VALIDATE BEFORE APPLY: back up the netplan file, write the new one, run
#    `netplan generate`; if it fails, RESTORE the backup and abort — never apply
#    an unvalidated config.
#  - Multiplatform: nmcli (NetworkManager / RHEL) when present, else netplan
#    (Ubuntu). Both via the privileged broker (_sudo_wrap / _run_priv_chain).


def _ensure_iw():
    """Ensure the `iw` CLI exists (wireless scan/detect on netplan boxes without
    NetworkManager). Field gap 2026-07-08: stock Ubuntu 22.04 SERVER does not ship
    `iw` (desktop does) — so on exactly the boxes that need the netplan path, the
    WiFi card's scan silently returned nothing. Mirrors _ensure_ldapsearch: tiny
    package, installed on demand through the apt↔dnf shim (package is named `iw`
    on both families). Checks sbin paths explicitly — the console user's PATH may
    exclude /usr/sbin even when the binary is installed."""
    for p in ('/usr/sbin/iw', '/sbin/iw', '/usr/bin/iw'):
        if os.path.exists(p):
            return True
    if shutil.which('iw'):
        return True
    try:
        _pkg_install('iw', timeout=120)
    except Exception:
        pass
    return any(os.path.exists(p) for p in ('/usr/sbin/iw', '/sbin/iw', '/usr/bin/iw')) or bool(shutil.which('iw'))


def _ensure_nm_wifi():
    """Ensure NetworkManager's WiFi plugin is present on RHEL-family boxes.

    RHEL/Rocky/Alma — minimal AND server installs — DO NOT ship
    `NetworkManager-wifi` (it is a separate package), so a fresh box shows the
    WiFi device as 'unmanaged' and every nmcli WiFi op (scan/add/connect) fails
    silently. Field-hit 2026-07-09 (Rocky NUC, first RHEL Leg-6 test); confirmed
    documented Rocky behaviour. Ubuntu ships WiFi support by default, so this is
    a RHEL-only gap — no-op on debian. Mirrors _ensure_iw: tiny package,
    installed on demand through the apt↔dnf shim (the existing nmcli code path
    then handles scan/add/persist). Restarts NetworkManager once after install
    so the radio flips 'managed'. Cheap once installed (glob short-circuits).
    Returns True when the plugin is present."""
    if _distro_family() != 'rhel':
        return True  # Ubuntu/debian ship WiFi support with NetworkManager.
    if not shutil.which('nmcli'):
        return False  # no NetworkManager — WiFi is not driven via nmcli here.
    import glob as _glob

    def _have_plugin():
        for pat in ('/usr/lib64/NetworkManager/*/libnm-device-plugin-wifi.so',
                    '/usr/lib64/NetworkManager/libnm-device-plugin-wifi.so',
                    '/usr/lib/NetworkManager/*/libnm-device-plugin-wifi.so',
                    '/usr/lib/NetworkManager/libnm-device-plugin-wifi.so'):
            if _glob.glob(pat):
                return True
        return False
    if _have_plugin():
        return True
    try:
        _pkg_install('NetworkManager-wifi', timeout=300)
        # Reload NM so it loads the new plugin and flips the WiFi device managed.
        _run_priv_chain([['systemctl', 'restart', 'NetworkManager']], mode='and', timeout=60)
    except Exception:
        pass
    return _have_plugin()


def _conn_wifi_iface():
    """Detect the wireless interface name (e.g. wlp1s0). Empty if none."""
    try:
        _ensure_iw()
        r = subprocess.run(_sudo_wrap(['iw', 'dev']), capture_output=True, text=True, timeout=8)
        m = re.search(r'Interface\s+(\S+)', r.stdout or '')
        if m:
            return m.group(1)
    except Exception:
        pass
    try:
        for n in sorted(os.listdir('/sys/class/net')):
            if os.path.exists('/sys/class/net/%s/wireless' % n):
                return n
    except Exception:
        pass
    return ''


def _conn_wifi_netplan_file():
    """The netplan file that defines the wifis: block (where APs live).

    Reads via the BROKER — netplan yamls are root-600 by design (they hold WiFi
    PSKs; cloud-init tightened this after CVE-2022-… era), so a direct open() as
    the non-root console EPERMs on every file and this reported 'No netplan wifi
    config found' on a box that was ON WiFi at that very moment (field-hit
    2026-07-08, NUC — first live Leg 6 test). Returns '' if no file has a
    wifis: block (caller creates our own layered file)."""
    try:
        import glob as _glob
        for f in sorted(_glob.glob('/etc/netplan/*.yaml')):
            try:
                r = subprocess.run(_sudo_wrap(['cat', f]), capture_output=True, text=True, timeout=8)
                if r.returncode == 0 and 'wifis' in (r.stdout or ''):
                    return f
            except Exception:
                continue
    except Exception:
        pass
    return ''


def _conn_wifi_saved():
    """SSIDs the box already knows (from nmcli or the netplan file)."""
    out = []
    if shutil.which('nmcli'):
        try:
            r = subprocess.run(_sudo_wrap(['nmcli', '-t', '-f', 'NAME,TYPE', 'connection', 'show']),
                               capture_output=True, text=True, timeout=10)
            for line in (r.stdout or '').splitlines():
                p = line.split(':')
                if len(p) >= 2 and 'wireless' in p[1]:
                    out.append(p[0])
        except Exception:
            pass
        return out
    # netplan branch: read every yaml via the broker (root-600 files — a direct
    # open() EPERMs as the non-root console and the saved list showed empty even
    # while the box was connected; same field bug as _conn_wifi_netplan_file).
    try:
        import glob as _glob
        import yaml as _yaml
        for f in sorted(_glob.glob('/etc/netplan/*.yaml')):
            try:
                r = subprocess.run(_sudo_wrap(['cat', f]), capture_output=True, text=True, timeout=8)
                doc = _yaml.safe_load(r.stdout or '') or {}
                for _iface, cfg in ((doc.get('network') or {}).get('wifis') or {}).items():
                    for _ssid in (cfg.get('access-points') or {}).keys():
                        if _ssid not in out:
                            out.append(_ssid)
            except Exception:
                continue
    except Exception:
        pass
    return out


def _conn_wifi_scan():
    """Best-effort list of visible SSIDs (+ signal where available)."""
    _ensure_nm_wifi()  # RHEL: pull NetworkManager-wifi so the radio is manageable
    nets, seen = [], set()

    def _add(ssid, signal=''):
        ssid = (ssid or '').strip()
        if ssid and ssid not in seen:
            seen.add(ssid)
            nets.append({'ssid': ssid, 'signal': signal})
    if shutil.which('nmcli'):
        try:
            subprocess.run(_sudo_wrap(['nmcli', 'dev', 'wifi', 'rescan']), capture_output=True, timeout=15)
            r = subprocess.run(_sudo_wrap(['nmcli', '-t', '-f', 'SSID,SIGNAL', 'dev', 'wifi', 'list']),
                               capture_output=True, text=True, timeout=20)
            for line in (r.stdout or '').splitlines():
                p = line.rsplit(':', 1)
                _add(p[0], p[1] if len(p) > 1 else '')
        except Exception:
            pass
        return nets
    iface = _conn_wifi_iface()
    if iface:
        try:
            _ensure_iw()
            r = subprocess.run(_sudo_wrap(['iw', 'dev', iface, 'scan']),
                               capture_output=True, text=True, timeout=25)
            for line in (r.stdout or '').splitlines():
                s = line.strip()
                if s.startswith('SSID:'):
                    _add(s[5:])
        except Exception:
            pass
    return nets


def _conn_wifi_visible():
    """SSIDs currently in range, from the radio's CACHED scan results — cheap and
    instant (no active scan), so it's safe to include on the list poll. nmcli uses
    its cached `dev wifi list`; netplan uses `iw dev <iface> scan dump` (kernel
    cache from the client's periodic background scans). The active 'Scan for
    networks' button refreshes the cache. Best-effort; empty if unavailable."""
    seen = set()
    if shutil.which('nmcli'):
        try:
            r = subprocess.run(_sudo_wrap(['nmcli', '-t', '-f', 'SSID', 'dev', 'wifi', 'list']),
                               capture_output=True, text=True, timeout=8)
            for ln in (r.stdout or '').splitlines():
                s = ln.strip()
                if s:
                    seen.add(s)
        except Exception:
            pass
        return list(seen)
    iface = _conn_wifi_iface()
    if iface:
        try:
            _ensure_iw()
            r = subprocess.run(_sudo_wrap(['iw', 'dev', iface, 'scan', 'dump']),
                               capture_output=True, text=True, timeout=8)
            for ln in (r.stdout or '').splitlines():
                s = ln.strip()
                if s.startswith('SSID:'):
                    v = s[5:].strip()
                    if v:
                        seen.add(v)
        except Exception:
            pass
    return list(seen)


def _conn_setup_ap_active():
    """True if the Setup AP is currently broadcasting (flag written by the engine)."""
    return os.path.exists('/var/lib/takguard/setup-ap.active')


def _conn_wifi_add(ssid, psk):
    """Add a wifi network ADDITIVELY and bring config up. Returns (ok, error).
    netplan path validates-before-apply with backup/restore; never strands."""
    if not (1 <= len(ssid.encode('utf-8')) <= 32):
        return False, 'Network name must be 1–32 characters.'
    if psk and not (8 <= len(psk) <= 63):
        return False, 'WiFi password must be 8–63 characters (WPA requirement).'
    _ensure_nm_wifi()  # RHEL: pull NetworkManager-wifi so nmcli can manage the radio
    # NetworkManager path (RHEL / any box with nmcli).
    # v10.1.0 parity fix: use `connection add` (create the PROFILE, activate
    # nothing), NOT `dev wifi connect` — connect ACTIVATES, i.e. it switches
    # the box onto the new network immediately (breaking the "adding never
    # disconnects the one you're on" promise) and it FAILS outright for an SSID
    # that isn't in range (breaking pre-provision, the flagship Leg 6 feature).
    # `connection add` + autoconnect matches netplan's additive semantics:
    # NM joins the network when it sees it, current connection untouched.
    if shutil.which('nmcli'):
        iface = _conn_wifi_iface() or '*'
        if ssid in _conn_wifi_saved():
            if not psk:
                return True, ''
            # Same SSID re-added with a (possibly new) password → update in place.
            cmd = ['nmcli', 'connection', 'modify', ssid, 'wifi-sec.psk', psk]
        else:
            # ipv4.may-fail no: without it NM declares the connection 'activated'
            # on IPv6 alone when DHCPv4 gets no answer (field-hit 2026-07-11,
            # iPhone hotspot: 'dhcp4: no lease' but nmcli up rc=0) — a state with
            # no usable IPv4, no tunnel, and a join loop that thinks it won.
            cmd = ['nmcli', 'connection', 'add', 'type', 'wifi',
                   'con-name', ssid, 'ifname', iface, 'ssid', ssid,
                   'connection.autoconnect', 'yes', 'ipv4.may-fail', 'no']
            if psk:
                cmd += ['wifi-sec.key-mgmt', 'wpa-psk', 'wifi-sec.psk', psk]
        r = subprocess.run(_sudo_wrap(cmd), capture_output=True, text=True, timeout=45)
        if r.returncode != 0:
            return False, (r.stderr or r.stdout or 'nmcli profile add failed').strip()[:200]
        # ADDITIVE-ONLY, even from the Setup AP (2026-07-11 redesign). Honor the card's
        # promise "Adding a network never disconnects the one you're on": just save the
        # profile (autoconnect=yes) and leave the AP broadcasting, so the operator can
        # pre-provision several networks before committing. The SWITCH to a saved network
        # happens ONLY when they explicitly hit "Stop Setup WiFi" (setup-ap/stop ->
        # _conn_join_best_saved), which is where the deterministic join-out-of-AP-mode
        # now lives (NM autoconnect coming out of AP mode is unreliable on RHEL).
        return True, ''
    # netplan path (Ubuntu).
    f = _conn_wifi_netplan_file()
    created_new = False
    if not f:
        # No wifis: block anywhere (ethernet-only cloud-init, or WiFi configured
        # outside netplan). Create our OWN lexically-layered file instead of
        # failing — netplan merges mappings across files, and never touching
        # cloud-init's file means cloud-init can't clobber our APs later.
        f = '/etc/netplan/90-infratak-wifi.yaml'
        created_new = True
    iface = _conn_wifi_iface()
    if not iface:
        return False, 'No wireless interface detected.'
    try:
        import yaml as _yaml
        # Read current config via privileged cat (file may be root-only).
        cur = subprocess.run(_sudo_wrap(['cat', f]), capture_output=True, text=True, timeout=10)
        doc = _yaml.safe_load(cur.stdout or '') or {}
        net = doc.setdefault('network', {})
        net.setdefault('version', 2)
        wifis = net.setdefault('wifis', {})
        ap = wifis.setdefault(iface, {})
        ap.setdefault('dhcp4', True)
        points = ap.setdefault('access-points', {})
        # ADDITIVE: add/replace only THIS ssid, keep every other AP untouched.
        if psk:
            points[ssid] = {'auth': {'key-management': 'psk', 'password': psk}}
        else:
            points[ssid] = {}
        new_yaml = _yaml.safe_dump(doc, default_flow_style=False, sort_keys=False)
    except Exception as ex:
        return False, 'Could not read/parse netplan config: %s' % str(ex)[:160]
    # Write via temp → privileged install, keeping a backup for restore-on-failure.
    tmp_path = bak = None
    try:
        fd, tmp_path = tempfile.mkstemp(prefix='netplan-', suffix='.yaml')
        os.write(fd, new_yaml.encode())
        os.close(fd)
        os.chmod(tmp_path, 0o600)
        bak = f + '.infratak-wifi.bak'
        if not created_new:
            _run_priv_chain([['cp', '-a', f, bak]], mode='and')
        inst = _run_priv_chain([['install', '-m', '600', '-o', 'root', '-g', 'root', tmp_path, f]], mode='and')
        if not inst or inst.returncode != 0:
            return False, 'Could not write netplan config.'
        # VALIDATE — if generate fails, roll back and abort (never apply). For a
        # freshly created file there is no backup to restore — remove it instead
        # (leaves the box exactly as it was).
        gen = _run_priv_chain([['netplan', 'generate']], mode='and')
        if not gen or gen.returncode != 0:
            if created_new:
                _run_priv_chain([['rm', '-f', f], ['netplan', 'generate']], mode='seq')
            else:
                _run_priv_chain([['cp', '-a', bak, f], ['netplan', 'generate']], mode='seq')
            return False, 'New network config failed validation — reverted, nothing changed. (%s)' \
                % ((gen.stderr if gen else '') or '')[:140]
        # If the Setup AP is broadcasting (the operator is provisioning FROM it),
        # the radio is busy being the AP — a raw `netplan apply` would fight
        # hostapd. Instead stop the AP: its teardown restores the client and runs
        # netplan apply, so the box joins the just-added network (in range at the
        # new location) and drops the AP in one step. Otherwise apply directly
        # (additive — doesn't drop the current connection).
        # ADDITIVE-ONLY on the Setup AP (2026-07-11 redesign): the netplan config is
        # written + validated above but deliberately NOT applied here — leave the AP
        # broadcasting and the radio untouched so the operator can pre-provision more
        # networks. The switch happens only on the explicit "Stop Setup WiFi", whose
        # teardown (restore_client) runs `netplan apply` and joins the saved network.
        # Off the AP, apply now (additive — doesn't drop the current connection).
        if _conn_setup_ap_active():
            return True, ''
        appl = _run_priv_chain([['netplan', 'apply']], mode='and')
        if not appl or appl.returncode != 0:
            return False, 'Config validated but apply failed: %s' % ((appl.stderr if appl else '') or '')[:140]
        return True, ''
    finally:
        if tmp_path and os.path.exists(tmp_path):
            try:
                os.remove(tmp_path)
            except Exception:
                pass


@app.route('/api/connectivity/wifi/list')
@login_required
def connectivity_wifi_list_api():
    ap_active = _conn_setup_ap_active()
    # In AP mode the radio can't scan, so skip the (stale/empty) visible probe.
    return jsonify({'iface': _conn_wifi_iface(), 'saved': _conn_wifi_saved(),
                    'current': _conn_wifi_current(),
                    'visible': [] if ap_active else _conn_wifi_visible(),
                    'ap_active': ap_active})


@app.route('/api/connectivity/wifi/scan')
@login_required
def connectivity_wifi_scan_api():
    return jsonify({'networks': _conn_wifi_scan()})


@app.route('/api/connectivity/wifi/add', methods=['POST'])
@login_required
def connectivity_wifi_add_api():
    data = request.get_json(silent=True) or {}
    ssid = (data.get('ssid') or '').strip()
    psk = data.get('password') or ''
    if not ssid:
        return jsonify({'success': False, 'error': 'Enter a network name (SSID).'}), 400
    ok, err = _conn_wifi_add(ssid, psk)
    if not ok:
        return jsonify({'success': False, 'error': err}), 400
    return jsonify({'success': True})


# ── Reaching This Box — every LAN address the console (:port) answers on now ──
def _conn_reach_addresses():
    """Every LAN address this box's console (:port) is reachable at right now —
    the data behind the 'Reaching This Box' card (v10.1.2). Lists each real
    Ethernet/WiFi interface with its IP + a ready console URL, flags the one the
    current request arrived on ('you're here now'), and marks the WiFi ones so
    the UI can say 'use this after you unplug Ethernet' (the exact friction of a
    portable box hopping Ethernet→WiFi). Internal bridges (docker/veth/virbr/
    br-/cni/flannel) are excluded — they are not a reach path. No mDNS: this
    reads the box's OWN addresses inside the authenticated console, adds no
    listener and broadcasts nothing (deliberate — mDNS/Avahi was rejected on
    STIG/attack-surface grounds)."""
    try:
        port = str(load_settings().get('console_port') or 5001)
    except Exception:
        port = '5001'
    wifi_if = _conn_wifi_iface()
    here = ''
    try:
        here = (request.host or '').rsplit(':', 1)[0].strip('[]')
    except Exception:
        here = ''
    addrs = []
    info = _conn_local_network(lambda *_a, **_k: None)
    for i in info.get('interfaces', []):
        name = (i.get('iface') or '').strip()
        ip = (i.get('ip') or '').strip()
        if not name or not ip or name == 'lo':
            continue
        if name.startswith(('docker', 'veth', 'virbr', 'br-', 'cni', 'flannel', 'tailscale', 'wg')):
            continue  # internal / overlay bridges — not a LAN reach path
        addrs.append({
            'iface': name,
            'kind': 'wifi' if name == wifi_if else 'ethernet',
            'ip': ip,
            'url': 'https://%s:%s' % (ip, port),
            'current': bool(here) and ip == here,
        })
    # Ethernet first, then WiFi (mirrors the "unplug Ethernet → fall to WiFi" story).
    addrs.sort(key=lambda a: (a['kind'] != 'ethernet', a['iface']))
    return {'port': port, 'addresses': addrs,
            'has_wifi': any(a['kind'] == 'wifi' for a in addrs),
            'has_ethernet': any(a['kind'] == 'ethernet' for a in addrs)}


@app.route('/api/connectivity/addresses')
@login_required
def connectivity_addresses_api():
    return jsonify(_conn_reach_addresses())


# ── Leg 6c — CURRENT + FORGET (which network the box is on; drop a saved one) ──
def _conn_wifi_current():
    """SSID the box is CURRENTLY associated to (''=not connected). Prefers nmcli's
    active-connection view — reliable on RHEL and works even when the radio can't
    scan (associated + on Ethernet). Falls back to `iw dev`. Field-hit 2026-07-11:
    on a box connected to OXFORD, `iw dev` printed NO `ssid` line (driver quirk), so
    the console wrongly showed the live network as 'not in range' instead of
    'connected now'. Our added profiles use con-name==SSID, so the active connection
    name IS the SSID."""
    iface = _conn_wifi_iface()
    if not iface:
        return ''
    if shutil.which('nmcli'):
        try:
            r = subprocess.run(_sudo_wrap(['nmcli', '-t', '-f', 'DEVICE,TYPE,STATE,CONNECTION', 'device', 'status']),
                               capture_output=True, text=True, timeout=8)
            for ln in (r.stdout or '').splitlines():
                p = ln.split(':')
                if len(p) >= 4 and p[0] == iface and p[1] == 'wifi' and p[2] == 'connected':
                    name = ':'.join(p[3:]).strip()
                    if name and name != '--':
                        return name
        except Exception:
            pass
    try:
        _ensure_iw()
        r = subprocess.run(_sudo_wrap(['iw', 'dev']), capture_output=True, text=True, timeout=8)
        cur_if = None
        for ln in (r.stdout or '').splitlines():
            s = ln.strip()
            if s.startswith('Interface '):
                cur_if = s.split(None, 1)[1].strip()
            elif s.startswith('ssid ') and cur_if == iface:
                return s[5:].strip()
    except Exception:
        pass
    return ''


def _conn_wifi_forget(ssid):
    """Remove a saved network. Returns (ok, error). nmcli: delete the profile.
    netplan: strip the SSID from every netplan file that has it, then
    validate-before-apply (revert on failure). Never touches other APs."""
    ssid = (ssid or '').strip()
    if not ssid:
        return False, 'No network specified.'
    if shutil.which('nmcli'):
        r = subprocess.run(_sudo_wrap(['nmcli', 'connection', 'delete', ssid]),
                           capture_output=True, text=True, timeout=30)
        if r.returncode != 0:
            return False, (r.stderr or r.stdout or 'delete failed').strip()[:200]
        return True, ''
    # netplan: read-modify-write each file that contains the AP (via broker).
    import glob as _glob
    import yaml as _yaml
    touched = False
    for f in sorted(_glob.glob('/etc/netplan/*.yaml')):
        try:
            r = subprocess.run(_sudo_wrap(['cat', f]), capture_output=True, text=True, timeout=8)
            if r.returncode != 0 or 'access-points' not in (r.stdout or ''):
                continue
            doc = _yaml.safe_load(r.stdout or '') or {}
            wifis = ((doc.get('network') or {}).get('wifis') or {})
            removed_here = False
            emptied = []
            for _iface, cfg in wifis.items():
                aps = (cfg or {}).get('access-points') or {}
                if ssid in aps:
                    del aps[ssid]
                    removed_here = True
                    if not aps:
                        emptied.append(_iface)
            if not removed_here:
                continue
            # Prune an interface whose LAST access point just went away, and then a
            # `wifis:` block with no interfaces left. netplan's generator assumes the
            # access-points list is never empty and fails outright on `access-points: {}`
            # (canonical/netplan#468), so leaving the husk behind made `netplan generate`
            # fail, which reverted the whole edit — i.e. removing the only saved network
            # for an interface could NEVER succeed. That is the exact shape the Ubuntu
            # installer writes (one AP under 00-installer-config-wireless.yaml), so this
            # hit any box whose wifi was set up at install time. Field-hit ops1,
            # 2026-08-12: "Config failed validation — reverted, nothing changed."
            # Mutate `wifis` only AFTER the loop above — deleting during iteration
            # raises RuntimeError, which the bare `except: continue` would swallow into
            # a silent no-op ("that network is not saved on this box").
            for _iface in emptied:
                wifis.pop(_iface, None)
            if not wifis:
                (doc.get('network') or {}).pop('wifis', None)
            # netplan needs the version key even when nothing else is left in the file.
            if isinstance(doc.get('network'), dict):
                doc['network'].setdefault('version', 2)
            new_yaml = _yaml.safe_dump(doc, default_flow_style=False, sort_keys=False)
            tmp = None
            try:
                fd, tmp = tempfile.mkstemp(prefix='netplan-', suffix='.yaml')
                os.write(fd, new_yaml.encode())
                os.close(fd)
                os.chmod(tmp, 0o600)
                bak = f + '.infratak-forget.bak'
                _run_priv_chain([['cp', '-a', f, bak]], mode='and')
                _run_priv_chain([['install', '-m', '600', '-o', 'root', '-g', 'root', tmp, f]], mode='and')
                gen = _run_priv_chain([['netplan', 'generate']], mode='and')
                if not gen or gen.returncode != 0:
                    rev = _run_priv_chain([['cp', '-a', bak, f], ['netplan', 'generate']], mode='seq')
                    # Drop the backup once the original is demonstrably back in place.
                    # If the revert ITSELF failed, keep it — then it is the only copy
                    # of the operator's working config, not litter.
                    if rev is not None and getattr(rev, 'returncode', 1) == 0:
                        _run_priv_chain([['rm', '-f', bak]], mode='and')
                    # Carry netplan's own words out to the UI. The bare message gave the
                    # operator nothing to act on and nothing to report, which is how the
                    # empty-access-points bug above stayed invisible.
                    why = ((getattr(gen, 'stderr', '') or getattr(gen, 'stdout', '') or '')
                           .strip().splitlines() or [''])[-1][:200]
                    return False, ('Config failed validation — reverted, nothing changed.'
                                   + (f' netplan: {why}' if why else ''))
                # Generated cleanly — the backup has done its job (v10.1.48 W14;
                # these accumulated in /etc/netplan, one per forget, forever).
                _run_priv_chain([['rm', '-f', bak]], mode='and')
                touched = True
            finally:
                if tmp and os.path.exists(tmp):
                    try:
                        os.remove(tmp)
                    except Exception:
                        pass
        except Exception:
            continue
    if not touched:
        return False, 'That network is not saved on this box.'
    _run_priv_chain([['netplan', 'apply']], mode='and')
    # The new config is generated AND applied, so any .infratak-forget.bak still
    # sitting here is from an earlier release that never cleaned up. Safe to sweep
    # only at this point — earlier, one of them could still be a live rollback.
    for _stale in sorted(_glob.glob('/etc/netplan/*.infratak-forget.bak')):
        _run_priv_chain([['rm', '-f', _stale]], mode='and')
    return True, ''


def _conn_wifi_use(ssid):
    """Switch the box onto an already-SAVED network now, using the stored
    credentials (no re-typing the password). Returns (ok, error).
      nmcli   — `nmcli connection up <ssid>` (activates the saved profile).
      netplan — wpa_cli: find the saved network id, select it (associates now),
                then re-enable all others so roaming/fallback still works after.
    The switch is runtime; netplan config (all networks enabled) is authoritative
    again on the next apply/reboot."""
    ssid = (ssid or '').strip()
    if not ssid:
        return False, 'No network specified.'
    if ssid not in _conn_wifi_saved():
        return False, 'That network is not saved yet — add it first (with its password).'
    # If provisioning FROM the Setup AP, the radio is the AP — wpa_cli/nmcli-up
    # can't take effect. Stop the AP so the box reconnects to its known networks
    # (the target, being saved + in range, is what it lands on).
    if _conn_setup_ap_active():
        subprocess.run(_sudo_wrap(['systemctl', 'stop', 'takwerx-setup-ap.service']),
                       capture_output=True, text=True, timeout=60)
        return True, ''
    if shutil.which('nmcli'):
        r = subprocess.run(_sudo_wrap(['nmcli', 'connection', 'up', ssid]),
                           capture_output=True, text=True, timeout=45)
        if r.returncode != 0:
            return False, (r.stderr or r.stdout or 'switch failed').strip()[:200]
        return True, ''
    iface = _conn_wifi_iface()
    if not iface:
        return False, 'No wireless interface detected.'
    try:
        lst = subprocess.run(_sudo_wrap(['wpa_cli', '-i', iface, 'list_networks']),
                             capture_output=True, text=True, timeout=10)
        net_id = None
        for ln in (lst.stdout or '').splitlines():
            parts = ln.split('\t')
            if len(parts) >= 2 and parts[1] == ssid:
                net_id = parts[0].strip()
                break
        if net_id is None or not net_id.isdigit():
            return False, 'Saved network not found in the WiFi supplicant — try re-adding it.'
        sel = subprocess.run(_sudo_wrap(['wpa_cli', '-i', iface, 'select_network', net_id]),
                             capture_output=True, text=True, timeout=15)
        if 'OK' not in (sel.stdout or ''):
            return False, 'Switch command was not accepted: %s' % (sel.stdout or sel.stderr or '')[:120]
        # Re-enable the others so the box can still roam/fall back later.
        subprocess.run(_sudo_wrap(['wpa_cli', '-i', iface, 'enable_network', 'all']),
                       capture_output=True, text=True, timeout=10)
        return True, ''
    except Exception as ex:
        return False, 'Could not switch network: %s' % str(ex)[:160]


@app.route('/api/connectivity/wifi/use', methods=['POST'])
@login_required
def connectivity_wifi_use_api():
    data = request.get_json(silent=True) or {}
    ssid = (data.get('ssid') or '').strip()
    ok, err = _conn_wifi_use(ssid)
    if not ok:
        return jsonify({'success': False, 'error': err}), 400
    return jsonify({'success': True})


@app.route('/api/connectivity/wifi/forget', methods=['POST'])
@login_required
def connectivity_wifi_forget_api():
    data = request.get_json(silent=True) or {}
    ssid = (data.get('ssid') or '').strip()
    if not ssid:
        return jsonify({'success': False, 'error': 'No network specified.'}), 400
    # Forgetting the network the box is CURRENTLY using disconnects it. Allow it,
    # but require the operator to acknowledge (client sends confirm=true) AND warn
    # if the Setup AP isn't armed to catch the box.
    current = _conn_wifi_current()
    if ssid == current and not data.get('confirm'):
        ap = _conn_setup_ap_read_conf()
        return jsonify({'success': False, 'needs_confirm': True, 'is_current': True,
                        'setup_ap_ready': bool(ap.get('has_password')),
                        'error': 'This is the network the box is using right now — forgetting it disconnects the box.'}), 409
    ok, err = _conn_wifi_forget(ssid)
    if not ok:
        return jsonify({'success': False, 'error': err}), 400
    return jsonify({'success': True})


# ── Leg 6b — SETUP AP (broadcast own wifi for local provisioning) ─────────────
# When the box has no uplink, it broadcasts `infraTAK-setup-<host>` (WPA2) so an
# operator joins from a laptop, lands on the console login (captive redirect), and
# uses the WiFi card to pick a real network. ONE radio: broadcasting = not a wifi
# client, so this only runs with no uplink to lose. The powerful bits live in the
# root systemd unit takwerx-setup-ap.service (engine tak-setup-ap.sh); the console
# only start/stops that unit through the broker — no new broker privilege.
_SETUP_AP_CONF = '/var/lib/takguard/setup-ap.conf'
# Marks an AP raised by the console's Start button, so tak-setup-ap-watch.sh does
# not tear it down for the crime of the box still having internet.
_SETUP_AP_MANUAL_FLAG = '/var/lib/takguard/setup-ap.manual'
_SETUP_AP_ACTIVE_FLAG = '/var/lib/takguard/setup-ap.active'


def _conn_setup_ap_default_ssid():
    try:
        h = socket.gethostname().split('.')[0]
    except Exception:
        h = 'box'
    return 'infraTAK-setup-%s' % h


def _conn_setup_ap_read_conf():
    """Read the engine conf via the broker (root-600). Returns a dict of the
    SETUP_AP_* keys (ssid/auto only — never returns the password)."""
    out = {'ssid': _conn_setup_ap_default_ssid(), 'auto': True, 'has_password': False}
    try:
        r = subprocess.run(_sudo_wrap(['cat', _SETUP_AP_CONF]), capture_output=True, text=True, timeout=8)
        for ln in (r.stdout or '').splitlines():
            ln = ln.strip()
            if ln.startswith('SETUP_AP_SSID='):
                v = ln.split('=', 1)[1].strip().strip('"').strip("'")
                if v:
                    out['ssid'] = v
            elif ln.startswith('SETUP_AP_AUTO='):
                out['auto'] = ln.split('=', 1)[1].strip() != '0'
            elif ln.startswith('SETUP_AP_PASS=') and len(ln.split('=', 1)[1].strip()) >= 8:
                out['has_password'] = True
    except Exception:
        pass
    return out


def _conn_setup_ap_write_conf(ssid, password, auto):
    """Write the root-600 engine conf via a temp file + privileged install."""
    ssid = (ssid or '').strip() or _conn_setup_ap_default_ssid()
    _console_url = ''
    try:
        _st = load_settings()
        _console_port = int(_st.get('console_port') or 5001)
        # If the box has a real cert (LE via Caddy, or a custom cert), the setup AP
        # can send the laptop to the console's Caddy vhost by NAME — the AP's wildcard
        # DNS resolves it to the box, Caddy presents the TRUSTED cert (no warning), and
        # Caddy is the sanctioned auth proxy (it strips client X-Authentik-* — no
        # bypass). Fresh/self-signed boxes have no trusted cert, so the engine falls
        # back to the box's own self-signed https (accept-the-warning floor).
        _ssl_mode = (_st.get('ssl_mode') or '').strip().lower()
        _fqdn = (_st.get('fqdn') or '').split(':')[0].strip()
        if _fqdn and _ssl_mode in ('fqdn', 'custom'):
            _ihost = _get_all_service_domains(_st).get('infratak')
            if _ihost:
                _console_url = 'https://%s/' % _pub_hostport(_ihost, _st)
    except Exception:
        _console_port = 5001
    lines = ['# infra-TAK Setup AP config (managed by the console)\n',
             'SETUP_AP_SSID=%s\n' % ssid,
             'SETUP_AP_CONSOLE_PORT=%d\n' % _console_port,
             'SETUP_AP_CONSOLE_URL=%s\n' % _console_url,
             'SETUP_AP_AUTO=%s\n' % ('1' if auto else '0')]
    if password:
        lines.append('SETUP_AP_PASS=%s\n' % password)
    tmp = None
    try:
        _makedirs_priv('/var/lib/takguard')
        fd, tmp = tempfile.mkstemp(prefix='setup-ap-', suffix='.conf')
        # If no new password given, preserve the existing one (read via broker).
        if not password:
            try:
                r = subprocess.run(_sudo_wrap(['cat', _SETUP_AP_CONF]), capture_output=True, text=True, timeout=8)
                for ln in (r.stdout or '').splitlines():
                    if ln.strip().startswith('SETUP_AP_PASS='):
                        lines.append(ln if ln.endswith('\n') else ln + '\n')
                        break
            except Exception:
                pass
        os.write(fd, ''.join(lines).encode())
        os.close(fd)
        os.chmod(tmp, 0o600)
        inst = _run_priv_chain([['install', '-m', '600', '-o', 'root', '-g', 'root', tmp, _SETUP_AP_CONF]], mode='and')
        return bool(inst and inst.returncode == 0)
    except Exception:
        return False
    finally:
        if tmp and os.path.exists(tmp):
            try:
                os.remove(tmp)
            except Exception:
                pass


def _conn_setup_ap_have_nm():
    """True when NetworkManager drives the radio (RHEL, and Ubuntu Desktop)."""
    try:
        if not shutil.which('nmcli'):
            return False
        r = subprocess.run(['systemctl', 'is-active', '--quiet', 'NetworkManager'], timeout=8)
        return r.returncode == 0
    except Exception:
        return False


def _conn_setup_ap_deps_ready():
    """Can this box actually bring the Setup AP up RIGHT NOW, offline?

    NetworkManager boxes need nothing extra (`nmcli device wifi hotspot`).
    Everything else (Ubuntu Server = netplan/systemd-networkd, the fleet default)
    goes down tak-setup-ap.sh's hostapd path and needs hostapd + dnsmasq ON DISK."""
    if _conn_setup_ap_have_nm():
        return True
    return bool(shutil.which('hostapd')) and bool(shutil.which('dnsmasq'))


def _conn_setup_ap_ensure_deps(log_fn=None):
    """Pre-install the Setup AP's offline dependencies WHILE THE BOX IS ONLINE.

    v10.1.28 (ops1 2026-08-09, field): tak-setup-ap.sh installed hostapd/dnsmasq
    lazily at AP-start time — which is by definition the one moment the box has no
    internet. apt-get could not resolve, start failed, the client radio was
    restored, and the 30s watcher retried the identical failure forever (176 KB of
    log, no AP, nothing surfaced to the operator). The box shipped with a Setup AP
    that could never once come up on Ubuntu Server.

    Arming has to happen while connectivity still exists: on config save, and via
    the startup converge for boxes already configured. Idempotent and cheap when
    the packages are already present. Returns True when the box is armed."""
    _log = log_fn or (lambda m: None)
    if _conn_setup_ap_deps_ready():
        return True
    missing = [p for p in ('hostapd', 'dnsmasq') if not shutil.which(p)]
    if not missing:
        return True
    _log('Setup AP: installing offline dependencies (%s)' % ', '.join(missing))
    try:
        ok, out = _pkg_install(missing, timeout=300)
    except Exception as e:
        _log('Setup AP: dependency install error: %s' % str(e)[:160])
        return False
    if not ok:
        _log('Setup AP: dependency install FAILED: %s' % (out or '')[-300:])
        return False
    # Debian ENABLES dnsmasq.service on install; it would bind :53 on every
    # interface at next boot and collide with the AP's own script-managed dnsmasq
    # (which uses bind-interfaces). The engine masks these at start too — do it
    # here so a reboot between arming and first use cannot break the AP.
    for _u in ('dnsmasq.service', 'hostapd.service'):
        try:
            subprocess.run(_sudo_wrap(['systemctl', 'disable', '--now', _u]),
                           capture_output=True, text=True, timeout=30)
        except Exception:
            pass
    _log('Setup AP: armed — hostapd + dnsmasq installed')
    return True


def _conn_setup_ap_status():
    st = {'active': os.path.exists(_SETUP_AP_ACTIVE_FLAG), 'ap_capable': None, 'has_wifi': bool(_conn_wifi_iface())}
    st.update(_conn_setup_ap_read_conf())
    # Surface arming state so the page can never again promise an automatic
    # broadcast the box is physically unable to perform (ops1 2026-08-09).
    st['deps_ready'] = _conn_setup_ap_deps_ready()
    st['uses_nm'] = _conn_setup_ap_have_nm()
    return st


@app.route('/api/connectivity/setup-ap/status')
@login_required
def connectivity_setup_ap_status_api():
    return jsonify(_conn_setup_ap_status())


@app.route('/api/connectivity/setup-ap/reveal')
@login_required
def connectivity_setup_ap_reveal_api():
    """Return the current setup-AP password (the operator must be able to read it
    to type it on a laptop — the engine may have auto-generated a random one).
    On-demand only (not in the status poll), authenticated. Read via the broker."""
    pw = ''
    try:
        r = subprocess.run(_sudo_wrap(['cat', _SETUP_AP_CONF]), capture_output=True, text=True, timeout=8)
        for ln in (r.stdout or '').splitlines():
            if ln.strip().startswith('SETUP_AP_PASS='):
                pw = ln.split('=', 1)[1].strip()
                break
    except Exception:
        pass
    return jsonify({'password': pw})


@app.route('/api/connectivity/setup-ap/config', methods=['POST'])
@login_required
def connectivity_setup_ap_config_api():
    data = request.get_json(silent=True) or {}
    ssid = (data.get('ssid') or '').strip()
    password = data.get('password') or ''
    auto = bool(data.get('auto', True))
    if password and not (8 <= len(password) <= 63):
        return jsonify({'success': False, 'error': 'Setup-WiFi password must be 8–63 characters (WPA2).'}), 400
    if ssid and not (1 <= len(ssid.encode('utf-8')) <= 32):
        return jsonify({'success': False, 'error': 'Setup-WiFi name must be 1–32 characters.'}), 400
    # Strict charset (defense-in-depth: the root engine parses the conf by
    # assignment, not `source`, but never let shell-active bytes into a
    # root-read config file). Reject shell metacharacters, quotes, newlines.
    _bad = set('`$();&|<>\\\'"\n\r\t')
    if any(c in _bad for c in ssid) or any(c in _bad for c in password):
        return jsonify({'success': False, 'error': 'Name/password may not contain quotes, newlines, or any of ` $ ( ) ; & | < > \\'}), 400
    if not _conn_setup_ap_write_conf(ssid, password, auto):
        return jsonify({'success': False, 'error': 'Could not save Setup AP config.'}), 500
    # ARM IT NOW, while the box still has internet. The AP itself only ever runs
    # when connectivity is gone, so this is the last moment the dependencies can
    # be fetched (ops1 2026-08-09: lazy install at start time = never).
    _armed = _conn_setup_ap_ensure_deps()
    st = _conn_setup_ap_status()
    resp = {'success': True, 'status': st}
    if not _armed:
        resp['warning'] = ('Saved, but this box could not install the Setup WiFi components '
                           '(hostapd/dnsmasq). Automatic broadcast will NOT work until it can '
                           'reach the internet once — reconnect and press Save settings again.')
    return jsonify(resp)


@app.route('/api/connectivity/setup-ap/start', methods=['POST'])
@login_required
def connectivity_setup_ap_start_api():
    if not _conn_wifi_iface():
        return jsonify({'success': False, 'error': 'No wireless interface on this box — cannot broadcast a setup network.'}), 400
    _ensure_nm_wifi()  # RHEL: the NM hotspot (mode=ap) path needs NetworkManager-wifi installed
    # RHEL: the NM hotspot uses method=shared, whose DHCP + captive DNS is served by
    # dnsmasq — a fresh Rocky box lacks it, so a joined client gets NO IP (browser:
    # ERR_INTERNET_DISCONNECTED) and the FQDN can't resolve on the isolated AP net.
    # Pull it NOW while the box is still online (this endpoint is reached over the very
    # uplink the AP is about to replace). The captive DNS wildcard that makes the FQDN
    # resolve to the box is written root-side by the engine (tak-setup-ap.sh) — the
    # console broker deliberately can't write /etc/NetworkManager (not in PATH_ALLOW).
    if _distro_family() == 'rhel':
        try:
            _pkg_install('dnsmasq', timeout=300)
        except Exception:
            pass
    # Start the root service through the broker. This SEVERS any wifi uplink (the
    # radio becomes the AP), so the HTTP response is sent before the switch lands;
    # the operator reconnects locally to the setup wifi.
    # Claim this AP as operator-initiated BEFORE starting it, so the 30s auto-watcher
    # cannot race in and stop it (ops1 2026-08-09: manual start survived 7 seconds on
    # a box with a healthy uplink — the watcher's "internet is fine, AP should be
    # down" rule could not tell a deliberate start from a stale one).
    try:
        subprocess.run(_sudo_wrap(['touch', _SETUP_AP_MANUAL_FLAG]),
                       capture_output=True, text=True, timeout=15)
    except Exception:
        pass
    # restart, not start. The unit is Type=oneshot RemainAfterExit=yes, so if it is
    # left stale-active (the watcher used to stop the AP by calling the engine behind
    # systemd's back) `start` silently does NOTHING and this button appears dead —
    # exactly what ops1 showed on 2026-08-09: unit "active (exited)", AP down, press
    # Start, no AP, no error. restart always runs ExecStart.
    r = subprocess.run(_sudo_wrap(['systemctl', 'restart', 'takwerx-setup-ap.service']),
                       capture_output=True, text=True, timeout=60)
    if r.returncode != 0:
        try:
            subprocess.run(_sudo_wrap(['rm', '-f', _SETUP_AP_MANUAL_FLAG]),
                           capture_output=True, text=True, timeout=15)
        except Exception:
            pass
        return jsonify({'success': False, 'error': (r.stderr or r.stdout or 'start failed').strip()[:200]}), 500
    return jsonify({'success': True})


def _conn_clear_dead_ethernet():
    """Tear down ethernet connections whose cable is physically gone. Rocky/RHEL
    images ship NetworkManager with ignore-carrier=* — an unplugged NIC KEEPS its
    activation and its metric-100 default route, which blackholes all egress even
    after a wifi join succeeds (field-hit 2026-07-11: OXFORD associated + leased in
    2s after Stop, but the relay tunnel stayed dead until the cable came back —
    every packet was routed into the dead wire). Only touches devices with
    carrier=0; a NIC with a live cable is never disconnected. NM re-arms
    autoconnect on the next carrier-up, so replugging the cable restores wired."""
    try:
        r = subprocess.run(_sudo_wrap(['nmcli', '-t', '-f', 'DEVICE,TYPE,STATE', 'device', 'status']),
                           capture_output=True, text=True, timeout=10)
        for ln in (r.stdout or '').splitlines():
            parts = ln.split(':')
            if len(parts) < 3 or parts[1] != 'ethernet' or not parts[2].startswith('connected'):
                continue
            dev = parts[0]
            try:
                with open('/sys/class/net/%s/carrier' % dev) as f:
                    if f.read().strip() == '1':
                        continue
            except Exception:
                continue  # cannot prove the cable is gone -> leave the device alone
            subprocess.run(_sudo_wrap(['nmcli', 'device', 'disconnect', dev]),
                           capture_output=True, text=True, timeout=15)
    except Exception:
        pass


def _conn_join_best_saved():
    """After the Setup AP stops (the explicit 'done — switch now' action; add is
    additive), join the best saved CLIENT wifi. NM's autoconnect coming out of AP mode
    is unreliable on RHEL (radio comes up idle -> box offline -> watcher re-broadcasts
    the AP), so do it explicitly. Prefers in-range saved SSIDs (skips a slow 'up'
    timeout on out-of-range profiles), never touches the takwerx-hotspot AP profile.
    Best-effort; runs detached from the stop API."""
    if not shutil.which('nmcli'):
        return
    time.sleep(2)  # let the AP teardown (restore_client) free + re-enable the radio
    # Kill any cable-less ethernet FIRST — its stale default route (RHEL
    # ignore-carrier=*) outranks the wifi route and blackholes the box even after
    # a perfect join.
    _conn_clear_dead_ethernet()
    try:
        r = subprocess.run(_sudo_wrap(['nmcli', '-t', '-f', 'NAME,TYPE', 'connection', 'show']),
                           capture_output=True, text=True, timeout=10)
        saved = []
        for ln in (r.stdout or '').splitlines():
            parts = ln.rsplit(':', 1)
            if len(parts) == 2 and 'wireless' in parts[1] and parts[0] != 'takwerx-hotspot':
                saved.append(parts[0])
    except Exception:
        saved = []
    if not saved:
        return
    try:
        visible = set(_conn_wifi_visible())
    except Exception:
        visible = set()
    ordered = [n for n in saved if n in visible] + [n for n in saved if n not in visible]

    def _wifi_has_ipv4():
        # nmcli up returns 0 even for an IPv6-only 'activated' state (older
        # profiles without ipv4.may-fail=no; field-hit 2026-07-11) — a join with
        # no usable IPv4 is a FAILURE here, not a success.
        try:
            iface = _conn_wifi_iface()
            if not iface:
                return True  # can't verify -> don't block the join on it
            rc = subprocess.run(_sudo_wrap(['nmcli', '-t', '-f', 'IP4.ADDRESS', 'device', 'show', iface]),
                                capture_output=True, text=True, timeout=10)
            return 'IP4.ADDRESS' in (rc.stdout or '')
        except Exception:
            return True

    for name in ordered:
        try:
            rr = subprocess.run(_sudo_wrap(['nmcli', 'connection', 'up', name]),
                                capture_output=True, text=True, timeout=40)
            if rr.returncode == 0 and not _wifi_has_ipv4():
                # IPv6-only limbo: tear it down and let the next candidate try.
                subprocess.run(_sudo_wrap(['nmcli', 'connection', 'down', name]),
                               capture_output=True, text=True, timeout=15)
                continue
            if rr.returncode == 0:
                # Uplink changed interface/address — bounce the relay tunnel.
                # Kernel WireGuard caches the peer's source address; after moving
                # from ethernet to wifi it can keep stamping the OLD source and
                # never complete a handshake (field 2026-07-11: OXFORD joined,
                # default route correct via wlp1s0, tunnel stayed dead until the
                # cable returned). A wg-quick restart resets the socket; the
                # relay reconnects in ~2s. No-op when no relay is provisioned.
                if os.path.exists('/etc/wireguard/%s.conf' % _CONN_WG_IF):
                    try:
                        subprocess.run(_sudo_wrap(['systemctl', 'restart', 'wg-quick@%s' % _CONN_WG_IF]),
                                       capture_output=True, text=True, timeout=30)
                    except Exception:
                        pass
                return
        except Exception:
            continue


@app.route('/api/connectivity/setup-ap/stop', methods=['POST'])
@login_required
def connectivity_setup_ap_stop_api():
    # Release the operator claim first, so the AP cannot be re-protected from the
    # watcher if the service stop below is partial. The engine clears it too.
    try:
        subprocess.run(_sudo_wrap(['rm', '-f', _SETUP_AP_MANUAL_FLAG]),
                       capture_output=True, text=True, timeout=15)
    except Exception:
        pass
    r = subprocess.run(_sudo_wrap(['systemctl', 'stop', 'takwerx-setup-ap.service']),
                       capture_output=True, text=True, timeout=60)
    if r.returncode != 0:
        return jsonify({'success': False, 'error': (r.stderr or r.stdout or 'stop failed').strip()[:200]}), 500
    # Stopping the AP is now the explicit "done provisioning — switch to a saved
    # network" step (add is additive). Deterministically join the best saved client
    # wifi in a detached thread (NM autoconnect out of AP mode is unreliable on RHEL).
    threading.Thread(target=_conn_join_best_saved, daemon=True).start()
    return jsonify({'success': True})


# ── EUD Remote Assist Portal ──────────────────────────────────────────────────

_remote_assist_deploy_status = {'running': False, 'complete': False, 'error': False, 'log': []}
_remote_assist_uninstall_status = {'running': False, 'complete': False, 'error': False}


def _remote_assist_restore_tracked_files(ra_dir):
    """Discard infra-TAK patches to tracked files so git pull succeeds (v2.1.0+ uses .env only).
    server/package.json carries the build-time npm security pin (ops #190), rewritten before
    every build."""
    import subprocess as _sp
    if not os.path.isdir(os.path.join(ra_dir, '.git')):
        return
    # One file per call: git refuses the whole pathspec if any one path is unknown.
    for _f in ('docker-compose.yml', 'server/package.json'):
        _sp.run(['git', '-C', ra_dir, 'checkout', '--', _f],
                capture_output=True, text=True, timeout=30)


def _remote_assist_read_version_file(ra_dir):
    """Semver from upstream VERSION file (source of truth since v2.0.0)."""
    try:
        with open(os.path.join(ra_dir, 'VERSION')) as f:
            return f.read().strip().lstrip('vV')
    except Exception:
        return ''


def _remote_assist_checkout_pin(ra_dir, plog):
    """ops #234: bring the Remote Assist clone to REMOTE_ASSIST_SHA, verify it, return it.

    Fetches the pinned commit by SHA (a shallow clone of main does not hold it once upstream
    moves on; upstream also rewrote history on 2026-10-25, which broke `pull --ff-only`) and
    `reset --hard`s to it. A failed fetch is only a warning: an offline box that already has
    the commit still lands on it, and one that does not fails at the reset. Then HEAD must be
    the pin and no tracked file may differ from it, or nothing gets built.

    A checkout NEWER than the pin (a box that took upstream main before the pin shipped) is
    refused rather than downgraded: the portal's database may already be migrated past what
    the pinned release understands. It moves again when the pin is bumped past it."""
    import subprocess as _sp

    def git(*args, timeout=120):
        return _sp.run(['git', '-C', ra_dir, *args], capture_output=True, text=True, timeout=timeout)

    pin = REMOTE_ASSIST_SHA
    head = (git('rev-parse', 'HEAD', timeout=10).stdout or '').strip()
    have = _remote_assist_read_version_file(ra_dir)
    if head != pin and have and (_remote_assist_version_tuple(have)
                                 > _remote_assist_version_tuple(REMOTE_ASSIST_PIN_VERSION)):
        raise RuntimeError(f'installed v{have} is newer than the reviewed release '
                           f'v{REMOTE_ASSIST_PIN_VERSION} ({pin[:7]}) — not downgrading. '
                           'It moves again when infra-TAK pins a newer reviewed release.')
    git('remote', 'set-url', 'origin', REMOTE_ASSIST_REPO, timeout=10)
    f = git('fetch', '-q', '--depth=1', 'origin', pin)
    if f.returncode != 0:
        plog(f'  ⚠ git fetch {pin[:7]}: {(f.stderr or f.stdout).strip()[:300]}')
    r = git('reset', '--hard', pin)
    plog((r.stdout + r.stderr).strip() or '(no output)')
    if r.returncode != 0:
        raise RuntimeError(f'could not check out pinned commit {pin[:7]}: {(r.stderr or "").strip()[:300]}')
    head = (git('rev-parse', 'HEAD', timeout=10).stdout or '').strip()
    if head != pin:
        raise RuntimeError(f'clone is at {head[:7] or "?"}, expected pinned commit {pin[:7]}')
    st = git('status', '--porcelain', '--untracked-files=no', timeout=30)
    if st.returncode != 0 or st.stdout.strip():
        raise RuntimeError(f'checkout does not match pinned commit {pin[:7]}: '
                           f'{(st.stdout or st.stderr).strip()[:300]}')
    plog(f'✓ Checked out reviewed commit {pin[:7]} (v{REMOTE_ASSIST_PIN_VERSION})')
    return head


def _remote_assist_deploy_log(msg):
    _remote_assist_deploy_status['log'].append(msg)


# ops #135: `compose up -d --build` never pulls. A FROM image already on the box (e.g.
# `node:22-alpine`) is reused as-is, so a rebuild or Update kept shipping the base it was
# first built on: Remote Assist sat on Node 22.23.0 on test6 while Docker Hub had 22.23.4.
# So every Deploy and Update first `docker pull`s each FROM image, then builds WITHOUT
# --pull. A pull that fails (registry unreachable, rate limit, hang) must not stop a build
# that worked yesterday, so it is logged and the build goes on with the copy on the box.
# Why not `build --pull`: with Docker's containerd image store (the default on fresh
# Docker 29 installs, and on every fleet box) a base BuildKit fetched itself is not a tagged image, so a build resolves its FROM
# against the registry even without --pull, and with the registry down it fails. A
# `docker pull` tags the base in the store, so the next build resolves it locally
# (T&E round 3, ops #136, test8 with Docker Hub blocked).
# https://docs.docker.com/reference/cli/docker/image/pull/
# https://docs.docker.com/engine/storage/containerd/
_DOCKERFILE_FROM_RE = re.compile(r'^[ \t]*FROM[ \t]+(?:--\S+[ \t]+)*(\S+)(?:[ \t]+AS[ \t]+(\S+))?',
                                 re.IGNORECASE | re.MULTILINE)


def _dockerfile_base_images(build_dir):
    """FROM images of the Dockerfiles in build_dir and its direct subdirectories, in order,
    deduplicated. Skips build-stage names, `scratch` and ARG-templated names (`$X`), none
    of which can be pulled as written."""
    paths = [os.path.join(build_dir, 'Dockerfile')]
    try:
        paths += [os.path.join(build_dir, d, 'Dockerfile') for d in sorted(os.listdir(build_dir))]
    except OSError:
        pass
    images = []
    for path in paths:
        try:
            with open(path, encoding='utf-8', errors='replace') as f:
                text = f.read()
        except OSError:
            continue
        stages = set()
        for m in _DOCKERFILE_FROM_RE.finditer(text):
            img, stage = m.group(1), m.group(2)
            if img.lower() not in stages and img.lower() != 'scratch' and '$' not in img and img not in images:
                images.append(img)
            if stage:
                stages.add(stage.lower())
    return images


def _pull_base_images(build_dir, wrap=None, plog=None, timeout=300):
    """`docker pull` every FROM image under build_dir (argv passed through `wrap`, e.g.
    _sudo_wrap). Returns the images that could not be pulled. Never raises: a failed or
    timed-out pull only means the build uses the copy already on the box."""
    _log = plog or (lambda m: print(m, flush=True))
    _wrap = wrap or (lambda argv: argv)
    failed = []
    for img in _dockerfile_base_images(build_dir):
        _log(f'  Pulling base image {img}...')
        try:
            r = subprocess.run(_wrap(['docker', 'pull', img]), cwd=build_dir,
                               capture_output=True, text=True, timeout=timeout)
            lines = (r.stderr or r.stdout or '').strip().splitlines()
            err = '' if r.returncode == 0 else (lines[-1] if lines else f'rc={r.returncode}')[-300:]
        except subprocess.TimeoutExpired:
            err = f'timed out after {timeout}s'
        except OSError as e:
            err = str(e)[-300:] or 'could not run docker pull'
        if err:
            failed.append(img)
            _log(f'  ⚠ Could not pull {img}, building on the copy already on this box: {err}')
        else:
            _log(f'  ✓ {img} current')
    return failed


# ops #190 (GHSA-27r3-jxmh-p828, High): body-parser below 1.20.9 / 2.4.0 lets one request
# with a compressed body crash the whole Node process. Parsing runs before routing, so it
# needs no login and no real route. TAK Portal (2.3.0) and Remote Assist (1.20.5) are built
# ON THE BOX from upstream lockfiles that still pin the old release, so every image build
# first writes an npm `overrides` entry into the checkout's package.json — the npm side of
# what modules/tvr.py patch_requirements() does for TVR's Python pins. A checkout discards
# it (both Update paths reset tracked files) and the next build writes it again.
# Driven by the LOCKFILE, not by a fixed version: it fires only while the lock resolves a
# release below the fix, and always as `^fix` on the major the lock already uses (Express 4
# uses body-parser 1.x, Express 5 uses 2.x). Once upstream bumps the lock it does nothing.
# https://docs.npmjs.com/cli/v10/configuring-npm/package-json#overrides
NPM_SECURITY_FLOORS = {
    'body-parser': ('1.20.9', '2.4.0'),   # GHSA-27r3-jxmh-p828
}


def _npm_security_overrides(pkg, lock, floors=None):
    """npm `overrides` entries a project needs so its build resolves NPM_SECURITY_FLOORS.

    `pkg` / `lock` are the parsed package.json / package-lock.json. Returns
    ({name: '^fix'}, [note, ...]). Adds nothing when the lock is already at or above the
    fix, when upstream already overrides the package (their call), when it is a direct
    dependency (npm rejects an override that differs from one), or when the lock carries
    more than one major of it (a single override would force them all onto one)."""
    floors = NPM_SECURITY_FLOORS if floors is None else floors
    add, notes = {}, []
    packages = (lock or {}).get('packages') or {}
    direct = set()
    for k in ('dependencies', 'devDependencies', 'optionalDependencies', 'peerDependencies'):
        direct.update(((pkg or {}).get(k) or {}).keys())
    existing = (pkg or {}).get('overrides') or {}
    for name, fixes in floors.items():
        versions = sorted({str(v.get('version') or '') for k, v in packages.items()
                           if k == f'node_modules/{name}' or k.endswith(f'/node_modules/{name}')})
        found = [(v, _semver_tuple(v)) for v in versions]
        if not found:
            continue
        if any(t is None for _, t in found):
            notes.append(f'{name}: lockfile version not understood ({", ".join(versions)}) — left alone')
            continue
        majors = {t[0] for _, t in found}
        if len(majors) != 1:
            notes.append(f'{name}: lockfile has several major versions ({", ".join(versions)}) — left alone')
            continue
        fix = next((f for f in fixes if _semver_tuple(f)[0] in majors), None)
        if fix is None or all(t >= _semver_tuple(fix) for _, t in found):
            continue
        if existing.get(name) == f'^{fix}':
            continue                # ours, left by a checkout that did not reset the file
        if name in existing:
            notes.append(f'{name}: upstream already overrides it ({existing[name]!r}) — left alone')
            continue
        if name in direct:
            notes.append(f'{name}: direct dependency at {", ".join(versions)} — cannot override, '
                         f'needs upstream to move to {fix}')
            continue
        add[name] = f'^{fix}'
        notes.append(f'{name} {", ".join(versions)} → ^{fix}')
    return add, notes


def _apply_npm_security_overrides(project_dir, plog=None):
    """Write _npm_security_overrides() into project_dir/package.json before an image build.
    Returns the entries added. Never raises: the build goes on without the bump rather than
    not at all, and says so (the Caddy edge already strips the trigger — ops #190)."""
    _log = plog or (lambda m: print(m, flush=True))
    pkg_path = os.path.join(project_dir, 'package.json')
    try:
        with open(pkg_path, encoding='utf-8') as f:
            pkg = json.load(f)
        try:
            with open(os.path.join(project_dir, 'package-lock.json'), encoding='utf-8') as f:
                lock = json.load(f)
        except FileNotFoundError:
            return {}
        add, notes = _npm_security_overrides(pkg, lock)
        for n in notes:
            _log(f'  npm security pin: {n}')
        if not add:
            return {}
        pkg['overrides'] = {**(pkg.get('overrides') or {}), **add}
        with open(pkg_path, 'w', encoding='utf-8') as f:
            f.write(json.dumps(pkg, indent=2, ensure_ascii=False) + '\n')
        return add
    except Exception as e:
        _log(f'  ⚠ npm security pin not applied ({pkg_path}): {str(e)[:200]} — building upstream\'s lockfile as-is')
        return {}


def _remote_assist_compose_files(ra_dir):
    return os.path.join(ra_dir, 'docker-compose.yml')


def _remote_assist_compose_cmd(ra_dir, *args):
    return ['docker', 'compose', '-f', _remote_assist_compose_files(ra_dir), *args]


def _ensure_authentik_remote_assist_app(settings, plog=None):
    """Create Authentik OAuth2/OIDC provider + application for Remote Assist admin portal."""
    import urllib.request as _urlreq
    import urllib.error

    def log(msg):
        if plog:
            plog(msg)

    ak_url = _get_authentik_api_url(settings)
    token = (_get_authentik_env_value(settings, 'AUTHENTIK_BOOTSTRAP_TOKEN')
             or _get_authentik_env_value(settings, 'AUTHENTIK_TOKEN'))
    if not token:
        log('  ✗ No Authentik API token found in .env')
        return None, None
    _ak_headers = {'Authorization': f'Bearer {token}', 'Content-Type': 'application/json'}

    slug = REMOTE_ASSIST_OIDC_SLUG
    provider_name = 'EUD Remote Assist'
    portal_domain = _get_service_domain(settings, 'remote_assist')
    portal_base = f'https://{_pub_hostport(portal_domain)}'
    device_base = f'https://{portal_domain}:{REMOTE_ASSIST_DEVICE_PORT}'
    redirect_uris_obj = [
        {'matching_mode': 'strict', 'url': portal_base},
        {'matching_mode': 'strict', 'url': f'{portal_base}/'},
        {'matching_mode': 'strict', 'url': f'{portal_base}/callback'},
        {'matching_mode': 'strict', 'url': f'{portal_base}/silent-callback'},
    ]

    try:
        flow_pk, inv_flow_pk = None, None
        for attempt in range(6):
            try:
                req = _urlreq.Request(f'{ak_url}/api/v3/flows/instances/?designation=authorization&ordering=slug', headers=_ak_headers)
                auth_flows = json.loads(_urlreq.urlopen(req, timeout=15).read().decode())['results']
                flow_pk = next((f['pk'] for f in auth_flows if 'implicit' in f.get('slug', '')), auth_flows[0]['pk'] if auth_flows else None)
                req = _urlreq.Request(f'{ak_url}/api/v3/flows/instances/?designation=invalidation&ordering=slug', headers=_ak_headers)
                inv_flows = json.loads(_urlreq.urlopen(req, timeout=15).read().decode())['results']
                inv_flow_pk = inv_flows[0]['pk'] if inv_flows else None
            except Exception:
                pass
            if flow_pk and inv_flow_pk:
                break
            time.sleep(5)
        if not flow_pk or not inv_flow_pk:
            log(f'  ✗ Missing Authentik flows: auth={flow_pk}, invalidation={inv_flow_pk}')
            return None, None
        log('  ✓ Got authorization and invalidation flows')

        signing_key_pk = None
        scope_mapping_pks = []
        try:
            req = _urlreq.Request(f'{ak_url}/api/v3/crypto/certificatekeypairs/?has_key=true&ordering=name&page_size=50', headers=_ak_headers)
            certs = json.loads(_urlreq.urlopen(req, timeout=15).read().decode()).get('results', [])
            signing_key_pk = next((c['pk'] for c in certs if 'authentik' in (c.get('name') or '').lower()), None)
            if not signing_key_pk and certs:
                signing_key_pk = certs[0]['pk']
        except Exception:
            pass
        try:
            req = _urlreq.Request(f'{ak_url}/api/v3/propertymappings/provider/scope/?ordering=scope_name&page_size=50', headers=_ak_headers)
            mappings = json.loads(_urlreq.urlopen(req, timeout=15).read().decode()).get('results', [])
            scope_mapping_pks = [m['pk'] for m in mappings if m.get('scope_name') in {'openid', 'email', 'profile', 'groups'}]
        except Exception:
            pass

        _provider_extras = {}
        if signing_key_pk:
            _provider_extras['signing_key'] = signing_key_pk
        if scope_mapping_pks:
            _provider_extras['property_mappings'] = scope_mapping_pks

        provider_pk = None
        client_id = ''
        try:
            req = _urlreq.Request(f'{ak_url}/api/v3/providers/oauth2/?search={urllib.parse.quote(provider_name)}', headers=_ak_headers)
            existing = json.loads(_urlreq.urlopen(req, timeout=15).read().decode()).get('results', [])
            for ex in existing:
                if ex.get('name') == provider_name:
                    ex_pk = ex.get('pk')
                    req = _urlreq.Request(f'{ak_url}/api/v3/providers/oauth2/{ex_pk}/', headers=_ak_headers)
                    detail = json.loads(_urlreq.urlopen(req, timeout=15).read().decode())
                    if detail.get('client_id'):
                        provider_pk = ex_pk
                        client_id = detail['client_id']
                        # Browser portal is a public SPA (oidc-client-ts + PKCE). Confidential
                        # clients require client_secret at /token/ — causes HTTP 400 on sign-in.
                        patch_data = {
                            'redirect_uris': redirect_uris_obj,
                            'client_type': 'public',
                            'grant_types': ['authorization_code', 'refresh_token'],
                        }
                        patch_data.update(_provider_extras)
                        try:
                            req = _urlreq.Request(f'{ak_url}/api/v3/providers/oauth2/{ex_pk}/',
                                data=json.dumps(patch_data).encode(), headers=_ak_headers, method='PATCH')
                            _urlreq.urlopen(req, timeout=10)
                        except Exception:
                            pass
                        log(f'  ✓ Existing OAuth2 provider updated (public SPA), client_id={client_id[:8]}...')
                    break
        except Exception:
            pass

        if not provider_pk:
            payload = {
                'name': provider_name,
                'authorization_flow': flow_pk,
                'invalidation_flow': inv_flow_pk,
                'client_type': 'public',
                'client_id': slug,
                'redirect_uris': redirect_uris_obj,
                'grant_types': ['authorization_code', 'refresh_token'],
            }
            payload.update(_provider_extras)
            try:
                req = _urlreq.Request(f'{ak_url}/api/v3/providers/oauth2/',
                    data=json.dumps(payload).encode(), headers=_ak_headers, method='POST')
                p = json.loads(_urlreq.urlopen(req, timeout=15).read().decode())
                provider_pk = p.get('pk')
                client_id = p.get('client_id', '')
                log(f'  ✓ OAuth2 provider created (public SPA), client_id={client_id[:8]}...')
            except Exception as e:
                body = ''
                try:
                    body = e.read().decode()[:500]
                except Exception:
                    pass
                log(f'  ✗ OAuth2 provider create failed: {body or str(e)[:200]}')

        if not provider_pk or not client_id:
            log('  ✗ No OAuth2 provider — cannot continue')
            return None, None

        _app_body = {
            'name': provider_name,
            'slug': slug,
            'provider': provider_pk,
            'meta_launch_url': portal_base,
        }
        try:
            req = _urlreq.Request(f'{ak_url}/api/v3/core/applications/',
                data=json.dumps(_app_body).encode(), headers=_ak_headers, method='POST')
            _urlreq.urlopen(req, timeout=10)
            log('  ✓ Application created')
        except Exception as e:
            if hasattr(e, 'code') and e.code == 400:
                try:
                    req = _urlreq.Request(f'{ak_url}/api/v3/core/applications/{slug}/',
                        data=json.dumps({'provider': provider_pk, 'meta_launch_url': portal_base}).encode(),
                        headers=_ak_headers, method='PATCH')
                    _urlreq.urlopen(req, timeout=10)
                except Exception:
                    pass
                log('  ✓ Application already exists (updated)')
            else:
                log(f'  ⚠ Application error: {str(e)[:80]}')

        try:
            _ak_url = _get_authentik_api_url(settings)
            _ak_token = token
            if _ak_token:
                _ensure_app_access_policies(_ak_url, {'Authorization': f'Bearer {_ak_token}',
                                                      'Content-Type': 'application/json'}, plog)
                log('  ✓ Portal access restricted to infra-TAK administrators (authentik Admins)')
        except Exception as _e:
            log(f'  ⚠ Access policy binding skipped: {str(_e)[:120]}')

        return client_id, ''
    except Exception as e:
        log(f'  ✗ Authentik OAuth setup failed: {str(e)[:200]}')
        return None, None


def _deregister_authentik_oauth2_app(settings, app_slug, prov_name, plog=None):
    """Remove OAuth2 application + provider from Authentik. Idempotent, non-fatal."""
    _log = plog or (lambda m: None)
    import urllib.request as _req
    ak_token = (
        _get_authentik_env_value(settings, 'AUTHENTIK_BOOTSTRAP_TOKEN') or
        _get_authentik_env_value(settings, 'AUTHENTIK_TOKEN')
    )
    if not ak_token:
        return False
    ak_url = _get_authentik_api_url(settings)
    ak_headers = {'Authorization': f'Bearer {ak_token}', 'Content-Type': 'application/json'}

    def _del(url):
        try:
            _req.urlopen(_req.Request(url, headers=ak_headers, method='DELETE'), timeout=10)
            return True
        except Exception as e:
            if getattr(e, 'code', None) == 404:
                return True
            return False

    provider_pk = None
    try:
        r = _req.Request(f'{ak_url}/api/v3/core/applications/{app_slug}/', headers=ak_headers)
        app = json.loads(_req.urlopen(r, timeout=10).read().decode())
        provider_pk = app.get('provider')
    except Exception:
        pass
    if not provider_pk and prov_name:
        try:
            r = _req.Request(f'{ak_url}/api/v3/providers/oauth2/?search={urllib.parse.quote(prov_name)}', headers=ak_headers)
            results = json.loads(_req.urlopen(r, timeout=10).read().decode()).get('results', [])
            match = next((p for p in results if (p.get('name') or '').strip() == prov_name), None)
            if match:
                provider_pk = match.get('pk')
        except Exception:
            pass
    if _del(f'{ak_url}/api/v3/core/applications/{app_slug}/'):
        _log(f"  ✓ Authentik application '{app_slug}' removed")
    if provider_pk and _del(f'{ak_url}/api/v3/providers/oauth2/{provider_pk}/'):
        _log(f"  ✓ Authentik OAuth2 provider '{prov_name}' removed")
    return True


def _takportal_latest_tag(plog=None):
    """Newest TAK Portal RELEASE tag, or the pinned fallback. Never raises.

    Validated against a strict version shape before it is handed to git — the tag
    reaches a checkout argument, so an unexpected value must not flow through
    (same discipline as _ak_tag_is_sane() for the Authentik tag).
    """
    # `_ur` is imported PER FUNCTION throughout this file — there is no module-level
    # binding. Relying on one inside a try/except Exception is how the mediamtx
    # update checks sat dead from birth: NameError, swallowed, silent wrong answer
    # ([[apppy-ur-per-function-import-silent-nameerror]]). Import it here explicitly.
    import urllib.request as _ur
    tag = None
    try:
        req = _ur.Request('https://api.github.com/repos/ValleyTacticalSolutions/TAK-Portal/releases/latest',
                          headers={'Accept': 'application/vnd.github+json',
                                   'User-Agent': 'infra-TAK'})
        with _ur.urlopen(req, timeout=15) as r:
            tag = (json.loads(r.read().decode()) or {}).get('tag_name')
    except Exception as e:
        if plog:
            plog(f"  Could not reach the GitHub releases API ({str(e)[:80]}) — using pinned {TAKPORTAL_REF_FALLBACK}")
    if not tag or not re.match(r'^v?\d+(\.\d+){1,3}$', str(tag).strip()):
        return TAKPORTAL_REF_FALLBACK
    return str(tag).strip()


def _remote_assist_write_env(ra_dir, settings, client_id, pg_password):
    ak_domain = _get_service_domain(settings, 'authentik')
    portal_domain = _get_service_domain(settings, 'remote_assist')
    portal_base = f'https://{_pub_hostport(portal_domain)}'
    device_base = f'https://{portal_domain}:{REMOTE_ASSIST_DEVICE_PORT}'
    oidc_issuer = f'https://{_pub_hostport(ak_domain)}/application/o/{REMOTE_ASSIST_OIDC_SLUG}/'
    oidc_jwks = f'{oidc_issuer.rstrip("/")}/jwks/'
    env_lines = [
        f'POSTGRES_USER=cfd',
        f'POSTGRES_PASSWORD={pg_password}',
        f'POSTGRES_DB=eud_remote_assist',
        f'PUBLIC_BASE_URL={device_base}',
        f'OIDC_ISSUER={oidc_issuer}',
        f'OIDC_AUDIENCE={client_id}',
        f'OIDC_CLIENT_ID={client_id}',
        f'OIDC_JWKS_URI={oidc_jwks}',
        f'OIDC_ADMIN_GROUP=authentik Admins',
        f'CORS_ORIGIN={portal_base}',
        f'NGINX_BIND_ADDR=127.0.0.1',
        f'HTTP_PORT={REMOTE_ASSIST_PORT}',
        f'NGINX_ENABLE_TLS=false',
        # v10.0.9 security scan: keep upstream TLS verification ON for the phonedb.net
        # lookup (upstream .env.example ships it disabled-by-default — a MITM could inject
        # crafted HTML into device model metadata rendered in the admin console). CJIS bar
        # forbids disabled cert verification; the lookup is non-critical, so fail-closed.
        f'PHONEDB_TLS_INSECURE=false',
    ]
    env_path = os.path.join(ra_dir, '.env')
    with open(env_path, 'w') as f:
        f.write('\n'.join(env_lines) + '\n')
    os.chmod(env_path, 0o600)


# ops #138: Postgres reads POSTGRES_PASSWORD once, when the data volume is first created; the
# password then lives in the volume and the env var is ignored. Deploy and Update used to take
# the saved password or make a random one (since v0.9.59), so a box with none saved got a .env
# its own database had never seen, and Remote Assist could no longer log in. A new password is
# now made only when there is no database yet; otherwise the one in use is adopted and saved.
# https://hub.docker.com/_/postgres (POSTGRES_PASSWORD: "only used if you start the container
# with an empty data directory")
def _remote_assist_env_value(ra_dir, key):
    """`key` from Remote Assist's .env, or ''."""
    try:
        with open(os.path.join(ra_dir, '.env')) as f:
            for line in f:
                k, sep, v = line.strip().partition('=')
                if sep and k.strip() == key:
                    return v.strip().strip('"\'')
    except OSError:
        pass
    return ''


def _remote_assist_db_state(ra_dir):
    """(exists, password) for the database of the compose project in `ra_dir`: whether its
    postgres container or data volume exists, and the POSTGRES_PASSWORD its container was
    created with ('' if unknown). Plain docker, not compose: compose refuses to parse the
    file at all when .env is missing (POSTGRES_PASSWORD is `:?` required)."""
    project = re.sub(r'[^a-z0-9_-]', '', os.path.basename(os.path.normpath(ra_dir)).lower())
    try:
        r = subprocess.run(['docker', 'ps', '-a', '-q',
                            '--filter', f'label=com.docker.compose.project.working_dir={ra_dir}',
                            '--filter', 'label=com.docker.compose.service=postgres'],
                           capture_output=True, text=True, timeout=30)
        cids = (r.stdout or '').split() if r.returncode == 0 else []
        if cids:
            r = subprocess.run(['docker', 'inspect', '--format',
                                '{{range .Config.Env}}{{println .}}{{end}}', cids[0]],
                               capture_output=True, text=True, timeout=30)
            for line in (r.stdout or '').splitlines():
                k, sep, v = line.partition('=')
                if sep and k == 'POSTGRES_PASSWORD':
                    return True, v.strip()
            return True, ''
        r = subprocess.run(['docker', 'volume', 'ls', '-q',
                            '--filter', f'label=com.docker.compose.project={project}',
                            '--filter', 'label=com.docker.compose.volume=postgres_data'],
                           capture_output=True, text=True, timeout=30)
        return bool(r.returncode == 0 and (r.stdout or '').strip()), ''
    except Exception:
        return False, ''


def _remote_assist_pg_password(ra_dir, settings, plog):
    """The DB password to write to .env. Saved setting first, then the existing .env, then the
    running postgres container. A new one only when there is no database: with a database and
    no password anywhere, the new one is applied to the database by _remote_assist_sync_db_password."""
    saved = settings.get('remote_assist_pg_password')
    if saved:
        return saved
    from_env = _remote_assist_env_value(ra_dir, 'POSTGRES_PASSWORD')
    if from_env:
        plog('  No DB password saved in the console; using the one in .env')
        return from_env
    exists, from_container = _remote_assist_db_state(ra_dir)
    if from_container:
        plog('  No DB password saved in the console; using the one the database container runs with')
        return from_container
    if exists:
        plog('  ⚠ Existing database but no password found anywhere; setting a new one on the database')
    return secrets.token_hex(24)


def _remote_assist_pw_matches(verifier, password, user):
    """True if `password` matches a pg_authid.rolpassword verifier (SCRAM-SHA-256 or md5)."""
    verifier = (verifier or '').strip()
    if verifier.startswith('SCRAM-SHA-256$'):
        try:
            iters_salt, keys = verifier[len('SCRAM-SHA-256$'):].split('$', 1)
            iters, salt = iters_salt.split(':', 1)
            stored_key = keys.split(':', 1)[0]
            salted = hashlib.pbkdf2_hmac('sha256', password.encode(), _b64.b64decode(salt), int(iters))
            client_key = hmac.new(salted, b'Client Key', hashlib.sha256).digest()
            return hmac.compare_digest(hashlib.sha256(client_key).digest(), _b64.b64decode(stored_key))
        except Exception:
            return False
    if verifier.startswith('md5'):
        return hmac.compare_digest(verifier, 'md5' + hashlib.md5((password + user).encode()).hexdigest())
    return False


def _remote_assist_sync_db_password(ra_dir, pg_password, plog):
    """Make the database role's password match .env, over the container's local socket (trust
    in the official image, so the old password is not needed). A no-op when they already match.
    Also repairs installs an earlier Update already broke. Returns True if it changed anything."""
    user = _remote_assist_env_value(ra_dir, 'POSTGRES_USER') or 'cfd'
    psql = _remote_assist_compose_cmd(ra_dir, 'exec', '-T', 'postgres',
                                      'psql', '-v', 'ON_ERROR_STOP=1', '-U', user, '-d', 'postgres', '-tA')
    r = subprocess.run(psql + ['-c', 'SELECT rolpassword FROM pg_authid WHERE rolname = current_user'],
                       capture_output=True, text=True, timeout=60, cwd=ra_dir)
    if r.returncode != 0:
        plog(f'  ⚠ Could not check the database password: {(r.stderr or r.stdout).strip()[-200:]}')
        return False
    if _remote_assist_pw_matches(r.stdout, pg_password, user):
        plog('  ✓ Database password matches .env')
        return False
    # The password goes in on stdin, not argv, so it never shows in a process list.
    sql = "ALTER ROLE CURRENT_USER PASSWORD '%s';\n" % pg_password.replace("'", "''")
    r = subprocess.run(psql, input=sql, capture_output=True, text=True, timeout=60, cwd=ra_dir)
    if r.returncode != 0:
        # Not psql's output: an error echoes the statement, password included.
        plog(f'  ⚠ Could not set the database password (psql exit {r.returncode})')
        return False
    subprocess.run(_remote_assist_compose_cmd(ra_dir, 'restart', 'server'),
                   capture_output=True, text=True, timeout=120, cwd=ra_dir)
    plog('  ✓ Database password did not match .env; set it and restarted the server')
    return True


def _run_remote_assist_deploy(settings):
    import subprocess as _sp
    plog = _remote_assist_deploy_log
    ra_dir = REMOTE_ASSIST_INSTALL_DIR
    try:
        fqdn = (settings.get('fqdn') or '').strip()
        if not fqdn:
            raise RuntimeError('FQDN required — configure Caddy SSL first (Marketplace needs a domain for OIDC).')

        plog('━━━ Step 1/6: Checking Docker ━━━')
        _rc, _dv = _docker_probe()
        if _rc != 0:
            plog('  Docker not found — installing...')
            if not _install_docker_engine(plog):
                raise RuntimeError('Docker install failed — see log above')
            plog('✓ Docker installed')
        else:
            plog(f'✓ Docker present: {_dv}')

        plog('')
        plog('━━━ Step 2/6: Provisioning Authentik OIDC Application ━━━')
        client_id, client_secret = _ensure_authentik_remote_assist_app(settings, plog=plog)
        _w1_reassert_app_mfa(plog)  # WS3 1b: late-created app must not ship without the MFA gate
        if not client_id:
            raise RuntimeError('Authentik OIDC provisioning failed — ensure Authentik is running.')

        plog('')
        plog('━━━ Step 3/6: Cloning Repository ━━━')
        if os.path.isdir(os.path.join(ra_dir, '.git')):
            plog(f'  Repo already at {ra_dir}')
            _h, _he = _module_checkout_ownership_selfheal(ra_dir, plog=plog)
            if _he:
                plog(f'  ownership self-heal did not complete: {_he}')
            _remote_assist_restore_tracked_files(ra_dir)
        else:
            os.makedirs(ra_dir, exist_ok=True)
            plog(f'  Cloning {REMOTE_ASSIST_REPO} → {ra_dir}')
            # --no-checkout: main's tip is not what we run; the pinned commit is checked out next.
            r = _sp.run(['git', 'clone', '--depth=1', '--no-checkout', REMOTE_ASSIST_REPO, ra_dir],
                        capture_output=True, text=True, timeout=180)
            if r.returncode != 0:
                raise RuntimeError(f'git clone failed: {r.stderr[:300]}')
            plog('✓ Repository cloned')
        _remote_assist_checkout_pin(ra_dir, plog)  # ops #234

        sha_r = _sp.run(['git', '-C', ra_dir, 'rev-parse', '--short', 'HEAD'], capture_output=True, text=True)
        commit_sha = sha_r.stdout.strip() or 'unknown'
        plog(f'  Commit SHA: {commit_sha}')
        _sp.run(['git', '-C', ra_dir, 'fetch', '--tags', '--depth', '1'],
                capture_output=True, text=True, timeout=60)

        plog('')
        plog('━━━ Step 4/6: Writing Configuration ━━━')
        pg_password = _remote_assist_pg_password(ra_dir, settings, plog)
        _remote_assist_write_env(ra_dir, settings, client_id, pg_password)
        ra_version = _remote_assist_read_version_file(ra_dir)
        plog(f'✓ .env written (NGINX_BIND_ADDR=127.0.0.1 HTTP_PORT={REMOTE_ASSIST_PORT})')
        if ra_version:
            plog(f'  Portal release: v{ra_version}')

        plog('')
        plog('━━━ Step 5/6: Building & Starting Containers ━━━')
        plog('  ⏳ First build compiles server + web — allow 5–10 min...')
        _apply_npm_security_overrides(os.path.join(ra_dir, 'server'), plog=plog)  # ops #190
        _pull_base_images(ra_dir, plog=plog)  # ops #135
        r = _sp.run(_remote_assist_compose_cmd(ra_dir, 'up', '-d', '--build'),
                    capture_output=True, text=True, timeout=900, cwd=ra_dir)
        if r.returncode != 0:
            raise RuntimeError(f'docker compose up --build failed:\n{(r.stderr or r.stdout)[-600:]}')
        plog('✓ Containers built and started')
        _remote_assist_sync_db_password(ra_dir, pg_password, plog)
        _sp.run(_remote_assist_compose_cmd(ra_dir, 'up', '-d', '--force-recreate', 'nginx'),
                capture_output=True, text=True, timeout=120, cwd=ra_dir)
        plog('✓ nginx recreated (picks up host nginx.conf + loopback bind)')

        plog('')
        plog('━━━ Step 6/6: Firewall & Reverse Proxy ━━━')
        if _distro_family() == 'rhel':
            # No ufw on RHEL (bare argv ufw aborts the deploy). The admin/proxy port stays
            # closed — it's loopback/Caddy-only and firewalld default-deny covers it. But the
            # Android device API port is a real inbound listener (host Caddy), so it must be
            # opened in firewalld explicitly: the cloud SG sits IN FRONT of the host firewall,
            # so 'SG handles it' is not enough — firewalld still drops 8448 at the host.
            _run_priv_chain([['firewall-cmd', '--permanent', f'--add-port={REMOTE_ASSIST_DEVICE_PORT}/tcp'], ['firewall-cmd', '--reload']], 'seq', timeout=30)
            plog(f'  ✓ firewalld allow {REMOTE_ASSIST_DEVICE_PORT}/tcp (Android device API); {REMOTE_ASSIST_PORT} Caddy-only (loopback)')
        else:
            _sp.run(_sudo_wrap(['ufw', 'deny', f'{REMOTE_ASSIST_PORT}/tcp']), capture_output=True)
            plog(f'  ✓ ufw deny {REMOTE_ASSIST_PORT}/tcp (loopback/Caddy-only)')
            _sp.run(_sudo_wrap(['ufw', 'allow', f'{REMOTE_ASSIST_DEVICE_PORT}/tcp']), capture_output=True)
            plog(f'  ✓ ufw allow {REMOTE_ASSIST_DEVICE_PORT}/tcp (Android device API)')
        s = load_settings()
        s['remote_assist_enabled'] = True
        s['remote_assist_pg_password'] = pg_password
        s['remote_assist_commit_sha'] = commit_sha
        s['remote_assist_oidc_client_id'] = client_id
        if ra_version:
            s['remote_assist_version'] = ra_version
        save_settings(s)
        generate_caddyfile(s)
        _sp.run(_sudo_wrap(['systemctl', 'restart', 'caddy']), stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True, timeout=90)
        plog('✓ Caddy restarted (8448 listener requires full restart)')

        portal_url = f'https://{_pub_hostport(_get_service_domain(s, "remote_assist"))}'
        device_url = f'{portal_url}:{REMOTE_ASSIST_DEVICE_PORT}'
        plog('')
        plog('🎉 Remote Assist deployed successfully!')
        plog(f'Admin portal: {portal_url}')
        plog(f'Device API:   {device_url}')
        plog('Sign in with Authentik — infra-TAK administrators only (authentik Admins group).')
        _remote_assist_deploy_status.update({'running': False, 'complete': True, 'error': False})
    except Exception as exc:
        plog(f'✗ Deployment failed: {exc}')
        _remote_assist_deploy_status.update({'running': False, 'error': True})


def _remote_assist_version_tuple(ver):
    """Parse semver-ish tag (v1.3.3) to comparable tuple."""
    import re as _re
    v = (ver or '').strip().lstrip('vV')
    parts = []
    for p in v.split('.')[:3]:
        try:
            parts.append(int(_re.sub(r'[^0-9].*', '', p) or '0'))
        except ValueError:
            parts.append(0)
    while len(parts) < 3:
        parts.append(0)
    return tuple(parts)


def _get_remote_assist_running_version():
    """Running portal version from loopback /version (device API path on nginx)."""
    import urllib.request as _ur
    try:
        req = _ur.Request(
            f'http://127.0.0.1:{REMOTE_ASSIST_PORT}/version',
            headers={'User-Agent': 'infra-TAK'})
        with _ur.urlopen(req, timeout=5) as resp:
            data = json.loads(resp.read().decode())
            return (data.get('version') or '').strip().lstrip('vV')
    except Exception:
        return ''


def _get_remote_assist_version_info(*, fresh=False):
    """Return {version, update_available, latest, latest_tag, running, is_current} for EUD Remote Assist.

    ops #234: compares the FULL local SHA against the pin REMOTE_ASSIST_SHA, and `latest` is
    the pinned release. It used to chase upstream main through the GitHub API, which offered
    every box whatever upstream published next, unreviewed. A checkout newer than the pin is
    not offered an update (_remote_assist_checkout_pin refuses that downgrade). There is no
    network call any more; `fresh` is kept for the callers.
    """
    import subprocess as _sp
    info = {'version': '', 'update_available': False, 'latest': None, 'latest_tag': None,
            'running': '', 'is_current': False}
    ra_dir = REMOTE_ASSIST_INSTALL_DIR
    settings = load_settings()
    local_ver = ''
    if os.path.isdir(ra_dir):
        local_ver = _remote_assist_read_version_file(ra_dir)
    if not local_ver:
        local_ver = (settings.get('remote_assist_version') or '').strip()
    local_full = ''
    if os.path.isdir(os.path.join(ra_dir, '.git')):
        try:
            r = _sp.run(['git', 'rev-parse', 'HEAD'],
                        capture_output=True, text=True, timeout=5, cwd=ra_dir)
            if r.returncode == 0:
                local_full = r.stdout.strip()
        except Exception:
            pass
    if local_ver:
        info['version'] = local_ver
    elif local_full:
        info['version'] = local_full[:7]
    elif settings.get('remote_assist_commit_sha'):
        info['version'] = settings['remote_assist_commit_sha']

    info['latest'] = info['latest_tag'] = REMOTE_ASSIST_PIN_VERSION
    pin_t = _remote_assist_version_tuple(REMOTE_ASSIST_PIN_VERSION)
    newer = bool(local_ver) and _remote_assist_version_tuple(local_ver) > pin_t
    if local_full:
        info['is_current'] = local_full == REMOTE_ASSIST_SHA
        info['update_available'] = not info['is_current'] and not newer
    elif local_ver:
        info['update_available'] = _remote_assist_version_tuple(local_ver) < pin_t
        info['is_current'] = _remote_assist_version_tuple(local_ver) == pin_t
    running = _get_remote_assist_running_version()
    if running:
        info['running'] = running
    return info


_remote_assist_update_status = {'running': False, 'complete': False, 'error': False, 'log': []}


def _run_remote_assist_update():
    import subprocess as _sp
    global _remote_assist_update_status
    log = []
    def plog(msg):
        log.append(msg)
        _remote_assist_update_status['log'] = list(log)
    ra_dir = REMOTE_ASSIST_INSTALL_DIR
    try:
        settings = load_settings()
        plog('━━━ Step 1/5: Checking out the reviewed release ━━━')
        _h, _he = _module_checkout_ownership_selfheal(ra_dir, plog=plog)
        if _he:
            plog(f'  ownership self-heal did not complete: {_he}')
        _remote_assist_restore_tracked_files(ra_dir)
        # ops #234: the pinned commit, not upstream main (sets the remote URL too)
        _remote_assist_checkout_pin(ra_dir, plog)
        _sp.run(['git', '-C', ra_dir, 'fetch', '--tags', '--depth', '1'],
                capture_output=True, text=True, timeout=60)

        plog('')
        plog('━━━ Step 2/5: Refreshing Authentik + .env ━━━')
        client_id = settings.get('remote_assist_oidc_client_id')
        if not client_id:
            client_id, _ = _ensure_authentik_remote_assist_app(settings, plog=plog)
        if not client_id:
            raise RuntimeError('Authentik OIDC client_id missing')
        pg_password = _remote_assist_pg_password(ra_dir, settings, plog)
        _remote_assist_write_env(ra_dir, settings, client_id, pg_password)
        ra_version = _remote_assist_read_version_file(ra_dir)
        plog(f'✓ .env written (loopback nginx → 127.0.0.1:{REMOTE_ASSIST_PORT})')
        if ra_version:
            plog(f'  Portal release: v{ra_version}')

        plog('')
        plog('━━━ Step 3/5: Rebuilding containers ━━━')
        _apply_npm_security_overrides(os.path.join(ra_dir, 'server'), plog=plog)  # ops #190
        _pull_base_images(ra_dir, plog=plog)  # ops #135
        r = _sp.run(_remote_assist_compose_cmd(ra_dir, 'up', '-d', '--build'),
                    capture_output=True, text=True, timeout=900, cwd=ra_dir)
        plog((r.stdout + r.stderr).strip()[-600:] or '(no output)')
        if r.returncode != 0:
            raise RuntimeError(f'docker compose build failed: {r.stderr[:300]}')
        _remote_assist_sync_db_password(ra_dir, pg_password, plog)
        _sp.run(_remote_assist_compose_cmd(ra_dir, 'up', '-d', '--force-recreate', 'nginx'),
                capture_output=True, text=True, timeout=120, cwd=ra_dir)
        plog('✓ nginx recreated (picks up host nginx.conf + loopback bind)')
        try:
            if _coturn_converge_override(plog=lambda m: plog(f'  {m}')) == 'current':
                plog(f'✓ CoTURN already on {COTURN_IMAGE}')
        except Exception as _ct_err:
            plog(f'  ⚠ CoTURN security update not applied: {str(_ct_err)[:200]}')

        plog('')
        plog('━━━ Step 4/5: Verifying running version ━━━')
        running_ver = _get_remote_assist_running_version()
        if running_ver:
            plog(f'  GET /version → v{running_ver}')
            if ra_version and running_ver != ra_version:
                plog(f'  ⚠ VERSION file is v{ra_version} but container reports v{running_ver}')

        plog('')
        plog('━━━ Step 5/5: Saving new version ━━━')
        sha_r = _sp.run(['git', '-C', ra_dir, 'rev-parse', '--short', 'HEAD'],
                        capture_output=True, text=True, timeout=5)
        new_sha = sha_r.stdout.strip() or 'unknown'
        s = load_settings()
        s['remote_assist_commit_sha'] = new_sha
        s['remote_assist_pg_password'] = pg_password
        s['remote_assist_oidc_client_id'] = client_id
        if ra_version:
            s['remote_assist_version'] = ra_version
        save_settings(s)
        label = f'v{ra_version}' if ra_version else new_sha
        plog(f'✓ EUD Remote Assist updated to {label}')
        _remote_assist_update_status.update({'running': False, 'complete': True, 'error': False})
    except Exception as exc:
        plog(f'ERROR: {exc}')
        _remote_assist_update_status.update({'running': False, 'complete': False, 'error': str(exc)})


@app.route('/api/remote-assist/version')
@login_required
def remote_assist_version_api():
    fresh = request.args.get('fresh', '1').lower() in ('1', 'true', 'yes')
    return jsonify(_get_remote_assist_version_info(fresh=fresh))


@app.route('/api/remote-assist/update', methods=['POST'])
@login_required
def remote_assist_update_api():
    global _remote_assist_update_status
    if _remote_assist_update_status.get('running'):
        return jsonify({'started': False, 'error': 'Update already in progress'})
    _remote_assist_update_status = {'running': True, 'complete': False, 'error': False, 'log': []}
    threading.Thread(target=_run_tracked,  # v10.2.8 W10 (the worker mutates this dict in place)
                     args=('remote-assist', _remote_assist_update_status, None,
                           _run_remote_assist_update),
                     daemon=True).start()
    return jsonify({'started': True})


@app.route('/api/remote-assist/update-status')
@login_required
def remote_assist_update_status_api():
    return jsonify(_remote_assist_update_status)


@app.route('/remote-assist')
@login_required
def remote_assist_page():
    from flask import make_response
    settings = load_settings()
    modules = detect_modules()
    ra = modules.get('remote_assist', {})
    ak = modules.get('authentik', {})
    if ra.get('installed') and not _remote_assist_deploy_status.get('running', False):
        _remote_assist_deploy_status.update({'complete': False, 'error': False})
    ra_host = _get_service_domain(settings, 'remote_assist')
    ra_url = f'https://{_pub_hostport(ra_host)}' if ra_host else ''
    ra_vinfo = _get_remote_assist_version_info(fresh=True) if ra.get('installed') else {}
    ra_commit = settings.get('remote_assist_commit_sha', '')
    coturn_ip = settings.get('coturn_ip', '')
    coturn_port = str(settings.get('coturn_port') or COTURN_DEFAULT_PORT)
    # Legacy-NetBird coturn detection + shared-mode health (Mike/cfd2474, PR #49)
    _nb_has, _nb_ctr, _nb_conf = _netbird_coturn_status() if ra.get('installed') else (False, None, None)
    netbird_coturn_in_use = bool(settings.get('netbird_coturn_in_use'))
    r = make_response(render_template('remote_assist.html',
        settings=settings, ra=ra, version=VERSION,
        authentik_installed=ak.get('installed'),
        ra_host=ra_host, ra_url=ra_url,
        ra_vinfo=ra_vinfo, ra_commit=ra_commit,
        remote_assist_logo_url=REMOTE_ASSIST_LOGO_URL,
        coturn_installed=settings.get('coturn_installed', False),
        coturn_username=settings.get('coturn_username', ''),
        coturn_password=settings.get('coturn_password', ''),
        coturn_ip=coturn_ip,
        coturn_url=(f'turn:{coturn_ip}:{coturn_port}' if coturn_ip else ''),
        coturn_suggested_port=COTURN_DEFAULT_PORT,
        coturn_block_private=_coturn_block_private_peers(settings),
        can_configure_nb_coturn=bool(_nb_has and _nb_ctr and _nb_conf),
        netbird_coturn_in_use=netbird_coturn_in_use,
        netbird_coturn_missing=(netbird_coturn_in_use and not _nb_ctr),
        deploying=_remote_assist_deploy_status.get('running', False),
        deploy_done=_remote_assist_deploy_status.get('complete', False)))
    r.headers['Cache-Control'] = 'no-store, no-cache, must-revalidate'
    return r


# CoTURN image is PINNED (never :latest) — supply-chain rule. Bump deliberately.
COTURN_IMAGE = 'coturn/coturn:4.18.0'   # v10.2.8 W8: SECURITY — 4.14.0 carried GHSA-m23x (pre-auth heap
# disclosure), GHSA-fvj6 (weak RNG) + five MEDIUM; all fixed by 4.17.0. Our flags include none of 4.18's
# three removals (--drop-invalid-packets, --no-dtls, --no-cli); 4.17's DTLS-opt-in / stateless-nonce
# defaults do not touch a cert-less UDP/TCP TURN.
# Fleet constant (v10.0.7): standalone Remote-Assist CoTURN ALWAYS defaults to 3479,
# never 3478 — 3478 is reserved for NetBird's TURN so the two can land on one box in
# ANY install order with zero conflicts. RA clients are explicitly told URL+port by
# the module, so the non-IANA port costs nothing. (3478 in settings still occurs
# legitimately: NetBird-shared mode, and pre-10.0.7 standalone installs.)
COTURN_DEFAULT_PORT = '3479'
# Restrict credentials to a safe charset with NO YAML/shell metacharacters. The
# values are interpolated into docker-compose.override.yml (then `docker compose up`),
# so an unvalidated newline/quote could inject arbitrary compose directives
# (privileged:true, host bind-mounts) — under the non-root/broker model `docker
# compose` is NOT gated by the broker's `docker run` mount checks, so that would be a
# real escalation. This charset makes injection impossible.
_COTURN_USER_RE = re.compile(r'^[A-Za-z0-9._@+=-]{1,64}$')
_COTURN_PASS_RE = re.compile(r'^[A-Za-z0-9._@+=!%^-]{8,128}$')
_COTURN_REALM_RE = re.compile(r'^[A-Za-z0-9.-]{1,253}$')

# ops #201: the relay's peer ACL. Remote Assist peers are phones and admin browsers, never
# the box itself, its containers or link-local/CGNAT space. These ranges are refused on
# every box; 10/8 and 192.168/16 too unless the operator turns off "Block private peers"
# (LAN-only / field-kit setups where the device and the admin share a private network).
_COTURN_ALWAYS_DENIED = ('0.0.0.0/8', '127.0.0.0/8', '169.254.0.0/16', '100.64.0.0/10',
                         '172.16.0.0/12')
_COTURN_PRIVATE_DENIED = ('10.0.0.0/8', '192.168.0.0/16')
# ops #212: a call where both ends fell back to this TURN server. Each side asks permission
# for the other's relayed address (<external IP>:500xx), and coturn maps a peer at its
# external IP to its own relay address before checking it. With no --relay-ip that address
# is 0.0.0.0 (from --listening-ip), which coturn always refuses, so these calls never
# worked, v10.2.28 included. Pin the relay address to the container's own address and allow
# exactly that one: the call goes from one relay port to the other inside the container,
# and nothing outside the coturn container (the box, its bridges, other containers) is
# reachable. The image's entrypoint expands $(...) in each argument at start ($$ is
# compose's escape), so the value follows the container across recreates.
_COTURN_SELF_ADDR = "$$(hostname -i | cut -d' ' -f1)"


def _coturn_block_private_peers(settings):
    """'Block private peers' (Remote Assist page). On unless the operator turned it off."""
    return settings.get('coturn_block_private_peers') is not False


def _coturn_peer_range(net):
    """One coturn peer-ip value. coturn takes `IP` or `IP-IP` only — a CIDR aborts
    turnserver at startup ("CIDR is not supported"), so never emit one."""
    net = ipaddress.ip_network(net, strict=False)
    if net.num_addresses == 1:
        return str(net.network_address)
    return f'{net.network_address}-{net.broadcast_address}'


def _coturn_box_addresses():
    """(own IPv4 addresses, container bridge subnets) of this box, sorted.

    Own addresses are refused as peers. Container bridges are refused whole, whatever
    pool Docker took them from — a compose network can sit in 192.168/16 or 10/8,
    which the operator may have opened with the opt-out.
    Best-effort; ([], []) on any failure."""
    own, subnets = set(), set()
    try:
        r = subprocess.run(['ip', '-o', '-4', 'addr', 'show'],
                           capture_output=True, text=True, timeout=5)
        for line in (r.stdout or '').splitlines():
            parts = line.split()
            if len(parts) < 4:
                continue
            ifname = parts[1].split('@')[0]
            for i, tok in enumerate(parts):
                if tok == 'inet' and i + 1 < len(parts):
                    try:
                        iface = ipaddress.IPv4Interface(parts[i + 1])
                    except Exception:
                        continue
                    own.add(iface.ip)
                    if ifname.startswith(_F2B_CONTAINER_IFACE_PREFIXES) and iface.network.is_private:
                        subnets.add(iface.network)
    except Exception:
        pass
    return [str(a) for a in sorted(own)], [str(n) for n in sorted(subnets)]


def _coturn_peer_acl(external_ip, block_private, own_ips=(), container_subnets=()):
    """coturn --denied-peer-ip values, widest first; an entry already inside a refused
    range is left out. The advertised --external-ip is one of the box's own addresses
    (on a NAT'd cloud box it is on no interface), so it is listed too: the box is never
    a peer. coturn swaps a peer at the external IP for its own relay address before this
    list is checked, so that entry never refuses a call between two relays — see
    _COTURN_SELF_ADDR."""
    nets = [ipaddress.ip_network(n) for n in _COTURN_ALWAYS_DENIED]
    if block_private:
        nets += [ipaddress.ip_network(n) for n in _COTURN_PRIVATE_DENIED]
    for n in list(container_subnets) + list(own_ips) + [external_ip]:
        try:
            net = ipaddress.ip_network(n, strict=False)
        except Exception:
            continue
        if net.version == 4 and not any(net.subnet_of(d) for d in nets):
            nets.append(net)
    return [_coturn_peer_range(n) for n in nets]


def _coturn_override_content(port, ip, username, password, realm, block_private,
                             own_ips=(), container_subnets=()):
    """The standalone CoTURN docker-compose.override.yml. One writer: install and the
    ops #201 converge both build it here, so a box that enabled CoTURN on an old console
    ends up byte-identical to a fresh install.

    No --no-cli: 4.18 deprecated it (it only logs an ERROR line) — the telnet CLI is off
    unless --cli is passed, and we never pass it."""
    acl = ''.join(f'      - --denied-peer-ip={d}\n'
                  for d in _coturn_peer_acl(ip, block_private, own_ips, container_subnets))
    # Inputs are charset-validated by the callers, so this interpolation cannot break the YAML.
    return f"""services:
  coturn:
    image: {COTURN_IMAGE}
    restart: unless-stopped
    ports:
      - "{port}:{port}/tcp"
      - "{port}:{port}/udp"
      - "50000-50050:50000-50050/udp"
    command:
      - -c
      - ""
      - --log-file=stdout
      - --external-ip={ip}
      - --listening-port={port}
      - --listening-ip=0.0.0.0
      - --min-port=50000
      - --max-port=50050
      - --user={username}:{password}
      - --realm={realm}
      - --no-tcp-relay
      - --no-multicast-peers
      - "--relay-ip={_COTURN_SELF_ADDR}"
      - "--allowed-peer-ip={_COTURN_SELF_ADDR}"
{acl}"""


def _coturn_parse_override(text):
    """Port / external IP / user / password / realm out of an override we wrote.
    Each value is returned only if it passes the same check install applies — so it is
    safe to write back. Missing or failing values come back as ''."""
    vals = {}
    for line in (text or '').splitlines():
        m = re.match(r'^\s*-\s*"?--(listening-port|external-ip|user|realm)=(.*?)"?\s*$', line)
        if m:
            vals.setdefault(m.group(1), m.group(2).strip())
    user, _, password = vals.get('user', '').partition(':')
    port = vals.get('listening-port', '')
    return {
        'port': port if port.isdigit() and 1024 <= int(port) <= 65535 else '',
        'ip': vals.get('external-ip', '') if _valid_core_ip(vals.get('external-ip', '')) else '',
        'username': user if _COTURN_USER_RE.match(user) else '',
        'password': password if _COTURN_PASS_RE.match(password) else '',
        'realm': vals.get('realm', '') if _COTURN_REALM_RE.match(vals.get('realm', '')) else '',
    }


_coturn_override_lock = threading.Lock()   # converge (start / RA update / setting) vs install


def _coturn_converge_override(plog=None, settings=None):
    with _coturn_override_lock:
        return _coturn_converge_override_locked(plog, settings)


def _coturn_converge_override_locked(plog=None, settings=None):
    """ops #201: bring an existing standalone CoTURN onto COTURN_IMAGE and the current
    flags, then recreate only the coturn service.

    The pin and flags used to reach a box only when the operator clicked Install, so
    console and Remote Assist updates never moved an existing CoTURN forward. Runs on
    console start and after a Remote Assist update. Port,
    user and realm are kept from the override itself (settings as fallback).

    Returns 'absent' | 'netbird' | 'current' | 'rewritten' | 'skipped' | 'failed'."""
    log = plog or (lambda m: print(f'Startup migration: {m}', flush=True))
    if settings is None:
        settings = load_settings()
    if settings.get('netbird_coturn_in_use'):
        return 'netbird'                  # NetBird's coturn: not our file, not our flags
    ra_dir = REMOTE_ASSIST_INSTALL_DIR
    path = os.path.join(ra_dir, 'docker-compose.override.yml')
    if not os.path.isfile(path):
        return 'absent'
    with open(path) as f:
        old = f.read()
    cur = _coturn_parse_override(old)
    sport = str(settings.get('coturn_port') or '')
    port = cur['port'] or (sport if sport.isdigit() and 1024 <= int(sport) <= 65535 else '')
    ip = cur['ip'] or (settings.get('coturn_ip') if _valid_core_ip(settings.get('coturn_ip')) else '')
    user = cur['username'] or (settings.get('coturn_username') or '')
    password = cur['password'] or (settings.get('coturn_password') or '')
    realm = cur['realm'] or (settings.get('fqdn') or '').strip()
    if not _COTURN_REALM_RE.match(realm):
        realm = 'remote-assist'           # clients take the realm from the server's challenge
    if not (port and ip and _COTURN_USER_RE.match(user) and _COTURN_PASS_RE.match(password)):
        log('CoTURN override not recognised (port/IP/user unreadable) — left as is; '
            'reinstall CoTURN from the Remote Assist page to get the security update')
        return 'skipped'
    own_ips, subnets = _coturn_box_addresses()
    new = _coturn_override_content(port, ip, user, password, realm,
                                   _coturn_block_private_peers(settings), own_ips, subnets)
    if new == old:
        return 'current'
    with open(path, 'w') as f:
        f.write(new)
    r = subprocess.run(_remote_assist_compose_cmd(ra_dir, '-f', path, 'up', '-d', '--no-deps', 'coturn'),
                       cwd=ra_dir, capture_output=True, text=True, timeout=600)
    if r.returncode != 0:
        # Put the old file back so the next start tries again (a rewritten file would
        # read as 'current' and never be retried). compose pulls before it stops the old
        # container, so a failed pull leaves the old one running.
        with open(path, 'w') as f:
            f.write(old)
        _lines = [l.strip() for l in ((r.stderr or '') + '\n' + (r.stdout or '')).splitlines() if l.strip()]
        log(f'CoTURN security update failed, will retry on next start: {(_lines[-1] if _lines else "docker compose failed")[:300]}')
        return 'failed'
    log(f'CoTURN updated to {COTURN_IMAGE} with the relay peer restrictions '
        f'(private peers {"blocked" if _coturn_block_private_peers(settings) else "allowed"})')
    return 'rewritten'


def _startup_converge_coturn():
    try:
        _coturn_converge_override()
    except Exception as e:
        print(f'Startup migration: CoTURN converge error (non-fatal): {e}', flush=True)


def _netbird_coturn_status():
    """(has_netbird, coturn_container, turnserver_conf_host_path).

    Detects a LEGACY/classic NetBird install that runs a SEPARATE coturn
    container with a bind-mounted /etc/turnserver.conf — that conf can take an
    extra static `user=` line for Remote Assist (Mike/cfd2474, PR #49). The
    infra-TAK NetBird hub (all-in-one netbird-server image) embeds its
    STUN/TURN, so it returns (True, None, None) → standalone CoTURN on an
    alternate port is the path there."""
    import subprocess as _sp
    has_netbird, container, conf_path = False, None, None
    try:
        r = _sp.run(['docker', 'ps', '--format', '{{.Names}}'],
                    capture_output=True, text=True, timeout=10)
        names = [c.strip() for c in (r.stdout or '').splitlines() if c.strip()]
        has_netbird = any('netbird' in c.lower() for c in names)
        if has_netbird:
            for c in names:
                cl = c.lower()
                # Exclude our own Remote Assist coturn ("remote_assist"/"remote-assist"
                # compose project names) — only a coturn that belongs to NetBird counts.
                if 'coturn' in cl and 'remote' not in cl and 'assist' not in cl and 'infratak' not in cl:
                    container = c
                    break
            if container:
                ri = _sp.run(['docker', 'inspect', container],
                             capture_output=True, text=True, timeout=10)
                data = json.loads(ri.stdout or '[]')
                for mount in (data[0].get('Mounts', []) if data else []):
                    if mount.get('Destination') == '/etc/turnserver.conf':
                        conf_path = mount.get('Source')
                        break
    except Exception:
        pass
    return has_netbird, container, conf_path


@app.route('/api/remote-assist/coturn/configure-netbird', methods=['POST'])
@login_required
def remote_assist_coturn_configure_netbird():
    """Shared mode: append a DEDICATED static `user=` credential to a legacy
    NetBird coturn's turnserver.conf instead of running a second TURN server.
    Never reuses NetBird's own TURN secret — WebRTC creds are browser-visible."""
    import subprocess as _sp
    data = request.get_json(silent=True) or {}
    username = (data.get('username') or '').strip()
    password = (data.get('password') or '').strip()
    # Same charsets as the standalone install: these values land in
    # turnserver.conf, where an embedded newline would inject arbitrary
    # coturn directives (listening-ip, cert paths, ...).
    if not _COTURN_USER_RE.match(username):
        return jsonify({'success': False, 'error': 'Username must be 1–64 chars: letters, digits, . _ @ + = -'})
    if not _COTURN_PASS_RE.match(password):
        return jsonify({'success': False, 'error': 'Password must be 8–128 chars: letters, digits, . _ @ + = ! % ^ - (no spaces/quotes).'})
    has_nb, nb_container, conf_path = _netbird_coturn_status()
    if not (has_nb and nb_container and conf_path):
        return jsonify({'success': False, 'error': 'No NetBird coturn with a turnserver.conf mount found on this box.'})
    settings = load_settings()
    ip = (settings.get('server_ip') or '').strip()
    if not _valid_core_ip(ip):
        return jsonify({'success': False, 'error': 'Server public IP is not set — configure it on the Settings page first.'})
    try:
        # Never default to '' on a read failure — a blind write here would
        # REPLACE NetBird's whole turnserver.conf with our single line.
        try:
            conf = _read_priv(conf_path)
        except Exception as re_err:
            return jsonify({'success': False, 'error': f'Could not read turnserver.conf ({str(re_err)[:120]}) — aborting without changes.'})
        user_line = f'user={username}:{password}'
        lines = conf.splitlines()
        # Rotation must REVOKE: drop the previously-appended infra-TAK credential
        # (tracked in settings) so re-configuring doesn't strand old creds live.
        prev_user = settings.get('coturn_username', '')
        prev_pass = settings.get('coturn_password', '')
        prev_line = f'user={prev_user}:{prev_pass}' if prev_user else None
        new_lines = [l for l in lines if not (prev_line and l.strip() == prev_line and l.strip() != user_line)]
        if user_line not in [l.strip() for l in new_lines]:
            new_lines.append(user_line)
        if new_lines != lines:
            _write_priv(conf_path, '\n'.join(new_lines).rstrip('\n') + '\n')
            _sp.run(['docker', 'restart', nb_container], capture_output=True, timeout=90)
        settings['coturn_installed'] = True
        settings['coturn_username'] = username
        settings['coturn_password'] = password
        settings['coturn_ip'] = ip
        settings['coturn_port'] = '3478'
        settings['netbird_coturn_in_use'] = True
        save_settings(settings)
        return jsonify({'success': True})
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)[:300]})


@app.route('/api/remote-assist/coturn/install', methods=['POST'])
@login_required
def remote_assist_coturn_install():
    import subprocess as _sp
    data = request.get_json(silent=True) or {}
    username = (data.get('username') or '').strip()
    password = (data.get('password') or '').strip()
    ip = (data.get('ip') or '').strip()
    port = str(data.get('port') or COTURN_DEFAULT_PORT).strip() or COTURN_DEFAULT_PORT
    if not username or not password or not ip:
        return jsonify({'success': False, 'error': 'All fields are required.'})
    if not _COTURN_USER_RE.match(username):
        return jsonify({'success': False, 'error': 'Username must be 1–64 chars: letters, digits, . _ @ + = -'})
    if not _COTURN_PASS_RE.match(password):
        return jsonify({'success': False, 'error': 'Password must be 8–128 chars: letters, digits, . _ @ + = ! % ^ - (no spaces/quotes).'})
    if not _valid_core_ip(ip):
        return jsonify({'success': False, 'error': 'Public IP must be a valid IPv4 address.'})
    # Port is interpolated into the compose override — digits only, sane range.
    if not port.isdigit() or not (1024 <= int(port) <= 65535):
        return jsonify({'success': False, 'error': 'Port must be a number between 1024 and 65535 (default 3479).'})

    ra_dir = REMOTE_ASSIST_INSTALL_DIR
    if not os.path.exists(ra_dir):
        return jsonify({'success': False, 'error': 'EUD Remote Assist is not installed.'})
    # NetBird also serves STUN/TURN on 3478, so publishing 3478 next to it fails
    # ("port is already allocated"). Guide instead of dead-ending: legacy NetBird
    # (separate coturn container) → the Configure-NetBird flow; the all-in-one
    # hub → pick an alternate port (Mike/cfd2474, PR #49).
    if port == '3478':
        try:
            _nb_has, _nb_ctr, _nb_conf = _netbird_coturn_status()
            if _nb_has:
                if _nb_ctr and _nb_conf:
                    return jsonify({'success': False, 'error': 'Port 3478 is used by NetBird\'s coturn. Use "Configure NetBird CoTURN" to add Remote Assist credentials to it instead of running a second TURN server — or choose a different port (e.g. 3479).'})
                return jsonify({'success': False, 'error': 'Port 3478 is used by NetBird (it provides STUN/TURN). Choose a different port (e.g. 3479) to run CoTURN alongside it.'})
        except Exception:
            pass
    _settings = load_settings()
    fqdn = (_settings.get('fqdn') or 'remote-assist').strip()
    if not _COTURN_REALM_RE.match(fqdn):
        fqdn = 'remote-assist'
    override_path = os.path.join(ra_dir, 'docker-compose.override.yml')
    _own_ips, _subnets = _coturn_box_addresses()
    override_content = _coturn_override_content(port, ip, username, password, fqdn,
                                                _coturn_block_private_peers(_settings),
                                                _own_ips, _subnets)
    with _coturn_override_lock:
        try:
            with open(override_path, 'w') as f:
                f.write(override_content)
            r = _sp.run(_remote_assist_compose_cmd(ra_dir, '-f', override_path, 'up', '-d', 'coturn'),
                        cwd=ra_dir, capture_output=True, text=True, timeout=300)
            if r.returncode != 0:
                # docker compose writes pull PROGRESS to stderr, so the head of stderr is
                # noise — surface the actual failure (last Error/failed line, e.g. a port
                # conflict), and roll back the half-written override so a retry is clean.
                _out = ((r.stderr or '') + '\n' + (r.stdout or '')).strip()
                _lines = [l.strip() for l in _out.splitlines() if l.strip()]
                _err = next((l for l in reversed(_lines)
                             if any(k in l.lower() for k in ('error', 'failed', 'allocated', 'in use'))),
                            (_lines[-1] if _lines else 'docker compose failed'))
                try:
                    _sp.run(_remote_assist_compose_cmd(ra_dir, '-f', override_path, 'rm', '-sfv', 'coturn'),
                            cwd=ra_dir, capture_output=True, timeout=60)
                    os.remove(override_path)
                except Exception:
                    pass
                if 'allocated' in _err.lower() or 'in use' in _err.lower():
                    _err = f'Port conflict: {port} is already in use by another service — pick a different port (e.g. 3479) and try again. ({_err})'
                return jsonify({'success': False, 'error': _err[:400]})
            settings = load_settings()
            settings['coturn_installed'] = True
            settings['coturn_username'] = username
            settings['coturn_password'] = password
            settings['coturn_ip'] = ip
            settings['coturn_port'] = port
            settings['netbird_coturn_in_use'] = False
            save_settings(settings)
            return jsonify({'success': True})
        except Exception as e:
            return jsonify({'success': False, 'error': str(e)[:300]})


@app.route('/api/remote-assist/coturn/uninstall', methods=['POST'])
@login_required
def remote_assist_coturn_uninstall():
    _denied = _require_admin_password()
    if _denied:
        return _denied
    import subprocess as _sp
    ra_dir = REMOTE_ASSIST_INSTALL_DIR
    override_path = os.path.join(ra_dir, 'docker-compose.override.yml')
    try:
        settings = load_settings()
        if settings.get('netbird_coturn_in_use'):
            # Shared mode: our only footprint is the appended user= line in
            # NetBird's turnserver.conf — remove it, never touch NetBird itself.
            _has_nb, nb_container, conf_path = _netbird_coturn_status()
            user_line = f"user={settings.get('coturn_username', '')}:{settings.get('coturn_password', '')}"
            if conf_path and settings.get('coturn_username'):
                try:
                    conf = _read_priv(conf_path)
                    new_conf = '\n'.join(l for l in conf.splitlines() if l.strip() != user_line)
                    if new_conf != conf:
                        _write_priv(conf_path, new_conf.rstrip('\n') + '\n')
                        if nb_container:
                            _sp.run(['docker', 'restart', nb_container], capture_output=True, timeout=90)
                except Exception:
                    pass
        elif os.path.exists(override_path):
            _sp.run(_remote_assist_compose_cmd(ra_dir, '-f', override_path, 'rm', '-s', '-v', '-f', 'coturn'),
                    cwd=ra_dir, capture_output=True, text=True, timeout=120)
            os.remove(override_path)
        for k in ('coturn_installed', 'coturn_username', 'coturn_password', 'coturn_ip',
                  'coturn_port', 'netbird_coturn_in_use'):
            settings.pop(k, None)
        save_settings(settings)
        return jsonify({'success': True})
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)[:300]})


@app.route('/api/remote-assist/coturn/peer-policy', methods=['POST'])
@login_required
def remote_assist_coturn_peer_policy():
    """ops #201 "Block private peers". Turning it OFF loosens the relay, so that
    direction asks for the admin password, like uninstall."""
    data = request.get_json(silent=True) or {}
    block = data.get('block_private')
    if not isinstance(block, bool):
        return jsonify({'success': False, 'error': 'block_private must be true or false.'})
    if not block:
        _denied = _require_admin_password(data)
        if _denied:
            return _denied
    try:
        settings = load_settings()
        prev = settings.get('coturn_block_private_peers')
        settings['coturn_block_private_peers'] = block
        save_settings(settings)
        result = _coturn_converge_override(plog=lambda m: print(f'CoTURN: {m}', flush=True),
                                           settings=settings)
        if result in ('failed', 'skipped'):
            # The running CoTURN did not change, so neither does the setting.
            settings = load_settings()
            if prev is None:
                settings.pop('coturn_block_private_peers', None)
            else:
                settings['coturn_block_private_peers'] = prev
            save_settings(settings)
            return jsonify({'success': False, 'error': 'CoTURN could not be restarted with the new setting, so nothing changed — see the console log.'})
        return jsonify({'success': True, 'result': result})
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)[:300]})


