@app.route('/api/fail2ban/takserver/watching')
@login_required
def fail2ban_tak_watching_api():
    """Return IPs seen in the takserver jail (found but not currently banned).

    fail2ban logs Found via fail2ban.filter and Ban/Unban via fail2ban.actions.
    We scan the whole log, track ban/unban state per IP, and return IPs that
    have found entries but are not currently banned. No time filtering — fail2ban
    is the authoritative source for 'currently failed' count; we just reveal which IPs.
    """
    import re as _re_watch
    log_path = '/var/log/fail2ban.log'
    result = []
    try:
        # Found: fail2ban.filter  — "2026-05-02 21:36:29,811 fail2ban.filter         [PID]: INFO    [takserver] Found 1.2.3.4 - ..."
        # Ban/Unban: fail2ban.actions
        found_re = _re_watch.compile(r'\[takserver\] Found (\d[\d.:a-fA-F]+)')
        ban_re   = _re_watch.compile(r'\[takserver\] Ban (\d[\d.:a-fA-F]+)')
        unban_re = _re_watch.compile(r'\[takserver\] Unban (\d[\d.:a-fA-F]+)')
        ts_re    = _re_watch.compile(r'^(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2})')

        found_data  = {}  # ip -> {'count': N, 'last_seen': str}
        banned_ips  = set()

        with open(log_path) as _lf:
            for line in _lf:
                m = ban_re.search(line)
                if m:
                    banned_ips.add(m.group(1))
                    continue
                m = unban_re.search(line)
                if m:
                    banned_ips.discard(m.group(1))
                    continue
                m = found_re.search(line)
                if m:
                    ip = m.group(1)
                    ts_m = ts_re.match(line)
                    ts = ts_m.group(1) if ts_m else ''
                    if ip not in found_data:
                        found_data[ip] = {'count': 0, 'last_seen': ts}
                    found_data[ip]['count'] += 1
                    found_data[ip]['last_seen'] = ts

        for ip, data in found_data.items():
            if ip not in banned_ips:
                result.append({
                    'ip':        ip,
                    'attempts':  data['count'],
                    'last_seen': data['last_seen'],
                })
        result.sort(key=lambda x: x['attempts'], reverse=True)
    except FileNotFoundError:
        pass
    except Exception as e:
        return jsonify({'ok': False, 'error': str(e)[:200], 'watching': []}), 500
    return jsonify({'ok': True, 'watching': result})


def _f2b_get_version():
    """Return installed fail2ban version string, or None."""
    try:
        r = subprocess.run(_sudo_wrap(['fail2ban-client', '--version']), capture_output=True, text=True, timeout=5)
        lines = r.stdout.strip().splitlines()
        return lines[0] if lines else None
    except Exception:
        return None

def _f2b_get_available_version():
    """Return the apt candidate version for fail2ban, or None."""
    try:
        r = subprocess.run(['apt-cache', 'policy', 'fail2ban'], capture_output=True, text=True, timeout=8)
        for line in r.stdout.splitlines():
            line = line.strip()
            if line.startswith('Candidate:'):
                return line.split(':', 1)[1].strip()
    except Exception:
        pass
    return None

def _f2b_console_client_ip():
    """The address the operator is actually reaching the console from.

    `request.remote_addr` is the PROXY when the console sits behind Caddy (which is
    the normal deployment), so it would report 127.0.0.1 and we would tell every
    operator they are safe. Prefer the forwarded chain's first hop."""
    try:
        xff = (request.headers.get('X-Forwarded-For') or '').split(',')[0].strip()
        if xff:
            ipaddress.ip_address(xff)
            return xff
    except Exception:
        pass
    try:
        ra = (request.remote_addr or '').strip()
        ipaddress.ip_address(ra)
        return ra
    except Exception:
        return ''


def _f2b_ignoreip_explained():
    """ignoreip broken into labelled groups, plus whether the CALLER's own address
    is covered.

    `ignoreip` is one opaque space-separated string, so nobody can tell what is
    protected or why — and the one entry that matters most (the management tunnel)
    is invisible. Worse, an operator reaching the box by a path we do NOT
    auto-detect (a jump host, a third-party VPN we deliberately do not trust) has
    no way to know they are one ban away from losing the box. Say it plainly."""
    groups = []

    def add(label, cidrs, why):
        cidrs = [c for c in (cidrs or []) if c]
        if cidrs:
            groups.append({'label': label, 'cidrs': cidrs, 'why': why})

    add('Localhost', ['127.0.0.1/8', '::1'], 'this box talking to itself')
    add("This box's network", _f2b_local_subnets(),
        'the LAN or VNet this box sits on — stops an upstream gateway or load balancer being banned')
    add('Management tunnel', _f2b_mgmt_tunnel_subnets(),
        'the WireGuard / NetBird link this box is managed through — a ban here blocks every port '
        'and locks you out of a box you may not be able to reach any other way')
    add('Added by you', _f2b_fleet_ignore_cidrs(),
        "from 'fail2ban_ignore_cidrs' in settings")

    client = _f2b_console_client_ip()
    covered, matched = None, ''
    if client:
        try:
            addr = ipaddress.ip_address(client)
            for g in groups:
                for c in g['cidrs']:
                    try:
                        if addr in ipaddress.ip_network(c, strict=False):
                            covered, matched = True, f"{c} ({g['label']})"
                            break
                    except (ValueError, TypeError):
                        continue      # v4/v6 mismatch or malformed entry
                if covered:
                    break
            if covered is None:
                covered = False
        except ValueError:
            covered = None
    return {'groups': groups, 'client_ip': client, 'client_covered': covered,
            'client_matched': matched}


