def _f2b_recidive_enabled():
    return os.path.exists('/etc/fail2ban/jail.d/infratak-recidive.conf')

def _f2b_rewrite_all_jails():
    """Re-derive and re-write every currently-enabled infra-TAK jail from its stored
    thresholds. Used after the fleet trusted-CIDR whitelist changes so the new value
    propagates to ALL jails at once (each writer re-reads settings via
    _f2b_trusted_ignoreip). Returns the list of jails rewritten."""
    done = []
    if _f2b_authentik_jail_enabled():
        c = _f2b_read_jail_config()
        _f2b_write_jail_config(c['maxretry'], c['findtime'], c['bantime'], _f2b_operator_extra(c.get('ignoreip', '')))
        done.append('authentik')
    if _f2b_tak_jail_enabled():
        c = _f2b_read_tak_jail_config()
        _f2b_write_tak_jail_config(c['maxretry'], c['findtime'], c['bantime'], _f2b_operator_extra(c.get('ignoreip', '')))
        done.append('takserver')
    if _f2b_ssh_jail_enabled():
        c = _f2b_read_ssh_jail_config()
        _f2b_write_ssh_jail_config(c['maxretry'], c['findtime'], c['bantime'], _f2b_operator_extra(c.get('ignoreip', '')))
        done.append('sshd')
    if _f2b_mediamtx_jail_enabled():
        c = _f2b_read_mediamtx_jail_config()
        _f2b_write_mediamtx_jail(c['maxretry'], c['findtime'], c['bantime'], _f2b_operator_extra(c.get('ignoreip', '')))
        done.append('mediamtx-rtsp')
    if _f2b_portal_jail_enabled():
        c = _f2b_read_portal_jail_config()
        _f2b_write_portal_jail(c['maxretry'], c['findtime'], c['bantime'], _f2b_operator_extra(c.get('ignoreip', '')))
        done.append('takportal')
    if _f2b_recidive_enabled():
        c = _f2b_read_recidive_config()
        _f2b_write_recidive_config(c['maxretry'], c['findtime'])
        done.append('recidive')
    return done


@app.route('/api/fail2ban/trusted-cidrs', methods=['GET', 'POST'])
@login_required
def fail2ban_trusted_cidrs_api():
    """Fleet-wide trusted-upstream whitelist (settings 'fail2ban_ignore_cidrs').
    On a gateway/proxy/VNet-fronted deploy, ALL inbound traffic appears to come from
    the upstream's handful of IPs; a jail trip then bans the gateway itself and every
    vhost 502s ([[fail2ban-bans-azure-gateway]]). Operators add the gateway subnet
    here once and it is baked into every jail's ignoreip — and re-baked on every jail
    regen, so a MediaMTX redeploy can never re-expose the box."""
    if request.method == 'GET':
        return jsonify({
            'ok': True,
            'cidrs': _f2b_fleet_ignore_cidrs(),
            'local_subnets': _f2b_local_subnets(),
            'effective': _f2b_trusted_ignoreip(),
        })
    data = request.get_json(silent=True) or {}
    raw = str(data.get('cidrs', '') or '').replace(',', ' ').split()
    cleaned = []
    for c in raw:
        c = c.strip()
        if not c:
            continue
        try:
            ipaddress.ip_network(c, strict=False)  # validate CIDR / bare IP
        except Exception:
            return jsonify({'ok': False, 'error': f'Invalid CIDR/IP: {c}'}), 400
        if c not in cleaned:
            cleaned.append(c)
    s = load_settings()
    s['fail2ban_ignore_cidrs'] = ' '.join(cleaned)
    save_settings(s)
    rewritten = _f2b_rewrite_all_jails()
    try:
        subprocess.run(_sudo_wrap(['fail2ban-client', 'reload']), capture_output=True, timeout=15)
    except Exception:
        pass
    return jsonify({'ok': True, 'cidrs': cleaned, 'rewritten': rewritten,
                    'effective': _f2b_trusted_ignoreip()})

def _f2b_read_recidive_config():
    cfg = {'maxretry': 3, 'findtime': 86400}
    path = '/etc/fail2ban/jail.d/infratak-recidive.conf'
    if not os.path.exists(path):
        return cfg
    try:
        with open(path) as _f:
            for line in _f:
                line = line.strip()
                for key in ('maxretry', 'findtime'):
                    if line.startswith(key):
                        try: cfg[key] = int(line.split('=')[1].strip())
                        except Exception: pass
    except Exception:
        pass
    return cfg

# v10.1.70 W1.4: recidive ban duration — FLEET CONSTANT, deliberately finite.
#
# This jail bans on ALL ports (see _f2b_banaction), so a banned address loses :5001 —
# the console you would use to unban yourself — as well as :22. At bantime = -1 that
# state was PERMANENT and, for a customer who cannot SSH in from another address, it
# had no recovery path at all: the product could put a box beyond its owner's reach
# and keep it there. Three sshd bans inside findtime is ordinary NAT behavior (an
# office where three people mistype a password), not proof of an attacker.
#
# 7 days is still severe for a genuine repeat offender and it bounds the damage when
# we are wrong. Operator decision, 2026-09-12. Existing permanent bans are NOT
# rewritten — fail2ban stores bantime per ban — so they stay until unbanned from the
# console; only new bans take this. A fleet CONSTANT, never operator-tunable, per the
# fleet-uniform rule: the recovery floor is not something that should drift per box.
_F2B_RECIDIVE_BANTIME = 604800   # 7 days, in seconds


def _f2b_write_recidive_config(maxretry, findtime):
    """Write infratak-recidive jail and ensure fail2ban persistence."""
    _makedirs_priv('/etc/fail2ban/jail.d', exist_ok=True)
    jail_conf = (
        "[recidive]\n"
        "enabled  = true\n"
        "filter   = recidive\n"
        "logpath  = /var/log/fail2ban.log\n"
        f"bantime  = {_F2B_RECIDIVE_BANTIME}\n"
        f"findtime = {findtime}\n"
        f"maxretry = {maxretry}\n"
        # v10.1.30: never escalate a MEDIA ban into an all-ports one. recidive matches
        # `Ban <HOST>` from EVERY jail, bans for -1 (permanent) and uses the all-ports
        # action — so without this line the media-only scoping of mediamtx-rtsp is
        # undone after `maxretry` bans, and a repeat video offender loses TAK Server
        # and the console permanently. That is the exact incident this release exists
        # to fix (Ryan F., 2026-08-11), just delayed by three bans — and it is most
        # reachable in his own situation, a phone behind carrier NAT sharing one
        # public IP. Repeat media abuse keeps earning media-scoped bans instead.
        # Caught by /security-review before ship, 2026-08-13.
        # 2026-10-21: the same for takserver bans, now TAK-ports-only. Its commonest
        # repeat offender is an operator's own phone with an old certificate, which
        # re-trips every hour; escalating that cost the admin the console for 7 days.
        "ignoreregex = \\[(?:mediamtx-rtsp|takserver)\\] Ban\n"
        f"ignoreip = {_f2b_trusted_ignoreip()}\n"
        f"action   = {_f2b_banaction()}\n"
    )
    _write_priv('/etc/fail2ban/jail.d/infratak-recidive.conf', jail_conf)
    # The recidive jail reads fail2ban's own log; pre-create it so the jail loads on
    # the very first start (on RHEL fail2ban never creates it until a clean start —
    # chicken/egg). Harmless no-op where the file already exists (e.g. Debian).
    try:
        subprocess.run(_sudo_wrap(['touch', '/var/log/fail2ban.log']), capture_output=True, timeout=10)
    except Exception:
        pass
    # NOTE: _f2b_write_recidive_config takes no ignoreip arg — the recidive jail's
    # ignoreip is always the fleet trusted set (no per-jail operator override needed).
    # Ensure fail2ban SQLite persistence so permanent bans survive restarts
    local_path = '/etc/fail2ban/fail2ban.local'
    db_line = 'dbfile = /var/lib/fail2ban/fail2ban.sqlite3\n'
    purge_line = 'dbpurgeage = 0\n'
    try:
        # v10.0.5 non-root: /etc/fail2ban/fail2ban.local is root-owned — read+append via broker.
        try:
            existing = _read_priv(local_path)
        except Exception:
            existing = ''
        if 'dbfile' not in existing:
            addition = ('' if existing.strip() else '[Definition]\n') + db_line + purge_line
            _write_priv(local_path, existing + addition)
    except Exception:
        pass


@app.route('/api/fail2ban/trusted-cidrs/add-mine', methods=['POST'])
@login_required
def fail2ban_add_my_ip_api():
    """v10.1.70 W1.1: one-click 'never ban the address I am reaching the console from'.

    The fail2ban page has warned for releases that the caller's address is not on the
    never-ban list and that a ban there costs them every port on the box — but the only
    way to act on that warning was to retype the address into the trusted-CIDR field.
    That is why the workstation IP was present on two boxes and missing on a third.

    Deliberately separate from the trusted-cidrs POST, which REPLACES the whole list: a
    one-click control must not be able to drop entries the operator added. This only
    ever appends, and it takes no IP from the request body — the address comes from the
    connection itself, so a caller cannot use it to whitelist somebody else.
    """
    if not _f2b_is_available():
        return jsonify({'ok': False, 'error': 'fail2ban not installed'}), 400
    ip = _f2b_console_client_ip()
    if not ip:
        return jsonify({'ok': False, 'error': 'Could not determine your address'}), 400
    try:
        ipaddress.ip_address(ip)
    except ValueError:
        return jsonify({'ok': False, 'error': f'Not a usable address: {ip[:40]}'}), 400

    cidrs = _f2b_fleet_ignore_cidrs()
    if ip in cidrs:
        return jsonify({'ok': True, 'ip': ip, 'already': True,
                        'cidrs': cidrs, 'effective': _f2b_trusted_ignoreip()})
    cidrs.append(ip)
    s_cfg = load_settings()
    s_cfg['fail2ban_ignore_cidrs'] = ' '.join(cidrs)
    # An explicit click counts as the seed — do not let an automatic seed add a second,
    # different address later (e.g. one visit from another network).
    s_cfg['fail2ban_ignore_seeded'] = True
    save_settings(s_cfg)
    rewritten = _f2b_rewrite_all_jails()
    try:
        subprocess.run(_sudo_wrap(['fail2ban-client', 'reload']), capture_output=True, timeout=15)
    except Exception:
        pass
    print(f"fail2ban: {ip} added to the never-ban list by operator click; "
          f"rewrote {rewritten}", flush=True)
    return jsonify({'ok': True, 'ip': ip, 'already': False, 'cidrs': cidrs,
                    'rewritten': rewritten, 'effective': _f2b_trusted_ignoreip()})


@app.route('/api/fail2ban/recidive/status')
@login_required
def fail2ban_recidive_status_api():
    if not _f2b_is_available():
        return jsonify({'available': False, 'error': 'fail2ban not installed'})
    enabled = _f2b_recidive_enabled()
    status = {
        'available': True,
        'jail_enabled': enabled,
        'jail_config': _f2b_read_recidive_config(),
        # v10.1.70 W1.3: the UI called every recidive ban "Permanent" and drew it as an
        # infinity badge. Report the real duration so the card cannot drift from the jail.
        'bantime': _F2B_RECIDIVE_BANTIME,
        'bantime_label': '%d days' % (_F2B_RECIDIVE_BANTIME // 86400),
        'currently_banned': 0, 'total_banned': 0, 'banned_ips': [],
    }
    if enabled:
        try:
            r = subprocess.run(_sudo_wrap(['fail2ban-client', 'status', 'recidive']),
                               capture_output=True, text=True, timeout=10)
            status.update(_f2b_parse_status(r.stdout))
        except Exception as e:
            status['error'] = str(e)[:200]
        status['not_enforced'] = _f2b_recidive_not_enforced(status['banned_ips'])
    return jsonify(status)


def _f2b_ufw_blocked_ips():
    """Addresses ufw currently REJECTs/DENYs as a source, or None when that can't be read
    (no ufw: RHEL runs recidive on iptables-allports, which the broker cannot list)."""
    if _distro_family() == 'rhel':
        return None
    try:
        r = subprocess.run(_sudo_wrap(['ufw', 'status']), capture_output=True, text=True, timeout=15)
    except Exception:
        return None
    if r.returncode != 0 or 'Status:' not in r.stdout:
        return None
    blocked = set()
    for line in r.stdout.splitlines():
        # "Anywhere                   REJECT      203.0.113.50   # comment"
        m = re.match(r'^\S.*?\s(?:REJECT|DENY)(?: IN)?\s+(\S+)', line)
        if m:
            blocked.add(m.group(1))
    return blocked


def _f2b_recidive_not_enforced(banned_ips):
    """Recidive bans the firewall is NOT actually enforcing. fail2ban keeps its own ban list
    (and restores it from its database), so when the ufw rule is removed by hand the panel
    kept listing an address as banned for days while it could connect normally: test12,
    2026-10-21, the admin's own home address listed since Oct 19 with no rule behind it."""
    if not banned_ips:
        return []
    blocked = _f2b_ufw_blocked_ips()
    if blocked is None:
        return []
    return [ip for ip in banned_ips if ip not in blocked]


@app.route('/api/fail2ban/recidive/config', methods=['POST'])
@login_required
def fail2ban_recidive_config_api():
    if not _f2b_is_available():
        return jsonify({'ok': False, 'error': 'fail2ban not installed'}), 400
    data = request.get_json(force=True) or {}
    if not bool(data.get('enabled', False)):
        path = '/etc/fail2ban/jail.d/infratak-recidive.conf'
        subprocess.run(_sudo_wrap(['rm', '-f', path]), capture_output=True)  # v10.0.5 non-root
        subprocess.run(_sudo_wrap(['fail2ban-client', 'reload']), capture_output=True, timeout=15)
        return jsonify({'ok': True, 'enabled': False})
    try:
        maxretry = max(2, min(20,  int(data.get('maxretry', 3))))
        findtime = max(3600, min(2592000, int(data.get('findtime', 86400))))
    except (ValueError, TypeError) as e:
        return jsonify({'ok': False, 'error': f'Invalid value: {e}'}), 400
    # v10.1.70 W1.1: enabling recidive is the moment the operator turns on the jail that
    # bans every port — seed their own address before it can catch them. Seed-once, so
    # toggling the jail off and on does not re-add an address they removed on purpose.
    _seeded, _seed_why = _f2b_seed_console_client_ignore(
        _f2b_console_client_ip(), 'recidive jail enabled')
    try:
        _f2b_write_recidive_config(maxretry, findtime)
        # If we just seeded, the address has to reach EVERY jail, not only this one.
        # The lockout chain starts at sshd: three sshd bans inside findtime are what
        # promote an address to recidive in the first place. Seeding recidive alone
        # would leave the escalation path fully intact and only soften the last step.
        if _seeded:
            _f2b_rewrite_all_jails()
        subprocess.run(_sudo_wrap(['fail2ban-client', 'reload']), capture_output=True, timeout=15)
        return jsonify({'ok': True, 'enabled': True, 'maxretry': maxretry, 'findtime': findtime,
                        'bantime': _F2B_RECIDIVE_BANTIME,
                        'seeded_client': _seeded, 'seed_detail': _seed_why})
    except Exception as e:
        return jsonify({'ok': False, 'error': str(e)[:200]}), 500


@app.route('/api/fail2ban/recidive/unban', methods=['POST'])
@login_required
def fail2ban_recidive_unban_api():
    if not _f2b_is_available():
        return jsonify({'ok': False, 'error': 'fail2ban not installed'}), 400
    data = request.get_json(force=True) or {}
    ip = str(data.get('ip', '')).strip()
    if not ip or not _VALID_IP_RE.match(ip):
        return jsonify({'ok': False, 'error': 'Invalid IP address'}), 400
    try:
        r = subprocess.run(_sudo_wrap(['fail2ban-client', 'set', 'recidive', 'unbanip', ip]),
                           capture_output=True, text=True, timeout=10)
        if r.returncode == 0:
            return jsonify({'ok': True, 'ip': ip})
        return jsonify({'ok': False, 'error': r.stderr.strip()[:200] or 'Unban failed'}), 500
    except Exception as e:
        return jsonify({'ok': False, 'error': str(e)[:200]}), 500


# fail2ban install status dict (tracks background install progress)
_f2b_install_status = {'running': False, 'log': [], 'done': False, 'ok': False}

def _fail2ban_install_db_node_step(plog):
    """Wrapper so the install route and the dedicated route share one implementation."""
    if not _f2b_db_node_cfg():
        return True
    ok, _why = _f2b_install_db_node(plog)
    return ok


@app.route('/api/fail2ban/db-node/install', methods=['POST'])
@login_required
def fail2ban_db_node_install_api():
    """Protect the database node of a two-server deployment.

    Separate from /api/fail2ban/install on purpose: that route refuses with 400 once
    the CONSOLE host has fail2ban, which is exactly the state every existing split
    build is in — so there was no way to reach the database node at all. This is the
    one-click fix for a box that has been exposed since it was built.
    """
    if not _f2b_db_node_cfg():
        return jsonify({'ok': False, 'error': 'Not a two-server deployment'}), 400
    log = []
    def _plog(msg):
        log.append(msg)
        print(f"fail2ban db-node: {msg}", flush=True)
    try:
        ok, why = _f2b_install_db_node(_plog)
        return jsonify({'ok': ok, 'result': why, 'log': log,
                        'state': _f2b_db_node_state()})
    except Exception as e:
        log.append(f"ERROR: {e}")
        return jsonify({'ok': False, 'error': str(e)[:300], 'log': log}), 500


@app.route('/api/fail2ban/db-node/status')
@login_required
def fail2ban_db_node_status_api():
    """Read-only state of the split-deployment database node's brute-force protection."""
    return jsonify(_f2b_db_node_state())


@app.route('/api/fail2ban/install', methods=['POST'])
@login_required
def fail2ban_install_api():
    """Install fail2ban via the Marketplace. Runs in background; poll /api/fail2ban/install/status."""
    global _f2b_install_status
    if _f2b_install_status.get('running'):
        return jsonify({'ok': False, 'error': 'Install already in progress'}), 400
    if _f2b_is_available():
        return jsonify({'ok': False, 'error': 'fail2ban is already installed'}), 400

    _f2b_install_status = {'running': True, 'log': [], 'done': False, 'ok': False}

    # v10.1.70 W1.1: read the operator's address HERE, in the request context. `request`
    # does not exist inside the worker thread below, so deferring this would silently
    # seed nothing.
    _client_for_seed = _f2b_console_client_ip()

    def _plog(msg):
        _f2b_install_status['log'].append(msg)
        print(f"fail2ban install: {msg}", flush=True)

    def _run():
        global _f2b_install_status
        try:
            # Seed BEFORE the jails are written — _fail2ban_install_and_configure() bakes
            # ignoreip into every jail it creates, so seeding afterwards would not take
            # effect until something else happened to rewrite them.
            _seeded, _why = _f2b_seed_console_client_ignore(_client_for_seed, 'fail2ban install')
            _plog(f"never-ban list: seeded your address {_why}" if _seeded
                  else f"never-ban list: not seeded ({_why})")
            ok1 = _fail2ban_install_and_configure(_plog)
            if not ok1 and not _f2b_is_available():
                _f2b_install_status.update({'running': False, 'done': True, 'ok': False})
                return
            _fail2ban_add_guarddog_hook(_plog)
            _fail2ban_takserver_filter(_plog)
            # v10.1.68: a two-server build has a SECOND machine. Protect it in the same
            # action rather than leaving it exposed with nothing saying so.
            try:
                _fail2ban_install_db_node_step(_plog)
            except Exception as _dbx:
                _plog(f"db node: error (non-fatal, console host is protected): {_dbx}")
            _f2b_install_status.update({'running': False, 'done': True, 'ok': True})
        except Exception as e:
            _plog(f"ERROR: {e}")
            _f2b_install_status.update({'running': False, 'done': True, 'ok': False})

    import threading
    threading.Thread(target=_run, daemon=True).start()
    return jsonify({'ok': True, 'message': 'Install started'})

@app.route('/api/fail2ban/install/status')
@login_required
def fail2ban_install_status_api():
    """Poll install progress."""
    return jsonify({
        'running': _f2b_install_status.get('running', False),
        'done':    _f2b_install_status.get('done', False),
        'ok':      _f2b_install_status.get('ok', False),
        'log':     _f2b_install_status.get('log', []),
    })

@app.route('/api/fail2ban/uninstall', methods=['POST'])
@login_required
def fail2ban_uninstall_api():
    """Remove fail2ban, its configs, and clear settings.fail2ban_setup."""
    _denied = _require_admin_password()
    if _denied:
        return _denied
    log = []
    def _plog(msg):
        log.append(msg)
        print(f"fail2ban uninstall: {msg}", flush=True)
    try:
        # Stop and disable services
        subprocess.run(_sudo_wrap(['systemctl', 'stop', 'fail2ban']), capture_output=True)
        subprocess.run(_sudo_wrap(['systemctl', 'disable', 'fail2ban']), capture_output=True)
        subprocess.run(_sudo_wrap(['systemctl', 'stop', 'authentik-log-forwarder']), capture_output=True)
        subprocess.run(_sudo_wrap(['systemctl', 'disable', 'authentik-log-forwarder']), capture_output=True)
        _plog("Services stopped and disabled")
        # Remove package
        s = load_settings()
        pkg_mgr = s.get('pkg_mgr', 'apt')
        if pkg_mgr == 'apt':
            subprocess.run(_sudo_wrap(['apt-get', 'remove', '-y', 'fail2ban']), capture_output=True)
        else:
            subprocess.run(_sudo_wrap(['yum', 'remove', '-y', 'fail2ban']), capture_output=True)
        _plog("fail2ban package removed")
        # Remove config files
        for path in [
            '/etc/fail2ban/jail.d/infratak-authentik.conf',
            '/etc/fail2ban/jail.d/infratak-takserver.conf',
            '/etc/fail2ban/filter.d/authentik.conf',
            '/etc/fail2ban/filter.d/takserver.conf',
            '/etc/fail2ban/action.d/infratak-guarddog.conf',
            '/etc/fail2ban/action.d/infratak-guarddog-takserver.conf',
            '/etc/systemd/system/authentik-log-forwarder.service',
            '/usr/local/sbin/infratak-f2b-notify',
        ]:
            subprocess.run(_sudo_wrap(['rm', '-f', path]), capture_output=True)  # v10.0.5 non-root
        subprocess.run(_sudo_wrap(['systemctl', 'daemon-reload']), capture_output=True)
        _plog("Config files and systemd unit removed")
        # Clear settings
        s2 = load_settings()
        s2.pop('fail2ban_setup', None)
        save_settings(s2)
        _plog("Settings cleared")
        return jsonify({'ok': True, 'log': log})
    except Exception as e:
        _plog(f"ERROR: {e}")
        return jsonify({'ok': False, 'error': str(e)[:200], 'log': log}), 500


def _parse_guarddog_log_date(line):
    """Return (date, display_str) for a restarts.log line, or (None, line) if unparseable."""
    line = line.strip()
    if not line:
        return None, line
    # ISO: 2026-03-03T15:00:00Z | ...
    if len(line) >= 20 and line[10] == 'T' and line[19] in 'Z| ':
        try:
            dt = datetime.strptime(line[:19], '%Y-%m-%dT%H:%M:%S')
            return dt.date(), line[:19].replace('T', ' ')
        except ValueError:
            pass
    # date(1): Tue Mar  3 15:00:00 UTC 2026: message
    idx = line.find(': ')
    if idx > 20:
        prefix = line[:idx].strip()
        try:
            dt = datetime.strptime(prefix, '%a %b %d %H:%M:%S %Z %Y')
            return dt.date(), prefix
        except ValueError:
            pass
    return None, ''

def _guarddog_health_check(service_id):
    """Quick health check for one service. Returns True if healthy, False otherwise. Used for UI and optional monitors."""
    try:
        if service_id == 'takserver':
            # v10.0.1: container-aware liveness (docker inspect vs systemctl).
            if not _takserver_running_local():
                return False
            # Also check 8089 is listening (host-published for the container).
            r2 = subprocess.run('ss -ltn "sport = :8089" 2>/dev/null', shell=True, capture_output=True, text=True, timeout=2)
            return 'LISTEN' in (r2.stdout or '')
        if service_id == 'authentik':
            settings = load_settings()
            ak_url = _get_authentik_api_url(settings)
            req = urllib.request.Request(ak_url + '/', method='GET')
            with urllib.request.urlopen(req, timeout=8) as resp:
                return resp.status in (200, 302, 301)
        if service_id == 'takportal':
            return _takportal_web_running()  # v10.1.59: the WEB service, exact — not a substring
        if service_id == 'mediamtx':
            settings = load_settings()
            mtx_cfg = _get_module_deployment_config(settings, 'mediamtx_deployment')
            if mtx_cfg.get('target_mode') == 'remote' and mtx_cfg.get('deployed') and (mtx_cfg.get('remote', {}).get('host') or '').strip():
                ok, out = _ssh_probe(mtx_cfg.get('remote', {}), 'systemctl is-active mediamtx 2>/dev/null', timeout=8)
                return bool(ok and out and out.strip() == 'active')
            r = subprocess.run(_sudo_wrap(['systemctl', 'is-active', 'mediamtx']), capture_output=True, text=True, timeout=3)
            return r.returncode == 0
        if service_id == 'tak_video_restreamer':
            r = subprocess.run(
                _sudo_wrap(['docker', 'inspect', '--format', '{{.State.Running}}', 'tak-video-restreamer']),
                capture_output=True, text=True, timeout=5)
            return r.stdout.strip() == 'true'
        if service_id == 'simulator':
            r = subprocess.run(
                _sudo_wrap(['docker', 'inspect', '--format', '{{.State.Running}}', 'tak-simulator']),
                capture_output=True, text=True, timeout=5)
            return (r.stdout or '').strip() == 'true'
        if service_id == 'nodered':
            settings = load_settings()
            nr_cfg = _get_module_deployment_config(settings, 'nodered_deployment')
            if nr_cfg.get('target_mode') == 'remote' and nr_cfg.get('deployed') and (nr_cfg.get('remote', {}).get('host') or '').strip():
                ok, out = _ssh_probe(nr_cfg.get('remote', {}),
                    "curl -s -o /dev/null -w '%{http_code}' --connect-timeout 4 http://127.0.0.1:1880/ 2>/dev/null || echo 000", timeout=10)
                return bool(ok and out and out.strip() in ('200', '301', '302'))
            req = urllib.request.Request('http://127.0.0.1:1880/', method='GET')
            with urllib.request.urlopen(req, timeout=5) as resp:
                return resp.status in (200, 302, 301)
        if service_id == 'cloudtak':
            settings = load_settings()
            cfg = _get_cloudtak_deployment_config(settings)
            if cfg.get('target_mode') == 'remote':
                rcfg = cfg.get('remote', {})
                if cfg.get('deployed') and (rcfg.get('host') or '').strip():
                    ok, out = _ssh_probe(rcfg, "docker ps --filter name=cloudtak-api --format '{{.Status}}' 2>/dev/null", timeout=10)
                    return bool(ok and out and 'Up' in out)
                return False
            r = subprocess.run(_sudo_wrap(['docker', 'ps', '--filter', 'name=cloudtak-api', '--format', '{{.Status}}']), capture_output=True, text=True, timeout=5)
            return bool(r.stdout and 'Up' in r.stdout)
        if service_id == 'federation_hub':
            settings = load_settings()
            fh_cfg = _get_fedhub_deployment_config(settings)
            if not fh_cfg.get('deployed') or fh_cfg.get('target_mode') != 'remote':
                return None
            fh_remote = fh_cfg.get('remote', {})
            if not (fh_remote.get('host') or '').strip():
                return None
            ok, out = _ssh_probe(fh_remote, 'systemctl is-active federation-hub 2>/dev/null', timeout=8)
            return bool(ok and out and out.strip() == 'active')
        if service_id == 'remotedb':
            import socket
            db_host, db_port = _remotedb_host_port_from_tak_settings()
            if not db_host or not db_port:
                conf_path = '/opt/tak-guarddog/guarddog.conf'
                if not os.path.isfile(conf_path):
                    return None
                with open(conf_path) as f:
                    conf = json.load(f)
                db_host = conf.get('db_host', '')
                db_port = int(conf.get('db_port', 0))
            if not db_host or not db_port:
                return None
            s = socket.create_connection((db_host, db_port), timeout=5)
            s.close()
            return True
    except subprocess.TimeoutExpired:
        # v10.1.40: same carve-out as _monitor_health_check() below, and it matters MORE
        # here — this function's caller does `'ok' if val else 'fail'`, so a timed-out
        # probe painted a hard RED on the Console card rather than a caution. The probes
        # above run on 2-5s timeouts (`ss` 2s, `systemctl is-active` 3s, `docker ps` 5s),
        # which a box under load will blow through while being perfectly healthy.
        # None means "no reading"; the caller already filters it (`if val is not None`).
        return None
    except Exception:
        return False
    return False

# Monitor IDs per service for overall status (ok / caution / fail). Services with multiple monitors get caution when some are down.
def _guarddog_service_monitor_ids(settings):
    tak_cfg = _get_tak_deployment_config(settings)
    is_two_server = tak_cfg.get('mode') == 'two_server'
    takserver_ids = ['port8089', 'process', 'network']
    if not is_two_server:
        takserver_ids.extend(['postgresql', 'cotdb'])
    takserver_ids.extend(['oom', 'disk', 'cert', 'intca', 'jvm'])
    multi = {
        'takserver': takserver_ids,
        'remotedb': ['remotedb_tcp', 'remotedb_agent', 'remotedb_auth'],
        'federation_hub': ['fedhub_svc', 'fedhub_port', 'fedhub_mongo', 'fedhub_disk', 'fedhub_cert', 'fedhub_intca'],
        'authentik': ['authentik_http', 'authentik_channels'],
        'takportal': ['takportal_ctr'],
        'mediamtx': ['mediamtx_svc'],
        'tak_video_restreamer': ['tvr_http'],
        'simulator': ['simulator_ctr'],
        'nodered': ['nodered_http'],
        'cloudtak': ['cloudtak_ctr'],
        'updates': ['updates_check'],
        'relay': ['relay_tunnel'],
    }
    return multi


def _guarddog_monitored_service_ids(settings):
    """Return service IDs that Guard Dog should currently include in health rollups."""
    modules = detect_modules()
    tak_cfg = _get_tak_deployment_config(settings)
    is_two_server = tak_cfg.get('mode') == 'two_server'
    s1_host = (tak_cfg.get('server_one', {}).get('host') or '').strip() if is_two_server else ''

    ids = ['takserver']
    if is_two_server and s1_host:
        ids.append('remotedb')
    fh_cfg = _get_fedhub_deployment_config(settings)
    if fh_cfg.get('deployed') and fh_cfg.get('target_mode') == 'remote' and (fh_cfg.get('remote', {}).get('host') or '').strip():
        ids.append('federation_hub')
    if modules.get('authentik', {}).get('installed'):
        ids.append('authentik')
    if modules.get('takportal', {}).get('installed'):
        ids.append('takportal')
    if modules.get('mediamtx', {}).get('installed'):
        ids.append('mediamtx')
    if modules.get('tak_video_restreamer', {}).get('installed'):
        ids.append('tak_video_restreamer')
    if modules.get('simulator', {}).get('installed'):
        ids.append('simulator')
    if modules.get('nodered', {}).get('installed'):
        ids.append('nodered')
    if modules.get('cloudtak', {}).get('installed'):
        ids.append('cloudtak')
    if modules.get('guarddog', {}).get('installed'):
        ids.append('updates')
    if (settings.get('connectivity_anchor') or {}).get('anchor_ip'):
        ids.append('relay')
    return ids


# --- Guard Dog maintenance windows (v10.1.60 W4) ---------------------------------
# A restart the console itself asked for is not an outage. The in-memory health cache
# (rebuilt every _GD_PAGE_CACHE_TTL seconds) used to read "web container not running"
# during the 10-15 s a TAK Portal Update / Restart / Update Config / post-upgrade
# reconfigure keeps the container down, and the console then wore the "Guard Dog has an
# active alert" banner after every upgrade (field report, test12, 2026-09-06). The shell
# guards under /opt/tak-guarddog already debounce (three consecutive one-minute misses)
# and are untouched — this is only the console's own picture of itself.
#
# Inside a window a NON-ok probe result is replaced by the service's previous cached
# verdict: a healthy portal being restarted stays green; a portal that was already red
# stays red until a probe actually reads ok. It never fails open on a box that was down,
# and a window never outlives its deadline — a build that hangs still surfaces.
_gd_maintenance = {}
_gd_maintenance_lock = threading.Lock()


def _gd_maintenance_begin(service_id, seconds=180):
    """Declare `service_id` under console-driven maintenance for `seconds` from now.
    Replaces any earlier deadline, so a caller that opened a long window for a build
    shrinks it to a short grace once the build is over."""
    try:
        with _gd_maintenance_lock:
            _gd_maintenance[service_id] = time.time() + max(0, int(seconds))
    except Exception:
        pass


def _gd_in_maintenance(service_id):
    try:
        with _gd_maintenance_lock:
            return time.time() < _gd_maintenance.get(service_id, 0)
    except Exception:
        return False


def _gd_maintenance_verdict(service_id, fresh):
    """`fresh` is the verdict just computed ('ok'|'fail'|'caution'|None). Inside a
    maintenance window a non-ok result yields the previous cached verdict instead."""
    if fresh == 'ok' or fresh is None or not _gd_in_maintenance(service_id):
        return fresh
    prev = (_guarddog_page_cache.get('health') or {}).get(service_id)
    return prev if prev is not None else fresh


def _guarddog_run_one_service(sid, monitor_ids):
    """Run checks for one service (multi-monitor or single). Returns (sid, 'ok'|'fail'|'caution'|None)."""
    if monitor_ids:
        vals = []
        for mid in monitor_ids:
            v = _monitor_health_check(mid)
            if v is not None:
                vals.append(v)
        if not vals:
            return (sid, None)
        if all(vals):
            return (sid, 'ok')
        if not any(vals):
            return (sid, _gd_maintenance_verdict(sid, 'fail'))
        return (sid, _gd_maintenance_verdict(sid, 'caution'))
    val = _guarddog_health_check(sid)
    if val is not None:
        return (sid, 'ok' if val else _gd_maintenance_verdict(sid, 'fail'))
    return (sid, None)


def _detect_disk_layout():
    """v10.1.9 W2/WI-2 — is TAK boxed into a fraction of this disk?

    Fresh installs strand space away from root, where ALL of TAK lives (Docker,
    /opt/tak, Postgres, Authentik, CloudTAK): RHEL/Anaconda parks the remainder in
    a separate /home LV; Ubuntu/subiquity leaves unallocated VG extents. Read-only.

    Returns {mode, root_gb, root_pct_of_vg, vg_free_gb, home_lv_gb, home_used_mb,
             reclaimable_gb, vg, root_lv, home_lv, fold_safe}
    with mode ∈ {'ok','free_extents','idle_home','both'}; mode 'ok' also covers
    'not on LVM / nothing to reclaim'."""
    out = {'mode': 'ok', 'root_gb': 0, 'root_pct_of_vg': 100, 'vg_free_gb': 0,
           'home_lv_gb': 0, 'home_used_mb': 0, 'reclaimable_gb': 0,
           'vg': '', 'root_lv': '', 'home_lv': '', 'fold_safe': False}

    def _run(argv, timeout=20):
        # lvs/vgs read PV metadata → privileged, so these route through the broker.
        try:
            r = subprocess.run(_sudo_wrap(argv), capture_output=True, text=True, timeout=timeout)
            return (r.stdout or '').strip() if r.returncode == 0 else ''
        except Exception:
            return ''

    def _run_plain(argv, timeout=20):
        # df/findmnt report on mounted filesystems unprivileged — running them
        # unwrapped avoids a needless broker deny on an enforcing box.
        try:
            r = subprocess.run(argv, capture_output=True, text=True, timeout=timeout)
            return (r.stdout or '').strip() if r.returncode == 0 else ''
        except Exception:
            return ''

    try:
        root_dev = _run_plain(['findmnt', '-no', 'SOURCE', '/'])
        if not root_dev:
            return out
        vg = _run(['lvs', '--noheadings', '-o', 'vg_name', root_dev])
        root_lv = _run(['lvs', '--noheadings', '-o', 'lv_name', root_dev])
        if not vg or not root_lv:
            return out              # not on LVM — nothing this feature can do
        out['vg'], out['root_lv'] = vg, root_lv

        def _bytes(s):
            return int(re.sub(r'\D', '', s or '0') or 0)

        vg_size_b = _bytes(_run(['vgs', '--noheadings', '-o', 'vg_size', '--units', 'b', vg]))
        vg_free_b = _bytes(_run(['vgs', '--noheadings', '-o', 'vg_free', '--units', 'b', vg]))
        root_size_b = _bytes(_run(['lvs', '--noheadings', '-o', 'lv_size', '--units', 'b', root_dev]))
        out['root_gb'] = round(root_size_b / 1024 ** 3, 1)
        out['vg_free_gb'] = round(vg_free_b / 1024 ** 3, 1)
        if vg_size_b:
            out['root_pct_of_vg'] = int(root_size_b * 100 / vg_size_b)

        home_dev = _run_plain(['findmnt', '-no', 'SOURCE', '/home'])
        home_size_b = home_used_b = 0
        if home_dev:
            home_vg = _run(['lvs', '--noheadings', '-o', 'vg_name', home_dev])
            home_lv = _run(['lvs', '--noheadings', '-o', 'lv_name', home_dev])
            if home_vg == vg and home_lv:
                out['home_lv'] = f'{home_vg}/{home_lv}'
                home_size_b = _bytes(_run(['lvs', '--noheadings', '-o', 'lv_size', '--units', 'b', home_dev]))
                du = _run_plain(['df', '-B1', '--output=used', '/home'])
                lines = [l for l in du.splitlines() if l.strip()]
                home_used_b = _bytes(lines[-1]) if len(lines) > 1 else 0
                out['home_lv_gb'] = round(home_size_b / 1024 ** 3, 1)
                out['home_used_mb'] = round(home_used_b / 1024 ** 2, 1)
                # Same 2 GiB ceiling the broker enforces — keep the UI honest about
                # whether the fold-in would actually be accepted.
                out['fold_safe'] = home_used_b <= 2 * 1024 ** 3

        has_free = vg_free_b >= 1024 ** 3
        has_home = bool(out['home_lv']) and out['fold_safe'] and home_size_b >= 1024 ** 3
        out['mode'] = ('both' if (has_free and has_home) else
                       'free_extents' if has_free else
                       'idle_home' if has_home else 'ok')
        reclaimable_b = (vg_free_b if has_free else 0) + (home_size_b if has_home else 0)
        out['reclaimable_gb'] = round(reclaimable_b / 1024 ** 3, 1)
        return out
    except Exception:
        return out


@app.route('/api/guarddog/disk-layout')
@login_required
def guarddog_disk_layout_api():
    """Read-only disk-layout report (WI-2). Drives the 'X GB reclaimable' card."""
    return jsonify({'success': True, 'layout': _detect_disk_layout()})


@app.route('/api/console/disk/reclaim', methods=['POST'])
@login_required
def console_disk_reclaim_api():
    """v10.1.9 W2/WI-3 — reclaim stranded disk for TAK.

    mode='grow_free' is non-destructive (extend root into free extents).
    mode='fold_home' DESTROYS the /home LV after backing it up, so — like the
    Power Off control — it re-confirms the console password on top of
    @login_required and makes the caller echo the exact LV being destroyed.
    All privileged work happens inside the broker's fixed-shape `disk_reclaim`
    op; the console never composes LVM argv itself."""
    data = request.get_json(silent=True) or {}
    mode = (data.get('mode') or '').strip()
    if mode not in ('grow_free', 'fold_home'):
        return jsonify({'success': False, 'error': 'mode must be "grow_free" or "fold_home".'}), 400

    req = {'op': 'disk_reclaim', 'mode': mode}
    if mode == 'fold_home':
        password = data.get('password') or ''
        auth = load_auth()
        if not auth.get('password_hash') or not check_password_hash(auth['password_hash'], password):
            return jsonify({'success': False, 'error': 'Incorrect console password.', 'need_password': True}), 403
        layout = _detect_disk_layout()
        if not layout.get('home_lv'):
            return jsonify({'success': False, 'error': 'No separate /home LV found — nothing to fold in.'}), 400
        if not layout.get('fold_safe'):
            return jsonify({'success': False, 'error': f"/home holds {layout.get('home_used_mb')} MB — "
                                                       "too much to fold in safely. Move the data off first."}), 400
        confirm = (data.get('confirm_lv') or '').strip()
        if confirm != layout['home_lv']:
            return jsonify({'success': False, 'error': f"confirm_lv must be exactly '{layout['home_lv']}'.",
                            'expected_lv': layout['home_lv']}), 400
        req['confirm_lv'] = confirm
        # On a fresh box there is ALWAYS a login shell sitting in /home — the
        # person who installed it. The modal states that shells get signed out,
        # so grant the broker leave to close them; it still hard-refuses on any
        # holder that is not a plain interactive shell.
        req['close_shells'] = True

    try:
        # The fold-in rsyncs/tars /home and stops docker — allow a long window.
        res = _broker_request(req, timeout=2400)
    except Exception as e:
        return jsonify({'success': False, 'error': f'Broker request failed: {e}'}), 500
    if not res.get('ok'):
        return jsonify({'success': False, 'error': res.get('error') or 'Reclaim failed.',
                        'log': res.get('log') or []}), 400
    return jsonify({'success': True, 'mode': mode, 'log': res.get('log') or [],
                    'df_after': res.get('df_after', ''), 'backup': res.get('backup', ''),
                    'layout': _detect_disk_layout()})


@app.route('/api/guarddog/health')
@login_required
def guarddog_health_api():
    """Return health status per service. Always return cache when present so page shows colors in ~1s; background thread keeps cache warm."""
    from flask import make_response
    # Start background refresh on first request so cache is kept warm
    global _guarddog_background_started
    if not _guarddog_background_started:
        with _guarddog_background_lock:
            if not _guarddog_background_started:
                _guarddog_background_started = True
                threading.Thread(target=_guarddog_background_loop, daemon=True).start()
    # Return cache immediately when we have it (even if slightly stale)
    if _guarddog_page_cache['health'] is not None:
        r = make_response(jsonify(_guarddog_page_cache['health']))
        r.headers['Cache-Control'] = 'no-store, no-cache, must-revalidate'
        return r
    # Cold load: populate cache once then return
    _guarddog_refresh_page_cache()
    r = make_response(jsonify(_guarddog_page_cache['health'] or {}))
    r.headers['Cache-Control'] = 'no-store, no-cache, must-revalidate'
    return r


def _guarddog_overall_from_result(result):
    """Compute single overall status from per-service result dict."""
    if not result:
        return 'ok'
    vals = list(result.values())
    if all(v == 'ok' for v in vals):
        return 'ok'
    if all(v == 'fail' for v in vals):
        return 'fail'
    return 'caution'


# Cache overall health so we don't re-run all checks every 8s from the Console.
# The cache holds for 30s. On caution it holds for 10s so we re-check sooner.
_guarddog_overall_cache = {'overall': 'ok', 'ts': 0}

# Cache for Guard Dog page: service and monitor health so the monitors page shows status quickly (TTL 25s).
_guarddog_page_cache = {'health': None, 'health_ts': 0, 'monitor_key': None, 'monitor_result': None, 'monitor_ts': 0}
_GD_PAGE_CACHE_TTL = 25
_guarddog_background_started = False
_guarddog_background_lock = threading.Lock()


def _guarddog_refresh_page_cache():
    """Run health + monitor checks and update _guarddog_page_cache. Used by background thread and cold load."""
    from concurrent.futures import ThreadPoolExecutor, as_completed
    try:
        settings = load_settings()
        multi = _guarddog_service_monitor_ids(settings)
        service_ids = _guarddog_monitored_service_ids(settings)
        # Health
        result = {}
        with ThreadPoolExecutor(max_workers=min(16, len(service_ids) * 3)) as ex:
            futures = {ex.submit(_guarddog_run_one_service, sid, multi.get(sid)): sid for sid in service_ids}
            for fut in as_completed(futures):
                try:
                    sid, status = fut.result()
                    if status is not None:
                        result[sid] = status
                except Exception:
                    pass
        _guarddog_page_cache['health'] = result
        _guarddog_page_cache['health_ts'] = time.time()
        # All monitor ids used by services
        all_mids = []
        for sid in service_ids:
            all_mids.extend(multi.get(sid) or [])
        all_mids = list(dict.fromkeys(all_mids))
        if not all_mids:
            return
        mon_result = {}
        with ThreadPoolExecutor(max_workers=min(16, len(all_mids) or 1)) as ex:
            futures = {ex.submit(_monitor_health_check, mid): mid for mid in all_mids}
            for fut in as_completed(futures):
                mid = futures[fut]
                try:
                    val = fut.result()
                    if val is not None:
                        mon_result[mid] = val
                except Exception:
                    pass
        _guarddog_page_cache['monitor_key'] = tuple(sorted(all_mids))
        _guarddog_page_cache['monitor_result'] = mon_result
        _guarddog_page_cache['monitor_ts'] = time.time()
    except Exception:
        pass


def _guarddog_background_loop():
    """Daemon thread: refresh Guard Dog page cache every 25s so page load is instant."""
    time.sleep(2)  # Let first request do cold load, then we keep cache warm
    while True:
        _guarddog_refresh_page_cache()
        time.sleep(_GD_PAGE_CACHE_TTL)


def _compute_guarddog_overall():
    """Run all Guard Dog health checks and return overall status."""
    settings = load_settings()
    multi = _guarddog_service_monitor_ids(settings)
    result = {}
    for sid in _guarddog_monitored_service_ids(settings):
        monitor_ids = multi.get(sid)
        if monitor_ids:
            vals = []
            for mid in monitor_ids:
                v = _monitor_health_check(mid)
                if v is not None:
                    vals.append(v)
            if not vals:
                continue
            result[sid] = _gd_maintenance_verdict(
                sid, 'ok' if all(vals) else ('fail' if not any(vals) else 'caution'))
        else:
            val = _guarddog_health_check(sid)
            if val is not None:
                result[sid] = _gd_maintenance_verdict(sid, 'ok' if val else 'fail')
    return _guarddog_overall_from_result(result)


@app.route('/api/guarddog/overall-health')
@login_required
def guarddog_overall_health_api():
    """Overall Guard Dog health for Console card. Cached to avoid re-running all checks on every request."""
    now = time.time()
    age = now - _guarddog_overall_cache['ts']
    cached = _guarddog_overall_cache['overall']
    ttl = 10 if cached == 'caution' else 30
    if age < ttl:
        from flask import make_response
        r = make_response(jsonify({'overall': cached}))
        r.headers['Cache-Control'] = 'no-store, no-cache, must-revalidate'
        return r
    overall = _compute_guarddog_overall()
    _guarddog_overall_cache['overall'] = overall
    _guarddog_overall_cache['ts'] = now
    from flask import make_response
    r = make_response(jsonify({'overall': overall}))
    r.headers['Cache-Control'] = 'no-store, no-cache, must-revalidate'
    return r


def _monitor_health_check(monitor_id):
    """Quick health check for individual monitors. Returns True/False/None."""
    import socket
    try:
        if monitor_id == 'relay_tunnel':
            # Healthy = a fresh WireGuard handshake (<180s). Mirrors the Leg 7
            # watcher's threshold. None if no relay configured / interface absent.
            st = _conn_anchor_status()
            if not st.get('configured'):
                return None
            hs = st.get('handshake_secs')
            if hs is None:
                return False
            return hs <= 180
        if monitor_id == 'port8089':
            r = subprocess.run('ss -ltn "sport = :8089" 2>/dev/null', shell=True, capture_output=True, text=True, timeout=2)
            return 'LISTEN' in (r.stdout or '')
        if monitor_id == 'process':
            r = subprocess.run('pgrep -f "takserver" 2>/dev/null | head -1', shell=True, capture_output=True, text=True, timeout=3)
            return bool(r.stdout.strip())
        if monitor_id == 'network':
            # ICMP first — fast path where ping is allowed.
            for host in ('1.1.1.1', '8.8.8.8'):
                r = subprocess.run(['ping', '-c', '1', '-W', '2', host], capture_output=True, timeout=4)
                if r.returncode == 0:
                    return True
            # ICMP filtered (e.g. Azure NSG blocks outbound ping) — confirm real egress
            # via TCP before declaring the network down. Mirrors _detect_local_ip()'s
            # trust model: TCP/UDP egress is the truth, ICMP is not.
            for host, port in (('1.1.1.1', 443), ('8.8.8.8', 53)):
                try:
                    with socket.create_connection((host, port), timeout=2):
                        return True
                except OSError:
                    continue
            return False
        if monitor_id == 'postgresql':
            # v10.1.1 (F7): key off TAK's real DB topology (CoreConfig ground truth),
            # not a hardcoded local assumption. A split box whose CoreConfig points at
            # a remote DB was checking a nonexistent local postgres → permanent false-red.
            _db_mode, _db_host, _db_port = _tak_db_topology()
            if _db_mode == 'remote':
                # Remote DB: TCP-connect to the CoreConfig host:port (no SSH). A real
                # outage of the remote DB now turns this dot red instead of hiding it.
                try:
                    with socket.create_connection((_db_host, _db_port), timeout=2):
                        return True
                except OSError:
                    return False
            # v10.0.1: container TAK runs PostgreSQL in the takserver-db container,
            # not a host postgresql.service — check the container's running state
            # there (native is byte-identical: systemctl is-active postgresql).
            if _db_mode == 'container' or _tak_is_container():
                r = subprocess.run(_sudo_wrap(['docker', 'inspect', '-f', '{{.State.Running}}', TAK_DB_CONTAINER]),
                                   capture_output=True, text=True, timeout=5)
                return r.returncode == 0 and r.stdout.strip() == 'true'
            # native: Debian/Ubuntu uses the `postgresql` meta-service; RHEL/EL uses
            # `postgresql-<major>.service` (PGDG). Either being active means PG is up.
            # Probes EVERY major in TAK_PG_MAJORS: an un-migrated box is still on 15.
            for _pgsvc in ('postgresql',) + _PG_SVC_UNITS:
                r = subprocess.run(_sudo_wrap(['systemctl', 'is-active', _pgsvc]), capture_output=True, text=True, timeout=3)
                if r.returncode == 0 and r.stdout.strip() == 'active':
                    return True
            return False
        if monitor_id == 'cotdb':
            # v10.1.1 (F7): remote DB → psql over TCP with CoreConfig's martiuser creds;
            # fall back to TCP-reachable-only if auth fails (so the dot reflects "DB up"
            # even when the console can't read the size). Split boxes no longer false-red.
            _db_mode, _db_host, _db_port = _tak_db_topology()
            if _db_mode == 'remote':
                _pw, _ = _read_martiuser_password_from_local_coreconfig()
                if _pw:
                    _env = dict(os.environ, PGPASSWORD=_pw, PGCONNECT_TIMEOUT='4')
                    try:
                        r = subprocess.run(
                            ['psql', '-h', _db_host, '-p', str(_db_port), '-U', 'martiuser',
                             '-d', 'cot', '-tAc', "SELECT pg_database_size('cot')"],
                            capture_output=True, text=True, timeout=8, env=_env)
                        if r.returncode == 0 and r.stdout.strip().isdigit():
                            return True
                    except FileNotFoundError:
                        pass  # no psql client on this box — fall through to TCP reachability
                # Auth failed / no password / no psql client — degrade to TCP reachability.
                try:
                    with socket.create_connection((_db_host, _db_port), timeout=3):
                        return True
                except OSError:
                    return False
            # v10.0.1: container → docker exec -u postgres (peer auth); native →
            # sudo -u postgres psql. Both query the same cot database size.
            if _tak_is_container():
                r = subprocess.run(
                    _sudo_wrap(['docker', 'exec', '-u', 'postgres', TAK_DB_CONTAINER,
                     'psql', '-tAc', "SELECT pg_database_size('cot')"]),
                    capture_output=True, text=True, timeout=8)
                return r.returncode == 0 and r.stdout.strip().isdigit()
            r = _pg_exec(['psql', '-tAc', "SELECT pg_database_size('cot')"], timeout=5)
            return r.returncode == 0 and r.stdout.strip().isdigit()
        if monitor_id == 'oom':
            # Only count OOM entries logged after TAK's last start so a pre-restart OOM
            # doesn't keep the monitor permanently red after a successful recovery.
            # v10.1.14: TAK runs 5 JVMs with separate heaps — large DataSyncs exhaust
            # the api process, not messaging — so scan both logs and sum.
            log_paths = [p for p in ('/opt/tak/logs/takserver-messaging.log',
                                     '/opt/tak/logs/takserver-api.log') if os.path.isfile(p)]
            if not log_paths:
                return None
            tr = subprocess.run(
                _sudo_wrap(['systemctl', 'show', 'takserver', '--property=ActiveEnterTimestamp', '--value']), capture_output=True, text=True, timeout=3)
            tak_ts = tr.stdout.strip()  # e.g. "Tue 2026-05-19 14:32:38 UTC"
            tak_prefix = ''
            try:
                parts = tak_ts.split()  # ['Tue', '2026-05-19', '14:32:38', 'UTC']
                if len(parts) >= 3:
                    tak_prefix = f'{parts[1]}-{parts[2]}'  # "2026-05-19-14:32:38"
            except Exception:
                pass
            total = 0
            for log_path in log_paths:
                if tak_prefix:
                    # awk: track timestamped lines >= TAK start, count OOM in that window only
                    r = subprocess.run(
                        f'awk -v s="{tak_prefix}" \'/^[0-9]{{4}}-[0-9]{{2}}-[0-9]{{2}}-/{{a=($0>=s)}} a&&/OutOfMemoryError/{{c++}} END{{print c+0}}\' "{log_path}" 2>/dev/null',
                        shell=True, capture_output=True, text=True, timeout=10)
                else:
                    r = subprocess.run(
                        f'tail -n 10000 "{log_path}" | grep -c "OutOfMemoryError" 2>/dev/null',
                        shell=True, capture_output=True, text=True, timeout=5)
                try:
                    total += int(r.stdout.strip() or '0')
                except ValueError:
                    pass
            return total == 0
        if monitor_id == 'disk':
            r = subprocess.run("df / --output=pcent 2>/dev/null | tail -1", shell=True, capture_output=True, text=True, timeout=3)
            pct = int(r.stdout.strip().rstrip('%'))
            return pct < 80
        if monitor_id == 'cert':
            cert_path = '/opt/tak/certs/files/admin.pem'
            if not os.path.isfile(cert_path):
                cert_path = '/opt/tak/certs/files/takserver.pem'
            if not os.path.isfile(cert_path):
                return None
            r = subprocess.run(f'openssl x509 -in {cert_path} -checkend 3456000 2>/dev/null', shell=True, capture_output=True, timeout=3)
            return r.returncode == 0
        if monitor_id == 'jvm':
            # v10.1.63 W4. Read the RUNNING process's JVM (/proc/<pid>/exe), not `java
            # -version` — the process may have been started with a different JVM than the
            # one on today's PATH, and the running one is the only one that matters.
            # Container TAK carries its JVM in the image and cannot be moved by the host's
            # alternatives, so there is nothing to check.
            if _tak_is_container():
                return None
            # The API JVM's own flag — `takserver-api` matches TAK's launcher SHELL
            # (/usr/bin/dash), which would have made this monitor red on every healthy box.
            _pid = _tak_api_pid()
            if not _pid:
                return None          # TAK not running — the process monitor owns that
            _exe = _trusted_java_exe(_pid)   # argv is attacker-chosen — see the helper
            if _exe:
                _jr = subprocess.run([_exe, '-version'], capture_output=True, text=True, timeout=20)
                _jv = (_jr.stderr or '') + (_jr.stdout or '')
            else:
                # Non-root console cannot read /proc/<tak pid>/exe — take the root watcher's
                # reading rather than reporting unknown forever on most of the fleet.
                _kv = _jvm_status_from_guarddog(_pid)
                _jv = (_kv or {}).get('version', '')
            if 'version "' not in _jv:
                return None          # no Java version string = unknown: grey, never a false red
            return ('version "17.' in _jv) or ('version "17"' in _jv)
        if monitor_id == 'intca':
            for name in ('ca.pem', 'ca-do-not-delete.pem', 'intermediate-ca.pem'):
                p = f'/opt/tak/certs/files/{name}'
                if os.path.isfile(p):
                    r = subprocess.run(f'openssl x509 -in {p} -checkend 7776000 2>/dev/null', shell=True, capture_output=True, timeout=3)
                    if r.returncode != 0:
                        return False
            return True
        if monitor_id == 'remotedb_tcp':
            db_host, db_port = _remotedb_host_port_from_tak_settings()
            if not db_host or not db_port:
                conf_path = '/opt/tak-guarddog/guarddog.conf'
                if not os.path.isfile(conf_path):
                    return None
                with open(conf_path) as f:
                    conf = json.load(f)
                db_host = conf.get('db_host', '')
                db_port = int(conf.get('db_port', 0))
            if not db_host or not db_port:
                return None
            try:
                s = socket.create_connection((db_host, db_port), timeout=5)
                s.close()
                return True
            except (OSError, socket.timeout):
                return False
        if monitor_id == 'remotedb_agent':
            db_host, _dbp = _remotedb_host_port_from_tak_settings()
            if not db_host:
                conf_path = '/opt/tak-guarddog/guarddog.conf'
                if not os.path.isfile(conf_path):
                    return None
                with open(conf_path) as f:
                    conf = json.load(f)
                db_host = conf.get('db_host', '')
            if not db_host:
                return None
            # 1) Direct HTTP — works when 8080 is reachable from the console (host-firewall-scoped boxes).
            try:
                req = urllib.request.Request(f'http://{db_host}:8080/health', method='GET')
                with urllib.request.urlopen(req, timeout=4) as resp:
                    if resp.status == 200:
                        return True
            except Exception:
                pass
            # 2) Fallback: poll /health over the SSH channel we ALREADY have to Server One. On cloud
            # boxes Server One often has NO host firewall, so 8080 is governed by the provider security
            # group (allows 22/5432 but not 8080) — the direct hit can't reach it even though the agent
            # is healthy and SSH is open (TCP+SSH green). This also means 8080 never needs to be
            # network-exposed (the endpoint exposes PG state), so the monitor works AND stays private.
            try:
                _s1 = _get_tak_deployment_config(load_settings()).get('server_one', {})
                if _s1.get('host'):
                    ok, out = _ssh_probe(_s1, 'curl -s -m4 -o /dev/null -w "%{http_code}" http://127.0.0.1:8080/health', timeout=12)
                    if ok and (out or '').strip().endswith('200'):
                        return True
            except Exception:
                pass
            return False
        if monitor_id == 'remotedb_auth':
            settings = load_settings()
            tak_cfg = _get_tak_deployment_config(settings)
            if tak_cfg.get('mode') != 'two_server':
                return None
            s1_cfg = tak_cfg.get('server_one', {})
            # Read password from LOCAL CoreConfig.xml (what TAK Server actually uses).
            # v0.9.46: CoreConfig stores it XML-escaped; the helper unescapes so a
            # regenerated password with an XML-special char doesn't false-fail.
            local_pw, _ = _read_martiuser_password_from_local_coreconfig()
            if not local_pw:
                return False
            ok, _ = _verify_server_one_db_password(s1_cfg, local_pw)
            return ok
        if monitor_id == 'authentik_http':
            settings = load_settings()
            ak_url = _get_authentik_api_url(settings)
            req = urllib.request.Request(ak_url + '/', method='GET')
            with urllib.request.urlopen(req, timeout=8) as resp:
                return resp.status in (200, 302, 301)
        if monitor_id == 'authentik_channels':
            # v10.1.1 (F5): django_channels_postgres_message size, size-based (never
            # count(*) — that can't complete on a ballooned table, the NE-TAK 605GB
            # blind spot). Green < 1GB, red >= 1GB (the in-process reaper (F1–F4)
            # should keep it KB-range; a red dot means the reaper is failing and the
            # disk is at risk). None when Authentik isn't installed / PG not up.
            if not os.path.exists(os.path.expanduser('~/authentik/docker-compose.yml')):
                return None
            r = subprocess.run(
                _sudo_wrap(['docker', 'exec', 'authentik-postgresql-1', 'psql', '-U', 'authentik',
                 '-d', 'authentik', '-tA', '-c',
                 "SELECT COALESCE(pg_total_relation_size(to_regclass("
                 "'django_channels_postgres_message')),-1)"]),
                capture_output=True, text=True, timeout=10)
            if r.returncode != 0:
                return None
            try:
                _sz = int((r.stdout or '-1').strip())
            except ValueError:
                return None
            if _sz < 0:
                return None  # table absent (older Authentik)
            return _sz < 1024 * 1024 * 1024  # red at >= 1GB
        if monitor_id == 'mediamtx_svc':
            settings = load_settings()
            mtx_cfg = _get_module_deployment_config(settings, 'mediamtx_deployment')
            if mtx_cfg.get('target_mode') == 'remote' and mtx_cfg.get('deployed') and (mtx_cfg.get('remote', {}).get('host') or '').strip():
                ok, out = _ssh_probe(mtx_cfg.get('remote', {}), 'systemctl is-active mediamtx 2>/dev/null', timeout=8)
                return bool(ok and out and out.strip() == 'active')
            r = subprocess.run(_sudo_wrap(['systemctl', 'is-active', 'mediamtx']), capture_output=True, text=True, timeout=3)
            return r.returncode == 0
        if monitor_id == 'nodered_http':
            settings = load_settings()
            nr_cfg = _get_module_deployment_config(settings, 'nodered_deployment')
            if nr_cfg.get('target_mode') == 'remote' and nr_cfg.get('deployed') and (nr_cfg.get('remote', {}).get('host') or '').strip():
                ok, out = _ssh_probe(nr_cfg.get('remote', {}),
                    "curl -s -o /dev/null -w '%{http_code}' --connect-timeout 4 http://127.0.0.1:1880/ 2>/dev/null || echo 000", timeout=10)
                return bool(ok and out and out.strip() in ('200', '301', '302'))
            req = urllib.request.Request('http://127.0.0.1:1880/', method='GET')
            with urllib.request.urlopen(req, timeout=5) as resp:
                return resp.status in (200, 302, 301)
        if monitor_id == 'tvr_http':
            # TVR Flask app has no /api/health — use /login which always returns 200
            try:
                req = urllib.request.Request('http://127.0.0.1:3100/login', method='GET')
                with urllib.request.urlopen(req, timeout=5) as resp:
                    return resp.status == 200
            except Exception:
                return False
        if monitor_id == 'simulator_ctr':
            # v10.1.61: container liveness only — a stopped scenario is normal (PLAN §4.5)
            r = subprocess.run(_sudo_wrap(['docker', 'inspect', '--format', '{{.State.Running}}', 'tak-simulator']),
                               capture_output=True, text=True, timeout=5)
            return (r.stdout or '').strip() == 'true'
        if monitor_id == 'takportal_ctr':
            return _takportal_web_running()  # v10.1.59: the WEB service, exact — not a substring
        if monitor_id == 'cloudtak_ctr':
            settings = load_settings()
            cfg = _get_cloudtak_deployment_config(settings)
            if cfg.get('target_mode') == 'remote':
                rcfg = cfg.get('remote', {})
                if not cfg.get('deployed') or not (rcfg.get('host') or '').strip():
                    return False
                ok, out = _ssh_probe(rcfg, "docker ps --filter name=cloudtak-api --format '{{.Status}}' 2>/dev/null", timeout=10)
                return bool(ok and out and 'Up' in out)
            r = subprocess.run(_sudo_wrap(['docker', 'ps', '--filter', 'name=cloudtak-api', '--format', '{{.Status}}']), capture_output=True, text=True, timeout=5)
            return bool(r.stdout and 'Up' in r.stdout)
        if monitor_id == 'updates_check':
            # v10.1.69 W5: was `systemctl is-enabled takupdatesguard.timer`. That timer ran
            # tak-updates-watch.sh, a SECOND update-notification path that mailed the same
            # pending updates as _update_notify_loop() on its own 6h cycle — each deduping
            # only against itself, so customers got two emails per update set (field report,
            # Charles Laird/NC 2026-09-12). The timer is retired; check the liveness of the
            # thread that actually sends the mail now, so this monitor still means something.
            try:
                return any(t.name == 'update-notify' and t.is_alive()
                           for t in threading.enumerate())
            except Exception:
                return None
        # Federation Hub monitors (all remote via SSH)
        if monitor_id.startswith('fedhub_'):
            settings = load_settings()
            fh_cfg = _get_fedhub_deployment_config(settings)
            if not fh_cfg.get('deployed') or fh_cfg.get('target_mode') != 'remote':
                return None
            fh_remote = fh_cfg.get('remote', {})
            if not (fh_remote.get('host') or '').strip():
                return None
            if monitor_id == 'fedhub_svc':
                ok, out = _ssh_probe(fh_remote, 'systemctl is-active federation-hub 2>/dev/null', timeout=8)
                return bool(ok and out and out.strip() == 'active')
            if monitor_id == 'fedhub_port':
                ok, out = _ssh_probe(fh_remote, 'ss -ltn "sport = :9100" 2>/dev/null', timeout=8)
                return bool(ok and out and 'LISTEN' in out)
            if monitor_id == 'fedhub_mongo':
                ok, out = _ssh_probe(fh_remote, 'systemctl is-active mongod 2>/dev/null', timeout=8)
                return bool(ok and out and out.strip() == 'active')
            if monitor_id == 'fedhub_disk':
                ok, out = _ssh_probe(fh_remote, "df / --output=pcent 2>/dev/null | tail -1", timeout=8)
                if not ok or not out:
                    return None
                try:
                    pct = int(out.strip().rstrip('%'))
                    return pct < 80
                except ValueError:
                    return None
            if monitor_id == 'fedhub_cert':
                ok_h, hn = _ssh_probe(fh_remote, 'hostname 2>/dev/null', timeout=8)
                hshort = ((hn or '').strip().split('.') or [''])[0]
                if not hshort:
                    return None
                cert_path = f'/opt/tak/federation-hub/certs/files/{hshort}.pem'
                ok2, out2 = _ssh_probe(
                    fh_remote,
                    f'test -f {shlex.quote(cert_path)} && openssl x509 -in {shlex.quote(cert_path)} -checkend 3456000 >/dev/null 2>&1 && echo OK',
                    timeout=12,
                )
                return bool(ok2 and 'OK' in (out2 or ''))
            if monitor_id == 'fedhub_intca':
                rca = '/opt/tak/federation-hub/certs/files/root-ca.pem'
                ica = '/opt/tak/federation-hub/certs/files/ca.pem'
                ok2, out2 = _ssh_probe(
                    fh_remote,
                    f'test -f {rca} && test -f {ica} && '
                    f'openssl x509 -in {rca} -checkend 7776000 >/dev/null 2>&1 && '
                    f'openssl x509 -in {ica} -checkend 7776000 >/dev/null 2>&1 && echo OK',
                    timeout=15,
                )
                if not ok2:
                    return None
                return 'OK' in (out2 or '')
    except subprocess.TimeoutExpired:
        # v10.1.40: a check that RAN OUT OF TIME has told us nothing — it is not a
        # failing monitor. Returning False here made a loaded box report itself sick:
        # every probe above runs on a 2-5s timeout, and on test6 at load ~8 one would
        # intermittently expire, flip its service to 'caution' (some monitors pass,
        # some "fail"), and yellow the Console module card — while the Guard Dog page,
        # reading a 25s cache instead of running the checks live, stayed green. The
        # operator sees a caution, clicks through, and finds nothing wrong.
        # None is the documented third state and every caller already honours it
        # (_compute_guarddog_overall filters `if v is not None`), so the machinery to
        # say "unknown" was always there — this path just bypassed it.
        # Same class as _caddy_validate_config()'s permission-denied carve-out.
        return None
    except Exception:
        return False
    return None


@app.route('/api/guarddog/monitor-health')
@login_required
def guarddog_monitor_health_api():
    """Return health status per individual monitor. Return from cache when we have it (same as health API for fast load)."""
    monitor_ids = [m.strip() for m in request.args.get('ids', '').split(',') if m.strip()]
    cached = _guarddog_page_cache['monitor_result']
    # If cache has all requested ids, return subset immediately
    if cached and monitor_ids and all(mid in cached for mid in monitor_ids):
        subset = {mid: cached[mid] for mid in monitor_ids}
        return jsonify(subset)
    # Cold or partial: ensure full cache then return subset
    if not cached or not all(mid in cached for mid in monitor_ids):
        _guarddog_refresh_page_cache()
        cached = _guarddog_page_cache['monitor_result'] or {}
    subset = {mid: cached[mid] for mid in monitor_ids if mid in cached}
    return jsonify(subset)


@app.route('/api/guarddog/activity-log')
@login_required
def guarddog_activity_log():
    """Return Guard Dog restarts/alert log entries, optionally filtered by date. Newest first."""
    from_arg = request.args.get('from', '').strip()
    to_arg = request.args.get('to', '').strip()
    date_from = None
    date_to = None
    try:
        if from_arg:
            date_from = datetime.strptime(from_arg, '%Y-%m-%d').date()
        if to_arg:
            date_to = datetime.strptime(to_arg, '%Y-%m-%d').date()
    except ValueError:
        return jsonify({'error': 'Invalid date; use YYYY-MM-DD'}), 400
    log_path = '/var/log/takguard/restarts.log'
    entries = []
    try:
        if not os.path.exists(log_path):
            return jsonify({'entries': [], 'log_path': log_path})
        with open(log_path, 'r') as f:
            lines = f.readlines()
    except (OSError, PermissionError):
        return jsonify({'entries': [], 'error': 'Could not read log file', 'log_path': log_path})
    for raw in reversed(lines):
        raw = raw.rstrip('\n')
        if not raw:
            continue
        parsed_date, display_ts = _parse_guarddog_log_date(raw)
        if date_from is not None and parsed_date is not None and parsed_date < date_from:
            continue
        if date_to is not None and parsed_date is not None and parsed_date > date_to:
            continue
        entries.append({'raw': raw, 'date': parsed_date.isoformat() if parsed_date else None, 'time_display': display_ts})
    return jsonify({'entries': entries, 'log_path': log_path})

@app.route('/api/guarddog/diskio-history')
@login_required
def guarddog_diskio_history():
    """Return disk I/O benchmark history from CSV. Optional ?hours=N (default 24)."""
    try:
        hours = int(request.args.get('hours', 24))
        csv_path = '/var/lib/takguard/diskio_history.csv'
        # v10.0.5 non-root: 0600 root:root — read via the broker (a plain open()
        # EPERMs and 500s the whole panel). None -> treat as "no data yet".
        import io as _io
        hist_text = _read_guarddog_csv_text(csv_path)
        if hist_text is None:
            return jsonify({'entries': [], 'avg_1h': None, 'avg_24h': None})
        import csv as csv_mod
        cutoff = datetime.utcnow() - timedelta(hours=hours)
        entries = []
        reader = csv_mod.DictReader(_io.StringIO(hist_text))
        for row in reader:
            try:
                ts = datetime.strptime(row['timestamp'], '%Y-%m-%dT%H:%M:%SZ')
                if ts >= cutoff:
                    entries.append({'t': row['timestamp'], 'v': float(row['mb_per_sec'])})
            except (ValueError, KeyError):
                continue
        now = datetime.utcnow()
        vals_1h = [e['v'] for e in entries if (now - datetime.strptime(e['t'], '%Y-%m-%dT%H:%M:%SZ')).total_seconds() <= 3600]
        vals_all = [e['v'] for e in entries]
        avg_1h = round(sum(vals_1h) / len(vals_1h), 1) if vals_1h else None
        avg_all = round(sum(vals_all) / len(vals_all), 1) if vals_all else None
        min_val = round(min(vals_all), 1) if vals_all else None
        max_val = round(max(vals_all), 1) if vals_all else None
        # v0.9.54: latency-series parity (4 KB ms/commit). Additive — existing throughput
        # fields above are untouched. Charts ms/commit alongside MB/s; absent on boxes that
        # have not yet run the new probe (lat_* come back null, entries[] is [] → no break).
        lat_entries = []
        lat_path = '/var/lib/takguard/diskio_latency.csv'
        lat_text = _read_guarddog_csv_text(lat_path)
        if lat_text is not None:
            for row in csv_mod.DictReader(_io.StringIO(lat_text)):
                try:
                    ts = datetime.strptime(row['timestamp'], '%Y-%m-%dT%H:%M:%SZ')
                    if ts >= cutoff:
                        lat_entries.append({'t': row['timestamp'],
                                            'ms': float(row['ms_per_commit']),
                                            'kbps': float(row['kb_per_sec'])})
                except (ValueError, KeyError):
                    continue
        lat_1h = [e['ms'] for e in lat_entries if (now - datetime.strptime(e['t'], '%Y-%m-%dT%H:%M:%SZ')).total_seconds() <= 3600]
        lat_all = [e['ms'] for e in lat_entries]
        lat_avg_1h = round(sum(lat_1h) / len(lat_1h), 2) if lat_1h else None
        lat_avg_24h = round(sum(lat_all) / len(lat_all), 2) if lat_all else None
        return jsonify({'entries': entries, 'avg_1h': avg_1h, 'avg_24h': avg_all,
                        'min': min_val, 'max': max_val, 'samples': len(entries),
                        'latency': lat_entries, 'lat_avg_1h': lat_avg_1h, 'lat_avg_24h': lat_avg_24h,
                        'lat_ceiling_ms': _GUARDDOG_LAT_CEILING_MS})
    except Exception as e:
        import traceback
        return jsonify({'entries': [], 'error': f'{type(e).__name__}: {e}', 'traceback': traceback.format_exc()}), 500

# ── v0.9.47: network / fanout metrics (Guard Dog metrics collector → metrics.db) ──
_GD_METRICS_DB = '/var/lib/takguard/metrics.db'
# Whitelist: series key → (table, column). Keys/values are fixed here (never user input),
# so f-string interpolation into SQL is safe — the ?series= param is validated against this map.
_GD_SERIES = {
    'host_tx':          ('host_net',  'tx_bytes_s'),
    'host_rx':          ('host_net',  'rx_bytes_s'),
    'host_tx_pkts':     ('host_net',  'tx_pkts_s'),
    'host_rx_pkts':     ('host_net',  'rx_pkts_s'),
    'tcp_tx_queue':         ('tcp_queue', 'tx_queue_sum'),
    'tcp_tx_queue_max':     ('tcp_queue', 'tx_queue_max'),
    'tcp_tx_queue_active':     ('tcp_queue', 'tx_queue_active'),
    'tcp_tx_queue_active_max': ('tcp_queue', 'tx_queue_active_max'),
    'tcp_stalled_conns':    ('tcp_queue', 'stalled_conns'),
    'tcp_rx_queue':     ('tcp_queue', 'rx_queue_sum'),
    'tcp_conns':        ('tcp_queue', 'conn_count'),
    'clients':          ('marti',     'clients_connected'),
    'heap':             ('marti',     'heap_used_mb'),
    'heap_committed':   ('marti',     'heap_committed_mb'),
    'cpu':              ('host_sys',  'cpu_pct'),
    'mem_used':         ('host_sys',  'mem_used_mb'),
    'load1':            ('host_sys',  'load_1'),
}

def _gd_metrics_ro():
    """Open metrics.db read-only, or None if the collector hasn't produced it yet."""
    import sqlite3
    if not os.path.exists(_GD_METRICS_DB):
        return None
    try:
        return sqlite3.connect(f'file:{_GD_METRICS_DB}?mode=ro', uri=True, timeout=3)
    except Exception:
        return None

def _gd_bucketed(con, table, col, hours, where='', params=(), points=240):
    """Time-bucketed AVG of `col` over the last `hours`, ~`points` samples. Returns entry list."""
    now = int(time.time())
    cutoff = now - hours * 3600
    bucket = max(30, (hours * 3600) // points)
    q = (f"SELECT (ts/{bucket})*{bucket} AS b, AVG({col}) FROM {table} "
         f"WHERE ts >= ? {where} GROUP BY b ORDER BY b")
    rows = con.execute(q, (cutoff,) + tuple(params)).fetchall()
    return [{'t': datetime.utcfromtimestamp(b).strftime('%Y-%m-%dT%H:%M:%SZ'),
             'v': round(v, 2) if v is not None else 0} for b, v in rows]

def _gd_envelope(entries):
    """Mirror the diskio-history envelope: avg_1h / avg_24h / min / max / samples."""
    now = datetime.utcnow()
    vals = [e['v'] for e in entries]
    v1h = [e['v'] for e in entries
           if (now - datetime.strptime(e['t'], '%Y-%m-%dT%H:%M:%SZ')).total_seconds() <= 3600]
    return {
        'entries': entries,
        'avg_1h':  round(sum(v1h) / len(v1h), 2) if v1h else None,
        'avg_24h': round(sum(vals) / len(vals), 2) if vals else None,
        'min': round(min(vals), 2) if vals else None,
        'max': round(max(vals), 2) if vals else None,
        'samples': len(entries),
    }

@app.route('/api/guarddog/net-metrics')
@login_required
def guarddog_net_metrics():
    """One fanout series over the last ?hours=. ?series= ∈ _GD_SERIES keys (default host_tx)."""
    try:
        series = request.args.get('series', 'host_tx')
        hours = max(1, min(168, int(request.args.get('hours', 1))))
        if series not in _GD_SERIES:
            return jsonify({'entries': [], 'error': f'unknown series: {series}'}), 400
        con = _gd_metrics_ro()
        if con is None:
            return jsonify({'entries': [], 'deployed': False})
        try:
            table, col = _GD_SERIES[series]
            entries = _gd_bucketed(con, table, col, hours)
        finally:
            con.close()
        env = _gd_envelope(entries)
        env['series'] = series
        return jsonify(env)
    except Exception as e:
        import traceback
        return jsonify({'entries': [], 'error': f'{type(e).__name__}: {e}', 'traceback': traceback.format_exc()}), 500

@app.route('/api/guarddog/net-metrics/bridges')
@login_required
def guarddog_net_bridges():
    """Per-Docker-bridge (+lo) TX/RX bytes/s over the last ?hours=."""
    try:
        hours = max(1, min(168, int(request.args.get('hours', 1))))
        con = _gd_metrics_ro()
        if con is None:
            return jsonify({'series': [], 'deployed': False})
        try:
            cutoff = int(time.time()) - hours * 3600
            ifaces = con.execute(
                "SELECT iface, MAX(network_name) FROM bridge_net WHERE ts >= ? "
                "GROUP BY iface ORDER BY iface", (cutoff,)).fetchall()
            out = []
            for iface, name in ifaces:
                out.append({
                    'iface': iface, 'network_name': name,
                    'tx': _gd_bucketed(con, 'bridge_net', 'tx_bytes_s', hours,
                                       where='AND iface = ?', params=(iface,)),
                    'rx': _gd_bucketed(con, 'bridge_net', 'rx_bytes_s', hours,
                                       where='AND iface = ?', params=(iface,)),
                })
        finally:
            con.close()
        return jsonify({'series': out})
    except Exception as e:
        import traceback
        return jsonify({'series': [], 'error': f'{type(e).__name__}: {e}', 'traceback': traceback.format_exc()}), 500

@app.route('/api/guarddog/net-metrics/containers')
@login_required
def guarddog_net_containers():
    """Per-container net TX/RX bytes/s over the last ?hours=."""
    try:
        hours = max(1, min(168, int(request.args.get('hours', 1))))
        con = _gd_metrics_ro()
        if con is None:
            return jsonify({'series': [], 'deployed': False})
        try:
            cutoff = int(time.time()) - hours * 3600
            names = con.execute(
                "SELECT container FROM docker_stats WHERE ts >= ? "
                "GROUP BY container ORDER BY container", (cutoff,)).fetchall()
            out = []
            for (name,) in names:
                out.append({
                    'container': name,
                    'tx': _gd_bucketed(con, 'docker_stats', 'net_tx_bytes_s', hours,
                                       where='AND container = ?', params=(name,)),
                    'rx': _gd_bucketed(con, 'docker_stats', 'net_rx_bytes_s', hours,
                                       where='AND container = ?', params=(name,)),
                })
        finally:
            con.close()
        return jsonify({'series': out})
    except Exception as e:
        import traceback
        return jsonify({'series': [], 'error': f'{type(e).__name__}: {e}', 'traceback': traceback.format_exc()}), 500

@app.route('/api/guarddog/diskio-report')
@login_required
def guarddog_diskio_report():
    """Download disk I/O history as a CSV report with summary header."""
    try:
        return _guarddog_diskio_report_inner()
    except Exception as e:
        import traceback
        return f'Error: {type(e).__name__}: {e}\n\n{traceback.format_exc()}', 500, {'Content-Type': 'text/plain'}

def _guarddog_diskio_report_inner():
    hours = int(request.args.get('hours', 72))
    csv_path = '/var/lib/takguard/diskio_history.csv'
    import io as _io
    # v10.0.5 non-root: 0600 root:root — read via the broker, not a plain open().
    hist_text = _read_guarddog_csv_text(csv_path)
    if hist_text is None:
        return 'No disk I/O data available yet.\n', 404, {'Content-Type': 'text/plain'}
    import csv as csv_mod
    cutoff = datetime.utcnow() - timedelta(hours=hours)
    entries = []
    for row in csv_mod.DictReader(_io.StringIO(hist_text)):
        try:
            ts = datetime.strptime(row['timestamp'], '%Y-%m-%dT%H:%M:%SZ')
            if ts >= cutoff:
                entries.append((row['timestamp'], float(row['mb_per_sec'])))
        except (ValueError, KeyError):
            continue
    if not entries:
        return 'No data in the requested time range.\n', 404, {'Content-Type': 'text/plain'}
    vals = [e[1] for e in entries]
    now = datetime.utcnow()
    vals_1h = [e[1] for e in entries if (now - datetime.strptime(e[0], '%Y-%m-%dT%H:%M:%SZ')).total_seconds() <= 3600]
    avg_1h = round(sum(vals_1h) / len(vals_1h), 1) if vals_1h else 'N/A'
    avg_all = round(sum(vals) / len(vals), 1)
    hostname = subprocess.run(['hostname'], capture_output=True, text=True, timeout=5).stdout.strip()
    server_id = 'unknown'
    try:
        with open('/opt/tak-guarddog/server_identifier', 'r') as f:
            server_id = f.read().strip()
    except Exception:
        server_id = hostname
    import io
    output = io.StringIO()
    output.write(f'# Disk I/O Performance Report\n')
    output.write(f'# Server: {server_id}\n')
    output.write(f'# Generated: {now.strftime("%Y-%m-%dT%H:%M:%SZ")}\n')
    output.write(f'# Period: last {hours} hours ({len(entries)} readings)\n')
    output.write(f'# 1h average: {avg_1h} MB/s\n')
    output.write(f'# {hours}h average: {avg_all} MB/s\n')
    output.write(f'# Min: {round(min(vals), 1)} MB/s | Max: {round(max(vals), 1)} MB/s\n')
    # v0.9.54: small-block commit-latency summary — the regime that matches the provider's
    # 4 KB numbers and Postgres commits (a throttled disk reads 80 MB/s sequentially while
    # a 4 KB fsync takes 16 ms). Header-only; data rows below stay the throughput series.
    lat_path = '/var/lib/takguard/diskio_latency.csv'
    lat_text = _read_guarddog_csv_text(lat_path)
    if lat_text is not None:
        lat_vals = []
        for row in csv_mod.DictReader(_io.StringIO(lat_text)):
            try:
                ts = datetime.strptime(row['timestamp'], '%Y-%m-%dT%H:%M:%SZ')
                if ts >= cutoff:
                    lat_vals.append(float(row['ms_per_commit']))
            except (ValueError, KeyError):
                continue
        if lat_vals:
            output.write(f'# Commit latency (4 KB sync): {hours}h average {round(sum(lat_vals)/len(lat_vals), 2)} ms/commit '
                         f'| Min {round(min(lat_vals), 2)} | Max {round(max(lat_vals), 2)} ms (ceiling 10 ms)\n')
    output.write(f'#\n')
    output.write('timestamp,mb_per_sec\n')
    for ts, v in entries:
        output.write(f'{ts},{v}\n')
    csv_data = output.getvalue()
    fn = f'diskio-report-{server_id}-{now.strftime("%Y%m%d-%H%M")}.csv'
    return csv_data, 200, {
        'Content-Type': 'text/csv',
        'Content-Disposition': f'attachment; filename="{fn}"'
    }

def _guarddog_timer_list():
    """All Guard Dog timer unit names (core + optional service monitors)."""
    return ['tak8089guard.timer', 'takoomguard.timer', 'takdiskguard.timer', 'takdiskioguard.timer',
            'takdbguard.timer', 'takcotdbguard.timer', 'taknetguard.timer', 'takrelayguard.timer',
            'takwerxsetupapwatch.timer',
            'takprocessguard.timer', 'takcertguard.timer', 'takintcaguard.timer',
            'takauthentikguard.timer', 'takauthentiktasklogpurge.timer',
            'takdbrepack.timer', 'takretentionguard.timer',
            'takmediamtxguard.timer', 'taknoderedguard.timer', 'takfeedsourceguard.timer', 'takcloudtakguard.timer',
            'taktakportalguard.timer', 'takfedhubguard.timer']

GUARDDOG_DISKIO_TIMER = 'takdiskioguard.timer'


def _guarddog_diskio_monitor_enabled(settings=None):
    """Whether the disk I/O benchmark timer should run (default True). Stored in settings.json."""
    if settings is None:
        settings = load_settings()
    v = settings.get('guarddog_diskio_monitor_enabled')
    if v is None:
        return True
    return bool(v)


def _guarddog_diskio_email_enabled(settings=None):
    """Whether disk I/O degradation sends email/SMS (default True). Benchmark still runs if disabled."""
    if settings is None:
        settings = load_settings()
    v = settings.get('guarddog_diskio_email_enabled')
    if v is None:
        return True
    return bool(v)


def _guarddog_sync_diskio_email_off_file(settings=None):
    """Create/remove diskio_email_off so tak-diskio-watch.sh skips notifications only."""
    if not os.path.exists('/opt/tak-guarddog'):
        return
    if settings is None:
        settings = load_settings()
    path = '/opt/tak-guarddog/diskio_email_off'
    if not _guarddog_diskio_email_enabled(settings):
        try:
            _write_priv(path, '')   # v10.0.5 non-root: /opt/tak-guarddog is root-owned
        except Exception:
            pass
    else:
        subprocess.run(_sudo_wrap(['rm', '-f', path]), capture_output=True)


def _guarddog_apply_diskio_timer(settings=None):
    """Enable or disable takdiskioguard.timer per settings. No-op if Guard Dog not installed or globally disabled."""
    if not os.path.exists('/opt/tak-guarddog'):
        return
    if not _guarddog_is_enabled():
        return
    if settings is None:
        settings = load_settings()
    if _guarddog_diskio_monitor_enabled(settings):
        subprocess.run(_sudo_wrap(['systemctl', 'enable', '--now', GUARDDOG_DISKIO_TIMER]), capture_output=True, text=True, timeout=15)
    else:
        subprocess.run(_sudo_wrap(['systemctl', 'stop', GUARDDOG_DISKIO_TIMER]), capture_output=True, timeout=8)
        subprocess.run(_sudo_wrap(['systemctl', 'disable', GUARDDOG_DISKIO_TIMER]), capture_output=True, timeout=8)


def _guarddog_is_enabled():
    """True if Guard Dog timers are enabled (at least the core 8089 timer)."""
    r = subprocess.run(_sudo_wrap(['systemctl', 'is-enabled', 'tak8089guard.timer']), capture_output=True, text=True, timeout=5)
    return r.returncode == 0 and r.stdout.strip() == 'enabled'

@app.route('/api/guarddog/disable', methods=['POST'])
@login_required
def guarddog_disable():
    """Stop and disable all Guard Dog timers and health service. Scripts stay installed; user can enable again."""
    if not os.path.exists('/opt/tak-guarddog'):
        return jsonify({'error': 'Guard Dog is not installed'}), 400
    for t in _guarddog_timer_list():
        subprocess.run(_sudo_wrap(['systemctl', 'stop', t]), capture_output=True, timeout=5)
        subprocess.run(_sudo_wrap(['systemctl', 'disable', t]), capture_output=True, timeout=5)
    subprocess.run(_sudo_wrap(['systemctl', 'stop', 'tak-health.service']), capture_output=True, timeout=5)
    subprocess.run(_sudo_wrap(['systemctl', 'disable', 'tak-health.service']), capture_output=True, timeout=5)
    return jsonify({'success': True, 'enabled': False})

@app.route('/api/guarddog/enable', methods=['POST'])
@login_required
def guarddog_enable():
    """Enable and start all Guard Dog timers and health service."""
    if not os.path.exists('/opt/tak-guarddog'):
        return jsonify({'error': 'Guard Dog is not installed'}), 400
    subprocess.run(_sudo_wrap(['systemctl', 'daemon-reload']), capture_output=True, timeout=10)
    for t in _guarddog_timer_list():
        subprocess.run(_sudo_wrap(['systemctl', 'enable', t]), capture_output=True, timeout=5)
        subprocess.run(_sudo_wrap(['systemctl', 'start', t]), capture_output=True, timeout=5)
    subprocess.run(_sudo_wrap(['systemctl', 'enable', 'tak-health.service']), capture_output=True, timeout=5)
    subprocess.run(_sudo_wrap(['systemctl', 'start', 'tak-health.service']), capture_output=True, timeout=5)
    _s = load_settings()
    _auto_harden_guarddog_8080(_s)   # v0.9.12 A6
    _guarddog_apply_diskio_timer(_s)
    _guarddog_sync_diskio_email_off_file(_s)
    return jsonify({'success': True, 'enabled': True})

@app.route('/api/guarddog/diskio-monitor', methods=['POST'])
@login_required
def guarddog_diskio_monitor_save():
    """Save disk I/O benchmark on/off and/or email/SMS for disk I/O alerts; sync systemd + diskio_email_off file."""
    if not os.path.exists('/opt/tak-guarddog'):
        return jsonify({'success': False, 'error': 'Guard Dog is not installed'}), 400
    data = request.json or {}
    if 'enabled' not in data and 'email_enabled' not in data:
        return jsonify({'success': False, 'error': 'Provide enabled and/or email_enabled (booleans)'}), 400
    settings = load_settings()
    if 'enabled' in data:
        if not isinstance(data['enabled'], bool):
            return jsonify({'success': False, 'error': 'enabled must be a boolean'}), 400
        settings['guarddog_diskio_monitor_enabled'] = data['enabled']
    if 'email_enabled' in data:
        if not isinstance(data['email_enabled'], bool):
            return jsonify({'success': False, 'error': 'email_enabled must be a boolean'}), 400
        settings['guarddog_diskio_email_enabled'] = data['email_enabled']
    save_settings(settings)
    _guarddog_apply_diskio_timer(settings)
    _guarddog_sync_diskio_email_off_file(settings)
    return jsonify({
        'success': True,
        'enabled': _guarddog_diskio_monitor_enabled(settings),
        'email_enabled': _guarddog_diskio_email_enabled(settings),
    })

@app.route('/api/guarddog/apply-docker-log-limits', methods=['POST'])
@login_required
def guarddog_apply_docker_log_limits():
    """Apply Docker log limits (50m × 3 per container) so Node-RED/Authentik etc. cannot fill the disk. No redeploy needed."""
    restarted, err = _ensure_docker_log_limits()
    if err:
        return jsonify({'success': False, 'error': err}), 500
    return jsonify({
        'success': True,
        'docker_restarted': restarted,
        'message': 'Docker log limits applied (50 MB × 3 files per container).' + (' Docker was restarted — start other containers from their pages if needed.' if restarted else ' Limits were already set.')
    })

@app.route('/api/guarddog/update', methods=['POST'])
@login_required
@_records_module_update('guarddog', to_fn=lambda: VERSION)  # v10.2.8 W10
def guarddog_update():
    """Re-deploy Guard Dog scripts and timers from latest console version."""
    if not os.path.exists('/opt/tak-guarddog'):
        return jsonify({'success': False, 'error': 'Guard Dog not installed'}), 400
    try:
        _auto_update_guarddog()
        # v10.2.25 (ops #132): two-server — the Server One health agent rides the Update too.
        try:
            _ha_cfg = _get_tak_deployment_config(load_settings())
            _ha_s1 = _ha_cfg.get('server_one', {})
            _ha_key = (_ha_s1.get('ssh_key_path') or '').strip()
            if (_ha_cfg.get('mode') == 'two_server' and (_ha_s1.get('host') or '').strip()
                    and _ha_key and os.path.exists(os.path.expanduser(_ha_key))):
                _ha_changed, _ha_msg = _refresh_health_agent_on_server_one(_ha_s1)
                print(f'[guarddog] Server One health agent: {_ha_msg}', flush=True)
        except Exception as _ha_err:
            print(f'[guarddog] Server One health agent refresh failed (non-fatal): {_ha_err}', flush=True)
        # Ensure update-check units exist and are enabled.
        # v10.1.69 W5: this block used to WRITE takupdatesguard.service/.timer. It now
        # removes them — see _startup_retire_updates_timer(), which is the primary path
        # (startup, so it rides the console update). Called here too so a Guard Dog deploy
        # cannot silently reinstate what startup removed.
        try:
            _startup_retire_updates_timer()
        except Exception as _rt_err:
            print(f'[guarddog] retire updates timer failed (non-fatal): {_rt_err}', flush=True)
        # Auto-vacuum timer (daily 3am) — install if script exists but timer doesn't
        av_script = '/opt/tak-guarddog/tak-auto-vacuum.sh'
        av_svc_path = '/etc/systemd/system/takautovacuum.service'
        av_tmr_path = '/etc/systemd/system/takautovacuum.timer'
        if os.path.isfile(av_script) and not os.path.isfile(av_tmr_path):
            _settings = load_settings()
            _tak_cfg = _get_tak_deployment_config(_settings)
            _is_two = _tak_cfg.get('mode') == 'two_server'
            _after = 'network-online.target' if _is_two else _PG_SVC_AFTER
            _write_priv(av_svc_path, f'[Unit]\nDescription=Guard Dog Smart Auto-VACUUM\nAfter={_after}\n\n[Service]\nType=oneshot\nExecStart={av_script}\n')
            _write_priv(av_tmr_path, '[Unit]\nDescription=Run smart auto-VACUUM daily at 3am\n\n[Timer]\nOnCalendar=*-*-* 03:00:00\nPersistent=true\nUnit=takautovacuum.service\n\n[Install]\nWantedBy=timers.target\n')
        # CoT DB size timer — install for two-server if missing
        cotdb_svc_path = '/etc/systemd/system/takcotdbguard.service'
        cotdb_tmr_path = '/etc/systemd/system/takcotdbguard.timer'
        if os.path.isfile('/opt/tak-guarddog/tak-cotdb-watch.sh') and not os.path.isfile(cotdb_tmr_path):
            _settings2 = load_settings()
            _tak_cfg2 = _get_tak_deployment_config(_settings2)
            _is_two2 = _tak_cfg2.get('mode') == 'two_server'
            _after2 = 'network-online.target' if _is_two2 else _PG_SVC_AFTER
            _write_priv(cotdb_svc_path, f'[Unit]\nDescription=TAK CoT Database Size Monitor\nAfter={_after2}\n\n[Service]\nType=oneshot\nExecStart=/opt/tak-guarddog/tak-cotdb-watch.sh\n')
            _write_priv(cotdb_tmr_path, '[Unit]\nDescription=Run TAK CoT DB size monitor every 6 hours\n\n[Timer]\nOnBootSec=30min\nOnUnitActiveSec=6h\nUnit=takcotdbguard.service\n\n[Install]\nWantedBy=timers.target\n')
        # DB repack timer (weekly Sunday 4am) — install if script exists but timer doesn't
        rp_script = '/opt/tak-guarddog/tak-db-repack.sh'
        rp_svc_path = '/etc/systemd/system/takdbrepack.service'
        rp_tmr_path = '/etc/systemd/system/takdbrepack.timer'
        if os.path.isfile(rp_script) and not os.path.isfile(rp_tmr_path):
            _settings3 = load_settings()
            _tak_cfg3 = _get_tak_deployment_config(_settings3)
            _is_two3 = _tak_cfg3.get('mode') == 'two_server'
            _after3 = 'network-online.target' if _is_two3 else _PG_SVC_AFTER
            _write_priv(rp_svc_path, f'[Unit]\nDescription=Guard Dog Online DB Repack (pg_repack)\nAfter={_after3}\n\n[Service]\nType=oneshot\nTimeoutStartSec=3600\nExecStart={rp_script}\n')
            _write_priv(rp_tmr_path, '[Unit]\nDescription=Run online DB repack weekly (Sunday 4am)\n\n[Timer]\nOnCalendar=Sun *-*-* 04:00:00\nPersistent=true\nUnit=takdbrepack.service\n\n[Install]\nWantedBy=timers.target\n')
        # Retention guard timer (every 15min) — install if script exists but timer doesn't
        rg_script = '/opt/tak-guarddog/tak-retention-guard.sh'
        rg_svc_path = '/etc/systemd/system/takretentionguard.service'
        rg_tmr_path = '/etc/systemd/system/takretentionguard.timer'
        if os.path.isfile(rg_script) and not os.path.isfile(rg_tmr_path):
            _settings4 = load_settings()
            _tak_cfg4 = _get_tak_deployment_config(_settings4)
            _is_two4 = _tak_cfg4.get('mode') == 'two_server'
            _after4 = 'network-online.target' if _is_two4 else _PG_SVC_AFTER
            _write_priv(rg_svc_path, f'[Unit]\nDescription=Guard Dog CoT Retention Safety Net\nAfter={_after4}\n\n[Service]\nType=oneshot\nTimeoutStartSec=1800\nExecStart={rg_script}\n')
            _write_priv(rg_tmr_path, '[Unit]\nDescription=Run CoT retention guard every 15 minutes\n\n[Timer]\nOnBootSec=10min\nOnUnitActiveSec=15min\nUnit=takretentionguard.service\n\n[Install]\nWantedBy=timers.target\n')
        # Build-cache reclaim timer (daily 4:30am) — install if script exists but timer doesn't.
        # Cross-platform (docker + df only); no DB/SSH placeholders, no After= DB ordering.
        bc_script = '/opt/tak-guarddog/tak-buildcache-reclaim.sh'
        bc_svc_path = '/etc/systemd/system/takbuildcachereclaim.service'
        bc_tmr_path = '/etc/systemd/system/takbuildcachereclaim.timer'
        if os.path.isfile(bc_script) and not os.path.isfile(bc_tmr_path):
            _write_priv(bc_svc_path, f'[Unit]\nDescription=Guard Dog Docker build-cache reclaim (disk-capacity hygiene)\nAfter=docker.service\n\n[Service]\nType=oneshot\nExecStart={bc_script}\n')
            _write_priv(bc_tmr_path, '[Unit]\nDescription=Run Docker build-cache reclaim hourly (disk-capacity hygiene)\n\n[Timer]\nOnBootSec=45min\nOnUnitActiveSec=1h\nUnit=takbuildcachereclaim.service\n\n[Install]\nWantedBy=timers.target\n')
        # TAK Portal timer — install if script exists but timer doesn't
        tp_script = '/opt/tak-guarddog/tak-takportal-watch.sh'
        tp_svc_path = '/etc/systemd/system/taktakportalguard.service'
        tp_tmr_path = '/etc/systemd/system/taktakportalguard.timer'
        if os.path.isfile(tp_script) and not os.path.isfile(tp_tmr_path):
            _write_priv(tp_svc_path, f'[Unit]\nDescription=Guard Dog TAK Portal Monitor\n\n[Service]\nType=oneshot\nExecStart={tp_script}\n')
            _write_priv(tp_tmr_path, '[Unit]\nDescription=Run TAK Portal guard every 1 minute\n\n[Timer]\nOnBootSec=15min\nOnUnitActiveSec=1min\nUnit=taktakportalguard.service\n\n[Install]\nWantedBy=timers.target\n')
        # Authentik task log purge timer — install if Authentik is present but timer doesn't exist yet
        _ak_tl_svc_path = '/etc/systemd/system/takauthentiktasklogpurge.service'
        _ak_tl_tmr_path = '/etc/systemd/system/takauthentiktasklogpurge.timer'
        _ak_tl_script   = '/opt/tak-guarddog/tak-authentik-tasklog-purge.sh'
        _ak_compose_path = os.path.expanduser('~/authentik/docker-compose.yml')
        if os.path.exists(_ak_compose_path) and not os.path.isfile(_ak_tl_tmr_path):
            # v0.9.26: script body comes from the canonical _AUTHENTIK_TASKLOG_PURGE_SCRIPT
            # constant (see app.py around line 33985). Fixed the v0.9.5 VACUUM-in-transaction
            # bug + replaced the 30-day-only window with a 7d → 24h → 1h tier ladder.
            _write_priv(_ak_tl_script, _AUTHENTIK_TASKLOG_PURGE_SCRIPT, perm=0o755)
            _write_priv(_ak_tl_svc_path, '[Unit]\nDescription=Guard Dog Authentik Task Log Purge\n\n[Service]\nType=oneshot\nExecStart=/opt/tak-guarddog/tak-authentik-tasklog-purge.sh\n')
            _write_priv(_ak_tl_tmr_path, '[Unit]\nDescription=Purge Authentik task logs weekly (Sunday 03:00)\n\n[Timer]\nOnCalendar=Sun *-*-* 03:00:00\nPersistent=true\nUnit=takauthentiktasklogpurge.service\n\n[Install]\nWantedBy=timers.target\n')
        subprocess.run(_sudo_wrap(['systemctl', 'daemon-reload']), capture_output=True, timeout=10)
        new_timers = []   # v10.1.69 W5: takupdatesguard.timer retired (duplicate emails)
        if os.path.isfile(av_tmr_path):
            new_timers.append('takautovacuum.timer')
        if os.path.isfile(cotdb_tmr_path):
            new_timers.append('takcotdbguard.timer')
        if os.path.isfile(rp_tmr_path):
            new_timers.append('takdbrepack.timer')
        # v10.1.1 (F8): takretentionguard.timer was WRITTEN by run_guarddog_deploy but
        # never added to the enable list, so every full deploy left it loaded/disabled
        # and it never ran once (test6: cot_router bloated to 53GB / 2.9k live rows —
        # the "deletes don't return disk" pathology the online repack is meant to cure).
        if os.path.isfile(rg_tmr_path):
            new_timers.append('takretentionguard.timer')
        if os.path.isfile(bc_tmr_path):
            new_timers.append('takbuildcachereclaim.timer')
        if os.path.isfile(tp_tmr_path):
            new_timers.append('taktakportalguard.timer')
        if os.path.isfile(_ak_tl_tmr_path):
            new_timers.append('takauthentiktasklogpurge.timer')
        for t in new_timers:
            subprocess.run(_sudo_wrap(['systemctl', 'enable', '--now', t]), capture_output=True, text=True, timeout=10)
        # Stamp deployed version + settings so UI knows when re-deploy is needed
        try:
            _s = load_settings()
            _s['guarddog_deployed_version'] = VERSION
            _s['guarddog_deployed_email'] = (_s.get('guarddog_alert_email') or '').strip()
            _s['guarddog_deployed_nickname'] = (_s.get('guarddog_server_nickname') or '').strip()
            save_settings(_s)
        except Exception:
            pass
        # Refresh Guard Dog monitor cache so UI flips without waiting for background refresh.
        _guarddog_refresh_page_cache()
        _su = load_settings()
        _guarddog_apply_diskio_timer(_su)
        _guarddog_sync_diskio_email_off_file(_su)
        return jsonify({'success': True, 'message': 'Guard Dog scripts updated, timers installed, and reloaded.'})
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)[:300]}), 500


@app.route('/api/guarddog/uninstall', methods=['POST'])
@login_required
def guarddog_uninstall():
    data = request.json or {}
    password = data.get('password', '')
    auth = load_auth()
    if not auth.get('password_hash') or not check_password_hash(auth['password_hash'], password):
        return jsonify({'error': 'Invalid admin password'}), 403
    timers = _guarddog_timer_list()
    for t in timers:
        subprocess.run(_sudo_wrap(['systemctl', 'stop', t]), capture_output=True, timeout=5)
        subprocess.run(_sudo_wrap(['systemctl', 'disable', t]), capture_output=True, timeout=5)
    subprocess.run(_sudo_wrap(['systemctl', 'stop', 'tak-health.service']), capture_output=True, timeout=5)
    subprocess.run(_sudo_wrap(['systemctl', 'disable', 'tak-health.service']), capture_output=True, timeout=5)
    services_extra = ['tak8089guard.service', 'takoomguard.service', 'takdiskguard.service', 'takdiskioguard.service', 'takdbguard.service',
                      'takcotdbguard.service', 'taknetguard.service', 'takprocessguard.service', 'takcertguard.service',
                      'takintcaguard.service',
                      'takauthentikguard.service', 'takmediamtxguard.service', 'taknoderedguard.service', 'takfeedsourceguard.service', 'takcloudtakguard.service', 'taktakportalguard.service', 'tak-health.service']
    for name in timers + services_extra:
        # v10.0.5 non-root: /etc/systemd/system is root-owned — remove via broker.
        subprocess.run(_sudo_wrap(['rm', '-f', os.path.join('/etc/systemd/system', name)]), capture_output=True)
    if os.path.exists('/opt/tak-guarddog'):
        subprocess.run(_sudo_wrap(['rm', '-rf', '/opt/tak-guarddog']), capture_output=True, timeout=30)
    subprocess.run(_sudo_wrap(['systemctl', 'daemon-reload']), capture_output=True, timeout=10)
    return jsonify({'success': True})

# ── v10.1.30: notification pause (operator-requested 2026-08-12) ──────────────
# ONE switch muting Guard Dog email + SMS, with an optional auto-resume. Guard Dog
# keeps monitoring the whole time and the console keeps showing alerts on screen —
# this suppresses DELIVERY only, so a paused box is quiet, not blind.
#
# Enforced inside the two send helpers rather than at each call site. There are
# five senders today (the two localhost script routes, the AK/PG watchdog, the
# pending-update notifier, and the test buttons) and a sixth will get added by
# someone who has never read this comment; gating the helper makes "paused" the
# default for anything new. The test buttons pass force=True — a test that stays
# silent while paused is indistinguishable from a broken relay, which is exactly
# when an operator reaches for it.
_GD_PAUSE_DURATIONS = {'1h': 1, '4h': 4, '24h': 24}


def _gd_alerts_pause_state(settings=None):
    """Effective pause state: (paused: bool, until_iso: str). '' until = indefinite.

    PURE — never writes. An elapsed snooze reports not-paused rather than being
    cleared on read, so the expiry needs no writer, cannot race two workers against
    each other, and cannot leave a box muted because a cleanup write failed.

    An unparseable `until` reports NOT paused. A corrupt timestamp must never be
    able to silence a box forever; the failure direction has to be toward noise."""
    from datetime import timezone as _tz
    s = settings if settings is not None else load_settings()
    if not s.get('guarddog_alerts_paused'):
        return False, ''
    until = (s.get('guarddog_alerts_paused_until') or '').strip()
    if not until:
        return True, ''                      # indefinite — until the operator resumes
    try:
        dt = datetime.fromisoformat(until.replace('Z', '+00:00'))
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=_tz.utc)
    except Exception:
        return False, ''
    if datetime.now(_tz.utc) >= dt:
        return False, until                  # snooze elapsed — auto-resumed
    return True, until


# ── ops #228: quiet window — hold alert delivery while planned work runs ──────
# 2026-10-25: 25 of the 27 emails the dev fleet's Guard Dog sent in 14 hours were our own
# work — T&E plugin rounds (a TAK Portal marketplace install recreates CloudTAK, so
# "CloudTAK repaired automatically"), an Update/rollback drill (Guard Dog restarted CloudTAK
# and TAK Portal mid-rollback, so two "restarted" alarms), dev deploys. A customer's own
# Update Now trips the same watchers.
#
# Three signals open a window. Each carries its own hard expiry, so a run that dies cannot
# leave a box muted:
#   - GD_QUIET_MARKER "<start> <end> <reason>", written by /opt/tak-guarddog/gd-quiet.sh
#     (T&E, drills, box tests). Root-owned in Guard Dog's state dir, like the Authentik
#     update marker: anyone who can write it can mute Guard Dog. Ignored once past its end,
#     and ignored outright if it asks for more than GD_QUIET_MAX_S.
#   - the Update Now single-flight lock (cleared when post-update finishes; 20-min TTL);
#   - the Authentik update marker (#167; 30-min cap).
#
# HELD is not the operator's pause. The pause mutes on purpose; a window must not hide a
# real fault. So: (1) send-alert-email.sh exits 3 on a held alert, and the watchers that
# gate their once-per-episode state on delivery keep the episode open and alert after the
# window if the fault is still there; (2) every held alert is recorded, and when the window
# closes the console re-runs Guard Dog's checks, again GD_QUIET_SETTLE_S later, and if a
# check is still failing sends ONE email naming it and the alerts that were held
# (_gd_quiet_review_once). A fault the planned work caused and cleared costs nothing; a
# fault that outlives the window is still reported.
GD_QUIET_MARKER = '/var/lib/takguard/quiet_window'
GD_QUIET_MAX_S = 4 * 3600                # gd-quiet.sh MAX_MIN
_GD_QUIET_UPDATE_LOCK = '/var/lib/takwerx-console/update-now.lock'
_GD_QUIET_UPDATE_LOCK_TTL_S = 1200       # update_apply() _update_lock_ttl_s
_GD_QUIET_AK_MARKER = '/var/lib/takguard/authentik_update_in_progress'   # _GD_AUTHENTIK_UPDATE_MARKER
_GD_QUIET_AK_MAX_S = 1800                # _GD_AUTHENTIK_UPDATE_MAX_S
GD_QUIET_REVIEW_EVERY_S = 60
GD_QUIET_SETTLE_S = 600                  # close-out: a check must still be failing this long after
_gd_quiet_lock = threading.Lock()


def _gd_quiet_held_path():
    return os.path.join(CONFIG_DIR, 'guarddog_quiet_held.json')


def _gd_quiet_state(now=None):
    """Effective quiet window: (active: bool, until_epoch: int, reason: str).

    PURE — reads only, like _gd_alerts_pause_state(). Anything unreadable, unparseable,
    expired or over-long reports NOT quiet: the failure direction is toward noise."""
    now = time.time() if now is None else now
    best = [False, 0, '']

    def _consider(until, reason):
        if until > now and until > best[1]:
            best[:] = [True, int(until), reason]
    try:
        with open(GD_QUIET_MARKER) as f:
            parts = f.read(512).split(None, 2)
        start, end = int(parts[0]), int(parts[1])
        reason = ' '.join((parts[2] if len(parts) > 2 else '').split())[:120] or 'planned work'
        if start <= now + 60 and 0 < end - start <= GD_QUIET_MAX_S:
            _consider(end, reason)
    except Exception:
        pass
    for path, ttl, reason in ((_GD_QUIET_UPDATE_LOCK, _GD_QUIET_UPDATE_LOCK_TTL_S, 'Update Now in progress'),
                              (_GD_QUIET_AK_MARKER, _GD_QUIET_AK_MAX_S, 'Authentik update in progress')):
        try:
            _consider(os.path.getmtime(path) + ttl, reason)
        except Exception:
            pass
    return tuple(best)


def _gd_quiet_held_load():
    try:
        with open(_gd_quiet_held_path()) as f:
            d = json.load(f)
        return d if isinstance(d, dict) else {}
    except Exception:
        return {}


def _gd_quiet_held_save(d):
    tmp = None
    try:
        os.makedirs(CONFIG_DIR, exist_ok=True)
        fd, tmp = tempfile.mkstemp(dir=CONFIG_DIR, prefix='.gd-quiet-', suffix='.tmp')
        with os.fdopen(fd, 'w') as f:
            json.dump(d, f)
        os.chmod(tmp, 0o600)
        os.replace(tmp, _gd_quiet_held_path())
    except Exception as e:
        if tmp:
            try:
                os.unlink(tmp)
            except Exception:
                pass
        print(f"[guarddog] quiet window: could not record a held alert ({str(e)[:120]})", flush=True)


def _gd_quiet_hold(subject, state=None):
    """Record one alert held by the quiet window, for the close-out review."""
    _a, until, reason = state or _gd_quiet_state()
    print(f"[guarddog] alert HELD — quiet window ({reason}) until "
          f"{datetime.utcfromtimestamp(until).strftime('%H:%M:%SZ') if until else '?'}: {subject}",
          flush=True)
    with _gd_quiet_lock:
        rec = _gd_quiet_held_load()
        held = rec.get('held') if isinstance(rec.get('held'), list) else []
        held.append({'at': int(time.time()), 'subject': str(subject or '')[:200], 'reason': reason})
        rec['held'] = held[-50:]
        _gd_quiet_held_save(rec)


def _gd_quiet_failing():
    _guarddog_refresh_page_cache()
    health = _guarddog_page_cache.get('health') or {}
    return {k: v for k, v in health.items() if v != 'ok'}


def _gd_quiet_review_once(now=None):
    """Close-out of a quiet window that held alerts. Returns 'open' | 'none' | 'settling' |
    'clear' | 'sent' | 'not-sent'.

    Re-runs Guard Dog's health checks rather than replaying the held alerts: a replay would
    re-send exactly the noise the window exists to hold (a restart during a drill is over
    by now), while a check that is still failing is the fault the window must not hide.

    Two looks, GD_QUIET_SETTLE_S apart. Right after the window closes the box is often
    still settling — nuc, 2026-10-25: a console restart, then the close-out 60 s later
    found a check not yet OK and mailed. Update Now ends exactly like that on every box.
    Only a check that is not OK at the close AND still not OK after the settle is reported;
    a new fault after the close is not held, so its own watcher reports it as usual."""
    now = time.time() if now is None else now
    if _gd_quiet_state(now)[0]:
        with _gd_quiet_lock:
            rec = _gd_quiet_held_load()
            if 'closed_at' in rec:           # reopened while settling: settle after this one
                rec.pop('closed_at', None)
                rec.pop('failing', None)
                _gd_quiet_held_save(rec)
        return 'open'
    with _gd_quiet_lock:
        rec = _gd_quiet_held_load()
    held = rec.get('held')
    if not isinstance(held, list) or not held:
        return 'none'
    closed_at = rec.get('closed_at')
    if not isinstance(closed_at, (int, float)):
        first = _gd_quiet_failing()
        if first:
            with _gd_quiet_lock:
                cur = _gd_quiet_held_load()
                cur.update({'closed_at': int(now), 'failing': sorted(first)})
                _gd_quiet_held_save(cur)
            print(f"[guarddog] quiet window closed with {len(held)} held alert(s); not OK right "
                  f"now: {', '.join(f'{k}={v}' for k, v in sorted(first.items()))} — checking "
                  f"again in {GD_QUIET_SETTLE_S // 60} min", flush=True)
            return 'settling'
        failing, health = [], {}
    elif now - closed_at < GD_QUIET_SETTLE_S:
        return 'settling'
    else:
        health = _gd_quiet_failing()
        failing = sorted(set(health) & set(rec.get('failing') or []))
    with _gd_quiet_lock:
        # Drop only what was read above; a hold recorded since (a new window) stays.
        rest = _gd_quiet_held_load().get('held')
        rest = rest[len(held):] if isinstance(rest, list) else []
        _gd_quiet_held_save({'held': rest} if rest else {})
    if not failing:
        print(f"[guarddog] quiet window closed: {len(held)} alert(s) held, every Guard Dog "
              f"check that was not OK at the close is OK now — nothing sent", flush=True)
        return 'clear'
    settings = load_settings()
    to_addr = (settings.get('guarddog_alert_email') or '').strip()
    if not to_addr:
        print("[guarddog] quiet window close-out SUPPRESSED (no recipient configured)", flush=True)
        return 'not-sent'
    ident = _guarddog_server_identifier(settings) or socket.gethostname()
    reasons = sorted({str(h.get('reason') or '') for h in held if h.get('reason')})
    lines = [f"Guard Dog held {len(held)} alert(s) during planned work "
             f"({'; '.join(reasons) or 'quiet window'}). The window ended "
             f"{int((now - closed_at) // 60)} min ago and these Guard Dog checks are still "
             f"not OK:", '']
    lines += [f"  • {k}: {health.get(k)}" for k in failing]
    lines += ['', 'Alerts held during the window:']
    for h in held[-20:]:
        lines.append(f"  {datetime.utcfromtimestamp(int(h.get('at') or 0)).strftime('%Y-%m-%d %H:%M:%SZ')}"
                     f"  {h.get('subject') or ''}")
    if len(held) > 20:
        lines.append(f"  … and {len(held) - 20} earlier")
    lines += ['', 'Open the Guard Dog page in the console for details.', '',
              f"Server: {ident}", f"Time (UTC): {datetime.utcnow().strftime('%Y-%m-%d %H:%M:%S')}"]
    subj = f"Guard Dog: still failing after planned work on {ident}"
    try:
        if _guarddog_send_alert_email_via_relay(to_addr, subj, '\n'.join(lines)):
            print(f"[guarddog] sent: {subj} ({', '.join(failing)})", flush=True)
            return 'sent'
    except Exception as e:
        print(f"[guarddog] quiet window close-out not sent: {e}", flush=True)
    return 'not-sent'


def _gd_quiet_review_loop():
    time.sleep(120)
    while True:
        try:
            _gd_quiet_review_once()
        except Exception as e:
            try:
                print(f"[guarddog] quiet window review failed: {e}", flush=True)
            except Exception:
                pass
        time.sleep(GD_QUIET_REVIEW_EVERY_S)


try:
    threading.Thread(target=_gd_quiet_review_loop, daemon=True, name='gd-quiet-review').start()
except Exception:
    pass


def _guarddog_send_alert_email_via_relay(to_addr, subject, body, force=False):
    """Send email via Email Relay (localhost:25 → Postfix → Brevo). Used by test email and send-alert-email endpoint.

    Returns True if sent, False if suppressed by the notification pause. Raises on
    a genuine send failure, so a suppressed alert is never reported as an error."""
    import smtplib
    from email.mime.text import MIMEText
    if not force:
        paused, until = _gd_alerts_pause_state()
        if paused:
            print(f"[guarddog] alert email suppressed — notifications paused"
                  f"{' until ' + until if until else ' (indefinite)'}: {subject}", flush=True)
            return False
        quiet = _gd_quiet_state()
        if quiet[0]:
            _gd_quiet_hold(subject, quiet)   # ops #228: reviewed when the window closes
            return False
    settings = load_settings()
    relay = settings.get('email_relay', {})
    from_addr = relay.get('from_addr', 'noreply@localhost')
    from_name = relay.get('from_name', 'Guard Dog')
    # to_addr may carry several addresses (comma-joined). Re-validate here rather than
    # trusting the caller: this is the last point before SMTP, and every entry point
    # feeding it is a separate route.
    recipients = _safe_alert_emails(to_addr)
    if not recipients:
        return False
    msg = MIMEText(body or '', 'plain', 'utf-8')
    msg['From'] = f'{from_name} <{from_addr}>'
    msg['To'] = ', '.join(recipients)
    msg['Subject'] = subject or 'Guard Dog Alert'
    with smtplib.SMTP('localhost', 25, timeout=15) as s:
        # One envelope, all recipients — a per-address loop would let a single bad
        # mailbox abort the rest partway through.
        s.sendmail(from_addr, recipients, msg.as_string())
    return True


# ── v10.1.7 WS2: pending-update email notifications ──────────────────────────
# Operator-requested (2026-07-22): nothing proactively said a CloudTAK plugin /
# CloudTAK / console update exists — the badges are computed only on page open.
# Rides the Guard Dog alert-email relay path. De-dup is one email per NEW target
# identity (SHA/tag), never per poll; state in CONFIG_DIR/update_notify_state.json.
UPDATE_NOTIFY_FIRST_DELAY_S = 900     # let the box settle after boot
UPDATE_NOTIFY_INTERVAL_S = 21600      # 6 h between sweeps (fleet constant)


def _update_notify_state_path():
    return os.path.join(CONFIG_DIR, 'update_notify_state.json')


def _update_notify_state_load():
    try:
        with open(_update_notify_state_path()) as f:
            d = json.load(f)
        return d if isinstance(d, dict) else {}
    except Exception:
        return {}


def _update_notify_state_save(state):
    os.makedirs(CONFIG_DIR, exist_ok=True)
    tmp = None
    try:
        fd, tmp = tempfile.mkstemp(dir=CONFIG_DIR, prefix='.update-notify-', suffix='.tmp')
        with os.fdopen(fd, 'w') as f:
            json.dump(state, f, indent=2)
            f.flush()
            os.fsync(f.fileno())
        os.chmod(tmp, 0o600)
        os.replace(tmp, _update_notify_state_path())
    except Exception:
        if tmp:
            try:
                os.unlink(tmp)
            except Exception:
                pass


def _console_pending_update(settings):
    """Pending infra-TAK console update for this box's channel, or None.
    Same comparisons as update_check(), compact and side-effect-free (no cache writes)."""
    import urllib.request
    gh_headers = {'Accept': 'application/vnd.github.v3+json', 'User-Agent': 'infra-TAK'}
    channel = (settings.get('update_channel') or 'main').strip().lower()
    if channel == 'dev':
        req = urllib.request.Request(
            f'https://api.github.com/repos/{GITHUB_REPO}/commits?sha=dev&per_page=1', headers=gh_headers)
        with urllib.request.urlopen(req, timeout=10) as resp:
            data = json.loads(resp.read().decode())
        remote_full = (data[0].get('sha') or '') if data else ''
        try:
            local = subprocess.run(
                ['git', f'--git-dir={os.path.join(os.path.dirname(os.path.abspath(__file__)), ".git")}',
                 'rev-parse', '--short', 'HEAD'],
                capture_output=True, text=True, timeout=5).stdout.strip()
        except Exception:
            local = ''
        if remote_full and not remote_full.startswith(local or 'XXXXXXXX'):
            return {'label': 'infra-TAK console', 'installed': f'v{VERSION} @ {local or "?"}',
                    'target': f'dev@{remote_full[:7]}', 'identity': remote_full[:7]}
        return None
    req = urllib.request.Request(
        f'https://api.github.com/repos/{GITHUB_REPO}/releases/latest', headers=gh_headers)
    with urllib.request.urlopen(req, timeout=10) as resp:
        data = json.loads(resp.read().decode())
    tag = (data.get('tag_name') or '').strip()

    def _vt(v):
        return tuple(int(p) for p in v.lstrip('vV').replace('-alpha', '').replace('-beta', '').split('.'))
    try:
        if tag and _vt(tag) > _vt(VERSION):
            item = {'label': 'infra-TAK console', 'installed': f'v{VERSION}',
                    'target': tag, 'identity': tag,
                    'how': 'Console page → Update Now.'}
            # ops #168: name every security release between what runs here and the
            # target — skipping one (installed .20, security .22, latest .25) still
            # leaves the box exposed. Unreadable release list = unknown, not security.
            try:
                req = urllib.request.Request(
                    f'https://api.github.com/repos/{GITHUB_REPO}/releases?per_page=50', headers=gh_headers)
                with urllib.request.urlopen(req, timeout=10) as resp:
                    rels = json.loads(resp.read().decode())
                sec = []
                for rel in rels if isinstance(rels, list) else []:
                    rtag = (rel.get('tag_name') or '').strip()
                    if rel.get('draft') or not rtag:
                        continue
                    try:
                        if not (_vt(VERSION) < _vt(rtag) <= _vt(tag)):
                            continue
                    except Exception:
                        continue
                    what = _release_security_summary(rel.get('body'))
                    if what:
                        sec.append((_vt(rtag), f'{rtag} is a security release: {what}'))
                item['security'] = [s for _, s in sorted(sec)]
            except Exception as e:
                item['security_unknown'] = True
                print(f"[update-notify] infra-TAK release notes unreadable: {e}", flush=True)
            return item
    except Exception:
        pass
    return None


# ops #168: the ship skill already opens a security release's notes with this headline
# (v10.2.21/22 `## Security release: …`, v10.2.24 `## Security: …`). Only the FIRST
# line counts — a "### Security" section deeper in ordinary notes is not a flag.
_SECURITY_RELEASE_HEADLINE_RE = re.compile(
    r'^\s*#{1,6}\s*[*_]*\s*security(?:\s+release)?\s*[*_]*\s*:\s*[*_]*\s*(.+?)\s*[*_]*\s*$', re.I)


def _release_security_summary(body):
    """What a release fixes when its notes open with the security headline, else None."""
    for ln in (body or '').splitlines():
        if ln.strip():
            m = _SECURITY_RELEASE_HEADLINE_RE.match(ln)
            return m.group(1)[:240] if m else None
    return None


def _semver_tuple(v):
    """'v13.49.0' / '13.49' -> (13, 49, 0); None when it is not plain dotted numbers."""
    m = re.match(r'^\s*v?(\d+(?:\.\d+)*)\s*$', v or '')
    if not m:
        return None
    t = tuple(int(x) for x in m.group(1).split('.'))
    return t + (0,) * (3 - len(t)) if len(t) < 3 else t


def _version_in_range(version, spec):
    """True/False for a GitHub advisory range (`<= 13.49.0`, `>= 1.0, < 1.2.3`),
    None when either side cannot be parsed — the caller must then claim nothing."""
    ver = _semver_tuple(version)
    if ver is None or not (spec or '').strip():
        return None
    ops = {'<': lambda a, b: a < b, '<=': lambda a, b: a <= b, '>': lambda a, b: a > b,
           '>=': lambda a, b: a >= b, '=': lambda a, b: a == b}
    for part in spec.split(','):
        m = re.match(r'^\s*(<=|>=|<|>|=)?\s*(\S+)\s*$', part)
        bound = _semver_tuple(m.group(2)) if m else None
        if bound is None:
            return None
        if not ops[m.group(1) or '='](ver, bound):
            return False
    return True


def _gh_advisories_fixed_by(repo, installed, target):
    """Published GitHub security advisories of `repo` that `installed` is exposed to and
    `target` is not: ['GHSA-… (high): summary', …]. Raises when GitHub cannot be read.
    An advisory whose ranges do not parse is skipped — never claimed."""
    import urllib.request
    req = urllib.request.Request(
        f'https://api.github.com/repos/{repo}/security-advisories?per_page=100',
        headers={'Accept': 'application/vnd.github+json', 'User-Agent': 'infra-TAK'})
    with urllib.request.urlopen(req, timeout=10) as resp:
        advs = json.loads(resp.read().decode())
    out = []
    for a in advs if isinstance(advs, list) else []:
        if a.get('state') not in (None, 'published') or a.get('withdrawn_at'):
            continue
        for v in a.get('vulnerabilities') or []:
            rng = v.get('vulnerable_version_range') or ''
            if _version_in_range(installed, rng) is not True:
                continue
            if _version_in_range(target, rng) is not False:
                continue
            patched = (v.get('patched_versions') or '').strip()
            if patched and _version_in_range(target, patched) is not True:
                continue
            ident = a.get('cve_id') or a.get('ghsa_id') or 'advisory'
            sev = (a.get('severity') or '').lower()
            out.append(f"{ident}{' (' + sev + ')' if sev else ''}: {(a.get('summary') or '').strip()[:160]}")
            break
    return out


# ops #182: security releases a component never published a GitHub advisory for. The
# update notice merges these with the GHSA results, so a box below `fixed_in` gets the
# same security flag a GHSA would give it. Add an entry when a lead/security review
# confirms a release is a security fix; `reason` is shown to the customer as-is.
KNOWN_SECURITY_RELEASES = (
    {'component': 'cloudtak', 'fixed_in': '13.112.2',
     'reason': 'Node.js security fixes CVE-2026-111497 and CVE-2026-106069 '
               '(API image rebuilt on Node 26)'},
    # ops #190: CloudTAK's own GHSA list does not cover a dependency advisory.
    {'component': 'cloudtak', 'fixed_in': '13.113.0',
     'reason': 'body-parser security fix GHSA-27r3-jxmh-p828 (an unauthenticated request '
               'could crash the API)'},
)


def _known_security_fixed_by(component, installed, target):
    """KNOWN_SECURITY_RELEASES entries for `component` that `installed` is below and
    `target` reaches: ['<reason> (fixed in v<fixed_in>)', …]. A version that does not
    parse claims nothing."""
    inst, tgt = _semver_tuple(installed), _semver_tuple(target)
    if inst is None or tgt is None:
        return []
    out = []
    for e in KNOWN_SECURITY_RELEASES:
        fixed = _semver_tuple(e['fixed_in'])
        if e['component'] == component and fixed is not None and inst < fixed <= tgt:
            out.append(f"{e['reason']} (fixed in v{e['fixed_in']})")
    return out


def _apply_security_identity(item):
    """ops #168: a pending version that turns out to be a security release mails once
    more (identity + '+security'); a sweep that could not tell accepts whichever
    identity was already mailed, so a GitHub blip neither re-mails nor drops the flag."""
    base = item['identity']
    if item.get('security'):
        item['identity'] = base + '+security'
    elif item.get('security_unknown'):
        item['seen_ok'] = [base, base + '+security']
    return item


# ops #168: with unattended-upgrades / dnf-automatic applying updates, a fresh security
# patch is normally installed by the next daily run (lists refresh twice a day with up to
# 12 h of random delay; the upgrade runs ~06:00). Mail only what is still pending after
# that window — otherwise every Ubuntu box would get a "you should update" email every
# few days for patches that install themselves. With automatic updates off: next sweep.
OS_SECURITY_AUTO_GRACE_S = 36 * 3600


def _os_security_items(seen, unknown, now=None):
    """Update-email items for this box's OS (ops #168): pending security patches, and a
    security kernel that is installed but not running.

    `seen` is the persisted {name=version: first-seen epoch} map, updated in place.
    A key whose state could not be read this sweep goes into `unknown`, so the
    caller carries its dedup state instead of pruning it (no re-mail after a blip)."""
    now = now or time.time()
    items = []
    try:
        sec = _pending_security_os_updates()
    except Exception as e:
        sec = None
        unknown.add('os-security')
        print(f"[update-notify] OS security check failed: {e}", flush=True)
    if sec is not None:
        pkgs = sec['packages']
        ids = ['%s=%s' % (p['name'], p['new']) for p in pkgs]
        for k in [k for k in seen if k not in ids]:
            del seen[k]
        for k in ids:
            seen.setdefault(k, now)
        posture = _auto_update_posture() if pkgs else {}
        auto = bool(posture.get('applies'))
        due = [(p, k) for p, k in zip(pkgs, ids)
               if not auto or now - seen[k] >= OS_SECURITY_AUTO_GRACE_S]
        if due:
            names = sorted({p['name'] for p, _ in due})
            fixes = ['Packages: ' + ', '.join(names[:10])
                     + (f' (+{len(names) - 10} more)' if len(names) > 10 else '')]
            adv = sec.get('advisories') or []
            if adv:
                fixes.append('Advisories: ' + ', '.join(
                    a['id'] + (f" ({a['severity']})" if a['severity'] else '') for a in adv[:6])
                    + (f' (+{len(adv) - 6} more)' if len(adv) > 6 else ''))
            if auto:
                fixes.append(f"Automatic updates ({posture.get('mechanism') or 'on'}) have not "
                             'installed these for over a day.')
            n = len(due)
            items.append({
                'key': 'os-security', 'label': 'Operating system',
                'installed': f'{n} package{"s" if n != 1 else ""}', 'target': 'security patches',
                'summary': f'Operating system: {n} security patch{"es" if n != 1 else ""} pending',
                'identity': hashlib.sha256('\n'.join(sorted(k for _, k in due)).encode()).hexdigest()[:16],
                'security': fixes,
                'how': 'Console page → "Operating system updates available" → Install updates.'})
    rb = _kernel_reboot_state()
    if rb.get('kernel'):
        try:
            what = _staged_kernel_security(rb)
        except Exception as e:
            what = None
            unknown.add('kernel-security')
            print(f"[update-notify] kernel security check failed: {e}", flush=True)
        if what:
            items.append({
                'key': 'kernel-security', 'label': 'Linux kernel',
                'installed': rb['running'], 'target': rb['staged'],
                'summary': 'Linux kernel: a security fix is installed but not running',
                'identity': rb['sig'],
                'security': [f"Kernel {rb['staged']} ({what}) is installed, but this box is still "
                             f"running {rb['running']} and is not protected until it restarts."],
                'how': 'Console page → Reboot now (the box is back in 1-3 minutes).'})
    return items


def _collect_pending_updates(settings, seen=None, unknown=None):
    """All currently-pending updates as [{key,label,installed,target,identity}], plus
    (ops #168) `security`/`how` on the ones that are security fixes. Read-only; each
    source shielded so one failure never hides the rest. `seen`/`unknown`: see
    _os_security_items."""
    seen = {} if seen is None else seen
    unknown = set() if unknown is None else unknown
    pending = []
    try:
        c = _console_pending_update(settings)
        if c:
            pending.append(_apply_security_identity({**c, 'key': 'console'}))
    except Exception as e:
        print(f"[update-notify] console check failed: {e}", flush=True)
    try:
        if os.path.isdir(os.path.expanduser('~/CloudTAK')):
            info = _get_cloudtak_version_info()
            if info.get('version') and info.get('update_available') and info.get('latest'):
                ct = {'key': 'cloudtak', 'label': 'CloudTAK',
                      'installed': f"v{info['version']}", 'target': f"v{info['latest']}",
                      'identity': str(info['latest']), 'how': 'CloudTAK page → Update.'}
                # ops #168: CloudTAK publishes GitHub advisories with version ranges.
                # ops #182: plus the releases it shipped as security fixes without one.
                known = ['Fixes ' + k for k in _known_security_fixed_by(
                    'cloudtak', info['version'], info['latest'])]
                try:
                    ct['security'] = ['Fixes ' + a for a in _gh_advisories_fixed_by(
                        'dfpc-coe/CloudTAK', info['version'], info['latest'])] + known
                except Exception as e:
                    ct['security_unknown'] = True
                    if known:
                        ct['security'] = known
                    print(f"[update-notify] CloudTAK advisories unreadable: {e}", flush=True)
                pending.append(_apply_security_identity(ct))
    except Exception as e:
        print(f"[update-notify] CloudTAK check failed: {e}", flush=True)
    try:
        pending.extend(_os_security_items(seen, unknown))
    except Exception as e:
        unknown.update({'os-security', 'kernel-security'})
        print(f"[update-notify] OS security check failed: {e}", flush=True)
    try:
        for p in _detect_cloudtak_plugins():
            if p.get('installed') and p.get('update_available') and not p.get('local'):
                ident = p.get('remote_sha') or 'unknown'
                pending.append({'key': f"plugin:{p['key']}",
                                'label': f"CloudTAK plugin “{p['name']}”",
                                'installed': p.get('sha') or '(not built)',
                                'target': f"{ident} ({p.get('channel') or 'main'} channel)",
                                'identity': ident})
    except Exception as e:
        print(f"[update-notify] plugin check failed: {e}", flush=True)
    return pending


def _update_notify_check_once():
    """One pending-update sweep. Emails the Guard Dog alert address only when at least
    one pending item's identity has not been mailed before (one email per new SHA/tag,
    never per poll). Returns {'pending': [...], 'emailed': bool} for the trigger route."""
    settings = load_settings()
    to_addr = _safe_alert_email_list(settings.get('guarddog_alert_email'))
    if not to_addr:
        return {'pending': [], 'emailed': False, 'skipped': 'no alert email configured'}
    if settings.get('guarddog_update_email_enabled') is False:
        return {'pending': [], 'emailed': False, 'skipped': 'update emails disabled'}
    # ops #228: defer — never mark as mailed — while a quiet window is open. Going through
    # the held send below would record this version as notified and lose it for good.
    _q_on, _q_until, _q_why = _gd_quiet_state()
    if _q_on:
        return {'pending': [], 'emailed': False, 'skipped': f'quiet window ({_q_why})',
                'quiet_until': _q_until}
    state = _update_notify_state_load()
    seen = state.get('_os_security_seen')
    seen = dict(seen) if isinstance(seen, dict) else {}
    unknown = set()
    pending = _collect_pending_updates(settings, seen=seen, unknown=unknown)

    def _mailed(p):
        return state.get(p['key']) in (p.get('seen_ok') or [p['identity']])

    new_items = [p for p in pending if not _mailed(p)]
    emailed = False
    if new_items:
        server_id = _guarddog_server_identifier(settings) or socket.gethostname()
        sec_items = [p for p in pending if p.get('security')]
        other = [p for p in pending if not p.get('security')]
        lines = []
        if sec_items:
            # ops #168: say it plainly, say what it fixes, say where to click.
            lines += [f"SECURITY UPDATE: you should update this machine ({server_id}).", '']
            for p in sec_items:
                lines.append(f"  • {p.get('summary') or p['label'] + ': ' + p['installed'] + ' → ' + p['target']}")
                lines += [f"      {s}" for s in p['security']]
                if p.get('how'):
                    lines.append(f"      Fix it from the infra-TAK console: {p['how']}")
                lines.append('')
            if other:
                lines.append('Other pending updates:')
        else:
            lines += [f"The following updates are pending on {server_id}:", '']
        for p in other:
            lines.append(f"  • {p['label']}: {p['installed']} → {p['target']}")
        fqdn = (settings.get('fqdn') or '').split(':')[0].strip() or (settings.get('server_ip') or '').strip()
        port = settings.get('console_port') or 5001
        lines += ['', f"Open the console (https://{fqdn}:{port}) to review and apply.",
                  f"Update channel: {(settings.get('update_channel') or 'main').strip().lower()}",
                  '', 'You get one email per new pending version — not a reminder per sweep.']
        if sec_items:
            subj = f"🔒 Security update pending on {server_id} — update this machine"
        else:
            subj = (f"⬆ Update pending on {server_id}" if len(pending) == 1
                    else f"⬆ {len(pending)} updates pending on {server_id}")
        try:
            _guarddog_send_alert_email_via_relay(to_addr, subj, '\n'.join(lines))
            emailed = True
            print(f"[update-notify] emailed {len(pending)} pending update(s) to {to_addr} "
                  f"({len(new_items)} new)", flush=True)
        except Exception as e:
            print(f"[update-notify] email send failed: {e}", flush=True)
    # Persist ONLY what was successfully mailed (a failed send retries next sweep);
    # prune entries no longer pending so the same target re-mails if it reappears.
    new_state = {p['key']: (state[p['key']] if _mailed(p) else p['identity']) for p in pending}
    # ops #168: a source that could not be read this sweep is not "no longer pending".
    for k in unknown:
        if k in state and k not in new_state:
            new_state[k] = state[k]
    if seen:
        new_state['_os_security_seen'] = seen
    if (emailed or not new_items) and new_state != state:
        _update_notify_state_save(new_state)
    return {'pending': pending, 'emailed': emailed}


def _startup_retire_updates_timer():
    """v10.1.69 W5: remove the legacy takupdatesguard timer/service.

    It ran tak-updates-watch.sh, a SECOND update-notification path that mailed the same
    pending updates as _update_notify_loop() on its own 6 h cycle. Each deduped only
    against itself, so neither could see the other's mail and customers got two emails
    per update set (field report, Charles Laird/NC 2026-09-12 — two subjects 75 min apart
    on two 6 h cycles).

    Runs at STARTUP, not from the Guard Dog deploy route: fixes ride the console update
    ([[feedback-console-path-delivery]]). Idempotent — silent no-op once the units are gone."""
    service_path = '/etc/systemd/system/takupdatesguard.service'
    timer_path = '/etc/systemd/system/takupdatesguard.timer'
    if not (os.path.exists(service_path) or os.path.exists(timer_path)):
        return False
    # mode='seq': disable/stop legitimately fail when a unit is already masked or stopped,
    # and that must not stop the rm — this has to converge on every box.
    _run_priv_chain([
        ['systemctl', 'disable', '--now', 'takupdatesguard.timer'],
        ['systemctl', 'stop', 'takupdatesguard.service'],
        ['rm', '-f', timer_path],
        ['rm', '-f', service_path],
        ['systemctl', 'daemon-reload'],
    ], 'seq', timeout=30)
    # Verify rather than assume — a removal that silently did nothing is exactly how this
    # customer got two emails a day for months.
    if os.path.exists(service_path) or os.path.exists(timer_path):
        print('Startup migration: WARNING legacy takupdatesguard units still present after '
              'removal attempt', flush=True)
        return False
    print('Startup migration: removed legacy takupdatesguard timer/service '
          '(duplicate update emails - v10.1.69 W5)', flush=True)
    return True


def _update_notify_loop():
    time.sleep(UPDATE_NOTIFY_FIRST_DELAY_S)
    while True:
        wait = UPDATE_NOTIFY_INTERVAL_S
        try:
            r = _update_notify_check_once() or {}
            if r.get('quiet_until'):
                # ops #228: deferred by a quiet window — look again once it has settled,
                # not six hours later.
                wait = min(UPDATE_NOTIFY_INTERVAL_S,
                           max(60, int(r['quiet_until'] - time.time()) + UPDATE_NOTIFY_FIRST_DELAY_S))
        except Exception as e:
            try:
                print(f"[update-notify] sweep failed: {e}", flush=True)
            except Exception:
                pass
        time.sleep(wait)


# Start the sweep thread once (daemon; idle-cheap — first sweep 15 min after boot).
try:
    threading.Thread(target=_update_notify_loop, daemon=True, name='update-notify').start()
except Exception:
    pass


@app.route('/api/guarddog/update-notify-check', methods=['POST'])
@login_required
def guarddog_update_notify_check():
    """Run one pending-update sweep now (T&E / support — nobody waits 6 h)."""
    try:
        return jsonify({'success': True, **_update_notify_check_once()})
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)}), 500


_GUARDDOG_SPIRAL_CORR_SENTINEL = '/var/lib/takguard/spiral_correlation_alert_sent'


def _guarddog_spiral_correlation_check(cl_waiting):
    """v0.9.54 §4c: correlate a disk commit-latency stall with real DB demand.

    When the 1h-avg 4 KB commit latency is over the fleet ceiling AND PgBouncer has
    clients waiting (cl_waiting > 0) in the same window, the disk is throttling
    Postgres commits while Authentik genuinely needs the DB — the unambiguous
    fingerprint of provider-disk-contention (the 2026-06-10 test12 incident). Emit a
    distinct, attributed alert BEFORE the outage. Detection/attribution ONLY —
    remediation stays with the existing watchdog/autotune.

    Best-effort and read-only: callers wrap in try/except so the safety net is never
    blocked. journald line fires every time the correlation holds; the email/SMS
    notification is debounced 6h via a sentinel and honors diskio_email_off (this is
    fundamentally a disk-attribution alert)."""
    if not cl_waiting or cl_waiting <= 0:
        return
    lat_1h = _guarddog_diskio_latency_1h_avg()
    if lat_1h is None or lat_1h <= _GUARDDOG_LAT_CEILING_MS:
        return
    print(f"[ak-pg-watchdog] SPIRAL-INCOMING: disk commit latency {lat_1h:.1f} ms/commit "
          f"(ceiling {_GUARDDOG_LAT_CEILING_MS} ms) with cl_waiting={cl_waiting} — provider "
          f"disk contention starving Postgres; Authentik/feed spiral likely imminent.", flush=True)
    # 6h debounce on the notification (the journald line above always fires).
    try:
        import time as _t
        if (os.path.exists(_GUARDDOG_SPIRAL_CORR_SENTINEL)
                and (_t.time() - os.path.getmtime(_GUARDDOG_SPIRAL_CORR_SENTINEL)) < 21600):
            return
    except Exception:
        pass
    if os.path.exists('/opt/tak-guarddog/diskio_email_off'):
        print("[ak-pg-watchdog] spiral-incoming notification suppressed (diskio_email_off set)", flush=True)
        return
    settings = load_settings()
    alert_email = (settings.get('guarddog_alert_email') or '').strip()
    try:
        with open('/opt/tak-guarddog/server_identifier') as f:
            server_id = f.read().strip()
    except Exception:
        server_id = socket.gethostname()
    subj = f"⚠ Spiral incoming on {server_id} — provider disk contention"
    body = (f"Guard Dog detected the disk-latency / DB-demand correlation that precedes "
            f"an Authentik spiral.\n\n"
            f"Server: {server_id}\n"
            f"Commit latency (1h avg): {lat_1h:.1f} ms/commit (ceiling {_GUARDDOG_LAT_CEILING_MS} ms)\n"
            f"PgBouncer cl_waiting: {cl_waiting}\n\n"
            f"A throttled disk is stalling small-block (4 KB) Postgres commits while "
            f"Authentik genuinely needs the database. This is hosting-provider disk "
            f"contention — NOT an infra-TAK fault. If it persists, request a node "
            f"migration from your VPS provider.\n\n"
            f"— Guard Dog")
    # Touch the sentinel BEFORE sending (matches the disk script) so a send failure
    # can't re-spam every tick inside the 6h window.
    try:
        _makedirs_priv('/var/lib/takguard', exist_ok=True)
        _write_priv(_GUARDDOG_SPIRAL_CORR_SENTINEL, '')   # v10.0.5 non-root: /var/lib/takguard root-owned
    except Exception:
        pass
    if alert_email:
        try:
            _guarddog_send_alert_email_via_relay(alert_email, subj, body)
            print(f"[ak-pg-watchdog] spiral-incoming email sent to {alert_email}", flush=True)
        except Exception as _e:
            print(f"[ak-pg-watchdog] spiral-incoming email failed: {_e}", flush=True)
    if os.path.exists('/opt/tak-guarddog/sms_send.sh'):
        try:
            _tmp = f'/tmp/gd-spiral-sms-{os.getpid()}.txt'
            with open(_tmp, 'w') as f:
                f.write(body)
            subprocess.run(['/opt/tak-guarddog/sms_send.sh', subj, _tmp], capture_output=True, timeout=20)
            os.remove(_tmp)
        except Exception:
            pass


def _guarddog_alert_recipient_warning(settings=None):
    """Return a warning string when Guard Dog has no alert recipient, else ''.

    A watcher deployed with no recipient is not broken — the console resolves the
    address from settings.json at send time, so one set later starts working with
    no redeploy. What it must not be is SILENT: every alert that box raises is
    suppressed with a 200 OK and nothing anywhere says so (found on test6 during
    the v10.1.47 T&E, where `send-alert-email.sh "$SUBJ" ""` was read as the fault
    — it is not; the empty $2 is by design, see scripts/guarddog/send-alert-email.sh).
    """
    if settings is None:
        settings = load_settings()
    if (settings.get('guarddog_alert_email') or '').strip():
        return ''
    return ('no Guard Dog alert recipient is configured — every alert this box '
            'raises will be suppressed. Set one on the Guard Dog page (it takes '
            'effect immediately; no redeploy needed).')


@app.route('/api/guarddog/send-alert-email', methods=['POST'])
def guarddog_send_alert_email():
    """Called by Guard Dog scripts (localhost only) to send alerts via Email Relay (same path as test email)."""
    if request.remote_addr not in ('127.0.0.1', '::1'):
        return jsonify({'error': 'Forbidden'}), 403
    data = request.get_json(silent=True) or {}
    # settings.json is the SOURCE OF TRUTH for the recipient; the caller's `to` is a
    # legacy fallback only. The watch scripts pass the address that was baked into
    # them at deploy time (ALERT_EMAIL_PLACEHOLDER), and this used to prefer that —
    # so clearing the alert email in the console changed the field, said "saved", and
    # alerts kept arriving at the stale baked address until Guard Dog was redeployed.
    # Changing the address had the same fault: the OLD one kept getting mail. Reading
    # settings first makes remove, change, and pause all take effect at once, with no
    # redeploy ([[no-redeploy-button-on-installed-modules]]).
    # No `or data.get('to')` fallback: keeping one would defeat the whole fix, since a
    # cleared setting would fall straight back to the baked address it is trying to
    # remove. Empty here means the operator removed the recipient — send nothing. The
    # console shows this same field, so what it displays is what actually gets mail.
    to_addr = (load_settings().get('guarddog_alert_email') or '').strip()
    subject = (data.get('subject') or 'Guard Dog Alert')[:200]
    if not to_addr:
        # v10.1.48 W4: this returned a bare 200 and the caller pipes its output to
        # /dev/null, so a box with no recipient dropped every alert without a trace
        # anywhere. Say so in the journal — suppressed is a decision, not a non-event.
        print(f"[guarddog] alert SUPPRESSED (no recipient configured): {subject}",
              flush=True)
        return jsonify({'success': True, 'suppressed': True, 'reason': 'no recipient configured'})
    body = (data.get('body') or '')[:50000]
    try:
        # ops #228: say HELD (quiet window), not just suppressed. send-alert-email.sh exits
        # 3 on it, so a watcher that gates its episode on delivery keeps it open and
        # alerts after the window if the fault is still there.
        held = _gd_quiet_state()[0] and not _gd_alerts_pause_state()[0]
        sent = _guarddog_send_alert_email_via_relay(to_addr, subject, body)
        if held and not sent:
            return jsonify({'success': True, 'suppressed': True, 'held': True,
                            'reason': 'quiet window'})
        return jsonify({'success': True, 'suppressed': not sent})
    except Exception as e:
        return jsonify({'error': str(e)[:200]}), 500


@app.route('/api/guarddog/test-email', methods=['POST'])
@login_required
def guarddog_test_email():
    """Send a test email to the configured Guard Dog alert address (uses Email Relay / Brevo when deployed)."""
    settings = load_settings()
    data = request.json or {}
    to_addr = data.get('to', '').strip() or (settings.get('guarddog_alert_email') or '').strip()
    if not to_addr:
        return jsonify({'success': False, 'error': 'No email address configured'}), 400
    _bad = _alert_email_rejects(to_addr)
    if _bad:
        return jsonify({'success': False,
                        'error': 'Invalid alert email address: ' + ', '.join(_bad[:3])}), 400
    to_addr = _safe_alert_email_list(to_addr)
    if data.get('save'):
        settings['guarddog_alert_email'] = to_addr
        save_settings(settings)
    try:
        _guarddog_send_alert_email_via_relay(
            to_addr, 'Guard Dog Test Alert',
            'Test alert from infra-TAK Guard Dog.\n\nIf you received this, email notifications are working (via Email Relay/Brevo when deployed).',
            force=True   # a test that goes silent while paused looks like a broken relay
        )
        paused, _u = _gd_alerts_pause_state(settings)
        # v10.2.8 W6 (GH #87): say "accepted", not "sent" — the relay cannot see delivery.
        try:
            _said = mod_registry.emailrelay.accepted_message(settings, to_addr)
        except Exception:
            _said = f'Test email handed to the relay for {to_addr}'
        return jsonify({'success': True,
                        'message': _said
                                   + (' — note: alerts are currently PAUSED, so real alerts are not being delivered.'
                                      if paused else '')})
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)[:200]}), 500

@app.route('/api/guarddog/notifications/save', methods=['POST'])
@login_required
def guarddog_notifications_save():
    """Save alert email and server nickname; if Guard Dog is installed, write server_identifier so alerts use the nickname without redeploy."""
    data = request.json or {}
    settings = load_settings()
    email = (data.get('alert_email') or '').strip()
    _bad = _alert_email_rejects(email)
    if _bad:
        return jsonify({'success': False,
                        'error': 'Invalid alert email address: ' + ', '.join(_bad[:3])}), 400
    # Store canonicalised (validated, de-duplicated, comma-joined) so every consumer —
    # including scripts baked at deploy time — reads one predictable shape.
    email = _safe_alert_email_list(email)
    nickname = (data.get('server_nickname') or '').strip()
    settings['guarddog_alert_email'] = email
    settings['guarddog_server_nickname'] = nickname
    save_settings(settings)
    if os.path.exists('/opt/tak-guarddog'):
        try:
            ident = _guarddog_server_identifier(settings)
            _write_priv('/opt/tak-guarddog/server_identifier', ident)
        except Exception:
            pass
    return jsonify({'success': True, 'message': 'Saved. Alerts will use the server nickname.'})

@app.route('/api/guarddog/notifications/pause', methods=['POST'])
@login_required
def guarddog_notifications_pause():
    """Pause or resume Guard Dog alert delivery (email + SMS together).

    Body: {paused: bool, duration: '1h'|'4h'|'24h'|''}. Empty duration = indefinite.
    Monitoring is unaffected — this suppresses delivery only."""
    from datetime import timezone as _tz
    data = request.json or {}
    paused = bool(data.get('paused'))
    settings = load_settings()
    if not paused:
        settings['guarddog_alerts_paused'] = False
        settings['guarddog_alerts_paused_until'] = ''
        save_settings(settings)
        return jsonify({'success': True, 'paused': False, 'message': 'Alerts resumed.'})
    duration = (data.get('duration') or '').strip()
    if duration and duration not in _GD_PAUSE_DURATIONS:
        return jsonify({'success': False,
                        'error': 'Duration must be 1h, 4h, 24h, or empty for indefinite'}), 400
    until = ''
    if duration:
        until = (datetime.now(_tz.utc)
                 + timedelta(hours=_GD_PAUSE_DURATIONS[duration])).replace(microsecond=0).isoformat()
    settings['guarddog_alerts_paused'] = True
    settings['guarddog_alerts_paused_until'] = until
    save_settings(settings)
    return jsonify({'success': True, 'paused': True, 'until': until,
                    'message': (f'Alerts paused for {duration}.' if duration
                                else 'Alerts paused until you resume them.')})


@app.route('/api/guarddog/restarts')
@login_required
def guarddog_restarts_api():
    """Recent restarts with WHY, from tak-restart-watch.sh's history file (v10.1.57 W5).

    Deliberately NOT folded into /api/guarddog/health: that route is served from a warm
    cache so the page can paint colours in ~1s, and this is a small file read that would
    only add latency to it.

    The point of this endpoint is that the customer's OWN console can say "your hosting
    provider shut you down". helpnow was power-cycled ten times by its host and the
    operator spent days blaming a certificate he had changed, because nothing anywhere
    told him otherwise.
    """
    def _uptime_s():
        try:
            with open('/proc/uptime') as _u:
                return int(float(_u.read().split()[0]))
        except Exception:
            return 0

    def _iso_ts(s):
        """Seconds since epoch from the watcher's short-iso stamps, or 0.

        strptime('%z'), not datetime.fromisoformat(): journalctl -o short-iso emits
        '2026-08-31T00:57:29-0700' (no colon in the offset), and fromisoformat only
        learned to accept that in Python 3.11. Ubuntu 22.04 — the baseline platform —
        ships 3.10, so fromisoformat would raise there and silently zero every count.
        """
        if not s or s == 'unknown':
            return 0
        for fmt in ('%Y-%m-%dT%H:%M:%S%z', '%Y-%m-%dT%H:%M:%SZ', '%Y-%m-%dT%H:%M:%S'):
            try:
                return datetime.strptime(s, fmt).timestamp()
            except Exception:
                continue
        return 0

    path = '/var/lib/takguard/restart-history.jsonl'
    entries = []
    try:
        with open(path) as f:
            for line in f:
                line = line.strip()
                if not line:
                    continue
                try:
                    entries.append(json.loads(line))
                except Exception:
                    continue          # a torn line is not a reason to fail the card
    except FileNotFoundError:
        # No file yet = the watcher has not run a boot since install. That is "nothing
        # to report", NOT an error, and the card must not shout about it.
        return jsonify({'success': True, 'supported': True, 'entries': [],
                        'window_days': 7, 'unexpected_7d': 0, 'uptime_seconds': _uptime_s()})
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)[:200]}), 500

    entries = entries[-50:]
    entries.reverse()                 # newest first
    cutoff = time.time() - 7 * 86400
    unexpected = 0
    for e in entries:
        # OPERATOR is a deliberate reboot and is not counted against the box.
        if (e.get('verdict') or '') == 'OPERATOR':
            continue
        try:
            when = e.get('booted_at') or ''
            ts = _iso_ts(when)
        except Exception:
            ts = 0
        if ts >= cutoff:
            unexpected += 1
    return jsonify({'success': True, 'supported': True, 'entries': entries,
                    'window_days': 7, 'unexpected_7d': unexpected,
                    'uptime_seconds': _uptime_s()})


@app.route('/api/guarddog/notifications/status')
@login_required
def guarddog_notifications_status():
    """Live pause state for the Guard Dog card. Reports the EFFECTIVE state, so an
    elapsed snooze reads as resumed without anything having to write settings."""
    settings = load_settings()
    paused, until = _gd_alerts_pause_state(settings)
    # Report what is ACTUALLY saved and would receive an alert right now, read back
    # from settings — not echoed from whatever the form posted. The card previously
    # rendered the field once at page load and then said nothing, so after an edit
    # there was no way to tell a typed value from a saved one, and no way to see that
    # a save had silently dropped an invalid address.
    emails = _safe_alert_emails(settings.get('guarddog_alert_email'))
    sms = settings.get('guarddog_sms') or {}
    q_on, q_until, q_why = _gd_quiet_state()
    return jsonify({
        'paused': paused,
        'until': until if paused else '',
        # ops #228: a quiet window holds delivery while planned work runs (ends by itself).
        'quiet': q_on,
        'quiet_until': (datetime.utcfromtimestamp(q_until).strftime('%Y-%m-%dT%H:%M:%SZ')
                        if q_on else ''),
        'quiet_reason': q_why if q_on else '',
        'indefinite': bool(paused and not until),
        'has_email': bool(emails),
        'has_sms': bool(sms.get('provider')),
        'emails': emails,
        'email_saved': ','.join(emails),
        'nickname': (settings.get('guarddog_server_nickname') or '').strip(),
        'sms_provider': sms.get('provider') or '',
        'sms_to': (sms.get('to_numbers') or '').strip(),
    })


@app.route('/api/guarddog/sms/save', methods=['POST'])
@login_required
def guarddog_sms_save():
    """Save SMS provider config (Twilio or Brevo) and write sms_send.sh for watch scripts."""
    data = request.json or {}
    provider = (data.get('provider') or '').strip().lower()
    settings = load_settings()
    if provider not in ('twilio', 'brevo', ''):
        return jsonify({'success': False, 'error': 'Provider must be Twilio, Brevo, or empty to disable'}), 400
    if provider == '':
        settings['guarddog_sms'] = {}
        save_settings(settings)
        for path in ['/opt/tak-guarddog/sms_send.sh', '/opt/tak-guarddog/sms_send.py']:
            if os.path.exists(path):
                try:
                    os.remove(path)
                except Exception:
                    pass
        return jsonify({'success': True, 'message': 'SMS disabled'})
    if provider == 'twilio':
        account_sid = (data.get('account_sid') or '').strip()
        auth_token = (data.get('auth_token') or '').strip()
        from_number = (data.get('from_number') or '').strip()
        to_numbers = (data.get('to_numbers') or '').strip()
        if not all([account_sid, auth_token, from_number, to_numbers]):
            return jsonify({'success': False, 'error': 'Twilio: Account SID, Auth Token, From number, and To number(s) required'}), 400
        settings['guarddog_sms'] = {'provider': 'twilio', 'account_sid': account_sid, 'auth_token': auth_token, 'from_number': from_number, 'to_numbers': to_numbers}
    else:
        api_key = (data.get('api_key') or '').strip()
        sender = (data.get('sender') or '').strip()
        to_numbers = (data.get('to_numbers') or '').strip()
        if not all([api_key, sender, to_numbers]):
            return jsonify({'success': False, 'error': 'Brevo: API key, Sender (max 11 chars), and To number(s) with country code required'}), 400
        settings['guarddog_sms'] = {'provider': 'brevo', 'api_key': api_key, 'sender': sender, 'to_numbers': to_numbers}
    save_settings(settings)
    _guarddog_write_sms_send_script(settings)
    return jsonify({'success': True, 'message': 'SMS settings saved'})

def _guarddog_write_sms_send_script(settings):
    """Write /opt/tak-guarddog/sms_send.sh that watch scripts can call to send SMS via console API."""
    sms = settings.get('guarddog_sms', {})
    if not sms or not sms.get('provider'):
        return
    _makedirs_priv('/opt/tak-guarddog', exist_ok=True)
    py_script = '''#!/usr/bin/env python3
import urllib.request, json, sys
if len(sys.argv) < 3:
    sys.exit(0)
subj, path = sys.argv[1], sys.argv[2]
try:
    with open(path) as f: body = f.read()
except Exception:
    body = subj
data = json.dumps({"subject": subj, "body": body}).encode()
req = urllib.request.Request("http://127.0.0.1:5001/api/guarddog/send-sms", data=data, headers={"Content-Type": "application/json"}, method="POST")
try:
    urllib.request.urlopen(req, timeout=10)
except Exception:
    pass
'''
    sh_script = '''#!/bin/bash
SUBJ="$1"
BODY_FILE="$2"
[ -z "$BODY_FILE" ] || [ ! -f "$BODY_FILE" ] && exit 0
/usr/bin/python3 /opt/tak-guarddog/sms_send.py "$SUBJ" "$BODY_FILE"
'''
    for name, content in [('sms_send.py', py_script), ('sms_send.sh', sh_script)]:
        p = os.path.join('/opt/tak-guarddog', name)
        _write_priv(p, content, perm=0o755)   # v10.0.5 non-root: /opt/tak-guarddog root-owned

def _guarddog_send_sms_now(sms, text, force=False):
    """Send SMS via Twilio or Brevo. sms = settings['guarddog_sms'], text = message body (max 1600 chars). Raises on error. Returns optional dict with e.g. {'brevo_message_id': ...} for debugging.

    Returns {'suppressed': True} without sending when notifications are paused
    (force=True bypasses, for the test button). See _gd_alerts_pause_state()."""
    text = (text or '')[:1600]
    out = {}
    if not force:
        paused, until = _gd_alerts_pause_state()
        if paused:
            print(f"[guarddog] alert SMS suppressed — notifications paused"
                  f"{' until ' + until if until else ' (indefinite)'}", flush=True)
            return {'suppressed': True}
        # ops #228: the same alert's email records the hold for the close-out review;
        # recording it again here would list every alert twice.
        quiet = _gd_quiet_state()
        if quiet[0]:
            print(f"[guarddog] alert SMS HELD — quiet window ({quiet[2]})", flush=True)
            return {'suppressed': True, 'held': True}
    if sms.get('provider') == 'twilio':
        import base64
        import urllib.error
        account_sid = sms.get('account_sid', '')
        auth_token = sms.get('auth_token', '')
        from_num = sms.get('from_number', '')
        to_list = [n.strip() for n in (sms.get('to_numbers') or '').split(',') if n.strip()]
        if not to_list:
            raise ValueError('No To numbers configured')
        auth = base64.b64encode(f"{account_sid}:{auth_token}".encode()).decode()
        for to_num in to_list:
            to_e164 = '+' + ''.join(c for c in to_num if c.isdigit()).lstrip('+') or to_num.lstrip('+')
            req_body = f"To={urllib.parse.quote(to_e164)}&From={urllib.parse.quote(from_num)}&Body={urllib.parse.quote(text)}"
            req = urllib.request.Request(f'https://api.twilio.com/2010-04-01/Accounts/{account_sid}/Messages.json', data=req_body.encode(), method='POST', headers={'Authorization': f'Basic {auth}', 'Content-Type': 'application/x-www-form-urlencoded'})
            try:
                urllib.request.urlopen(req, timeout=15)
            except urllib.error.HTTPError as e:
                body = e.read().decode() if e.fp else ''
                try:
                    err_json = json.loads(body) if body else {}
                    msg = err_json.get('message') or str(err_json.get('code', '')) or body[:200] or f'HTTP {e.code}'
                except Exception:
                    msg = body[:200] or f'HTTP {e.code}'
                raise ValueError(f'Twilio SMS: {msg}')
    else:
        import urllib.error
        api_key = sms.get('api_key', '')
        sender = (sms.get('sender', '') or 'GuardDog')[:11]
        to_list = [n.strip() for n in (sms.get('to_numbers') or '').split(',') if n.strip()]
        if not to_list:
            raise ValueError('No To numbers configured')
        for to_num in to_list:
            recipient = ''.join(c for c in to_num if c.isdigit())
            if not recipient or len(recipient) < 10:
                raise ValueError(f'Brevo recipient must be digits with country code (e.g. 15551234567). Got: {to_num[:25]}')
            payload = json.dumps({'sender': sender, 'recipient': recipient, 'content': text, 'type': 'transactional', 'tag': 'GuardDog', 'unicodeEnabled': True}).encode()
            req = urllib.request.Request('https://api.brevo.com/v3/transactionalSMS/send', data=payload, method='POST', headers={'api-key': api_key, 'Content-Type': 'application/json', 'accept': 'application/json'})
            try:
                with urllib.request.urlopen(req, timeout=15) as resp:
                    body = resp.read().decode()
                    try:
                        data = json.loads(body) if body else {}
                        if data.get('messageId') is not None:
                            out['brevo_message_id'] = data.get('messageId')
                    except Exception:
                        pass
            except urllib.error.HTTPError as e:
                body = e.read().decode() if e.fp else ''
                try:
                    err_json = json.loads(body) if body else {}
                    msg = err_json.get('message') or err_json.get('code') or body[:200] or f'HTTP {e.code}'
                except Exception:
                    msg = body[:200] or f'HTTP {e.code}'
                raise ValueError(f'Brevo SMS: {msg}')
    return out

@app.route('/api/guarddog/brevo-sms-events', methods=['GET'])
@login_required
def guarddog_brevo_sms_events():
    """Fetch last SMS events from Brevo (sent, delivered, rejected, etc.) so user can see delivery status without digging in Brevo UI."""
    settings = load_settings()
    sms = settings.get('guarddog_sms', {})
    if not sms or sms.get('provider') != 'brevo':
        return jsonify({'error': 'Brevo SMS not configured'}), 400
    api_key = sms.get('api_key', '')
    if not api_key:
        return jsonify({'error': 'Brevo API key not set'}), 400
    days = request.args.get('days', '1')
    try:
        days_int = max(1, min(7, int(days)))
    except ValueError:
        days_int = 1
    url = f'https://api.brevo.com/v3/transactionalSMS/statistics/events?days={days_int}&tags=GuardDog&limit=50&sort=desc'
    req = urllib.request.Request(url, method='GET', headers={'api-key': api_key, 'accept': 'application/json'})
    try:
        with urllib.request.urlopen(req, timeout=15) as resp:
            data = json.loads(resp.read().decode())
    except urllib.error.HTTPError as e:
        body = e.read().decode() if e.fp else ''
        try:
            err = json.loads(body) if body else {}
            msg = err.get('message') or err.get('code') or body[:200] or f'HTTP {e.code}'
        except Exception:
            msg = body[:200] or f'HTTP {e.code}'
        return jsonify({'error': f'Brevo: {msg}'}), 400
    except Exception as e:
        return jsonify({'error': str(e)[:200]}), 500
    events = data.get('events') or []
    return jsonify({'events': events})

@app.route('/api/guarddog/test-sms', methods=['POST'])
@login_required
def guarddog_test_sms():
    """Send a test SMS using saved Guard Dog SMS config (Twilio or Brevo)."""
    settings = load_settings()
    sms = settings.get('guarddog_sms', {})
    if not sms or sms.get('provider') not in ('twilio', 'brevo'):
        return jsonify({'success': False, 'error': 'SMS not configured. Save Twilio or Brevo settings first.'}), 400
    try:
        info = _guarddog_send_sms_now(sms, 'Guard Dog test - if you got this, SMS is working.',
                                      force=True)   # same reason as the test email
        msg = 'Test SMS sent to configured number(s).'
        if _gd_alerts_pause_state(settings)[0]:
            msg += ' Note: alerts are currently PAUSED, so real alerts are not being delivered.'
        if info.get('brevo_message_id') is not None:
            msg += f' Brevo message ID: {info["brevo_message_id"]} (check Brevo SMS logs if the text did not arrive).'
        return jsonify({'success': True, 'message': msg})
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)[:200]}), 500

@app.route('/api/guarddog/send-sms', methods=['POST'])
def guarddog_send_sms():
    """Called by Guard Dog scripts (localhost only) to send SMS via Twilio or Brevo."""
    if request.remote_addr not in ('127.0.0.1', '::1'):
        return jsonify({'error': 'Forbidden'}), 403
    data = request.get_json(silent=True) or {}
    subj = (data.get('subject') or '')[:100]
    body = (data.get('body') or '')[:1600]
    settings = load_settings()
    sms = settings.get('guarddog_sms', {})
    if not sms or sms.get('provider') not in ('twilio', 'brevo'):
        return jsonify({'error': 'SMS not configured'}), 400
    try:
        _guarddog_send_sms_now(sms, f"{subj}: {body}")
        return jsonify({'success': True})
    except Exception as e:
        return jsonify({'error': str(e)[:200]}), 500

# v0.9.47: shared so the deploy path and the boot self-heal can't drift.
_METRICS_COLLECTOR_UNIT = ('[Unit]\nDescription=Guard Dog Network/Fanout Metrics Collector\n'
                           'After=network.target takserver.service docker.service\n\n'
                           '[Service]\nType=simple\n'
                           'ExecStart=/usr/bin/python3 /opt/tak-guarddog/tak-metrics-collector.py\n'
                           'Restart=always\nRestartSec=15\n\n'
                           '[Install]\nWantedBy=multi-user.target\n')

# v10.1.46 (W1/W2). ONE definition, used by both the Guard Dog deploy path and the
# console-startup auto-update — if the two ever disagree the startup path rewrites
# the unit on every restart, and which cadence a box gets depends on which ran last
# (the takbuildcachereclaim daily-vs-hourly split, ~line 67665, is that bug).
#
# takclientgate is the INDEPENDENT backstop for the 8089 boot gate: OnBootSec only,
# fires once per boot, releases whether or not a gate exists and whether or not
# tak-post-start.sh ever ran. It is deliberately dumb.
_CLIENT_GATE_UNITS = [
    ('takclientgate.service', '[Unit]\nDescription=Guard Dog TAK client gate release (boot backstop)\n\n[Service]\nType=oneshot\nExecStart=/opt/tak-guarddog/tak-client-gate.sh release\n'),
    ('takclientgate.timer', '[Unit]\nDescription=Release the TAK client gate 15 min after boot, unconditionally\n\n[Timer]\nOnBootSec=15min\nAccuracySec=30s\nUnit=takclientgate.service\n\n[Install]\nWantedBy=timers.target\n'),
    ('taksessionguard.service', '[Unit]\nDescription=TAK Client Session Visibility Monitor (invisible / groupless sessions)\nAfter=network.target takserver.service\n\n[Service]\nType=oneshot\nExecStart=/opt/tak-guarddog/tak-session-watch.sh\n'),
    ('taksessionguard.timer', '[Unit]\nDescription=Run TAK session visibility monitor every 5 minutes\n\n[Timer]\nOnBootSec=20min\nOnUnitActiveSec=5min\nUnit=taksessionguard.service\n\n[Install]\nWantedBy=timers.target\n'),
    # Console-startup stale-gate sweep. A UNIT rather than a direct call because
    # the broker denies `bash <script>` outright (arbitrary-shell escalation) —
    # on a non-root box a direct invocation would simply be refused, and the
    # sweep would silently never run. `systemctl start` is already allowed, and
    # this adds no new privilege the console did not have.
    # No timer: the console triggers it, and takclientgate.timer is the periodic net.
    ('takclientgatesweep.service', '[Unit]\nDescription=Guard Dog TAK client gate stale sweep (console startup)\n\n[Service]\nType=oneshot\nExecStart=/opt/tak-guarddog/tak-client-gate.sh sweep\n'),
]

def run_guarddog_deploy(alert_email):
    """Deploy Guard Dog: monitors + health endpoint. Requires TAK Server at /opt/tak. Alert email optional (alerts only when set)."""
    def plog(msg):
        entry = f"[{datetime.now().strftime('%H:%M:%S')}] {msg}"
        guarddog_deploy_log.append(entry)
    alert_sms = ''  # Optional SMS; scripts accept empty
    try:
        if not os.path.exists('/opt/tak'):
            plog("✗ TAK Server not found at /opt/tak. Deploy TAK Server first.")
            guarddog_deploy_status.update({'running': False, 'error': True})
            return
        plog("━━━ Guard Dog deployment ━━━")
        scripts_dir = os.path.join(BASE_DIR, 'scripts', 'guarddog')
        if not os.path.isdir(scripts_dir):
            plog(f"✗ Scripts directory not found: {scripts_dir}")
            guarddog_deploy_status.update({'running': False, 'error': True})
            return
        for d in ['/opt/tak-guarddog', '/var/lib/takguard', '/var/log/takguard']:
            _makedirs_priv(d)
        # v0.9.29 CRIT-08 fix: provision pinned SSH known_hosts for watchdog
        # scripts (used when StrictHostKeyChecking=accept-new is in effect).
        try:
            _kh = '/opt/tak-guarddog/known_hosts'
            subprocess.run(_sudo_wrap(['touch', _kh]), capture_output=True)
            _chmod_priv(_kh, 0o600)
            subprocess.run(_sudo_wrap(['chown', 'root:root', _kh]), capture_output=True)
        except Exception:
            pass
        plog("✓ Directories created")
        # Detect two-server mode
        settings = load_settings()
        tak_cfg = _get_tak_deployment_config(settings)
        is_two_server = tak_cfg.get('mode') == 'two_server'
        s1_host = (tak_cfg.get('server_one', {}).get('host') or '').strip() if is_two_server else ''
        s1_user = (tak_cfg.get('server_one', {}).get('ssh_user') or 'root').strip() if is_two_server else ''
        db_port = str(int(tak_cfg.get('database', {}).get('port') or 5432)) if is_two_server else '5432'
        # Resolve the REAL Server One key from config (canonical name is
        # ~/.ssh/infratak_serverone), never a hardcoded legacy name. The old
        # hardcoded '~/.ssh/infra-tak-server-one' didn't exist on non-root/flipped
        # boxes → every two-server DB script (auto-vacuum, cotdb-watch, db-repack,
        # retention-guard, remotedb watchers) got a dead SSH_KEY and skipped/failed.
        ssh_key_path = ''
        if is_two_server:
            _s1 = dict(tak_cfg.get('server_one', {}))
            ssh_key_path = _find_ssh_key_for_server_one(_s1) or (_s1.get('ssh_key_path') or '').strip()
        if is_two_server and s1_host:
            plog(f"Two-server mode detected — DB on {s1_host}:{db_port}")
        script_files = [
            # v10.0.1: shared TAK/DB dispatch lib sourced by the DB/process/cert
            # watch scripts (native vs container). No-op on deb boxes (its native
            # branch emits the identical commands); enables container mode here.
            '_gd-tak-lib.sh',
            'send-alert-email.sh', 'tak-boot-sequencer.sh', 'tak-post-start.sh',
            # ops #228: opens/closes the quiet window for T&E, drills and box tests.
            'gd-quiet.sh',
            # v10.1.46 (W1/W2): the boot client gate on 8089 and the session
            # visibility watcher. Both are fleet-wide — the gate no-ops on a box
            # with no firewall backend, the watcher no-ops until TAK is up.
            'tak-client-gate.sh', 'tak-session-watch.sh',
            # v10.1.57 W4: classify the previous boot and say WHY the box went down.
            # Guard Dog had no restart detection at all — a customer box was power-cycled
            # ten times by its host and the console had nothing to say about it.
            'tak-restart-watch.sh',
            'tak-8089-watch.sh', 'tak-oom-watch.sh', 'tak-disk-watch.sh', 'tak-diskio-watch.sh',
            'tak-network-watch.sh', 'tak-process-watch.sh', 'tak-cert-watch.sh', 'tak-intca-watch.sh', 'tak-health-endpoint.py',
            # v10.1.63 W4: the JVM the TAK API is ACTUALLY running on. Every other monitor
            # stays green while enrollment is dead on a JDK 21 — this is the only one that
            # would have caught Tom Endress's three-day outage on day one.
            'tak-jvm-watch.sh',
            'tak-metrics-collector.py', 'tak-updates-watch.sh', 'tak-swap-reclaim.sh',
            'tak-buildcache-reclaim.sh',
            # v10.1.0 Leg 7: relay tunnel health. Installed fleet-wide — the script
            # no-ops silently when no relay is configured (no /etc/wireguard/wg0.conf),
            # and starts watching the moment the operator connects a relay later.
            'tak-relay-watch.sh',
            # v10.1.0 Leg 6b: Setup AP engine + auto-trigger watcher. The engine is
            # invoked by a systemd unit (console start/stop) and by the watcher; the
            # watcher no-ops on boxes with no wifi radio or with auto-AP disabled.
            'tak-setup-ap.sh', 'tak-setup-ap-watch.sh'
        ]
        # Two-server: remote DB monitors + CoT size (SSH to Server One); single-server: local PG + CoT
        if is_two_server and s1_host:
            script_files.append('tak-remotedb-watch.sh')
            script_files.append('tak-remotedb-auth-watch.sh')
            script_files.append('tak-cotdb-watch.sh')
        else:
            script_files.extend(['tak-db-watch.sh', 'tak-cotdb-watch.sh'])
        script_files.append('tak-auto-vacuum.sh')
        script_files.append('tak-db-repack.sh')
        script_files.append('tak-retention-guard.sh')
        # Optional: monitors for other services (only install if that service is present)
        ak_dir = os.path.expanduser('~/authentik')
        nr_dir = os.path.expanduser('~/node-red')
        cloudtak_dir = os.path.expanduser('~/CloudTAK')
        if os.path.exists(os.path.join(ak_dir, 'docker-compose.yml')):
            script_files.append('tak-authentik-watch.sh')
        if os.path.exists('/usr/local/bin/mediamtx') and os.path.exists('/usr/local/etc/mediamtx.yml'):
            script_files.append('tak-mediamtx-watch.sh')
        if os.path.exists(os.path.join(nr_dir, 'docker-compose.yml')):
            script_files.append('tak-nodered-watch.sh')
            # v10.1.34: feed-source staleness rides with Node-RED, since ArcGIS feed
            # configs live in Node-RED's global context. The script exits 0 quietly when
            # no arcgis_configs exist, so installing it alongside Node-RED is harmless
            # on a box that only runs other flows.
            script_files.append('tak-feedsource-watch.sh')
        if os.path.exists(cloudtak_dir) and os.path.exists(os.path.join(cloudtak_dir, 'docker-compose.yml')):
            script_files.append('tak-cloudtak-watch.sh')
        portal_dir = os.path.expanduser('~/TAK-Portal')
        if os.path.exists(os.path.join(portal_dir, 'docker-compose.yml')):
            script_files.append('tak-takportal-watch.sh')
        fh_cfg = _get_fedhub_deployment_config(settings)
        fh_deployed = fh_cfg.get('deployed') and fh_cfg.get('target_mode') == 'remote'
        fh_host = (fh_cfg.get('remote', {}).get('host') or '').strip() if fh_deployed else ''
        if fh_deployed and fh_host:
            script_files.append('tak-fedhub-watch.sh')
        _no_recip = _guarddog_alert_recipient_warning(settings)
        if _no_recip:
            plog(f"⚠ {_no_recip}")
        # Scripts (e.g. tak-cert-watch.sh) live in repo scripts/guarddog/ — read from disk each deploy.
        # Only rewrite a script whose rendered content differs, same as _auto_update_guarddog().
        # Update Now runs this right after the startup copy, and rewriting every file with
        # identical bytes made the box's mtimes disagree with the "N script(s) updated" log line.
        changed = []
        for name in script_files:
            src = os.path.join(scripts_dir, name)
            if not os.path.isfile(src):
                plog(f"✗ Missing script: {name}")
                guarddog_deploy_status.update({'running': False, 'error': True})
                return
            content = open(src, 'r').read()
            cert_pass = _get_tak_cert_password(settings)
            content = (content
                .replace('ALERT_EMAIL_PLACEHOLDER', _safe_alert_email_list(alert_email))
                .replace('ALERT_SMS_PLACEHOLDER', alert_sms or '')
                .replace('CERT_PASS_PLACEHOLDER', cert_pass)
                .replace('CONSOLE_VERSION_PLACEHOLDER', VERSION)
                # v10.1.40: the updates watcher must compare Authentik against what THIS
                # box's console will actually offer, not upstream latest — see
                # scripts/guarddog/tak-updates-watch.sh.
                .replace('UPDATE_CHANNEL_PLACEHOLDER',
                         (settings.get('update_channel') or 'main').strip().lower())
                .replace('AK_VETTED_PLACEHOLDER', AUTHENTIK_VETTED_RELEASE))
            if is_two_server and name in ('tak-remotedb-watch.sh', 'tak-remotedb-auth-watch.sh', 'tak-cotdb-watch.sh', 'tak-auto-vacuum.sh', 'tak-db-repack.sh', 'tak-retention-guard.sh'):
                content = content.replace('DB_HOST_PLACEHOLDER', s1_host)
                content = content.replace('DB_PORT_PLACEHOLDER', db_port)
                content = content.replace('SSH_KEY_PLACEHOLDER', ssh_key_path)
                content = content.replace('SSH_USER_PLACEHOLDER', s1_user)
                # Same value _sync_guarddog_remote_db_from_settings() writes for two-server.
                # Leaving the placeholder in made the two renders differ, so every Update Now
                # rewrote tak-remotedb-watch.sh and logged it as changed (test8, 2026-10-10).
                content = content.replace('EXTERNAL_DB_PLACEHOLDER', '')
            if name == 'tak-fedhub-watch.sh' and fh_deployed and fh_host:
                fh_remote = fh_cfg.get('remote', {})
                fh_ssh_key = (fh_remote.get('ssh_key_path') or '').strip()
                fh_ssh_user = (fh_remote.get('username') or 'root').strip()
                content = content.replace('FEDHUB_HOST_PLACEHOLDER', fh_host)
                content = content.replace('SSH_KEY_PLACEHOLDER', fh_ssh_key)
                content = content.replace('SSH_USER_PLACEHOLDER', fh_ssh_user)
            dest = os.path.join('/opt/tak-guarddog', name)
            _perm = 0o755 if name.endswith('.sh') else None
            try:
                _unchanged = _read_priv(dest) == content
            except Exception:
                _unchanged = False
            if _unchanged and _perm is not None:
                try:
                    _chmod_priv(dest, _perm)   # still repair a lost +x; chmod leaves mtime alone
                except Exception:
                    _unchanged = False         # legacy non-root: let _write_priv's sudo chmod do it
            if _unchanged:
                continue
            _write_priv(dest, content, perm=_perm)
            changed.append(name)
        if changed:
            plog(f"✓ Scripts installed: {len(changed)} changed ({', '.join(sorted(changed))}), "
                 f"{len(script_files) - len(changed)} already current")
        else:
            plog(f"✓ Scripts installed: all {len(script_files)} already current")
        # Config file for the DB modules and health endpoint. The database section comes from
        # _guarddog_db_topology() (settings, else TAK's CoreConfig) — GH #101: this used to
        # come from settings alone, so a split box settings didn't know about was written
        # with no database section at all.
        # v10.0.1: container TAK — tell _gd-tak-lib.sh to dispatch DB/process/cert
        # work via docker exec against these containers (absent → native mode).
        _is_ctr = _tak_is_container()
        gd_ok, gd_msg = _write_guarddog_conf(settings, {
            'tak_mode': 'container' if _is_ctr else None,
            'tak_container': TAK_CONTAINER if _is_ctr else None,
            'db_container': TAK_DB_CONTAINER if _is_ctr else None,
            # v0.9.47: metrics collector extracts admin.p12 for the Marti scrape — needs the cert pass.
            'tak_cert_pass': _get_tak_cert_password(settings),
        })
        plog(f"{'✓' if gd_ok else '✗'} guarddog.conf {gd_msg}")
        if not gd_ok:
            guarddog_deploy_status.update({'running': False, 'error': True})
            return
        # Server identifier for alerts (nickname and/or IP/FQDN) so multi-server monitoring can tell which host
        server_identifier = _guarddog_server_identifier(settings)
        _write_priv('/opt/tak-guarddog/server_identifier', server_identifier)
        plog("✓ Server identifier written (for alert subject/body)")
        units = [
            ('tak8089guard.service', '[Unit]\nDescription=TAK 8089 Health Guard Dog\nAfter=network-online.target\n\n[Service]\nType=oneshot\nExecStart=/opt/tak-guarddog/tak-8089-watch.sh\n'),
            ('tak8089guard.timer', '[Unit]\nDescription=Run TAK 8089 guard dog every 1 minute\n\n[Timer]\nOnBootSec=20min\nOnUnitActiveSec=1min\nUnit=tak8089guard.service\n\n[Install]\nWantedBy=timers.target\n'),
            ('takoomguard.service', '[Unit]\nDescription=TAK OOM Guard Dog\nAfter=takserver.service\n\n[Service]\nType=oneshot\nExecStart=/opt/tak-guarddog/tak-oom-watch.sh\n'),
            ('takoomguard.timer', '[Unit]\nDescription=Run TAK OOM guard dog every 1 minute\n\n[Timer]\nOnBootSec=20min\nOnUnitActiveSec=1min\nUnit=takoomguard.service\n\n[Install]\nWantedBy=timers.target\n'),
            ('takdiskguard.service', '[Unit]\nDescription=TAK Disk Space Monitor\n\n[Service]\nType=oneshot\nExecStart=/opt/tak-guarddog/tak-disk-watch.sh\n'),
            ('takdiskguard.timer', '[Unit]\nDescription=Run TAK disk monitor every hour\n\n[Timer]\nOnBootSec=30min\nOnUnitActiveSec=1h\nUnit=takdiskguard.service\n\n[Install]\nWantedBy=timers.target\n'),
            ('takdiskioguard.service', '[Unit]\nDescription=Guard Dog Disk I/O Performance Monitor\n\n[Service]\nType=oneshot\nExecStart=/opt/tak-guarddog/tak-diskio-watch.sh\n'),
            ('takdiskioguard.timer', '[Unit]\nDescription=Run disk I/O benchmark every 15 minutes\n\n[Timer]\nOnBootSec=10min\nOnUnitActiveSec=15min\nUnit=takdiskioguard.service\n\n[Install]\nWantedBy=timers.target\n'),
            ('takswapreclaim.service', '[Unit]\nDescription=Guard Dog Swap Reclaim (stale-swap hygiene)\n\n[Service]\nType=oneshot\nExecStart=/opt/tak-guarddog/tak-swap-reclaim.sh\n'),
            ('takswapreclaim.timer', '[Unit]\nDescription=Run swap reclaim every 10 minutes\n\n[Timer]\nOnBootSec=12min\nOnUnitActiveSec=10min\nUnit=takswapreclaim.service\n\n[Install]\nWantedBy=timers.target\n'),
            ('takbuildcachereclaim.service', '[Unit]\nDescription=Guard Dog Docker build-cache reclaim (disk-capacity hygiene)\nAfter=docker.service\n\n[Service]\nType=oneshot\nExecStart=/opt/tak-guarddog/tak-buildcache-reclaim.sh\n'),
            ('takbuildcachereclaim.timer', '[Unit]\nDescription=Run Docker build-cache reclaim hourly (disk-capacity hygiene)\n\n[Timer]\nOnBootSec=45min\nOnUnitActiveSec=1h\nUnit=takbuildcachereclaim.service\n\n[Install]\nWantedBy=timers.target\n'),
            ('taknetguard.service', '[Unit]\nDescription=TAK Network Monitor\nAfter=network.target\n\n[Service]\nType=oneshot\nExecStart=/opt/tak-guarddog/tak-network-watch.sh\n'),
            ('taknetguard.timer', '[Unit]\nDescription=TAK Network Monitor Timer\nRequires=taknetguard.service\n\n[Timer]\nOnBootSec=2min\nOnUnitActiveSec=1min\nAccuracySec=30s\n\n[Install]\nWantedBy=timers.target\n'),
            ('takrelayguard.service', '[Unit]\nDescription=TAK Relay Tunnel Monitor (connectivity anchor)\nAfter=network.target\n\n[Service]\nType=oneshot\nExecStart=/opt/tak-guarddog/tak-relay-watch.sh\n'),
            ('takrelayguard.timer', '[Unit]\nDescription=TAK Relay Tunnel Monitor Timer\nRequires=takrelayguard.service\n\n[Timer]\nOnBootSec=3min\nOnUnitActiveSec=1min\nAccuracySec=30s\n\n[Install]\nWantedBy=timers.target\n'),
            # v10.1.0 Leg 6b: Setup AP. The service is the console's start/stop handle
            # (RemainAfterExit so `systemctl start` = AP up, `stop` = AP down + client
            # restored). The watcher timer drives the automatic no-uplink trigger.
            ('takwerx-setup-ap.service', '[Unit]\nDescription=infra-TAK Setup AP (broadcast own wifi for local provisioning)\nAfter=network.target\n\n[Service]\nType=oneshot\nRemainAfterExit=yes\nExecStart=/opt/tak-guarddog/tak-setup-ap.sh start\nExecStop=/opt/tak-guarddog/tak-setup-ap.sh stop\n'),
            ('takwerxsetupapwatch.service', '[Unit]\nDescription=infra-TAK Setup AP auto-trigger watcher\nAfter=network.target\n\n[Service]\nType=oneshot\nExecStart=/opt/tak-guarddog/tak-setup-ap-watch.sh\n'),
            ('takwerxsetupapwatch.timer', '[Unit]\nDescription=infra-TAK Setup AP watcher timer\nRequires=takwerxsetupapwatch.service\n\n[Timer]\nOnBootSec=30s\nOnUnitActiveSec=30s\nAccuracySec=10s\n\n[Install]\nWantedBy=timers.target\n'),
            ('takprocessguard.service', '[Unit]\nDescription=TAK Server Process Monitor\nAfter=network.target takserver.service\n\n[Service]\nType=oneshot\nExecStart=/opt/tak-guarddog/tak-process-watch.sh\n'),
            ('takprocessguard.timer', '[Unit]\nDescription=TAK Server Process Monitor Timer\nRequires=takprocessguard.service\n\n[Timer]\nOnBootSec=20min\nOnUnitActiveSec=1min\nAccuracySec=30s\n\n[Install]\nWantedBy=timers.target\n'),
            ('takcertguard.service', '[Unit]\nDescription=TAK Certificate Expiry Monitor\n\n[Service]\nType=oneshot\nExecStart=/opt/tak-guarddog/tak-cert-watch.sh\n'),
            ('takcertguard.timer', '[Unit]\nDescription=Run TAK cert monitor daily\n\n[Timer]\nOnBootSec=1h\nOnUnitActiveSec=1d\nUnit=takcertguard.service\n\n[Install]\nWantedBy=timers.target\n'),
            _TAK_JVM_GUARD_UNITS[0], _TAK_JVM_GUARD_UNITS[1],
            ('takintcaguard.service', '[Unit]\nDescription=TAK Intermediate CA Expiry Monitor\n\n[Service]\nType=oneshot\nExecStart=/opt/tak-guarddog/tak-intca-watch.sh\n'),
            ('takintcaguard.timer', '[Unit]\nDescription=Run TAK Intermediate CA expiry monitor daily\n\n[Timer]\nOnBootSec=2h\nOnUnitActiveSec=1d\nUnit=takintcaguard.service\n\n[Install]\nWantedBy=timers.target\n'),
            ('tak-health.service', '[Unit]\nDescription=TAK Server Health Check Endpoint\nAfter=network.target takserver.service\n\n[Service]\nType=simple\nExecStart=/usr/bin/python3 /opt/tak-guarddog/tak-health-endpoint.py\nRestart=always\nRestartSec=10\n\n[Install]\nWantedBy=multi-user.target\n'),
            ('tak-metrics-collector.service', _METRICS_COLLECTOR_UNIT),
            # Boot-time oneshot, no timer: there is exactly one previous boot to classify
            # per boot. Ordered after the console because the alert relay lives on :5001.
            ('takrestartwatch.service', '[Unit]\nDescription=Guard Dog Unexpected-Restart Detector\nAfter=network-online.target takwerx-console.service\nWants=network-online.target\n\n[Service]\nType=oneshot\nTimeoutStartSec=300\nExecStart=/opt/tak-guarddog/tak-restart-watch.sh\n\n[Install]\nWantedBy=multi-user.target\n'),
            ('tak-post-start.service', '[Unit]\nDescription=Guard Dog Post-Start Orchestrator (starts Authentik, TAK Portal, CloudTAK after TAK)\nAfter=takserver.service docker.service\nWants=takserver.service\n\n[Service]\nType=oneshot\nRemainAfterExit=yes\nTimeoutStartSec=1200\nExecStart=/opt/tak-guarddog/tak-post-start.sh\n\n[Install]\nWantedBy=multi-user.target\n'),
        ]
        # Two-server: remote DB monitor instead of local PG monitors
        if is_two_server and s1_host:
            units.extend([
                ('takremotedbguard.service', '[Unit]\nDescription=Guard Dog Remote Database Monitor\nAfter=network-online.target\n\n[Service]\nType=oneshot\nExecStart=/opt/tak-guarddog/tak-remotedb-watch.sh\n'),
                ('takremotedbguard.timer', '[Unit]\nDescription=Run remote DB monitor every 2 minutes\n\n[Timer]\nOnBootSec=5min\nOnUnitActiveSec=2min\nUnit=takremotedbguard.service\n\n[Install]\nWantedBy=timers.target\n'),
                ('takremotedbauthguard.service', '[Unit]\nDescription=Guard Dog Remote DB Auth Monitor\nAfter=network-online.target\n\n[Service]\nType=oneshot\nExecStart=/opt/tak-guarddog/tak-remotedb-auth-watch.sh\n'),
                ('takremotedbauthguard.timer', '[Unit]\nDescription=Validate DB credentials every 2 minutes\n\n[Timer]\nOnBootSec=3min\nOnUnitActiveSec=2min\nUnit=takremotedbauthguard.service\n\n[Install]\nWantedBy=timers.target\n'),
                ('takcotdbguard.service', '[Unit]\nDescription=TAK CoT Database Size Monitor\nAfter=network-online.target\n\n[Service]\nType=oneshot\nExecStart=/opt/tak-guarddog/tak-cotdb-watch.sh\n'),
                ('takcotdbguard.timer', '[Unit]\nDescription=Run TAK CoT DB size monitor every 6 hours\n\n[Timer]\nOnBootSec=30min\nOnUnitActiveSec=6h\nUnit=takcotdbguard.service\n\n[Install]\nWantedBy=timers.target\n'),
                ('takautovacuum.service', '[Unit]\nDescription=Guard Dog Smart Auto-VACUUM\nAfter=network-online.target\n\n[Service]\nType=oneshot\nExecStart=/opt/tak-guarddog/tak-auto-vacuum.sh\n'),
                ('takautovacuum.timer', '[Unit]\nDescription=Run smart auto-VACUUM daily at 3am\n\n[Timer]\nOnCalendar=*-*-* 03:00:00\nPersistent=true\nUnit=takautovacuum.service\n\n[Install]\nWantedBy=timers.target\n'),
                ('takdbrepack.service', '[Unit]\nDescription=Guard Dog Online DB Repack (pg_repack)\nAfter=network-online.target\n\n[Service]\nType=oneshot\nTimeoutStartSec=3600\nExecStart=/opt/tak-guarddog/tak-db-repack.sh\n'),
                ('takdbrepack.timer', '[Unit]\nDescription=Run online DB repack weekly (Sunday 4am)\n\n[Timer]\nOnCalendar=Sun *-*-* 04:00:00\nPersistent=true\nUnit=takdbrepack.service\n\n[Install]\nWantedBy=timers.target\n'),
                ('takretentionguard.service', '[Unit]\nDescription=Guard Dog CoT Retention Safety Net\nAfter=network-online.target\n\n[Service]\nType=oneshot\nTimeoutStartSec=1800\nExecStart=/opt/tak-guarddog/tak-retention-guard.sh\n'),
                ('takretentionguard.timer', '[Unit]\nDescription=Run CoT retention guard every 15 minutes\n\n[Timer]\nOnBootSec=10min\nOnUnitActiveSec=15min\nUnit=takretentionguard.service\n\n[Install]\nWantedBy=timers.target\n'),
            ])
        else:
            units.extend([
                ('takdbguard.service', '[Unit]\nDescription=TAK PostgreSQL Monitor\n\n[Service]\nType=oneshot\nExecStart=/opt/tak-guarddog/tak-db-watch.sh\n'),
                ('takdbguard.timer', '[Unit]\nDescription=Run TAK DB monitor every 5 minutes\n\n[Timer]\nOnBootSec=15min\nOnUnitActiveSec=5min\nUnit=takdbguard.service\n\n[Install]\nWantedBy=timers.target\n'),
                ('takcotdbguard.service', '[Unit]\nDescription=TAK CoT Database Size Monitor\nAfter=' + _PG_SVC_AFTER + '\n\n[Service]\nType=oneshot\nExecStart=/opt/tak-guarddog/tak-cotdb-watch.sh\n'),
                ('takcotdbguard.timer', '[Unit]\nDescription=Run TAK CoT DB size monitor every 6 hours\n\n[Timer]\nOnBootSec=30min\nOnUnitActiveSec=6h\nUnit=takcotdbguard.service\n\n[Install]\nWantedBy=timers.target\n'),
                ('takautovacuum.service', '[Unit]\nDescription=Guard Dog Smart Auto-VACUUM\nAfter=' + _PG_SVC_AFTER + '\n\n[Service]\nType=oneshot\nExecStart=/opt/tak-guarddog/tak-auto-vacuum.sh\n'),
                ('takautovacuum.timer', '[Unit]\nDescription=Run smart auto-VACUUM daily at 3am\n\n[Timer]\nOnCalendar=*-*-* 03:00:00\nPersistent=true\nUnit=takautovacuum.service\n\n[Install]\nWantedBy=timers.target\n'),
                ('takdbrepack.service', '[Unit]\nDescription=Guard Dog Online DB Repack (pg_repack)\nAfter=' + _PG_SVC_AFTER + '\n\n[Service]\nType=oneshot\nTimeoutStartSec=3600\nExecStart=/opt/tak-guarddog/tak-db-repack.sh\n'),
                ('takdbrepack.timer', '[Unit]\nDescription=Run online DB repack weekly (Sunday 4am)\n\n[Timer]\nOnCalendar=Sun *-*-* 04:00:00\nPersistent=true\nUnit=takdbrepack.service\n\n[Install]\nWantedBy=timers.target\n'),
                ('takretentionguard.service', '[Unit]\nDescription=Guard Dog CoT Retention Safety Net\nAfter=' + _PG_SVC_AFTER + '\n\n[Service]\nType=oneshot\nTimeoutStartSec=1800\nExecStart=/opt/tak-guarddog/tak-retention-guard.sh\n'),
                ('takretentionguard.timer', '[Unit]\nDescription=Run CoT retention guard every 15 minutes\n\n[Timer]\nOnBootSec=10min\nOnUnitActiveSec=15min\nUnit=takretentionguard.service\n\n[Install]\nWantedBy=timers.target\n'),
            ])
        # Optional timers for other services (only if we installed the script)
        if 'tak-authentik-watch.sh' in script_files:
            units.extend([
                ('takauthentikguard.service', '[Unit]\nDescription=Guard Dog Authentik Monitor\n\n[Service]\nType=oneshot\nExecStart=/opt/tak-guarddog/tak-authentik-watch.sh\n'),
                ('takauthentikguard.timer', '[Unit]\nDescription=Run Authentik guard every 1 minute\n\n[Timer]\nOnBootSec=15min\nOnUnitActiveSec=1min\nUnit=takauthentikguard.service\n\n[Install]\nWantedBy=timers.target\n'),
            ])
            # Authentik task log purge — weekly cleanup of authentik_tasks_task/tasklog tables
            # v0.9.26: script body comes from the canonical _AUTHENTIK_TASKLOG_PURGE_SCRIPT
            # constant (see app.py around line 33985). Fixed the v0.9.5 VACUUM-in-transaction
            # bug + replaced the 30-day-only window with a 7d → 24h → 1h tier ladder.
            _ak_purge_path = '/opt/tak-guarddog/tak-authentik-tasklog-purge.sh'
            try:
                _ak_purge_same = _read_priv(_ak_purge_path) == _AUTHENTIK_TASKLOG_PURGE_SCRIPT
                if _ak_purge_same:
                    _chmod_priv(_ak_purge_path, 0o755)   # keep +x; leave mtime alone
            except Exception:
                _ak_purge_same = False
            if not _ak_purge_same:
                _write_priv(_ak_purge_path, _AUTHENTIK_TASKLOG_PURGE_SCRIPT, perm=0o755)
            units.extend([
                ('takauthentiktasklogpurge.service', '[Unit]\nDescription=Guard Dog Authentik Task Log Purge\n\n[Service]\nType=oneshot\nExecStart=/opt/tak-guarddog/tak-authentik-tasklog-purge.sh\n'),
                ('takauthentiktasklogpurge.timer', '[Unit]\nDescription=Purge Authentik task logs weekly (Sunday 03:00)\n\n[Timer]\nOnCalendar=Sun *-*-* 03:00:00\nPersistent=true\nUnit=takauthentiktasklogpurge.service\n\n[Install]\nWantedBy=timers.target\n'),
            ])
        if 'tak-mediamtx-watch.sh' in script_files:
            units.extend([
                ('takmediamtxguard.service', '[Unit]\nDescription=Guard Dog MediaMTX Monitor\n\n[Service]\nType=oneshot\nExecStart=/opt/tak-guarddog/tak-mediamtx-watch.sh\n'),
                ('takmediamtxguard.timer', '[Unit]\nDescription=Run MediaMTX guard every 1 minute\n\n[Timer]\nOnBootSec=15min\nOnUnitActiveSec=1min\nUnit=takmediamtxguard.service\n\n[Install]\nWantedBy=timers.target\n'),
            ])
        if 'tak-nodered-watch.sh' in script_files:
            units.extend([
                ('taknoderedguard.service', '[Unit]\nDescription=Guard Dog Node-RED Monitor\n\n[Service]\nType=oneshot\nExecStart=/opt/tak-guarddog/tak-nodered-watch.sh\n'),
                ('taknoderedguard.timer', '[Unit]\nDescription=Run Node-RED guard every 1 minute\n\n[Timer]\nOnBootSec=15min\nOnUnitActiveSec=1min\nUnit=taknoderedguard.service\n\n[Install]\nWantedBy=timers.target\n'),
            ])
        if 'tak-feedsource-watch.sh' in script_files:
            # Hourly, not per-minute like the service monitors: this watches an EXTERNAL
            # publisher's edit timestamp, the threshold is 6h, and each run costs one
            # HTTPS request per configured feed against a third-party service.
            units.extend([
                ('takfeedsourceguard.service', '[Unit]\nDescription=Guard Dog Map Feed Source Monitor (upstream publisher staleness)\n\n[Service]\nType=oneshot\nExecStart=/opt/tak-guarddog/tak-feedsource-watch.sh\n'),
                ('takfeedsourceguard.timer', '[Unit]\nDescription=Check map feed sources hourly\n\n[Timer]\nOnBootSec=20min\nOnUnitActiveSec=1h\nUnit=takfeedsourceguard.service\n\n[Install]\nWantedBy=timers.target\n'),
            ])
        if 'tak-cloudtak-watch.sh' in script_files:
            units.extend([
                ('takcloudtakguard.service', '[Unit]\nDescription=Guard Dog CloudTAK Monitor\n\n[Service]\nType=oneshot\nExecStart=/opt/tak-guarddog/tak-cloudtak-watch.sh\n'),
                ('takcloudtakguard.timer', '[Unit]\nDescription=Run CloudTAK guard every 1 minute\n\n[Timer]\nOnBootSec=15min\nOnUnitActiveSec=1min\nUnit=takcloudtakguard.service\n\n[Install]\nWantedBy=timers.target\n'),
            ])
        if 'tak-takportal-watch.sh' in script_files:
            units.extend([
                ('taktakportalguard.service', '[Unit]\nDescription=Guard Dog TAK Portal Monitor\n\n[Service]\nType=oneshot\nExecStart=/opt/tak-guarddog/tak-takportal-watch.sh\n'),
                ('taktakportalguard.timer', '[Unit]\nDescription=Run TAK Portal guard every 1 minute\n\n[Timer]\nOnBootSec=15min\nOnUnitActiveSec=1min\nUnit=taktakportalguard.service\n\n[Install]\nWantedBy=timers.target\n'),
            ])
        if 'tak-fedhub-watch.sh' in script_files:
            units.extend([
                ('takfedhubguard.service', '[Unit]\nDescription=Guard Dog Federation Hub Monitor\nAfter=network-online.target\n\n[Service]\nType=oneshot\nExecStart=/opt/tak-guarddog/tak-fedhub-watch.sh\n'),
                ('takfedhubguard.timer', '[Unit]\nDescription=Run Federation Hub guard every 1 minute\n\n[Timer]\nOnBootSec=15min\nOnUnitActiveSec=1min\nUnit=takfedhubguard.service\n\n[Install]\nWantedBy=timers.target\n'),
            ])
        # v10.1.46 (W1) — the client gate's INDEPENDENT backstop. It must not depend
        # on tak-post-start.sh having run, completed, or even existing: this is the
        # net under the net. OnBootSec only (no OnUnitActiveSec) — it fires once per
        # boot, 15 minutes in, and releases whether or not a gate is present.
        # v10.1.46 (W2) — session visibility watcher: read-only, alerts only.
        units.extend(_CLIENT_GATE_UNITS)
        # v10.1.69 W5: takupdatesguard.service/.timer are NOT written any more. They ran
        # tak-updates-watch.sh, which mailed the same pending updates as the in-process
        # _update_notify_loop() notifier on a separate 6h cycle — two emails per update set.
        # The Python notifier wins: per-identity dedup, a console toggle, and it names each
        # item installed -> target. Existing units are removed by the migration above.
        for name, content in units:
            path = os.path.join('/etc/systemd/system', name)
            _write_priv(path, content)
        plog("✓ Systemd units installed")
        # TAK Server soft start: start after network and PostgreSQL to avoid boot race / restart loops.
        # v10.0.1: skip on container TAK — there is no host takserver.service to
        # attach a drop-in to (the container uses --restart=always), so the boot
        # sequencer / ExecStartPre never fires. Writing it would be inert clutter.
        if _tak_is_container():
            plog("✓ Container TAK — skipping native soft-start drop-in (container uses --restart=always)")
        else:
            tak_dropin_dir = '/etc/systemd/system/takserver.service.d'
            _makedirs_priv(tak_dropin_dir)
            tak_dropin = os.path.join(tak_dropin_dir, 'soft-start.conf')
            # TimeoutStartSec must exceed the boot sequencer's MAX_WAIT (120s):
            # systemd's 90s default would otherwise kill start-pre mid-wait and
            # mark the unit failed(timeout) before the sequencer's "proceed anyway"
            # fallback can fire. Universal hardening — applies to every distro.
            # v10.1.46 (W6): `+` = run ExecStartPre with FULL PRIVILEGES regardless of
            # the unit's User=. On RHEL, TAK's .rpm unit carries User=tak, so the boot
            # sequencer ran UNPRIVILEGED there and every privileged step silently
            # no-opped: `docker stop` (the whole CPU-headroom design), `systemctl stop
            # mediamtx`, and — as of this release — the client gate's firewall-cmd.
            # Measured on nuc 2026-08-24: not one container-stop line logged (each is
            # `docker ... && _log`, so the && short-circuits), TAK took 210s to open
            # 8089 against 20-30s on the Debian boxes, and its messaging JVM crashed on
            # the way up. Debian's .deb unit runs ExecStartPre as root already, so `+`
            # is a no-op there. This has been broken on RHEL since 10.1.44.
            _write_priv(tak_dropin, '[Unit]\nAfter=network-online.target ' + _PG_SVC_AFTER + '\nWants=network-online.target\n\n[Service]\nTimeoutStartSec=300\nExecStartPre=+-/opt/tak-guarddog/tak-boot-sequencer.sh\n')
            plog("✓ TAK Server soft-start drop-in installed (boot sequencer waits for PostgreSQL + Authentik before TAK starts)")
            # v10.1.63 W3: pin TAK to its own JDK 17 in the same breath. Also re-applied on
            # every console startup — see _pin_takserver_jvm().
            try:
                _pin_takserver_jvm(plog)
            except Exception as _je:
                plog(f"\u26a0 JVM pin skipped: {_je}")
        # 4GB swap for memory stability (from reference TAK Server Hardening script)
        try:
            r = subprocess.run(_sudo_wrap(['swapon', '--show']), capture_output=True, text=True, timeout=5)
            if r.returncode == 0 and '/swapfile' in (r.stdout or ''):
                plog("✓ Swap already configured, skipping")
            else:
                if os.path.exists('/swapfile'):
                    subprocess.run(_sudo_wrap(['swapon', '/swapfile']), capture_output=True, timeout=5)
                    fstab = _read_priv('/etc/fstab')
                    if '/swapfile' not in fstab:
                        _write_priv('/etc/fstab', '\n/swapfile swap swap defaults 0 0\n', mode='a')
                    plog("✓ Swap file enabled")
                else:
                    subprocess.run(_sudo_wrap(['fallocate', '-l', '4G', '/swapfile']), check=True, timeout=30)
                    _chmod_priv('/swapfile', 0o600)
                    subprocess.run(_sudo_wrap(['mkswap', '/swapfile']), check=True, capture_output=True, timeout=10)
                    subprocess.run(_sudo_wrap(['swapon', '/swapfile']), check=True, timeout=10)
                    fstab = _read_priv('/etc/fstab')
                    if '/swapfile' not in fstab:
                        _write_priv('/etc/fstab', '\n/swapfile swap swap defaults 0 0\n', mode='a')
                    plog("✓ 4GB swap configured (memory stability)")
        except Exception as e:
            plog(f"⚠ Swap setup skipped: {e}")
        # Low swappiness: only use swap when RAM is actually exhausted.
        # Default 60 aggressively swaps out processes even with tons of free RAM,
        # causing severe performance issues on VPS with mediocre disk I/O.
        try:
            cur = subprocess.run(_sudo_wrap(['sysctl', '-n', 'vm.swappiness']), capture_output=True, text=True, timeout=5)
            if cur.returncode == 0 and cur.stdout.strip() != '10':
                subprocess.run(_sudo_wrap(['sysctl', '-w', 'vm.swappiness=10']), capture_output=True, timeout=5)
                sysctl_conf = '/etc/sysctl.conf'
                content = _read_priv(sysctl_conf)
                if 'vm.swappiness' in content:
                    lines = content.split('\n')
                    lines = [('vm.swappiness=10' if l.strip().startswith('vm.swappiness') else l) for l in lines]
                    _write_priv(sysctl_conf, '\n'.join(lines))
                else:
                    _write_priv(sysctl_conf, content + '\nvm.swappiness=10\n')
                plog("✓ vm.swappiness set to 10 (swap only when RAM exhausted)")
            else:
                plog("✓ vm.swappiness already 10")
        except Exception as e:
            plog(f"⚠ Swappiness tuning skipped: {e}")
        r = subprocess.run(_sudo_wrap(['systemctl', 'daemon-reload']), capture_output=True, text=True, timeout=60)
        if r.returncode != 0:
            plog(f"✗ daemon-reload failed: {r.stderr}")
            guarddog_deploy_status.update({'running': False, 'error': True})
            return
        timers = ['tak8089guard.timer', 'takoomguard.timer', 'takdiskguard.timer', 'takdiskioguard.timer',
                  'takswapreclaim.timer', 'takbuildcachereclaim.timer',
                  'taknetguard.timer', 'takrelayguard.timer', 'takwerxsetupapwatch.timer',
                  'takprocessguard.timer', 'takcertguard.timer', 'takintcaguard.timer',
                  'takjvmguard.timer']
        if is_two_server and s1_host:
            timers.append('takremotedbguard.timer')
            timers.append('takcotdbguard.timer')
        else:
            timers.extend(['takdbguard.timer', 'takcotdbguard.timer'])
        timers.append('takautovacuum.timer')
        if 'tak-authentik-watch.sh' in script_files:
            timers.append('takauthentikguard.timer')
            timers.append('takauthentiktasklogpurge.timer')
        if 'tak-mediamtx-watch.sh' in script_files:
            timers.append('takmediamtxguard.timer')
        if 'tak-nodered-watch.sh' in script_files:
            timers.append('taknoderedguard.timer')
        if 'tak-feedsource-watch.sh' in script_files:
            # v10.1.34. Registering a watcher takes THREE edits, not two: the script
            # (script_files), the unit files (units), and enabling the timer HERE.
            # Missing this one wrote both unit files and left the timer disabled and
            # inactive — installed, invisible, and silent. Caught on test12 2026-08-14.
            timers.append('takfeedsourceguard.timer')
        if 'tak-cloudtak-watch.sh' in script_files:
            timers.append('takcloudtakguard.timer')
        if 'tak-takportal-watch.sh' in script_files:
            timers.append('taktakportalguard.timer')
        if 'tak-fedhub-watch.sh' in script_files:
            timers.append('takfedhubguard.timer')
        # v10.1.69 W5: takupdatesguard.timer deliberately NOT enabled — retired.
        # v10.1.46: the gate backstop and the session watcher. A timer written but
        # not enabled is the exact bug called out above for takfeedsourceguard —
        # and for the gate backstop it would be the difference between a released
        # gate and a locked-out fleet.
        timers.append('takclientgate.timer')
        timers.append('taksessionguard.timer')
        for t in timers:
            re = subprocess.run(_sudo_wrap(['systemctl', 'enable', t]), capture_output=True, text=True, timeout=5)
            if re.returncode != 0:
                plog(f"✗ systemctl enable {t} failed: {re.stderr or re.stdout or 'unknown'}")
                guarddog_deploy_status.update({'running': False, 'error': True})
                return
            rs = subprocess.run(_sudo_wrap(['systemctl', 'start', t]), capture_output=True, text=True, timeout=5)
            if rs.returncode != 0:
                plog(f"⚠ systemctl start {t} failed (continuing): {rs.stderr or rs.stdout or 'unknown'}")
        _guarddog_apply_diskio_timer(settings)
        _guarddog_sync_diskio_email_off_file(settings)
        re = subprocess.run(_sudo_wrap(['systemctl', 'enable', 'tak-health.service']), capture_output=True, text=True, timeout=5)
        if re.returncode != 0:
            plog(f"✗ systemctl enable tak-health.service failed: {re.stderr or re.stdout or 'unknown'}")
            guarddog_deploy_status.update({'running': False, 'error': True})
            return
        subprocess.run(_sudo_wrap(['systemctl', 'start', 'tak-health.service']), capture_output=True, timeout=5)
        # v0.9.47: network/fanout metrics collector (always-on, like tak-health). Best-effort
        # start — a collector failure must never block the rest of the Guard Dog deploy.
        rmc = subprocess.run(_sudo_wrap(['systemctl', 'enable', 'tak-metrics-collector.service']), capture_output=True, text=True, timeout=5)
        if rmc.returncode != 0:
            plog(f"⚠ enable tak-metrics-collector.service failed (continuing): {rmc.stderr or rmc.stdout or 'unknown'}")
        else:
            subprocess.run(_sudo_wrap(['systemctl', 'restart', 'tak-metrics-collector.service']), capture_output=True, timeout=5)
            plog("✓ Network/fanout metrics collector started")
        # v0.9.12 A6: source-scope UFW for Guard Dog health endpoint
        _auto_harden_guarddog_8080(settings, plog=plog)
        subprocess.run(_sudo_wrap(['systemctl', 'enable', 'tak-post-start.service']), capture_output=True, text=True, timeout=5)
        # v10.1.57 W4: boot oneshot, so it needs enabling the same way — a timer would
        # never fire it (there is exactly one previous boot to classify, at boot).
        subprocess.run(_sudo_wrap(['systemctl', 'enable', 'takrestartwatch.service']), capture_output=True, text=True, timeout=5)
        plog("✓ Boot orchestrator enabled (staggered start: TAK → Authentik → TAK Portal → CloudTAK)")
        for f in ['process_alert_sent', 'disk_alert_sent', 'db_alert_sent', 'cotdb_alert_sent', 'network_alert_sent', 'cert_alert_sent']:
            p = os.path.join('/var/lib/takguard', f)
            subprocess.run(_sudo_wrap(['touch', p]), capture_output=True)
        if not _guarddog_is_enabled():
            plog("✗ Timers did not end up enabled; run Enable on the Guard Dog page or retry deploy.")
            guarddog_deploy_status.update({'running': False, 'error': True})
            return
        plog("✓ Timers and health endpoint started")

        # Two-server: deploy health agent to Server One via SSH/SCP
        if is_two_server and s1_host and os.path.exists(ssh_key_path):
            plog(f"Deploying health agent to Server One / remote server ({s1_host})...")
            s1_cfg = tak_cfg.get('server_one', {})
            agent_src = os.path.join(scripts_dir, 'tak-db-health-agent.py')
            if os.path.isfile(agent_src):
                # v10.0.5: land in /tmp — Server One's SSH user (e.g. rocky) isn't root and
                # scp can't sudo, so a scp to root-owned /opt failed ("Permission denied").
                scp_ok, scp_out = _scp_to_host(s1_cfg, agent_src, '/tmp/', timeout=30)
                if scp_ok:
                    # Open port 8080 on Server One — backend-aware (firewalld on RHEL, ufw on
                    # Debian; the old `sudo ufw` hard-code silently no-op'd on a Rocky Server One).
                    _gd_src_ip = _fedhub_caddy_source_ip(settings)
                    try:
                        _gd_dbh, _gd_dbp = _remotedb_host_port_from_tak_settings()
                        _gd_db_port = int(_gd_dbp or 5432)
                    except Exception:
                        _gd_db_port = 5432
                    _gd_fw_step = _remote_healthagent_fw_step(_gd_db_port, _gd_src_ip)
                    setup_cmd = (
                        'SRC=$(echo "$SSH_CLIENT" | awk \'{print $1}\'); '
                        'sudo mkdir -p /opt/tak-guarddog && '
                        'sudo mv /tmp/tak-db-health-agent.py /opt/tak-guarddog/tak-db-health-agent.py && '
                        'sudo chmod 644 /opt/tak-guarddog/tak-db-health-agent.py && '
                        'cat > /tmp/tak-db-health.service << \'UNIT\'\n'
                        '[Unit]\n'
                        'Description=TAK Database Health Endpoint\n'
                        'After=network.target postgresql.service\n\n'
                        '[Service]\n'
                        'Type=simple\n'
                        'ExecStart=/usr/bin/python3 /opt/tak-guarddog/tak-db-health-agent.py\n'
                        'Restart=always\n'
                        'RestartSec=10\n\n'
                        '[Install]\n'
                        'WantedBy=multi-user.target\n'
                        'UNIT\n'
                        'sudo mv /tmp/tak-db-health.service /etc/systemd/system/tak-db-health.service && '
                        # RHEL/SELinux: restore the unit + agent contexts (mv from /tmp keeps tmp_t →
                        # systemd can't open the unit). No-op on Ubuntu; `; true` keeps the && chain.
                        '{ command -v restorecon >/dev/null 2>&1 && sudo restorecon -RF /opt/tak-guarddog /etc/systemd/system/tak-db-health.service 2>/dev/null; true; } && '
                        'sudo systemctl daemon-reload && '
                        'sudo systemctl enable tak-db-health.service && '
                        'sudo systemctl restart tak-db-health.service && '
                        + _gd_fw_step +
                        'echo AGENT_OK'
                    )
                    ok, out = _ssh_probe(s1_cfg, setup_cmd, timeout=30)
                    if ok and 'AGENT_OK' in (out or ''):
                        plog(f"✓ Health agent running on Server One — http://{s1_host}:8080/health")
                    else:
                        plog(f"⚠ Health agent install on Server One had issues: {(out or '')[:200]}")
                else:
                    plog(f"⚠ Could not SCP health agent to Server One: {(scp_out or '')[:200]}")
            else:
                plog("⚠ tak-db-health-agent.py not found in scripts — skipping Server One agent")
        elif is_two_server and s1_host:
            plog("⚠ SSH key not found — skipping Server One health agent deploy")

        plog("✓ Deployment complete")
        # Stamp the deployed version + settings so the UI can detect when re-deploy is needed
        try:
            _s = load_settings()
            _s['guarddog_deployed_version'] = VERSION
            _s['guarddog_deployed_email'] = (_s.get('guarddog_alert_email') or '').strip()
            _s['guarddog_deployed_nickname'] = (_s.get('guarddog_server_nickname') or '').strip()
            save_settings(_s)
        except Exception:
            pass
        guarddog_deploy_status.update({'running': False, 'complete': True, 'error': False})
    except Exception as e:
        plog(f"✗ Error: {str(e)}")
        guarddog_deploy_status.update({'running': False, 'error': True})

@app.route('/nodered')
@login_required
def nodered_page():
    settings = load_settings()
    modules = detect_modules()
    nr = modules.get('nodered', {})
    ak = modules.get('authentik', {})
    nodered_deploy_cfg = _get_module_deployment_config(settings, 'nodered_deployment')
    nodered_remote_host = None
    if nodered_deploy_cfg.get('target_mode') == 'remote':
        nodered_remote_host = (nodered_deploy_cfg.get('remote', {}).get('host') or '').strip() or None
    resp = make_response(render_template('nodered.html',
        settings=settings, nr=nr, version=VERSION,
        authentik_installed=ak.get('installed'),
        nodered_deploy_cfg=nodered_deploy_cfg,
        nodered_remote_host=nodered_remote_host,
        deploying=nodered_deploy_status.get('running', False),
        deploy_done=nodered_deploy_status.get('complete', False),
        caddy_logo_url=CADDY_LOGO_URL, tak_logo_url=TAK_LOGO_URL, authentik_logo_url=AUTHENTIK_LOGO_URL,
        cloudtak_icon=CLOUDTAK_ICON, mediamtx_logo_url=MEDIAMTX_LOGO_URL))
    resp.headers['Cache-Control'] = 'no-store, no-cache, must-revalidate'
    return resp

@app.route('/cloudtak')
@login_required
def cloudtak_page():
    settings = load_settings()
    cloudtak_cfg = _get_cloudtak_deployment_config(settings)
    cloudtak_tak_suggest = _suggest_tak_core_host(settings)
    ct_bootstrap_user, ct_bootstrap_pass = _get_webadmin_defaults(settings)
    ct_cert_pass = _get_tak_cert_password(settings)
    cloudtak = detect_modules().get('cloudtak', {})
    container_info = {}
    if cloudtak.get('running'):
        containers = []
        if cloudtak_cfg.get('target_mode') == 'remote':
            rcfg = cloudtak_cfg.get('remote', {})
            ok, out = _ssh_probe(rcfg, "docker ps --filter 'name=cloudtak' --format '{{.Names}}|||{{.Status}}' 2>/dev/null", timeout=12)
            if ok:
                for line in (out or '').strip().split('\n'):
                    if line.strip():
                        parts = line.split('|||')
                        containers.append({'name': parts[0], 'status': parts[1] if len(parts) > 1 else ''})
        else:
            r = subprocess.run(_sudo_wrap(['docker', 'ps', '--filter', 'name=cloudtak', '--format', '{{.Names}}|||{{.Status}}']), capture_output=True, text=True, timeout=5)
            for line in (r.stdout or '').strip().split('\n'):
                if line.strip():
                    parts = line.split('|||')
                    containers.append({'name': parts[0], 'status': parts[1] if len(parts) > 1 else ''})
        container_info['containers'] = containers
    ct_vinfo = _get_cloudtak_version_info() if cloudtak.get('installed') else {}
    ct_version = ct_vinfo.get('version', '')
    ct_update_available = ct_vinfo.get('update_available', False)
    ct_latest = ct_vinfo.get('latest', '')
    # v0.9.11 security advisory state — drives the in-UI banner.
    # compromise_detected: ~/CloudTAK/COMPROMISE-DETECTED.txt was written by
    #   _auto_harden_cloudtak() because malware persistence (.so + shared_preload_libraries)
    #   was found in the postgis data volume during the last Update Now.
    # legacy_install: the install pre-dates v0.9.11 (no .postgres-password file). Postgis
    #   still has the upstream 'docker' password baked into pg_authid — Remove + Reinstall
    #   is required to rotate to the strong random value, even though network is locked.
    sec_compromised = False
    sec_legacy_install = False
    try:
        _ct_dir = os.path.expanduser('~/CloudTAK')
        if cloudtak.get('installed') and cloudtak_cfg.get('target_mode') != 'remote':
            sec_compromised = os.path.exists(os.path.join(_ct_dir, 'COMPROMISE-DETECTED.txt'))
            sec_legacy_install = not os.path.exists(os.path.join(_ct_dir, '.postgres-password'))
    except Exception:
        pass
    # Only probe plugin dirs when CloudTAK is installed locally — skip for remote
    ct_plugins = []
    if cloudtak.get('installed') and cloudtak_cfg.get('target_mode') != 'remote':
        try:
            ct_plugins = _detect_cloudtak_plugins()
        except Exception:
            ct_plugins = []
    return render_template('cloudtak.html',
        settings=settings, cloudtak=cloudtak,
        version=VERSION,
        cloudtak_version=ct_version,
        cloudtak_update_available=ct_update_available,
        cloudtak_latest=ct_latest,
        cloudtak_version_info=ct_vinfo,
        cloudtak_icon=CLOUDTAK_ICON,
        cloudtak_cfg=cloudtak_cfg,
        cloudtak_tak_suggest=cloudtak_tak_suggest,
        cloudtak_bootstrap_user=ct_bootstrap_user,
        cloudtak_bootstrap_pass=ct_bootstrap_pass,
        cloudtak_cert_password=ct_cert_pass,
        container_info=container_info,
        sec_compromised=sec_compromised,
        sec_legacy_install=sec_legacy_install,
        cloudtak_plugins=ct_plugins,
        deploying=cloudtak_deploy_status.get('running', False),
        deploy_done=cloudtak_deploy_status.get('complete', False),
        deploy_error=cloudtak_deploy_status.get('error', False))

