# set-password/update/update-status) are registry-registered at the SAME URLs
# by modules/tvr.py since v10.1.24 — only the page route above remains here.


def _configure_authentik_smtp_and_recovery_remote(deploy_cfg, from_addr, settings, plog=None):
    """Remote-deploy variant: SSH to the Authentik host, patch .env with SMTP settings
    pointing to the console server's Postfix, restart containers, set up recovery flow.
    Returns a status message string. Raises on fatal error."""
    import base64 as _b64
    _log = plog or (lambda msg: None)
    host = (deploy_cfg.get('remote', {}).get('host') or '').strip()
    if not host:
        raise RuntimeError('Remote host not configured in Authentik deployment settings.')
    _from = (from_addr or '').strip() or 'authentik@localhost'
    # Email Relay (Postfix) runs on the console server — Authentik must connect to it over the network
    console_ip = (settings.get('server_ip') or '').strip()
    smtp_host = console_ip if console_ip and console_ip not in ('localhost', '127.0.0.1') else host
    email_lines = '\n'.join([
        '',
        '# Email — use console server Email Relay (Postfix)',
        f'AUTHENTIK_EMAIL__HOST={smtp_host}',
        'AUTHENTIK_EMAIL__PORT=25',
        'AUTHENTIK_EMAIL__USERNAME=',
        'AUTHENTIK_EMAIL__PASSWORD=',
        'AUTHENTIK_EMAIL__USE_TLS=false',
        'AUTHENTIK_EMAIL__USE_SSL=false',
        'AUTHENTIK_EMAIL__TIMEOUT=10',
        f'AUTHENTIK_EMAIL__FROM={_from}',
    ])
    # Read current .env from remote, strip old email settings, append new ones
    _ok, _env_out = _module_run(deploy_cfg, 'cat ~/authentik/.env 2>/dev/null || true', timeout=10)
    env_lines = []
    for line in (_env_out or '').splitlines():
        if not line.strip().startswith('AUTHENTIK_EMAIL__'):
            env_lines.append(line)
    if env_lines and env_lines[-1].strip() != '':
        env_lines.append('')
    new_env = '\n'.join(env_lines) + email_lines + '\n'
    encoded = _b64.b64encode(new_env.encode()).decode()
    _ok, _out = _module_run(deploy_cfg,
        f"echo '{encoded}' | base64 -d > ~/authentik/.env", timeout=15)
    if not _ok:
        raise RuntimeError(f'Could not write .env on remote host: {_out}')
    _log('  Wrote SMTP settings to remote Authentik .env')
    # Open port 25 on the console server for the remote Authentik host
    if host:
        subprocess.run(_sudo_wrap(['ufw', 'allow', 'from', host, 'to', 'any', 'port', '25', 'proto', 'tcp']), capture_output=True)
        subprocess.run(_sudo_wrap(['ufw', 'reload']), capture_output=True)
        _log(f'  UFW: allowed {host} → port 25 (console Postfix)')
    # Recreate ONLY server + worker (SMTP env) — recreating the whole stack races
    # the just-recreated LDAP outpost → name conflict (see local variant). --no-deps
    # leaves db/redis/ldap untouched.
    _log('  Recreating Authentik server + worker for SMTP on remote (ldap/db/redis untouched)...')
    _ok, _out = _module_run(deploy_cfg,
        'cd ~/authentik && docker compose up -d --force-recreate --no-deps --remove-orphans server worker 2>&1', timeout=120)
    if not _ok:
        raise RuntimeError(f'Authentik restart failed on remote: {(_out or "")[:300]}')
    _log('  ✓ Authentik restarted')
    # Retrieve bootstrap token from remote .env
    _ok2, _tok_out = _module_run(deploy_cfg,
        "grep '^AUTHENTIK_BOOTSTRAP_TOKEN=' ~/authentik/.env | head -1 | cut -d= -f2-",
        timeout=10)
    ak_token = (_tok_out or '').strip().strip('"').strip("'")
    message = f'Authentik SMTP configured ({smtp_host}:25).'
    if ak_token:
        ak_url = f'http://{host}:9090'
        ak_headers = {'Authorization': f'Bearer {ak_token}', 'Content-Type': 'application/json'}
        _log('  Waiting for Authentik API...')
        api_ready = _wait_for_authentik_api(ak_url, ak_headers, max_attempts=120, plog=_log)
        if api_ready:
            _log('  Setting up recovery flow...')
            ok, recovery_msg, recovery_slug = _ensure_authentik_recovery_flow(ak_url, ak_headers)
            if ok:
                message += ' ' + recovery_msg
                if recovery_slug:
                    base = _get_authentik_base_url(settings)
                    message += f' Direct recovery URL: {base}/if/flow/{recovery_slug}/.'
            else:
                message += f' Recovery flow issue: {recovery_msg}.'
        else:
            message += ' API not ready in time — recovery flow not set up.'
    # Persist the configured state so the status badge shows correctly on next page load
    try:
        s = load_settings()
        s['authentik_smtp_configured_remote'] = True
        save_settings(s)
    except Exception:
        pass
    return message


def _authentik_ldap_recreate_in_flight():
    """True while authentik-ldap-1 exists but is not Up (mid-recreate/restarting).

    The Email-Relay deploy's SMTP restart must not touch the Authentik stack while the
    LDAP outpost is being recreated (e.g. an Authentik deploy's outpost step just ran) —
    concurrent compose ops collide on the container name and abort mid-recreate, leaving
    Authentik down (memory authentik-deploy-emailrelay-smtp-restart-conflict)."""
    try:
        r = subprocess.run(_sudo_wrap(['docker', 'ps', '-a', '--filter', 'name=authentik-ldap-1',
                                       '--format', '{{.Status}}']),
                           capture_output=True, text=True, timeout=10)
        lines = [l for l in (r.stdout or '').strip().splitlines() if l.strip()]
        if not lines:
            return False  # no LDAP outpost container — nothing to race
        return not lines[0].startswith('Up')
    except Exception:
        return False


def _authentik_recover_compose_conflict(ak_dir, err, plog):
    """Self-heal the 'container name already in use' compose abort: rm -f the conflicting
    container(s) named in the error, then bring the full stack up. This is the manual
    recovery operators used to run by hand (docker rm -f + up -d), now automatic."""
    import re as _re
    names = set(_re.findall(r'container name "/?([A-Za-z0-9._-]+)" is already in use', err))
    if not names:
        names = {'authentik-ldap-1'}  # the historical collider
    for ref in sorted(names):
        plog(f"  Removing conflicting container {ref}...")
        subprocess.run(_sudo_wrap(['docker', 'rm', '-f', ref]), capture_output=True, text=True, timeout=60)
    with _authentik_compose_lock('conflict-recovery', plog=plog) as _locked:  # v10.1.55 W3
        if not _locked:
            raise RuntimeError('Authentik recovery deferred: another healer holds the compose lock')
        r = subprocess.run(_sudo_wrap(['docker', 'compose', 'up', '-d', '--remove-orphans']),
                           cwd=ak_dir, capture_output=True, text=True, timeout=300)
    if r.returncode != 0:
        raise RuntimeError(f'Authentik recovery up -d failed: {(r.stderr or r.stdout)[:400]}')
    plog("  ✓ Authentik stack recovered (conflicting containers removed, full up -d)")


def _configure_authentik_smtp_and_recovery(from_addr, plog=None):
    """Push SMTP settings into Authentik .env, restart containers, and set up recovery flow.
    Used by both the Email Relay deploy and the 'Configure Authentik' button.
    Returns a status message string. Raises on fatal error."""
    import re as _re
    ak_dir = os.path.expanduser('~/authentik')
    env_path = os.path.join(ak_dir, '.env')
    smtp_host = 'host.docker.internal'
    _from = (from_addr or '').strip() or 'authentik@localhost'
    _log = plog or (lambda msg: None)

    email_block = [
        '',
        '# Email — use local relay (Postfix on host)',
        f'AUTHENTIK_EMAIL__HOST={smtp_host}',
        'AUTHENTIK_EMAIL__PORT=25',
        'AUTHENTIK_EMAIL__USERNAME=',
        'AUTHENTIK_EMAIL__PASSWORD=',
        'AUTHENTIK_EMAIL__USE_TLS=false',
        'AUTHENTIK_EMAIL__USE_SSL=false',
        'AUTHENTIK_EMAIL__TIMEOUT=10',
        f'AUTHENTIK_EMAIL__FROM={_from}',
    ]
    lines = []
    if os.path.exists(env_path):
        with open(env_path) as f:
            for line in f:
                if line.strip().startswith('AUTHENTIK_EMAIL__'):
                    continue
                lines.append(line.rstrip('\n'))
    if lines and lines[-1].strip() != '':
        lines.append('')
    lines.extend(email_block)
    with open(env_path, 'w') as f:
        f.write('\n'.join(lines) + '\n')
    _log("  Wrote SMTP settings to Authentik .env")

    override_path = os.path.join(ak_dir, 'docker-compose.override.yml')
    override_content = '''# infra-TAK: allow containers to reach host Postfix for email
services:
  server:
    extra_hosts:
      - "host.docker.internal:host-gateway"
  worker:
    extra_hosts:
      - "host.docker.internal:host-gateway"
'''
    with open(override_path, 'w') as f:
        f.write(override_content)

    main_cf_path = '/etc/postfix/main.cf'
    if os.path.exists(main_cf_path):
        with open(main_cf_path) as f:
            mc = f.read()
        changed = False
        # So Docker (Authentik) can connect: listen on all interfaces
        if _re.search(r'^\s*inet_interfaces\s*=\s*localhost', mc, flags=_re.MULTILINE):
            mc = _re.sub(r'^\s*inet_interfaces\s*=\s*.*$', 'inet_interfaces = all', mc, flags=_re.MULTILINE)
            changed = True
        elif 'inet_interfaces' not in mc or _re.search(r'^\s*#\s*inet_interfaces', mc, flags=_re.MULTILINE):
            if mc.strip() and not mc.endswith('\n\n'):
                mc = mc.rstrip() + '\n'
            mc += 'inet_interfaces = all\n'
            changed = True
        if '172.16.0.0/12' not in mc:
            mc = _re.sub(r'^\s*mynetworks\s*=.*$', '', mc, flags=_re.MULTILINE)
            if mc.strip() and not mc.endswith('\n\n'):
                mc = mc.rstrip() + '\n'
            mc += 'mynetworks = 127.0.0.0/8 [::1]/128 172.16.0.0/12\n'
            changed = True
        if changed:
            _write_priv(main_cf_path, mc)   # v10.0.5 non-root: /etc/postfix/main.cf is root-owned
            subprocess.run(_sudo_wrap(['systemctl', 'restart', 'postfix']), stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True, timeout=90)

    # Allow Docker networks to reach host port 25 (Authentik worker → Postfix).
    # v10.0.5: pick the backend via _fw_backend() — the broker shims BOTH ufw and
    # firewall-cmd onto PATH, so `which` is poisoned and mis-detects on RHEL.
    _be25 = _fw_backend()
    if _be25 == 'ufw':
        subprocess.run(_sudo_wrap(['ufw', 'allow', 'from', '172.16.0.0/12', 'to', 'any', 'port', '25']), capture_output=True)
        subprocess.run(_sudo_wrap(['ufw', 'reload']), capture_output=True)
        _log("  UFW: allowed Docker networks → port 25")
    elif _be25 == 'firewalld':
        subprocess.run(
            _sudo_wrap(['firewall-cmd', '--permanent', '--add-rich-rule=rule family="ipv4" source address="172.16.0.0/12" port port="25" protocol="tcp" accept']), capture_output=True)
        subprocess.run(_sudo_wrap(['firewall-cmd', '--reload']), capture_output=True)
        _log("  firewalld: allowed Docker networks → port 25")

    # Recreate ONLY server + worker (they read the SMTP env). Recreating the whole
    # stack with --force-recreate races the LDAP outpost — which was just recreated
    # with its injected token in Step 11 — producing an 'authentik-ldap-1 name
    # already in use' conflict that aborts the compose op mid-recreate, leaving
    # server/postgres/redis down + orphan containers (Authentik DOWN after a
    # "successful" deploy → broken LDAP flow → 8446 WebTAK). --no-deps leaves
    # postgres/redis/ldap untouched. --remove-orphans cleans any prior orphan.
    # Pre-flight (v10.0.9): if the LDAP outpost is mid-recreate (Email Relay deployed
    # right after/during an Authentik deploy), wait for it to settle before any compose
    # op — bounded so a genuinely-down outpost cannot hang the deploy.
    for _i in range(18):  # up to ~90s
        if not _authentik_ldap_recreate_in_flight():
            break
        if _i == 0:
            _log("  Authentik LDAP outpost is mid-recreate — waiting for it to settle...")
        time.sleep(5)
    _log("  Recreating Authentik server + worker for SMTP (ldap/db/redis untouched)...")
    with _authentik_compose_lock('smtp-recreate', plog=_log) as _locked:  # v10.1.55 W3
        if not _locked:
            _log("  ⚠ SMTP recreate SKIPPED — another healer holds the Authentik compose lock")
            return False
        r = subprocess.run(
            _sudo_wrap(['docker', 'compose', 'up', '-d', '--force-recreate', '--no-deps', '--remove-orphans', 'server', 'worker']), cwd=ak_dir, capture_output=True, text=True, timeout=120)
    if r.returncode != 0:
        _err = r.stderr or r.stdout or ''
        if 'already in use' in _err:
            # The race still fired: compose aborted mid-recreate. Recover automatically
            # instead of leaving Authentik down for a manual rm -f + up -d.
            _log("  ⚠ Compose name conflict detected — running automatic recovery...")
            _authentik_recover_compose_conflict(ak_dir, _err, _log)
        else:
            raise RuntimeError(f'Authentik restart failed: {_err}')

    ak_token = ''
    if os.path.exists(env_path):
        with open(env_path) as f:
            for line in f:
                if line.strip().startswith('AUTHENTIK_BOOTSTRAP_TOKEN='):
                    ak_token = line.strip().split('=', 1)[1].strip()
                    break

    message = 'Authentik SMTP configured (host.docker.internal:25).'
    if ak_token:
        ak_url = 'http://127.0.0.1:9090'
        ak_headers = {'Authorization': f'Bearer {ak_token}', 'Content-Type': 'application/json'}
        _log("  Waiting for Authentik API...")
        api_ready = _wait_for_authentik_api(ak_url, ak_headers, max_attempts=120, plog=_log)
        if api_ready:
            _log("  Setting up recovery flow...")
            ok, recovery_msg, recovery_slug = _ensure_authentik_recovery_flow(ak_url, ak_headers)
            if ok:
                message += ' ' + recovery_msg
                if recovery_slug:
                    settings = load_settings()
                    base = _get_authentik_base_url(settings)
                    message += f' Direct recovery URL: {base}/if/flow/{recovery_slug}/.'
            else:
                message += f' Recovery flow issue: {recovery_msg}.'
        else:
            message += ' API not ready in time — recovery flow not set up.'
    # Full-stack `docker compose up -d --force-recreate` reapplies blueprints/worker state; LDAP bind flows
    # can break afterward (ak-stage-flow-error on simple binds). Re-apply our API flow fix + LDAP outpost recreate.
    if ak_token:
        try:
            _log("  Re-healing LDAP authentication flow after Authentik SMTP/recovery restart...")
            ok_heal, err_heal = _ensure_ldap_flow_authentication_none()
            if ok_heal:
                _log("  ✓ LDAP flow re-healed (ldap-authentication-flow + outpost)")
            else:
                _log(f"  ⚠ LDAP flow re-heal: {err_heal}")
        except Exception as _heal_ex:
            _log(f"  ⚠ LDAP flow re-heal skipped: {str(_heal_ex)[:100]}")
    return message


def _wait_for_authentik_api(ak_url, ak_headers, max_attempts=90, plog=None, require_200=False):
    """Poll until Authentik API responds. Returns True when ready. If require_200=True, only returns True on 200 (token valid)."""
    import urllib.request as _req
    import urllib.error
    _log = plog or (lambda msg: None)
    for attempt in range(max_attempts):
        try:
            req = _req.Request(f'{ak_url}/api/v3/core/users/', headers=ak_headers)
            _req.urlopen(req, timeout=5)
            return True
        except urllib.error.HTTPError as e:
            if not require_200 and e.code in (401, 403):
                return True
            if e.code == 503 or (require_200 and e.code == 403):
                pass
        except Exception:
            pass
        if attempt > 0 and attempt % 6 == 0:
            _log(f"  ⏳ Still waiting for API... ({attempt * 5}s)")
        time.sleep(5)
    return False


def _ak_api_call(url, data=None, method='GET', headers=None, max_retries=3, timeout=15):
    """Authentik API call with automatic retry on 502/503/timeout."""
    import urllib.request as _req
    import urllib.error
    last_exc = None
    for attempt in range(max_retries):
        try:
            req = _req.Request(url, data=data, method=method, headers=headers or {})
            return _req.urlopen(req, timeout=timeout)
        except urllib.error.HTTPError as e:
            if e.code in (502, 503) and attempt < max_retries - 1:
                time.sleep(5 * (attempt + 1))
                last_exc = e
                continue
            raise
        except (urllib.error.URLError, OSError) as e:
            if attempt < max_retries - 1:
                time.sleep(5 * (attempt + 1))
                last_exc = e
                continue
            raise
    if last_exc:
        raise last_exc


# v10.1.28: "Show password" on the recovery (reset) prompt. authentik's PromptStage has no
# allow_show_password (that setting exists only on PasswordStage, which is why the LOGIN page
# already has an eyeball) — upstream goauthentik/authentik#12550. These two pieces reproduce it
# with supported config only: a `static` prompt field emitting the checkbox, and brand CSS that
# unmasks siblings when it is checked. Marker string _AK_SHOWPW_MARKER makes the CSS idempotent.
_AK_SHOWPW_MARKER = 'infra-TAK-showpw'
# The checkbox flips the inputs' type via an inline onchange handler. Field-verified on
# ops1: authentik serves flow pages with NO Content-Security-Policy header, so an inline
# handler runs (a <script> tag would NOT — this HTML lands via innerHTML, which never
# executes script elements). Walking shadowRoot too, because the CSS-only version below
# could not reach the inputs. Toggling `type` also works in Firefox, which the CSS
# fallback cannot (no -webkit-text-security there). data-pw marks what we flipped so
# unchecking restores only those inputs.
_AK_SHOWPW_FIELD_HTML = (
    '<label style="display:flex;gap:8px;align-items:center;font-size:13px;'
    'cursor:pointer;margin:-8px 0 4px">'
    '<input type="checkbox" id="showpw" style="cursor:pointer" onchange="'
    "var c=this.checked;var f=function(r){r.querySelectorAll('input').forEach("
    "function(i){if(c){if(i.type==='password'){i.type='text';i.setAttribute('data-pw','1')}}"
    "else{if(i.getAttribute('data-pw')){i.type='password'}}});"
    "r.querySelectorAll('*').forEach(function(e){if(e.shadowRoot){f(e.shadowRoot)}})};f(document)"
    '"> Show password</label>'
)
_AK_SHOWPW_CSS = (
    '/* ' + _AK_SHOWPW_MARKER + ': reveal toggle for the password reset prompt.\n'
    '   PromptStage has no allow_show_password (upstream #12550), so the checkbox in the\n'
    '   static prompt field drives this rule. Firefox lacks -webkit-text-security, so the\n'
    '   fields stay masked there — degrades quietly, never errors. */\n'
    'form:has(#showpw:checked) input[type="password"],\n'
    'div:has(#showpw:checked) input[type="password"] {\n'
    '    -webkit-text-security: none !important;\n'
    '}\n'
)


def _ensure_authentik_showpw_css(ak_url, ak_headers):
    """Append the show-password CSS to every Authentik brand, idempotently.

    Keyed on _AK_SHOWPW_MARKER rather than an exact-string compare so an operator's own
    custom CSS in the same field is preserved instead of being overwritten.
    Returns the number of brands changed.
    """
    import urllib.request as _ur
    changed = 0
    req = _ur.Request(f'{ak_url}/api/v3/core/brands/', headers=ak_headers)
    brands = json.loads(_ur.urlopen(req, timeout=15).read().decode()).get('results', [])
    for b in brands:
        cur = (b.get('branding_custom_css') or '')
        if _AK_SHOWPW_MARKER in cur:
            continue
        new_css = (cur.rstrip() + '\n\n' + _AK_SHOWPW_CSS) if cur.strip() else _AK_SHOWPW_CSS
        pr = _ur.Request(
            f'{ak_url}/api/v3/core/brands/{b["brand_uuid"]}/',
            data=json.dumps({'branding_custom_css': new_css}).encode(),
            headers=ak_headers, method='PATCH')
        _ur.urlopen(pr, timeout=15)
        changed += 1
    return changed


def _ensure_authentik_recovery_flow(ak_url, ak_headers):
    """Create recovery flow + stages + bindings and link to default authentication flow.
    Identification -> Email -> Prompt (new pw) -> User Write -> Session Logout.
    Deliberately diverges from the stock Authentik blueprint, which ends in User Login:
    the reset ALWAYS ends signed out so the pre-reset OAuth state is never redeemed
    (see the v10.1.28 note below on the click-tracker / SameSite=Lax callback 400).
    Fetches ALL bindings and filters client-side (the flow__pk server filter is unreliable).
    Returns (success: bool, message: str, recovery_slug: str|None)."""
    import urllib.request as _req
    import urllib.error
    def _err(e):
        try:
            body = e.read().decode()[:300]
        except Exception:
            body = ''
        return f'HTTP {e.code}: {body}' if body else f'HTTP {e.code}'
    def _api_get(path):
        r = _req.Request(f'{ak_url}/api/v3/{path}', headers=ak_headers)
        resp = _req.urlopen(r, timeout=15)
        return json.loads(resp.read().decode())
    def _api_post(path, body):
        r = _req.Request(f'{ak_url}/api/v3/{path}', data=json.dumps(body).encode(), headers=ak_headers, method='POST')
        resp = _req.urlopen(r, timeout=15)
        return json.loads(resp.read().decode())
    def _api_patch(path, body):
        r = _req.Request(f'{ak_url}/api/v3/{path}', data=json.dumps(body).encode(), headers=ak_headers, method='PATCH')
        resp = _req.urlopen(r, timeout=15)
        return json.loads(resp.read().decode())
    def _api_delete(path):
        r = _req.Request(f'{ak_url}/api/v3/{path}', headers=ak_headers, method='DELETE')
        _req.urlopen(r, timeout=15)
    def _find_stage(api_path, name):
        results = _api_get(f'{api_path}?search={_req.quote(name)}').get('results', [])
        for s in results:
            if s.get('name') == name:
                return s['pk']
        return None
    def _find_or_create_stage(api_path, name, extra_attrs=None):
        pk = _find_stage(api_path, name)
        if pk:
            return pk
        body = {'name': name}
        if extra_attrs:
            body.update(extra_attrs)
        try:
            return _api_post(api_path, body)['pk']
        except urllib.error.HTTPError as e:
            if e.code == 400:
                pk = _find_stage(api_path, name)
                if pk:
                    return pk
            raise
    try:
        recovery_flow_slug = 'default-password-recovery'

        # 1) Get or create recovery flow
        recovery_flows = _api_get('flows/instances/?designation=recovery').get('results', [])
        recovery_flow_pk = None
        for f in recovery_flows:
            if f.get('slug') == recovery_flow_slug:
                recovery_flow_pk = f['pk']
                break
        if not recovery_flow_pk and recovery_flows:
            recovery_flow_pk = recovery_flows[0]['pk']
            recovery_flow_slug = recovery_flows[0].get('slug', recovery_flow_slug)
        if not recovery_flow_pk:
            data = _api_post('flows/instances/', {
                'name': 'Password Recovery', 'slug': recovery_flow_slug,
                'designation': 'recovery', 'title': 'Reset your password',
                'authentication': 'none'})
            recovery_flow_pk = data['pk']
        else:
            try:
                _api_patch(f'flows/instances/{recovery_flow_slug}/', {'authentication': 'none'})
            except Exception:
                pass

        # 2) Create all required stages

        # v10.1.28: the recovery flow gets its OWN identification stage. Reusing the login
        # page's default-authentication-identification put a "Forgot username or password?"
        # link on the reset page itself — that stage carries recovery_flow, and the link is a
        # dead-end loop for someone who is already resetting. Editing the shared stage instead
        # would strip the link off the real login page, where it belongs.
        id_stage_pk = _find_or_create_stage('stages/identification/', 'Recovery Identification', {
            'user_fields': ['email', 'username'],
            'case_insensitive_matching': True,
            'pretend_user_exists': True,
            'show_matched_user': True})
        if id_stage_pk:
            # Assert the links are off even when the stage already existed. user_fields is
            # resent because this serializer cross-validates the whole object on PATCH.
            try:
                _api_patch(f'stages/identification/{id_stage_pk}/', {
                    'user_fields': ['email', 'username'],
                    'recovery_flow': None, 'enrollment_flow': None, 'passwordless_flow': None})
            except Exception:
                pass
        if not id_stage_pk:
            id_stage_pk = _find_stage('stages/identification/', 'default-authentication-identification')
        if not id_stage_pk:
            all_id_stages = _api_get('stages/identification/').get('results', [])
            if all_id_stages:
                id_stage_pk = all_id_stages[0]['pk']

        email_stage_pk = _find_or_create_stage('stages/email/', 'Recovery Email', {
            'use_global_settings': True,
            'template': 'email/password_reset.html',
            'activate_user_on_success': True,
            'token_expiry': 'minutes=30',
            'subject': 'Password Reset'})
        if email_stage_pk:
            try:
                _api_patch(f'stages/email/{email_stage_pk}/', {
                    'use_global_settings': True,
                    'template': 'email/password_reset.html',
                    'activate_user_on_success': True})
            except Exception:
                pass

        def _find_or_create_prompt(name, field_key, label, order,
                                   ftype='password', required=True, placeholder=None,
                                   initial_value=None):
            results = _api_get(f'stages/prompt/prompts/?search={_req.quote(name)}').get('results', [])
            for p in results:
                if p.get('name') == name:
                    return p['pk']
            body = {
                'name': name, 'field_key': field_key, 'label': label,
                'type': ftype, 'required': required,
                'placeholder': label if placeholder is None else placeholder,
                'order': order, 'placeholder_expression': False}
            if initial_value is not None:
                # A `static` field renders its INITIAL VALUE, not its placeholder
                # (placeholder is placeholder text / choice list) — per
                # https://docs.goauthentik.io/add-secure-apps/flows-stages/stages/prompt/
                body['initial_value'] = initial_value
                body['initial_value_expression'] = False
            try:
                return _api_post('stages/prompt/prompts/', body)['pk']
            except urllib.error.HTTPError as e:
                if e.code == 400:
                    results = _api_get(f'stages/prompt/prompts/?search={_req.quote(name)}').get('results', [])
                    for p in results:
                        if p.get('name') == name:
                            return p['pk']
                raise

        pw_field_pk = _find_or_create_prompt('recovery-field-password', 'password', 'Password', 0)
        pw_repeat_field_pk = _find_or_create_prompt('recovery-field-password-repeat', 'password_repeat', 'Password (repeat)', 1)
        # v10.1.28: the reset page had no way to see what you were typing, while the LOGIN
        # page does (PasswordStage.allow_show_password=True). PromptStage has no such
        # setting — upstream goauthentik/authentik#12550 is open with no PR — so the toggle
        # is built from parts authentik already supports: a `static` prompt field carrying a
        # checkbox, plus brand CSS that unmasks the password inputs when it is checked.
        # No JS (authentik's CSP blocks inline handlers) and no patched container, so it
        # survives Authentik upgrades. Chrome/Safari/Edge only: -webkit-text-security is
        # unsupported in Firefox, where the fields simply stay masked (no error, no toggle).
        showpw_field_pk = _find_or_create_prompt(
            'recovery-field-show-password', 'showpw_toggle', 'Show password', 50,
            ftype='static', required=False, placeholder='',
            initial_value=_AK_SHOWPW_FIELD_HTML)
        if showpw_field_pk:
            # Self-heal: boxes that got the first cut of this (markup in `placeholder`,
            # which a static field ignores — it renders nothing at all) are repaired here,
            # since _find_or_create_prompt returns an existing prompt untouched.
            try:
                _api_patch(f'stages/prompt/prompts/{showpw_field_pk}/', {
                    'initial_value': _AK_SHOWPW_FIELD_HTML,
                    'initial_value_expression': False})
            except Exception:
                pass
        _recovery_fields = [pw_field_pk, pw_repeat_field_pk]
        if showpw_field_pk:
            _recovery_fields.append(showpw_field_pk)

        prompt_stage_pk = _find_stage('stages/prompt/stages/', 'Recovery Password Change')
        if not prompt_stage_pk:
            try:
                prompt_stage_pk = _api_post('stages/prompt/stages/', {
                    'name': 'Recovery Password Change',
                    'fields': _recovery_fields})['pk']
            except urllib.error.HTTPError as e:
                if e.code == 400:
                    prompt_stage_pk = _find_stage('stages/prompt/stages/', 'Recovery Password Change')
                if not prompt_stage_pk:
                    raise
        else:
            try:
                _api_patch(f'stages/prompt/stages/{prompt_stage_pk}/', {
                    'fields': _recovery_fields})
            except Exception:
                pass

        # The checkbox is inert without the CSS that acts on it — apply both or neither.
        try:
            _ensure_authentik_showpw_css(ak_url, ak_headers)
        except Exception:
            pass

        user_write_pk = _find_or_create_stage('stages/user_write/', 'Recovery User Write',
            {'user_creation_mode': 'never_create'})

        # v10.1.28: the recovery flow ALWAYS ends signed OUT, on every box — hardened or
        # not. user_login_pk stays None so step 4 below DELETES any existing User Login
        # binding, and a user_logout stage is bound LAST (order 110) instead.
        #
        # Why (field-confirmed on nuc 2026-08-09): a trailing User Login makes Authentik
        # resume the pending authorization and bounce the browser to the outpost callback
        # carrying the state minted BEFORE the reset. Every mail provider rewrites the
        # reset link through a click tracker (Brevo -> sendibt2.com), so that callback is
        # reached via a CROSS-SITE redirect chain and Chrome withholds the outpost's
        # SameSite=Lax session cookie. The outpost then logs "mismatched session ID" with
        # should="" and returns a bare 400. Ending signed out means the stale state is
        # never redeemed, so the 400 cannot occur — which is exactly why W1-hardened
        # boxes (test12/test8, WS3c) never reproduced it while nuc/ops1 did.
        #
        # This also closes the WS3c privilege-handoff hazard (test8 2026-07-18) on
        # non-hardened boxes: finishing someone else's reset can no longer leave the
        # browser sitting inside whatever session it already held.
        #
        # Trade-off, deliberate: after a reset the user signs in with the new password.
        # Field-proven — it is what test12/test8 have done since v10.1.4.
        user_login_pk = None
        logout_stage_pk = _find_or_create_stage('stages/user_logout/', 'Recovery Session Logout')

        # 3) Fetch ALL bindings, filter client-side by target == recovery flow PK.
        #    The server-side flow__pk filter is unreliable and returns bindings from other flows.
        all_bindings = []
        page = 1
        while True:
            data = _api_get(f'flows/bindings/?ordering=order&page_size=500&page={page}')
            all_bindings.extend(data.get('results', []))
            if not data.get('pagination', {}).get('next'):
                break
            page += 1

        recovery_bindings = [b for b in all_bindings if str(b.get('target')) == str(recovery_flow_pk)]

        desired_stage_pks = set()
        for pk in [id_stage_pk, email_stage_pk, prompt_stage_pk, user_write_pk, user_login_pk,
                   logout_stage_pk]:
            if pk:
                desired_stage_pks.add(str(pk))

        # 4) Delete any binding on the recovery flow whose stage is NOT one of our 5 desired stages
        for b in recovery_bindings:
            if str(b.get('stage', '')) not in desired_stage_pks:
                try:
                    _api_delete(f'flows/bindings/{b["pk"]}/')
                except Exception:
                    pass

        # 5) Create missing bindings
        already_bound = {str(b.get('stage')) for b in recovery_bindings}
        desired_bindings = [
            (10, id_stage_pk),
            (20, email_stage_pk),
            (30, prompt_stage_pk),
            (40, user_write_pk),
            (100, user_login_pk),
            (110, logout_stage_pk),
        ]
        for order, stage_pk in desired_bindings:
            if not stage_pk or str(stage_pk) in already_bound:
                continue
            try:
                _api_post('flows/bindings/', {
                    'target': recovery_flow_pk, 'stage': stage_pk, 'order': order,
                    'evaluate_on_plan': True, 're_evaluate_policies': order <= 20,
                    'policy_engine_mode': 'any', 'invalid_response_action': 'retry'})
            except urllib.error.HTTPError as e:
                if e.code == 400:
                    pass
                else:
                    raise

        # 6) Link recovery flow to the default-authentication-identification stage
        auth_id_stage_pk = _find_stage('stages/identification/', 'default-authentication-identification')
        if not auth_id_stage_pk:
            all_id = _api_get('stages/identification/').get('results', [])
            for s in all_id:
                if 'default' in s.get('name', '').lower() and 'authentication' in s.get('name', '').lower():
                    auth_id_stage_pk = s['pk']
                    break
        if auth_id_stage_pk:
            try:
                stage_data = _api_get(f'stages/identification/{auth_id_stage_pk}/')
                current_rf = stage_data.get('recovery_flow')
                current_pk = (current_rf if isinstance(current_rf, str) else
                              (current_rf.get('pk') if isinstance(current_rf, dict) and current_rf else None))
                if current_pk != recovery_flow_pk:
                    patch_body = {'recovery_flow': recovery_flow_pk}
                    uf = stage_data.get('user_fields')
                    if uf:
                        patch_body['user_fields'] = uf
                    try:
                        _api_patch(f'stages/identification/{auth_id_stage_pk}/', patch_body)
                    except urllib.error.HTTPError:
                        put_body = {k: v for k, v in stage_data.items()
                                    if k not in ('pk', 'component', 'verbose_name', 'verbose_name_plural', 'meta_model_name', 'flow_set')}
                        put_body['recovery_flow'] = recovery_flow_pk
                        r = _req.Request(f'{ak_url}/api/v3/stages/identification/{auth_id_stage_pk}/',
                            data=json.dumps(put_body).encode(), headers=ak_headers, method='PUT')
                        _req.urlopen(r, timeout=15)
            except urllib.error.HTTPError:
                pass
        return True, 'Recovery flow created and linked; "Forgot password?" is on the login page.', recovery_flow_slug
    except urllib.error.HTTPError as e:
        return False, _err(e), None
    except Exception as e:
        return False, str(e)[:200], None


