# (registry-resident since v10.1.24).


# ── Docker log limits (prevents Node-RED / Authentik LDAP etc. from filling disk) ──
def _ensure_docker_log_limits_remote(remote_cfg, log_fn=None):
    """On remote host: ensure /etc/docker/daemon.json has log-opts (max-size 50m, max-file 3). Restart Docker if changed.
    Returns (ok: bool, docker_restarted: bool). Non-fatal: on failure we log and return (False, False)."""
    if not remote_cfg or not (remote_cfg.get('host') or '').strip():
        return True, False
    script_content = '''import json, os, subprocess, sys
p = "/etc/docker/daemon.json"
data = {}
if os.path.isfile(p) and os.path.getsize(p) > 0:
    try:
        with open(p) as f:
            data = json.load(f)
    except Exception:
        pass
opts = data.get("log-opts") or {}
if opts.get("max-size") == "50m" and opts.get("max-file") == "3":
    print("OK_ALREADY")
    sys.exit(0)
data["log-driver"] = data.get("log-driver", "json-file")
data["log-opts"] = {"max-size": "50m", "max-file": "3"}
os.makedirs("/etc/docker", exist_ok=True)
with open(p, "w") as f:
    json.dump(data, f, indent=2)
    f.write("\\n")
subprocess.run(["systemctl", "restart", "docker"], timeout=90, capture_output=True)
print("OK_RESTARTED")
'''
    tmp_path = '/tmp/infra_tak_docker_log_limits.py'
    try:
        with open(tmp_path, 'w') as f:
            f.write(script_content)
        copy_ok, _cm = _module_copy({'target_mode': 'remote', 'remote': remote_cfg}, tmp_path, tmp_path, timeout=15)
        if not copy_ok:
            if log_fn:
                log_fn("  ⚠ Could not copy Docker log-limits script to remote")
            return False, False
        ok, out = _ssh_probe(remote_cfg, f'python3 {tmp_path} 2>&1; rm -f {tmp_path}', timeout=45)
    except Exception as e:
        if log_fn:
            log_fn(f"  ⚠ Docker log limits on remote: {str(e)[:100]}")
        return False, False
    finally:
        try:
            os.remove(tmp_path)
        except Exception:
            pass
    out = (out or '').strip()
    if not ok:
        if log_fn:
            log_fn(f"  ⚠ Docker log limits on remote could not be applied: {(out or '')[:120]}")
        return False, False
    if 'OK_RESTARTED' in out:
        if log_fn:
            log_fn("✓ Docker log limits set on remote (50 MB × 3). Docker was restarted.")
        return True, True
    if log_fn and 'OK_ALREADY' in out:
        log_fn("✓ Docker log limits already set on remote.")
    return True, False


def _update_boot_stagger_service():
    """Create/update a systemd service that staggers Docker container startup on boot.
    Called after any module deploy or uninstall so it always reflects current state.
    Startup order: Authentik DB -> Authentik -> TAK Portal -> CloudTAK."""
    try:
        # v10.1.59: TAK Portal is a compose PROJECT (web + worker + Postgres ...). Stop and
        # start every container it has, and start it with `docker compose up -d` in the
        # project dir so services come up in dependency order — `docker start tak-portal`
        # started the web container alone and left a worker/Postgres to chance.
        _tp_dir = _takportal_dir()
        try:
            _tp_names = [c['name'] for c in _takportal_project_containers(all_states=True)] or ['tak-portal']
        except Exception:
            _tp_names = ['tak-portal']
        _tp_compose = (os.path.exists(os.path.join(_tp_dir, 'docker-compose.yml'))
                       and "'" not in _tp_dir and ' ' not in _tp_dir)
        BOOT_ORDER = [
            ('Authentik DB', ['authentik-postgresql-1'], 5),
            ('Authentik', ['authentik-server-1', 'authentik-worker-1'], 10),
            ('Authentik LDAP', ['authentik-ldap-1'], 5),
            ('TAK Portal', _tp_names, 5),
            ('CloudTAK DB', ['cloudtak-postgis-1'], 5),
            ('CloudTAK', ['cloudtak-api-1', 'cloudtak-tiles-1', 'cloudtak-events-1', 'cloudtak-store-1', 'cloudtak-media-1'], 0),
        ]
        existing = set()
        r = subprocess.run(_sudo_wrap(['docker', 'ps', '-a', '--format', '{{.Names}}']), capture_output=True, text=True, timeout=10)
        if r.returncode == 0:
            existing = {name.strip() for name in r.stdout.strip().split('\n') if name.strip()}
        steps = []
        for label, containers, sleep_after in BOOT_ORDER:
            present = [c for c in containers if c in existing]
            if present:
                if label == 'TAK Portal' and _tp_compose:
                    steps.append(f'echo "Starting {label}..." && ((cd {_tp_dir} && docker compose up -d) || docker start {" ".join(present)})')
                else:
                    steps.append(f'echo "Starting {label}..." && docker start {" ".join(present)}')
                if sleep_after > 0:
                    steps.append(f'sleep {sleep_after}')
        if not steps:
            svc = '/etc/systemd/system/docker-stagger.service'
            if os.path.exists(svc):
                _run_priv_chain([['systemctl', 'disable', 'docker-stagger'], ['rm', '-f', '/etc/systemd/system/docker-stagger.service'], ['systemctl', 'daemon-reload']], 'seq', timeout=10)
            return
        all_containers = []
        for _, containers, _ in BOOT_ORDER:
            all_containers.extend(c for c in containers if c in existing)
        stop_cmd = f'docker stop {" ".join(all_containers)} 2>/dev/null; true'
        steps.append('echo "All containers started"')
        exec_cmd = ' && \\\n  '.join(steps)
        unit = (
            '[Unit]\n'
            'Description=Stagger Docker container startup on boot\n'
            'After=docker.service\n'
            'Requires=docker.service\n\n'
            '[Service]\n'
            'Type=oneshot\n'
            'RemainAfterExit=yes\n'
            f"ExecStart=/bin/bash -c '\\\n  {stop_cmd} && \\\n  {exec_cmd}'\n\n"
            '[Install]\n'
            'WantedBy=multi-user.target\n'
        )
        _write_priv('/etc/systemd/system/docker-stagger.service', unit)
        _run_priv_chain([['systemctl', 'daemon-reload'], ['systemctl', 'enable', 'docker-stagger']], 'and', timeout=10)
    except Exception:
        pass


def _ensure_docker_log_limits(log_fn=None):
    """Ensure /etc/docker/daemon.json has log-opts (max-size 50m, max-file 3). If we write or change it, restart Docker.
    Returns (docker_restarted: bool, error: str or None)."""
    daemon_json = '/etc/docker/daemon.json'
    if not os.path.isdir('/etc/docker'):
        return False, 'Docker not installed'
    try:
        data = {}
        if os.path.isfile(daemon_json) and os.path.getsize(daemon_json) > 0:
            with open(daemon_json) as f:
                data = json.load(f)
        opts = data.get('log-opts') or {}
        if opts.get('max-size') == '50m' and opts.get('max-file') == '3':
            if log_fn:
                log_fn("✓ Docker log limits already set.")
            return False, None
        data['log-driver'] = 'json-file'
        data['log-opts'] = {'max-size': '50m', 'max-file': '3'}
        _makedirs_priv('/etc/docker', exist_ok=True)
        _write_priv(daemon_json, json.dumps(data, indent=2) + '\n')
        subprocess.run(_sudo_wrap(['systemctl', 'restart', 'docker']), capture_output=True, timeout=90)
        time.sleep(5)
        if log_fn:
            log_fn("✓ Docker log limits set (50 MB × 3 per container). Docker was restarted; other containers may need starting from their pages.")
        return True, None
    except Exception as e:
        err = str(e)
        if log_fn:
            log_fn(f"✗ Failed to set Docker log limits: {err}")
        return False, err


