nodered_deploy_log = []
nodered_deploy_status = {'running': False, 'complete': False, 'error': False, 'cancelled': False}

@app.route('/api/nodered/deploy', methods=['POST'])
@login_required
def nodered_deploy_api():
    if nodered_deploy_status.get('running'):
        return jsonify({'error': 'Deployment already in progress'}), 409
    data = request.get_json() or {}
    if data.get('config'):
        settings = load_settings()
        cfg = _normalize_module_deployment_config(data['config'])
        settings['nodered_deployment'] = cfg
        save_settings(settings)
    nodered_deploy_log.clear()
    nodered_deploy_status.update({'running': True, 'complete': False, 'error': False, 'cancelled': False})
    threading.Thread(target=run_nodered_deploy, daemon=True).start()
    return jsonify({'success': True})

@app.route('/api/nodered/deploy/cancel', methods=['POST'])
@login_required
def nodered_deploy_cancel():
    nodered_deploy_status['cancelled'] = True
    return jsonify({'success': True})

@app.route('/api/nodered/deploy/log')
@login_required
def nodered_deploy_log_api():
    idx = request.args.get('index', 0, type=int)
    return jsonify({'entries': nodered_deploy_log[idx:], 'total': len(nodered_deploy_log),
        'running': nodered_deploy_status['running'], 'complete': nodered_deploy_status['complete'],
        'error': nodered_deploy_status['error'], 'cancelled': nodered_deploy_status.get('cancelled', False)})

@app.route('/api/nodered/control', methods=['POST'])
@login_required
def nodered_control():
    action = (request.json or {}).get('action', '')
    nr_dir = os.path.expanduser('~/node-red')
    compose = os.path.join(nr_dir, 'docker-compose.yml')
    if not os.path.exists(compose):
        return jsonify({'error': 'Node-RED not deployed here'}), 400
    if action == 'start':
        # No `-f`: compose discovers its files in nr_dir, so an operator's
        # docker-compose.override.yml (e.g. an extra published port) is applied.
        # `-f docker-compose.yml` recreated the container without it (gh #246).
        subprocess.run(_sudo_wrap(['docker', 'compose', 'up', '-d']), stdout=subprocess.PIPE, stderr=subprocess.STDOUT, timeout=60, cwd=nr_dir)
    elif action == 'stop':
        subprocess.run(_sudo_wrap(['docker', 'compose', '-f', compose, 'stop']), stdout=subprocess.PIPE, stderr=subprocess.STDOUT, timeout=60, cwd=nr_dir)
    elif action == 'restart':
        subprocess.run(_sudo_wrap(['docker', 'compose', '-f', compose, 'restart']), stdout=subprocess.PIPE, stderr=subprocess.STDOUT, timeout=60, cwd=nr_dir)
    else:
        return jsonify({'error': 'Invalid action'}), 400
    time.sleep(2)
    r = subprocess.run(_sudo_wrap(['docker', 'ps', '--filter', 'name=nodered', '--format', '{{.Status}}']), capture_output=True, text=True)
    running = r.stdout and 'Up' in r.stdout
    return jsonify({'success': True, 'running': running})

@app.route('/api/nodered/logs')
@login_required
def nodered_logs():
    lines = request.args.get('lines', 80, type=int)
    nr_dir = os.path.expanduser('~/node-red')
    compose = os.path.join(nr_dir, 'docker-compose.yml')
    if not os.path.exists(compose):
        return jsonify({'entries': []})
    r = subprocess.run(_sudo_wrap(['docker', 'compose', '-f', compose, 'logs', f'--tail={lines}']), stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True, timeout=15, cwd=nr_dir)
    entries = [l for l in (r.stdout.strip().split('\n') if r.stdout else []) if l.strip()]
    return jsonify({'entries': entries})


@app.route('/api/nodered/remote-metrics')
@login_required
def nodered_remote_metrics():
    """Return CPU/memory/disk/uptime for the remote host when Node-RED is deployed remotely."""
    settings = load_settings()
    deploy_cfg = _get_module_deployment_config(settings, 'nodered_deployment')
    if deploy_cfg.get('target_mode') != 'remote' or not (deploy_cfg.get('remote', {}).get('host') or '').strip():
        return jsonify({'error': 'Not remote'}), 404
    metrics = _get_remote_host_metrics(deploy_cfg.get('remote', {}))
    if metrics is None:
        return jsonify({'error': 'Could not fetch remote metrics'}), 503
    return jsonify(metrics)


@app.route('/api/nodered/uninstall', methods=['POST'])
@login_required
def nodered_uninstall():
    try:
        data = request.get_json(silent=True) or {}
        password = data.get('password', '')
        auth = load_auth()
        if not auth.get('password_hash') or not check_password_hash(auth['password_hash'], password):
            return jsonify({'error': 'Invalid admin password'}), 403
        settings = load_settings()
        deploy_cfg = _get_module_deployment_config(settings, 'nodered_deployment')
        steps = []
        if deploy_cfg.get('target_mode') == 'remote' and (deploy_cfg.get('remote', {}).get('host') or '').strip():
            remote = deploy_cfg.get('remote', {})
            # 300 s, not 90 — same reason as the local branch below: `down -v` has to
            # stop the container and drop the named volume, and the old budget expired
            # mid-teardown on a real box.
            ok, out = _ssh_probe(remote, 'cd ~/node-red && docker compose down -v 2>&1; rm -rf ~/node-red 2>/dev/null; true', timeout=300)
            if not ok:
                return jsonify({'error': f'Remote uninstall failed: {(out or "unknown error")[:200]}'}), 500
            steps.append('Stopped and removed Node-RED on remote host')
            deploy_cfg['deployed'] = False
            settings['nodered_deployment'] = _normalize_module_deployment_config(deploy_cfg)
            save_settings(settings)
        else:
            nr_dir = os.path.expanduser('~/node-red')
            compose = os.path.join(nr_dir, 'docker-compose.yml')
            if os.path.exists(compose):
                # `down -v` stops the container, removes it and drops the named volume.
                # On a non-root box it routes through the broker, and the old 60 s budget
                # expired mid-teardown — measured on nuc, 2026-09-13. The TimeoutExpired
                # then escaped into this function's outer `except Exception` and the UI
                # reported "Uninstall failed" on an uninstall that HAD removed both the
                # container and the volume, while the rm -rf below never ran. The stale
                # directory it left behind keeps _is_module_deployed() reporting Node-RED
                # as installed, so the console disagreed with the box.
                try:
                    subprocess.run(_sudo_wrap(['docker', 'compose', '-f', compose, 'down', '-v']),
                                   stdout=subprocess.PIPE, stderr=subprocess.STDOUT, timeout=300, cwd=nr_dir)
                except subprocess.TimeoutExpired:
                    steps.append('Teardown ran long — verified actual state instead of assuming failure')
                # Never trust the exit path here: killing the compose CLI does not stop
                # dockerd, so what matters is what is actually gone. Only refuse if the
                # container survived — removing the compose file out from under a live
                # container is what would strand it.
                if _nodered_container_running():
                    return jsonify({'error': 'Node-RED is still running after teardown — nothing was '
                                             'removed. Retry the uninstall; if it persists, the Docker '
                                             'daemon is not responding.'}), 500
            # F2b/F2c (v10.1.72): everything above is gated on the compose file existing. With no
            # compose file the teardown was skipped ENTIRELY, the directory was deleted, and the
            # route still returned {"success": true, "steps": ["Node-RED container and data
            # removed"]} — while the container kept running. Proven on dev-4, 2026-09-14.
            #
            # And the running-only guard above cannot close it: container names are unique across
            # every state, so an EXITED `nodered` container still owns the name and still blocks
            # the next `compose up -d` with a name conflict, while `docker ps` shows nothing.
            # That is how a box ends up in a loop where uninstall claims success and deploy keeps
            # failing — which is exactly the loop a user hit in the field.
            #
            # So: regardless of the compose file, if the name is still taken, remove it by name.
            if _nodered_container_exists():
                _rm = subprocess.run(_sudo_wrap(['docker', 'rm', '-f', 'nodered']),
                                     capture_output=True, text=True, timeout=60)
                if _nodered_container_exists():
                    return jsonify({'error': 'A container named "nodered" could not be removed '
                                             f'({(_rm.stderr or _rm.stdout or "").strip()[-200:]}). '
                                             'Nothing was deleted. Retry; if it persists, the '
                                             'Docker daemon is not responding.'}), 500
                steps.append('Removed a leftover "nodered" container that was holding the name')
            if os.path.exists(nr_dir):
                # List argv, not shell=True: same broker routing via _sudo_wrap (the shim
                # PATH intercepted the bare `rm` before), minus a shell interpolating a
                # path into an `rm -rf`. Not attacker-controlled here, but it is not a
                # construction worth leaving in the tree.
                subprocess.run(_sudo_wrap(['rm', '-rf', nr_dir]), capture_output=True, timeout=30)
            steps.append('Node-RED container and data removed')
            deploy_cfg['deployed'] = False
            settings['nodered_deployment'] = _normalize_module_deployment_config(deploy_cfg)
            save_settings(settings)
        nodered_deploy_log.clear()
        nodered_deploy_status.update({'running': False, 'complete': False, 'error': False})
        if settings.get('fqdn'):
            generate_caddyfile(settings)
            _caddy_reload()
            steps.append('Caddyfile updated')
        _deregister_authentik_proxy_app(settings, 'node-red', 'Node-RED Proxy', plog=lambda m: steps.append(m.strip()))
        return jsonify({'success': True, 'steps': steps})
    except Exception as e:
        return jsonify({'error': f'Uninstall failed: {str(e)[:200]}'}), 500


def _is_module_deployed(settings, module_key):
    """True if the given module is deployed (so we only create its Authentik app when deployed). Keys: nodered, mediamtx, takportal, infratak (infratak always True)."""
    if module_key == 'infratak':
        return True
    if module_key == 'takportal':
        return os.path.exists(os.path.expanduser('~/TAK-Portal/docker-compose.yml'))
    if module_key == 'nodered':
        nr_cfg = _get_module_deployment_config(settings, 'nodered_deployment')
        if nr_cfg.get('target_mode') == 'remote' and nr_cfg.get('deployed') and (nr_cfg.get('remote', {}).get('host') or '').strip():
            return True
        nr_compose = os.path.join(os.path.expanduser('~/node-red'), 'docker-compose.yml')
        if os.path.exists(nr_compose):
            return True
        if os.path.exists(os.path.expanduser('~/node-red')) or os.path.exists('/opt/nodered'):
            return True
        return False
    if module_key == 'mediamtx':
        mtx_cfg = _get_module_deployment_config(settings, 'mediamtx_deployment')
        if mtx_cfg.get('target_mode') == 'remote' and mtx_cfg.get('deployed') and (mtx_cfg.get('remote', {}).get('host') or '').strip():
            return True
        return os.path.exists('/usr/local/bin/mediamtx') and os.path.exists('/usr/local/etc/mediamtx.yml')
    return False


def _ensure_authentik_nodered_app(fqdn, ak_token, plog=None, flow_pk=None, inv_flow_pk=None, settings=None):
    """Create Node-RED proxy provider + application in Authentik, add to embedded outpost.
    When flow_pk/inv_flow_pk are provided (e.g. from Step 12), use them. Otherwise wait for flows.
    When settings is provided, use _get_authentik_api_url(settings) so remote Authentik is supported."""
    if not fqdn or not ak_token:
        return False
    def log(msg):
        if plog:
            plog(msg)
    import urllib.request as _urlreq
    import urllib.error
    _ak_headers = {'Authorization': f'Bearer {ak_token}', 'Content-Type': 'application/json'}
    _ak_url = _get_authentik_api_url(settings) if settings else 'http://127.0.0.1:9090'

    try:
        if not flow_pk or not inv_flow_pk:
            for attempt in range(36):
                try:
                    req = _urlreq.Request(f'{_ak_url}/api/v3/flows/instances/?designation=authorization&ordering=slug', headers=_ak_headers)
                    resp = _urlreq.urlopen(req, timeout=10)
                    flows = json.loads(resp.read().decode())['results']
                    flow_pk = next((f['pk'] for f in flows if 'implicit' in f.get('slug', '')), flows[0]['pk'] if flows else None)
                    if flow_pk:
                        req = _urlreq.Request(f'{_ak_url}/api/v3/flows/instances/?designation=invalidation', headers=_ak_headers)
                        resp = _urlreq.urlopen(req, timeout=10)
                        inv_flows = json.loads(resp.read().decode())['results']
                        inv_flow_pk = next((f['pk'] for f in inv_flows if 'provider' not in f.get('slug', '')), inv_flows[0]['pk'] if inv_flows else None)
                        if inv_flow_pk:
                            break
                except Exception:
                    pass
                if attempt % 6 == 0:
                    log(f"  ⏳ Waiting for authorization flow... ({attempt * 5}s)")
                time.sleep(5)
            if not flow_pk or not inv_flow_pk:
                log("  ⚠ No authorization/invalidation flow — skipping Node-RED proxy provider")
                return False
            log("  ✓ Got authorization and invalidation flows")

        # Create proxy provider (same payload structure as TAK Portal)
        provider_pk = None
        try:
            _nr_host = f'https://{_pub_hostport(_get_service_domain(settings, "nodered") if settings else f"nodered.{fqdn}")}'
            _cookie = f'.{fqdn.split(":")[0]}'
            req = _urlreq.Request(f'{_ak_url}/api/v3/providers/proxy/',
                data=json.dumps({'name': 'Node-RED Proxy', 'authorization_flow': flow_pk,
                    'invalidation_flow': inv_flow_pk,
                    'external_host': _nr_host, 'mode': 'forward_single',
                    'token_validity': 'hours=24', 'cookie_domain': _cookie}).encode(),
                headers=_ak_headers, method='POST')
            resp = _urlreq.urlopen(req, timeout=10)
            provider_pk = json.loads(resp.read().decode())['pk']
            log("  ✓ Proxy provider created")
        except Exception as e:
            if hasattr(e, 'code') and e.code == 400:
                req = _urlreq.Request(f'{_ak_url}/api/v3/providers/proxy/?search=Node-RED', headers=_ak_headers)
                resp = _urlreq.urlopen(req, timeout=10)
                results = json.loads(resp.read().decode())['results']
                if results:
                    provider_pk = results[0]['pk']
                    try:
                        req = _urlreq.Request(f'{_ak_url}/api/v3/providers/proxy/{provider_pk}/',
                            data=json.dumps({'external_host': _nr_host, 'cookie_domain': _cookie}).encode(),
                            headers=_ak_headers, method='PATCH')
                        _urlreq.urlopen(req, timeout=10)
                    except Exception:
                        pass
                log("  ✓ Proxy provider already exists (external_host updated)")
            else:
                log(f"  ⚠ Proxy provider error: {str(e)[:100]}")

        # Create application
        if provider_pk:
            try:
                req = _urlreq.Request(f'{_ak_url}/api/v3/core/applications/',
                    data=json.dumps({'name': 'Node-RED', 'slug': 'node-red',
                        'provider': provider_pk, 'open_in_new_tab': True}).encode(),
                    headers=_ak_headers, method='POST')
                _urlreq.urlopen(req, timeout=10)
                log("  ✓ Application 'Node-RED' created")
            except Exception as e:
                if hasattr(e, 'code') and e.code == 400:
                    try:
                        req = _urlreq.Request(f'{_ak_url}/api/v3/core/applications/node-red/',
                            data=json.dumps({'provider': provider_pk}).encode(),
                            headers=_ak_headers, method='PATCH')
                        _urlreq.urlopen(req, timeout=10)
                    except Exception:
                        pass
                    log("  ✓ Application 'Node-RED' updated")
                else:
                    log(f"  ⚠ Application error: {str(e)[:80]}")

            # 5) Add to embedded outpost
            _outpost_add_providers_safe(_ak_url, _ak_headers, [provider_pk], plog=log)
            # 6) Restrict to authentik Admins — MUST run here, not only in the
            # Authentik deploy/reconfigure paths. Fleet deploy order is
            # Caddy → Authentik → … → Node-RED, so at Authentik-deploy time
            # `_is_module_deployed(settings,'nodered')` is False and the app does
            # not exist yet; the Node-RED deploy then created it with NO policy
            # binding, which in Authentik means "visible to every authenticated
            # user". TAK Portal AGENCY admins (members of
            # `authentik-<ABBR>-AgencyAdmin`, not `authentik Admins`) therefore
            # saw the Node-RED tile — only GLOBAL admins should. Idempotent.
            _ensure_app_access_policies(_ak_url, _ak_headers, plog=log)
        else:
            log("  ⚠ Could not create or find Node-RED proxy provider")
    except Exception as e:
        log(f"  ⚠ Forward auth setup error: {str(e)[:100]}")
    return True

def _ensure_authentik_webodm_app(fqdn, ak_token, plog=None, flow_pk=None, inv_flow_pk=None, settings=None):
    """Create WebODM proxy provider + application in Authentik, add to embedded outpost.
    Same pattern as Node-RED / MediaMTX — Caddy forward_auth protects the route."""
    if not fqdn or not ak_token:
        return False
    def log(msg):
        if plog:
            plog(msg)
    import urllib.request as _urlreq
    import urllib.error
    _ak_headers = {'Authorization': f'Bearer {ak_token}', 'Content-Type': 'application/json'}
    _ak_url = _get_authentik_api_url(settings) if settings else 'http://127.0.0.1:9090'

    try:
        if not flow_pk or not inv_flow_pk:
            for attempt in range(36):
                try:
                    req = _urlreq.Request(f'{_ak_url}/api/v3/flows/instances/?designation=authorization&ordering=slug', headers=_ak_headers)
                    resp = _urlreq.urlopen(req, timeout=10)
                    flows = json.loads(resp.read().decode())['results']
                    flow_pk = next((f['pk'] for f in flows if 'implicit' in f.get('slug', '')), flows[0]['pk'] if flows else None)
                    if flow_pk:
                        req = _urlreq.Request(f'{_ak_url}/api/v3/flows/instances/?designation=invalidation', headers=_ak_headers)
                        resp = _urlreq.urlopen(req, timeout=10)
                        inv_flows = json.loads(resp.read().decode())['results']
                        inv_flow_pk = next((f['pk'] for f in inv_flows if 'provider' not in f.get('slug', '')), inv_flows[0]['pk'] if inv_flows else None)
                        if inv_flow_pk:
                            break
                except Exception:
                    pass
                if attempt % 6 == 0:
                    log(f"  ⏳ Waiting for authorization flow... ({attempt * 5}s)")
                time.sleep(5)
            if not flow_pk or not inv_flow_pk:
                log("  ⚠ No authorization/invalidation flow — skipping WebODM proxy provider")
                return False
            log("  ✓ Got authorization and invalidation flows")

        provider_pk = None
        try:
            _wo_host = f'https://{_pub_hostport(_get_service_domain(settings, "webodm") if settings else f"webodm.{fqdn}")}'
            _cookie = f'.{fqdn.split(":")[0]}'
            req = _urlreq.Request(f'{_ak_url}/api/v3/providers/proxy/',
                data=json.dumps({'name': 'WebODM Proxy', 'authorization_flow': flow_pk,
                    'invalidation_flow': inv_flow_pk,
                    'external_host': _wo_host, 'mode': 'forward_single',
                    'token_validity': 'hours=24', 'cookie_domain': _cookie}).encode(),
                headers=_ak_headers, method='POST')
            resp = _urlreq.urlopen(req, timeout=10)
            provider_pk = json.loads(resp.read().decode())['pk']
            log("  ✓ Proxy provider created")
        except Exception as e:
            if hasattr(e, 'code') and e.code == 400:
                req = _urlreq.Request(f'{_ak_url}/api/v3/providers/proxy/?search=WebODM', headers=_ak_headers)
                resp = _urlreq.urlopen(req, timeout=10)
                results = json.loads(resp.read().decode())['results']
                if results:
                    provider_pk = results[0]['pk']
                    try:
                        req = _urlreq.Request(f'{_ak_url}/api/v3/providers/proxy/{provider_pk}/',
                            data=json.dumps({'external_host': _wo_host, 'cookie_domain': _cookie}).encode(),
                            headers=_ak_headers, method='PATCH')
                        _urlreq.urlopen(req, timeout=10)
                    except Exception:
                        pass
                log("  ✓ Proxy provider already exists (external_host updated)")
            else:
                log(f"  ⚠ Proxy provider error: {str(e)[:100]}")

        if provider_pk:
            try:
                req = _urlreq.Request(f'{_ak_url}/api/v3/core/applications/',
                    data=json.dumps({'name': 'WebODM', 'slug': 'webodm',
                        'provider': provider_pk, 'open_in_new_tab': True}).encode(),
                    headers=_ak_headers, method='POST')
                _urlreq.urlopen(req, timeout=10)
                log("  ✓ Application 'WebODM' created")
            except Exception as e:
                if hasattr(e, 'code') and e.code == 400:
                    try:
                        req = _urlreq.Request(f'{_ak_url}/api/v3/core/applications/webodm/',
                            data=json.dumps({'provider': provider_pk}).encode(),
                            headers=_ak_headers, method='PATCH')
                        _urlreq.urlopen(req, timeout=10)
                    except Exception:
                        pass
                    log("  ✓ Application 'WebODM' updated")
                else:
                    log(f"  ⚠ Application error: {str(e)[:80]}")

            _outpost_add_providers_safe(_ak_url, _ak_headers, [provider_pk], plog=log)
        else:
            log("  ⚠ Could not create or find WebODM proxy provider")
    except Exception as e:
        log(f"  ⚠ Forward auth setup error: {str(e)[:100]}")

    # ── Native OIDC login (GH #50) — WebODM >= 3.2.2 ships first-party OIDC
    # (app/views/oidc.py): an OAuth2 provider here + OIDC_AUTH_PROVIDERS in the
    # mounted local_settings.py turns WebODM's login page into a single
    # "Login with Authentik" button, killing the double login behind
    # forward_auth. The proxy provider above stays in front (defense in depth).
    # WebODM calls the token/userinfo endpoints from inside the webapp
    # container with verify=True, so this needs the public https Authentik URL
    # presenting a cert the container's CA bundle trusts (LE / public custom).
    try:
        ak_public = _get_authentik_base_url(settings) if settings else ''
        if not ak_public.startswith('https://'):
            log('  ⚠ No public https Authentik URL — skipping WebODM OIDC login setup')
            return True
        wo_base = f'https://{_pub_hostport(_get_service_domain(settings, "webodm") if settings else f"webodm.{fqdn}")}'
        redirect_uris_obj = [{'matching_mode': 'strict', 'url': f'{wo_base}/oidc/callback/'}]

        # Signing key + openid/email/profile scope mappings (NetBird pattern —
        # WebODM requests scope "openid email").
        signing_key_pk = None
        try:
            req = _urlreq.Request(f'{_ak_url}/api/v3/crypto/certificatekeypairs/?has_key=true&ordering=name&page_size=50', headers=_ak_headers)
            certs = json.loads(_urlreq.urlopen(req, timeout=15).read().decode()).get('results', [])
            signing_key_pk = next((c['pk'] for c in certs if 'authentik' in (c.get('name') or '').lower() and 'self-signed' in (c.get('name') or '').lower()),
                                  certs[0]['pk'] if certs else None)
        except Exception:
            pass
        scope_mapping_pks = []
        try:
            req = _urlreq.Request(f'{_ak_url}/api/v3/propertymappings/provider/scope/?ordering=scope_name&page_size=50', headers=_ak_headers)
            mappings = json.loads(_urlreq.urlopen(req, timeout=15).read().decode()).get('results', [])
            scope_mapping_pks = [m['pk'] for m in mappings if m.get('scope_name') in ('openid', 'email', 'profile')]
        except Exception:
            pass
        _oidc_extras = {}
        if signing_key_pk:
            _oidc_extras['signing_key'] = signing_key_pk
        if scope_mapping_pks:
            _oidc_extras['property_mappings'] = scope_mapping_pks

        _oidc_name = 'WebODM OIDC'
        oidc_pk, client_id, client_secret = None, '', ''
        # Reuse an existing provider (keeps client_id/secret stable across
        # deploys/repairs); heal redirect_uris + grant_types on it. A provider
        # missing its secret is useless — delete and recreate.
        try:
            req = _urlreq.Request(f'{_ak_url}/api/v3/providers/oauth2/?search=WebODM', headers=_ak_headers)
            for ex in json.loads(_urlreq.urlopen(req, timeout=15).read().decode())['results']:
                if ex.get('name') != _oidc_name:
                    continue
                req = _urlreq.Request(f'{_ak_url}/api/v3/providers/oauth2/{ex["pk"]}/', headers=_ak_headers)
                detail = json.loads(_urlreq.urlopen(req, timeout=15).read().decode())
                if detail.get('client_id') and detail.get('client_secret'):
                    oidc_pk, client_id, client_secret = ex['pk'], detail['client_id'], detail['client_secret']
                    patch = {'redirect_uris': redirect_uris_obj, 'client_type': 'confidential',
                             'grant_types': ['authorization_code', 'refresh_token']}
                    patch.update(_oidc_extras)
                    try:
                        req = _urlreq.Request(f'{_ak_url}/api/v3/providers/oauth2/{oidc_pk}/',
                            data=json.dumps(patch).encode(), headers=_ak_headers, method='PATCH')
                        _urlreq.urlopen(req, timeout=10)
                    except Exception:
                        pass
                    log('  ✓ WebODM OIDC provider already exists (healed)')
                else:
                    try:
                        req = _urlreq.Request(f'{_ak_url}/api/v3/providers/oauth2/{ex["pk"]}/',
                            headers=_ak_headers, method='DELETE')
                        _urlreq.urlopen(req, timeout=10)
                    except Exception:
                        pass
                break
        except Exception:
            pass
        if not oidc_pk:
            payload = {
                'name': _oidc_name,
                'authorization_flow': flow_pk,
                'invalidation_flow': inv_flow_pk,
                'client_type': 'confidential',
                'redirect_uris': redirect_uris_obj,
                # grant_types defaults to EMPTY on Authentik 2024.x+ create — an
                # empty list rejects every OIDC login before the user sees a
                # form (the NetBird/FedHub trap). Set it explicitly.
                'grant_types': ['authorization_code', 'refresh_token'],
            }
            payload.update(_oidc_extras)
            req = _urlreq.Request(f'{_ak_url}/api/v3/providers/oauth2/',
                data=json.dumps(payload).encode(), headers=_ak_headers, method='POST')
            p = json.loads(_urlreq.urlopen(req, timeout=15).read().decode())
            oidc_pk, client_id, client_secret = p.get('pk'), p.get('client_id', ''), p.get('client_secret', '')
            log(f'  ✓ WebODM OIDC provider created, client_id={client_id[:8]}...')

        # Separate application — an Authentik app holds ONE provider and the
        # 'webodm' app already carries the proxy provider. blank://blank keeps
        # this one out of the user launcher (same trick as the SSO connector).
        try:
            req = _urlreq.Request(f'{_ak_url}/api/v3/core/applications/',
                data=json.dumps({'name': _oidc_name, 'slug': 'webodm-oidc',
                    'provider': oidc_pk, 'meta_launch_url': 'blank://blank'}).encode(),
                headers=_ak_headers, method='POST')
            _urlreq.urlopen(req, timeout=10)
            log("  ✓ Application 'WebODM OIDC' created")
        except Exception as e:
            if hasattr(e, 'code') and e.code == 400:
                try:
                    req = _urlreq.Request(f'{_ak_url}/api/v3/core/applications/webodm-oidc/',
                        data=json.dumps({'provider': oidc_pk, 'meta_launch_url': 'blank://blank'}).encode(),
                        headers=_ak_headers, method='PATCH')
                    _urlreq.urlopen(req, timeout=10)
                except Exception:
                    pass
                log("  ✓ Application 'WebODM OIDC' updated")
            else:
                log(f'  ⚠ WebODM OIDC application error: {str(e)[:80]}')

        # webadmin ships WITHOUT an email, but WebODM's OIDC callback hard-requires
        # a non-empty email claim ("OIDC claims missing required sub or email" →
        # generic "SSO login failed"; field: aws-rocky 2026-07-02). Heal an empty
        # email with a deterministic synthetic address on the box FQDN. Other
        # operator-created users must have an email set in Authentik to use SSO.
        try:
            req = _urlreq.Request(f'{_ak_url}/api/v3/core/users/?search=webadmin', headers=_ak_headers)
            _wa_users = json.loads(_urlreq.urlopen(req, timeout=10).read().decode())['results']
            _wa = next((u for u in _wa_users if u.get('username') == 'webadmin'), None)
            if _wa and not (_wa.get('email') or '').strip():
                _wa_email = f'webadmin@{fqdn.split(":")[0]}'
                req = _urlreq.Request(f'{_ak_url}/api/v3/core/users/{_wa["pk"]}/',
                    data=json.dumps({'email': _wa_email}).encode(),
                    headers=_ak_headers, method='PATCH')
                _urlreq.urlopen(req, timeout=10)
                log(f'  ✓ webadmin had no email — set {_wa_email} (WebODM OIDC login requires an email claim)')
        except Exception:
            pass

        if oidc_pk and client_id and client_secret and settings:
            _webodm_apply_oidc_local_settings(settings, client_id, client_secret, plog=plog)
        elif not client_secret:
            log('  ⚠ No OIDC client secret — WebODM keeps manual login only')
    except Exception as e:
        log(f'  ⚠ WebODM OIDC setup error: {str(e)[:120]}')
    return True


