@app.route('/api/authentik/audit-log')
@login_required
def authentik_audit_log_api():
    """v0.9.23 Phase 1 forensic endpoint. Return the rolling audit events the
    watchdog has scraped from Authentik for the protected admin accounts.

    Useful for identifying mid-session mutators without SSH'ing to the box:
        curl -s -H "Cookie: $C" https://<host>/api/authentik/audit-log | jq

    Read-only. No mutations. Returns last 20 events per username plus repair
    counters and last-repair timestamps so operators can correlate the audit
    events (who/when/from-where) to our self-healer's writes.
    """
    s = load_settings()
    out = {
        'usernames': ['adm_ldapservice', 'webadmin'],
        'repair_counters': {
            'authentik_ldap_sa_repair_count': int(s.get('authentik_ldap_sa_repair_count') or 0),
            'authentik_ldap_sa_last_repair': s.get('authentik_ldap_sa_last_repair') or '',
            'authentik_webadmin_role_repair_count': int(s.get('authentik_webadmin_role_repair_count') or 0),
            'authentik_webadmin_role_last_repair': s.get('authentik_webadmin_role_last_repair') or '',
        },
        'events': {
            'adm_ldapservice': s.get('authentik_audit_recent_adm_ldapservice') or [],
            'webadmin': s.get('authentik_audit_recent_webadmin') or [],
        },
        'high_water': {
            'adm_ldapservice': s.get('authentik_audit_last_seen_adm_ldapservice') or '',
            'webadmin': s.get('authentik_audit_last_seen_webadmin') or '',
        },
    }
    return jsonify(out)


@app.route('/api/authentik/audit-log/scrape-now', methods=['POST'])
@login_required
def authentik_audit_log_scrape_now_api():
    """v0.9.23 Phase 1. Force an immediate audit-log scrape (don't wait for the
    next 5-min watchdog tick). Useful when an operator just witnessed a drift
    event and wants to see who wrote to the user RIGHT NOW.
    """
    try:
        n = _authentik_audit_scrape_recent(plog_fn=lambda m: print(m, flush=True))
        return jsonify({'success': True, 'new_events': n})
    except Exception as e:
        return jsonify({'success': False, 'message': str(e)[:200]}), 500


@app.route('/api/authentik/max-requests')
@login_required
def authentik_max_requests_api():
    """v0.9.23 endpoint. Return the current MAX_REQUESTS value + auto-tune
    state so the dashboard can surface 'Authentik worker recycle: every N
    requests, auto-tuned 2h ago after watchdog fired' to operators.

    Read-only.
    """
    s = load_settings()
    cur_max, cur_jitter = _authentik_max_requests_get_current()
    fires = list(s.get('authentik_max_requests_fire_history') or [])
    tunes = list(s.get('authentik_max_requests_tune_history') or [])
    import time as _t
    _now = int(_t.time())
    fires_last_24h = [f for f in fires if _now - f < 86400]
    out = {
        'current_max_requests': cur_max,
        'current_jitter': cur_jitter,
        'autotune_disabled': bool(s.get('authentik_max_requests_autotune_disabled')),
        'floor': int(s.get('authentik_max_requests_floor') or _AUTHENTIK_MAX_REQUESTS_FLOOR_DEFAULT),
        'ceiling': int(s.get('authentik_max_requests_ceiling') or _AUTHENTIK_MAX_REQUESTS_CEILING_DEFAULT),
        'baseline': int(s.get('authentik_max_requests_baseline') or 1000),
        'last_tune_ts': int(s.get('authentik_max_requests_last_tune_ts') or 0),
        'tune_history': tunes[-10:],
        'fire_history_last_24h_count': len(fires_last_24h),
        'last_fire_ts': max(fires) if fires else 0,
    }
    return jsonify(out)


@app.route('/api/authentik/max-requests/log')
@login_required
def authentik_max_requests_log_api():
    """v0.9.23 endpoint. Tail the auto-tune log file.

    Query params:
      - lines (int, default 200, max 5000): number of trailing lines to return

    Returns plain text (Content-Type: text/plain) so it can be `curl`'d into
    less / piped through grep without JSON parsing overhead.

    The log file is /var/log/takguard/ak-mr-autotune.log; tail it directly
    with `tail -F` on the VPS for live monitoring.
    """
    try:
        n = int(request.args.get('lines') or 200)
    except (TypeError, ValueError):
        n = 200
    n = max(1, min(n, 5000))
    try:
        if not os.path.exists(_AUTOTUNE_LOG_PATH):
            return ("(no events yet — auto-tune log file does not exist; "
                    "will be created when the watchdog records its first event)\n"),  200, {
                'Content-Type': 'text/plain; charset=utf-8'
            }
        with open(_AUTOTUNE_LOG_PATH, 'r', errors='replace') as f:
            tail = f.readlines()[-n:]
        body = ''.join(tail) or '(log file is empty)\n'
        return body, 200, {'Content-Type': 'text/plain; charset=utf-8'}
    except Exception as e:
        return f"(error reading log: {e})\n", 500, {
            'Content-Type': 'text/plain; charset=utf-8'
        }


@app.route('/api/authentik/max-requests/autotune', methods=['POST'])
@login_required
def authentik_max_requests_autotune_api():
    """v0.9.23 endpoint. Operator controls for the MAX_REQUESTS auto-tuner.

    Accepts JSON body with optional keys:
      - `disabled` (bool): set settings.authentik_max_requests_autotune_disabled
      - `floor` (int): clamp the minimum the auto-tuner will set
      - `ceiling` (int): clamp the maximum the auto-tuner will set
      - `baseline` (int): the "happy path" value the auto-tuner returns to
        after a long no-fire period

    No body or missing keys = no-op for that field (read current settings only).

    Returns the updated state. Read-only-style query is also supported via
    GET on /api/authentik/max-requests.
    """
    data = request.get_json() or {}
    s = load_settings()
    if 'disabled' in data:
        s['authentik_max_requests_autotune_disabled'] = bool(data['disabled'])
    if 'floor' in data:
        try:
            s['authentik_max_requests_floor'] = max(50, int(data['floor']))
        except (TypeError, ValueError):
            pass
    if 'ceiling' in data:
        try:
            s['authentik_max_requests_ceiling'] = min(10000, int(data['ceiling']))
        except (TypeError, ValueError):
            pass
    if 'baseline' in data:
        try:
            s['authentik_max_requests_baseline'] = int(data['baseline'])
        except (TypeError, ValueError):
            pass
    save_settings(s)
    return jsonify({
        'success': True,
        'autotune_disabled': bool(s.get('authentik_max_requests_autotune_disabled')),
        'floor': int(s.get('authentik_max_requests_floor') or _AUTHENTIK_MAX_REQUESTS_FLOOR_DEFAULT),
        'ceiling': int(s.get('authentik_max_requests_ceiling') or _AUTHENTIK_MAX_REQUESTS_CEILING_DEFAULT),
        'baseline': int(s.get('authentik_max_requests_baseline') or 1000),
    })


@app.route('/api/authentik/recover-admin', methods=['POST'])
@login_required
def authentik_recover_admin_api():
    """Reactivate a protected Authentik admin user. Whitelist: akadmin, webadmin.

    Tries the API first (bootstrap token from ~/authentik/.env), falls back to
    `docker exec authentik-server-1 ak shell` running Django ORM. The ak-shell
    path works even when the bootstrap token has been revoked or the
    authentication flow is broken — only requirement is that the
    authentik-server-1 container is running.
    """
    data = request.get_json() or {}
    username = (data.get('user') or '').strip()
    if not username:
        return jsonify({'success': False, 'message': 'user field required'}), 400
    ok, msg, method = _recover_authentik_user(username)
    status = 200 if ok else 400
    return jsonify({'success': ok, 'message': msg, 'method': method}), status


# --- v10.1.36 MFA device recovery -------------------------------------------------------

@app.route('/api/authentik/mfa/users')
@login_required
def authentik_mfa_users_api():
    """Search Authentik users and report the MFA devices each one has registered.

    Powers the MFA Device Recovery panel on /authentik — the "user lost their phone" path.
    Read-only. Requires ?q= (>=2 chars) so this can never be used to dump the directory.
    """
    q = (request.args.get('q') or '').strip()
    ak_url, ak_headers, _s = _w1_ak_ctx()
    if not ak_url:
        return jsonify({'users': [], 'error': 'authentik-not-deployed',
                        'message': 'Authentik is not deployed on this box (no API token).'})
    if len(q) < 2:
        return jsonify({'users': [], 'message': 'Type at least 2 characters to search.'})

    try:
        force_enroll, force_detail = _ak_force_enroll_posture(ak_url, ak_headers)
        codes_ok, codes_detail = _ak_backup_codes_posture(ak_url, ak_headers)
        found = _w1_ak_get(
            ak_url, f'core/users/?search={urllib.parse.quote(q, safe="")}&page_size=25',
            ak_headers).get('results', [])
        # One pass for the whole box, then join — authentik ignores ?user= on the device
        # viewsets, so a per-user query would be both wrong and 5x more calls.
        dev_map = _ak_all_mfa_devices(ak_url, ak_headers)
    except Exception as e:
        return jsonify({'users': [], 'error': 'authentik-api',
                        'message': f'Could not reach the Authentik API: {str(e)[:200]}'}), 502

    users = []
    for u in found:
        devs = dev_map.get(int(u['pk']), [])
        users.append({
            'pk': u['pk'],
            'username': u.get('username') or '',
            'name': u.get('name') or '',
            'email': u.get('email') or '',
            'is_active': bool(u.get('is_active')),
            'is_superuser': bool(u.get('is_superuser')),
            'devices': devs,
            'device_count': len(devs),
        })
    users.sort(key=lambda x: (x['device_count'] == 0, x['username'].lower()))
    return jsonify({
        'users': users,
        'posture': {
            'force_enroll': force_enroll,
            'force_enroll_detail': force_detail,
            'backup_codes': codes_ok,
            'backup_codes_detail': codes_detail,
        },
    })


@app.route('/api/authentik/mfa/reset', methods=['POST'])
@login_required
def authentik_mfa_reset_api():
    """Revoke every MFA device registered to one Authentik user.

    The lost-phone remedy: with the devices gone, W1's force-enroll walks the user through
    setting up a new authenticator at their next sign-in (this is the flow upstream documents
    for exactly this case). ATAK/iTAK are unaffected — the LDAP flow is never MFA-bound.

    Body: {user_pk: int, username: str, kill_sessions: bool, confirm_no_force_enroll: bool}

    `username` is an interlock, not decoration: the caller must name who it believes it is
    resetting, and we refuse on mismatch. Prevents a stale browser row from revoking the wrong
    person's MFA after the directory shifts under it.
    """
    data = request.get_json() or {}
    raw_pk = data.get('user_pk')
    expect = (data.get('username') or '').strip()
    kill_sessions = data.get('kill_sessions', True)

    try:
        user_pk = int(raw_pk)
    except (TypeError, ValueError):
        return jsonify({'success': False, 'message': 'user_pk must be an integer'}), 400
    if not expect:
        return jsonify({'success': False, 'message': 'username is required (identity interlock)'}), 400

    ak_url, ak_headers, _s = _w1_ak_ctx()
    if not ak_url:
        return jsonify({'success': False,
                        'message': 'Authentik is not deployed on this box (no API token).'}), 400

    try:
        user = _w1_ak_get(ak_url, f'core/users/{user_pk}/', ak_headers)
    except Exception as e:
        return jsonify({'success': False,
                        'message': f'Could not read user {user_pk}: {str(e)[:200]}'}), 502
    actual = user.get('username') or ''
    if actual != expect:
        return jsonify({'success': False, 'conflict': True,
                        'message': (f'Refusing to act: user {user_pk} is "{actual}", but the '
                                    f'request named "{expect}". Re-run the search and try again.')}), 409

    # Guard: without force-enroll, revoking devices does not prompt re-enrollment — it just
    # drops this user to password-only. Warn once, act only on an explicit second call.
    force_enroll, force_detail = _ak_force_enroll_posture(ak_url, ak_headers)
    if not force_enroll and not data.get('confirm_no_force_enroll'):
        return jsonify({
            'success': False, 'warning': 'no-force-enroll',
            'message': (f'This box will not prompt {actual} to enroll a new authenticator '
                        f'({force_detail}). Revoking their devices now would leave them signing '
                        f'in with a password only. Confirm to proceed anyway.'),
        }), 200

    try:
        devices = _ak_user_mfa_devices(ak_url, ak_headers, user_pk)
    except Exception as e:
        return jsonify({'success': False,
                        'message': f'Could not list devices: {str(e)[:200]}'}), 502

    removed, failures = _ak_revoke_mfa_devices(ak_url, ak_headers, devices)

    # Verify — never trust the write. Anything left is a failure to surface, not a success.
    try:
        left = _ak_user_mfa_devices(ak_url, ak_headers, user_pk)
    except Exception:
        left = []
    n_removed = sum(removed.values())

    sessions_killed, session_failures = 0, []
    if kill_sessions and not failures:
        try:
            for s in _ak_user_sessions(ak_url, ak_headers, user_pk):
                uuid_ = s.get('uuid')
                if not uuid_:
                    continue
                try:
                    _ak_api_call(
                        f'{ak_url}/api/v3/core/authenticated_sessions/'
                        f'{urllib.parse.quote(str(uuid_), safe="")}/',
                        method='DELETE', headers=ak_headers)
                    sessions_killed += 1
                except Exception as e:
                    session_failures.append(str(e)[:80])
        except Exception as e:
            session_failures.append(str(e)[:80])

    _record_mfa_reset(actual, user_pk, removed, sessions_killed)

    if failures or left:
        return jsonify({
            'success': False,
            'message': (f'Partly failed: removed {n_removed}, but {len(left)} device(s) remain '
                        f'on {actual}. ' + ('; '.join(failures)[:300] if failures else '')),
            'removed': removed, 'remaining': len(left),
        }), 500

    if n_removed == 0:
        msg = (f'{actual} had no MFA devices registered. They will be asked to set one up at '
               f'their next sign-in.')
    else:
        parts = ', '.join(f'{n} × {_AK_MFA_KIND_LABELS.get(k, k)}' for k, n in sorted(removed.items()))
        msg = (f'Removed {parts} from {actual}. They will be asked to set up a new authenticator '
               f'the next time they sign in.')
    if sessions_killed:
        msg += f' {sessions_killed} active session(s) signed out.'
    if session_failures:
        msg += f' (Some sessions could not be signed out: {session_failures[0]})'
    return jsonify({'success': True, 'message': msg, 'removed': removed,
                    'sessions_killed': sessions_killed})


@app.route('/api/authentik/mfa/reset-admin', methods=['POST'])
@login_required
def authentik_mfa_reset_admin_api():
    """Break-glass: reset a PROTECTED admin's MFA (akadmin / webadmin) when the operator is the
    one who lost their device. Falls back to `ak shell` when the API is unusable — see
    _purge_authentik_user_mfa(). Whitelist-gated; ordinary users go through /api/authentik/mfa/reset.
    """
    data = request.get_json() or {}
    username = (data.get('user') or '').strip()
    if not username:
        return jsonify({'success': False, 'message': 'user field required'}), 400
    # Count what is there BEFORE the purge so the audit entry states a real number. The
    # ak-shell fallback reports its own count but the API path does not, and an audit trail
    # that invents a figure is worse than one that admits it does not know.
    before = {}
    try:
        _u, _h, _s2 = _w1_ak_ctx()
        if _u:
            found = _w1_ak_get(
                _u, f'core/users/?username={urllib.parse.quote(username, safe="")}',
                _h).get('results', [])
            match = next((x for x in found if x.get('username') == username), None)
            if match:
                for d in _ak_user_mfa_devices(_u, _h, match['pk']):
                    before[d['kind']] = before.get(d['kind'], 0) + 1
    except Exception:
        before = {}

    ok, msg, method = _purge_authentik_user_mfa(username)
    if ok:
        _record_mfa_reset(username, None, before, 0, method=method or 'break-glass')
    return jsonify({'success': ok, 'message': msg, 'method': method}), (200 if ok else 400)


