@app.route('/api/takserver/connect-ldap', methods=['POST'])
@login_required
def takserver_connect_ldap():
    """One-shot: fix LDAP blueprint (remove recursion-causing password_stage), fix flow auth, ensure LDAP app open to all users (QR registration), ensure service account, ensure webadmin, patch CoreConfig, restart TAK Server."""
    diag = []
    settings = load_settings()
    ak_cfg = _get_module_deployment_config(settings, 'authentik_deployment')
    is_remote_ak = ak_cfg.get('target_mode') == 'remote' and (ak_cfg.get('remote', {}).get('host') or '').strip()
    # For remote Authentik, verify API reachability first (console must reach Authentik host:9090)
    if is_remote_ak:
        ok_api, err_api = _check_authentik_api_reachable(settings)
        if not ok_api:
            return jsonify({'success': False, 'message': err_api or 'Authentik API unreachable'}), 400
    # Fix LDAP blueprint if it has the broken password_stage (causes "invalid credentials" / recursion on user bind). Same fix for local or remote.
    if is_remote_ak:
        ok_bp, out = _ak_module_compose(ak_cfg, "grep -q 'password_stage: !KeyOf ldap-authentication-password' ~/authentik/blueprints/tak-ldap-setup.yaml 2>/dev/null && sed -i '/password_stage: !KeyOf ldap-authentication-password/d' ~/authentik/blueprints/tak-ldap-setup.yaml && cd ~/authentik && docker compose restart worker 2>&1; echo BP_DONE", 'connect-ldap-worker-restart', timeout=120)
        if ok_bp and 'BP_DONE' in (out or ''):
            diag.append('LDAP blueprint checked on remote (flow fix via API runs next)')
            if 'restart' in (out or '').lower():
                time.sleep(10)  # allow worker to reconcile if we restarted it
        elif not ok_bp:
            diag.append('Blueprint fix on remote: skip or failed (flow fix via API will still run)')
    else:
        bp_path = os.path.expanduser('~/authentik/blueprints/tak-ldap-setup.yaml')
        if os.path.exists(bp_path):
            try:
                with open(bp_path, 'r') as f:
                    content = f.read()
                if 'password_stage: !KeyOf ldap-authentication-password' in content:
                    _bp_orig = content
                    content = content.replace('      password_stage: !KeyOf ldap-authentication-password\n', '')
                    with open(bp_path, 'w') as f:
                        f.write(content)
                    _r = _ak_compose_subprocess(_sudo_wrap(['docker', 'compose', 'restart', 'worker']), 'connect-ldap-worker-restart', None,
                                                cwd=os.path.expanduser('~/authentik'), stdout=subprocess.PIPE, stderr=subprocess.STDOUT, timeout=90)
                    if _r.returncode == _AK_COMPOSE_LOCK_BUSY_RC:
                        # Put it back so the next Connect sees the fix as pending and retries.
                        with open(bp_path, 'w') as f:
                            f.write(_bp_orig)
                        diag.append('LDAP blueprint fix NOT applied (blueprint restored): worker restart '
                                    + _r.stdout.decode())
                    else:
                        time.sleep(50)  # let blueprint reconcile and update identification stage
                        diag.append('LDAP blueprint fixed (removed password_stage); worker restarted')
            except Exception as e:
                diag.append(f'Blueprint fix: {str(e)[:80]}')
    # Fix flow (clear identification password_stage, ensure 3 ldap-* bindings) so user bind / QR works
    ok_flow, err_flow = _ensure_ldap_flow_authentication_none()
    if not ok_flow:
        diag.append(f'Flow fix: {err_flow}')
        msg = ' | '.join(diag)
        if is_remote_ak:
            msg += '. For remote Authentik ensure this host can reach the Authentik server on port 9090 (firewall).'
        return jsonify({'success': False, 'message': msg}), 400
    diag.append('Flow: OK')
    # Ensure LDAP app has no restrictive policy (blocks QR registration for non-admin users)
    try:
        settings = load_settings()
        ak_token = _get_authentik_env_value(settings, 'AUTHENTIK_BOOTSTRAP_TOKEN') or _get_authentik_env_value(settings, 'AUTHENTIK_TOKEN')
        if ak_token:
            ak_url = _get_authentik_api_url(settings)
            _ensure_app_access_policies(ak_url, {'Authorization': f'Bearer {ak_token}', 'Content-Type': 'application/json'}, lambda m: diag.append(m.strip()))
            diag.append('App policies: LDAP open to all authenticated users')
    except Exception as e:
        diag.append(f'App policies: {str(e)[:60]}')
    # Resync LDAP credential BEFORE bind test so drifted password can't block the fix
    changed, resync_msg = _resync_ldap_credential_to_coreconfig()
    if changed:
        diag.append(f'Credential resync: {resync_msg}')
    # v10.0.1: wait for Authentik healthy (self-heal a stopped container) + retry on
    # a transient API 500 — on an unhealthy fresh-deploy Authentik this button used to
    # fail with "Authentik API 500: <!DOCTYPE html>…" and leave 8446 on WebTAK.
    ok, msg = _sync_authentik_ldap_sa_with_retry(lambda m: diag.append(m.strip()))
    if not ok:
        if '-w' in (msg or ''):
            msg = 'ldapsearch timed out or failed (check Authentik LDAP outpost logs)'
        diag.append(f'Service account: LDAP bind failed ({msg}) — continuing with CoreConfig patch')
    else:
        diag.append(f'Service account: {msg}')
    ok_wa, err_wa = _ensure_authentik_webadmin()
    if not ok_wa:
        diag.append(f'WebAdmin: {err_wa}')
    else:
        diag.append('WebAdmin: OK')
    _remove_webadmin_from_userauth()
    diag.append('Removed flat-file webadmin shadow if present (8446 → LDAP)')
    ok, msg = _apply_ldap_to_coreconfig()
    diag.append(f'CoreConfig: {msg}')
    # Run the proactive FQDN routing migration directly from the manual repair button, BEFORE the
    # bind verification below. Previously this only fired from a full deploy or the webadmin-sync
    # 'inconclusive' branch — so on a box stranded on internal routing (hard 'fail' verdict) the
    # operator's "Resync LDAP" click never actually moved the outpost off the spiral-prone path.
    # The migration is self-contained (recreates only the ldap container, validates the websocket
    # connection, auto-rolls-back if FQDN isn't viable), so it's safe to invoke here. Visible output.
    # force: an operator click skips the failed-move back-off (ops #128), not the DNS/cert check.
    try:
        _ensure_authentik_ldap_outpost_on_fqdn(lambda m: diag.append(m.strip()), force=True)
    except Exception as _e:
        diag.append(f'Proactive routing: skipped ({str(_e)[:80]})')
    # Diagnostic: compare passwords and check outpost health
    try:
        settings = load_settings()
        ldap_pass = _get_authentik_env_value(settings, 'AUTHENTIK_BOOTSTRAP_LDAPSERVICE_PASSWORD')
        import re as _re
        cc_pass = ''
        if os.path.exists('/opt/tak/CoreConfig.xml'):
            m = _re.search(r'serviceAccountCredential="([^"]*)"', _read_coreconfig())
            cc_pass = m.group(1) if m else ''
        if ldap_pass and cc_pass:
            diag.append(f'Password match: {"YES" if ldap_pass == cc_pass else "NO (MISMATCH!)"}')
        elif not cc_pass:
            diag.append('Password: not in CoreConfig')
        ak_cfg = _get_module_deployment_config(settings, 'authentik_deployment')
        if ak_cfg.get('target_mode') == 'remote' and (ak_cfg.get('remote', {}).get('host') or '').strip():
            ok_ssh, out = _ssh_probe(ak_cfg['remote'], 'docker ps --filter name=authentik-ldap --format "{{.Status}}" 2>/dev/null', timeout=10)
            ldap_status = (out or '').strip()
            diag.append(f'LDAP outpost: {ldap_status or "not running"}')
            ok_ssh2, out2 = _ssh_probe(ak_cfg['remote'], 'docker logs authentik-ldap-1 --since 60s 2>&1 | tail -25', timeout=15)
            outpost_tail = (out2 or '').strip()
        else:
            r = subprocess.run(_sudo_wrap(['docker', 'ps', '--filter', 'name=authentik-ldap', '--format', '{{.Status}}']), capture_output=True, text=True, timeout=10)
            ldap_status = (r.stdout or '').strip()
            diag.append(f'LDAP outpost: {ldap_status or "not running"}')
            r = _priv_pipe(['docker', 'logs', 'authentik-ldap-1', '--since', '60s'], ['tail', '-25'], timeout=10)
            outpost_tail = (r.stdout or '').strip()
        if outpost_tail:
            # Classify the bind OUTCOME up front — the result line was previously cut off by the
            # 200-char truncation, which hid whether the failure was a flow spiral (slow-disk /
            # recursion), a real password mismatch, or actually a success that verification missed.
            _low = outpost_tail.lower()
            if 'exceeded stage recursion depth' in _low or 'nil pointer dereference' in _low:
                diag.append('Outpost verdict: FLOW SPIRAL (stage recursion) — bind-flow recursion, NOT a bad password')
            elif 'invalid credentials' in _low or 'access denied' in _low or 'insufficient access' in _low:
                diag.append('Outpost verdict: INVALID CREDENTIALS — password mismatch (re-set webadmin pw + Sync webadmin)')
            elif 'authenticated' in _low:
                diag.append('Outpost verdict: AUTHENTICATED — bind succeeded (verification may be falsely red)')
            elif 'failed to execute flow' in _low or 'ak-stage-flow-error' in _low or 'flow error' in _low:
                diag.append('Outpost verdict: FLOW ERROR — bind flow could not complete (check ldap-* flow bindings)')
            # Surface the outcome-bearing lines (not just the last 5), and raise the cap so the
            # decisive line is never cut. Fall back to the raw tail if no marker matched.
            _markers = ('authenticated', 'invalid credentials', 'access denied', 'recursion',
                        'flow error', 'failed to execute flow', 'ak-stage-flow-error', 'bind request')
            _hot = [ln for ln in outpost_tail.splitlines() if any(m in ln.lower() for m in _markers)]
            _show = '\n'.join(_hot[-8:]) if _hot else outpost_tail
            diag.append(f'Outpost log: {_show[:800]}')
    except Exception as e:
        diag.append(f'Diagnostic error: {str(e)[:100]}')
    # Post-fix verification signals (best-effort)
    try:
        verify = {}
        verify['coreconfig_has_ldap'] = bool(_coreconfig_has_ldap())
        ws = _get_authentik_webadmin_status()
        verify['webadmin_exists_in_authentik'] = bool(ws.get('exists'))
        verify['webadmin_superuser'] = bool(ws.get('is_superuser'))
        ldap_pass = _get_authentik_env_value(settings, 'AUTHENTIK_BOOTSTRAP_LDAPSERVICE_PASSWORD') or ''
        verify['service_bind_seen'] = bool(_test_ldap_bind(ldap_pass)) if ldap_pass else False
        wap = (settings.get('webadmin_password') or '').strip()
        # Tri-state verdict ('ok' | 'fail' | 'inconclusive'). The boolean wrapper used to
        # conflate 'fail' and 'inconclusive' as False, so a box where ldapsearch couldn't be
        # installed (apt lock / no network during deploy) ALWAYS reported webadmin-bind=FAIL and
        # a scary "NOT READY (verification failed)" — even when the bind actually worked. We now
        # distinguish a CONFIRMED failure (real problem) from "could not verify" (probably fine).
        wa_verdict = _test_ldap_bind_dn_verdict('cn=webadmin,ou=users,dc=takldap', wap) if wap else 'fail'
        verify['webadmin_bind'] = wa_verdict
        verify['webadmin_bind_seen'] = (wa_verdict == 'ok')
        core_ok = all([
            verify['coreconfig_has_ldap'],
            verify['webadmin_exists_in_authentik'],
            verify['webadmin_superuser'],
        ])
        verify['ready'] = bool(core_ok and wa_verdict == 'ok')
        verify['unverified'] = bool(core_ok and wa_verdict == 'inconclusive')
        diag.append(
            "Verification: coreconfig={} webadmin={} superuser={} webadmin-bind={} ready={}".format(
                'OK' if verify['coreconfig_has_ldap'] else 'FAIL',
                'OK' if verify['webadmin_exists_in_authentik'] else 'FAIL',
                'OK' if verify['webadmin_superuser'] else 'FAIL',
                {'ok': 'OK', 'fail': 'FAIL', 'inconclusive': 'UNVERIFIED'}.get(wa_verdict, 'FAIL'),
                'YES' if verify['ready'] else ('UNVERIFIED' if verify['unverified'] else 'NO'),
            )
        )
    except Exception as e:
        verify = {'ready': False, 'error': str(e)[:120]}
        diag.append(f'Verification: ERROR ({str(e)[:80]})')
    # An 'inconclusive' webadmin bind (core config all good but ldapsearch unavailable) is NOT a
    # failure — report success with a clear UNVERIFIED caveat and the manual 8446 test as the next
    # step, instead of a false-red dead end. Only a CONFIRMED 'fail' blocks success.
    if verify.get('unverified'):
        overall_ok = bool(ok)
        diag.append('Final: READY (webadmin bind UNVERIFIED — ldapsearch unavailable; confirm by logging in at '
                    ':8446. If 8446 rejects the password, run: docker logs authentik-ldap-1 --since 2m — a '
                    '"stage recursion" line means the bind-flow spiral, "invalid credentials" means a password mismatch)')
    else:
        overall_ok = bool(ok and verify.get('ready', True))
        diag.append('Final: READY' if overall_ok else 'Final: NOT READY (verification failed)')
    # ops #126: the webadmin/FQDN steps above can recreate the LDAP outpost under a TAK
    # Server that _apply_ldap_to_coreconfig left running (CoreConfig already correct). If
    # so, heal TAK's clients once LDAP settles (restart only as the fallback) — in the
    # background, it takes minutes.
    if not is_remote_ak:
        threading.Thread(
            target=lambda: _tak_recycle_after_ldap_outage(
                lambda m: print(f"Resync LDAP to TAK Server:{m}", flush=True),
                'Resync LDAP to TAK Server', check_outpost=True),
            daemon=True, name='tak-ldap-recycle').start()
        diag.append('TAK clients: if the outpost was restarted under TAK Server, clients left with no '
                    'groups are re-checked in the background once LDAP settles (TAK restart only if that '
                    'fails; console log: "TAK LDAP recycle")')
    return jsonify({'success': overall_ok, 'message': ' | '.join(diag), 'verification': verify})


@app.route('/api/takserver/ldap-drift-check')
@login_required
def takserver_ldap_drift_check():
    """Compare LDAP service-account password in Authentik .env vs CoreConfig.xml.

    Returns {match: bool, detail: str} so the frontend can warn on drift.
    """
    settings = load_settings()
    coreconfig = '/opt/tak/CoreConfig.xml'
    env_pass = _get_authentik_env_value(settings, 'AUTHENTIK_BOOTSTRAP_LDAPSERVICE_PASSWORD')
    env_src = 'authentik'
    if env_pass is None:
        portal_env = os.path.expanduser('~/tak-portal/.env')
        if os.path.isfile(portal_env):
            try:
                with open(portal_env) as f:
                    for line in f:
                        if line.strip().startswith('AUTHENTIK_BOOTSTRAP_LDAPSERVICE_PASSWORD='):
                            env_pass = line.strip().split('=', 1)[1].strip()
                            env_src = portal_env
                            break
            except Exception:
                pass
    if not os.path.exists(coreconfig):
        return jsonify({'match': True, 'detail': 'no_coreconfig'})
    try:
        cc = _read_coreconfig(coreconfig)
    except Exception:
        return jsonify({'match': True, 'detail': 'coreconfig_unreadable'})
    if 'adm_ldapservice' not in cc:
        return jsonify({'match': True, 'detail': 'no_ldap_in_coreconfig'})
    import re as _re
    m = _re.search(r'serviceAccountCredential="([^"]*)"', cc)
    if not m:
        return jsonify({'match': True, 'detail': 'no_credential_attr'})
    cc_pass = m.group(1)

    if env_pass is None:
        return jsonify({'match': True, 'detail': 'no_env_password_found'})

    if cc_pass == env_pass:
        return jsonify({'match': True, 'detail': 'ok', 'source': env_src})
    return jsonify({
        'match': False,
        'detail': 'LDAP credential drift detected — CoreConfig.xml password does not match Authentik .env. Click Resync LDAP to fix.',
        'source': env_src
    })


_vacuum_status = {'running': False, 'full': False, 'started': None, 'result': None, 'error': None}

def _run_vacuum_background(use_full, tak_cfg):
    vacuum_sql = "VACUUM FULL;" if use_full else "VACUUM ANALYZE;"
    timeout_sec = 3600 if use_full else 600
    _vacuum_status.update({'running': True, 'full': use_full, 'started': datetime.now().isoformat(), 'result': None, 'error': None})
    try:
        if tak_cfg.get('mode') == 'two_server':
            s1 = tak_cfg.get('server_one', {})
            # cd / first: SSH lands in /root, and `sudo -u postgres` can't cd there, which
            # prints a benign "could not change directory to /root: Permission denied" warning
            # into the output and reads as a failure even though VACUUM ran. (Local path uses cwd='/'.)
            vacuum_cmd = f"cd / && sudo -u postgres psql -d cot -c '{vacuum_sql}' 2>&1"
            ok, out = _ssh_probe(s1, vacuum_cmd, timeout=timeout_sec)
            if not ok:
                _vacuum_status.update({'running': False, 'error': (out or 'SSH command failed')[:500]})
                return
            _vacuum_status.update({'running': False, 'result': (out or '').strip()})
        else:
            r = _pg_exec(['psql', '-d', 'cot', '-c', vacuum_sql], timeout=timeout_sec)
            out = (r.stdout or '') + (r.stderr or '')
            if r.returncode != 0:
                _vacuum_status.update({'running': False, 'error': out.strip() or f'Exit code {r.returncode}'})
                return
            _vacuum_status.update({'running': False, 'result': out.strip()})
    except subprocess.TimeoutExpired:
        _vacuum_status.update({'running': False, 'error': 'VACUUM timed out (database may be very large)'})
    except Exception as e:
        _vacuum_status.update({'running': False, 'error': str(e)[:200]})

@app.route('/api/takserver/vacuum', methods=['POST'])
@login_required
def takserver_vacuum():
    """Run VACUUM on the CoT database in background. Returns immediately, poll /api/takserver/vacuum/status."""
    if not os.path.exists('/opt/tak'):
        return jsonify({'success': False, 'error': 'TAK Server not installed'}), 400
    if _vacuum_status['running']:
        return jsonify({'success': False, 'error': 'VACUUM already running', 'status': 'running', 'full': _vacuum_status['full'], 'started': _vacuum_status['started']}), 409
    data = request.get_json() or {}
    use_full = data.get('full') is True
    settings = load_settings()
    tak_cfg = _get_tak_deployment_config(settings)
    if tak_cfg.get('mode') == 'two_server':
        s1 = tak_cfg.get('server_one', {})
        if not s1.get('host'):
            return jsonify({'success': False, 'error': 'Server One host not configured'}), 400

    # v10.1.29 W3 — preflight VACUUM FULL before the thread starts.
    # VACUUM FULL rewrites each table into a NEW file before dropping the old
    # one, so on a full filesystem it is arithmetically impossible and PostgreSQL
    # answers with `could not extend file … Check free disk space.` — an error the
    # operator cannot act on, and the one that dead-ended mg1921 on 2026-08-10.
    # Refuse legibly instead of letting PostgreSQL hit ENOSPC. VACUUM ANALYZE
    # (full=false) is safe and cheap and stays completely ungated.
    if use_full:
        facts = _cotdb_facts(tak_cfg)
        refusal = _cotdb_space_refusal(facts)
        if refusal:
            return jsonify(dict(refusal, success=False)), 400
        dead = facts.get('dead_tuples')
        # Only claim "no bloat" when the dead-tuple count is actually a
        # measurement. If ANALYZE has never run it reads ~0 on a badly bloated
        # database, and refusing here would block the very box that needs this.
        if (dead is not None and dead < _COTDB_BLOAT_FLOOR
                and not facts.get('stats_stale') and data.get('force') is not True):
            # Not a hard refuse: it is legal, just pointless. Say so and steer.
            return jsonify({
                'success': False, 'warn_no_bloat': True, 'verdict': 'no_bloat',
                'dead_tuples': dead, 'db_human': facts.get('db_human', '-'),
                'recommend': ['purge'],
                'error': (f"This will reclaim almost nothing - {dead:,} dead tuples. "
                          f"Your {facts.get('db_human', '-')} is live data, and VACUUM FULL only "
                          "recovers space held by DELETED rows. Purge Old CoT is what you want."),
            }), 409

    threading.Thread(target=_run_vacuum_background, args=(use_full, tak_cfg), daemon=True).start()
    return jsonify({'success': True, 'status': 'started', 'full': use_full})

@app.route('/api/takserver/vacuum/status')
@login_required
def takserver_vacuum_status():
    """Poll VACUUM progress. Also checks PostgreSQL directly for running VACUUM."""
    running = _vacuum_status['running']
    full = _vacuum_status['full']
    elapsed_secs = 0
    if not running:
        try:
            check_sql = "SELECT query, extract(epoch from now() - query_start)::int AS secs FROM pg_stat_activity WHERE query ILIKE '%VACUUM%' AND state = 'active' AND pid != pg_backend_pid() LIMIT 1;"
            settings = load_settings()
            tak_cfg = _get_tak_deployment_config(settings)
            if tak_cfg.get('mode') == 'two_server':
                s1 = tak_cfg.get('server_one', {})
                if s1.get('host'):
                    ok, out = _ssh_probe(s1, f'sudo -u postgres psql -t -A -d cot -c "{check_sql}" 2>/dev/null', timeout=10)
                    raw = (out or '').strip()
            else:
                r = _pg_exec(['psql', '-t', '-A', '-d', 'cot', '-c', check_sql], timeout=10)
                raw = (r.stdout or '').strip()
            if raw and 'VACUUM' in raw.upper():
                running = True
                full = 'FULL' in raw.upper()
                parts = raw.split('|')
                elapsed_secs = int(parts[-1]) if len(parts) > 1 and parts[-1].strip().isdigit() else 0
        except Exception:
            pass
    if running and not elapsed_secs and _vacuum_status.get('started'):
        try:
            st = datetime.fromisoformat(_vacuum_status['started'])
            elapsed_secs = int((datetime.now() - st).total_seconds())
        except Exception:
            pass
    return jsonify({
        'running': running,
        'full': full,
        'elapsed_secs': elapsed_secs,
        'result': _vacuum_status['result'],
        'error': _vacuum_status['error'],
    })


@app.route('/api/takserver/reindex', methods=['POST'])
@login_required
def takserver_reindex():
    """Run REINDEX on the CoT database to rebuild indexes and improve query performance."""
    if not os.path.exists('/opt/tak'):
        return jsonify({'success': False, 'error': 'TAK Server not installed'}), 400
    reindex_sql = "REINDEX DATABASE cot;"
    timeout_sec = 3600

    settings = load_settings()
    tak_cfg = _get_tak_deployment_config(settings)
    if tak_cfg.get('mode') == 'two_server':
        s1 = tak_cfg.get('server_one', {})
        if not s1.get('host'):
            return jsonify({'success': False, 'error': 'Server One host not configured'}), 400
        # cd / first (see VACUUM note): avoids the benign "/root: Permission denied" warning leaking into output.
        reindex_cmd = f"cd / && sudo -u postgres psql -d cot -c '{reindex_sql}' 2>&1"
        ok, out = _ssh_probe(s1, reindex_cmd, timeout=timeout_sec)
        if not ok:
            return jsonify({'success': False, 'error': (out or 'SSH command failed')[:500]}), 400
        return jsonify({'success': True, 'output': (out or '').strip(), 'remote': True})

    try:
        r = _pg_exec(['psql', '-d', 'cot', '-c', reindex_sql], timeout=timeout_sec)
        out = (r.stdout or '') + (r.stderr or '')
        if r.returncode != 0:
            return jsonify({'success': False, 'error': out.strip() or f'Exit code {r.returncode}'}), 400
        return jsonify({'success': True, 'output': out.strip()})
    except subprocess.TimeoutExpired:
        return jsonify({'success': False, 'error': 'REINDEX timed out (database may be very large)'}), 400
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)[:200]}), 500


@app.route('/api/takserver/cot-db-size')
@login_required
def takserver_cot_db_size():
    """Return CoT database size in bytes and human-readable (for UI)."""
    if not os.path.exists('/opt/tak'):
        return jsonify({'size_bytes': 0, 'size_human': 'N/A', 'error': 'TAK Server not installed'})
    size_cmd = "sudo -u postgres psql -t -A -c \"SELECT COALESCE(pg_database_size('cot'), 0);\" 2>/dev/null"
    try:
        settings = load_settings()
        tak_cfg = _get_tak_deployment_config(settings)
        if tak_cfg.get('mode') == 'two_server':
            s1 = tak_cfg.get('server_one', {})
            if not s1.get('host'):
                return jsonify({'size_bytes': 0, 'size_human': 'N/A', 'error': 'Server One host not configured'})
            ok, out = _ssh_probe(s1, size_cmd, timeout=15)
            raw = (out or '0').strip()
        else:
            r = _pg_exec(['psql', '-t', '-A', '-c', "SELECT COALESCE(pg_database_size('cot'), 0);"], timeout=10)
            raw = (r.stdout or '0').strip()
        size = int(raw or 0)
        if size >= 1024 ** 3:
            human = f'{size // (1024**3)} GB'
        elif size >= 1024 ** 2:
            human = f'{size // (1024**2)} MB'
        elif size >= 1024:
            human = f'{size // 1024} KB'
        else:
            human = f'{size} B'
        # Additional stats
        msg_count = 0
        dead_tuples = 0
        try:
            stats_sql = "SELECT COALESCE((SELECT SUM(n_live_tup) FROM pg_stat_user_tables), 0), COALESCE((SELECT SUM(n_dead_tup) FROM pg_stat_user_tables), 0);"
            if tak_cfg.get('mode') == 'two_server':
                ok2, out2 = _ssh_probe(s1, f'sudo -u postgres psql -t -A -d cot -c "{stats_sql}" 2>/dev/null', timeout=15)
                parts = (out2 or '0|0').strip().split('|')
            else:
                r2 = _pg_exec(['psql', '-t', '-A', '-d', 'cot', '-c', stats_sql], timeout=10)
                parts = (r2.stdout or '0|0').strip().split('|')
            msg_count = int(parts[0]) if len(parts) > 0 and parts[0].strip().isdigit() else 0
            dead_tuples = int(parts[1]) if len(parts) > 1 and parts[1].strip().isdigit() else 0
        except Exception:
            pass
        return jsonify({'size_bytes': size, 'size_human': human, 'message_count': msg_count, 'dead_tuples': dead_tuples})
    except Exception as e:
        return jsonify({'size_bytes': 0, 'size_human': 'N/A', 'error': str(e)[:200]})


# ==========================================================================
# v10.1.29 — Guard Dog CoT database rescue (W1)
# ==========================================================================
# Field case (mg1921, 2026-08-10): 96 GB root disk 100% full, 43 GB CoT DB,
# 48.3M rows, 147 dead tuples. Every button on the Database maintenance card
# was either impossible to run (VACUUM FULL / repack need free space roughly
# equal to the largest table) or would have reclaimed nothing (the space was
# LIVE rows that retention had never deleted). PostgreSQL emitted a raw
# `could not extend file … Check free disk space.` and the operator concluded
# the database was corrupt. It was not.
#
# _cotdb_facts() is the single read-only fact-gatherer behind the Diagnose
# verdict, the stat tiles and every preflight gate, so the diagnosis and the
# gates can never disagree.
#
# SECURITY INVARIANT: every statement here is console-authored FIXED SQL. No
# request value is ever interpolated as a string — see _pg_exec()'s docstring.
# Table names come from the fixed allowlist below, never from a request.
_COTDB_TABLES = ('cot_router',)

# ops #227: the cot_router rows retention actually deletes — tak-retention-guard.sh's
# EXPIRED_WHERE (TAK's own LocalQueryService.deleteCotByTtl predicate) minus the age
# bound. Mission content (mission_uid) and legacy GeoChat ('b-t-f') are kept on
# purpose, so an old one of those is never evidence that retention has stalled.
_COTDB_EXPIRABLE_WHERE = ("cr.cot_type <> 'b-t-f' AND NOT EXISTS "
                          "(SELECT 1 FROM mission_uid mu WHERE mu.uid = cr.uid)")

# psql prints this when it runs as the postgres OS user from a cwd that user
# cannot read — e.g. a console installed under /home/<operator>/infra-TAK on a
# non-root box. Harmless, unrelated to the query, and on 2026-08-10 it was
# printed in red directly above the real ENOSPC error and cost diagnostic time.
_COTDB_NOISE_RE = re.compile(r'^.*could not change directory to.*$\n?', re.MULTILINE)

# Verdict thresholds. Fleet constants — no per-box tuning, no operator override.
_COTDB_COMPACT_HEADROOM = 1.1        # free space needed vs largest table
_COTDB_BLOAT_FLOOR = 100000          # below this, VACUUM FULL reclaims ~nothing
_COTDB_BLOAT_CEIL = 1000000          # above this, compacting is worth it
# "Is there actually a problem to solve?" Cases 3/4 of the verdict tree answer
# WHICH remedy to reach for when a database is big or a disk is tight. Without
# this gate, a small idle box gets told "only N dead tuples -> Purge Old CoT",
# which points a perfectly healthy box at a destructive button (seen on nuc,
# 219 MB database with 177 GB free, 2026-08-10). Thresholds match what the rest
# of the card already uses: the cotdb-watch size warning, and the free-disk
# tile's green boundary.
_COTDB_PRESSURE_DB_BYTES = 25 * 1024 ** 3
_COTDB_PRESSURE_FREE_PCT = 20


def _cotdb_clean(text):
    """Strip psql's benign 'could not change directory' warning from output."""
    return _COTDB_NOISE_RE.sub('', text or '').strip()


def _cotdb_fmt_bytes(n):
    try:
        n = int(n or 0)
    except Exception:
        return '-'
    for unit, div in (('TB', 1024 ** 4), ('GB', 1024 ** 3), ('MB', 1024 ** 2), ('KB', 1024)):
        if n >= div:
            v = n / div
            return f'{v:.1f} {unit}' if v < 10 else f'{int(round(v))} {unit}'
    return f'{n} B'


def _cotdb_fmt_age(seconds):
    """Human age for the oldest CoT row: '4 hours' / '3 days' / '8 months'."""
    try:
        s = int(seconds or 0)
    except Exception:
        return '-'
    if s <= 0:
        return '-'
    if s < 3600:
        return f'{max(1, s // 60)} min'
    if s < 172800:
        return f'{s // 3600} hours'
    d = s // 86400
    if d < 60:
        return f'{d} days'
    if d < 730:
        return f'{d // 30} months'
    return f'{d // 365} years'


def _cotdb_psql(tak_cfg, sql, db='cot', timeout=25):
    """Run ONE console-authored statement against the CoT cluster.

    Returns (ok, text). Covers local native, containerized TAK and the non-root
    broker (all via _pg_exec, which already picks runuser vs docker exec) plus
    the two-server SSH path used by the existing DB routes."""
    if tak_cfg.get('mode') == 'two_server':
        s1 = tak_cfg.get('server_one', {})
        if not (s1.get('host') or '').strip():
            return False, 'Server One host not configured'
        # cd / first: SSH lands in a home dir that `sudo -u postgres` cannot read.
        cmd = f'cd / && sudo -u postgres psql -t -A -d {db} -c {shlex.quote(sql)}'
        ok, out = _ssh_probe(s1, cmd, timeout=timeout)
        return ok, _cotdb_clean(out)
    try:
        r = _pg_exec(['psql', '-t', '-A', '-d', db, '-c', sql], timeout=timeout)
        if r.returncode == 0:
            return True, _cotdb_clean(r.stdout or '')
        return False, _cotdb_clean((r.stdout or '') + (r.stderr or ''))
    except subprocess.TimeoutExpired:
        return False, 'query timed out'
    except Exception as e:
        return False, str(e)[:200]


def _cotdb_df(tak_cfg, path):
    """(free_bytes, total_bytes) for the filesystem holding `path`, measured
    where the DATA actually lives — over SSH in two-server mode, INSIDE the DB
    container for container TAK (its named volume is a different filesystem than
    the console's cwd), natively otherwise. Reporting `/` instead of the data
    directory is exactly the kind of wrong number this card is meant to kill."""
    out = ''
    try:
        if tak_cfg.get('mode') == 'two_server':
            s1 = tak_cfg.get('server_one', {})
            ok, raw = _ssh_probe(s1, f'df -P -B1 {shlex.quote(path)}', timeout=15)
            out = raw if ok else ''
        elif _tak_is_container():
            r = subprocess.run(_sudo_wrap(['docker', 'exec', TAK_DB_CONTAINER, 'df', '-P', '-B1', path]),
                               capture_output=True, text=True, timeout=15)
            out = (r.stdout or '') if r.returncode == 0 else ''
        else:
            # df on a mounted filesystem is unprivileged — run it unwrapped so an
            # enforcing broker never needlessly denies it.
            r = subprocess.run(['df', '-P', '-B1', path], capture_output=True, text=True, timeout=15)
            out = (r.stdout or '') if r.returncode == 0 else ''
    except Exception:
        out = ''
    for line in reversed([l for l in (out or '').splitlines() if l.strip()]):
        parts = line.split()
        if len(parts) >= 4 and parts[1].isdigit() and parts[3].isdigit():
            return int(parts[3]), int(parts[1])
    try:
        st = os.statvfs(path if os.path.isdir(path) else '/')
        return st.f_bavail * st.f_frsize, st.f_blocks * st.f_frsize
    except Exception:
        return 0, 0


TAK_RETENTION_POLICY_YML = '/opt/tak/conf/retention/retention-policy.yml'


def _cotdb_retention_hours():
    """CoT retention TTL in hours, from where TAK Server 5.x ACTUALLY stores it.

    The policy set in TAK's Web Admin (:8443 > Data Retention Policies) lives in
    /opt/tak/conf/retention/retention-policy.yml under `dataRetentionMap.cot`,
    in SECONDS. It is NOT CoreConfig.xml's `retentionDays` — 5.x does not use
    that attribute at all. Verified 2026-08-10: on test6/test8/test12 the
    <repository> element carries no retentionDays whatsoever, yet the retention
    service logs `deleteCotByTtl, Number of rows deleted 78` every hour, driven
    by `cot: 86400` in the YAML. Reading the wrong file made every correctly
    configured box look like it had no retention policy at all.

    `cot: null` means no policy is set (nuc). CoreConfig remains a fallback for
    older servers. We only READ this — the policy is TAK Server's to own."""
    try:
        with open(TAK_RETENTION_POLICY_YML, 'r', encoding='utf-8') as fh:
            pol = fh.read()
    except Exception:
        try:
            pol = _read_priv(TAK_RETENTION_POLICY_YML)
        except Exception:
            pol = ''
    if pol:
        blk = pol.split('dataRetentionMap:', 1)
        m = re.search(r'^\s+cot:\s*(\S+)\s*$', blk[1] if len(blk) > 1 else pol, re.M)
        if m:
            raw = m.group(1).strip()
            if raw.isdigit() and int(raw) > 0:
                # seconds -> hours, never rounding a real policy down to zero
                return max(1, int(raw) // 3600)
            return None            # null / ~ / 0 -> explicitly no policy
    try:
        cc = _read_coreconfig()
    except Exception:
        return None
    try:
        import xml.etree.ElementTree as ET
        root = ET.fromstring(cc)
    except Exception:
        return None
    ns = {'m': 'http://bbn.com/marti/xml/config'}
    try:
        repos = list(root.findall('.//m:repository', ns)) + list(root.findall('.//repository'))
    except Exception:
        return None
    for repo in repos:
        rd = repo.get('retentionDays')
        if not rd:
            continue
        try:
            h = int(float(rd) * 24)
        except Exception:
            continue
        if h > 0:
            return h
    return None


def _cotdb_systemctl(args, timeout=6):
    """systemctl stdout (ignoring exit status — `is-enabled` exits non-zero for a
    disabled unit but still prints the state). Verb-gated by the broker."""
    try:
        r = subprocess.run(_sudo_wrap(['systemctl'] + list(args)),
                           capture_output=True, text=True, timeout=timeout)
        return (r.stdout or '').strip()
    except Exception:
        return ''


def _cotdb_retention_proc_alive():
    """Is TAK's retention Java process running? (the 5th TAK process). None when
    it cannot be determined."""
    try:
        if _tak_is_container():
            r = subprocess.run(_sudo_wrap(['docker', 'exec', TAK_CONTAINER,
                                           'pgrep', '-f', 'takserver-retention.jar']),
                               capture_output=True, text=True, timeout=10)
        else:
            r = subprocess.run(['pgrep', '-f', 'takserver-retention.jar'],
                               capture_output=True, text=True, timeout=6)
        return bool((r.stdout or '').strip())
    except Exception:
        return None


def _cotdb_facts(tak_cfg=None):
    """Read-only fact-gatherer behind Diagnose (W1), the stat tiles (W2) and the
    preflight gates. Never raises: a fact we cannot read comes back as None and
    the caller degrades, because a card that 500s on a full disk is worse than
    one that says 'unknown'."""
    if tak_cfg is None:
        tak_cfg = _get_tak_deployment_config(load_settings())
    f = {
        'db_bytes': None, 'live_rows': None, 'dead_tuples': None,
        'largest_table': None, 'largest_table_bytes': None,
        'data_directory': None, 'fs_free_bytes': None, 'fs_total_bytes': None, 'fs_pct': None,
        'oldest_cot': None, 'newest_cot': None, 'oldest_age_secs': None,
        'retention_hours': None, 'retention_proc_alive': None,
        'guard_timer_enabled': None, 'guard_timer_last': None,
        'repack_timer_enabled': None,
        'fk_dependents': [], 'two_server': tak_cfg.get('mode') == 'two_server',
        'reltuples': None, 'stats_stale': None, 'stats_never_analyzed': None,
        'stats_tables': None,
        'errors': [],
    }

    # Both are cluster-level and fail together if the cluster is unreachable, so
    # merging them costs no robustness and saves an SSH round trip on split boxes.
    ok, out = _cotdb_psql(tak_cfg,
                          "SELECT COALESCE(pg_database_size('cot'), 0), current_setting('data_directory');",
                          db='postgres', timeout=15)
    if ok and '|' in out:
        size_s, _, dd = out.strip().partition('|')
        if size_s.strip().isdigit():
            f['db_bytes'] = int(size_s.strip())
        f['data_directory'] = dd.strip() or None
    elif not ok:
        f['errors'].append(f'db size: {out[:200]}')

    # n_live_tup/n_dead_tup are counters maintained since the last stats reset and
    # are only reconciled with reality by (auto)ANALYZE. On a box where analyze has
    # NEVER run they are not measurements: nuc 2026-08-10 reported n_live_tup=821
    # and n_dead_tup=0 for a cot_router actually holding 80,236 rows. So collect
    # reltuples (the planner's own estimate) and whether anything has ever been
    # analyzed, and let the verdict refuse to reason about bloat when it hasn't.
    ok, out = _cotdb_psql(
        tak_cfg,
        'SELECT COALESCE(SUM(s.n_live_tup), 0), COALESCE(SUM(s.n_dead_tup), 0), '
        'COALESCE(SUM(c.reltuples)::bigint, 0), '
        'COUNT(*) FILTER (WHERE s.last_analyze IS NULL AND s.last_autoanalyze IS NULL), '
        'COUNT(*) '
        'FROM pg_stat_user_tables s JOIN pg_class c ON c.oid = s.relid;', timeout=15)
    if ok:
        parts = [p.strip() for p in out.strip().split('|')]
        if len(parts) == 5 and all(p.lstrip('-').isdigit() for p in parts):
            live, dead, reltup, never, total = (int(p) for p in parts)
            # Prefer whichever row estimate is not obviously stale.
            f['live_rows'] = max(live, reltup)
            f['dead_tuples'] = dead
            f['reltuples'] = reltup
            f['stats_never_analyzed'] = never
            f['stats_tables'] = total
            f['stats_stale'] = bool(never)
    elif out:
        f['errors'].append(f'row stats: {out[:200]}')

    ok, out = _cotdb_psql(
        tak_cfg,
        'SELECT relname, pg_total_relation_size(relid) FROM pg_statio_user_tables '
        'ORDER BY pg_total_relation_size(relid) DESC LIMIT 1;', timeout=20)
    if ok and '|' in out:
        name, _, size = out.strip().partition('|')
        f['largest_table'] = name.strip()
        if size.strip().isdigit():
            f['largest_table_bytes'] = int(size.strip())
    elif out:
        f['errors'].append(f'largest table: {out[:200]}')

    free_b, total_b = _cotdb_df(tak_cfg, f['data_directory'] or '/')
    f['fs_free_bytes'] = free_b
    f['fs_total_bytes'] = total_b
    if total_b:
        f['fs_pct'] = round(free_b * 100.0 / total_b, 1)

    # A seq-scan min() on a 48M-row table would hang the card on exactly the box
    # that needs it, so bound the statement rather than the HTTP request.
    ok, out = _cotdb_psql(
        tak_cfg,
        "SET statement_timeout = '20s'; "
        "SELECT COALESCE(min(servertime)::text, ''), COALESCE(max(servertime)::text, ''), "
        'COALESCE(EXTRACT(EPOCH FROM (now() - min(servertime)))::bigint, 0) FROM cot_router;',
        timeout=30)
    if ok and '|' in out:
        parts = out.strip().split('|')
        if len(parts) >= 3:
            f['oldest_cot'] = parts[0].strip() or None
            f['newest_cot'] = parts[1].strip() or None
            if parts[2].strip().lstrip('-').isdigit():
                f['oldest_age_secs'] = int(parts[2].strip())
    elif out:
        f['errors'].append(f'cot_router age: {out[:200]}')

    ok, out = _cotdb_psql(
        tak_cfg,
        "SELECT conrelid::regclass::text, conname FROM pg_constraint "
        "WHERE confrelid = 'cot_router'::regclass;", timeout=20)
    if ok:
        for line in (out or '').splitlines():
            if '|' in line:
                tbl, _, con = line.partition('|')
                if tbl.strip():
                    f['fk_dependents'].append({'table': tbl.strip(), 'constraint': con.strip()})

    # GH #273: data_feed_cot links feeds to cot_router rows with no foreign key, so
    # retention leaves every link behind and the table only grows (reporter: 71.7M
    # rows / 4.5 GB, all orphans; pg_stat showed n_live_tup = 0 for it). Its size
    # comes from the catalog, never from tuple stats, and "has orphans" is one
    # LIMIT 1 probe down the cot_router_id index — the same anti-join the retention
    # guard's Step 2b deletes with.
    f['feed_cot_bytes'] = None
    f['feed_cot_orphans'] = None
    ok, out = _cotdb_psql(
        tak_cfg,
        "SET statement_timeout = '15s'; "
        "SELECT CASE WHEN to_regclass('public.data_feed_cot') IS NULL THEN '' ELSE "
        "pg_total_relation_size('public.data_feed_cot')::text || '|' || "
        "(SELECT EXISTS (SELECT 1 FROM data_feed_cot d WHERE NOT EXISTS "
        "(SELECT 1 FROM cot_router c WHERE c.id = d.cot_router_id)))::text END;", timeout=25)
    if ok and '|' in out:
        size_s, _, orph = out.strip().splitlines()[-1].partition('|')
        if size_s.strip().isdigit():
            f['feed_cot_bytes'] = int(size_s.strip())
        f['feed_cot_orphans'] = orph.strip() in ('t', 'true')
    elif not ok and out:
        f['errors'].append(f'data_feed_cot: {out[:200]}')
    f['feed_cot_human'] = (_cotdb_fmt_bytes(f['feed_cot_bytes'])
                           if f['feed_cot_bytes'] is not None else '-')

    # GH #273 (smaller note): the same data package uploaded again and again — the
    # reporter's `resource` table held 6 identical copies of a 501 MB GeoTIFF. TAK
    # already stores a hash per row; this only REPORTS repeats. Deleting a package
    # is TAK's call (its Web Admin), not ours, so nothing here removes anything.
    f['dup_packages'] = []
    ok, out = _cotdb_psql(
        tak_cfg,
        "SET statement_timeout = '15s'; "
        "SELECT count(*), COALESCE(sum(pg_column_size(data)), 0)::bigint, "
        "max(replace(replace(COALESCE(name, filename, ''), '|', ' '), E'\\n', ' ')) "
        "FROM resource WHERE hash IS NOT NULL AND hash <> '' "
        "GROUP BY hash HAVING count(*) > 1 "
        "ORDER BY sum(pg_column_size(data)) DESC NULLS LAST LIMIT 5;", timeout=25)
    if ok:
        for line in (out or '').splitlines():
            parts = line.split('|', 2)
            if len(parts) == 3 and parts[0].strip().isdigit() and parts[1].strip().isdigit():
                copies, total = int(parts[0].strip()), int(parts[1].strip())
                f['dup_packages'].append({
                    'name': parts[2].strip()[:120] or '(unnamed)', 'copies': copies,
                    'bytes': total, 'human': _cotdb_fmt_bytes(total),
                    'extra_human': _cotdb_fmt_bytes(total - total // copies)})

    f['retention_hours'] = _cotdb_retention_hours()
    f['retention_proc_alive'] = _cotdb_retention_proc_alive()
    f['guard_timer_enabled'] = _cotdb_systemctl(['is-enabled', 'takretentionguard.timer']) or 'unknown'
    f['repack_timer_enabled'] = _cotdb_systemctl(['is-enabled', 'takdbrepack.timer']) or 'unknown'
    # --timestamp=unix (systemd >= 247, so both Ubuntu 22.04 and RHEL 9) gives an
    # epoch we can turn into "14 min ago" without parsing a localized date string.
    last = _cotdb_systemctl(['show', 'takretentionguard.timer', '-p', 'LastTriggerUSec',
                             '--value', '--timestamp=unix'])
    if not last:
        last = _cotdb_systemctl(['show', 'takretentionguard.timer', '-p', 'LastTriggerUSec', '--value'])
    f['guard_timer_last'] = last if last and last not in ('n/a', '0') else None
    f['guard_timer_last_secs'] = None
    f['guard_timer_last_human'] = None
    if last.startswith('@') and last[1:].isdigit() and last != '@0':
        f['guard_timer_last_secs'] = max(0, int(time.time()) - int(last[1:]))
        f['guard_timer_last_human'] = _cotdb_fmt_age(f['guard_timer_last_secs']) + ' ago'

    # Formatted once, here, so the tiles and the verdict text cannot drift apart.
    f['db_human'] = _cotdb_fmt_bytes(f['db_bytes']) if f['db_bytes'] is not None else '-'
    f['fs_free_human'] = _cotdb_fmt_bytes(f['fs_free_bytes'])
    f['largest_table_human'] = (_cotdb_fmt_bytes(f['largest_table_bytes'])
                                if f['largest_table_bytes'] is not None else '-')
    f['oldest_age_human'] = _cotdb_fmt_age(f['oldest_age_secs'])
    f['compact_needed_bytes'] = (int(f['largest_table_bytes'] * _COTDB_COMPACT_HEADROOM)
                                 if f['largest_table_bytes'] else None)
    f['compact_needed_human'] = (_cotdb_fmt_bytes(f['compact_needed_bytes'])
                                 if f['compact_needed_bytes'] else '-')
    # ops #227: on a box with missions the oldest row is usually mission content that
    # retention keeps on purpose, and the card said "Retention is stalled" for
    # exactly that. Judge it on the oldest row retention WOULD delete. The scan
    # only covers rows already past the stall line, which on a healthy box are just
    # the kept ones, so it stays small.
    stall_secs = int(f['retention_hours']) * 3600 * 2 if f['retention_hours'] else 0
    f['oldest_expirable_age_secs'] = f['oldest_age_secs']
    f['old_rows_kept'] = False
    if stall_secs and f['oldest_age_secs'] and f['oldest_age_secs'] > stall_secs:
        ok, out = _cotdb_psql(
            tak_cfg,
            "SET statement_timeout = '20s'; "
            "SELECT COALESCE(EXTRACT(EPOCH FROM (now() - min(cr.servertime)))::bigint, 0) "
            f"FROM cot_router cr WHERE cr.servertime < now() - interval '{stall_secs} seconds' "
            f"AND {_COTDB_EXPIRABLE_WHERE};", timeout=30)
        last = out.strip().splitlines()[-1].strip() if ok and out.strip() else ''
        if last.isdigit():
            f['oldest_expirable_age_secs'] = int(last)
            f['old_rows_kept'] = not int(last)
        else:
            # Unknown is not "fine": keep the whole-table answer so a real stall
            # still raises the alarm, and record why the card could not tell.
            f['errors'].append(f'retention-eligible age: {(out or "no answer")[:200]}')
    f['oldest_expirable_age_human'] = _cotdb_fmt_age(f['oldest_expirable_age_secs'])
    f['retention_stalled'] = bool(stall_secs and f['oldest_expirable_age_secs']
                                  and f['oldest_expirable_age_secs'] > stall_secs)
    f['guard_timer_ok'] = (f['guard_timer_enabled'] or '') in ('enabled', 'enabled-runtime', 'static')
    return f


def _cotdb_space_refusal(facts):
    """Shared W3/W4 preflight: VACUUM FULL and pg_repack BOTH rewrite each table
    into a new file before dropping the old one, so both need free space ~= the
    largest table. Returns a refusal dict when there is not enough, else None."""
    need = facts.get('compact_needed_bytes')
    free = facts.get('fs_free_bytes')
    if not need or free is None:
        return None            # unknown -> do not block; the DB will report
    if free >= need:
        return None
    msg = (f"Cannot compact - VACUUM FULL and Online Compact need about "
           f"{facts['compact_needed_human']} free (the size of the largest table, "
           f"{facts.get('largest_table') or 'unknown'}) and this filesystem has "
           f"{facts['fs_free_human']}. Free disk first.")
    layout = {}
    try:
        layout = _detect_disk_layout()
    except Exception:
        layout = {}
    if layout.get('mode') and layout.get('mode') != 'ok' and layout.get('reclaimable_gb'):
        msg += (f" {layout['reclaimable_gb']} GB is reclaimable on this box - "
                "see Reclaim disk on the Console page.")
    return {'error': msg, 'verdict': 'no_disk',
            'needed_bytes': need, 'free_bytes': free,
            'recommend': ['purge'] + (['reclaim_disk'] if layout.get('mode', 'ok') != 'ok' else [])}


def _cotdb_verdict(facts):
    """The W1 decision tree plus an honesty pass over its recommendation.

    Purge Old CoT deletes from cot_router ONLY (the fixed _COTDB_TABLES
    allowlist). On a box whose bulk sits in a different table it would reclaim
    almost nothing, so recommending it without saying that would be the very
    failure this card exists to remove. Seen on test8, 2026-08-10: 5.7 GB
    database of which data_feed_cot is 5.6 GB, verdict retention_stalled,
    recommendation Purge."""
    verdict, headline, detail, recommend = _cotdb_verdict_tree(facts)
    lt = facts.get('largest_table')
    if facts.get('feed_cot_orphans'):
        # GH #273: test8's 5.6 GB data_feed_cot (above) was this — links to CoT rows
        # retention had already deleted. Purge cannot reach it; the retention guard can.
        detail += (f" data_feed_cot holds {facts.get('feed_cot_human', '-')} including links to CoT "
                   "rows that no longer exist. Guard Dog's retention guard deletes those every "
                   "15 minutes in batches; Run Retention Now starts it immediately. PostgreSQL reuses "
                   "the freed space once autovacuum has run; Online Compact gives it back to the disk.")
        recommend = list(recommend or [])
        if 'retention_run' not in recommend:
            recommend.insert(0, 'retention_run')
        if lt == 'data_feed_cot':
            return verdict, headline, detail, recommend
    if 'purge' in (recommend or []):
        if lt and lt not in _COTDB_TABLES:
            detail += (f" NOTE: the largest table here is {lt} "
                       f"({facts.get('largest_table_human', '-')}), which Purge Old CoT does "
                       f"NOT touch - it only deletes from {_COTDB_TABLES[0]}. Purging will not "
                       f"reclaim that space.")
    return verdict, headline, detail, recommend


def _cotdb_verdict_tree(facts):
    """The W1 decision tree, in order. Returns (verdict, headline, detail, recommend)."""
    free = facts.get('fs_free_bytes')
    need = facts.get('compact_needed_bytes')
    dead = facts.get('dead_tuples')
    rh = facts.get('retention_hours')

    # 1. No room to compact. Checked first: it is the only case where the button
    #    the card offers is arithmetically impossible.
    if need and free is not None and free < need:
        ref = _cotdb_space_refusal(facts) or {}
        return ('no_disk', 'Not enough free disk to compact', ref.get('error', ''),
                ref.get('recommend') or ['purge'])

    # 2. Retention is not deleting. The space is live rows; compacting frees nothing.
    if facts.get('retention_stalled'):
        causes = []
        if facts.get('retention_proc_alive') is False:
            causes.append("TAK Server's retention process is not running")
        if not facts.get('guard_timer_ok'):
            causes.append(f"the Guard Dog retention timer is {facts.get('guard_timer_enabled') or 'unknown'}")
        if not causes:
            causes.append('retention is configured but has not been deleting')
        detail = (f"Retention is set to {rh} h but the oldest CoT row it should have deleted is "
                  f"{facts.get('oldest_expirable_age_human') or facts['oldest_age_human']} old - "
                  f"retention is not deleting. Compacting will not help; the space is live data. "
                  f"Cause: {'; '.join(causes)}.")
        return ('retention_stalled', 'Retention is stalled', detail, ['retention_run', 'purge'])

    # Only advise on a remedy when there is something to remedy. A small database
    # with plenty of free disk has no problem for either branch below to solve.
    pressure = bool(
        (facts.get('db_bytes') or 0) >= _COTDB_PRESSURE_DB_BYTES
        or (facts.get('fs_pct') is not None and facts['fs_pct'] < _COTDB_PRESSURE_FREE_PCT)
        or facts.get('retention_stalled')
    )

    # 2b. No retention policy configured AT ALL. Distinct from "stalled": nothing
    #     is broken, nothing was ever set up, and the fix is a different screen.
    #     This is not a footnote on a healthy verdict — with no TTL, TAK Server
    #     never deletes a CoT row, so the database grows until the filesystem
    #     fills, at which point compacting is impossible too. It is the 2026-08-10
    #     failure in slow motion, and it is silent right up until the disk is gone.
    if not rh:
        detail = ("No CoT retention policy is configured, so TAK Server never deletes old "
                  "position reports and this database grows for as long as the server runs. "
                  "VACUUM and Online Compact cannot help - they reclaim space from DELETED "
                  "rows, and nothing is being deleted. Set a CoT (non-chat) retention period "
                  "in TAK Server's own Web Admin at :8443 > Data Retention Policies; infra-TAK "
                  "reads that setting but deliberately does not write it. Guard Dog's "
                  "15-minute retention guard then enforces whatever you set.")
        if facts.get('oldest_age_secs'):
            detail += f" Oldest row here is already {facts.get('oldest_age_human')} old."
        return ('no_retention', 'No retention policy - this database grows forever',
                detail, [])

    # 2c. The dead-tuple count is the input to both remaining branches. If ANALYZE
    #     has never run, that count is not a measurement and "nothing to reclaim"
    #     would be an unearned claim — the opposite mistake to recommending a
    #     purge on a healthy box, and equally wrong. Say so, and point at the one
    #     button that fixes it (VACUUM ANALYZE refreshes the statistics).
    if pressure and facts.get('stats_stale'):
        detail = (f"{facts.get('stats_never_analyzed')} of {facts.get('stats_tables')} tables have "
                  "never been analyzed, so the dead-tuple count is not trustworthy and this card "
                  "cannot tell reclaimable bloat from live data. Press Optimize Tables (VACUUM "
                  "ANALYZE) - it is safe while TAK Server is running - then press Diagnose again.")
        return ('stats_stale', 'Statistics are stale - cannot judge bloat yet',
                detail, ['vacuum_analyze'])

    # 3. Nothing for VACUUM to reclaim. This is the reporter's actual case.
    if pressure and dead is not None and dead < _COTDB_BLOAT_FLOOR:
        detail = (f"Only {dead:,} dead tuples - there is almost nothing for VACUUM to reclaim. "
                  f"This database is {facts.get('db_human', '-')} of live rows. "
                  "Deleting rows (Purge Old CoT) is what frees space here, not compacting.")
        return ('no_bloat', 'Nothing to reclaim - this is live data', detail, ['purge'])

    # 4. Real bloat, and room to compact it.
    if dead is not None and dead > _COTDB_BLOAT_CEIL:
        detail = (f"{dead:,} dead tuples - reclaimable. Online Compact runs without an exclusive "
                  "lock, so TAK Server can stay up; Compact Database is faster but needs TAK stopped.")
        return ('bloat', 'Reclaimable bloat found', detail, ['repack', 'vacuum_full'])

    # Keep this consistent with the tiles: if the stats have never been collected,
    # do not quote a dead-tuple count here that the tile is reporting as unknown.
    dead_phrase = ('dead tuples unknown (statistics have never been collected on this database)'
                   if facts.get('stats_stale')
                   else f"{(dead if dead is not None else 0):,} dead tuples")
    detail = (f"{dead_phrase}, "
              f"{facts.get('fs_free_human', '-')} free on the database filesystem, oldest CoT row "
              f"{facts.get('oldest_age_human', '-')} old"
              + (" (mission content or GeoChat, which retention keeps on purpose)"
                 if facts.get('old_rows_kept') else '')
              + ". Nothing to do.")
    # (No "TTL not set" note here any more — that case returns its own red
    #  no_retention verdict above instead of riding along on a green one.)
    return ('healthy', 'Database looks healthy', detail, [])


@app.route('/api/guarddog/cotdb/diagnose')
@login_required
def guarddog_cotdb_diagnose():
    """W1 - read-only CoT database diagnosis. Safe to spam: no writes, no locks.

    Answers the question the card could not: WHICH failure am I in, and which
    button actually helps? Also feeds the W2 stat tiles from the same payload so
    one fetch drives the whole card."""
    if not os.path.exists('/opt/tak'):
        return jsonify({'success': False, 'error': 'TAK Server not installed'}), 400
    try:
        tak_cfg = _get_tak_deployment_config(load_settings())
        facts = _cotdb_facts(tak_cfg)
        verdict, headline, detail, recommend = _cotdb_verdict(facts)
        return jsonify({'success': True, 'verdict': verdict, 'headline': headline,
                        'detail': detail, 'recommend': recommend, 'facts': facts})
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)[:300]}), 500


# Guard Dog units this card can drive, and the log tag each one writes. A FIXED
# map — the request supplies a job key, never a unit name.
_COTDB_JOBS = {
    'retention': {'unit': 'takretentionguard.service', 'tag': 'RETENTION-GUARD:'},
    'repack': {'unit': 'takdbrepack.service', 'tag': 'DB-REPACK:'},
}
_COTDB_GUARD_LOG = '/var/log/takguard/restarts.log'


def _cotdb_log_tail(tag, limit=40):
    """Last `limit` Guard Dog log lines carrying `tag`. The scripts already log
    their row counts there — surfacing them beats inventing a second channel."""
    text = ''
    try:
        with open(_COTDB_GUARD_LOG, 'r', errors='replace') as fh:
            text = fh.read()
    except Exception:
        try:
            text = _read_priv(_COTDB_GUARD_LOG)
        except Exception:
            return []
    return [l for l in (text or '').splitlines() if tag in l][-limit:]


def _cotdb_heal_timers():
    """Re-arm the Guard Dog DB timers if they are not enabled.

    v10.1.1 (F8): run_guarddog_deploy WROTE takretentionguard.timer but never
    added it to the enable list, so on every box installed before that fix it has
    sat loaded-but-disabled and has never fired once — our own test6 bloated
    cot_router to 53 GB from exactly this. The startup migration re-arms it, but
    only on Update Now; this makes the same remedy reachable from the page.
    Returns the list of units that were enabled."""
    healed = []
    for unit in ('takretentionguard.timer', 'takdbrepack.timer'):
        if not os.path.exists(f'/etc/systemd/system/{unit}'):
            continue
        if _cotdb_systemctl(['is-enabled', unit]) in ('enabled', 'enabled-runtime', 'static'):
            continue
        try:
            r = subprocess.run(_sudo_wrap(['systemctl', 'enable', '--now', unit]),
                               capture_output=True, text=True, timeout=45)
            if r.returncode == 0:
                healed.append(unit)
        except Exception:
            pass
    return healed


@app.route('/api/guarddog/cotdb/retention-run', methods=['POST'])
@login_required
def guarddog_cotdb_retention_run():
    """W6 - run the Guard Dog retention guard NOW, and re-arm its timer.

    The guard performs the SAFE automatic batched delete; it is what should have
    kept the reporter's box from ever filling. Started with --no-block because
    takretentionguard.service is Type=oneshot with TimeoutStartSec=1800 - a
    blocking start would hold a gunicorn thread (1 worker / 4 threads) for up to
    half an hour. The client polls /api/guarddog/cotdb/job-status."""
    if not os.path.exists('/etc/systemd/system/takretentionguard.service'):
        return jsonify({'success': False,
                        'error': 'Guard Dog retention guard is not installed on this box. '
                                 'Deploy or update Guard Dog first.'}), 400
    audit('cotdb:retention-run', 'start requested')
    healed = _cotdb_heal_timers()
    try:
        r = subprocess.run(_sudo_wrap(['systemctl', 'start', '--no-block',
                                       'takretentionguard.service']),
                           capture_output=True, text=True, timeout=45)
    except Exception as e:
        audit('cotdb:retention-run', f'start failed: {str(e)[:120]}')
        return jsonify({'success': False, 'error': f'Could not start retention guard: {str(e)[:200]}'}), 500
    if r.returncode != 0:
        err = ((r.stderr or '') + (r.stdout or '')).strip()[:300] or f'Exit code {r.returncode}'
        audit('cotdb:retention-run', f'start failed: {err[:120]}')
        return jsonify({'success': False, 'error': err}), 400
    msg = 'Retention guard started.'
    if healed:
        msg += (' Re-enabled ' + ', '.join(healed) +
                ' - the timer was not armed, so the automatic 15-minute safety net had never run.')
    audit('cotdb:retention-run', f'started; healed={",".join(healed) or "none"}')
    return jsonify({'success': True, 'job': 'retention', 'healed_timers': healed, 'message': msg})


@app.route('/api/guarddog/cotdb/repack', methods=['POST'])
@login_required
def guarddog_cotdb_repack():
    """W4 - Online Compact. Reclaims bloat WITHOUT an exclusive lock, so unlike
    VACUUM FULL it does not require stopping TAK Server.

    Drives the existing, already-audited takdbrepack.service through the
    already-allowed `systemctl start` verb. pg_repack is deliberately NOT in the
    broker's _PG_AS_POSTGRES allowlist, so running it through _pg_exec() would be
    DENIED - driving the unit is what makes this work on the non-root fleet with
    no new broker privilege and no new CJIS review surface."""
    if not os.path.exists('/etc/systemd/system/takdbrepack.service'):
        return jsonify({'success': False,
                        'error': 'Guard Dog online repack is not installed on this box. '
                                 'Deploy or update Guard Dog first.'}), 400
    tak_cfg = _get_tak_deployment_config(load_settings())
    # pg_repack builds a full copy of each table before swapping it in, exactly
    # like VACUUM FULL - so it gets the same free-space refusal (W3).
    facts = _cotdb_facts(tak_cfg)
    refusal = _cotdb_space_refusal(facts)
    if refusal:
        return jsonify(dict(refusal, success=False)), 400
    audit('cotdb:repack', 'start requested')
    # W4c: tell the script this is an operator-initiated run so it bypasses the
    # 10 GB size threshold that exists for the weekly timer. Without this the
    # button silently no-ops on any box with a small CoT database — a button that
    # decides not to do what you asked is the failure this release is about.
    try:
        _write_priv('/var/lib/takguard/repack_force', '1')
    except Exception as e:
        # Non-fatal: the repack still runs, it just honours the size threshold.
        print(f'cotdb repack: could not set force flag ({e})', flush=True)
    # Clear any previous failure so job-status reports THIS run's outcome.
    try:
        subprocess.run(_sudo_wrap(['systemctl', 'reset-failed', 'takdbrepack.service']),
                       capture_output=True, text=True, timeout=20)
    except Exception:
        pass
    try:
        r = subprocess.run(_sudo_wrap(['systemctl', 'start', '--no-block', 'takdbrepack.service']),
                           capture_output=True, text=True, timeout=45)
    except Exception as e:
        audit('cotdb:repack', f'start failed: {str(e)[:120]}')
        return jsonify({'success': False, 'error': f'Could not start online repack: {str(e)[:200]}'}), 500
    if r.returncode != 0:
        err = ((r.stderr or '') + (r.stdout or '')).strip()[:300] or f'Exit code {r.returncode}'
        audit('cotdb:repack', f'start failed: {err[:120]}')
        return jsonify({'success': False, 'error': err}), 400
    audit('cotdb:repack', f"started; db={facts.get('db_human')} dead={facts.get('dead_tuples')}")
    return jsonify({'success': True, 'job': 'repack',
                    'message': 'Online compact started. TAK Server can stay up; '
                               'pg_repack works without an exclusive lock.'})


@app.route('/api/guarddog/cotdb/job-status')
@login_required
def guarddog_cotdb_job_status():
    """Poll a Guard Dog DB job (retention guard / online repack): unit state plus
    the tail of the lines that job writes to the Guard Dog log."""
    spec = _COTDB_JOBS.get((request.args.get('job') or '').strip())
    if not spec:
        return jsonify({'success': False, 'error': 'Unknown job.'}), 400
    state = _cotdb_systemctl(['is-active', spec['unit']]) or 'unknown'
    return jsonify({'success': True, 'state': state,
                    'active': state in ('active', 'activating', 'reloading'),
                    'failed': state == 'failed',
                    'lines': _cotdb_log_tail(spec['tag'])})


# --------------------------------------------------------------------------
# W5 — Purge Old CoT (DESTRUCTIVE)
# --------------------------------------------------------------------------
# The only action that recovers a box at 441 MB free. Two modes:
#   age — batched ctid DELETE by cutoff. WAL-light, runs while TAK is up, but
#         needs headroom for the WAL it writes.
#   all — TRUNCATE. Drops the old relfilenode instead of rewriting it, so it is
#         near-instant and needs essentially no free space. The escape hatch.
_COTDB_PURGE_BATCH = 50000              # same chunk the retention guard proved
_COTDB_PURGE_MAX_BATCHES = 200          # 50k x 200 = 10M rows per press
_COTDB_PURGE_SLEEP = 2
_COTDB_PURGE_WAL_FLOOR = 2 * 1024 ** 3  # a multi-million-row DELETE writes GBs of WAL
_COTDB_PURGE_MAX_HOURS = 8760           # 1 year

_cotdb_purge_status = {'running': False, 'mode': None, 'started': None, 'hours': None,
                       'deleted': 0, 'batches': 0, 'capped': False,
                       'result': None, 'error': None}


def _cotdb_cascade_set(tak_cfg):
    """Every table a `TRUNCATE cot_router CASCADE` would reach, transitively.

    The plain fk_dependents probe finds DIRECT dependents only, but CASCADE
    follows the chain — so listing only the direct ones would show the operator a
    smaller blast radius than the statement actually has. Confirmation is
    worthless if it confirms the wrong set."""
    sql = ("WITH RECURSIVE d AS ("
           "  SELECT conrelid FROM pg_constraint WHERE confrelid = 'cot_router'::regclass "
           "  UNION "
           "  SELECT c.conrelid FROM pg_constraint c JOIN d ON c.confrelid = d.conrelid"
           ") SELECT DISTINCT conrelid::regclass::text FROM d;")
    ok, out = _cotdb_psql(tak_cfg, sql, timeout=20)
    if not ok:
        return None                    # unknown -> caller must refuse, not guess
    return sorted({l.strip() for l in (out or '').splitlines() if l.strip()})


def _run_cotdb_purge_background(hours, tak_cfg):
    """Batched delete by cutoff, using the ctid pattern proven in
    tak-retention-guard.sh Step 5 (small chunks, sleep between, hard iteration
    cap) so PostgreSQL never attempts one massive transaction."""
    table = _COTDB_TABLES[0]
    # `hours` is an int() already range-checked by the caller; the table name is a
    # module constant. No request STRING ever reaches this statement.
    sql = (f"DELETE FROM {table} WHERE ctid IN (SELECT ctid FROM {table} "
           f"WHERE servertime < now() - interval '{hours} hours' "
           f"LIMIT {_COTDB_PURGE_BATCH});")
    total = 0
    batches = 0
    try:
        while batches < _COTDB_PURGE_MAX_BATCHES:
            ok, out = _cotdb_psql(tak_cfg, sql, timeout=600)
            if not ok:
                _cotdb_purge_status.update({'running': False, 'error': (out or 'DELETE failed')[:400],
                                            'deleted': total, 'batches': batches})
                audit('cotdb:purge', f'mode=age hours={hours} rows={total} FAILED: {(out or "")[:120]}',
                      force=True)
                return
            m = re.search(r'DELETE\s+(\d+)', out or '')
            n = int(m.group(1)) if m else 0
            total += n
            batches += 1
            _cotdb_purge_status.update({'deleted': total, 'batches': batches})
            if n < _COTDB_PURGE_BATCH:
                break
            time.sleep(_COTDB_PURGE_SLEEP)
        else:
            _cotdb_purge_status['capped'] = True
        msg = f'Deleted {total:,} rows older than {hours} h in {batches} batches.'
        if _cotdb_purge_status['capped']:
            msg += (f' Stopped at the {_COTDB_PURGE_MAX_BATCHES}-batch safety cap - '
                    'press Purge Old CoT again to continue.')
        msg += (' DELETE does not shrink the database file: follow with Online Compact '
                'to hand the space back to the filesystem.')
        _cotdb_purge_status.update({'running': False, 'result': msg, 'deleted': total,
                                    'batches': batches})
        audit('cotdb:purge', f'mode=age hours={hours} rows={total} batches={batches}', force=True)
    except Exception as e:
        _cotdb_purge_status.update({'running': False, 'error': str(e)[:300], 'deleted': total})
        audit('cotdb:purge', f'mode=age hours={hours} rows={total} EXCEPTION: {str(e)[:120]}',
              force=True)


@app.route('/api/guarddog/cotdb/purge', methods=['POST'])
@login_required
def guarddog_cotdb_purge():
    """W5 - DESTRUCTIVE. Delete CoT position history to recover a full box.

    Authorization follows the fold_home precedent exactly: @login_required, PLUS
    a re-verified console password, PLUS a literal confirmation string the caller
    must echo. Destructive CoT deletion stays operator-initiated - there is no
    automatic or scheduled path into this route."""
    if not os.path.exists('/opt/tak'):
        return jsonify({'success': False, 'error': 'TAK Server not installed'}), 400
    data = request.get_json(silent=True) or {}
    mode = (data.get('mode') or '').strip()
    if mode not in ('age', 'all'):
        return jsonify({'success': False, 'error': 'mode must be "age" or "all".'}), 400
    if _cotdb_purge_status['running']:
        return jsonify({'success': False, 'error': 'A purge is already running.',
                        'status': 'running'}), 409

    # The one-copy admin-password gate (modules/__init__.py, allowlisted in
    # smoke.py AUTH_FUNCS) rather than a 19th inline check_password_hash.
    if mod_registry._check_admin_password({'load_auth': load_auth,
                                           'verify_password': verify_password}, data):
        return jsonify({'success': False, 'error': 'Incorrect console password.',
                        'need_password': True}), 403

    table = _COTDB_TABLES[0]
    confirm = (data.get('confirm') or '').strip()
    hours = None
    if mode == 'age':
        # HARD int coercion + range check. A request STRING must never reach the
        # statement — this is the one place a request value influences SQL at all.
        try:
            hours = int(str(data.get('hours', '')).strip())
        except Exception:
            return jsonify({'success': False,
                            'error': f'hours must be a whole number between 1 and '
                                     f'{_COTDB_PURGE_MAX_HOURS}.'}), 400
        if not (1 <= hours <= _COTDB_PURGE_MAX_HOURS):
            return jsonify({'success': False,
                            'error': f'hours must be between 1 and {_COTDB_PURGE_MAX_HOURS}.'}), 400
        if confirm != str(hours):
            return jsonify({'success': False,
                            'error': f"confirm must be exactly '{hours}' (the cutoff in hours).",
                            'expected_confirm': str(hours)}), 400
    else:
        if confirm != table:
            return jsonify({'success': False,
                            'error': f"confirm must be exactly '{table}'.",
                            'expected_confirm': table}), 400

    audit('cotdb:purge', f'mode={mode} hours={hours} requested', force=True)
    tak_cfg = _get_tak_deployment_config(load_settings())
    facts = _cotdb_facts(tak_cfg)

    if mode == 'age':
        free = facts.get('fs_free_bytes')
        if free is not None and free < _COTDB_PURGE_WAL_FLOOR:
            # A multi-million-row DELETE writes GBs of WAL onto this same
            # filesystem and can drive PostgreSQL to PANIC / read-only. Mode
            # `all` exists precisely for this situation.
            return jsonify({
                'success': False, 'verdict': 'no_wal_room',
                'free_bytes': free, 'needed_bytes': _COTDB_PURGE_WAL_FLOOR,
                'error': (f"Only {facts.get('fs_free_human')} free - a batched DELETE writes "
                          "gigabytes of write-ahead log onto this same filesystem and could "
                          "drive PostgreSQL read-only. At least 2 GB free is required. Use "
                          "Purge everything (TRUNCATE), which needs essentially no free space."),
            }), 400
        _cotdb_purge_status.update({'running': True, 'mode': 'age', 'hours': hours,
                                    'started': datetime.now().isoformat(), 'deleted': 0,
                                    'batches': 0, 'capped': False, 'result': None, 'error': None})
        threading.Thread(target=_run_cotdb_purge_background, args=(hours, tak_cfg),
                         daemon=True).start()
        return jsonify({'success': True, 'status': 'started', 'mode': 'age', 'hours': hours})

    # ---- mode 'all': TRUNCATE ------------------------------------------------
    cascade = False
    deps = facts.get('fk_dependents') or []
    if deps:
        full_set = _cotdb_cascade_set(tak_cfg)
        if full_set is None:
            return jsonify({'success': False, 'fk_dependents': deps,
                            'error': f'{table} has foreign-key dependents but the full CASCADE '
                                     'set could not be read. Refusing to TRUNCATE blind.'}), 400
        want = data.get('cascade_tables')
        want_set = sorted({str(t).strip() for t in want}) if isinstance(want, list) else None
        if want_set != full_set:
            return jsonify({
                'success': False, 'fk_dependents': deps, 'cascade_tables': full_set,
                'error': (f'{table} has foreign-key dependents, so TRUNCATE would CASCADE into: '
                          + ', '.join(full_set) + '. Those tables would be emptied too. Confirm '
                          'the exact list to proceed, or cancel and use Purge by age instead.'),
            }), 400
        cascade = True

    # Bounded lock wait: TRUNCATE needs ACCESS EXCLUSIVE, and TAK Server holds the
    # table while it is up. Report that plainly instead of hanging the request.
    sql = f"SET lock_timeout = '10s'; TRUNCATE TABLE {table}" + (' CASCADE;' if cascade else ';')
    before = facts.get('db_bytes')
    ok, out = _cotdb_psql(tak_cfg, sql, timeout=120)
    if not ok:
        low = (out or '').lower()
        if 'lock timeout' in low or 'canceling statement' in low:
            audit('cotdb:purge', 'mode=all BLOCKED by lock', force=True)
            return jsonify({'success': False, 'verdict': 'locked',
                            'error': 'TAK Server is holding the table - stop TAK Server and retry.'}), 409
        audit('cotdb:purge', f'mode=all FAILED: {(out or "")[:120]}', force=True)
        return jsonify({'success': False, 'error': (out or 'TRUNCATE failed')[:400]}), 400

    after = _cotdb_facts(tak_cfg)
    freed = None
    if before is not None and after.get('db_bytes') is not None:
        freed = max(0, before - after['db_bytes'])
    audit('cotdb:purge',
          f"mode=all cascade={cascade} before={before} after={after.get('db_bytes')}", force=True)
    msg = f'{table} truncated.'
    if cascade:
        msg += ' CASCADE also emptied: ' + ', '.join(full_set) + '.'
    if freed:
        msg += f' Reclaimed {_cotdb_fmt_bytes(freed)} immediately - TRUNCATE drops the old files.'
    return jsonify({'success': True, 'mode': 'all', 'message': msg,
                    'freed_bytes': freed, 'facts': after})


@app.route('/api/guarddog/cotdb/purge/status')
@login_required
def guarddog_cotdb_purge_status():
    """Poll the batched (mode=age) purge."""
    return jsonify({'success': True, **_cotdb_purge_status})


# ── Leftover PostgreSQL 15 cluster after the TAK 5.8 migration (GH #273) ─────────
# upgrade-db.sh's pg_upgrade runs in copy mode, so the 15 cluster survives, stopped, as
# the rollback — and nothing ever removed it (reporter: 15 GB, untouched for 10 days,
# next to a 14 GB PostgreSQL 18; test6: 3 GB). The card reports it and offers a
# password-gated Remove once 18 is the live database. Nothing is removed automatically:
# it is the only way back from a bad migration, so dropping it is the operator's call.
#
# Local (native) boxes go through the broker's fixed-shape `pg_old_cluster` op, which
# re-checks every precondition itself. A two-server Server One runs the same checks in
# the fixed script below over SSH. No request value reaches either: the action is one
# of two literals, the majors and paths are constants.
_PG_OLD_CLUSTER_MAJOR = 15
_PG_OLD_CLUSTER_SH = r'''set -u
ACTION="__ACTION__"
pgdir() {
  for d in "/var/lib/postgresql/$1/main" "/var/lib/pgsql/$1/data"; do
    if [ -d "$d" ] && [ ! -L "$d" ] && [ "$(cat "$d/PG_VERSION" 2>/dev/null)" = "$1" ]; then
      echo "$d"; return 0
    fi
  done
  return 1
}
OLD=$(pgdir 15) || OLD=""
if [ -z "$OLD" ]; then
  echo "found=0"
  [ "$ACTION" = "drop" ] && { echo "error=no PostgreSQL 15 cluster found"; exit 1; }
  exit 0
fi
NEW=$(pgdir 18) || NEW=""
FAM=rhel; case "$OLD" in /var/lib/postgresql/*) FAM=debian ;; esac
RUN=0; [ -e "$OLD/postmaster.pid" ] && RUN=1
NEWRUN=0; [ -n "$NEW" ] && [ -e "$NEW/postmaster.pid" ] && NEWRUN=1
KB=$(du -sk "$OLD" 2>/dev/null | awk '{print $1}')
BYTES=$(( ${KB:-0} * 1024 ))
echo "found=1"; echo "family=$FAM"; echo "path=$OLD"; echo "running=$RUN"
echo "new_path=$NEW"; echo "new_running=$NEWRUN"; echo "bytes=${BYTES:-0}"
[ "$ACTION" = "drop" ] || exit 0
[ "$RUN" = "1" ] && { echo "error=the PostgreSQL 15 cluster is running, not removing it"; exit 1; }
[ "$NEWRUN" = "1" ] || { echo "error=no running PostgreSQL 18 cluster, the 15 cluster may still be the only database"; exit 1; }
if [ "$FAM" = "debian" ] && command -v pg_dropcluster >/dev/null 2>&1; then
  pg_dropcluster 15 main >/dev/null 2>&1
else
  systemctl disable postgresql-15 >/dev/null 2>&1
fi
[ -d "$OLD" ] && [ ! -L "$OLD" ] && rm -rf "$OLD"
if [ -e "$OLD" ]; then echo "removed=0"; echo "error=$OLD is still present"; exit 1; fi
echo "removed=1"; echo "freed_bytes=${BYTES:-0}"
'''


def _pg_old_cluster_call(action, tak_cfg):
    """Ask (action='inspect') or remove (action='drop') the leftover 15 cluster where
    TAK's database lives. Returns the broker op's dict shape; never raises."""
    if action not in ('inspect', 'drop'):
        return {'ok': False, 'error': 'bad action'}
    mode = (tak_cfg or {}).get('mode') or ''
    if mode == 'two_server':
        s1 = tak_cfg.get('server_one') or {}
        if not (s1.get('host') or '').strip():
            return {'ok': False, 'error': 'Server One host not configured'}
        script = _PG_OLD_CLUSTER_SH.replace('__ACTION__', action)
        ok, out = _ssh_probe(s1, 'cd / && sudo -n bash -c ' + shlex.quote(script),
                             timeout=1800 if action == 'drop' else 120)
        res = {'ok': ok, 'where': 'Server One (%s)' % s1.get('host')}
        for line in (out or '').splitlines():
            k, sep, v = line.strip().partition('=')
            if not sep or k not in ('found', 'family', 'path', 'running', 'new_path',
                                    'new_running', 'bytes', 'removed', 'freed_bytes', 'error'):
                continue
            if k in ('found', 'running', 'new_running', 'removed'):
                res[k] = v.strip() == '1'
            elif k in ('bytes', 'freed_bytes'):
                res[k] = int(v) if v.strip().isdigit() else 0
            else:
                res[k] = v.strip()
        if 'found' not in res:
            res['ok'] = False
            res.setdefault('error', (out or 'no answer from Server One')[:300])
        return res
    if mode == 'external_db' or _tak_is_container():
        # A managed database has no cluster of ours on disk; container TAK keeps its
        # PostgreSQL 15 data in a docker volume the 5.8 migration names itself.
        return {'ok': True, 'found': False, 'not_applicable': True}
    req = {'op': 'pg_old_cluster', 'action': action}
    try:
        if _broker_should_route() and _broker_available():
            res = _broker_request(req, timeout=1800 if action == 'drop' else 300)
        elif os.getuid() == 0:
            m = _broker_module()
            m._check_pg_old_cluster(req)
            res = m._do_pg_old_cluster(req)
        else:
            return {'ok': False, 'error': 'privilege broker unavailable'}
    except Exception as e:
        return {'ok': False, 'error': str(e)[:300]}
    res['where'] = 'this server'
    return res


def _pg_old_cluster_state(tak_cfg):
    """inspect + the console's own "is PostgreSQL 18 really the live database" check.
    `removable` is what gates the card's Remove button."""
    res = _pg_old_cluster_call('inspect', tak_cfg)
    if not res.get('found'):
        return res
    ok, out = _cotdb_psql(tak_cfg,
                          "SELECT current_setting('server_version_num')::int / 10000, "
                          "current_setting('data_directory'), "
                          "(SELECT count(*) FROM pg_database WHERE datname = 'cot');",
                          db='postgres', timeout=20)
    parts = out.strip().split('|') if ok else []
    live_major = int(parts[0]) if len(parts) == 3 and parts[0].strip().isdigit() else None
    live_dir = parts[1].strip() if len(parts) == 3 else ''
    has_cot = len(parts) == 3 and parts[2].strip() not in ('', '0')
    res['live_major'] = live_major
    res['bytes_human'] = _cotdb_fmt_bytes(res.get('bytes') or 0)
    why = None
    if res.get('running'):
        why = 'The PostgreSQL %d cluster is still running.' % _PG_OLD_CLUSTER_MAJOR
    elif live_major is None or not has_cot:
        why = 'Could not confirm that the live database is healthy, so removal is not offered.'
    elif live_major <= _PG_OLD_CLUSTER_MAJOR or live_dir == res.get('path'):
        why = 'PostgreSQL %d is still the live database.' % _PG_OLD_CLUSTER_MAJOR
    elif not res.get('new_running'):
        why = 'The PostgreSQL %d cluster is not running.' % live_major
    res['removable'] = why is None
    res['not_removable_reason'] = why
    return res


@app.route('/api/guarddog/pg-old-cluster')
@login_required
def guarddog_pg_old_cluster():
    """Read-only: is a stopped PostgreSQL 15 cluster still on disk, and how big is it."""
    if not os.path.exists('/opt/tak'):
        return jsonify({'success': False, 'error': 'TAK Server not installed'}), 400
    res = _pg_old_cluster_state(_get_tak_deployment_config(load_settings()))
    return jsonify({'success': bool(res.get('ok', True)), **res})


@app.route('/api/guarddog/pg-old-cluster/remove', methods=['POST'])
@login_required
def guarddog_pg_old_cluster_remove():
    """DESTRUCTIVE: remove the leftover PostgreSQL 15 cluster — the 5.8 migration's
    rollback copy. Password + typed confirmation, same gate as Purge Old CoT."""
    if not os.path.exists('/opt/tak'):
        return jsonify({'success': False, 'error': 'TAK Server not installed'}), 400
    data = request.get_json(silent=True) or {}
    if mod_registry._check_admin_password({'load_auth': load_auth,
                                           'verify_password': verify_password}, data):
        return jsonify({'success': False, 'error': 'Incorrect console password.',
                        'need_password': True}), 403
    want = str(_PG_OLD_CLUSTER_MAJOR)
    if (data.get('confirm') or '').strip() != want:
        return jsonify({'success': False, 'error': "confirm must be exactly '%s'." % want,
                        'expected_confirm': want}), 400
    tak_cfg = _get_tak_deployment_config(load_settings())
    st = _pg_old_cluster_state(tak_cfg)
    if not st.get('found'):
        return jsonify({'success': False, 'error': 'No PostgreSQL %s cluster found.' % want}), 400
    if not st.get('removable'):
        return jsonify({'success': False, 'error': st.get('not_removable_reason') or 'Not removable.'}), 409
    audit('guarddog:pg-old-cluster', 'remove PostgreSQL %s cluster %s on %s (%s)'
          % (want, st.get('path'), st.get('where'), st.get('bytes_human')), force=True)
    res = _pg_old_cluster_call('drop', tak_cfg)
    ok = bool(res.get('ok') and res.get('removed'))
    audit('guarddog:pg-old-cluster', ('removed, freed %s' % st.get('bytes_human')) if ok
          else ('FAILED: %s' % (res.get('error') or 'unknown')[:200]), force=True)
    if not ok:
        return jsonify({'success': False, 'error': res.get('error') or 'Removal failed.'}), 500
    return jsonify({'success': True, 'freed_human': st.get('bytes_human'),
                    'message': 'Removed the PostgreSQL %s cluster (%s) on %s and freed %s.'
                               % (want, st.get('path'), st.get('where'), st.get('bytes_human'))})


@app.route('/api/takserver/cert-expiry')
@login_required
def takserver_cert_expiry():
    """Return Root CA and Intermediate CA expiry dates and days remaining."""
    cert_dir = '/opt/tak/certs/files'
    results = {}
    for label, filename in [('root_ca', 'root-ca.pem'), ('intermediate_ca', 'ca.pem')]:
        path = os.path.join(cert_dir, filename)
        if not os.path.exists(path):
            results[label] = {'error': 'Not found', 'file': filename}
            continue
        try:
            r = subprocess.run(
                ['openssl', 'x509', '-enddate', '-noout', '-in', path],
                capture_output=True, text=True, timeout=5
            )
            if r.returncode != 0:
                results[label] = {'error': 'Failed to read cert'}
                continue
            raw = r.stdout.strip().split('=', 1)[-1]
            from datetime import datetime
            expiry = datetime.strptime(raw, '%b %d %H:%M:%S %Y %Z')
            now = datetime.utcnow()
            days_left = (expiry - now).days
            results[label] = {
                'file': filename,
                'expires': expiry.strftime('%Y-%m-%d'),
                'days_left': days_left
            }
        except Exception as e:
            results[label] = {'error': str(e)[:200]}
    return jsonify(results)


@app.route('/api/fedhub/cert-expiry')
@login_required
def fedhub_cert_expiry():
    """Return Federation Hub Root CA and Intermediate CA expiry (local or remote). Same shape as /api/takserver/cert-expiry."""
    settings = load_settings()
    cfg = _get_fedhub_deployment_config(settings)
    if not cfg.get('deployed'):
        return jsonify({'root_ca': {'error': 'Not deployed'}, 'intermediate_ca': {'error': 'Not deployed'}})
    is_remote = cfg.get('target_mode') == 'remote'
    remote = cfg.get('remote', {})
    if is_remote and not (remote.get('host') or '').strip():
        return jsonify({'root_ca': {'error': 'No host'}, 'intermediate_ca': {'error': 'No host'}})
    fh_dir = '/opt/tak/federation-hub/certs/files'
    results = {}
    for label, filename in [('root_ca', 'root-ca.pem'), ('intermediate_ca', 'ca.pem')]:
        path = f'{fh_dir}/{filename}'
        cmd = f'openssl x509 -enddate -noout -in {shlex.quote(path)} 2>/dev/null'
        ok, out = _module_run(cfg, cmd, timeout=15)
        if not ok or not (out or '').strip() or 'notAfter' not in out:
            results[label] = {'error': 'Not found', 'file': filename}
            continue
        try:
            raw = out.strip().split('=', 1)[-1].strip()
            from datetime import datetime
            expiry = datetime.strptime(raw, '%b %d %H:%M:%S %Y %Z')
            now = datetime.utcnow()
            days_left = (expiry - now).days
            results[label] = {
                'file': filename,
                'expires': expiry.strftime('%Y-%m-%d'),
                'days_left': days_left,
            }
        except Exception as e:
            results[label] = {'error': str(e)[:200], 'file': filename}
    return jsonify(results)


def _canonical_tak_group_name(value):
    """Normalize TAK group names to a canonical channel name.

    We intentionally collapse TAK Portal directional suffix groups
    (e.g. *_READ, *_WRITE, *_BOTH) to the base name so cert assignment
    targets the same channel identity.
    """
    name = str(value or '').strip()
    if not name:
        return ''
    m = re.match(r'^(.*?)(?:[_-](?:read|write|both))$', name, re.IGNORECASE)
    if m:
        base = (m.group(1) or '').strip()
        if base:
            return base
    return name


def _exclude_from_cert_group_picker(name):
    """Return True for system/admin groups we do not want in cert picker."""
    n = str(name or '').strip()
    if not n:
        return True
    lowered = n.lower()
    if lowered == '__anon__':
        return True
    if lowered == 'role_admin':
        return True
    if lowered.startswith('authentik'):
        return True
    if lowered.startswith('cn=tak_'):
        return True
    if lowered in ('vid_public', 'vid_private'):
        return True
    return False


@app.route('/api/takserver/groups')
@login_required
def takserver_groups():
    """List groups from TAK Server APIs using admin cert.

    We merge:
    - /Marti/api/groups/all
    - /user-management/api/list-groupnames
    so TAK Portal-created groups can still appear in certificate workflows.
    """
    settings = load_settings()
    cert_dir = '/opt/tak/certs/files'
    cert_pass = _get_tak_cert_password(settings)
    admin_p12 = os.path.join(cert_dir, 'admin.p12')
    if not os.path.exists(admin_p12):
        return jsonify({'error': 'admin.p12 not found in /opt/tak/certs/files/', 'groups': []})
    try:
        # TAK Server generates legacy PKCS12 (RC2-40-CBC) that modern curl/OpenSSL 3.x
        # rejects (exit 58). Extract PEM cert+key with -legacy flag for curl.
        admin_pem = '/tmp/tak-admin-curl.pem'
        admin_key = '/tmp/tak-admin-curl.key'
        # v10.0.5 non-root: admin.p12 is 0600 tak:tak — cat it via the broker into a temp so
        # openssl can read it (raw openssl as takwerx -> empty PEM -> "Failed to extract").
        import tempfile as _tf
        _src_p12, _tmp_src = admin_p12, None
        try:
            _cat = subprocess.run(_sudo_wrap(['cat', admin_p12]), capture_output=True, timeout=10)
            if _cat.returncode == 0 and _cat.stdout:
                _fd, _tmp_src = _tf.mkstemp(suffix='.p12')
                with os.fdopen(_fd, 'wb') as _f:
                    _f.write(_cat.stdout)
                _src_p12 = _tmp_src
        except Exception:
            pass
        subprocess.run(
            f'openssl pkcs12 -in {_src_p12} -passin pass:{shlex.quote(cert_pass)} -clcerts -nokeys -legacy 2>/dev/null > {admin_pem}',
            shell=True, capture_output=True, text=True, timeout=10)
        subprocess.run(
            f'openssl pkcs12 -in {_src_p12} -passin pass:{shlex.quote(cert_pass)} -nocerts -nodes -legacy 2>/dev/null > {admin_key}',
            shell=True, capture_output=True, text=True, timeout=10)
        if _tmp_src:
            try:
                os.remove(_tmp_src)
            except Exception:
                pass
        if not os.path.exists(admin_pem) or os.path.getsize(admin_pem) == 0:
            return jsonify({'error': 'Failed to extract PEM from admin.p12 (legacy conversion)', 'groups': []})
        import json as _json
        def _curl_json(url):
            cmd = ['curl', '-sk', '--max-time', '8',
                   '--cert', admin_pem, '--key', admin_key, url]
            r = subprocess.run(cmd, capture_output=True, text=True, timeout=12)
            body = (r.stdout or '').strip()
            if r.returncode != 0 or not body:
                return None, f'curl_exit_{r.returncode}'
            try:
                return _json.loads(body), None
            except _json.JSONDecodeError:
                return None, 'invalid_json'

        merged = {}
        warnings = []

        marti_data, marti_err = _curl_json('https://127.0.0.1:8443/Marti/api/groups/all')
        if marti_data is not None:
            items = marti_data.get('data', marti_data) if isinstance(marti_data, dict) else marti_data
            if isinstance(items, list):
                for g in items:
                    if not isinstance(g, dict):
                        continue
                    name = _canonical_tak_group_name(g.get('name'))
                    if _exclude_from_cert_group_picker(name):
                        continue
                    merged[name] = {
                        'name': name,
                        'direction': g.get('direction', ''),
                        'active': g.get('active', True)
                    }
        elif marti_err:
            warnings.append(f'marti_groups:{marti_err}')

        um_data, um_err = _curl_json('https://127.0.0.1:8443/user-management/api/list-groupnames')
        if um_data is not None:
            items = um_data.get('data', um_data) if isinstance(um_data, dict) else um_data
            if isinstance(items, list):
                for g in items:
                    if isinstance(g, str):
                        name = _canonical_tak_group_name(g)
                    elif isinstance(g, dict):
                        name = _canonical_tak_group_name(
                            g.get('name')
                            or g.get('groupName')
                            or g.get('groupname')
                            or g.get('group')
                            or ''
                        )
                    else:
                        name = ''
                    if _exclude_from_cert_group_picker(name):
                        continue
                    if name not in merged:
                        merged[name] = {
                            'name': name,
                            'direction': '',
                            'active': True
                        }
        elif um_err:
            warnings.append(f'user_mgmt_groups:{um_err}')

        # Also pull tak_* groups directly from Authentik so newly-created groups
        # appear in the picker before first user login hits TAK.
        ak_token = _get_authentik_env_value(settings, 'AUTHENTIK_BOOTSTRAP_TOKEN') or _get_authentik_env_value(settings, 'AUTHENTIK_TOKEN')
        if ak_token:
            try:
                import urllib.request as _req
                import urllib.parse as _parse
                ak_url = _get_authentik_api_url(settings)
                next_url = f'{ak_url}/api/v3/core/groups/?page_size=200&name__istartswith=tak_'
                seen = 0
                while next_url and seen < 2000:
                    req = _req.Request(next_url, headers={'Authorization': f'Bearer {ak_token}', 'Content-Type': 'application/json'})
                    with _req.urlopen(req, timeout=12) as resp:
                        page = _json.loads((resp.read() or b'').decode('utf-8', 'replace'))
                    results = page.get('results', []) if isinstance(page, dict) else []
                    for g in results:
                        raw = (g.get('name') or '').strip() if isinstance(g, dict) else ''
                        if not raw:
                            continue
                        name = raw[4:] if raw.lower().startswith('tak_') else raw
                        name = _canonical_tak_group_name(name)
                        if _exclude_from_cert_group_picker(name):
                            continue
                        if name not in merged:
                            merged[name] = {
                                'name': name,
                                'direction': '',
                                'active': True
                            }
                    seen += len(results)
                    nxt = page.get('next') if isinstance(page, dict) else None
                    if not nxt:
                        next_url = None
                    elif str(nxt).startswith('http'):
                        next_url = str(nxt)
                    else:
                        next_url = _parse.urljoin(ak_url, str(nxt))
            except Exception as e:
                warnings.append(f'authentik_groups:{str(e)[:80]}')

        groups = sorted(merged.values(), key=lambda x: x['name'].lower())
        if not groups and warnings:
            return jsonify({'error': '; '.join(warnings), 'groups': []})
        if warnings:
            return jsonify({'groups': groups, 'warnings': warnings})
        return jsonify({'groups': groups})
    except Exception as e:
        return jsonify({'error': str(e)[:200], 'groups': []})
    finally:
        for f in ['/tmp/tak-admin-curl.pem', '/tmp/tak-admin-curl.key']:
            try:
                os.remove(f)
            except OSError:
                pass


@app.route('/api/takserver/ca-info')
@login_required
def takserver_ca_info():
    """Return current Root CA and Intermediate CA names, expiry, and truststore contents."""
    cert_dir = '/opt/tak/certs/files'
    cert_pass = _get_tak_cert_password(load_settings())
    info = {'root_ca': None, 'intermediate_ca': None, 'old_cas_in_truststore': [], 'suggested_new_name': ''}
    for label, filename in [('root_ca', 'root-ca.pem'), ('intermediate_ca', 'ca.pem')]:
        path = os.path.join(cert_dir, filename)
        if not os.path.exists(path):
            continue
        try:
            r = subprocess.run(['openssl', 'x509', '-subject', '-enddate', '-noout', '-in', path],
                               capture_output=True, text=True, timeout=5)
            cn = ''
            expiry_raw = ''
            for line in r.stdout.strip().split('\n'):
                line = line.strip()
                if line.startswith('subject=') or line.startswith('subject ='):
                    subj = line.split('=', 1)[-1].strip()
                    for part in subj.split(','):
                        part = part.strip()
                        if part.startswith('CN') or part.startswith('CN '):
                            cn = part.split('=', 1)[-1].strip()
                elif 'notAfter' in line:
                    expiry_raw = line.split('=', 1)[-1].strip()
            days_left = None
            expires = ''
            if expiry_raw:
                from datetime import datetime
                exp_dt = datetime.strptime(expiry_raw, '%b %d %H:%M:%S %Y %Z')
                days_left = (exp_dt - datetime.utcnow()).days
                expires = exp_dt.strftime('%Y-%m-%d')
            info[label] = {'name': cn, 'file': filename, 'expires': expires, 'days_left': days_left}
        except Exception:
            pass
    import re
    def _increment_name(name):
        m = re.search(r'(\d+)$', name)
        if m:
            return name[:m.start()] + f'{int(m.group(1)) + 1:02d}'
        return name + '-02'
    if info['intermediate_ca'] and info['intermediate_ca']['name']:
        info['suggested_new_name'] = _increment_name(info['intermediate_ca']['name'])
    if info['root_ca'] and info['root_ca']['name']:
        info['suggested_new_root_name'] = _increment_name(info['root_ca']['name'])
        info['suggested_new_root_int_name'] = _increment_name(info.get('suggested_new_name', 'INT-CA-01'))
    # List CAs in current truststore (to show old CAs that can be revoked).
    # ops #174: the one TAK Server enforces, not the last name in sort order. When it can't be
    # told, no truststore is shown and no Revoke button appears.
    ts_name = _live_truststore(cert_dir, '.jks')
    if ts_name:
        ts_path = os.path.join(cert_dir, ts_name)
        info['truststore_file'] = ts_name
        try:
            if _tak_is_container():
                # v10.0.1: no host keytool on a container box (JDK is inside the container) —
                # list the truststore inside the running TAK container so old CAs are detected
                # and the 'Revoke Old CA' box actually appears on arm64.
                _kt = f'keytool -list -keystore {shlex.quote(ts_path)} -storepass {shlex.quote(cert_pass)}'
                r = subprocess.run(f'docker exec {TAK_CONTAINER} bash -c {shlex.quote(_kt)}',
                                   shell=True, capture_output=True, text=True, timeout=15)
            else:
                r = subprocess.run(
                    ['keytool', '-list', '-keystore', ts_path, '-storepass', cert_pass],
                    capture_output=True, text=True, timeout=10)
            aliases = []
            trusted_aliases = []
            for line in r.stdout.split('\n'):
                if ',' not in line:
                    continue
                alias = line.split(',')[0].strip()
                if 'trustedCertEntry' in line:
                    aliases.append(alias)
                    trusted_aliases.append(alias)
                elif 'PrivateKeyEntry' in line:
                    aliases.append(alias)
            info['truststore_aliases'] = aliases
            current_cn = (info['intermediate_ca'] or {}).get('name', '').lower()
            root_cn = (info['root_ca'] or {}).get('name', '').lower()
            old_cas = []
            skip_aliases = {'mykey'}  # legacy default alias, not a CA to revoke
            for a in trusted_aliases:
                if a.lower() in skip_aliases:
                    continue
                if a.lower() != current_cn.lower() and a.lower() != 'root-ca' and a.lower() != root_cn.lower():
                    old_cas.append(a)
            info['old_cas_in_truststore'] = old_cas
        except Exception:
            pass
    return jsonify(info)


rotate_intca_log = []
rotate_intca_status = {'running': False, 'complete': False, 'error': False}


def _rotate_client_cert_names(cert_dir, skip=()):
    """Client certs Rotate Intermediate CA re-issues: each NAME.p12 that is not CA material.

    makeCert.sh `ca` leaves NAME.crl, truststore-NAME.jks and NAME-signing.p12 behind for
    every intermediate ever made, so a box rotated N times holds INT-CA-01..0N and their
    -signing keystores. Matching only the old/new CA names re-issued all of those as client
    certs, which appends a non-CA private key to the live enrollment signing keystore that
    CoreConfig's TAKServerCAConfig points at (ops #82, seen on test8 after nine rotations).
    """
    files = os.listdir(cert_dir)
    cas = {'takserver', 'root-ca', 'ca'} | {s.lower() for s in skip if s}
    for f in files:
        if f.endswith('.crl'):
            cas.add(f[:-4].lower())
        elif f.startswith('truststore-') and f.endswith('.jks'):
            cas.add(f[len('truststore-'):-4].lower())
    names = []
    for f in sorted(files):
        if not f.endswith('.p12') or f.startswith('truststore-'):
            continue
        name = f[:-4]
        low = name.lower()
        if low in cas or (low.endswith('-signing') and low[:-len('-signing')] in cas):
            continue
        names.append(name)
    return names


# v10.2.26 — the names on TAK Server's own certificate (8089/8443). TAK's makeCert.sh gives a
# server cert exactly one SAN (`[alt_names] DNS.1 = <name>`), so every box we deployed carried
# only DNS:takserver. ATAK/iTAK/WinTAK/CloudTAK never check the hostname on 8089, so nothing
# noticed; anything that does — NineHills cUAS dialing takserver.trytak.org (2026-10-22, 50/50
# handshakes refused with BAD_CERTIFICATE), TAK Portal with --use-system-ca (nuc, 2026-08-06,
# ERR_TLS_CERT_ALTNAME_INVALID) — rejects the server outright.
#
# makeCert builds the server cert's extfile as a copy of certs/config.cfg with
# `subjectAltName = @alt_names` + `[alt_names] DNS.1 = <name>` appended, and OpenSSL merges a
# repeated section. So a managed [alt_names] block placed ABOVE `[ server ]` in config.cfg adds
# this box's names to the cert makeCert issues — verified on OpenSSL 3.0.2 (Ubuntu 22.04) and
# 3.6. The stock script, its key/keystore handling and the broker's makeCert-only carve-out
# stay exactly as they were; client and CA certs never reference @alt_names. CN stays
# `takserver` (it is what federation partners see) and so do the file names.
_TAK_CERTS_CONFIG = '/opt/tak/certs/config.cfg'
_TAK_SAN_BEGIN = '# >>> infra-TAK: TAK Server certificate names (managed - edits are replaced) >>>'
_TAK_SAN_END = '# <<< infra-TAK: TAK Server certificate names <<<'
_TAK_SAN_HOST_RE = re.compile(r'^(?=.{1,253}$)[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?'
                              r'(?:\.[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?)*$')
tak_server_cert_job = {'running': False, 'complete': False, 'error': False, 'log': [], 'started': 0.0}


def _tak_server_cert_names(settings):
    """Every name TAK Server's certificate should carry, as 'DNS:x' / 'IP:y'.

    makeCert's own DNS:takserver first (anything that dials the old name keeps working), then
    the TAK domain, the bare domain, the server IP and loopback. Every value is validated here
    because it ends up in a file makeCert hands to openssl."""
    names = ['DNS:takserver']

    def add(entry):
        if entry not in names:
            names.append(entry)
    for host in (_get_service_domain(settings, 'takserver'), settings.get('fqdn')):
        h = str(host or '').strip().lower().rstrip('.')
        if h and _TAK_SAN_HOST_RE.match(h):
            add(f'DNS:{h}')
    sip = settings.get('server_ip')
    if isinstance(sip, str):  # a list here is the server-ip tuple corruption; skip it, don't guess
        try:
            add(f'IP:{ipaddress.ip_address(sip.strip())}')
        except ValueError:
            pass
    add('DNS:localhost')
    add('IP:127.0.0.1')
    return names


def _tak_config_cfg_with_names(text, names):
    """config.cfg with the managed [alt_names] block (re)placed directly above `[ server ]`.

    Returns None when there is no `[ server ]` section, or a managed block with no end marker:
    a config this code does not recognize is left alone rather than guessed at."""
    kept, inside, after_block = [], False, False
    for line in text.splitlines(keepends=True):
        s = line.strip()
        if s == _TAK_SAN_BEGIN:
            inside = True
        elif inside:
            inside = s != _TAK_SAN_END
            after_block = not inside
        elif after_block and not s:
            after_block = False          # the blank line we put after our own block
        else:
            after_block = False
            kept.append(line)
    if inside:
        return None
    at = next((i for i, line in enumerate(kept) if re.match(r'^\s*\[\s*server\s*\]\s*$', line)), None)
    if at is None:
        return None
    # makeCert writes DNS.1 itself, so ours start at .2 (IP too, in case a name is ever an IP).
    counter = {'DNS': 1, 'IP': 1}
    block = [_TAK_SAN_BEGIN + '\n', '[ alt_names ]\n']
    for entry in names:
        if entry == 'DNS:takserver':
            continue
        kind, value = entry.split(':', 1)
        counter[kind] += 1
        block.append(f'{kind}.{counter[kind]} = {value}\n')
    block += [_TAK_SAN_END + '\n', '\n']
    if at and not kept[at - 1].endswith('\n'):
        kept[at - 1] += '\n'
    return ''.join(kept[:at] + block + kept[at:])


def _tak_server_cert_prepare(settings, log=None):
    """Write this box's names into certs/config.cfg so the next `makeCert.sh server` carries them.

    Call it before every makeCert server run. Never raises and never blocks the caller: a box
    whose config.cfg cannot be read or extended still gets the stock DNS:takserver cert, exactly
    as before, and the TAK Server page's certificate row shows it. Returns True when in place."""
    say = log or (lambda _m: None)
    try:
        cur = _read_priv(_TAK_CERTS_CONFIG)
    except Exception as e:
        say(f"  ⚠ Could not read {_TAK_CERTS_CONFIG} ({str(e)[:120]}) — server certificate keeps only DNS:takserver")
        return False
    names = _tak_server_cert_names(settings)
    new = _tak_config_cfg_with_names(cur or '', names)
    if new is None:
        say(f"  ⚠ {_TAK_CERTS_CONFIG} has no [ server ] section — server certificate keeps only DNS:takserver")
        return False
    if new != cur:
        try:
            _write_priv(_TAK_CERTS_CONFIG, new)
        except Exception as e:
            say(f"  ⚠ Could not update {_TAK_CERTS_CONFIG} ({str(e)[:120]}) — server certificate keeps only DNS:takserver")
            return False
    say("  Server certificate names: " + ', '.join(n.split(':', 1)[1] for n in names))
    return True


def _cert_san_entries(pem):
    """SANs of a PEM certificate as 'DNS:x' / 'IP:y' (IPs normalized), or None if unreadable."""
    try:
        r = subprocess.run(['openssl', 'x509', '-noout', '-ext', 'subjectAltName'],
                           input=pem, capture_output=True, text=True, timeout=10)
    except Exception:
        return None
    if r.returncode != 0:
        return None
    out = []
    for part in r.stdout.split('\n', 1)[-1].split(','):
        p = part.strip()
        if p.startswith('DNS:'):
            out.append('DNS:' + p[4:].lower())
        elif p.startswith('IP Address:'):
            try:
                out.append(f"IP:{ipaddress.ip_address(p.split(':', 1)[1].strip())}")
            except ValueError:
                pass
    return out


def _tak_server_cert_live_names():
    """SANs on the certificate TAK Server is presenting RIGHT NOW, or None if it isn't answering.

    Reads 8443, not 8089: both are served from the same <tls> keystore, and a client-certless
    handshake on 8089 writes an ERROR line into takserver-messaging.log on every probe, while
    8443 stays quiet. s_client gets the server's cert before TAK asks for ours; nothing is sent."""
    try:
        r = subprocess.run(['openssl', 's_client', '-connect', '127.0.0.1:8443'],
                           input='', capture_output=True, text=True, timeout=10)
    except Exception:
        return None
    m = re.search(r'-----BEGIN CERTIFICATE-----.*?-----END CERTIFICATE-----', r.stdout, re.S)
    return _cert_san_entries(m.group(0)) if m else None


def _tak_server_cert_status(settings):
    """What the TAK Server page's certificate row shows. Judged from the LIVE cert, so the row
    only turns green once TAK is actually presenting the names, not when a file was written."""
    want = _tak_server_cert_names(settings)
    tak_domain = (_get_service_domain(settings, 'takserver') or '').lower()
    live = _tak_server_cert_live_names()
    st = {'expected': [n.split(':', 1)[1] for n in want], 'domain': tak_domain}
    if live is None:
        return {**st, 'state': 'unknown', 'live': [], 'missing': []}
    missing = [n.split(':', 1)[1] for n in want if n not in live]
    return {**st, 'state': 'missing' if missing else 'ok',
            'live': [n.split(':', 1)[1] for n in live], 'missing': missing}


_tak_cert_status_cache = {'at': 0.0, 'status': None, 'refreshing': False}
_TAK_CERT_STATUS_TTL = 600


def _tak_server_cert_status_remember(status):
    _tak_cert_status_cache.update(at=time.time(), status=status)
    return status


def _tak_server_cert_status_cached(settings):
    """The last live result, for callers on every page render (the notice bar) that must not
    run a TLS handshake inline. When stale, a background thread refreshes it and this call
    returns the previous result (None before the first one lands). The TAK Server page and
    the Fix job store fresh results directly, so the bar follows them without waiting."""
    c = _tak_cert_status_cache
    if (time.time() - c['at'] > _TAK_CERT_STATUS_TTL and not c['refreshing']
            and not tak_server_cert_job['running']):
        c['refreshing'] = True
        snap = dict(settings or {})

        def _refresh():
            try:
                _tak_server_cert_status_remember(_tak_server_cert_status(snap))
            except Exception:
                pass
            finally:
                c['refreshing'] = False
        threading.Thread(target=_refresh, daemon=True).start()
    return c['status']


def _rotate_reissue_cert(kind, name, run, cert_dir='/opt/tak/certs/files'):
    """`makeCert.sh <kind> NAME` that really replaces NAME.p12 and NAME.jks. Returns True on success.

    makeCert.sh writes both keystores with `keytool -importkeystore -alias NAME`, which on an
    existing store asks "Existing entry alias NAME exists, overwrite? [no]" on stdin. The one
    `echo "y"` piped in is read by the first keytool (the .jks); the second (the .p12) reads EOF
    and keeps the OLD cert. So every rotation left NAME.pem/.jks on the new CA and NAME.p12 on
    the one it was first made with, and whatever loads the .p12 (TAK Portal's admin.p12,
    CloudTAK's bootstrap cert, Guard Dog's Marti scrape) kept presenting it until a later
    rotation dropped that CA from the truststore — then 8089 "peer not verified" (ops #96,
    test8: admin.p12 still on INT-CA-08 three rotations later). Moving both keystores aside
    first means makeCert creates them fresh, with no prompt; they are put back if it does not.
    `run` is the rotation's own runner: run(cmd) -> bool, container-aware, logs failures."""
    aside = []
    for ext in ('.p12', '.jks'):
        p = os.path.join(cert_dir, name + ext)
        if _exists_priv(p) and run(f'mv -f {shlex.quote(p)} {shlex.quote(p + ".reissue")}'):
            aside.append(p)
    ok = run(f'cd /opt/tak/certs && echo "y" | runuser -u tak -- /opt/tak/certs/makeCert.sh {kind} {shlex.quote(name)} 2>&1')
    for p in aside:
        if _exists_priv(p):
            run(f'rm -f {shlex.quote(p + ".reissue")}')
        else:
            run(f'mv -f {shlex.quote(p + ".reissue")} {shlex.quote(p)}')
            ok = False
    return ok


def _rotate_refresh_integrations(log):
    """After a rotation's TAK Server restart: integrations that cache a client cert in memory.

    Node-RED's TLS config reads /certs/admin.pem once, when the flows start, so it presents the
    previous cert until it restarts — fine while that CA is still in the truststore, and an 8089
    failure from the next rotation on (test8, 3:01 PM PT Oct 19, until a console update happened
    to resync the flows). CloudTAK keeps its TAK cert in its own database; the existing W11d heal
    swaps it only when the connection is dead because its CA is gone, which is exactly the state
    the rotation that drops that CA leaves behind.

    makeCert.sh writes the new admin.key 600 (tak-owned), and Node-RED reads it as uid 1000
    through the bind mount, so the restart alone came back with EACCES on /certs/admin.key and
    connected to 8089 with no client cert at all (test8, 7:59 PM PT Oct 19). The boot-time heal
    puts the pair back to 644 first."""
    try:
        _heal_nodered_cert_read_access(lambda m: log(f"  {m}"))
    except Exception as e:
        log(f"  ⚠ Node-RED cert read heal skipped: {str(e)[:160]}")
    try:
        r = subprocess.run(_sudo_wrap(['docker', 'ps', '-q', '--filter', 'name=nodered']),
                           capture_output=True, text=True, timeout=15)
        if (r.stdout or '').strip():
            r = subprocess.run(_sudo_wrap(['docker', 'restart', 'nodered']),
                               capture_output=True, text=True, timeout=120)
            log(f"  {'✓ Node-RED restarted (reloads admin.pem)' if r.returncode == 0 else '⚠ Node-RED restart failed: ' + (r.stderr or r.stdout or '').strip()[:160]}")
    except Exception as e:
        log(f"  ⚠ Node-RED restart skipped: {str(e)[:160]}")
    try:
        _cloudtak_tak_cert_heal(log=log)
    except Exception as e:
        log(f"  ⚠ CloudTAK cert check skipped: {str(e)[:160]}")


def _rotate_sh(argv, timeout=120):
    """Runs `runuser -u tak -- <argv>`, container-aware, and keeps the output: (ok, stdout+stderr).
    An argv list, not a shell string: the truststore password goes in as one word."""
    try:
        r = subprocess.run(_rotate_tak_cert_argv(argv), stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                           text=True, timeout=timeout)
        return r.returncode == 0, r.stdout or ''
    except Exception as e:
        return False, str(e)


def _rotate_coreconfig_truststore(cc_text):
    """(absolute truststoreFile, truststorePass) from CoreConfig's <tls> element, or ('', '').
    This is the truststore TAK Server is enforcing right now. Federation has a <tls> of its own
    (fed-truststore.jks), so read the one under <security>."""
    sec = re.search(r'<security\b.*?</security>', cc_text or '', re.S)
    m = re.search(r'<tls\b[^>]*>', sec.group(0) if sec else (cc_text or ''))
    if not m:
        return '', ''
    f = re.search(r'\btruststoreFile="([^"]*)"', m.group(0))
    p = re.search(r'\btruststorePass="([^"]*)"', m.group(0))
    path = (f.group(1) if f else '').strip()
    if path and not path.startswith('/'):
        path = os.path.join('/opt/tak', path)
    return path, html.unescape(p.group(1)) if p else ''


def _pem_key(pem):
    """The base64 body of a PEM cert, whitespace-free: equal for the same cert in any store."""
    m = re.search(r'-----BEGIN CERTIFICATE-----(.*?)-----END CERTIFICATE-----', pem or '', re.S)
    return re.sub(r'\s+', '', m.group(1) if m else (pem or ''))


def _rotate_truststore_entries(ts_path, storepass, sh):
    """[(alias, pem)] for every trustedCertEntry in a truststore, via `keytool -list -rfc`.
    None if keytool cannot read it. sh(argv) -> (ok, output), argv run as `tak`."""
    ok, out = sh(['keytool', '-list', '-rfc', '-keystore', ts_path, '-storepass', storepass])
    if not ok or 'Alias name:' not in out:
        return None
    entries = []
    for block in out.split('Alias name:')[1:]:
        alias = block.split('\n', 1)[0].strip()
        pem = re.search(r'-----BEGIN CERTIFICATE-----.*?-----END CERTIFICATE-----', block, re.S)
        if alias and pem and 'trustedCertEntry' in block:
            entries.append((alias, pem.group(0)))
    return entries


def _pem_cn_and_expiry(pem):
    """(subject CN, notAfter datetime or None) of a PEM cert, via openssl."""
    try:
        r = subprocess.run(['openssl', 'x509', '-noout', '-subject', '-enddate'], input=pem,
                           capture_output=True, text=True, timeout=10)
        out = r.stdout or ''
    except Exception:
        return '', None
    cn = re.search(r'^subject\s*=.*?CN\s*=\s*([^,/\n]+)', out, re.M)
    end = re.search(r'^notAfter=(.+)$', out, re.M)
    try:
        not_after = datetime.strptime(end.group(1).strip(), '%b %d %H:%M:%S %Y %Z') if end else None
    except ValueError:
        not_after = None
    return (cn.group(1).strip() if cn else ''), not_after


def _tak_live_certs_by_issuer(query):
    """{issuer CN lower: count} of the client certs in TAK Server's certificate table that are
    still live (not revoked, not expired), or None if the table can't be read.
    query(sql) -> (ok, text), e.g. _cotdb_psql bound to the box's deployment config."""
    ok, out = query("SELECT replace(replace(certificate, chr(13), ''), chr(10), '') FROM certificate "
                    "WHERE revocation_date IS NULL AND (expiration_date IS NULL OR expiration_date > now())")
    if not ok:
        return None
    pems = []
    for line in (out or '').splitlines():
        body = re.sub(r'-----(BEGIN|END) CERTIFICATE-----|\s', '', line)
        if body:
            pems.append('-----BEGIN CERTIFICATE-----\n'
                        + '\n'.join(body[i:i + 64] for i in range(0, len(body), 64))
                        + '\n-----END CERTIFICATE-----\n')
    counts = {}
    if not pems:
        return counts
    try:
        with tempfile.NamedTemporaryFile('w', suffix='.pem') as f:
            f.write(''.join(pems))
            f.flush()
            p7 = subprocess.run(['openssl', 'crl2pkcs7', '-nocrl', '-certfile', f.name],
                                capture_output=True, text=True, timeout=60)
            r = subprocess.run(['openssl', 'pkcs7', '-print_certs', '-noout'], input=p7.stdout,
                               capture_output=True, text=True, timeout=60)
        if p7.returncode != 0 or r.returncode != 0:
            return None
    except Exception:
        return None
    for m in re.finditer(r'^issuer\s*=.*?CN\s*=\s*([^,/\n]+)', r.stdout or '', re.M):
        k = m.group(1).strip().lower()
        counts[k] = counts.get(k, 0) + 1
    return counts


def _rotate_tak_live_certs_by_issuer():
    try:
        tak_cfg = _get_tak_deployment_config(load_settings())
        return _tak_live_certs_by_issuer(lambda sql: _cotdb_psql(tak_cfg, sql))
    except Exception:
        return None


def _live_count_text(live, cn):
    if live is None:
        return 'live cert count unknown'
    n = live.get((cn or '').lower(), 0)
    return f"{n} live client cert{'' if n == 1 else 's'}"


def _rotate_carry_forward_truststore(new_ts, prev_ts, prev_pass, cert_pass, old_ca_name, old_pem,
                                     live, run, sh, log, now=None):
    """Rotate Intermediate CA Step 5: the new truststore keeps every CA the live one trusts.

    It used to get only the root, the new CA and the CA being replaced, so the CA from two
    rotations back left the truststore and every client cert it signed (ATAK enrollments,
    bridges, TAKX) was refused without a word (infra-TAK #204: test8 lost INT-CA-08 with 82
    live certs). Every trusted entry of the truststore CoreConfig points at now is copied over;
    only an expired CA is dropped, and that is logged with the live certs that still name it.
    A CA that is no longer in the truststore is not brought back (Revoke Old CA may have removed
    it on purpose); if live certs still depend on it, that is logged as a warning.
    Returns the CNs of every CA in the new truststore."""
    now = now or datetime.utcnow()
    have = _rotate_truststore_entries(new_ts, cert_pass, sh) or []
    have_keys = {_pem_key(p) for _, p in have}
    have_aliases = {a.lower() for a, _ in have}
    trusted = {_pem_cn_and_expiry(p)[0].lower() for _, p in have}
    prev = None
    if prev_ts and os.path.realpath(prev_ts) != os.path.realpath(new_ts):
        prev = _rotate_truststore_entries(prev_ts, prev_pass or cert_pass, sh)
    if prev is None:
        log(f"  ⚠ Could not read the current truststore ({os.path.basename(prev_ts or '') or 'none'}); "
            f"only {old_ca_name} is carried forward")
        prev = []
    kept, dropped = [], []
    for alias, pem in prev:
        key = _pem_key(pem)
        if key in have_keys:
            continue
        cn, not_after = _pem_cn_and_expiry(pem)
        if not_after and not_after < now:
            dropped.append(alias)
            log(f"  ⚠ Dropped {alias}: expired {not_after:%Y-%m-%d} ({_live_count_text(live, cn or alias)} signed by it)")
            continue
        # makeCert.sh puts each new CA in its truststore as `mykey`, so the CA being replaced
        # clashes with the new one on every rotation: carry it under its CN, which is also the
        # alias Revoke Old CA lists it by.
        dest = alias
        if dest.lower() in have_aliases and cn:
            dest = cn
        while dest.lower() in have_aliases:
            dest = f'{dest}-prev'
        if run(f'runuser -u tak -- keytool -importkeystore -srckeystore {shlex.quote(prev_ts)} '
               f'-srcstorepass {shlex.quote(prev_pass or cert_pass)} -srcalias {shlex.quote(alias)} '
               f'-destkeystore {shlex.quote(new_ts)} -deststorepass {shlex.quote(cert_pass)} '
               f'-destalias {shlex.quote(dest)} -noprompt 2>&1'):
            have_keys.add(key)
            have_aliases.add(dest.lower())
            trusted.add((cn or alias).lower())
            kept.append(dest)
        else:
            log(f"  ⚠ Could not carry {alias} forward; {_live_count_text(live, cn or alias)} depend on it")
    # The CA being replaced signed every client cert issued up to now: it must stay trusted
    # even when the old truststore could not be read or did not hold it.
    if old_ca_name.lower() not in trusted and os.path.exists(old_pem):
        if run(f'runuser -u tak -- keytool -import -trustcacerts -file {shlex.quote(old_pem)} '
               f'-keystore {shlex.quote(new_ts)} -alias {shlex.quote(old_ca_name)} '
               f'-deststorepass {shlex.quote(cert_pass)} -noprompt 2>&1'):
            trusted.add(old_ca_name.lower())
            kept.append(old_ca_name)
    if old_ca_name.lower() not in trusted:
        log(f"  ⚠ {old_ca_name} is NOT in the new truststore; {_live_count_text(live, old_ca_name)} depend on it")
    log(f"  Carried forward: {', '.join(kept) if kept else 'none'}")
    for cn, n in sorted((live or {}).items()):
        if n and cn not in trusted:
            log(f"  ⚠ {n} live client cert{'' if n == 1 else 's'} signed by {cn}, which is not in the truststore: "
                f"those clients are refused. Not re-added (Revoke Old CA may have removed it); "
                f"re-import its .pem if it was dropped by mistake")
    return trusted


def _rotate_log_dropped_cas(ts_path, storepass, live, sh, log):
    """Rotate Root CA replaces the whole PKI, so every CA in the live truststore goes. Say which,
    and how many live client certs each one signed, before the cert dir is wiped."""
    entries = _rotate_truststore_entries(ts_path, storepass, sh) if ts_path else None
    if entries is None:
        log(f"  ⚠ Could not read the current truststore ({os.path.basename(ts_path or '') or 'none'})")
        return
    log("  CAs leaving the truststore (their clients must re-enroll):")
    for alias, pem in entries:
        cn = _pem_cn_and_expiry(pem)[0] or alias
        log(f"    {alias}: {_live_count_text(live, cn)}")


@app.route('/api/takserver/rotate-intca', methods=['POST'])
@login_required
def takserver_rotate_intca():
    """Rotate the intermediate CA: create new CA, server cert, admin cert, import old CA into truststore."""
    if rotate_intca_status.get('running'):
        return jsonify({'error': 'Rotation already in progress'}), 409
    data = request.json or {}
    new_ca_name = (data.get('new_ca_name') or '').strip()
    if not new_ca_name:
        return jsonify({'error': 'New CA name is required'}), 400
    try:
        _validate_ca_name(new_ca_name, 'New CA name')
    except ValueError as e:
        return jsonify({'error': str(e)}), 400

    cert_dir = '/opt/tak/certs/files'
    if not os.path.exists(os.path.join(cert_dir, 'root-ca.pem')):
        return jsonify({'error': 'root-ca.pem not found — cannot rotate without a Root CA'}), 400
    if not os.path.exists(os.path.join(cert_dir, 'ca.pem')):
        return jsonify({'error': 'ca.pem not found — no current intermediate CA detected'}), 400

    # Detect current intermediate CA name
    try:
        r = subprocess.run(['openssl', 'x509', '-subject', '-noout', '-in', os.path.join(cert_dir, 'ca.pem')],
                           capture_output=True, text=True, timeout=5)
        old_ca_name = ''
        for part in r.stdout.replace('subject=', '').split(','):
            part = part.strip()
            if part.startswith('CN') or part.startswith('CN '):
                old_ca_name = part.split('=', 1)[-1].strip()
    except Exception:
        old_ca_name = ''
    if not old_ca_name:
        return jsonify({'error': 'Could not detect current intermediate CA name from ca.pem'}), 500
    if new_ca_name == old_ca_name:
        return jsonify({'error': f'New CA name must be different from current ({old_ca_name})'}), 400

    # Optional new cert password (save so thread uses it for new keystores)
    new_cert_password = (data.get('new_cert_password') or '').strip()
    if new_cert_password:
        settings = load_settings()
        settings['tak_cert_password'] = new_cert_password
        save_settings(settings)
    cert_pass = _get_tak_cert_password(load_settings())

    # Root CA days left — cap new intermediate validity to this
    root_days_left = None
    try:
        r = subprocess.run(['openssl', 'x509', '-enddate', '-noout', '-in', os.path.join(cert_dir, 'root-ca.pem')],
                           capture_output=True, text=True, timeout=5)
        if r.returncode == 0 and r.stdout:
            from datetime import datetime
            expiry_raw = r.stdout.strip().split('=', 1)[-1].strip()
            exp_dt = datetime.strptime(expiry_raw, '%b %d %H:%M:%S %Y %Z')
            root_days_left = (exp_dt - datetime.utcnow()).days
    except Exception:
        pass

    try:
        requested_validity = int(data.get('intermediate_validity_days') or 730)
        requested_validity = max(1, min(3652, requested_validity))
    except (TypeError, ValueError):
        requested_validity = 730
    int_validity_days = min(requested_validity, root_days_left) if root_days_left is not None and root_days_left > 0 else requested_validity
    if root_days_left is not None and requested_validity > root_days_left:
        pass  # already capped to root_days_left in int_validity_days

    rotate_intca_log.clear()
    rotate_intca_status.update({'running': True, 'complete': False, 'error': False})

    def do_rotate():
        def log(msg):
            rotate_intca_log.append(msg)

        def run(cmd, desc=None, check=True):
            if desc:
                log(desc)
            cmd = _rotate_tak_cert_cmd(cmd)  # v10.0.1: container-aware (runuser/chown/systemctl → docker)
            try:
                r = subprocess.run(cmd, shell=True, capture_output=True, text=True, timeout=120)
                if check and r.returncode != 0:
                    err = (r.stderr or r.stdout or '').strip()[:200]
                    log(f"  ✗ Failed (exit {r.returncode}): {err}")
                    return False
                return True
            except Exception as e:
                log(f"  ✗ Exception: {e}")
                return False

        try:
            log(f"━━━ Rotating Intermediate CA ━━━")
            log(f"  Old CA: {old_ca_name}")
            log(f"  New CA: {new_ca_name}")
            log("")

            # Save current (old) intermediate to a named file before we overwrite ca.pem — needed for transition bundle and truststore
            old_pem = os.path.join(cert_dir, f'{old_ca_name}.pem')
            if not os.path.exists(old_pem):
                run(f'cp {cert_dir}/ca.pem {old_pem}')
                log(f"  Saved current CA to {old_ca_name}.pem for transition bundle")

            log("Step 1/7: Restoring Root CA as working CA...")
            run(f'cp {cert_dir}/root-ca.pem {cert_dir}/ca.pem')
            run(f'cp {cert_dir}/root-ca-do-not-share.key {cert_dir}/ca-do-not-share.key')
            run(f'cp {cert_dir}/root-ca-trusted.pem {cert_dir}/ca-trusted.pem')
            log("✓ Root CA files restored")

            _patch_openssl_string_mask()

            log("")
            log(f"Step 2/7: Creating new Intermediate CA: {new_ca_name}...")
            run('chown tak:tak /opt/tak/certs/cert-metadata.sh && chmod 500 /opt/tak/certs/cert-metadata.sh')
            run(f'grep -qE "^CA_VALIDITY=" /opt/tak/certs/cert-metadata.sh 2>/dev/null && sed -i "s/^CA_VALIDITY=.*/CA_VALIDITY={int_validity_days}/" /opt/tak/certs/cert-metadata.sh || true', check=False)
            run(f'grep -qE "^INTERMEDIATE_VALIDITY" /opt/tak/certs/cert-metadata.sh 2>/dev/null && sed -i "s/^INTERMEDIATE_VALIDITY.*/INTERMEDIATE_VALIDITY={int_validity_days}/" /opt/tak/certs/cert-metadata.sh || true', check=False)
            log(f"  New intermediate validity: {int_validity_days} days (capped by root if needed)")
            _patch_cert_metadata_password(cert_pass)
            if not run(f'cd /opt/tak/certs && echo "y" | runuser -u tak -- /opt/tak/certs/makeCert.sh ca "{new_ca_name}" 2>&1'):
                raise Exception('Failed to create new intermediate CA')
            log(f"✓ Intermediate CA {new_ca_name} created")

            log("")
            log("Step 3/7: Creating new server certificate (signed by new CA)...")
            _tak_server_cert_prepare(load_settings(), log)  # v10.2.26: real names, not just `takserver`
            if not _rotate_reissue_cert('server', 'takserver', run, cert_dir):
                raise Exception('Failed to create new server certificate')
            log("✓ Server certificate regenerated (signed by new CA)")

            log("")
            log("Step 4/7: Regenerating all client certificates...")
            run('chown tak:tak /opt/tak/certs/cert-metadata.sh && chmod 500 /opt/tak/certs/cert-metadata.sh')
            regen_count = 0
            regen_failed = []
            for name in _rotate_client_cert_names(cert_dir, skip=(old_ca_name, new_ca_name)):
                log(f"  Regenerating: {name}")
                if _rotate_reissue_cert('client', name, run, cert_dir):
                    regen_count += 1
                else:
                    regen_failed.append(name)
            log(f"✓ {regen_count} client certificate(s) regenerated (signed by new CA)")
            if regen_failed:
                log(f"  ⚠ {len(regen_failed)} not regenerated: {', '.join(regen_failed[:10])}{' …' if len(regen_failed) > 10 else ''}")

            log("")
            log("Step 5/7: Updating truststore...")
            ts_jks = os.path.join(cert_dir, f'truststore-{new_ca_name}.jks')
            # v10.0.5 non-root: bare keytool writes JKS into tak-owned /opt/tak/certs/files
            # and fails as takwerx — route via the broker-allowed `runuser -u tak -- keytool`.
            run(f'runuser -u tak -- keytool -import -alias root-ca -file {cert_dir}/root-ca.pem '
                f'-keystore {ts_jks} -storepass {shlex.quote(cert_pass)} -noprompt 2>&1', check=False)
            log("  Root CA imported into new truststore")
            old_pem = os.path.join(cert_dir, f'{old_ca_name}.pem')
            try:
                prev_ts, prev_pass = _rotate_coreconfig_truststore(_read_priv('/opt/tak/CoreConfig.xml'))
            except Exception:
                prev_ts, prev_pass = '', ''
            if not prev_ts:
                prev_ts = os.path.join(cert_dir, f'truststore-{old_ca_name}.jks')
            live = _rotate_tak_live_certs_by_issuer()
            if live is None:
                log("  ⚠ Could not read TAK Server's certificate table; live cert counts unavailable")
            _rotate_carry_forward_truststore(ts_jks, prev_ts, prev_pass, cert_pass, old_ca_name, old_pem,
                                             live, run, _rotate_sh, log)
            log("✓ Truststore updated")

            log("")
            log("Step 6/7: Updating CoreConfig.xml...")
            # v10.0.5 non-root: sed isn't broker-routed + /opt/tak is tak:tak — rewrite
            # CoreConfig via broker read-modify-write.
            for _cc in ('/opt/tak/CoreConfig.xml', '/opt/tak/CoreConfig.example.xml'):
                try:
                    _t = _read_priv(_cc)
                    if old_ca_name in _t:
                        _write_priv(_cc, _t.replace(old_ca_name, new_ca_name))
                except Exception:
                    pass
            _patch_coreconfig_passwords(cert_pass, log_fn=log)
            log("✓ CoreConfig.xml updated")

            log("")
            log("Step 7/7: Updating TAK Portal certificates...")
            # v10.0.1: delegate to _takportal_sync_certs — refreshes client cert +
            # CA via a temp-file re-encode (the old stdin pipe failed on OpenSSL 3
            # and shipped an unreadable legacy cert). restart=True so the portal
            # picks up the new CA-signed cert.
            _tp_ok, _tp_msg = _takportal_sync_certs(plog=log, restart=True)
            log(f"  {'✓' if _tp_ok else '⚠'} TAK Portal cert sync: {_tp_msg}")

            log("")
            log("Restarting TAK Server...")
            ne_changed, ne_msg = _sanitize_coreconfig_name_entries()
            if ne_changed:
                log(f"  NameEntry fix: {ne_msg}")
            changed, resync_msg = _resync_ldap_credential_to_coreconfig()
            if changed:
                log(f"  LDAP resync: {resync_msg}")
            run('systemctl restart takserver 2>&1')
            log("  Waiting for TAK Server to come back up...")
            time.sleep(45)
            log("✓ TAK Server restarted")

            log("")
            log("Refreshing integrations that hold a client certificate...")
            _rotate_refresh_integrations(log)

            log("")
            log("━━━ ROTATION COMPLETE ━━━")
            log(f"  New CA: {new_ca_name}")
            log(f"  Server cert + all client certs signed by new CA")
            log(f"  Old CA ({old_ca_name}) and earlier CAs kept in truststore — server still accepts their client certs")
            log(f"  Existing ATAK clients must re-enroll (new QR) to get the new CA")
            log(f"  When everyone has re-enrolled, use 'Revoke Old CA' to remove {old_ca_name}")
            rotate_intca_status.update({'running': False, 'complete': True, 'error': False})
        except Exception as e:
            log(f"")
            log(f"✗ ROTATION FAILED: {e}")
            rotate_intca_status.update({'running': False, 'complete': True, 'error': True})

    import threading
    threading.Thread(target=do_rotate, daemon=True).start()
    return jsonify({'started': True, 'old_ca': old_ca_name, 'new_ca': new_ca_name})


@app.route('/api/takserver/rotate-intca/status')
@login_required
def takserver_rotate_intca_status():
    return jsonify({'log': rotate_intca_log, **rotate_intca_status})


@app.route('/api/takserver/revoke-old-ca', methods=['POST'])
@login_required
def takserver_revoke_old_ca():
    """Create new server cert (signed by current/new CA), remove old CA from truststore, restart. Cuts off clients with old certs."""
    data = request.json or {}
    old_ca_alias = (data.get('old_ca_alias') or '').strip()
    if not old_ca_alias:
        return jsonify({'error': 'Old CA alias is required'}), 400

    cert_dir = '/opt/tak/certs/files'
    cert_pass = _get_tak_cert_password(load_settings())
    # ops #174: delete from the truststore TAK Server enforces. The last name in sort order could
    # be a stale one, and a guess here removes a CA from the wrong file.
    ts_name = _live_truststore(cert_dir, '.jks')
    if not ts_name:
        return jsonify({'error': 'Could not tell which truststore TAK Server is using '
                                 '(CoreConfig.xml and ca.pem name none here). Nothing was changed.'}), 500
    ts_path = os.path.join(cert_dir, ts_name)

    try:
        # 1) Create new server cert (signed by current = new CA) so server presents new chain. Skip if using Let's Encrypt.
        le_jks = os.path.join(cert_dir, 'takserver-le.jks')
        if not os.path.isfile(le_jks):
            _tak_server_cert_prepare(load_settings())  # v10.2.26: real names, not just `takserver`
            r = subprocess.run(
                _rotate_tak_cert_cmd('cd /opt/tak/certs && echo "y" | runuser -u tak -- /opt/tak/certs/makeCert.sh server takserver 2>&1'),
                shell=True, capture_output=True, text=True, timeout=120)
            if r.returncode != 0:
                return jsonify({'error': f'Creating new server cert failed: {(r.stderr or r.stdout or "")[:200]}'}), 500
            # Build JKS from new takserver.p12 so server can use it (CoreConfig may reference takserver.jks or we update connector)
            p12 = os.path.join(cert_dir, 'takserver.p12')
            jks = os.path.join(cert_dir, 'takserver.jks')
            if os.path.isfile(p12):
                subprocess.run(
                    _rotate_tak_cert_cmd(
                        f'runuser -u tak -- keytool -importkeystore -srcstoretype PKCS12 -srckeystore {p12} -srcstorepass {shlex.quote(cert_pass)} '
                        f'-deststoretype JKS -destkeystore {jks} -deststorepass {shlex.quote(cert_pass)} -noprompt 2>&1'),
                    shell=True, capture_output=True, text=True, timeout=30)

        # 2) Remove old CA from truststore
        r = subprocess.run(
            _rotate_tak_cert_cmd(
                f'runuser -u tak -- keytool -delete -alias {shlex.quote(old_ca_alias)} '
                f'-keystore {shlex.quote(ts_path)} -storepass {shlex.quote(cert_pass)} 2>&1'),
            shell=True, capture_output=True, text=True, timeout=15)
        if r.returncode != 0:
            return jsonify({'error': f'keytool failed: {r.stderr or r.stdout}'}), 500

        # 3) Regenerate .p12 truststore
        ts_p12 = ts_path.replace('.jks', '.p12')
        subprocess.run(
            _rotate_tak_cert_cmd(
                f'runuser -u tak -- keytool -importkeystore -srckeystore {ts_path} -destkeystore {ts_p12} '
                f'-srcstoretype JKS -deststoretype PKCS12 -srcstorepass {shlex.quote(cert_pass)} -deststorepass {shlex.quote(cert_pass)} -noprompt 2>&1'),
            shell=True, capture_output=True, text=True, timeout=15)

        if _tak_is_container():
            subprocess.run(_sudo_wrap(['docker', 'restart', 'takserver']), stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True, timeout=120)
        else:
            subprocess.run(_sudo_wrap(['systemctl', 'restart', 'takserver']), stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True, timeout=90)

        # 4) Update TAK Portal certs so it can talk to TAK Server (new server cert / chain)
        # v10.0.1: delegate to _takportal_sync_certs (temp-file re-encode of the
        # client cert + CA; restart so the portal picks up the new chain).
        _takportal_sync_certs(restart=True)

        msg = (f'Removed {old_ca_alias} from truststore and restarted TAK Server. '
               f'Server cert is now signed by the new CA (clients who re-enrolled via CloudTAK/QR can connect). '
               f'TAK Portal certs updated. Clients still using certs signed by {old_ca_alias} must re-enroll.')
        if os.path.isfile(le_jks):
            msg = (f'Removed {old_ca_alias} from truststore and restarted TAK Server. '
                   f'(Server TLS is Let\'s Encrypt; unchanged.) Clients with certs signed by {old_ca_alias} must re-enroll.')
        return jsonify({'success': True, 'message': msg})
    except Exception as e:
        return jsonify({'error': str(e)[:200]}), 500


rotate_rootca_log = []
rotate_rootca_status = {'running': False, 'complete': False, 'error': False}

@app.route('/api/takserver/rotate-rootca', methods=['POST'])
@login_required
def takserver_rotate_rootca():
    """Full Root CA rotation: new root, new intermediate, new server cert, all client certs, update TAK Portal, restart."""
    if rotate_rootca_status.get('running'):
        return jsonify({'error': 'Root CA rotation already in progress'}), 409
    data = request.json or {}
    new_root_name = (data.get('new_root_name') or '').strip()
    new_int_name = (data.get('new_int_name') or '').strip()
    if not new_root_name or not new_int_name:
        return jsonify({'error': 'Both new Root CA and Intermediate CA names are required'}), 400
    import re
    for name in [new_root_name, new_int_name]:
        if not re.match(r'^[a-zA-Z0-9._-]+$', name):
            return jsonify({'error': f'CA name "{name}" can only contain letters, numbers, dots, hyphens, underscores'}), 400

    # Optional new cert password (save so thread uses it for new keystores)
    new_cert_password = (data.get('new_cert_password') or '').strip()
    if new_cert_password:
        settings = load_settings()
        settings['tak_cert_password'] = new_cert_password
        save_settings(settings)
    cert_pass = _get_tak_cert_password(load_settings())

    cert_dir = '/opt/tak/certs/files'
    if not os.path.exists(os.path.join(cert_dir, 'root-ca.pem')):
        return jsonify({'error': 'root-ca.pem not found — no current Root CA detected'}), 400

    # Detect current names
    old_root_name = ''
    old_int_name = ''
    for label, filename in [('root', 'root-ca.pem'), ('int', 'ca.pem')]:
        path = os.path.join(cert_dir, filename)
        if not os.path.exists(path):
            continue
        try:
            r = subprocess.run(['openssl', 'x509', '-subject', '-noout', '-in', path],
                               capture_output=True, text=True, timeout=5)
            for line in r.stdout.strip().split('\n'):
                if line.startswith('subject=') or line.startswith('subject ='):
                    subj = line.split('=', 1)[-1].strip()
                    for part in subj.split(','):
                        part = part.strip()
                        if part.startswith('CN') or part.startswith('CN '):
                            cn = part.split('=', 1)[-1].strip()
                            if label == 'root':
                                old_root_name = cn
                            else:
                                old_int_name = cn
        except Exception:
            pass
    if not old_root_name:
        return jsonify({'error': 'Could not detect current Root CA name'}), 500

    rotate_rootca_log.clear()
    rotate_rootca_status.update({'running': True, 'complete': False, 'error': False})

    def do_rotate_root():
        def log(msg):
            rotate_rootca_log.append(msg)

        def run(cmd, desc=None, check=True):
            if desc:
                log(desc)
            cmd = _rotate_tak_cert_cmd(cmd)  # v10.0.1: container-aware (runuser/chown/systemctl → docker)
            try:
                r = subprocess.run(cmd, shell=True, capture_output=True, text=True, timeout=120)
                if check and r.returncode != 0:
                    err = (r.stderr or r.stdout or '').strip()[:200]
                    log(f"  ✗ Failed (exit {r.returncode}): {err}")
                    return False
                return True
            except Exception as e:
                log(f"  ✗ Exception: {e}")
                return False

        try:
            log("━━━ Rotating Root CA ━━━")
            log(f"  Old Root CA: {old_root_name}")
            log(f"  Old Intermediate CA: {old_int_name}")
            log(f"  New Root CA: {new_root_name}")
            log(f"  New Intermediate CA: {new_int_name}")
            try:
                _ts, _ts_pass = _rotate_coreconfig_truststore(_read_priv('/opt/tak/CoreConfig.xml'))
            except Exception:
                _ts, _ts_pass = '', ''
            _live = _rotate_tak_live_certs_by_issuer()
            if _live is None:
                log("  ⚠ Could not read TAK Server's certificate table; live cert counts unavailable")
            _rotate_log_dropped_cas(_ts, _ts_pass or cert_pass, _live, _rotate_sh, log)
            log("")

            log("Step 1/8: Removing old certificate files...")
            if _tak_is_container():
                # v10.0.1: the cert files are owned by the container uid, so a HOST `rm -rf`
                # as takwerx SILENTLY fails and the old truststore-*.jks survives — then Step 6's
                # `keytool -import -alias root-ca` hits the existing `root-ca` alias and is dropped
                # (check=False), so the new ROOT CA never lands in the truststore and EUDs get
                # "cert not trusted". Clear the dir INSIDE the container (root there) so the
                # rotation starts from a clean slate, exactly like the native rm does. The native
                # branch below is byte-identical to before — Ubuntu/Rocky are untouched.
                _tak_real = os.path.realpath('/opt/tak')
                run(f"docker run --rm -v {shlex.quote(_tak_real)}:/opt/tak:z --entrypoint bash "
                    f"{TAK_CONTAINER} -c 'rm -rf /opt/tak/certs/files && mkdir -p /opt/tak/certs/files' 2>&1")
            else:
                run('rm -rf /opt/tak/certs/files')
                run('mkdir -p /opt/tak/certs/files')
                run('chown -R tak:tak /opt/tak/certs/')
            log("✓ Old cert files cleared")

            _patch_openssl_string_mask()

            log("")
            log(f"Step 2/8: Creating new Root CA: {new_root_name}...")
            run('chown tak:tak /opt/tak/certs/cert-metadata.sh && chmod 500 /opt/tak/certs/cert-metadata.sh')
            _patch_cert_metadata_password(cert_pass)
            if not run(f'cd /opt/tak/certs && echo "{new_root_name}" | runuser -u tak -- /opt/tak/certs/makeRootCa.sh 2>&1'):
                raise Exception('Failed to create new Root CA')
            log(f"✓ Root CA {new_root_name} created")

            log("")
            log(f"Step 3/8: Creating new Intermediate CA: {new_int_name}...")
            if not run(f'cd /opt/tak/certs && echo "y" | runuser -u tak -- /opt/tak/certs/makeCert.sh ca "{new_int_name}" 2>&1'):
                raise Exception('Failed to create new Intermediate CA')
            log(f"✓ Intermediate CA {new_int_name} created")

            log("")
            log("Step 4/8: Creating new server certificate...")
            _tak_server_cert_prepare(load_settings(), log)  # v10.2.26: real names, not just `takserver`
            if not run('cd /opt/tak/certs && echo "y" | runuser -u tak -- /opt/tak/certs/makeCert.sh server takserver 2>&1'):
                raise Exception('Failed to create server certificate')
            log("✓ Server certificate created")

            log("")
            log("Step 5/8: Regenerating all client certificates...")
            skip = {'takserver', 'root-ca', 'ca', new_root_name.lower(), new_int_name.lower(),
                    old_root_name.lower(), old_int_name.lower()}
            # We need to create admin and user first since old files were cleared
            run('cd /opt/tak/certs && runuser -u tak -- /opt/tak/certs/makeCert.sh client admin 2>&1')
            log("  Regenerated: admin")
            run('cd /opt/tak/certs && runuser -u tak -- /opt/tak/certs/makeCert.sh client user 2>&1')
            log("  Regenerated: user")
            # Check settings or old backup for any other client cert names to recreate
            regen_count = 2
            log(f"✓ {regen_count} client certificate(s) created")
            log("  Note: Additional client certs (Node-RED, etc.) must be recreated manually")

            log("")
            log("Step 6/8: Updating truststore...")
            ts_jks = os.path.join(cert_dir, f'truststore-{new_int_name}.jks')
            # v10.0.5 non-root: route keytool via broker-allowed `runuser -u tak -- keytool`.
            run(f'runuser -u tak -- keytool -import -alias root-ca -file {cert_dir}/root-ca.pem '
                f'-keystore {ts_jks} -storepass {shlex.quote(cert_pass)} -noprompt 2>&1', check=False)
            log("  Root CA imported into truststore")
            log("✓ Truststore updated")

            log("")
            log("Step 7/8: Updating CoreConfig.xml...")
            # v10.0.5 non-root: sed isn't broker-routed + /opt/tak is tak:tak — rewrite
            # CoreConfig via broker read-modify-write.
            _repl = []
            if old_int_name:
                _repl.append((old_int_name, new_int_name))
            if old_root_name and old_root_name != new_root_name:
                _repl.append((old_root_name, new_root_name))
            for _cc in ('/opt/tak/CoreConfig.xml', '/opt/tak/CoreConfig.example.xml'):
                try:
                    _t = _read_priv(_cc); _orig = _t
                    for _o, _n in _repl:
                        _t = _t.replace(_o, _n)
                    if _t != _orig:
                        _write_priv(_cc, _t)
                except Exception:
                    pass
            _patch_coreconfig_passwords(cert_pass, log_fn=log)
            log("✓ CoreConfig.xml updated")

            log("")
            log("Step 8/8: Restarting TAK Server and updating TAK Portal...")
            ne_changed, ne_msg = _sanitize_coreconfig_name_entries()
            if ne_changed:
                log(f"  NameEntry fix: {ne_msg}")
            changed, resync_msg = _resync_ldap_credential_to_coreconfig()
            if changed:
                log(f"  LDAP resync: {resync_msg}")
            run('systemctl restart takserver 2>&1')
            log("  TAK Server restarting...")

            # Copy new certs to TAK Portal if it's running
            portal_running = _takportal_web_running()
            if portal_running:
                log("  Updating TAK Portal certificates...")
                # v10.0.1: delegate to _takportal_sync_certs — temp-file re-encode
                # of the client cert + CA (the old stdin pipe failed on OpenSSL 3
                # and shipped an unreadable legacy cert). restart=True.
                _tp_ok, _tp_msg = _takportal_sync_certs(plog=log, restart=True)
                log(f"  {'✓' if _tp_ok else '⚠'} TAK Portal cert sync: {_tp_msg}")
            else:
                log("  TAK Portal not running — skip cert copy (will update on next TAK Portal deploy)")

            log("  Waiting for TAK Server to come back up...")
            time.sleep(45)
            log("✓ TAK Server restarted")

            log("")
            log("━━━ ROOT CA ROTATION COMPLETE ━━━")
            log(f"  New Root CA: {new_root_name}")
            log(f"  New Intermediate CA: {new_int_name}")
            log(f"  All certificates have been regenerated")
            if portal_running:
                log(f"  TAK Portal updated — users can scan new QR codes to re-enroll")
            log(f"  All existing client connections are disconnected")
            log(f"  Clients must re-enroll via TAK Portal QR code")
            rotate_rootca_status.update({'running': False, 'complete': True, 'error': False})
        except Exception as e:
            log(f"")
            log(f"✗ ROOT CA ROTATION FAILED: {e}")
            rotate_rootca_status.update({'running': False, 'complete': True, 'error': True})

    import threading
    threading.Thread(target=do_rotate_root, daemon=True).start()
    return jsonify({'started': True, 'old_root': old_root_name, 'new_root': new_root_name})


@app.route('/api/takserver/rotate-rootca/status')
@login_required
def takserver_rotate_rootca_status():
    return jsonify({'log': rotate_rootca_log, **rotate_rootca_status})


@app.route('/api/takserver/server-cert')
@login_required
def takserver_server_cert_status():
    """v10.2.26 — the TAK Server page's certificate row: live names vs. this box's names,
    plus the Fix job's progress. No live probe while the job runs (TAK is restarting)."""
    job = {k: tak_server_cert_job[k] for k in ('running', 'complete', 'error')}
    job['elapsed'] = int(time.time() - tak_server_cert_job['started']) if tak_server_cert_job['started'] else 0
    job['log'] = list(tak_server_cert_job['log'])
    if tak_server_cert_job['running']:
        return jsonify({'job': job, 'status': None})
    return jsonify({'job': job,
                    'status': _tak_server_cert_status_remember(_tak_server_cert_status(load_settings()))})


@app.route('/api/takserver/server-cert/fix', methods=['POST'])
@login_required
def takserver_server_cert_fix():
    """v10.2.26 — reissue TAK Server's certificate with this box's names, same CA.

    Backs up takserver.{pem,key,p12,jks,csr}, writes the names into certs/config.cfg, reissues
    through the stock makeCert.sh, checks the new file carries every name, restarts TAK and
    waits until the LIVE cert does. Any failure before the restart puts the old files back
    untouched; a TAK that doesn't come back presenting the new cert gets the old one restored
    and restarted. Enrolled devices trust the CA, not this cert, so nobody re-enrolls."""
    if not os.path.exists('/opt/tak/certs/makeCert.sh'):
        return jsonify({'success': False, 'error': 'TAK Server not installed'}), 400
    data = request.get_json(silent=True) or {}
    if mod_registry._check_admin_password({'load_auth': load_auth,
                                           'verify_password': verify_password}, data):
        return jsonify({'success': False, 'error': 'Incorrect console password.',
                        'need_password': True}), 403
    if (tak_server_cert_job['running'] or rotate_rootca_status.get('running')
            or rotate_intca_status.get('running')):
        return jsonify({'success': False, 'error': 'A certificate operation is already running.'}), 409
    settings = load_settings()
    want = _tak_server_cert_names(settings)
    tak_server_cert_job.update(running=True, complete=False, error=False, log=[], started=time.time())

    def do_fix():
        log = tak_server_cert_job['log'].append
        cert_dir = '/opt/tak/certs/files'
        stamp = time.strftime('%Y%m%d-%H%M%S')
        files = [f'{cert_dir}/takserver.{ext}' for ext in ('pem', 'key', 'p12', 'jks', 'csr')]
        backed = []

        # The same shell-string runner the CA rotations use: _rotate_reissue_cert() hands it
        # `cd … && echo "y" | runuser -u tak -- makeCert.sh …` and mv/rm/cp strings. NOT
        # _rotate_sh(): ops #163 made that one argv-only (`runuser -u tak -- <argv>`), so a
        # string reached runuser one character at a time — "runuser: failed to execute c"
        # on test12, 2026-10-22 (the backup step refused, nothing changed).
        def run(cmd, check=True):
            cmd = _rotate_tak_cert_cmd(cmd)  # v10.0.1: container-aware (runuser/chown/systemctl → docker)
            try:
                r = subprocess.run(cmd, shell=True, capture_output=True, text=True, timeout=120)
                if check and r.returncode != 0:
                    log(f"  ✗ {(r.stderr or r.stdout or '').strip()[:200]}")
                    return False
                return True
            except Exception as e:
                log(f"  ✗ {str(e)[:200]}")
                return False

        def restore():
            ok = all(run(f'cp -p {shlex.quote(p + "." + stamp)} {shlex.quote(p)}') for p in backed)
            log("  ✓ Previous certificate restored" if ok else "  ✗ Restore incomplete — backups are "
                f"{cert_dir}/takserver.*.{stamp}")
            return ok

        def wait_live(seconds):
            end = time.time() + seconds
            live = None
            while time.time() < end:
                time.sleep(5)
                live = _tak_server_cert_live_names()
                if live is not None and all(n in live for n in want):
                    return live
            return live

        try:
            log("━━━ Fixing TAK Server's certificate names ━━━")
            log("Step 1/4: Backing up the current server certificate...")
            for p in files:
                if _exists_priv(p):
                    if not run(f'cp -p {shlex.quote(p)} {shlex.quote(p + "." + stamp)}'):
                        raise Exception('Backup failed — nothing was changed')
                    backed.append(p)
            log(f"  ✓ Saved as {cert_dir}/takserver.*.{stamp}")

            log("Step 2/4: Writing this server's names into the certificate config...")
            if not _tak_server_cert_prepare(settings, log):
                raise Exception('Could not write the names — nothing was changed')

            log("Step 3/4: Reissuing the server certificate (same CA)...")
            if not _rotate_reissue_cert('server', 'takserver', run, cert_dir):
                restore()
                raise Exception('makeCert.sh failed')
            got = _cert_san_entries(_read_priv(f'{cert_dir}/takserver.pem')) or []
            short = [n.split(':', 1)[1] for n in want if n not in got]
            if short:
                restore()
                raise Exception('The new certificate is missing ' + ', '.join(short))
            log("  ✓ New certificate carries: " + ', '.join(n.split(':', 1)[1] for n in got))

            log("Step 4/4: Restarting TAK Server (devices reconnect on their own)...")
            if not run('systemctl restart takserver 2>&1'):
                restore()
                run('systemctl restart takserver 2>&1')
                raise Exception('TAK Server restart failed')
            live = wait_live(300)
            if live is None or not all(n in live for n in want):
                log("  ✗ TAK Server didn't come back presenting the new certificate within 5 minutes")
                restore()
                run('systemctl restart takserver 2>&1')
                raise Exception('TAK Server did not pick up the new certificate')
            log("  ✓ TAK Server is presenting the new certificate")
            _tak_server_cert_status_remember(_tak_server_cert_status(settings))
            log("")
            log("━━━ DONE ━━━")
            tak_server_cert_job.update(running=False, complete=True, error=False)
        except Exception as e:
            log("")
            log(f"✗ FAILED: {e}")
            tak_server_cert_job.update(running=False, complete=True, error=True)

    threading.Thread(target=do_fix, daemon=True).start()
    return jsonify({'success': True, 'started': True})


@app.route('/api/takserver/create-client-cert', methods=['POST'])
@login_required
def takserver_create_client_cert():
    """Create a client certificate with optional group assignment."""
    data = request.json or {}
    cert_name = (data.get('name') or '').strip()
    if not cert_name:
        return jsonify({'error': 'Certificate name is required'}), 400
    import re
    if not re.match(r'^[a-zA-Z0-9._-]+$', cert_name):
        return jsonify({'error': 'Name can only contain letters, numbers, dots, hyphens, underscores'}), 400
    if len(cert_name) > 64:
        return jsonify({'error': 'Name too long (max 64 chars)'}), 400

    cert_dir = '/opt/tak/certs/files'
    # ops #169: makeCert.sh client NAME writes NAME.key/.pem/.p12 over whatever is there, so a
    # name that is a CA's (ca, INT-CA-09, …-signing, …-do-not-share) would overwrite CA files.
    if (cert_name in _NOT_CLIENT_CERT_NAMES or _is_ca_private_material(f'{cert_name}.p12')
            or cert_name.lower().startswith('truststore-')):
        return jsonify({'error': f'"{cert_name}" is reserved for TAK Server and CA files'}), 400
    if any(os.path.exists(os.path.join(cert_dir, f'{cert_name}{ext}')) for ext in ('.p12', '.pem', '.key')):
        return jsonify({'error': f'Certificate "{cert_name}" already exists'}), 400

    def _normalize_groups(values):
        out = []
        seen = set()
        for v in (values or []):
            g = _canonical_tak_group_name(v)
            if not g:
                continue
            key = g.lower()
            if key in seen:
                continue
            seen.add(key)
            out.append(g)
        return out

    groups_in = _normalize_groups(data.get('groups_in', []))
    groups_out = _normalize_groups(data.get('groups_out', []))
    groups_both = _normalize_groups(data.get('groups_both', []))
    groups_in = [g for g in groups_in if g not in groups_both]
    groups_out = [g for g in groups_out if g not in groups_both]

    try:
        _patch_openssl_string_mask()
        _cert_metadata_prepare_for_makecert()
        r = subprocess.run(
            _rotate_tak_cert_cmd(f'cd /opt/tak/certs && runuser -u tak -- /opt/tak/certs/makeCert.sh client {cert_name} 2>&1'),
            shell=True, capture_output=True, text=True, timeout=30
        )
        if r.returncode != 0:
            return jsonify({'error': f'makeCert.sh failed: {r.stdout or r.stderr}'}), 500

        p12_path = os.path.join(cert_dir, f'{cert_name}.p12')
        if not os.path.exists(p12_path):
            return jsonify({'error': 'Certificate file was not created'}), 500

        group_warning = ''
        if groups_in or groups_out or groups_both:
            pem_path = os.path.join(cert_dir, f'{cert_name}.pem')
            argv = ['java', '-jar', '/opt/tak/utils/UserManager.jar', 'certmod']
            for g in groups_both:
                argv += ['-g', g]
            for g in groups_in:
                argv += ['-ig', g]
            for g in groups_out:
                argv += ['-og', g]
            argv.append(pem_path)
            # v10.0.1 container: java + UserManager.jar live ONLY inside the takserver container
            # (no host JDK), so run the group-assignment in-container (the same `docker exec ...
            # bash -c` form _tak_exec() builds). v10.2.26: an argv list with no host shell, so a
            # group name is always one word and never re-parsed.
            full = (['docker', 'exec', TAK_CONTAINER, 'bash', '-c', shlex.join(argv)]
                    if _tak_is_container() else argv)
            # v10.2.26: 15 s was a JVM start on an idle box. test12 under load took 16.1 s, the
            # TimeoutExpired fell to the outer except and the page said the create FAILED while
            # the cert existed with no groups. Give it room, and when the groups don't land, say
            # exactly that next to a cert that was created.
            try:
                gr = subprocess.run(full, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True, timeout=120)
                if gr.returncode != 0:
                    group_warning = ('Certificate created, but TAK Server did not accept the group '
                                     f'assignment: {(gr.stdout or "").strip()[-200:]}')
            except subprocess.TimeoutExpired:
                group_warning = ('Certificate created, but assigning its groups took over 2 minutes '
                                 'and was stopped. Assign the groups in TAK Server before using it.')

        return jsonify({
            'success': True,
            'name': cert_name,
            'p12': f'{cert_name}.p12',
            'download_url': f'/api/certs/download/{cert_name}.p12',
            'groups_both': groups_both,
            'groups_in': groups_in,
            'groups_out': groups_out,
            'package_url': f'/api/takserver/client-cert/{cert_name}/package',
            'group_warning': group_warning,
        })
    except Exception as e:
        return jsonify({'error': str(e)[:200]}), 500


# v10.2.26 W5 — integration package. A third-party system (cUAS cloud, CAD, SIEM) needs PEM
# files and a "trust this server" CA file, not the one TAK-format .p12 the console used to hand
# out. Cert-only by design: the groups are the ones put on the cert at creation, as Create
# Client Certificate always did — no Authentik user, no data feed.
_CERT_FILES_DIR = '/opt/tak/certs/files'
_CLIENT_CERT_NAME_RE = re.compile(r'^[A-Za-z0-9._-]{1,64}$')
_NOT_CLIENT_CERT_NAMES = {'takserver', 'ca', 'root-ca'}


def _cert_file_bytes(path):
    """A file from the TAK cert dir. Client .p12/.key are 0600 tak:tak, so a non-root console
    takes the privileged read when the plain one is refused (same as the .p12 download)."""
    try:
        with open(path, 'rb') as f:
            return f.read()
    except PermissionError:
        return _read_priv_bytes(path)


def _is_int_truststore(f, ext='.p12'):
    return f.startswith('truststore-') and f.endswith(ext) and 'root' not in f


def _live_truststore(cert_dir=None, ext='.p12'):
    """The truststore-<CA><ext> (.p12 or .jks) of the intermediate TAK Server uses now, or ''.
    ops #170: Rotate CA leaves every earlier truststore-INT-CA-NN.p12 behind, and taking the
    first one alphabetically handed out INT-CA-01 on a box running INT-CA-14. CoreConfig's
    <tls> truststoreFile names the live CA, ca.pem's CN is the fallback, and a lone candidate
    is unambiguous. Between several, never guess. ops #174: the CA-info panel and Revoke Old
    CA take the .jks from here too, so a revoke never edits a stale truststore."""
    d = cert_dir or _CERT_FILES_DIR
    try:
        have = set(os.listdir(d))
    except OSError:
        return ''
    wanted = []
    try:
        ts, _pass = _rotate_coreconfig_truststore(_read_priv('/opt/tak/CoreConfig.xml'))
        base = os.path.basename(ts)
        if base.endswith('.jks'):
            wanted.append(base[:-4] + ext)
    except Exception:
        pass
    try:
        cn, _end = _pem_cn_and_expiry(_cert_file_bytes(os.path.join(d, 'ca.pem')).decode(errors='replace'))
        if cn:
            wanted.append(f'truststore-{cn}{ext}')
    except Exception:
        pass
    for f in wanted:
        if f in have and _is_int_truststore(f, ext):
            return f
    cands = [f for f in have if _is_int_truststore(f, ext)]
    return cands[0] if len(cands) == 1 else ''


def _is_client_cert_pem(pem):
    """True only for a leaf client cert: CA:FALSE and clientAuth WITHOUT serverAuth. The server
    cert (both EKUs), the CAs and anything unreadable are refused."""
    try:
        r = subprocess.run(['openssl', 'x509', '-noout', '-ext', 'basicConstraints,extendedKeyUsage'],
                           input=pem, capture_output=True, text=True, timeout=10)
    except Exception:
        return False
    out = r.stdout
    return (r.returncode == 0 and 'CA:FALSE' in out and 'TLS Web Client Authentication' in out
            and 'TLS Web Server Authentication' not in out)


def _client_cert_pem_or_none(name):
    if name in _NOT_CLIENT_CERT_NAMES or not _CLIENT_CERT_NAME_RE.match(name or ''):
        return None
    # ops #169: a CA:FALSE leaf left as INT-CA-NN-signing.pem/.key by the old Rotate CA bug
    # passed the leaf test, and the package then zipped INT-CA-NN-signing.p12 — the CA's own
    # signing keystore. Any name whose .p12 is CA material is never a client cert here.
    if _is_ca_private_material(f'{name}.p12'):
        return None
    try:
        pem = _cert_file_bytes(os.path.join(_CERT_FILES_DIR, f'{name}.pem')).decode(errors='replace')
    except Exception:
        return None
    return pem if _is_client_cert_pem(pem) else None


def _cert_pubkey(pem):
    """The public key of a PEM certificate, or b'' when it can't be read."""
    try:
        r = subprocess.run(['openssl', 'x509', '-noout', '-pubkey'], input=pem.encode(),
                           capture_output=True, timeout=10)
    except Exception:
        return b''
    return r.stdout.strip() if r.returncode == 0 else b''


def _private_key_pubkey(data, password, p12=False):
    """The public half of the private key in a PEM .key, or in a .p12 holding exactly one key.
    b'' when it can't be read — the caller treats that as "does not match". The password
    travels in the environment, never argv."""
    import tempfile as _tf
    env = dict(os.environ, ITK_P12_PASS=password or '')
    try:
        with _tf.TemporaryDirectory(prefix='itk-keychk-') as td:
            os.chmod(td, 0o700)
            path = os.path.join(td, 'in')
            with open(os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600), 'wb') as f:
                f.write(data)
            if not p12:
                r = subprocess.run(['openssl', 'pkey', '-in', path, '-passin', 'env:ITK_P12_PASS', '-pubout'],
                                   capture_output=True, env=env, timeout=10)
                return r.stdout.strip() if r.returncode == 0 else b''
            # makeCert.sh writes RC2-40 .p12, which OpenSSL 3 opens only with -legacy.
            for extra in ([], ['-legacy']):
                r = subprocess.run(['openssl', 'pkcs12', '-in', path, '-nocerts', '-nodes',
                                    '-passin', 'env:ITK_P12_PASS'] + extra,
                                   capture_output=True, env=env, timeout=10)
                if r.returncode == 0 and b'PRIVATE KEY-----' in r.stdout:
                    break
            else:
                return b''
            if r.stdout.count(b'-----BEGIN ') != 1:
                return b''
            r = subprocess.run(['openssl', 'pkey', '-pubout'], input=r.stdout, capture_output=True, timeout=10)
            return r.stdout.strip() if r.returncode == 0 else b''
    except Exception:
        return b''


def _modern_p12(pem_path, key_path, chain_pem, name, password):
    """Re-wrap the client cert + key as a PKCS#12 OpenSSL 3, Node and Python can open.

    makeCert.sh writes .p12 as pbeWithSHA1And40BitRC2-CBC (ATAK needs it), which modern stacks
    refuse ("RC2-40-CBC unsupported"). OpenSSL 3's export defaults are AES-256-CBC + PBKDF2 +
    SHA-256 MAC. The password travels in the environment, never argv. Returns bytes or None."""
    import tempfile as _tf
    try:
        with _tf.TemporaryDirectory(prefix='itk-p12-') as td:
            os.chmod(td, 0o700)
            key_tmp, pem_tmp, chain_tmp = (os.path.join(td, n) for n in ('k', 'c', 'ca'))
            for p, data in ((key_tmp, _cert_file_bytes(key_path)), (pem_tmp, _cert_file_bytes(pem_path)),
                            (chain_tmp, chain_pem.encode())):
                with open(os.open(p, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600), 'wb') as f:
                    f.write(data)
            env = dict(os.environ, ITK_P12_PASS=password)
            r = subprocess.run(['openssl', 'pkcs12', '-export', '-in', pem_tmp, '-inkey', key_tmp,
                                '-certfile', chain_tmp, '-name', name,
                                '-passin', 'env:ITK_P12_PASS', '-passout', 'env:ITK_P12_PASS'],
                               capture_output=True, env=env, timeout=20)
            return r.stdout if r.returncode == 0 and r.stdout else None
    except Exception:
        return None


@app.route('/api/takserver/client-certs')
@login_required
def takserver_client_certs():
    """v10.2.26 W5 — client certs an integration package can be built for."""
    try:
        files = sorted(os.listdir(_CERT_FILES_DIR))
    except OSError:
        return jsonify({'certs': []})
    have = set(files)
    names = [f[:-4] for f in files
             if f.endswith('.pem') and not f.endswith('-trusted.pem')
             and f'{f[:-4]}.key' in have and _client_cert_pem_or_none(f[:-4])]
    return jsonify({'certs': names})


@app.route('/api/takserver/client-cert/<name>/package')
@login_required
def takserver_client_cert_package(name):
    """v10.2.26 W5 — <name>-integration.zip: the client cert in every form a third-party system
    asks for, this server's CA as plain PEM, and a README. The cert password is deliberately NOT
    in the zip — it is shown beside the button for the operator to send separately."""
    from flask import send_file
    import io
    import zipfile
    pem = _client_cert_pem_or_none(name)
    if not pem:
        return jsonify({'error': f'"{name}" is not a client certificate on this server'}), 404
    d = _CERT_FILES_DIR
    try:
        key = _cert_file_bytes(os.path.join(d, f'{name}.key'))
        ca = _cert_file_bytes(os.path.join(d, 'ca.pem')).decode(errors='replace')
    except Exception as e:
        return jsonify({'error': f'Could not read the certificate files: {str(e)[:160]}'}), 500
    try:
        root = _cert_file_bytes(os.path.join(d, 'root-ca.pem')).decode(errors='replace')
    except Exception:
        root = ''
    chain = ca.strip() + '\n' + (root.strip() + '\n' if root.strip() and root.strip() != ca.strip() else '')
    settings = load_settings()
    password = _get_tak_cert_password(settings)
    # ops #169: only private keys that belong to THIS cert go in the zip. A .key or .p12 sitting
    # next to the .pem under the same name is not proof — check the key against the cert.
    pub = _cert_pubkey(pem)
    if not pub or _private_key_pubkey(key, password) != pub:
        audit('integration_package_refused', f'cert={name} reason=key-mismatch')
        return jsonify({'error': f'The private key for "{name}" does not match its certificate; '
                                 'no package was built'}), 409
    try:
        legacy_p12 = _cert_file_bytes(os.path.join(d, f'{name}.p12'))
    except Exception:
        legacy_p12 = b''
    if legacy_p12 and _private_key_pubkey(legacy_p12, password, p12=True) != pub:
        audit('integration_package_p12_skipped', f'cert={name} reason=key-mismatch')
        legacy_p12 = b''
    trust = _live_truststore(d)
    try:
        trust_p12 = _cert_file_bytes(os.path.join(d, trust)) if trust else b''
    except Exception:
        trust_p12 = b''
    modern_p12 = _modern_p12(os.path.join(d, f'{name}.pem'), os.path.join(d, f'{name}.key'),
                             chain, name, password)
    host = _get_takserver_host(settings) or (settings.get('server_ip') or '').strip() or '<this server>'

    files = []  # (zip name, bytes, README line)
    if modern_p12:
        files.append((f'{name}.p12', modern_p12, 'Client certificate + private key (PKCS#12 / .pfx, AES-256).'
                                                 ' Use this if your system takes a .p12 or .pfx.'))
    if legacy_p12:
        files.append((f'{name}-legacy.p12' if modern_p12 else f'{name}.p12', legacy_p12,
                      'The same, in the older RC2 format TAK clients (ATAK) and older systems expect.'))
    files += [(f'{name}.pem', pem.encode(), 'Client certificate (PEM).          } use these two if your system wants'),
              (f'{name}.key', key, 'Client private key (PEM, encrypted). } separate certificate and key files'),
              ('ca-chain.pem', chain.encode(), "This server's certificate authority (PEM). Add it as the trusted /"
                                               ' server CA so your system trusts TAK Server.')]
    if trust_p12:
        files.append((trust, trust_p12, 'The same CA as a PKCS#12 truststore, for TAK clients that ask for one.'))
    w = max(len(f[0]) for f in files)
    readme = '\n'.join(
        [f'TAK Server integration package: {name}',
         f'Created {datetime.utcnow().strftime("%Y-%m-%d %H:%M")} UTC by infra-TAK v{VERSION}', '',
         f'Server:  {host}',
         'Port:    8089 (TLS, client certificate required)', '', 'Files:']
        + [f'  {fn.ljust(w)}  {line}' for fn, _b, line in files]
        + ['', 'Password: the .p12 files and the .key are protected with the TAK certificate password.',
           'It is not included in this package; get it from your TAK Server administrator.', ''])
    buf = io.BytesIO()
    with zipfile.ZipFile(buf, 'w', zipfile.ZIP_DEFLATED) as z:
        for fn, data, _line in files:
            z.writestr(fn, data)
        z.writestr('README.txt', readme)
    audit('integration_package', f'cert={name} files={",".join(f[0] for f in files)}')
    buf.seek(0)
    return send_file(buf, as_attachment=True, download_name=f'{name}-integration.zip',
                     mimetype='application/zip')


def _sync_webadmin_after_authentik_reconfigure(plog):
    """After Authentik reconfigure, regenerate Caddyfile and reload Caddy. Does NOT touch TAK Server or 8446 cert."""
    modules = detect_modules(fresh=True)
    if not modules.get('takserver', {}).get('installed'):
        return
    try:
        plog("  Syncing WebAdmin (Caddy reload only, no TAK restart)...")
        settings = load_settings()
        generate_caddyfile(settings)
        _caddy_reload()
        plog("  ✓ Caddy reloaded.")
    except Exception as e:
        plog(f"  ⚠ WebAdmin sync failed: {str(e)[:80]} — run Update config on TAK Server page if needed.")


def _run_takserver_update_config():
    """Regenerate Caddyfile, reload Caddy, re-install 8446 LE cert for current TAK Server hostname, restart TAK Server."""
    settings = load_settings()
    fqdn = settings.get('fqdn', '').strip()
    generate_caddyfile(settings)
    _caddy_reload()
    takserver_host = _get_service_domain(settings, 'takserver')
    if fqdn and takserver_host:
        caddy_active = subprocess.run(_sudo_wrap(['systemctl', 'is-active', 'caddy']), capture_output=True, text=True)
        if caddy_active.stdout.strip() == 'active':
            def _log(msg):
                print(msg, flush=True)
            install_le_cert_on_8446(takserver_host, _log, wait_for_cert=False)
    subprocess.run(_tak_systemctl('restart'), shell=True, capture_output=True, text=True, timeout=60)  # v10.0.1: container-aware
    takserver_update_config_status.update({'running': False, 'complete': True, 'error': False})

takserver_update_config_status = {'running': False, 'complete': False, 'error': False}

@app.route('/api/takserver/update-config', methods=['POST'])
@login_required
def takserver_update_config():
    """Sync Caddy + 8446 cert to current TAK Server domain and restart TAK Server. Use after changing TAK Server domain in Caddy/Domains."""
    if takserver_update_config_status.get('running'):
        return jsonify({'error': 'Update already in progress'}), 409
    modules = detect_modules(fresh=True)
    tak = modules.get('takserver', {})
    if not tak.get('installed'):
        return jsonify({'error': 'TAK Server not installed'}), 400
    takserver_update_config_status.update({'running': True, 'complete': False, 'error': False})
    def _run():
        try:
            _run_takserver_update_config()
        except Exception as e:
            takserver_update_config_status.update({'running': False, 'complete': True, 'error': True, 'message': str(e)[:200]})
    threading.Thread(target=_run, daemon=True).start()
    return jsonify({'success': True, 'message': 'Update config started. Caddy and 8446 cert (if applicable) will be updated; TAK Server will restart.'})

@app.route('/api/takserver/update-config/status')
@login_required
def takserver_update_config_status_api():
    return jsonify(takserver_update_config_status)

@app.route('/api/takserver/control', methods=['POST'])
@login_required
def takserver_control():
    action = request.json.get('action')
    target = request.json.get('target', 'core')  # core | database | both
    if action not in ['start', 'stop', 'restart']:
        return jsonify({'error': 'Invalid action'}), 400
    results = {}
    settings = load_settings()
    tak_cfg = _get_tak_deployment_config(settings)
    is_two_server = tak_cfg.get('mode') == 'two_server'
    # Handle remote database (Server One)
    if is_two_server and target in ('database', 'both'):
        s1 = tak_cfg.get('server_one', {})
        if s1.get('host'):
            pg_action = 'restart' if action == 'restart' else action
            db_cmd = f'sudo pg_ctlcluster 15 main {pg_action} 2>&1 || sudo systemctl {pg_action} postgresql 2>&1'
            ok, out = _ssh_probe(s1, db_cmd, timeout=30)
            verify_ok, verify_out = _ssh_probe(s1, 'pg_isready -q && echo DB_OK', timeout=10)
            db_running = verify_ok and 'DB_OK' in (verify_out or '')
            results['database'] = {'success': ok or db_running, 'running': db_running, 'host': s1['host']}
        else:
            results['database'] = {'success': False, 'error': 'Server One host not configured'}
    # Handle local TAK Server (Core)
    if target in ('core', 'both'):
        if action in ('start', 'restart'):
            ne_changed, ne_msg = _sanitize_coreconfig_name_entries()
            if ne_changed:
                results['nameentry_fix'] = ne_msg
            changed, msg = _resync_ldap_credential_to_coreconfig()
            if changed:
                results['ldap_resync'] = msg
        # v10.0.1: container-aware lifecycle — _tak_systemctl maps start/stop/
        # restart to `docker ...` in container mode (native systemctl on .deb).
        subprocess.run(_tak_systemctl(action), shell=True, capture_output=True, text=True, timeout=120)
        time.sleep(3)
        results['core'] = {'success': True, 'running': _takserver_running_local()}
    return jsonify({'success': True, 'results': results, 'action': action, 'target': target,
                    'running': results.get('core', {}).get('running', None)})

@app.route('/api/takserver/log')
@login_required
def takserver_log():
    """Tail the takserver-messaging.log file"""
    log_path = '/opt/tak/logs/takserver-messaging.log'
    offset = request.args.get('offset', 0, type=int)
    lines = request.args.get('lines', 100, type=int)
    if not os.path.exists(log_path):
        return jsonify({'entries': [], 'offset': 0, 'size': 0})
    try:
        size = os.path.getsize(log_path)
        if offset == 0:
            r = subprocess.run(f'tail -n {lines} "{log_path}"', shell=True, capture_output=True, text=True, timeout=10)
            entries = r.stdout.strip().split('\n') if r.stdout.strip() else []
            return jsonify({'entries': entries, 'offset': size, 'size': size})
        elif size > offset:
            with open(log_path, 'r') as f:
                f.seek(offset)
                new_data = f.read()
            entries = new_data.strip().split('\n') if new_data.strip() else []
            return jsonify({'entries': entries, 'offset': size, 'size': size})
        else:
            return jsonify({'entries': [], 'offset': offset, 'size': size})
    except Exception as e:
        return jsonify({'entries': [f'Error reading log: {str(e)[:200]}'], 'offset': offset, 'size': 0})

@app.route('/api/takserver/services')
@login_required
def takserver_services():
    """Get TAK Server Java process status"""
    services = []
    try:
        r = subprocess.run("ps aux | grep java | grep -v grep", shell=True, capture_output=True, text=True, timeout=10)
        seen = {}
        for line in r.stdout.strip().split('\n'):
            if not line.strip(): continue
            parts = line.split()
            if len(parts) < 11: continue
            pid = parts[1]
            cpu = parts[2]
            mem_pct = parts[3]
            rss_kb = int(parts[5])
            mem_mb = round(rss_kb / 1024)
            cmd = ' '.join(parts[10:])
            # Identify the service
            if 'profiles.active=messaging' in cmd:
                name = 'Messaging'; icon = '📡'
            elif 'profiles.active=api' in cmd:
                name = 'API'; icon = '🧩'
            elif 'profiles.active=config' in cmd:
                name = 'Config'; icon = '⚙️'
            elif 'takserver-pm.jar' in cmd:
                name = 'Plugin Manager'; icon = '🔌'
            elif 'takserver-retention.jar' in cmd:
                name = 'Retention'; icon = '📦'
            else:
                continue  # skip unknown java processes
            # Keep only one entry per service name (highest mem)
            if name not in seen or mem_mb > seen[name]['mem_mb_raw']:
                seen[name] = {
                    'name': name, 'icon': icon, 'pid': pid,
                    'cpu': f"{cpu}%", 'mem_mb': f"{mem_mb} MB",
                    'mem_pct': f"{mem_pct}%", 'status': 'running',
                    'mem_mb_raw': mem_mb
                }
        for svc in seen.values():
            del svc['mem_mb_raw']
            services.append(svc)
        # Check PostgreSQL — remote for two-server, local otherwise
        settings = load_settings()
        tak_cfg = _get_tak_deployment_config(settings)
        if tak_cfg.get('mode') == 'two_server':
            s1 = tak_cfg.get('server_one', {})
            s1_host = (s1.get('host') or '').strip()
            if s1_host:
                import socket
                db_port = int(tak_cfg.get('database', {}).get('port') or 5432)
                try:
                    s = socket.create_connection((s1_host, db_port), timeout=5)
                    s.close()
                    pg_status = 'running'
                except Exception:
                    pg_status = 'stopped'
                services.append({
                    'name': f'PostgreSQL ({s1_host})', 'icon': '🐘', 'pid': '',
                    'cpu': '', 'mem_mb': '', 'mem_pct': '',
                    'status': pg_status
                })
            else:
                # v10.1.64 W1: two_server with no recorded host — ask TAK's own config
                # rather than rendering a hardcoded "stopped" for a database that may be
                # perfectly healthy on another machine.
                _h = _tak_db_host_from_coreconfig()
                _st = 'unknown'
                if _h:
                    import socket as _sk
                    try:
                        _sk.create_connection((_h, 5432), timeout=5).close()
                        _st = 'running'
                    except Exception:
                        _st = 'stopped'
                services.append({
                    'name': f'PostgreSQL ({_h})' if _h else 'PostgreSQL (remote)',
                    'icon': '🐘', 'pid': '',
                    'cpu': '', 'mem_mb': '', 'mem_pct': '',
                    'status': _st
                })
        elif _tak_is_container():
            # v10.0.1: single-server container deploy — PostgreSQL runs in the
            # takserver-db container, not as a host systemd service.
            pg_running = _tak_container_running(TAK_DB_CONTAINER)
            services.append({
                'name': 'PostgreSQL', 'icon': '🐘', 'pid': '',
                'cpu': '', 'mem_mb': '', 'mem_pct': '',
                'status': 'running' if pg_running else 'stopped'
            })
        else:
            # Native host PostgreSQL: Debian/Ubuntu use the unsuffixed `postgresql`
            # meta-service; RHEL/EL (PGDG) use `postgresql-<major>`. EITHER being active
            # means PG is up. Probing only `postgresql` false-reds every Rocky/RHEL
            # native box ("PostgreSQL stopped") even though postgresql-<major> is serving
            # cot fine — same EL/Debian split already handled at the deploy probe.
            # v10.1.64 W1: before trusting a local probe, ask TAK where its database
            # actually is. A box split by hand (CoreConfig pointing elsewhere) is NOT in
            # two_server mode as far as our settings know, and this branch then reported a
            # healthy remote database as "stopped".
            _dbh = _tak_db_host_from_coreconfig()
            if _tak_db_is_remote(_dbh):
                import socket as _sk
                try:
                    _sk.create_connection((_dbh, 5432), timeout=5).close()
                    _pgst = 'running'
                except Exception:
                    _pgst = 'stopped'
                services.append({
                    'name': f'PostgreSQL ({_dbh})', 'icon': '🐘', 'pid': '',
                    'cpu': '', 'mem_mb': '', 'mem_pct': '', 'status': _pgst
                })
            else:
                pg = subprocess.run(_sudo_wrap(['systemctl', 'is-active', 'postgresql'] + list(_PG_SVC_UNITS)), capture_output=True, text=True, timeout=5)
                pg_active = 'active' in (pg.stdout or '').split()
                services.append({
                    'name': 'PostgreSQL', 'icon': '🐘', 'pid': '',
                    'cpu': '', 'mem_mb': '', 'mem_pct': '',
                    'status': 'running' if pg_active else 'stopped'
                })
    except Exception as e:
        services.append({'name': 'Error', 'icon': '❌', 'status': str(e)[:200]})
    return jsonify({'services': services, 'count': len([s for s in services if s['status'] == 'running'])})


@app.route('/api/takserver/remote-metrics')
@login_required
def takserver_remote_metrics():
    """Return CPU/memory/disk/uptime for Server One when in two-server (remote DB) mode."""
    settings = load_settings()
    tak_cfg = _get_tak_deployment_config(settings)
    if tak_cfg.get('mode') != 'two_server':
        return jsonify({'error': 'Not two-server'}), 404
    s1 = tak_cfg.get('server_one', {})
    if not (s1.get('host') or '').strip():
        return jsonify({'error': 'No Server One host'}), 404
    metrics = _get_remote_host_metrics(s1)
    if metrics is None:
        return jsonify({'error': 'Could not fetch remote metrics'}), 503
    return jsonify(metrics)


@app.route('/api/takserver/uninstall', methods=['POST'])
@login_required
def takserver_uninstall():
    """Remove TAK Server, clean up, ready for fresh deploy"""
    data = request.json or {}
    password = data.get('password', '')
    auth = load_auth()
    if not auth.get('password_hash') or not check_password_hash(auth['password_hash'], password):
        return jsonify({'error': 'Invalid admin password'}), 403
    steps = []
    # v10.0.1: container TAK teardown FIRST. The native systemctl/apt steps below
    # are no-ops on a Docker TAK (no unit, no package) and --restart=always would
    # just respawn the containers, so do the real teardown here. Confirmed by the
    # uninstall test: native Remove left containers/volume/network/bundle behind.
    if _tak_is_container():
        for c in (TAK_CONTAINER, TAK_DB_CONTAINER):
            subprocess.run(_sudo_wrap(['docker', 'rm', '-f', c]), capture_output=True, timeout=60)
        subprocess.run(_sudo_wrap(['docker', 'volume', 'rm', TAK_DB_VOLUME]), capture_output=True, timeout=30)
        subprocess.run(_sudo_wrap(['docker', 'network', 'rm', TAK_DOCKER_NET]), capture_output=True, timeout=30)
        subprocess.run(_sudo_wrap(['rm', '-rf', TAK_DOCKER_ROOT]), capture_output=True, timeout=60)  # v10.0.1: broker rm — the host console user can't delete the root-owned in-container cert files
        # Remove the /opt/tak symlink explicitly. After ~/tak-docker is gone it is a
        # DANGLING symlink, which the native `if os.path.exists('/opt/tak')` cleanup
        # below skips (exists() follows the link → False), leaving it behind.
        subprocess.run(_sudo_wrap(['rm', '-f', '/opt/tak']), capture_output=True, timeout=10)
        # Reset the persisted method/credentials so detection falls back to the
        # platform default (arm64 still defaults to container; a redeploy re-sets it).
        try:
            _us = load_settings()
            _us.pop('tak_install_method', None)
            _us.pop('tak_db_password', None)
            save_settings(_us)
        except Exception:
            pass
        steps.append('Container TAK removed (containers, volume, network, ~/tak-docker)')
    # Stop service.
    #
    # A slow shutdown must NOT abort the uninstall. `systemctl stop takserver` on a
    # busy 5.8 box regularly exceeds 90 s (measured on a Rocky 9 box with ~1M rows,
    # 2026-09-03), and subprocess.run raises TimeoutExpired. That exception was
    # unhandled, so the route 500'd and every step below it - package purge,
    # /opt/tak removal, database cleanup - never ran. The operator got "Internal
    # Server Error" and a half-removed server: package still installed, unit in
    # `failed`, /opt/tak still on disk. The next deploy then lands on that mess.
    #
    # Graceful stop is a courtesy here; the SIGKILL below is what actually
    # guarantees the processes are gone. So allow longer, and on timeout say so and
    # carry on to the kill rather than abandoning the uninstall.
    _stopped_cleanly = True
    for _unit_cmd in (['systemctl', 'stop', 'takserver'], ['systemctl', 'disable', 'takserver']):
        try:
            subprocess.run(_sudo_wrap(_unit_cmd), capture_output=True, timeout=300)
        except subprocess.TimeoutExpired:
            _stopped_cleanly = False
        except Exception:
            _stopped_cleanly = False
    steps.append('Stopped TAK Server' if _stopped_cleanly else
                 'TAK Server did not stop within 5 minutes — killed instead (uninstall continued)')
    # Kill any remaining processes.
    #
    # This used to be a bare unwrapped `pkill -9 -f takserver`, which on a born-non-root
    # box runs as `takwerx` and therefore cannot signal anything owned by `tak` — the
    # step reported "Killed remaining processes" while every one of them survived.
    # What survives matters: TAK's own postrm runs `userdel tak`, and userdel exits 8
    # ("user tak is currently used by process N") if ANY tak-owned process is left, so
    # the package purge fails and the package is stranded half-installed. Measured on
    # az-ubuntu-1, 2026-09-19 — survivors were a lingering `systemd --user` manager,
    # four abandoned login session scopes, and orphaned takserver-plugins.sh /
    # takserver-retention.sh wrappers with their JVMs.
    #
    # `pkill` is not on the broker's allow-list (and should not be — it is a
    # signal-anything primitive). `loginctl` is, and terminate-user is the correct
    # systemd answer anyway: it takes down the user's manager and every session scope,
    # which is exactly where those orphans live. disable-linger stops it coming back.
    _run_priv_chain([['loginctl', 'terminate-user', 'tak'],
                     ['loginctl', 'disable-linger', 'tak']], 'seq', timeout=60)
    subprocess.run('pkill -9 -f takserver 2>/dev/null; true', shell=True, capture_output=True)
    time.sleep(3)
    _tak_left = subprocess.run("ps -u tak -o pid= 2>/dev/null | wc -l",
                               shell=True, capture_output=True, text=True).stdout.strip()
    try:
        _tak_left = int(_tak_left)
    except (TypeError, ValueError):
        _tak_left = 0
    if _tak_left:
        # Say so. The purge below is about to fail because of exactly this, and a step
        # list that claims a kill that did not happen sends the operator to the wrong place.
        steps.append('⚠ %d process(es) still owned by the tak user after terminate-user — '
                     'the package purge may fail (userdel refuses while they are running)'
                     % _tak_left)
    else:
        steps.append('Killed remaining processes')
    # Purge package — must complete BEFORE removing /opt/tak, otherwise the
    # package can remain in 'ii' state with files gone, and the next
    # `apt-get install` becomes a no-op ("already newest version") that leaves
    # a half-installed system. See deploy Step 4 self-heal for the matching
    # recovery path.
    if _distro_family() == 'rhel':
        # EL9 native: dnf remove the rpm, then drop the SELinux policy module that
        # the rpm's apply-selinux.sh loaded (else a reinstall warns it's already there).
        # IMPORTANT: clean_requirements_on_remove=False — by default `dnf remove
        # takserver` CASCADES out postgresql15 (and psql) as now-orphaned deps, which
        # runs BEFORE the cot/martiuser drop below → the drop fails (no psql) and a
        # redeploy inherits a stale martiuser with a mismatched password. Keeping
        # postgres (matches the .deb uninstall, which doesn't cascade it) lets the
        # later DROP DATABASE cot / DROP USER martiuser actually run.
        _rpm_installed = subprocess.run('rpm -q takserver 2>/dev/null', shell=True, capture_output=True, text=True).stdout.strip()
        if _rpm_installed.startswith('takserver'):
            subprocess.run(_sudo_wrap(['dnf', 'remove', '-y', '--setopt=clean_requirements_on_remove=False', 'takserver']), stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True, timeout=180)
            _after = subprocess.run('rpm -q takserver 2>/dev/null', shell=True, capture_output=True, text=True).stdout.strip()
            if not _after.startswith('takserver') or 'not installed' in _after.lower():
                steps.append('Removed TAK Server rpm (dnf)')
            else:
                subprocess.run('rpm -e --noscripts --nodeps takserver 2>&1', shell=True, capture_output=True, text=True, timeout=120)
                steps.append('Force-removed TAK Server rpm')
        # remove the takserver SELinux module (named takserver-policy on EL9)
        _run_priv_chain([['semodule', '-r', 'takserver-policy'], ['semodule', '-r', 'takserver']], 'seq', timeout=60)
    else:
        pkg_status = subprocess.run(
            "dpkg-query -W -f='${Status}' takserver 2>/dev/null",
            shell=True, capture_output=True, text=True
        ).stdout.strip()
        if pkg_status:
            # Try purge, escalating. These MUST go through _sudo_wrap: the console
            # runs as `takwerx` on a born-non-root box, so the original unwrapped
            # `apt-get purge` / `dpkg --purge` shell strings failed with permission
            # denied every single time and Remove ended on "still registered with
            # dpkg — manual cleanup required". Reproduced twice on az-ubuntu-1,
            # 2026-09-19; the leftover half-installed package then has to be cleared
            # by hand before the box can be redeployed.
            #
            # Shape matters too: the broker runs argv, not a shell, and both `env`
            # and every shell are on its deny list — so DEBIAN_FRONTEND goes in the
            # process environment, never as an `env`/inline prefix. The first step
            # uses the apt<->dnf shim rather than a bare apt-get, per CLAUDE.md.
            def _pkg_gone():
                st = subprocess.run(
                    "dpkg-query -W -f='${Status}' takserver 2>/dev/null",
                    shell=True, capture_output=True, text=True).stdout.strip()
                return (not st) or ('not-installed' in st)

            _pkg_remove('takserver', purge=True, timeout=180)
            purge_ok = _pkg_gone()
            if not purge_ok:
                for argv in (['dpkg', '--purge', 'takserver'],
                             ['dpkg', '--purge', '--force-all', 'takserver']):
                    _run_priv_chain([argv], 'seq', timeout=180,
                                    env=dict(os.environ, DEBIAN_FRONTEND='noninteractive'))
                    if _pkg_gone():
                        purge_ok = True
                        break
            if purge_ok:
                steps.append('Purged TAK Server package')
            else:
                steps.append('⚠ Could not purge takserver package (still registered with dpkg) — manual cleanup required')
    # Clean up /opt/tak
    if os.path.exists('/opt/tak'):
        subprocess.run(_sudo_wrap(['rm', '-rf', '/opt/tak']), capture_output=True)
        steps.append('Removed /opt/tak')
    # Clean up PostgreSQL — local or external depending on deployment mode
    settings = load_settings()
    tak_cfg = _get_tak_deployment_config(settings)
    if tak_cfg.get('mode') == 'external_db':
        # External / managed DB: use stored martiuser credentials to drop the cot database.
        # martiuser was granted azure_pg_admin (Azure) or rds_superuser (AWS) during provisioning
        # so it has permission to drop databases it doesn't own.
        edb = tak_cfg.get('external_db', {})
        edb_host = (edb.get('host') or '').strip()
        edb_port = int(edb.get('port') or 5432)
        edb_name = (edb.get('name') or 'cot').strip()
        edb_user = (edb.get('user') or 'martiuser').strip()
        edb_pass = (edb.get('password') or '').strip()
        if edb_host and edb_pass:
            env = dict(os.environ, PGPASSWORD=edb_pass)
            # Terminate active connections then drop the database
            terminate_sql = f"SELECT pg_terminate_backend(pid) FROM pg_stat_activity WHERE datname='{edb_name}' AND pid <> pg_backend_pid();"
            drop_sql = f"DROP DATABASE IF EXISTS {edb_name};"
            for sql, label in [(terminate_sql, 'terminate connections'), (drop_sql, f'drop database {edb_name}')]:
                r = subprocess.run(
                    ['psql', '-h', edb_host, '-p', str(edb_port), '-U', edb_user,
                     '-d', 'postgres', '--no-password', '-c', sql],
                    capture_output=True, text=True, timeout=30, env=env
                )
                if r.returncode == 0:
                    steps.append(f'External DB: {label} — OK')
                else:
                    steps.append(f'External DB: {label} — {(r.stderr or r.stdout or "failed")[:120]}')
        else:
            steps.append('External DB cleanup skipped — no credentials stored (run Provision Database on next deploy)')
        # The .deb installer always creates a local martiuser + cot DB regardless of deployment
        # mode. Clean them up so re-deploys don't hit stale-password noise in the postinstall.
        subprocess.run("runuser -u postgres -- psql -c \"DROP DATABASE IF EXISTS cot WITH (FORCE);\" 2>/dev/null || runuser -u postgres -- psql -c \"DROP DATABASE IF EXISTS cot;\" 2>/dev/null; true", shell=True, capture_output=True, timeout=30)
        subprocess.run("runuser -u postgres -- psql -c \"DROP USER IF EXISTS martiuser;\" 2>/dev/null; true", shell=True, capture_output=True, timeout=30)
        steps.append('Cleaned up local PostgreSQL side-effect (cot database, martiuser)')
    else:
        # Local PostgreSQL (single-server or two-server mode)
        subprocess.run("runuser -u postgres -- psql -c \"DROP DATABASE IF EXISTS cot WITH (FORCE);\" 2>/dev/null || runuser -u postgres -- psql -c \"DROP DATABASE IF EXISTS cot;\" 2>/dev/null; true", shell=True, capture_output=True, timeout=30)
        subprocess.run("runuser -u postgres -- psql -c \"DROP USER IF EXISTS martiuser;\" 2>/dev/null; true", shell=True, capture_output=True, timeout=30)
        steps.append('Cleaned up local PostgreSQL (cot database, martiuser)')
    # Clean up GPG verification artifacts
    subprocess.run('rm -rf /usr/share/debsig/keyrings/* /etc/debsig/policies/* 2>/dev/null; true', shell=True, capture_output=True, timeout=10)
    steps.append('Cleaned up GPG verification artifacts')
    # Clean up uploads so user can upload fresh
    for f in os.listdir(UPLOAD_DIR):
        os.remove(os.path.join(UPLOAD_DIR, f))
    steps.append('Cleared uploads')
    # Reset deploy status
    deploy_log.clear()
    deploy_status.update({'running': False, 'complete': False, 'error': False})
    # Clear saved deployment config so the form is blank on next visit
    try:
        _settings = load_settings()
        td = _settings.get('tak_deployment', {})
        td['mode'] = 'single_server'
        edb = td.get('external_db', {})
        edb['host'] = ''
        edb['password'] = ''
        td['external_db'] = edb
        _settings['tak_deployment'] = td
        save_settings(_settings)
        steps.append('Cleared saved deployment config')
    except Exception as _ce:
        steps.append(f'Could not clear deployment config (non-fatal): {_ce}')
    # v0.9.31: regenerate Caddyfile so the webtak.<fqdn> vhost is removed.
    # Same gap as takportal/authentik uninstall — without this the vhost
    # remained and Caddy fell through to Authentik's "Not Found" page.
    try:
        settings = load_settings()
        generate_caddyfile(settings)
        _caddy_reload()
        steps.append('Regenerated Caddyfile + reloaded Caddy')
    except Exception as caddy_err:
        steps.append(f'Caddy regen warning (non-fatal): {caddy_err}')
    return jsonify({'success': True, 'steps': steps})

@app.route('/api/upload/takserver', methods=['POST'])
@login_required
def upload_takserver_package():
    if 'files' not in request.files:
        return jsonify({'error': 'No files uploaded'}), 400
    files = request.files.getlist('files')
    if not files or all(f.filename == '' for f in files):
        return jsonify({'error': 'No files selected'}), 400
    os_type = load_settings().get('os_type', '')
    results = {'packages': [], 'gpg_key': None, 'policy': None}
    for f in files:
        raw_name = f.filename or ''
        fn = secure_filename(raw_name)
        if not fn:
            return jsonify({'error': f'Invalid filename: {raw_name[:64]}'}), 400
        # Normalize the EXTENSION to lower case before anything looks at it.
        #
        # Every classifier here, and ~25 `endswith('.deb')` sites downstream in the
        # deploy/update routes, are case-sensitive. A file that arrives as
        # TAKSERVER-DOCKER-HARDENED-5.8-RELEASE-75.ZIP therefore matched none of them:
        # it uploaded, sat in the uploads directory, and was invisible to every path
        # that goes looking for a bundle — "infra-TAK seems to not find it, because it
        # is named differently" (GH #66, 2026-09-08). tak.gov hands out mixed-case
        # names, and an operator renaming a file should not be a prerequisite.
        #
        # Doing it once, here, fixes the classifiers below AND every downstream reader,
        # because what lands on disk now ends in a lower-case extension. The base name
        # is left alone: it is what the version parser reads, and that regex is already
        # case-insensitive.
        _stem, _ext = os.path.splitext(fn)
        if _ext and _ext != _ext.lower():
            fn = _stem + _ext.lower()
        fp = os.path.join(UPLOAD_DIR, fn)
        f.save(fp)
        sz = round(os.path.getsize(fp) / (1024*1024), 1)
        # v10.0.1 platform gate: the accepted package type is fixed by arch+distro,
        # mirroring the existing .deb/.rpm cross-rejection. arm64 → docker .zip only
        # (no native arm TAK package exists); amd64 RHEL → .rpm only; amd64 Debian/
        # Ubuntu → .deb only. Reject anything else up-front so a box can't be deployed
        # with the wrong package by accident.
        _arch = _host_arch()
        _native_ext = '.rpm' if _distro_family() == 'rhel' else '.deb'
        # A `takserver-database` package is the ONE artifact that legitimately belongs to
        # the other family: in a two-server deployment it is installed on Server One,
        # over SSH, and _setup_server_one() explicitly probes that host's OS and
        # dispatches to the RHEL path when it differs from the console's ("the DB box
        # (Server One) can be a DIFFERENT OS family than the console"). The deploy also
        # already accepts either extension from uploads. Only this gate disagreed, so an
        # Ubuntu core could never stage the .rpm its own Rocky Server One needs, and the
        # mixed-family split-box the code supports was unreachable through the UI.
        # arm64 stays container-only either way — that is not about families.
        _is_db_pkg = 'database' in fn.lower()
        if fn.endswith('.deb'):
            if _arch == 'arm64':
                os.remove(fp)
                return jsonify({'error': f'.deb uploaded but this arm64 box deploys TAK Server via the container path — upload the takserver-docker .zip.'}), 400
            if _distro_family() == 'rhel' and not _is_db_pkg:
                os.remove(fp)
                return jsonify({'error': f'.deb uploaded but system is {os_type} (RHEL family). Need a takserver .rpm.'}), 400
            results['packages'].append({'filename': fn, 'filepath': fp, 'pkg_type': 'deb', 'size_mb': sz})
        elif fn.endswith('.rpm'):
            if _arch == 'arm64':
                os.remove(fp)
                return jsonify({'error': f'.rpm uploaded but this arm64 box deploys TAK Server via the container path — upload the takserver-docker .zip.'}), 400
            if _distro_family() != 'rhel' and not _is_db_pkg:
                os.remove(fp)
                return jsonify({'error': f'.rpm uploaded but system is {os_type}. Need a takserver .deb.'}), 400
            results['packages'].append({'filename': fn, 'filepath': fp, 'pkg_type': 'rpm', 'size_mb': sz})
        elif fn.endswith('.zip') and 'docker' in fn.lower():
            # official takserver-docker-*.zip - the CONTAINER path.
            #
            # v10.2.0: amd64 may now upload this. The container path was always
            # described as "arm64, or operator-selected on amd64" (see the block
            # comment by TAK_CONTAINER) and the deploy route has always honoured an
            # explicit install_method='container' on any arch - but this validation
            # rejected the only artifact that path needs, so on amd64 it was
            # unreachable through the UI. The two now agree.
            #
            # arm64 remains container-ONLY, enforced above: .deb and .rpm are still
            # rejected there. This widens amd64; it does not loosen arm64.
            results['packages'].append({'filename': fn, 'filepath': fp, 'pkg_type': 'docker', 'size_mb': sz})
        elif fn.endswith('.key') or 'gpg' in fn.lower():
            results['gpg_key'] = {'filename': fn, 'filepath': fp, 'size_mb': sz}
        elif fn.endswith('.pol') or 'policy' in fn.lower():
            results['policy'] = {'filename': fn, 'filepath': fp, 'size_mb': sz}
    return jsonify({'success': True, **results,
        'has_verification': results['gpg_key'] is not None and results['policy'] is not None})

@app.route('/api/upload/takserver/delete', methods=['POST'])
@login_required
def delete_uploaded_file():
    fn = request.json.get('filename', '')
    import re
    if not fn or not re.match(r'^[a-zA-Z0-9._-]+$', fn):
        return jsonify({'error': 'Invalid filename'}), 400
    fp = os.path.join(UPLOAD_DIR, fn)
    if os.path.exists(fp):
        os.remove(fp)
        return jsonify({'success': True, 'filename': fn})
    return jsonify({'error': 'File not found'}), 404

@app.route('/api/upload/takserver/existing')
@login_required
def check_existing_uploads():
    """Check for files already uploaded from a previous session. Returns all .deb/.rpm as packages list (database + core both shown)."""
    files = {'packages': []}
    for fn in sorted(os.listdir(UPLOAD_DIR)):
        fp = os.path.join(UPLOAD_DIR, fn)
        if not os.path.isfile(fp):
            continue
        sz = os.path.getsize(fp)
        sz_mb = round(sz / (1024*1024), 1)
        if fn.endswith('.deb') or fn.endswith('.rpm') or (fn.endswith('.zip') and 'docker' in fn.lower()):
            files['packages'].append({'filename': fn, 'filepath': fp, 'size_mb': sz_mb})
        elif fn.endswith('.key') or 'gpg' in fn.lower():
            files['gpg_key'] = {'filename': fn, 'filepath': fp, 'size_mb': sz_mb}
        elif fn.endswith('.pol') or 'policy' in fn.lower():
            files['policy'] = {'filename': fn, 'filepath': fp, 'size_mb': sz_mb}
    return jsonify(files)


@app.route('/api/upload/fedhub', methods=['POST'])
@login_required
def upload_fedhub_package():
    if 'files' not in request.files:
        return jsonify({'error': 'No files uploaded'}), 400
    files = request.files.getlist('files')
    if not files or all((f.filename or '') == '' for f in files):
        return jsonify({'error': 'No files selected'}), 400
    results = []
    for f in files:
        raw_name = f.filename or ''
        fn = secure_filename(raw_name)
        if not fn:
            return jsonify({'error': f'Invalid filename: {raw_name[:64]}'}), 400
        # Same lower-casing as the TAK Server upload: a `.DEB` from tak.gov would
        # otherwise be rejected outright as "must be a .deb file" (GH #66).
        _stem, _ext = os.path.splitext(fn)
        if _ext and _ext != _ext.lower():
            fn = _stem + _ext.lower()
        if not fn.endswith('.deb'):
            return jsonify({'error': 'Federation Hub upload must be a .deb file'}), 400
        fp = os.path.join(UPLOAD_DIR, fn)
        f.save(fp)
        ok_m, err = _validate_fedhub_deb_path(fp)
        if not ok_m:
            try:
                os.remove(fp)
            except OSError:
                pass
            return jsonify({'error': err}), 400
        sz = round(os.path.getsize(fp) / (1024 * 1024), 1)
        results.append({'filename': fn, 'size_mb': sz})
    return jsonify({'success': True, 'packages': results})


@app.route('/api/upload/fedhub/delete', methods=['POST'])
@login_required
def delete_fedhub_upload():
    fn = (request.json or {}).get('filename', '')
    if not fn or not re.match(r'^[a-zA-Z0-9._-]+$', fn):
        return jsonify({'error': 'Invalid filename'}), 400
    fp = os.path.join(UPLOAD_DIR, fn)
    if os.path.isfile(fp):
        ok_m, _ = _validate_fedhub_deb_path(fp)
        if not ok_m:
            return jsonify({'error': 'File is not a recognized Federation Hub package'}), 400
        os.remove(fp)
        return jsonify({'success': True, 'filename': fn})
    return jsonify({'error': 'File not found'}), 404


@app.route('/api/upload/fedhub/package')
@login_required
def fedhub_uploaded_package_info():
    fn, fp = _find_fedhub_deb_in_uploads()
    if not fp:
        return jsonify({'filename': None})
    return jsonify({'filename': fn, 'size_mb': round(os.path.getsize(fp) / (1024 * 1024), 1)})

# === TAK Server Deployment ===

deploy_log = []
deploy_status = {'running': False, 'complete': False, 'error': False, 'cancelled': False}

upgrade_log = []
upgrade_status = {'running': False, 'complete': False, 'error': False}

tak_migrate_log = []
tak_migrate_status = {'running': False, 'complete': False, 'error': False}

# ── v10.2.2 W9: every TAK Server update leaves a record Diagnostics can read ──────
# A failed update used to leave its log only in this process's memory: visible in the
# one browser tab that started it, gone at the next console restart, and nowhere in a
# Diagnostics report. (Field 2026-10-01: a customer's 5.8 upgrade failed; all we had was
# a screenshot of three lines.) Each update worker now ends by saving its result and the
# tail of its log to .config/ — console-owned, mode 600 — and Help → Diagnostics lists the
# recent runs and the log of the latest one that did not succeed, through the same
# redaction as the rest of the report.
TAK_UPDATE_HISTORY = os.path.join(CONFIG_DIR, 'takserver_update_history.json')
_TAK_UPDATE_HISTORY_KEEP = 5
_TAK_UPDATE_HISTORY_LINES = 400
_TAK_UPDATE_HISTORY_LOCK = threading.Lock()


def _tak_update_history():
    """Recorded TAK Server update runs, newest first ([] when none or unreadable)."""
    try:
        with open(TAK_UPDATE_HISTORY) as f:
            h = json.load(f)
        return h if isinstance(h, list) else []
    except (OSError, ValueError):
        return []


def _tak_update_record(kind, pkg, log, status, started, exc=None, running=False, run_id=None):
    lines = [str(l) for l in list(log)]
    if running:
        result = 'running'
    elif exc is not None:
        result = 'CRASHED (%s: %s)' % (type(exc).__name__, str(exc)[:160])
    elif any('MID-UPGRADE' in l for l in lines):
        result = 'FAILED (left mid-upgrade)'
    elif status.get('error'):
        result = 'FAILED'
    elif status.get('complete'):
        result = 'ok'
    else:
        result = 'unfinished'
    entry = {'id': run_id or '%s@%.3f' % (kind, started),
             'started': time.strftime('%Y-%m-%d %H:%M:%S UTC', time.gmtime(started)),
             'finished': time.strftime('%Y-%m-%d %H:%M:%S UTC', time.gmtime()),
             'seconds': int(time.time() - started), 'kind': kind,
             'package': os.path.basename(pkg or ''), 'result': result,
             'total_lines': len(lines), 'lines': lines[-_TAK_UPDATE_HISTORY_LINES:]}
    with _TAK_UPDATE_HISTORY_LOCK:
        # One entry per run: the in-flight checkpoints and the final record share an id.
        hist = [entry] + [h for h in _tak_update_history() if h.get('id') != entry['id']]
        tmp = TAK_UPDATE_HISTORY + '.tmp'
        fd = os.open(tmp, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600)
        with os.fdopen(fd, 'w') as f:
            json.dump(hist[:_TAK_UPDATE_HISTORY_KEEP], f)
        os.replace(tmp, TAK_UPDATE_HISTORY)


def _tak_update_job(kind, target, log, status):
    """Thread target for a TAK Server update worker: run it, then record how it ended —
    success, failure, or an exception (recorded, then re-raised)."""
    def run(*a, **kw):
        started, exc = time.time(), None
        # ops #25: kind@ms alone collides when two runs start in the same millisecond, and
        # the later one then replaces the earlier one's record. A random suffix keeps every
        # run distinct; entries already on disk keep their old ids and are left alone.
        run_id = '%s@%.3f#%s' % (kind, started, secrets.token_hex(4))
        pkg = a[0] if a and isinstance(a[0], str) else ''
        _mod_result_start('takserver', 'update', '', kind)     # v10.2.8 W10 — the card + Diagnostics
        # v10.2.11 (ops #9): the record used to be written only when the worker ENDED, so a
        # run cut off by a console restart, a reboot or an OOM kill left no log anywhere —
        # the one run that changed the box was the one Diagnostics could not show (lutak2.net:
        # TAK 5.8 installed, cot gone, update history only listing two runs that changed
        # nothing). Checkpoint the log while it runs; a 'running' entry whose worker is gone
        # is reported as interrupted, with the log up to the point it stopped.
        stop, ck_lock = threading.Event(), threading.Lock()

        def checkpoint():
            seen = -1
            while True:
                with ck_lock:
                    if stop.is_set():
                        return
                    if len(log) != seen:
                        seen = len(log)
                        try:
                            _tak_update_record(kind, pkg, log, status, started, running=True,
                                               run_id=run_id)
                        except Exception:
                            pass
                stop.wait(15)
        threading.Thread(target=checkpoint, daemon=True).start()
        try:
            target(*a, **kw)
        except BaseException as e:
            exc = e
            raise
        finally:
            with ck_lock:
                stop.set()
            try:
                _tak_update_record(kind, pkg, log, status, started, exc, run_id=run_id)
            except Exception as _re:
                print(f'TAK Server update: record not saved ({_re})', flush=True)
            _tracked_finish('takserver', status, log,
                            exc=exc if isinstance(exc, Exception) else None)
    return run

plugin_install_log = []
plugin_install_status = {'running': False, 'complete': False, 'error': False}

TAK_LIB_DIR = '/opt/tak/lib'
TAK_PLUGINS_CONF_DIR = '/opt/tak/conf/plugins'


@app.route('/api/takserver/plugins/list')
@login_required
def takserver_plugins_list():
    """List installed plugins: union of JARs in /opt/tak/lib/ and YAMLs in /opt/tak/conf/plugins/."""
    plugins = {}
    if os.path.isdir(TAK_LIB_DIR):
        r = subprocess.run(_sudo_wrap(['ls', TAK_LIB_DIR]), capture_output=True, text=True, timeout=5)
        for fn in (r.stdout.splitlines() if r.returncode == 0 else []):
            if fn.endswith('.jar'):
                stem = fn[:-4]
                plugins[stem] = {'jar': fn, 'classname': None, 'has_config': False}
    if os.path.isdir(TAK_PLUGINS_CONF_DIR):
        r2 = subprocess.run(_sudo_wrap(['ls', TAK_PLUGINS_CONF_DIR]), capture_output=True, text=True, timeout=5)
        for fn in (r2.stdout.splitlines() if r2.returncode == 0 else []):
            if fn.endswith('.yaml'):
                classname = fn[:-5]
                matched = False
                for stem, entry in plugins.items():
                    if stem.lower().replace('-', '').replace('_', '') in classname.lower().replace('.', '').replace('-', '').replace('_', ''):
                        entry['classname'] = classname
                        entry['has_config'] = True
                        matched = True
                        break
                if not matched:
                    plugins[classname] = {'jar': None, 'classname': classname, 'has_config': True}
    result = sorted(plugins.values(), key=lambda x: (x['jar'] is None, x.get('jar') or x.get('classname', '')))
    return jsonify({'plugins': result})


@app.route('/api/upload/takserver-plugin', methods=['POST'])
@login_required
def upload_takserver_plugin():
    """Accept .jar or .yaml plugin file, save to UPLOAD_DIR."""
    if 'file' not in request.files:
        return jsonify({'error': 'No file uploaded'}), 400
    f = request.files['file']
    raw_name = f.filename or ''
    fn = secure_filename(raw_name)
    if not fn:
        return jsonify({'error': 'Invalid filename'}), 400
    if not fn.endswith('.jar') and not fn.endswith('.yaml'):
        return jsonify({'error': 'Only .jar and .yaml files are accepted'}), 400
    fp = os.path.join(UPLOAD_DIR, fn)
    f.save(fp)
    sz = round(os.path.getsize(fp) / (1024 * 1024), 2)
    return jsonify({'success': True, 'filename': fn, 'size_mb': sz, 'type': 'jar' if fn.endswith('.jar') else 'yaml'})


@app.route('/api/takserver/plugins/install-jar', methods=['POST'])
@login_required
def takserver_plugin_install_jar():
    """Copy an uploaded .jar to /opt/tak/lib/."""
    import re as _re
    data = request.get_json() or {}
    fn = data.get('filename', '')
    if not fn or not fn.endswith('.jar'):
        return jsonify({'error': 'No .jar filename provided'}), 400
    if not _re.match(r'^[a-zA-Z0-9._-]+\.jar$', fn):
        return jsonify({'error': 'Invalid filename'}), 400
    src = os.path.join(UPLOAD_DIR, fn)
    if not os.path.exists(src):
        return jsonify({'error': f'File not found in uploads: {fn}'}), 404
    dest = os.path.join(TAK_LIB_DIR, fn)
    plugin_install_log.clear()
    plugin_install_status.update({'running': True, 'complete': False, 'error': False})
    def _do_install(src=src, dest=dest, fn=fn):
        try:
            plugin_install_log.append(f'Copying {fn} to {TAK_LIB_DIR}...')
            r = subprocess.run(_sudo_wrap(['mkdir', '-p', TAK_LIB_DIR]), capture_output=True, text=True, timeout=10)
            r2 = subprocess.run(_sudo_wrap(['cp', src, dest]), capture_output=True, text=True, timeout=30)
            if r2.returncode != 0:
                plugin_install_log.append(f'Error: {r2.stderr.strip() or "copy failed"}')
                plugin_install_status.update({'running': False, 'error': True})
                return
            subprocess.run(_sudo_wrap(['chmod', '644', dest]), capture_output=True, text=True, timeout=10)
            plugin_install_log.append(f'\u2713 {fn} installed to {TAK_LIB_DIR}')
            plugin_install_log.append('Restart TAK Server to load the plugin.')
            plugin_install_status.update({'running': False, 'complete': True})
        except Exception as e:
            plugin_install_log.append(f'Error: {str(e)[:200]}')
            plugin_install_status.update({'running': False, 'error': True})
    threading.Thread(target=_do_install, daemon=True).start()
    return jsonify({'success': True})


@app.route('/api/takserver/plugins/install-yaml', methods=['POST'])
@login_required
def takserver_plugin_install_yaml():
    """Copy an uploaded plugin .yaml config to /opt/tak/conf/plugins/. Validates tak.server.plugins.* naming."""
    import re as _re
    data = request.get_json() or {}
    fn = data.get('filename', '')
    if not fn or not fn.endswith('.yaml'):
        return jsonify({'error': 'No .yaml filename provided'}), 400
    if not _re.match(r'^tak\.server\.plugins\.[a-zA-Z0-9._-]+\.yaml$', fn):
        return jsonify({'error': 'Plugin config filename must be named tak.server.plugins.<ClassName>.yaml'}), 400
    src = os.path.join(UPLOAD_DIR, fn)
    if not os.path.exists(src):
        return jsonify({'error': f'File not found in uploads: {fn}'}), 404
    dest = os.path.join(TAK_PLUGINS_CONF_DIR, fn)
    try:
        subprocess.run(_sudo_wrap(['mkdir', '-p', TAK_PLUGINS_CONF_DIR]), capture_output=True, text=True, timeout=10)
        r = subprocess.run(_sudo_wrap(['cp', src, dest]), capture_output=True, text=True, timeout=30)
        if r.returncode != 0:
            return jsonify({'error': r.stderr.strip() or 'Copy failed'}), 500
        subprocess.run(_sudo_wrap(['chmod', '644', dest]), capture_output=True, text=True, timeout=10)
        return jsonify({'success': True, 'filename': fn})
    except Exception as e:
        return jsonify({'error': str(e)[:200]}), 500


@app.route('/api/takserver/plugins/config/<classname>')
@login_required
def takserver_plugin_config_get(classname):
    """Read a plugin YAML config from /opt/tak/conf/plugins/."""
    import re as _re
    if not _re.match(r'^[a-zA-Z0-9._-]+$', classname):
        return jsonify({'error': 'Invalid classname'}), 400
    fn = classname if classname.endswith('.yaml') else classname + '.yaml'
    path = os.path.join(TAK_PLUGINS_CONF_DIR, fn)
